# ============================================================
# TEACHER LOGIN REQUIRED
# ============================================================

def teacher_login_required(view):

    @wraps(view)
    def wrapped_view(*args, **kwargs):

        # ====================================================
        # GET TEACHER ID FROM SESSION
        # ====================================================

        teacher_id = session.get(
            "teacher_id"
        )

        # ====================================================
        # NO TEACHER SESSION
        # ====================================================

        if not teacher_id:

            flash(
                "Please login as a teacher first.",
                "warning"
            )

            return redirect(
                url_for("main.teacher_login")
            )

        # ====================================================
        # FIND TEACHER
        # ====================================================

        teacher = db.session.get(
            Teacher,
            teacher_id
        )

        # ====================================================
        # TEACHER NOT FOUND
        # ====================================================

        if not teacher:

            session.pop(
                "teacher_id",
                None
            )

            session.pop(
                "teacher_role",
                None
            )

            session.pop(
                "teacher_institution_id",
                None
            )

            session.pop(
                "teacher_branch_id",
                None
            )

            flash(
                "Teacher account was not found.",
                "danger"
            )

            return redirect(
                url_for("main.teacher_login")
            )

        # ====================================================
        # ACCOUNT ACTIVE
        # ====================================================

        if not teacher.is_active:

            session.pop(
                "teacher_id",
                None
            )

            session.pop(
                "teacher_role",
                None
            )

            session.pop(
                "teacher_institution_id",
                None
            )

            session.pop(
                "teacher_branch_id",
                None
            )

            flash(
                "Your teacher account is inactive.",
                "danger"
            )

            return redirect(
                url_for("main.teacher_login")
            )

        # ====================================================
        # STATUS
        # ====================================================

        if teacher.status != "active":

            session.pop(
                "teacher_id",
                None
            )

            session.pop(
                "teacher_role",
                None
            )

            session.pop(
                "teacher_institution_id",
                None
            )

            session.pop(
                "teacher_branch_id",
                None
            )

            flash(
                "Your teacher account is no longer active.",
                "danger"
            )

            return redirect(
                url_for("main.teacher_login")
            )

        # ====================================================
        # ROLE
        # ====================================================

        if teacher.role != "teacher":

            session.pop(
                "teacher_id",
                None
            )

            session.pop(
                "teacher_role",
                None
            )

            session.pop(
                "teacher_institution_id",
                None
            )

            session.pop(
                "teacher_branch_id",
                None
            )

            flash(
                "Invalid teacher account.",
                "danger"
            )

            return redirect(
                url_for("main.teacher_login")
            )

        # ====================================================
        # UPDATE LAST ACTIVE
        # ====================================================

        teacher.last_active = datetime.utcnow()

        try:

            db.session.commit()

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Teacher last active update failed"
            )

        # ====================================================
        # MAKE TEACHER AVAILABLE
        # ====================================================

        g.teacher = teacher

        # ====================================================
        # CONTINUE ROUTE
        # ====================================================

        return view(
            *args,
            **kwargs
        )

    return wrapped_view

