@bp.route(
    "/teacher/login",
    methods=["GET", "POST"]
)
def teacher_login():

    # ========================================================
    # ALREADY LOGGED IN AS TEACHER
    # ========================================================

    if session.get("teacher_id"):

        flash(
            "You are already logged in.",
            "info"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # GET
    # ========================================================

    if request.method == "GET":

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # FORM DATA
    # ========================================================

    username_or_email = request.form.get(
        "username",
        ""
    ).strip()

    password = request.form.get(
        "password",
        ""
    )

    # ========================================================
    # VALIDATION
    # ========================================================

    if not username_or_email:

        flash(
            "Username or email is required.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    if not password:

        flash(
            "Password is required.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # FIND TEACHER
    # ========================================================

    teacher = Teacher.query.filter(
        db.or_(
            Teacher.username == username_or_email,
            Teacher.email == username_or_email.lower()
        )
    ).first()

    # ========================================================
    # TEACHER NOT FOUND
    # ========================================================

    if not teacher:

        flash(
            "Invalid username/email or password.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK PASSWORD
    # ========================================================

    if not teacher.check_password(password):

        flash(
            "Invalid username/email or password.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK ACCOUNT ACTIVE
    # ========================================================

    if not teacher.is_active:

        flash(
            "Your teacher account is inactive. "
            "Please contact the administrator.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK TEACHER STATUS
    # ========================================================

    if teacher.status != "active":

        if teacher.status == "suspended":

            message = (
                "Your teacher account has been suspended. "
                "Please contact the administrator."
            )

        elif teacher.status == "resigned":

            message = (
                "This teacher account is no longer active."
            )

        else:

            message = (
                "Your teacher account is inactive. "
                "Please contact the administrator."
            )

        flash(
            message,
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK ROLE
    # ========================================================

    if teacher.role != "teacher":

        flash(
            "This account is not registered as a teacher account.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CREATE TEACHER SESSION
    #
    # IMPORTANT:
    # No database auth_status/session_token check here.
    #
    # The same teacher can login from:
    # - another browser
    # - another computer
    # - another device
    #
    # ========================================================

    session["teacher_id"] = teacher.id

    session["teacher_role"] = "teacher"

    session["teacher_institution_id"] = (
        teacher.institution_id
    )

    session["teacher_branch_id"] = (
        teacher.branch_id
    )

    # ========================================================
    # UPDATE LOGIN INFORMATION
    # ========================================================

    now = datetime.utcnow()

    teacher.login_time = now

    teacher.last_login = now

    teacher.last_active = now

    # ========================================================
    # SAVE LOGIN INFORMATION
    # ========================================================

    try:

        db.session.commit()

    except Exception:

        db.session.rollback()

        # Remove only teacher session values
        session.pop(
            "teacher_id",
            None
        )

        session.pop(
            "teacher_role",
            None
        )

        session.pop(
            "teacher_institution_id",
            None
        )

        session.pop(
            "teacher_branch_id",
            None
        )

        current_app.logger.exception(
            "Teacher login update error"
        )

        flash(
            "Unable to complete teacher login. "
            "Please try again.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # SUCCESS MESSAGE
    # ========================================================

    flash(
        f"Welcome back, {teacher.full_name}!",
        "success"
    )

    # ========================================================
    # REDIRECT TEACHER DASHBOARD
    # ========================================================

    return redirect(
        url_for("main.teacher_dashboard")
    )


# ============================================================
# TEACHER DASHBOARD
# ============================================================

@bp.route(
    "/teacher/dashboard",
    methods=["GET"]
)
@teacher_login_required
def teacher_dashboard():

    # ========================================================
    # CURRENT TEACHER
    # ========================================================

    teacher = getattr(g, "teacher", None)

    if not teacher:
        abort(403)

    # ========================================================
    # BASIC TEACHER IDS
    # ========================================================

    teacher_id = teacher.id

    institution_id = teacher.institution_id

    branch_id = teacher.branch_id

    # ========================================================
    # INSTITUTION
    # ========================================================
    # Teacher -> Institution
    #
    # Waxaan si gaar ah u query-gareyneynaa si dashboard-ku
    # u helo institution-ka saxda ah.

    institution = None

    if institution_id:

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )

    # ========================================================
    # BRANCH
    # ========================================================
    # Branch waa inuu ka tirsan yahay institution-ka teacher-ka.

    branch = None

    if branch_id and institution_id:

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id,
                Branch.institution_id == institution_id
            )
            .first()
        )

    # ========================================================
    # TEACHER SUBJECT ASSIGNMENTS
    # ========================================================
    # TeacherSubject:
    #
    # Teacher
    # Subject
    # Program
    # Class
    # Section
    # Academic Year
    #
    # Waxaan ku xireynaa institution + branch si aysan
    # teacher-ku u arkin assignment branch kale.

    teacher_subjects = (
        TeacherSubject.query
        .filter(
            TeacherSubject.teacher_id == teacher_id,
            TeacherSubject.institution_id == institution_id,
            TeacherSubject.branch_id == branch_id
        )
        .order_by(
            TeacherSubject.id.desc()
        )
        .all()
    )

    # ========================================================
    # SUBJECT COUNT
    # ========================================================

    subjects_count = len(
        teacher_subjects
    )

    # ========================================================
    # EXAM SUBJECT ASSIGNMENTS
    # ========================================================
    # ExamSubject institution/branch columns ma laha.
    #
    # Sidaas darteed Exam ayaan JOIN gareyneynaa:
    #
    # ExamSubject -> Exam
    #
    # kadib waxaan ka filter-gareyneynaa institution iyo branch.

    exam_subjects = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.teacher_id == teacher_id,
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )
        .order_by(
            ExamSubject.id.desc()
        )
        .all()
    )

    # ========================================================
    # EXAM SUBJECT COUNT
    # ========================================================

    exam_subjects_count = len(
        exam_subjects
    )

    # ========================================================
    # LAST ACTIVE
    # ========================================================

    last_active = teacher.last_active

    # ========================================================
    # RENDER DASHBOARD
    # ========================================================

    return render_template(
        "backend/teacher/home/dashboard.html",


        # ----------------------------------------------------
        # TEACHER
        # ----------------------------------------------------

        teacher=teacher,
        teacher_id=teacher_id,

        # ----------------------------------------------------
        # INSTITUTION
        # ----------------------------------------------------

        institution=institution,
        institution_id=institution_id,

        # ----------------------------------------------------
        # BRANCH
        # ----------------------------------------------------

        branch=branch,
        branch_id=branch_id,

        # ----------------------------------------------------
        # TEACHER SUBJECTS
        # ----------------------------------------------------

        teacher_subjects=teacher_subjects,
        subjects_count=subjects_count,

        # ----------------------------------------------------
        # EXAM SUBJECTS
        # ----------------------------------------------------

        exam_subjects=exam_subjects,
        exam_subjects_count=exam_subjects_count,

        # ----------------------------------------------------
        # SESSION / ACTIVITY
        # ----------------------------------------------------

        last_active=last_active
    )



# ============================================================
# TEACHER - MY STUDENTS
# ============================================================

@bp.route(
    "/teacher/my-students",
    methods=["GET"]
)
@teacher_login_required
def teacher_my_students():

    # ============================================================
    # CURRENT TEACHER
    # ============================================================

    teacher = g.teacher

    if not teacher:
        abort(403)

    institution_id = teacher.institution_id
    branch_id = teacher.branch_id

    if not institution_id or not branch_id:
        flash(
            "Your teacher account is not assigned to an institution and branch.",
            "warning"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ============================================================
    # FILTER VALUES
    # ============================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    program_id = request.args.get(
        "program_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    status = request.args.get(
        "status",
        "active",
        type=str
    ).strip().lower()

    if status not in {
        "active",
        "inactive",
        "all"
    }:
        status = "active"


    # ============================================================
    # TEACHER ASSIGNMENTS
    # ============================================================

    assignments_query = (
        TeacherSubject.query
        .filter(
            TeacherSubject.teacher_id == teacher.id,
            TeacherSubject.institution_id == institution_id,
            TeacherSubject.branch_id == branch_id,
            TeacherSubject.status == "active",
        )
    )

    if academic_year_id:

        assignments_query = assignments_query.filter(
            TeacherSubject.academic_year_id == academic_year_id
        )

    assignments = (
        assignments_query
        .order_by(
            TeacherSubject.id.asc()
        )
        .all()
    )


    # ============================================================
    # NO ASSIGNMENTS
    # ============================================================

    if not assignments:

        return render_template(
            "backend/teacher/pages/my_students.html",

            teacher=teacher,

            students=[],
            student_enrollments={},

            program_cards=[],
            class_cards=[],
            section_cards=[],

            programs=[],
            classes=[],
            sections=[],
            academic_years=[],

            stats={
                "program_count": 0,
                "class_count": 0,
                "section_count": 0,
                "student_count": 0,
            },

            search=search,

            selected_program_id=program_id,
            selected_class_id=class_id,
            selected_section_id=section_id,
            selected_academic_year_id=academic_year_id,
            selected_status=status,
        )


    # ============================================================
    # BUILD TEACHER ASSIGNMENT CONDITIONS
    #
    # Priority:
    # Section -> Class -> Program
    # ============================================================

    assignment_conditions = []

    for assignment in assignments:

        # --------------------------------------------------------
        # SECTION ASSIGNMENT
        # --------------------------------------------------------

        if assignment.section_id:

            assignment_conditions.append(
                StudentEnrollment.section_id
                == assignment.section_id
            )

        # --------------------------------------------------------
        # CLASS ASSIGNMENT
        # --------------------------------------------------------

        elif assignment.class_id:

            assignment_conditions.append(
                StudentEnrollment.class_id
                == assignment.class_id
            )

        # --------------------------------------------------------
        # PROGRAM ASSIGNMENT
        # --------------------------------------------------------

        elif assignment.program_id:

            assignment_conditions.append(
                StudentEnrollment.program_id
                == assignment.program_id
            )


    # ============================================================
    # IF ASSIGNMENTS HAVE NO PROGRAM/CLASS/SECTION SCOPE
    # ============================================================

    if not assignment_conditions:

        return render_template(
            "backend/teacher/pages/my_students.html",

            teacher=teacher,

            students=[],
            student_enrollments={},

            program_cards=[],
            class_cards=[],
            section_cards=[],

            programs=[],
            classes=[],
            sections=[],
            academic_years=[],

            stats={
                "program_count": 0,
                "class_count": 0,
                "section_count": 0,
                "student_count": 0,
            },

            search=search,

            selected_program_id=program_id,
            selected_class_id=class_id,
            selected_section_id=section_id,
            selected_academic_year_id=academic_year_id,
            selected_status=status,
        )


    # ============================================================
    # STUDENT ID QUERY
    #
    # IMPORTANT:
    # Do NOT use:
    #
    # .distinct(Student.id)
    #
    # because PostgreSQL converts it to DISTINCT ON.
    # ============================================================

    student_ids_query = (
        db.session.query(
            StudentEnrollment.student_id
        )
        .filter(
            StudentEnrollment.institution_id == institution_id,
            StudentEnrollment.branch_id == branch_id,
            db.or_(*assignment_conditions)
        )
    )


    # ============================================================
    # ACADEMIC YEAR FILTER
    # ============================================================

    if academic_year_id:

        student_ids_query = student_ids_query.filter(
            StudentEnrollment.academic_year_id
            == academic_year_id
        )


    # ============================================================
    # PROGRAM FILTER
    # ============================================================

    if program_id:

        student_ids_query = student_ids_query.filter(
            StudentEnrollment.program_id
            == program_id
        )


    # ============================================================
    # CLASS FILTER
    # ============================================================

    if class_id:

        student_ids_query = student_ids_query.filter(
            StudentEnrollment.class_id
            == class_id
        )


    # ============================================================
    # SECTION FILTER
    # ============================================================

    if section_id:

        student_ids_query = student_ids_query.filter(
            StudentEnrollment.section_id
            == section_id
        )


    # ============================================================
    # DISTINCT STUDENT IDS
    # PostgreSQL SAFE
    # ============================================================

    student_ids_subquery = (
        student_ids_query
        .distinct()
        .subquery()
    )


    # ============================================================
    # STUDENTS QUERY
    # ============================================================

    students_query = (
        Student.query
        .filter(
            Student.institution_id == institution_id,
            Student.branch_id == branch_id,

            Student.id.in_(
                db.session.query(
                    student_ids_subquery.c.student_id
                )
            )
        )
    )


    # ============================================================
    # STUDENT STATUS
    # ============================================================

    if status != "all":

        students_query = students_query.filter(
            Student.status == status
        )


    # ============================================================
    # SEARCH
    # ============================================================

    if search:

        search_value = f"%{search}%"

        students_query = students_query.filter(
            db.or_(
                Student.full_name.ilike(search_value),

                Student.admission_no.ilike(
                    search_value
                ),

                Student.roll_no.ilike(
                    search_value
                ),

                Student.username.ilike(
                    search_value
                ),

                Student.email.ilike(
                    search_value
                ),

                Student.phone.ilike(
                    search_value
                ),
            )
        )


    # ============================================================
    # ORDER STUDENTS
    # ============================================================

    students = (
        students_query
        .order_by(
            Student.full_name.asc(),
            Student.id.desc()
        )
        .all()
    )


    # ============================================================
    # STUDENT IDS
    # ============================================================

    student_ids = [
        student.id
        for student in students
    ]


    # ============================================================
    # STUDENT ENROLLMENTS
    # ============================================================

    enrollments = []

    if student_ids:

        enrollment_query = (
            StudentEnrollment.query
            .filter(
                StudentEnrollment.student_id.in_(
                    student_ids
                ),

                StudentEnrollment.institution_id
                == institution_id,

                StudentEnrollment.branch_id
                == branch_id,

                db.or_(*assignment_conditions)
            )
        )


        # --------------------------------------------------------
        # ACADEMIC YEAR
        # --------------------------------------------------------

        if academic_year_id:

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.academic_year_id
                == academic_year_id
            )


        # --------------------------------------------------------
        # PROGRAM
        # --------------------------------------------------------

        if program_id:

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.program_id
                == program_id
            )


        # --------------------------------------------------------
        # CLASS
        # --------------------------------------------------------

        if class_id:

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.class_id
                == class_id
            )


        # --------------------------------------------------------
        # SECTION
        # --------------------------------------------------------

        if section_id:

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.section_id
                == section_id
            )


        enrollments = (
            enrollment_query
            .order_by(
                StudentEnrollment.id.desc()
            )
            .all()
        )


    # ============================================================
    # MAP STUDENT -> ENROLLMENT
    # ============================================================

    student_enrollments = {}

    for enrollment in enrollments:

        if enrollment.student_id not in student_enrollments:

            student_enrollments[
                enrollment.student_id
            ] = enrollment


    # ============================================================
    # PROGRAM / CLASS / SECTION DATA
    # ============================================================

    program_map = {}
    class_map = {}
    section_map = {}


    for enrollment in enrollments:

        # --------------------------------------------------------
        # PROGRAM
        # --------------------------------------------------------

        if enrollment.program:

            program = enrollment.program

            if program.id not in program_map:

                program_map[program.id] = {
                    "id": program.id,
                    "name": program.name,
                    "code": getattr(
                        program,
                        "code",
                        None
                    ),
                    "class_ids": set(),
                    "student_ids": set(),
                }

            program_map[
                program.id
            ]["student_ids"].add(
                enrollment.student_id
            )


        # --------------------------------------------------------
        # CLASS
        # --------------------------------------------------------

        if enrollment.class_:

            current_class = enrollment.class_

            if current_class.id not in class_map:

                class_map[current_class.id] = {
                    "id": current_class.id,
                    "name": current_class.name,
                    "code": getattr(
                        current_class,
                        "code",
                        None
                    ),
                    "program_id": (
                        enrollment.program_id
                    ),
                    "program_name": (
                        enrollment.program.name
                        if enrollment.program
                        else None
                    ),
                    "section_ids": set(),
                    "student_ids": set(),
                }

            class_map[
                current_class.id
            ]["student_ids"].add(
                enrollment.student_id
            )


        # --------------------------------------------------------
        # SECTION
        # --------------------------------------------------------

        if enrollment.section:

            section = enrollment.section

            if section.id not in section_map:

                section_map[section.id] = {
                    "id": section.id,
                    "name": section.name,
                    "code": getattr(
                        section,
                        "code",
                        None
                    ),
                    "class_id": (
                        enrollment.class_id
                    ),
                    "class_name": (
                        enrollment.class_.name
                        if enrollment.class_
                        else None
                    ),
                    "program_id": (
                        enrollment.program_id
                    ),
                    "program_name": (
                        enrollment.program.name
                        if enrollment.program
                        else None
                    ),
                    "student_ids": set(),
                }

            section_map[
                section.id
            ]["student_ids"].add(
                enrollment.student_id
            )


        # --------------------------------------------------------
        # CONNECT PROGRAM -> CLASS
        # --------------------------------------------------------

        if (
            enrollment.program
            and enrollment.class_
        ):

            program_map[
                enrollment.program.id
            ]["class_ids"].add(
                enrollment.class_.id
            )


        # --------------------------------------------------------
        # CONNECT CLASS -> SECTION
        # --------------------------------------------------------

        if (
            enrollment.class_
            and enrollment.section
        ):

            class_map[
                enrollment.class_.id
            ]["section_ids"].add(
                enrollment.section.id
            )


    # ============================================================
    # PROGRAM CARDS
    # ============================================================

    program_cards = []

    for item in program_map.values():

        program_cards.append({
            "id": item["id"],
            "name": item["name"],
            "code": item["code"],

            "class_count": len(
                item["class_ids"]
            ),

            "student_count": len(
                item["student_ids"]
            ),
        })


    program_cards.sort(
        key=lambda item: (
            item["name"] or ""
        ).lower()
    )


    # ============================================================
    # CLASS CARDS
    # ============================================================

    class_cards = []

    for item in class_map.values():

        class_cards.append({
            "id": item["id"],
            "name": item["name"],
            "code": item["code"],

            "program_id": item[
                "program_id"
            ],

            "program_name": item[
                "program_name"
            ],

            "section_count": len(
                item["section_ids"]
            ),

            "student_count": len(
                item["student_ids"]
            ),
        })


    class_cards.sort(
        key=lambda item: (
            item["name"] or ""
        ).lower()
    )


    # ============================================================
    # SECTION CARDS
    # ============================================================

    section_cards = []

    for item in section_map.values():

        section_cards.append({
            "id": item["id"],
            "name": item["name"],
            "code": item["code"],

            "class_id": item[
                "class_id"
            ],

            "class_name": item[
                "class_name"
            ],

            "program_id": item[
                "program_id"
            ],

            "program_name": item[
                "program_name"
            ],

            "student_count": len(
                item["student_ids"]
            ),
        })


    section_cards.sort(
        key=lambda item: (
            item["name"] or ""
        ).lower()
    )


    # ============================================================
    # FILTER OPTIONS
    #
    # IMPORTANT:
    # Only show programs/classes/sections that are connected
    # to THIS teacher's assignments.
    # ============================================================

    teacher_program_ids = {
        assignment.program_id
        for assignment in assignments
        if assignment.program_id
    }

    teacher_class_ids = {
        assignment.class_id
        for assignment in assignments
        if assignment.class_id
    }

    teacher_section_ids = {
        assignment.section_id
        for assignment in assignments
        if assignment.section_id
    }


    # ============================================================
    # PROGRAM FILTER OPTIONS
    # ============================================================

    program_query = (
        Program.query
        .filter(
            Program.institution_id
            == institution_id,

            Program.status
            == "active",

            db.or_(
                Program.branch_id == branch_id,
                Program.branch_id.is_(None)
            )
        )
    )


    if teacher_program_ids:

        program_query = program_query.filter(
            Program.id.in_(
                teacher_program_ids
            )
        )

    else:

        program_query = program_query.filter(
            Program.id.in_(
                [
                    item["id"]
                    for item in program_cards
                ]
            )
        )


    programs = (
        program_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )


    # ============================================================
    # CLASS FILTER OPTIONS
    # ============================================================

    class_query = (
        Class.query
        .filter(
            Class.institution_id
            == institution_id,

            Class.branch_id
            == branch_id,

            Class.status
            == "active"
        )
    )


    if teacher_class_ids:

        class_query = class_query.filter(
            Class.id.in_(
                teacher_class_ids
            )
        )

    else:

        class_query = class_query.filter(
            Class.id.in_(
                [
                    item["id"]
                    for item in class_cards
                ]
            )
        )


    classes = (
        class_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )


    # ============================================================
    # SECTION FILTER OPTIONS
    # ============================================================

    section_query = (
        Section.query
        .filter(
            Section.institution_id
            == institution_id,

            Section.branch_id
            == branch_id,

            Section.status
            == "active"
        )
    )


    if teacher_section_ids:

        section_query = section_query.filter(
            Section.id.in_(
                teacher_section_ids
            )
        )

    else:

        section_query = section_query.filter(
            Section.id.in_(
                [
                    item["id"]
                    for item in section_cards
                ]
            )
        )


    sections = (
        section_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )


    # ============================================================
    # ACADEMIC YEAR FILTER OPTIONS
    # ============================================================

    teacher_academic_year_ids = {
        assignment.academic_year_id
        for assignment in assignments
        if assignment.academic_year_id
    }


    academic_year_query = (
        AcademicYear.query
        .filter(
            AcademicYear.institution_id
            == institution_id,

            AcademicYear.status
            == "active"
        )
    )


    if teacher_academic_year_ids:

        academic_year_query = academic_year_query.filter(
            AcademicYear.id.in_(
                teacher_academic_year_ids
            )
        )


    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.name.desc()
        )
        .all()
    )


    # ============================================================
    # STATISTICS
    # ============================================================

    stats = {
        "program_count": len(
            program_cards
        ),

        "class_count": len(
            class_cards
        ),

        "section_count": len(
            section_cards
        ),

        "student_count": len(
            students
        ),
    }


    # ============================================================
    # RENDER
    # ============================================================

    return render_template(

        "backend/teacher/pages/my_students.html",

        teacher=teacher,

        students=students,

        student_enrollments=student_enrollments,

        # Cards
        program_cards=program_cards,
        class_cards=class_cards,
        section_cards=section_cards,

        # Filter options
        programs=programs,
        classes=classes,
        sections=sections,
        academic_years=academic_years,

        # Statistics
        stats=stats,

        # Current filters
        search=search,

        selected_program_id=program_id,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_academic_year_id=academic_year_id,

        selected_status=status,
    )



# ============================================================
# TEACHER MY SUBJECTS
# ============================================================
@bp.route(
    "/teacher/my-subjects",
    methods=["GET"]
)
@teacher_login_required
def teacher_my_subjects():

    # ========================================================
    # CURRENT TEACHER
    # ========================================================

    teacher = g.teacher

    if not teacher:
        abort(403)

    institution_id = teacher.institution_id
    branch_id = teacher.branch_id

    if not institution_id:
        flash(
            "Your teacher account is not assigned to an institution.",
            "warning"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    program_id = request.args.get(
        "program_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    status = request.args.get(
        "status",
        "active",
        type=str
    ).strip().lower()

    if status not in {
        "active",
        "inactive",
        "all"
    }:
        status = "active"

    # ========================================================
    # HELPER:
    # TEACHER BRANCH SCOPE
    #
    # TeacherSubject assignments are normally stored against
    # the selected branch.
    #
    # If teacher has a branch, use that branch.
    # If teacher is institution-wide, assignments are still
    # restricted to the institution.
    # ========================================================

    assignment_scope_filters = [
        TeacherSubject.teacher_id == teacher.id,
        TeacherSubject.institution_id == institution_id,
    ]

    if branch_id:
        assignment_scope_filters.append(
            TeacherSubject.branch_id == branch_id
        )

    # ========================================================
    # STEP 1
    # GET CURRENT TEACHER ASSIGNMENTS
    #
    # IMPORTANT:
    #
    # My Subjects MUST come from TeacherSubject.subject_id.
    #
    # We DO NOT discover subjects through:
    #
    #     Subject.program_id
    #
    # We DO NOT load every subject in a program.
    #
    # Only subjects explicitly assigned to this teacher are
    # displayed.
    # ========================================================

    assignment_query = (
        TeacherSubject.query
        .filter(
            *assignment_scope_filters
        )
    )

    # ========================================================
    # STATUS FILTER
    # ========================================================

    if status != "all":

        assignment_query = assignment_query.filter(
            TeacherSubject.status == status
        )

    # ========================================================
    # ACADEMIC YEAR FILTER
    # ========================================================

    if academic_year_id:

        assignment_query = assignment_query.filter(
            TeacherSubject.academic_year_id
            == academic_year_id
        )

    # ========================================================
    # PROGRAM FILTER
    # ========================================================

    if program_id:

        assignment_query = assignment_query.filter(
            TeacherSubject.program_id
            == program_id
        )

    # ========================================================
    # CLASS FILTER
    # ========================================================

    if class_id:

        assignment_query = assignment_query.filter(
            TeacherSubject.class_id
            == class_id
        )

    # ========================================================
    # SECTION FILTER
    # ========================================================

    if section_id:

        assignment_query = assignment_query.filter(
            TeacherSubject.section_id
            == section_id
        )

    # ========================================================
    # GET ASSIGNMENTS
    # ========================================================

    assignments = (
        assignment_query
        .order_by(
            TeacherSubject.id.desc()
        )
        .all()
    )

    # ========================================================
    # STEP 2
    # DIRECT SUBJECT IDS
    #
    # ONLY TeacherSubject.subject_id.
    #
    # This prevents a program from automatically exposing all
    # of its subjects.
    # ========================================================

    teacher_subject_ids = {
        assignment.subject_id
        for assignment in assignments
        if assignment.subject_id
    }

    # ========================================================
    # STEP 3
    # SUBJECTS
    # ========================================================

    subjects = []

    if teacher_subject_ids:

        subject_query = (
            Subject.query
            .filter(
                Subject.institution_id
                == institution_id,

                Subject.id.in_(
                    teacher_subject_ids
                ),

                db.or_(
                    Subject.branch_id
                    == branch_id,

                    Subject.branch_id.is_(None)
                )
            )
        )

        # ====================================================
        # SUBJECT SEARCH
        # ====================================================

        if search:

            search_value = f"%{search}%"

            subject_query = (
                subject_query.filter(
                    db.or_(
                        Subject.name.ilike(
                            search_value
                        ),

                        Subject.code.ilike(
                            search_value
                        ),

                        Subject.short_name.ilike(
                            search_value
                        ),

                        Subject.subject_type.ilike(
                            search_value
                        )
                    )
                )
            )

        subjects = (
            subject_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    # ========================================================
    # STEP 4
    # COLLECT ALL RELATED IDS
    #
    # We use these IDs to load actual names in bulk.
    # ========================================================

    all_program_ids = {
        assignment.program_id
        for assignment in assignments
        if assignment.program_id
    }

    all_class_ids = {
        assignment.class_id
        for assignment in assignments
        if assignment.class_id
    }

    all_section_ids = {
        assignment.section_id
        for assignment in assignments
        if assignment.section_id
    }

    all_academic_year_ids = {
        assignment.academic_year_id
        for assignment in assignments
        if assignment.academic_year_id
    }

    # ========================================================
    # STEP 5
    # LOAD PROGRAMS
    # ========================================================

    program_map = {}

    if all_program_ids:

        program_query = (
            Program.query
            .filter(
                Program.institution_id
                == institution_id,

                Program.id.in_(
                    all_program_ids
                ),

                db.or_(
                    Program.branch_id
                    == branch_id,

                    Program.branch_id.is_(None)
                )
            )
        )

        program_objects = (
            program_query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

        program_map = {
            program.id: program
            for program in program_objects
        }

    # ========================================================
    # STEP 6
    # LOAD CLASSES
    #
    # ONLY classes actually used by TeacherSubject assignments.
    # ========================================================

    class_map = {}

    if all_class_ids:

        class_query = (
            Class.query
            .filter(
                Class.institution_id
                == institution_id,

                Class.id.in_(
                    all_class_ids
                )
            )
        )

        if branch_id:
            class_query = class_query.filter(
                Class.branch_id == branch_id
            )

        class_objects = (
            class_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

        class_map = {
            class_obj.id: class_obj
            for class_obj in class_objects
        }

    # ========================================================
    # STEP 7
    # LOAD SECTIONS
    # ========================================================

    section_map = {}

    if all_section_ids:

        section_query = (
            Section.query
            .filter(
                Section.institution_id
                == institution_id,

                Section.id.in_(
                    all_section_ids
                )
            )
        )

        if branch_id:
            section_query = section_query.filter(
                Section.branch_id == branch_id
            )

        section_objects = (
            section_query
            .order_by(
                Section.name.asc()
            )
            .all()
        )

        section_map = {
            section.id: section
            for section in section_objects
        }

    # ========================================================
    # STEP 8
    # LOAD ACADEMIC YEARS
    # ========================================================

    academic_year_map = {}

    if all_academic_year_ids:

        academic_year_objects = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == institution_id,

                AcademicYear.id.in_(
                    all_academic_year_ids
                )
            )
            .order_by(
                AcademicYear.name.desc()
            )
            .all()
        )

        academic_year_map = {
            academic_year.id: academic_year
            for academic_year in academic_year_objects
        }

    # ========================================================
    # STEP 9
    # BUILD SUBJECT CARDS
    #
    # Every card represents a DIRECTLY assigned subject.
    #
    # Example:
    #
    # Teacher A
    #   English -> Class 1
    #   English -> Class 2
    #   Somali  -> Class 1
    #
    # The result will be:
    #
    # English
    #   Classes: Class 1, Class 2
    #
    # Somali
    #   Classes: Class 1
    # ========================================================

    subject_cards = []

    for subject in subjects:

        # ----------------------------------------------------
        # ONLY assignments belonging to this subject
        # ----------------------------------------------------

        related_assignments = [
            assignment
            for assignment in assignments
            if assignment.subject_id == subject.id
        ]

        # ----------------------------------------------------
        # PROGRAM OBJECTS
        # ----------------------------------------------------

        related_programs = {}

        for assignment in related_assignments:

            if assignment.program_id:

                program_obj = program_map.get(
                    assignment.program_id
                )

                if program_obj:

                    related_programs[
                        program_obj.id
                    ] = program_obj

        # ----------------------------------------------------
        # SUBJECT'S OWN PROGRAM
        #
        # Show it as information only.
        #
        # IMPORTANT:
        # We do NOT use this program to discover subjects.
        # ----------------------------------------------------

        if subject.program_id:

            subject_program = program_map.get(
                subject.program_id
            )

            if subject_program:

                related_programs[
                    subject_program.id
                ] = subject_program

        # ----------------------------------------------------
        # CLASS OBJECTS
        # ----------------------------------------------------

        related_classes = {}

        for assignment in related_assignments:

            if assignment.class_id:

                class_obj = class_map.get(
                    assignment.class_id
                )

                if class_obj:

                    related_classes[
                        class_obj.id
                    ] = class_obj

        # ----------------------------------------------------
        # SECTION OBJECTS
        # ----------------------------------------------------

        related_sections = {}

        for assignment in related_assignments:

            if assignment.section_id:

                section_obj = section_map.get(
                    assignment.section_id
                )

                if section_obj:

                    related_sections[
                        section_obj.id
                    ] = section_obj

        # ----------------------------------------------------
        # ACADEMIC YEAR OBJECTS
        # ----------------------------------------------------

        related_years = {}

        for assignment in related_assignments:

            if assignment.academic_year_id:

                year_obj = academic_year_map.get(
                    assignment.academic_year_id
                )

                if year_obj:

                    related_years[
                        year_obj.id
                    ] = year_obj

        # ----------------------------------------------------
        # SORTED OBJECTS
        # ----------------------------------------------------

        related_program_list = sorted(
            related_programs.values(),
            key=lambda item: (
                (item.name or "").lower()
                if getattr(item, "name", None)
                else ""
            )
        )

        related_class_list = sorted(
            related_classes.values(),
            key=lambda item: (
                (item.name or "").lower()
                if getattr(item, "name", None)
                else ""
            )
        )

        related_section_list = sorted(
            related_sections.values(),
            key=lambda item: (
                (item.name or "").lower()
                if getattr(item, "name", None)
                else ""
            )
        )

        related_year_list = sorted(
            related_years.values(),
            key=lambda item: (
                str(item.name)
                if getattr(item, "name", None)
                else ""
            ),
            reverse=True
        )

        # ----------------------------------------------------
        # ACTUAL CLASS NAMES
        #
        # This is what the template can display directly.
        # ----------------------------------------------------

        class_names = [
            class_obj.name
            for class_obj in related_class_list
            if getattr(class_obj, "name", None)
        ]

        # ----------------------------------------------------
        # ACTUAL SECTION NAMES
        # ----------------------------------------------------

        section_names = [
            section_obj.name
            for section_obj in related_section_list
            if getattr(section_obj, "name", None)
        ]

        # ----------------------------------------------------
        # ACTUAL PROGRAM NAMES
        # ----------------------------------------------------

        program_names = [
            program_obj.name
            for program_obj in related_program_list
            if getattr(program_obj, "name", None)
        ]

        # ----------------------------------------------------
        # ACTUAL ACADEMIC YEAR NAMES
        # ----------------------------------------------------

        academic_year_names = [
            academic_year.name
            for academic_year in related_year_list
            if getattr(academic_year, "name", None)
        ]

        # ----------------------------------------------------
        # CLASS IDS
        # ----------------------------------------------------

        assignment_class_ids = {
            assignment.class_id
            for assignment in related_assignments
            if assignment.class_id
        }

        # ----------------------------------------------------
        # SECTION IDS
        # ----------------------------------------------------

        assignment_section_ids = {
            assignment.section_id
            for assignment in related_assignments
            if assignment.section_id
        }

        # ----------------------------------------------------
        # PROGRAM IDS
        # ----------------------------------------------------

        assignment_program_ids = {
            assignment.program_id
            for assignment in related_assignments
            if assignment.program_id
        }

        # Include subject's program only as display metadata.
        if subject.program_id:
            assignment_program_ids.add(
                subject.program_id
            )

        # ----------------------------------------------------
        # ACADEMIC YEAR IDS
        # ----------------------------------------------------

        assignment_year_ids = {
            assignment.academic_year_id
            for assignment in related_assignments
            if assignment.academic_year_id
        }

        # ----------------------------------------------------
        # SUBJECT CARD
        # ----------------------------------------------------

        subject_cards.append({

            # =================================================
            # BASIC INFORMATION
            # =================================================

            "id": subject.id,

            "name": subject.name,

            "code": subject.code,

            "short_name": subject.short_name,

            "subject_type": subject.subject_type,

            # =================================================
            # HOURS
            # =================================================

            "weekly_hours": subject.weekly_hours,

            "credit_hours": subject.credit_hours,

            # =================================================
            # MARKS
            # =================================================

            "max_marks": subject.max_marks,

            "pass_marks": subject.pass_marks,

            # =================================================
            # DESCRIPTION
            # =================================================

            "description": subject.description,

            # =================================================
            # STATUS
            # =================================================

            "status": subject.status,

            # =================================================
            # SUBJECT PROGRAM
            # =================================================

            "program_id": subject.program_id,

            "program_name": (
                subject.program.name
                if getattr(subject, "program", None)
                else None
            ),

            # =================================================
            # PROGRAM INFORMATION
            # =================================================

            "programs": related_program_list,

            "program_names": program_names,

            # =================================================
            # CLASS INFORMATION
            #
            # THIS IS THE IMPORTANT PART FOR YOUR TEMPLATE.
            # =================================================

            "classes": related_class_list,

            "class_names": class_names,

            # =================================================
            # SECTION INFORMATION
            # =================================================

            "sections": related_section_list,

            "section_names": section_names,

            # =================================================
            # ACADEMIC YEAR INFORMATION
            # =================================================

            "academic_years": related_year_list,

            "academic_year_names": academic_year_names,

            # =================================================
            # COUNTS
            # =================================================

            "program_count": len(
                assignment_program_ids
            ),

            "class_count": len(
                assignment_class_ids
            ),

            "section_count": len(
                assignment_section_ids
            ),

            "academic_year_count": len(
                assignment_year_ids
            ),

            "assignment_count": len(
                related_assignments
            ),

            # =================================================
            # FULL ASSIGNMENTS
            # =================================================

            "assignments": related_assignments,
        })

    # ========================================================
    # STEP 10
    # FILTER OPTIONS
    #
    # IMPORTANT:
    # These are based on ALL ACTIVE assignments belonging to
    # this teacher, NOT the current search results.
    #
    # This prevents dropdown options from disappearing when
    # another filter/search is applied.
    # ========================================================

    all_assignment_query = (
        TeacherSubject.query
        .filter(
            TeacherSubject.teacher_id
            == teacher.id,

            TeacherSubject.institution_id
            == institution_id,

            TeacherSubject.status
            == "active",
        )
    )

    if branch_id:

        all_assignment_query = (
            all_assignment_query.filter(
                TeacherSubject.branch_id
                == branch_id
            )
        )

    all_assignments = (
        all_assignment_query
        .order_by(
            TeacherSubject.id.desc()
        )
        .all()
    )

    # ========================================================
    # FILTER OPTION IDS
    # ========================================================

    program_ids = {
        assignment.program_id
        for assignment in all_assignments
        if assignment.program_id
    }

    class_ids = {
        assignment.class_id
        for assignment in all_assignments
        if assignment.class_id
    }

    section_ids = {
        assignment.section_id
        for assignment in all_assignments
        if assignment.section_id
    }

    academic_year_ids = {
        assignment.academic_year_id
        for assignment in all_assignments
        if assignment.academic_year_id
    }

    # ========================================================
    # FILTER SUBJECT IDS
    # ========================================================

    all_teacher_subject_ids = {
        assignment.subject_id
        for assignment in all_assignments
        if assignment.subject_id
    }

    # ========================================================
    # PROGRAMS
    # ========================================================

    programs = []

    if program_ids:

        program_filter_query = (
            Program.query
            .filter(
                Program.institution_id
                == institution_id,

                Program.id.in_(
                    program_ids
                ),

                db.or_(
                    Program.branch_id
                    == branch_id,

                    Program.branch_id.is_(None)
                )
            )
            .order_by(
                Program.name.asc()
            )
        )

        programs = (
            program_filter_query
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    classes = []

    if class_ids:

        class_filter_query = (
            Class.query
            .filter(
                Class.institution_id
                == institution_id,

                Class.id.in_(
                    class_ids
                )
            )
        )

        if branch_id:

            class_filter_query = (
                class_filter_query.filter(
                    Class.branch_id
                    == branch_id
                )
            )

        classes = (
            class_filter_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections = []

    if section_ids:

        section_filter_query = (
            Section.query
            .filter(
                Section.institution_id
                == institution_id,

                Section.id.in_(
                    section_ids
                )
            )
        )

        if branch_id:

            section_filter_query = (
                section_filter_query.filter(
                    Section.branch_id
                    == branch_id
                )
            )

        sections = (
            section_filter_query
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_years = []

    if academic_year_ids:

        academic_years = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == institution_id,

                AcademicYear.id.in_(
                    academic_year_ids
                )
            )
            .order_by(
                AcademicYear.name.desc()
            )
            .all()
        )

    # ========================================================
    # STEP 11
    # STATISTICS
    #
    # Statistics are based on ALL ACTIVE assignments so they
    # remain stable while searching/filtering.
    # ========================================================

    all_active_subject_ids = {
        assignment.subject_id
        for assignment in all_assignments
        if assignment.subject_id
    }

    all_active_program_ids = {
        assignment.program_id
        for assignment in all_assignments
        if assignment.program_id
    }

    all_active_class_ids = {
        assignment.class_id
        for assignment in all_assignments
        if assignment.class_id
    }

    all_active_section_ids = {
        assignment.section_id
        for assignment in all_assignments
        if assignment.section_id
    }

    all_active_year_ids = {
        assignment.academic_year_id
        for assignment in all_assignments
        if assignment.academic_year_id
    }

    stats = {

        # ====================================================
        # UNIQUE SUBJECTS
        # ====================================================

        "subject_count": len(
            all_active_subject_ids
        ),

        # ====================================================
        # CURRENTLY DISPLAYED ASSIGNMENTS
        # ====================================================

        "assignment_count": len(
            assignments
        ),

        # ====================================================
        # ALL ACTIVE PROGRAMS
        # ====================================================

        "program_count": len(
            all_active_program_ids
        ),

        # ====================================================
        # ALL ACTIVE CLASSES
        # ====================================================

        "class_count": len(
            all_active_class_ids
        ),

        # ====================================================
        # ALL ACTIVE SECTIONS
        # ====================================================

        "section_count": len(
            all_active_section_ids
        ),

        # ====================================================
        # ALL ACTIVE ACADEMIC YEARS
        # ====================================================

        "academic_year_count": len(
            all_active_year_ids
        ),
    }

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/teacher/pages/my_subjects.html",

        # ====================================================
        # CURRENT TEACHER
        # ====================================================

        teacher=teacher,

        # ====================================================
        # SUBJECTS
        # ====================================================

        subjects=subjects,

        subject_cards=subject_cards,

        # ====================================================
        # ASSIGNMENTS
        # ====================================================

        assignments=assignments,

        # ====================================================
        # ALL ACTIVE ASSIGNMENTS
        #
        # Useful if the template needs complete assignment
        # information.
        # ====================================================

        all_assignments=all_assignments,

        # ====================================================
        # FILTER OPTIONS
        # ====================================================

        programs=programs,

        classes=classes,

        sections=sections,

        academic_years=academic_years,

        # ====================================================
        # STATISTICS
        # ====================================================

        stats=stats,

        # ====================================================
        # FILTER VALUES
        # ====================================================

        search=search,

        selected_program_id=program_id,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_academic_year_id=academic_year_id,

        selected_status=status,
    )


# ============================================================
# TEACHER ATTENDANCE
# TAKE ATTENDANCE
# ============================================================

# ============================================================
# TEACHER TAKE ATTENDANCE
# ============================================================

@bp.route(
    "/teacher/attendance/take",
    methods=["GET", "POST"]
)
@teacher_login_required
def teacher_take_attendance():

    # ========================================================
    # SECURITY
    # ========================================================

    teacher = g.teacher

    if not teacher:
        abort(403)

    institution_id = teacher.institution_id
    branch_id = teacher.branch_id
    teacher_id = teacher.id

    # ========================================================
    # ========================================================
    # GET
    # ========================================================
    # ========================================================

    if request.method == "GET":

        # ====================================================
        # SELECTED VALUES
        # ====================================================

        selected_class_id = request.args.get(
            "class_id",
            type=int
        )

        selected_teacher_subject_id = request.args.get(
            "teacher_subject_id",
            type=int
        )

        selected_section_id = request.args.get(
            "section_id",
            type=int
        )

        selected_date = (
            request.args.get("attendance_date")
            or date.today().isoformat()
        )

        # ====================================================
        # VALIDATE DATE
        # ====================================================

        try:

            attendance_date_obj = datetime.strptime(
                selected_date,
                "%Y-%m-%d"
            ).date()

        except (TypeError, ValueError):

            attendance_date_obj = date.today()
            selected_date = attendance_date_obj.isoformat()

        # ====================================================
        # TEACHER CLASSES
        # ====================================================

        class_ids = [
            row[0]
            for row in (
                db.session.query(
                    distinct(TeacherSubject.class_id)
                )
                .filter(
                    TeacherSubject.teacher_id == teacher_id,
                    TeacherSubject.institution_id == institution_id,
                    TeacherSubject.branch_id == branch_id,
                    TeacherSubject.class_id.isnot(None),
                    TeacherSubject.status == "active",
                    TeacherSubject.subject_id.isnot(None),
                )
                .all()
            )
            if row[0] is not None
        ]

        classes = []

        if class_ids:

            classes = (
                Class.query
                .filter(
                    Class.id.in_(class_ids),
                    Class.institution_id == institution_id,
                    Class.branch_id == branch_id,
                )
                .order_by(
                    Class.name.asc()
                )
                .all()
            )

        # ====================================================
        # DEFAULT DATA
        # ====================================================

        subjects = []
        sections = []
        students = []

        selected_class = None
        selected_section = None
        selected_assignment = None
        selected_program = None

        existing_session = None

        # ====================================================
        # SELECTED CLASS
        # ====================================================

        if selected_class_id:

            # ------------------------------------------------
            # VERIFY TEACHER CLASS ASSIGNMENT
            # ------------------------------------------------

            class_assignment_exists = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id == teacher_id,
                    TeacherSubject.institution_id == institution_id,
                    TeacherSubject.branch_id == branch_id,
                    TeacherSubject.class_id == selected_class_id,
                    TeacherSubject.status == "active",
                    TeacherSubject.subject_id.isnot(None),
                )
                .first()
            )

            if not class_assignment_exists:
                abort(403)

            # ------------------------------------------------
            # LOAD CLASS
            # ------------------------------------------------

            selected_class = (
                Class.query
                .filter(
                    Class.id == selected_class_id,
                    Class.institution_id == institution_id,
                    Class.branch_id == branch_id,
                )
                .first()
            )

            if not selected_class:
                abort(404)

            # =================================================
            # LOAD ALL TEACHER ASSIGNMENTS
            # =================================================

            assignments = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id == teacher_id,
                    TeacherSubject.institution_id == institution_id,
                    TeacherSubject.branch_id == branch_id,
                    TeacherSubject.class_id == selected_class_id,
                    TeacherSubject.status == "active",
                    TeacherSubject.subject_id.isnot(None),
                )
                .order_by(
                    TeacherSubject.id.asc()
                )
                .all()
            )

            # =================================================
            # SECTIONS
            # =================================================

            section_ids = []

            for assignment in assignments:

                if assignment.section_id:

                    section_ids.append(
                        assignment.section_id
                    )

            section_ids = list(
                dict.fromkeys(section_ids)
            )

            if section_ids:

                sections = (
                    Section.query
                    .filter(
                        Section.id.in_(section_ids),
                        Section.institution_id == institution_id,
                        Section.branch_id == branch_id,
                    )
                    .order_by(
                        Section.name.asc()
                    )
                    .all()
                )

            # =================================================
            # SELECTED SECTION
            # =================================================

            if selected_section_id:

                selected_section = (
                    Section.query
                    .filter(
                        Section.id == selected_section_id,
                        Section.institution_id == institution_id,
                        Section.branch_id == branch_id,
                    )
                    .first()
                )

                if not selected_section:
                    abort(404)

                # ---------------------------------------------
                # TEACHER MUST HAVE ACCESS TO THIS SECTION
                # ---------------------------------------------

                section_assignment_exists = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.teacher_id == teacher_id,
                        TeacherSubject.institution_id == institution_id,
                        TeacherSubject.branch_id == branch_id,
                        TeacherSubject.class_id == selected_class_id,
                        TeacherSubject.section_id == selected_section_id,
                        TeacherSubject.status == "active",
                    )
                    .first()
                )

                if not section_assignment_exists:
                    abort(403)

            # =================================================
            # BUILD SUBJECTS
            #
            # PRIORITY:
            #
            # 1. Section-specific assignment
            # 2. Class-wide assignment
            #
            # If selected section exists:
            #   exact section OR class-wide
            #
            # If no section:
            #   class-wide only
            # =================================================

            subject_assignment_map = {}

            for assignment in assignments:

                subject = assignment.subject

                if not subject:
                    continue

                # ---------------------------------------------
                # SECTION MATCH
                # ---------------------------------------------

                if selected_section_id:

                    if (
                        assignment.section_id is not None
                        and
                        assignment.section_id !=
                        selected_section_id
                    ):

                        continue

                    priority = (
                        2
                        if assignment.section_id ==
                        selected_section_id
                        else 1
                    )

                else:

                    # -----------------------------------------
                    # No section selected:
                    # only class-wide assignments.
                    # -----------------------------------------

                    if assignment.section_id is not None:
                        continue

                    priority = 1

                subject_id = subject.id

                current = subject_assignment_map.get(
                    subject_id
                )

                if current is None:

                    subject_assignment_map[
                        subject_id
                    ] = (
                        priority,
                        assignment
                    )

                else:

                    current_priority = current[0]

                    if priority > current_priority:

                        subject_assignment_map[
                            subject_id
                        ] = (
                            priority,
                            assignment
                        )

            # =================================================
            # BUILD SUBJECT RESPONSE
            # =================================================

            for subject_id, value in sorted(
                subject_assignment_map.items(),
                key=lambda item: (
                    (
                        item[1][1].subject.name
                        or ""
                    ).lower()
                )
            ):

                assignment = value[1]
                subject = assignment.subject

                # ---------------------------------------------
                # PROGRAM
                # ---------------------------------------------

                program = None

                if assignment.program_id:

                    program = assignment.program

                elif getattr(
                    subject,
                    "program_id",
                    None
                ):

                    program = subject.program

                # ---------------------------------------------
                # SESSION FOR THIS EXACT ASSIGNMENT
                # ---------------------------------------------

                session_query = (
                    AttendanceSession.query
                    .filter(
                        AttendanceSession.institution_id ==
                        institution_id,

                        AttendanceSession.branch_id ==
                        branch_id,

                        AttendanceSession.teacher_id ==
                        teacher_id,

                        AttendanceSession.teacher_subject_id ==
                        assignment.id,

                        AttendanceSession.academic_year_id ==
                        assignment.academic_year_id,

                        AttendanceSession.class_id ==
                        selected_class_id,

                        AttendanceSession.attendance_date ==
                        attendance_date_obj,

                        AttendanceSession.status.in_([
                            "completed",
                            "locked",
                        ]),
                    )
                )

                # ---------------------------------------------
                # SECTION
                # ---------------------------------------------

                if selected_section_id:

                    session_query = session_query.filter(
                        AttendanceSession.section_id ==
                        selected_section_id
                    )

                else:

                    session_query = session_query.filter(
                        AttendanceSession.section_id.is_(None)
                    )

                submitted_session = (
                    session_query
                    .order_by(
                        AttendanceSession.id.desc()
                    )
                    .first()
                )

                # ---------------------------------------------
                # IMPORTANT:
                #
                # ALREADY SUBMITTED SUBJECT IS NOT INCLUDED
                # ---------------------------------------------

                if submitted_session:

                    continue

                subjects.append({

                    "id":
                        assignment.id,

                    "teacher_subject_id":
                        assignment.id,

                    "subject":
                        subject,

                    "subject_id":
                        subject.id,

                    "name":
                        subject.name,

                    "code":
                        getattr(
                            subject,
                            "code",
                            None
                        ),

                    "short_name":
                        getattr(
                            subject,
                            "short_name",
                            None
                        ),

                    "program_id":
                        (
                            program.id
                            if program
                            else None
                        ),

                    "program_name":
                        (
                            program.name
                            if program
                            else None
                        ),

                    "section_id":
                        assignment.section_id,

                    "academic_year_id":
                        assignment.academic_year_id,

                    "already_submitted":
                        False,

                    "attendance_submitted":
                        False,

                    "attendance_session_id":
                        None,

                    "attendance_status":
                        None,

                    "attendance_date":
                        selected_date,
                })

            # =================================================
            # SELECTED ASSIGNMENT
            #
            # Must be an assignment that is actually valid
            # for the selected section.
            # =================================================

            if selected_teacher_subject_id:

                candidate_assignment = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.id ==
                        selected_teacher_subject_id,

                        TeacherSubject.teacher_id ==
                        teacher_id,

                        TeacherSubject.institution_id ==
                        institution_id,

                        TeacherSubject.branch_id ==
                        branch_id,

                        TeacherSubject.class_id ==
                        selected_class_id,

                        TeacherSubject.status ==
                        "active",

                        TeacherSubject.subject_id.isnot(None),
                    )
                    .first()
                )

                if not candidate_assignment:
                    abort(403)

                # ---------------------------------------------
                # SECTION COMPATIBILITY
                # ---------------------------------------------

                if selected_section_id:

                    if (
                        candidate_assignment.section_id
                        not in (
                            None,
                            selected_section_id,
                        )
                    ):

                        abort(403)

                else:

                    # Section-specific assignment requires
                    # section selection.

                    if candidate_assignment.section_id:
                        abort(403)

                # ---------------------------------------------
                # SELECTED ASSIGNMENT
                # ---------------------------------------------

                selected_assignment = candidate_assignment

                # ---------------------------------------------
                # PROGRAM
                # ---------------------------------------------

                if selected_assignment.program_id:

                    selected_program = (
                        selected_assignment.program
                    )

                elif (
                    selected_assignment.subject
                    and
                    getattr(
                        selected_assignment.subject,
                        "program_id",
                        None
                    )
                ):

                    selected_program = (
                        selected_assignment.subject.program
                    )

                # ---------------------------------------------
                # CHECK ALREADY SUBMITTED AGAIN
                #
                # Server-side protection.
                # ---------------------------------------------

                selected_session_query = (
                    AttendanceSession.query
                    .filter(
                        AttendanceSession.institution_id ==
                        institution_id,

                        AttendanceSession.branch_id ==
                        branch_id,

                        AttendanceSession.teacher_id ==
                        teacher_id,

                        AttendanceSession.teacher_subject_id ==
                        selected_assignment.id,

                        AttendanceSession.academic_year_id ==
                        selected_assignment.academic_year_id,

                        AttendanceSession.class_id ==
                        selected_class_id,

                        AttendanceSession.attendance_date ==
                        attendance_date_obj,

                        AttendanceSession.status.in_([
                            "completed",
                            "locked",
                        ]),
                    )
                )

                if selected_section_id:

                    selected_session_query = (
                        selected_session_query
                        .filter(
                            AttendanceSession.section_id ==
                            selected_section_id
                        )
                    )

                else:

                    selected_session_query = (
                        selected_session_query
                        .filter(
                            AttendanceSession.section_id.is_(None)
                        )
                    )

                submitted_session = (
                    selected_session_query
                    .order_by(
                        AttendanceSession.id.desc()
                    )
                    .first()
                )

                # ---------------------------------------------
                # NEVER LOAD COMPLETED/LOCKED SESSION
                # ---------------------------------------------

                if submitted_session:

                    # =================================================
                    # ALREADY SUBMITTED RESPONSE
                    #
                    # JSON / AJAX RESPONSE
                    # =================================================

                    wants_json = (
                        request.is_json
                        or
                        "application/json"
                        in (
                            request.headers.get(
                                "Accept",
                                ""
                            ).lower()
                        )
                        or
                        request.headers.get(
                            "X-Requested-With",
                            ""
                        ).lower()
                        == "xmlhttprequest"
                    )

                    message = (
                        "Attendance for this subject, "
                        "section and date has already "
                        "been submitted."
                    )

                    if wants_json:

                        return jsonify({

                            "success":
                                False,

                            "already_submitted":
                                True,

                            "attendance_submitted":
                                True,

                            "message":
                                message,

                            "error":
                                "ATTENDANCE_ALREADY_SUBMITTED",

                            "attendance_session_id":
                                submitted_session.id,

                            "attendance_status":
                                submitted_session.status,

                            "attendance_date":
                                selected_date,

                            "class_id":
                                selected_class_id,

                            "teacher_subject_id":
                                selected_assignment.id,

                            "section_id":
                                selected_section_id,

                            "redirect_url":
                                url_for(
                                    "main.teacher_take_attendance",
                                    class_id=
                                        selected_class_id,
                                    section_id=
                                        selected_section_id,
                                    attendance_date=
                                        selected_date,
                                ),
                        }), 409

                    # =================================================
                    # NORMAL BROWSER RESPONSE
                    # =================================================

                    flash(
                        message,
                        "warning"
                    )

                    return redirect(
                        url_for(
                            "main.teacher_take_attendance",
                            class_id=selected_class_id,
                            section_id=selected_section_id,
                            attendance_date=selected_date,
                        )
                    )

                # ---------------------------------------------
                # FIND OPEN SESSION
                # ---------------------------------------------

                existing_session_query = (
                    AttendanceSession.query
                    .filter(
                        AttendanceSession.institution_id ==
                        institution_id,

                        AttendanceSession.branch_id ==
                        branch_id,

                        AttendanceSession.teacher_id ==
                        teacher_id,

                        AttendanceSession.teacher_subject_id ==
                        selected_assignment.id,

                        AttendanceSession.academic_year_id ==
                        selected_assignment.academic_year_id,

                        AttendanceSession.class_id ==
                        selected_class_id,

                        AttendanceSession.attendance_date ==
                        attendance_date_obj,

                        AttendanceSession.status ==
                        "open",
                    )
                )

                if selected_section_id:

                    existing_session_query = (
                        existing_session_query
                        .filter(
                            AttendanceSession.section_id ==
                            selected_section_id
                        )
                    )

                else:

                    existing_session_query = (
                        existing_session_query
                        .filter(
                            AttendanceSession.section_id.is_(None)
                        )
                    )

                existing_session = (
                    existing_session_query
                    .order_by(
                        AttendanceSession.id.desc()
                    )
                    .first()
                )

                # =================================================
                # ACTIVE ENROLLMENTS
                # =================================================

                enrollment_query = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.institution_id ==
                        institution_id,

                        StudentEnrollment.branch_id ==
                        branch_id,

                        StudentEnrollment.class_id ==
                        selected_class_id,

                        StudentEnrollment.academic_year_id ==
                        selected_assignment.academic_year_id,

                        StudentEnrollment.status ==
                        "active",
                    )
                )

                # ---------------------------------------------
                # SECTION
                # ---------------------------------------------

                if selected_section_id:

                    enrollment_query = (
                        enrollment_query
                        .filter(
                            StudentEnrollment.section_id ==
                            selected_section_id
                        )
                    )

                # ---------------------------------------------
                # PROGRAM
                # ---------------------------------------------

                if selected_assignment.program_id:

                    enrollment_query = (
                        enrollment_query
                        .filter(
                            StudentEnrollment.program_id ==
                            selected_assignment.program_id
                        )
                    )

                enrollments = (
                    enrollment_query
                    .join(
                        Student,
                        Student.id ==
                        StudentEnrollment.student_id
                    )
                    .order_by(
                        Student.full_name.asc()
                    )
                    .all()
                )

                # =================================================
                # EXISTING RECORDS
                # =================================================

                existing_records = {}

                if existing_session:

                    existing_records = {
                        record.student_id: record
                        for record in existing_session.records
                    }

                # =================================================
                # STUDENTS
                # =================================================

                for enrollment in enrollments:

                    student = enrollment.student

                    if not student:
                        continue

                    record = existing_records.get(
                        student.id
                    )

                    students.append({

                        "student":
                            student,

                        "enrollment":
                            enrollment,

                        "record":
                            record,

                        "status":
                            (
                                record.status
                                if record
                                else "present"
                            ),

                        "notes":
                            (
                                record.notes
                                if record
                                else ""
                            ),

                    })

        # ====================================================
        # RENDER
        # ====================================================

        return render_template(

            "backend/teacher/pages/take_attendance.html",

            classes=classes,

            subjects=subjects,

            sections=sections,

            students=students,

            selected_class=selected_class,

            selected_section=selected_section,

            selected_assignment=selected_assignment,

            selected_program=selected_program,

            selected_class_id=selected_class_id,

            selected_section_id=selected_section_id,

            selected_teacher_subject_id=
                selected_teacher_subject_id,

            selected_date=selected_date,

            existing_session=existing_session,

            already_submitted=False,
        )

    # ========================================================
    # ========================================================
    # POST
    # ========================================================
    # SAVE ATTENDANCE
    # ========================================================
    # ========================================================

    class_id = request.form.get(
        "class_id",
        type=int
    )

    teacher_subject_id = request.form.get(
        "teacher_subject_id",
        type=int
    )

    section_id = request.form.get(
        "section_id",
        type=int
    )

    attendance_date_raw = (
        request.form.get(
            "attendance_date"
        )
    )

    session_type = (
        request.form.get("session_type")
        or "subject"
    )

    period = (
        request.form.get("period")
        or None
    )

    notes = (
        request.form.get("notes")
        or None
    )

    # ========================================================
    # BASIC VALIDATION
    # ========================================================

    if not class_id:

        flash(
            "Please select a class.",
            "danger"
        )

        return redirect(
            url_for(
                "main.teacher_take_attendance"
            )
        )

    if not teacher_subject_id:

        flash(
            "Please select a subject.",
            "danger"
        )

        return redirect(
            url_for(
                "main.teacher_take_attendance",
                class_id=class_id
            )
        )

    try:

        attendance_date = datetime.strptime(
            attendance_date_raw,
            "%Y-%m-%d"
        ).date()

    except (TypeError, ValueError):

        flash(
            "Invalid attendance date.",
            "danger"
        )

        return redirect(
            url_for(
                "main.teacher_take_attendance",
                class_id=class_id,
                teacher_subject_id=teacher_subject_id,
                section_id=section_id,
            )
        )

    # ========================================================
    # LOAD ASSIGNMENT
    # ========================================================

    assignment = (
        TeacherSubject.query
        .filter(
            TeacherSubject.id ==
            teacher_subject_id,

            TeacherSubject.teacher_id ==
            teacher_id,

            TeacherSubject.institution_id ==
            institution_id,

            TeacherSubject.branch_id ==
            branch_id,

            TeacherSubject.class_id ==
            class_id,

            TeacherSubject.status ==
            "active",

            TeacherSubject.subject_id.isnot(None),
        )
        .first()
    )

    if not assignment:
        abort(403)

    # ========================================================
    # SECTION SECURITY
    # ========================================================

    if section_id:

        # Section-specific assignment must match.

        if (
            assignment.section_id is not None
            and
            assignment.section_id != section_id
        ):

            abort(403)

        # Verify section belongs to teacher/class.

        section_exists = (
            TeacherSubject.query
            .filter(
                TeacherSubject.teacher_id == teacher_id,
                TeacherSubject.institution_id == institution_id,
                TeacherSubject.branch_id == branch_id,
                TeacherSubject.class_id == class_id,
                TeacherSubject.section_id == section_id,
                TeacherSubject.status == "active",
            )
            .first()
        )

        if not section_exists:
            abort(403)

        section_obj = (
            Section.query
            .filter(
                Section.id == section_id,
                Section.institution_id == institution_id,
                Section.branch_id == branch_id,
            )
            .first()
        )

        if not section_obj:
            abort(404)

    else:

        # Section-specific assignment cannot be saved
        # without selecting its section.

        if assignment.section_id is not None:

            flash(
                "Please select the section for this subject.",
                "warning"
            )

            return redirect(
                url_for(
                    "main.teacher_take_attendance",
                    class_id=class_id,
                    attendance_date=attendance_date.isoformat(),
                )
            )

    # ========================================================
    # CLASS
    # ========================================================

    selected_class = (
        Class.query
        .filter(
            Class.id == class_id,
            Class.institution_id == institution_id,
            Class.branch_id == branch_id,
        )
        .first()
    )

    if not selected_class:
        abort(404)

    # ========================================================
    # PROGRAM
    # ========================================================

    program_id = assignment.program_id

    if not program_id and assignment.subject:

        program_id = getattr(
            assignment.subject,
            "program_id",
            None
        )

    # ========================================================
    # CHECK COMPLETED / LOCKED SESSION
    #
    # THIS IS THE FINAL SERVER-SIDE LOCK.
    # ========================================================

    submitted_session_query = (
        AttendanceSession.query
        .filter(
            AttendanceSession.institution_id ==
            institution_id,

            AttendanceSession.branch_id ==
            branch_id,

            AttendanceSession.teacher_id ==
            teacher_id,

            AttendanceSession.teacher_subject_id ==
            assignment.id,

            AttendanceSession.academic_year_id ==
            assignment.academic_year_id,

            AttendanceSession.class_id ==
            class_id,

            AttendanceSession.attendance_date ==
            attendance_date,

            AttendanceSession.status.in_([
                "completed",
                "locked",
            ]),
        )
    )

    if section_id:

        submitted_session_query = (
            submitted_session_query
            .filter(
                AttendanceSession.section_id ==
                section_id
            )
        )

    else:

        submitted_session_query = (
            submitted_session_query
            .filter(
                AttendanceSession.section_id.is_(None)
            )
        )

    submitted_session = (
        submitted_session_query
        .order_by(
            AttendanceSession.id.desc()
        )
        .first()
    )

    if submitted_session:

        # ====================================================
        # ALREADY SUBMITTED RESPONSE
        #
        # AJAX / JSON
        # ====================================================

        wants_json = (
            request.is_json
            or
            "application/json"
            in (
                request.headers.get(
                    "Accept",
                    ""
                ).lower()
            )
            or
            request.headers.get(
                "X-Requested-With",
                ""
            ).lower()
            == "xmlhttprequest"
        )

        message = (
            "Attendance for this subject, section and date "
            "has already been submitted."
        )

        if wants_json:

            return jsonify({

                "success":
                    False,

                "already_submitted":
                    True,

                "attendance_submitted":
                    True,

                "message":
                    message,

                "error":
                    "ATTENDANCE_ALREADY_SUBMITTED",

                "attendance_session_id":
                    submitted_session.id,

                "attendance_status":
                    submitted_session.status,

                "attendance_date":
                    attendance_date.isoformat(),

                "class_id":
                    class_id,

                "teacher_subject_id":
                    assignment.id,

                "section_id":
                    section_id,

                "redirect_url":
                    url_for(
                        "main.teacher_take_attendance",
                        class_id=class_id,
                        teacher_subject_id=assignment.id,
                        section_id=section_id,
                        attendance_date=
                            attendance_date.isoformat(),
                    ),
            }), 409

        # ====================================================
        # NORMAL BROWSER RESPONSE
        # ====================================================

        flash(
            message,
            "warning"
        )

        return redirect(
            url_for(
                "main.teacher_take_attendance",
                class_id=class_id,
                section_id=section_id,
                attendance_date=
                    attendance_date.isoformat(),
            )
        )

    # ========================================================
    # OPEN SESSION
    # ========================================================

    session_query = (
        AttendanceSession.query
        .filter(
            AttendanceSession.institution_id ==
            institution_id,

            AttendanceSession.branch_id ==
            branch_id,

            AttendanceSession.teacher_id ==
            teacher_id,

            AttendanceSession.teacher_subject_id ==
            assignment.id,

            AttendanceSession.academic_year_id ==
            assignment.academic_year_id,

            AttendanceSession.class_id ==
            class_id,

            AttendanceSession.attendance_date ==
            attendance_date,

            AttendanceSession.status == "open",
        )
    )

    if section_id:

        session_query = (
            session_query
            .filter(
                AttendanceSession.section_id ==
                section_id
            )
        )

    else:

        session_query = (
            session_query
            .filter(
                AttendanceSession.section_id.is_(None)
            )
        )

    session = (
        session_query
        .order_by(
            AttendanceSession.id.desc()
        )
        .first()
    )

    # ========================================================
    # CREATE SESSION
    # ========================================================

    if not session:

        session = AttendanceSession(

            institution_id=
                institution_id,

            branch_id=
                branch_id,

            teacher_id=
                teacher_id,

            teacher_subject_id=
                assignment.id,

            academic_year_id=
                assignment.academic_year_id,

            class_id=
                class_id,

            section_id=
                section_id,

            subject_id=
                assignment.subject_id,

            attendance_date=
                attendance_date,

            session_type=
                session_type,

            period=
                period,

            status=
                "open",

            notes=
                notes,
        )

        db.session.add(session)

        db.session.flush()

    else:

        session.period = period
        session.notes = notes

    # ========================================================
    # ACTIVE ENROLLMENTS
    # ========================================================

    enrollment_query = (
        StudentEnrollment.query
        .filter(
            StudentEnrollment.institution_id ==
            institution_id,

            StudentEnrollment.branch_id ==
            branch_id,

            StudentEnrollment.class_id ==
            class_id,

            StudentEnrollment.academic_year_id ==
            assignment.academic_year_id,

            StudentEnrollment.status ==
            "active",
        )
    )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.section_id ==
                section_id
            )
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    if program_id:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.program_id ==
                program_id
            )
        )

    enrollments = (
        enrollment_query
        .all()
    )

    # ========================================================
    # PROCESS STUDENTS
    # ========================================================

    allowed_statuses = {
        "present",
        "absent",
        "late",
        "excused",
        "sick",
        "leave",
    }

    for enrollment in enrollments:

        student_id = enrollment.student_id

        # ----------------------------------------------------
        # CHECKBOX
        #
        # checked   = present
        # unchecked = absent
        # ----------------------------------------------------

        status = request.form.get(
            f"attendance_{student_id}"
        )

        if not status:
            status = "absent"

        if status not in allowed_statuses:
            status = "present"

        # ----------------------------------------------------
        # NOTE
        # ----------------------------------------------------

        student_note = (
            request.form.get(
                f"note_{student_id}"
            )
            or None
        )

        # ----------------------------------------------------
        # EXISTING RECORD
        # ----------------------------------------------------

        record = (
            AttendanceRecord.query
            .filter(
                AttendanceRecord.attendance_session_id ==
                session.id,

                AttendanceRecord.student_id ==
                student_id,
            )
            .first()
        )

        # ----------------------------------------------------
        # CREATE
        # ----------------------------------------------------

        if not record:

            record = AttendanceRecord(

                attendance_session_id=
                    session.id,

                student_id=
                    student_id,

                enrollment_id=
                    enrollment.id,

                status=
                    status,

                marked_by_teacher_id=
                    teacher_id,

                notes=
                    student_note,
            )

            if status in {
                "present",
                "late",
            }:

                record.check_in = datetime.utcnow()

            db.session.add(record)

        # ----------------------------------------------------
        # UPDATE
        # ----------------------------------------------------

        else:

            record.status = status

            record.enrollment_id = (
                enrollment.id
            )

            record.marked_by_teacher_id = (
                teacher_id
            )

            record.notes = student_note

            if status in {
                "present",
                "late",
            }:

                if not record.check_in:

                    record.check_in = (
                        datetime.utcnow()
                    )

            else:

                record.check_in = None

            if status != "present":

                record.check_out = None

    # ========================================================
    # COMPLETE
    # ========================================================

    session.status = "completed"

    session.updated_at = datetime.utcnow()

    # ========================================================
    # COMMIT
    # ========================================================

    try:

        db.session.commit()

    except Exception:

        db.session.rollback()

        flash(
            "Unable to save attendance. "
            "Please try again.",
            "danger"
        )

        return redirect(
            url_for(
                "main.teacher_take_attendance",
                class_id=class_id,
                teacher_subject_id=assignment.id,
                section_id=section_id,
                attendance_date=
                    attendance_date.isoformat(),
            )
        )

    # ========================================================
    # SUCCESS
    # ========================================================

    flash(
        "Attendance saved successfully.",
        "success"
    )

    return redirect(
        url_for(
            "main.teacher_take_attendance",
            class_id=class_id,
            attendance_date=
                attendance_date.isoformat(),
        )
    )

# ============================================================
# AJAX:
# GET SUBJECTS + SECTIONS FOR SELECTED CLASS
# ============================================================

@bp.route(
    "/teacher/attendance/class/<int:class_id>/subjects",
    methods=["GET"]
)
@teacher_login_required
def teacher_attendance_class_subjects(class_id):

    # ========================================================
    # SECURITY
    # ========================================================

    teacher = getattr(
        g,
        "teacher",
        None
    )

    if not teacher:
        abort(403)

    institution_id = getattr(
        teacher,
        "institution_id",
        None
    )

    branch_id = getattr(
        teacher,
        "branch_id",
        None
    )

    teacher_id = getattr(
        teacher,
        "id",
        None
    )

    if not institution_id or not teacher_id:
        abort(403)

    # ========================================================
    # TODAY ONLY
    # ========================================================

    today = datetime.utcnow().date()

    attendance_date = today

    # ========================================================
    # REQUESTED SECTION
    #
    # OPTIONAL
    # ========================================================

    requested_section_id = request.args.get(
        "section_id",
        type=int
    )

    # ========================================================
    # COMMON EMPTY RESPONSE
    # ========================================================

    def empty_response(
        message,
        status_code=200
    ):

        return jsonify({

            "success": False,

            "message": message,

            "class_id": class_id,

            "attendance_date":
                attendance_date.isoformat(),

            "requested_section_id":
                requested_section_id,

            "subjects": [],

            "sections": [],

            "today_only": True,

            "can_change_date": False,

            "hidden_submitted_subjects": False,

        }), status_code

    # ========================================================
    # VERIFY CLASS
    #
    # Teacher must belong to same institution + branch.
    # ========================================================

    class_obj = (
        Class.query
        .filter(
            Class.id == class_id,
            Class.institution_id == institution_id,
            Class.branch_id == branch_id,
        )
        .first()
    )

    if not class_obj:

        return empty_response(
            "Class not found.",
            404
        )

    # ========================================================
    # LOAD ACTIVE TEACHER SUBJECT ASSIGNMENTS
    #
    # IMPORTANT:
    #
    # We load BOTH:
    #
    #     section_id = NULL
    #
    # and
    #
    #     section_id != NULL
    #
    # because we need to determine:
    #
    #     1. available class-wide subjects
    #     2. explicitly assigned sections
    #     3. exact section subjects
    # ========================================================

    assignments = (
        TeacherSubject.query
        .filter(
            TeacherSubject.teacher_id == teacher_id,

            TeacherSubject.institution_id ==
                institution_id,

            TeacherSubject.branch_id ==
                branch_id,

            TeacherSubject.class_id ==
                class_id,

            TeacherSubject.status ==
                "active",

            TeacherSubject.subject_id.isnot(None),
        )
        .order_by(
            TeacherSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # NO ASSIGNMENT AT ALL
    # ========================================================

    if not assignments:

        return empty_response(
            "You are not assigned to this class.",
            403
        )

    # ========================================================
    # SEPARATE ASSIGNMENTS
    # ========================================================

    class_wide_assignments = [
        assignment
        for assignment in assignments
        if assignment.section_id is None
    ]

    section_specific_assignments = [
        assignment
        for assignment in assignments
        if assignment.section_id is not None
    ]

    # ========================================================
    # VALIDATE REQUESTED SECTION
    # ========================================================

    requested_section = None

    if requested_section_id is not None:

        requested_section = (
            Section.query
            .filter(
                Section.id ==
                    requested_section_id,

                Section.institution_id ==
                    institution_id,

                Section.branch_id ==
                    branch_id,
            )
            .first()
        )

        # ====================================================
        # SECTION NOT FOUND
        # ====================================================

        if not requested_section:

            return empty_response(
                "Section not found.",
                404
            )

        # ====================================================
        # SECTION MUST BELONG TO SELECTED CLASS
        # ====================================================

        section_class_id = getattr(
            requested_section,
            "class_id",
            None
        )

        if section_class_id != class_id:

            return empty_response(
                "The selected section does not belong to this class.",
                403
            )

        # ====================================================
        # VERY IMPORTANT
        #
        # CHECK EXPLICIT SECTION ASSIGNMENT
        #
        # CLASS-WIDE ASSIGNMENT DOES NOT GRANT SECTION ACCESS.
        # ====================================================

        exact_section_assignments = [

            assignment

            for assignment in section_specific_assignments

            if assignment.section_id ==
                requested_section_id
        ]

        if not exact_section_assignments:

            return empty_response(
                "You are not assigned to this section.",
                403
            )

    # ========================================================
    # BUILD ACCESSIBLE SECTIONS
    #
    # IMPORTANT:
    #
    # ONLY EXPLICIT SECTION ASSIGNMENTS.
    #
    # We DO NOT add all class sections when class-wide
    # assignment exists.
    # ========================================================

    section_map = {}

    for assignment in section_specific_assignments:

        section = getattr(
            assignment,
            "section",
            None
        )

        if not section:
            continue

        # ====================================================
        # VERIFY INSTITUTION
        # ====================================================

        section_institution_id = getattr(
            section,
            "institution_id",
            None
        )

        if (
            section_institution_id !=
            institution_id
        ):
            continue

        # ====================================================
        # VERIFY BRANCH
        # ====================================================

        section_branch_id = getattr(
            section,
            "branch_id",
            None
        )

        if (
            section_branch_id !=
            branch_id
        ):
            continue

        # ====================================================
        # VERIFY CLASS
        # ====================================================

        section_class_id = getattr(
            section,
            "class_id",
            None
        )

        if (
            section_class_id !=
            class_id
        ):
            continue

        # ====================================================
        # ADD SECTION
        # ====================================================

        if section.id not in section_map:

            section_map[
                section.id
            ] = {

                "id":
                    section.id,

                "name":
                    getattr(
                        section,
                        "name",
                        None
                    ),

                "teacher_subject_id":
                    assignment.id,

                "already_submitted":
                    False,

                "attendance_submitted":
                    False,

                "attendance_session_id":
                    None,

                "attendance_status":
                    None,
            }

        else:

            # =================================================
            # Prefer primary assignment
            # =================================================

            existing_id = (
                section_map[
                    section.id
                ].get(
                    "teacher_subject_id"
                )
            )

            existing_assignment = next(
                (
                    item
                    for item in section_specific_assignments
                    if item.id == existing_id
                ),
                None
            )

            if existing_assignment:

                existing_primary = bool(
                    getattr(
                        existing_assignment,
                        "is_primary",
                        False
                    )
                )

                new_primary = bool(
                    getattr(
                        assignment,
                        "is_primary",
                        False
                    )
                )

                if (
                    new_primary
                    and
                    not existing_primary
                ):

                    section_map[
                        section.id
                    ][
                        "teacher_subject_id"
                    ] = assignment.id

                elif (
                    new_primary ==
                    existing_primary
                    and
                    assignment.id <
                    existing_assignment.id
                ):

                    section_map[
                        section.id
                    ][
                        "teacher_subject_id"
                    ] = assignment.id

    # ========================================================
    # SORT SECTIONS
    # ========================================================

    sections = list(
        section_map.values()
    )

    sections.sort(
        key=lambda item: (
            str(
                item.get(
                    "name"
                )
                or ""
            )
        ).lower()
    )

    # ========================================================
    # FIND BEST ASSIGNMENT PER SUBJECT
    #
    # NO SECTION:
    #
    #     ONLY class-wide assignments.
    #
    # SECTION SELECTED:
    #
    #     EXACT section assignment
    #         priority 2
    #
    #     class-wide assignment
    #         priority 1
    #
    # IMPORTANT:
    #
    # The class-wide fallback is allowed ONLY because the
    # requested section was already verified above as an
    # explicitly assigned section.
    # ========================================================

    best_assignments = {}

    for assignment in assignments:

        subject = getattr(
            assignment,
            "subject",
            None
        )

        if not subject:
            continue

        # ====================================================
        # NO SECTION SELECTED
        # ====================================================

        if requested_section_id is None:

            # Only class-wide subjects.
            if assignment.section_id is not None:
                continue

            priority = 1

        # ====================================================
        # SECTION SELECTED
        # ====================================================

        else:

            # Exact section assignment.
            if (
                assignment.section_id ==
                requested_section_id
            ):

                priority = 2

            # Class-wide fallback.
            elif assignment.section_id is None:

                priority = 1

            # Assignment belongs to another section.
            else:

                continue

        # ====================================================
        # SUBJECT ID
        # ====================================================

        subject_id = getattr(
            subject,
            "id",
            None
        )

        if not subject_id:
            continue

        # ====================================================
        # CURRENT BEST
        # ====================================================

        current = best_assignments.get(
            subject_id
        )

        if current is None:

            best_assignments[
                subject_id
            ] = (
                priority,
                assignment
            )

            continue

        current_priority = current[0]

        current_assignment = current[1]

        # ====================================================
        # HIGHER SECTION PRIORITY
        # ====================================================

        if priority > current_priority:

            best_assignments[
                subject_id
            ] = (
                priority,
                assignment
            )

            continue

        # ====================================================
        # SAME PRIORITY
        #
        # PRIMARY FIRST
        # ====================================================

        current_primary = bool(
            getattr(
                current_assignment,
                "is_primary",
                False
            )
        )

        new_primary = bool(
            getattr(
                assignment,
                "is_primary",
                False
            )
        )

        if (
            new_primary
            and
            not current_primary
        ):

            best_assignments[
                subject_id
            ] = (
                priority,
                assignment
            )

            continue

        # ====================================================
        # SAME PRIMARY STATE
        #
        # LOWEST ID WINS
        # ====================================================

        if (
            new_primary ==
            current_primary
            and
            assignment.id <
            current_assignment.id
        ):

            best_assignments[
                subject_id
            ] = (
                priority,
                assignment
            )

    # ========================================================
    # BUILD SUBJECT RESPONSE
    # ========================================================

    subjects = []

    for subject_id, value in sorted(

        best_assignments.items(),

        key=lambda item: (
            str(
                getattr(
                    item[1][1].subject,
                    "name",
                    ""
                )
                or ""
            ).lower()
        )
    ):

        assignment = value[1]

        subject = getattr(
            assignment,
            "subject",
            None
        )

        if not subject:
            continue

        # ====================================================
        # PROGRAM
        # ====================================================

        program = None

        assignment_program_id = getattr(
            assignment,
            "program_id",
            None
        )

        if assignment_program_id:

            program = getattr(
                assignment,
                "program",
                None
            )

        elif getattr(
            subject,
            "program_id",
            None
        ):

            program = getattr(
                subject,
                "program",
                None
            )

        # ====================================================
        # BASE ATTENDANCE SESSION QUERY
        # ====================================================

        session_query = (
            AttendanceSession.query
            .filter(
                AttendanceSession.institution_id ==
                    institution_id,

                AttendanceSession.branch_id ==
                    branch_id,

                AttendanceSession.teacher_id ==
                    teacher_id,

                AttendanceSession.teacher_subject_id ==
                    assignment.id,

                AttendanceSession.academic_year_id ==
                    assignment.academic_year_id,

                AttendanceSession.class_id ==
                    class_id,

                AttendanceSession.attendance_date ==
                    attendance_date,

                AttendanceSession.status.in_([
                    "completed",
                    "locked",
                ]),
            )
        )

        submitted_session = None

        # ====================================================
        # SECTION-SPECIFIC ASSIGNMENT
        #
        # Exact section only.
        # ====================================================

        if assignment.section_id is not None:

            submitted_session = (
                session_query
                .filter(
                    AttendanceSession.section_id ==
                        assignment.section_id
                )
                .order_by(
                    AttendanceSession.id.desc()
                )
                .first()
            )

        # ====================================================
        # CLASS-WIDE ASSIGNMENT + SECTION SELECTED
        #
        # Exact section first.
        # Then class-wide session.
        #
        # This is allowed because the requested section was
        # already explicitly authorized above.
        # ====================================================

        elif requested_section_id is not None:

            exact_session = (
                session_query
                .filter(
                    AttendanceSession.section_id ==
                        requested_section_id
                )
                .order_by(
                    AttendanceSession.id.desc()
                )
                .first()
            )

            if exact_session:

                submitted_session = (
                    exact_session
                )

            else:

                submitted_session = (
                    session_query
                    .filter(
                        AttendanceSession.section_id.is_(None)
                    )
                    .order_by(
                        AttendanceSession.id.desc()
                    )
                    .first()
                )

        # ====================================================
        # CLASS-WIDE ASSIGNMENT + NO SECTION
        # ====================================================

        else:

            submitted_session = (
                session_query
                .filter(
                    AttendanceSession.section_id.is_(None)
                )
                .order_by(
                    AttendanceSession.id.desc()
                )
                .first()
            )

        # ====================================================
        # SUBJECT RESPONSE
        # ====================================================

        subjects.append({

            "teacher_subject_id":
                assignment.id,

            "subject_id":
                subject.id,

            "name":
                getattr(
                    subject,
                    "name",
                    None
                ),

            "code":
                getattr(
                    subject,
                    "code",
                    None
                ),

            "short_name":
                getattr(
                    subject,
                    "short_name",
                    None
                ),

            "program_id":
                (
                    program.id
                    if program
                    else None
                ),

            "program_name":
                (
                    getattr(
                        program,
                        "name",
                        None
                    )
                    if program
                    else None
                ),

            "section_id":
                assignment.section_id,

            "academic_year_id":
                assignment.academic_year_id,

            "already_submitted":
                bool(
                    submitted_session
                ),

            "attendance_submitted":
                bool(
                    submitted_session
                ),

            "attendance_session_id":
                (
                    submitted_session.id
                    if submitted_session
                    else None
                ),

            "attendance_status":
                (
                    submitted_session.status
                    if submitted_session
                    else None
                ),

            "attendance_date":
                attendance_date.isoformat(),
        })

    # ========================================================
    # SECTION ATTENDANCE STATUS
    #
    # ONLY ACCESSIBLE SECTIONS ARE PROCESSED.
    #
    # A section is "submitted" only when ALL applicable
    # subjects for that section have completed/locked sessions.
    # ========================================================

    for section_data in sections:

        section_id_value = section_data.get(
            "id"
        )

        if not section_id_value:
            continue

        # ====================================================
        # BEST ASSIGNMENT PER SUBJECT
        # ====================================================

        section_best_assignments = {}

        for assignment in section_specific_assignments:

            if (
                assignment.section_id !=
                section_id_value
            ):
                continue

            subject = getattr(
                assignment,
                "subject",
                None
            )

            if not subject:
                continue

            subject_id = getattr(
                subject,
                "id",
                None
            )

            if not subject_id:
                continue

            current = section_best_assignments.get(
                subject_id
            )

            if current is None:

                section_best_assignments[
                    subject_id
                ] = assignment

                continue

            current_primary = bool(
                getattr(
                    current,
                    "is_primary",
                    False
                )
            )

            new_primary = bool(
                getattr(
                    assignment,
                    "is_primary",
                    False
                )
            )

            if (
                new_primary
                and
                not current_primary
            ):

                section_best_assignments[
                    subject_id
                ] = assignment

                continue

            if (
                new_primary ==
                current_primary
                and
                assignment.id <
                current.id
            ):

                section_best_assignments[
                    subject_id
                ] = assignment

        # ====================================================
        # ALSO ADD CLASS-WIDE SUBJECTS
        #
        # Exact section assignment has priority.
        # Class-wide is fallback.
        # ====================================================

        for assignment in class_wide_assignments:

            subject = getattr(
                assignment,
                "subject",
                None
            )

            if not subject:
                continue

            subject_id = getattr(
                subject,
                "id",
                None
            )

            if not subject_id:
                continue

            if subject_id in section_best_assignments:
                continue

            section_best_assignments[
                subject_id
            ] = assignment

        # ====================================================
        # NO SUBJECTS
        # ====================================================

        if not section_best_assignments:

            continue

        # ====================================================
        # CHECK ALL SUBJECTS
        # ====================================================

        all_submitted = True

        submitted_sessions = []

        for subject_id, assignment in (
            section_best_assignments.items()
        ):

            session_query = (
                AttendanceSession.query
                .filter(
                    AttendanceSession.institution_id ==
                        institution_id,

                    AttendanceSession.branch_id ==
                        branch_id,

                    AttendanceSession.teacher_id ==
                        teacher_id,

                    AttendanceSession.teacher_subject_id ==
                        assignment.id,

                    AttendanceSession.academic_year_id ==
                        assignment.academic_year_id,

                    AttendanceSession.class_id ==
                        class_id,

                    AttendanceSession.attendance_date ==
                        attendance_date,

                    AttendanceSession.status.in_([
                        "completed",
                        "locked",
                    ]),
                )
            )

            # =================================================
            # SECTION-SPECIFIC ASSIGNMENT
            # =================================================

            if assignment.section_id is not None:

                found_session = (
                    session_query
                    .filter(
                        AttendanceSession.section_id ==
                            section_id_value
                    )
                    .order_by(
                        AttendanceSession.id.desc()
                    )
                    .first()
                )

            # =================================================
            # CLASS-WIDE ASSIGNMENT
            #
            # Exact section first.
            # Class-wide second.
            # =================================================

            else:

                exact_session = (
                    session_query
                    .filter(
                        AttendanceSession.section_id ==
                            section_id_value
                    )
                    .order_by(
                        AttendanceSession.id.desc()
                    )
                    .first()
                )

                if exact_session:

                    found_session = (
                        exact_session
                    )

                else:

                    found_session = (
                        session_query
                        .filter(
                            AttendanceSession.section_id.is_(None)
                        )
                        .order_by(
                            AttendanceSession.id.desc()
                        )
                        .first()
                    )

            if found_session:

                submitted_sessions.append(
                    found_session
                )

            else:

                all_submitted = False

        # ====================================================
        # UPDATE SECTION STATUS
        # ====================================================

        if (
            all_submitted
            and
            submitted_sessions
        ):

            latest_session = max(
                submitted_sessions,
                key=lambda session: (
                    session.id or 0
                )
            )

            section_data[
                "already_submitted"
            ] = True

            section_data[
                "attendance_submitted"
            ] = True

            section_data[
                "attendance_session_id"
            ] = latest_session.id

            section_data[
                "attendance_status"
            ] = latest_session.status

        else:

            section_data[
                "already_submitted"
            ] = False

            section_data[
                "attendance_submitted"
            ] = False

            section_data[
                "attendance_session_id"
            ] = None

            section_data[
                "attendance_status"
            ] = None

    # ========================================================
    # FINAL RESPONSE
    # ========================================================

    return jsonify({

        "success":
            True,

        "message":
            (
                "Subjects loaded."
                if subjects
                else
                (
                    "Please select a section to load "
                    "section-specific subjects."
                    if requested_section_id is None
                    else
                    "No subjects are assigned to this section."
                )
            ),

        "class_id":
            class_id,

        "attendance_date":
            attendance_date.isoformat(),

        "requested_section_id":
            requested_section_id,

        "subjects":
            subjects,

        "sections":
            sections,

        "today_only":
            True,

        "can_change_date":
            False,

        "hidden_submitted_subjects":
            False,

    })



# ============================================================
# AJAX:
# GET STUDENTS FOR ATTENDANCE
# ============================================================

@bp.route(
    "/teacher/attendance/students",
    methods=["GET"]
)
@teacher_login_required
def teacher_attendance_students():

    # ========================================================
    # SECURITY
    # ========================================================

    teacher = getattr(
        g,
        "teacher",
        None
    )

    if not teacher:
        abort(403)

    institution_id = getattr(
        teacher,
        "institution_id",
        None
    )

    branch_id = getattr(
        teacher,
        "branch_id",
        None
    )

    teacher_id = getattr(
        teacher,
        "id",
        None
    )

    if not institution_id or not teacher_id:
        abort(403)

    # ========================================================
    # TODAY
    # ========================================================

    attendance_date = datetime.utcnow().date()

    # ========================================================
    # PARAMETERS
    # ========================================================

    class_id = request.args.get(
        "class_id",
        type=int
    )

    teacher_subject_id = request.args.get(
        "teacher_subject_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    # ========================================================
    # BASIC VALIDATION
    # ========================================================

    if not class_id:

        return jsonify({

            "success":
                False,

            "message":
                "Class is required.",

            "students":
                [],

            "attendance_date":
                attendance_date.isoformat(),

        }), 400

    if not teacher_subject_id:

        return jsonify({

            "success":
                False,

            "message":
                "Teacher subject assignment is required.",

            "students":
                [],

            "attendance_date":
                attendance_date.isoformat(),

        }), 400

    # ========================================================
    # LOAD CLASS
    # ========================================================

    selected_class = (
        Class.query
        .filter(

            Class.id ==
            class_id,

            Class.institution_id ==
            institution_id,

            Class.branch_id ==
            branch_id,
        )
        .first()
    )

    if not selected_class:

        return jsonify({

            "success":
                False,

            "message":
                "Invalid class.",

            "students":
                [],

            "attendance_date":
                attendance_date.isoformat(),

        }), 403

    # ========================================================
    # LOAD TEACHER ASSIGNMENT
    # ========================================================

    assignment = (
        TeacherSubject.query
        .filter(

            TeacherSubject.id ==
            teacher_subject_id,

            TeacherSubject.teacher_id ==
            teacher_id,

            TeacherSubject.institution_id ==
            institution_id,

            TeacherSubject.branch_id ==
            branch_id,

            TeacherSubject.class_id ==
            class_id,

            TeacherSubject.status ==
            "active",

            TeacherSubject.subject_id.isnot(None),
        )
        .first()
    )

    if not assignment:

        return jsonify({

            "success":
                False,

            "message":
                (
                    "Invalid or unauthorized teacher "
                    "subject assignment."
                ),

            "students":
                [],

            "attendance_date":
                attendance_date.isoformat(),

        }), 403

    # ========================================================
    # SECTION SECURITY
    # ========================================================

    assignment_section_id = getattr(
        assignment,
        "section_id",
        None
    )

    # ========================================================
    # SECTION-SPECIFIC ASSIGNMENT
    #
    # MUST use exact section.
    # ========================================================

    if assignment_section_id is not None:

        if section_id is None:

            return jsonify({

                "success":
                    False,

                "message":
                    (
                        "A section is required for "
                        "this teacher assignment."
                    ),

                "students":
                    [],

                "attendance_date":
                    attendance_date.isoformat(),

            }), 400

        if assignment_section_id != section_id:

            return jsonify({

                "success":
                    False,

                "message":
                    (
                        "The selected section does not "
                        "belong to this teacher assignment."
                    ),

                "students":
                    [],

                "attendance_date":
                    attendance_date.isoformat(),

            }), 403

    # ========================================================
    # SECTION VALIDATION
    # ========================================================

    selected_section = None

    if section_id is not None:

        selected_section = (
            Section.query
            .filter(

                Section.id ==
                section_id,

                Section.institution_id ==
                institution_id,

                Section.branch_id ==
                branch_id,
            )
            .first()
        )

        if not selected_section:

            return jsonify({

                "success":
                    False,

                "message":
                    "Invalid section.",

                "students":
                    [],

                "attendance_date":
                    attendance_date.isoformat(),

            }), 403

        # ====================================================
        # SECTION -> CLASS
        # ====================================================

        selected_section_class_id = getattr(
            selected_section,
            "class_id",
            None
        )

        if (
            selected_section_class_id is not None
            and
            selected_section_class_id != class_id
        ):

            return jsonify({

                "success":
                    False,

                "message":
                    (
                        "The selected section does not "
                        "belong to this class."
                    ),

                "students":
                    [],

                "attendance_date":
                    attendance_date.isoformat(),

            }), 403

        # ====================================================
        # TEACHER SECTION ACCESS
        # ====================================================

        if assignment_section_id is None:

            # ------------------------------------------------
            # The selected assignment is class-wide.
            #
            # A class-wide assignment itself grants access to
            # the selected section.
            #
            # However, if an exact section assignment exists
            # for the same subject, it has priority.
            # ------------------------------------------------

            exact_section_assignment = (
                TeacherSubject.query
                .filter(

                    TeacherSubject.teacher_id ==
                    teacher_id,

                    TeacherSubject.institution_id ==
                    institution_id,

                    TeacherSubject.branch_id ==
                    branch_id,

                    TeacherSubject.class_id ==
                    class_id,

                    TeacherSubject.subject_id ==
                    assignment.subject_id,

                    TeacherSubject.section_id ==
                    section_id,

                    TeacherSubject.status ==
                    "active",
                )
                .order_by(
                    TeacherSubject.id.asc()
                )
                .first()
            )

            # ------------------------------------------------
            # Exact section assignment exists.
            #
            # Browser must not use the class-wide assignment
            # for this subject/section.
            # ------------------------------------------------

            if exact_section_assignment:

                assignment = (
                    exact_section_assignment
                )

                assignment_section_id = (
                    assignment.section_id
                )

    # ========================================================
    # SUBJECT
    # ========================================================

    subject = getattr(
        assignment,
        "subject",
        None
    )

    if not subject:

        return jsonify({

            "success":
                False,

            "message":
                (
                    "This teacher assignment has "
                    "no valid subject."
                ),

            "students":
                [],

            "attendance_date":
                attendance_date.isoformat(),

        }), 400

    # ========================================================
    # PROGRAM
    #
    # Priority:
    #   1. TeacherSubject.program_id
    #   2. Subject.program_id
    # ========================================================

    program_id = getattr(
        assignment,
        "program_id",
        None
    )

    if not program_id:

        program_id = getattr(
            subject,
            "program_id",
            None
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    academic_year_id = getattr(
        assignment,
        "academic_year_id",
        None
    )

    if not academic_year_id:

        return jsonify({

            "success":
                False,

            "message":
                (
                    "This teacher assignment has "
                    "no academic year."
                ),

            "students":
                [],

            "attendance_date":
                attendance_date.isoformat(),

        }), 400

    # ========================================================
    # CHECK ALREADY SUBMITTED ATTENDANCE
    #
    # completed / locked = submitted
    #
    # open = editable
    #
    # cancelled = ignored
    #
    # IMPORTANT:
    # Do this BEFORE loading students.
    # ========================================================

    submitted_session = None

    session_query = (
        AttendanceSession.query
        .filter(

            AttendanceSession.institution_id ==
            institution_id,

            AttendanceSession.branch_id ==
            branch_id,

            AttendanceSession.teacher_id ==
            teacher_id,

            AttendanceSession.teacher_subject_id ==
            assignment.id,

            AttendanceSession.academic_year_id ==
            academic_year_id,

            AttendanceSession.class_id ==
            class_id,

            AttendanceSession.attendance_date ==
            attendance_date,

            AttendanceSession.status.in_([
                "completed",
                "locked",
            ]),
        )
    )

    # ========================================================
    # SECTION-SPECIFIC ASSIGNMENT
    # ========================================================

    if assignment.section_id is not None:

        if section_id is None:

            return jsonify({

                "success":
                    False,

                "already_submitted":
                    False,

                "message":
                    (
                        "A section is required for "
                        "this teacher assignment."
                    ),

                "students":
                    [],

                "attendance_date":
                    attendance_date.isoformat(),

            }), 400

        submitted_session = (
            session_query
            .filter(
                AttendanceSession.section_id ==
                section_id
            )
            .order_by(
                AttendanceSession.id.desc()
            )
            .first()
        )

    # ========================================================
    # CLASS-WIDE ASSIGNMENT
    #
    # Selected section:
    #     exact section session first
    #     then class-wide session
    # ========================================================

    elif section_id is not None:

        exact_session = (
            session_query
            .filter(
                AttendanceSession.section_id ==
                section_id
            )
            .order_by(
                AttendanceSession.id.desc()
            )
            .first()
        )

        if exact_session:

            submitted_session = (
                exact_session
            )

        else:

            submitted_session = (
                session_query
                .filter(
                    AttendanceSession.section_id.is_(None)
                )
                .order_by(
                    AttendanceSession.id.desc()
                )
                .first()
            )

    # ========================================================
    # NO SECTION
    #
    # Only class-wide attendance applies.
    # ========================================================

    else:

        submitted_session = (
            session_query
            .filter(
                AttendanceSession.section_id.is_(None)
            )
            .order_by(
                AttendanceSession.id.desc()
            )
            .first()
        )

    # ========================================================
    # ALREADY SUBMITTED RESPONSE
    #
    # Do NOT return students.
    #
    # Frontend receives explicit status and can show:
    #
    #     Attendance Already Submitted
    #
    # instead of trying to render empty students as if the
    # request simply failed.
    # ========================================================

    if submitted_session:

        return jsonify({

            "success":
                False,

            "already_submitted":
                True,

            "attendance_submitted":
                True,

            "message":
                (
                    "Attendance for this subject, "
                    "section and date has already "
                    "been submitted and cannot be edited."
                ),

            "class_id":
                class_id,

            "teacher_subject_id":
                teacher_subject_id,

            "teacher_id":
                teacher_id,

            "institution_id":
                institution_id,

            "branch_id":
                branch_id,

            "section_id":
                section_id,

            "assignment_section_id":
                assignment.section_id,

            "academic_year_id":
                academic_year_id,

            "program_id":
                program_id,

            "subject_id":
                getattr(
                    assignment,
                    "subject_id",
                    None
                ),

            "subject_name":
                getattr(
                    subject,
                    "name",
                    None
                ),

            "attendance_session_id":
                submitted_session.id,

            "attendance_status":
                submitted_session.status,

            "attendance_date":
                attendance_date.isoformat(),

            "students":
                [],

            "student_count":
                0,

            "can_edit":
                False,

            "today_only":
                True,

            "can_change_date":
                False,

        }), 409

    # ========================================================
    # STUDENT ENROLLMENTS
    #
    # ACTIVE ENROLLMENT IS THE SOURCE OF TRUTH.
    # ========================================================

    enrollment_query = (
        StudentEnrollment.query
        .join(
            Student,
            Student.id ==
            StudentEnrollment.student_id
        )
        .filter(

            StudentEnrollment.institution_id ==
            institution_id,

            StudentEnrollment.branch_id ==
            branch_id,

            StudentEnrollment.class_id ==
            class_id,

            StudentEnrollment.academic_year_id ==
            academic_year_id,

            StudentEnrollment.status ==
            "active",
        )
    )

    # ========================================================
    # SECTION FILTER
    # ========================================================

    if section_id is not None:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.section_id ==
                section_id
            )
        )

    # ========================================================
    # PROGRAM FILTER
    # ========================================================

    if program_id is not None:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.program_id ==
                program_id
            )
        )

    # ========================================================
    # LOAD ENROLLMENTS
    # ========================================================

    enrollments = (
        enrollment_query
        .order_by(

            Student.full_name.asc(),

            Student.id.asc(),

            StudentEnrollment.id.asc(),
        )
        .all()
    )

    # ========================================================
    # BUILD STUDENT RESPONSE
    # ========================================================

    students = []

    seen_enrollment_ids = set()

    seen_student_ids = set()

    for enrollment in enrollments:

        if not enrollment:
            continue

        enrollment_id = getattr(
            enrollment,
            "id",
            None
        )

        student = getattr(
            enrollment,
            "student",
            None
        )

        if not enrollment_id or not student:
            continue

        student_id = getattr(
            student,
            "id",
            None
        )

        if not student_id:
            continue

        # ====================================================
        # DUPLICATE ENROLLMENT
        # ====================================================

        if enrollment_id in seen_enrollment_ids:
            continue

        # ====================================================
        # DUPLICATE STUDENT
        # ====================================================

        if student_id in seen_student_ids:
            continue

        seen_enrollment_ids.add(
            enrollment_id
        )

        seen_student_ids.add(
            student_id
        )

        # ====================================================
        # STUDENT RESPONSE
        #
        # Admission No / Roll No intentionally omitted.
        # ====================================================

        students.append({

            "student_id":
                student_id,

            "enrollment_id":
                enrollment_id,

            "full_name":
                getattr(
                    student,
                    "full_name",
                    ""
                ),

            "photo":
                getattr(
                    student,
                    "photo",
                    None
                ),

            "section_id":
                getattr(
                    enrollment,
                    "section_id",
                    None
                ),

            "class_id":
                getattr(
                    enrollment,
                    "class_id",
                    None
                ),

            "program_id":
                getattr(
                    enrollment,
                    "program_id",
                    None
                ),

            "academic_year_id":
                getattr(
                    enrollment,
                    "academic_year_id",
                    None
                ),
        })

    # ========================================================
    # FINAL RESPONSE
    # ========================================================

    return jsonify({

        "success":
            True,

        "already_submitted":
            False,

        "attendance_submitted":
            False,

        "can_edit":
            True,

        "class_id":
            class_id,

        "teacher_subject_id":
            teacher_subject_id,

        "teacher_id":
            teacher_id,

        "institution_id":
            institution_id,

        "branch_id":
            branch_id,

        "section_id":
            section_id,

        "assignment_section_id":
            assignment_section_id,

        "academic_year_id":
            academic_year_id,

        "program_id":
            program_id,

        "subject_id":
            getattr(
                assignment,
                "subject_id",
                None
            ),

        "subject_name":
            getattr(
                subject,
                "name",
                None
            ),

        "attendance_date":
            attendance_date.isoformat(),

        "today_only":
            True,

        "can_change_date":
            False,

        "student_count":
            len(students),

        "students":
            students,
    })



# ============================================================
# RESULT / GRADE HELPERS
# ============================================================

from decimal import Decimal, ROUND_HALF_UP


def to_decimal(value, default=Decimal("0")):
    """
    Safely convert a value to Decimal.
    """

    if value is None:
        return default

    try:
        return Decimal(str(value))
    except (TypeError, ValueError):
        return default


def money_decimal(value):
    return to_decimal(value).quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP
    )


# ============================================================
# GRADE
# ============================================================

def calculate_grade(percentage):

    p = to_decimal(percentage)

    if p >= Decimal("95"):
        return "A+"

    elif p >= Decimal("90"):
        return "A"

    elif p >= Decimal("85"):
        return "A-"

    elif p >= Decimal("80"):
        return "B+"

    elif p >= Decimal("75"):
        return "B"

    elif p >= Decimal("70"):
        return "B-"

    elif p >= Decimal("65"):
        return "C+"

    elif p >= Decimal("60"):
        return "C"

    elif p >= Decimal("50"):
        return "C-"

    elif p >= Decimal("40"):
        return "D"

    elif p >= Decimal("20"):
        return "E"

    return "F"


# ============================================================
# GPA POINT
# ============================================================

# ============================================================
# GRADE POINTS
# ============================================================

GRADE_POINTS = {
    "A+": Decimal("4.00"),
    "A":  Decimal("4.00"),
    "A-": Decimal("3.70"),

    "B+": Decimal("3.30"),
    "B":  Decimal("3.00"),
    "B-": Decimal("2.70"),

    "C+": Decimal("2.30"),
    "C":  Decimal("2.00"),
    "C-": Decimal("1.70"),

    "D":  Decimal("1.00"),
    "E":  Decimal("0.50"),
    "F":  Decimal("0.00"),
}


# ============================================================
# GPA CALCULATION
# ============================================================

def calculate_gpa_from_subjects(subject_results):

    if not subject_results:
        return Decimal("0.00")

    total_quality_points = Decimal("0.00")
    total_credit_hours = Decimal("0.00")

    for item in subject_results:

        grade = str(
            item.get("grade") or ""
        ).strip().upper()

        if not grade:
            continue

        grade_point = GRADE_POINTS.get(grade)

        if grade_point is None:
            continue

        credit_hours = to_decimal(
            item.get("credit_hours"),
            Decimal("0.00")
        )

        if credit_hours <= Decimal("0.00"):
            raise ValueError(
                f"Credit hours are required for grade {grade}."
            )

        # Grade Point × Credit Hours
        total_quality_points += (
            grade_point * credit_hours
        )

        # Total Credits
        total_credit_hours += credit_hours

    if total_credit_hours <= Decimal("0.00"):
        return Decimal("0.00")

    # GPA = Total Quality Points / Total Credit Hours
    gpa = (
        total_quality_points /
        total_credit_hours
    )

    # Final result = 2 decimal places
    return gpa.quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP
    )





# ============================================================
# TEACHER ENTER MARKS
# ============================================================

@bp.route(
    "/teacher/exams/<int:exam_subject_id>/marks",
    methods=["GET", "POST"]
)
@teacher_login_required
def teacher_enter_marks(exam_subject_id):

    # ========================================================
    # CURRENT TEACHER
    # ========================================================

    teacher = getattr(g, "teacher", None)

    if not teacher:
        abort(403)

    institution_id = teacher.institution_id
    branch_id = teacher.branch_id

    if not institution_id or not branch_id:

        flash(
            "Your teacher account is not assigned to an institution and branch.",
            "danger"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # TEACHER ACCOUNT STATUS
    # ========================================================

    if (
        not getattr(teacher, "is_active", False)
        or str(
            getattr(teacher, "status", "") or ""
        ).lower().strip() != "active"
    ):

        flash(
            "Your teacher account is not active.",
            "danger"
        )

        abort(403)

    # ========================================================
    # GET EXAM SUBJECT
    # ========================================================

    exam_subject = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id,
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )
        .first()
    )

    if not exam_subject:
        abort(404)

    # ========================================================
    # EXAM
    # ========================================================

    exam = exam_subject.exam

    if not exam:
        abort(404)

    # ========================================================
    # EXAM SECURITY
    # ========================================================

    if exam.institution_id != institution_id:
        abort(403)

    if exam.branch_id != branch_id:
        abort(403)

    if not exam.program_id:

        flash(
            "This exam is not connected to a program.",
            "danger"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    if not exam.academic_year_id:

        flash(
            "This exam is not connected to an academic year.",
            "danger"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # EXAM STATUS
    # ========================================================
    #
    # DRAFT / OPEN / ACTIVE:
    #       Teacher may enter marks.
    #
    # CLOSED / CANCELLED:
    #       Teacher cannot enter marks.
    #
    # ========================================================

    exam_status = str(
        getattr(exam, "status", "") or ""
    ).lower().strip()

    if exam_status in {
        "cancelled",
        "closed"
    }:

        flash(
            "This examination is closed.",
            "danger"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # EXAM SUBJECT STATUS
    # ========================================================

    exam_subject_status = str(
        getattr(exam_subject, "status", "") or ""
    ).lower().strip()

    if exam_subject_status != "active":

        flash(
            "This examination subject is not active.",
            "danger"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    subject = exam_subject.subject

    if not subject:

        flash(
            "This exam subject is not connected to a subject.",
            "danger"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # SUBJECT SECURITY
    # ========================================================

    if subject.institution_id != institution_id:
        abort(403)

    if (
        getattr(subject, "branch_id", None) is not None
        and subject.branch_id != branch_id
    ):
        abort(403)

    subject_status = str(
        getattr(subject, "status", "active") or ""
    ).lower().strip()

    if subject_status != "active":

        flash(
            "This subject is not active.",
            "danger"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    program_id = exam.program_id

    program = (
        Program.query
        .filter(
            Program.id == program_id,
            Program.institution_id == institution_id,
            db.or_(
                Program.branch_id == branch_id,
                Program.branch_id.is_(None)
            )
        )
        .first()
    )

    if not program:
        abort(404)

    # ========================================================
    # SUBJECT PROGRAM SECURITY
    # ========================================================

    subject_program_id = getattr(
        subject,
        "program_id",
        None
    )

    if (
        subject_program_id is not None
        and subject_program_id != program_id
    ):
        abort(403)

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    academic_year_id = exam.academic_year_id

    # ========================================================
    # CLASS
    # ========================================================

    class_id = exam_subject.class_id

    selected_class = None

    if class_id:

        selected_class = (
            Class.query
            .filter(
                Class.id == class_id,
                Class.institution_id == institution_id,
                Class.branch_id == branch_id,
                Class.program_id == program_id,
                Class.academic_year_id == academic_year_id
            )
            .first()
        )

        if not selected_class:
            abort(404)

    # ========================================================
    # SECTION
    # ========================================================

    section_id = exam_subject.section_id

    selected_section = None

    if section_id:

        if not class_id:
            abort(404)

        selected_section = (
            Section.query
            .filter(
                Section.id == section_id,
                Section.institution_id == institution_id,
                Section.branch_id == branch_id,
                Section.class_id == class_id,
                Section.academic_year_id == academic_year_id
            )
            .first()
        )

        if not selected_section:
            abort(404)

    # ========================================================
    # TEACHER AUTHORIZATION
    # ========================================================
    #
    # Teacher must have an active assignment for:
    #
    # teacher + institution + program + subject
    #
    # Branch can be:
    #
    #   current branch
    #   OR global branch NULL
    #
    # ========================================================

    teacher_assignment = (
        TeacherSubject.query
        .filter(
            TeacherSubject.teacher_id == teacher.id,
            TeacherSubject.institution_id == institution_id,
            TeacherSubject.program_id == program_id,
            TeacherSubject.subject_id == subject.id,
            TeacherSubject.status == "active"
        )
        .filter(
            db.or_(
                TeacherSubject.branch_id == branch_id,
                TeacherSubject.branch_id.is_(None)
            )
        )
        .order_by(
            TeacherSubject.id.desc()
        )
        .first()
    )

    # ========================================================
    # FINAL TEACHER AUTHORIZATION
    # ========================================================

    if not teacher_assignment:

        current_app.logger.warning(
            "TEACHER MARK ACCESS DENIED | "
            "teacher_id=%s | "
            "exam_subject_id=%s | "
            "exam_id=%s | "
            "subject_id=%s | "
            "program_id=%s | "
            "class_id=%s | "
            "section_id=%s | "
            "academic_year_id=%s | "
            "exam_subject_teacher_id=%s",
            teacher.id,
            exam_subject.id,
            exam.id,
            subject.id,
            program_id,
            class_id,
            section_id,
            academic_year_id,
            exam_subject.teacher_id
        )

        flash(
            "You are not assigned to teach this subject in this program.",
            "danger"
        )

        abort(403)

    # ========================================================
    # EXTRA ASSIGNMENT SAFETY
    # ========================================================

    if teacher_assignment.teacher_id != teacher.id:
        abort(403)

    if teacher_assignment.institution_id != institution_id:
        abort(403)

    if teacher_assignment.program_id != program_id:
        abort(403)

    if teacher_assignment.subject_id != subject.id:
        abort(403)

    assignment_branch_id = getattr(
        teacher_assignment,
        "branch_id",
        None
    )

    if (
        assignment_branch_id is not None
        and assignment_branch_id != branch_id
    ):
        abort(403)

    # ========================================================
    # EXAM SUBJECT TEACHER CONSISTENCY
    # ========================================================

    if (
        exam_subject.teacher_id is not None
        and exam_subject.teacher_id != teacher.id
    ):

        current_app.logger.warning(
            "EXAM SUBJECT TEACHER MISMATCH | "
            "teacher_id=%s | "
            "exam_subject_id=%s | "
            "assigned_teacher_id=%s",
            teacher.id,
            exam_subject.id,
            exam_subject.teacher_id
        )

        flash(
            "This examination subject is assigned to another teacher.",
            "danger"
        )

        abort(403)

    # ========================================================
    # MAX MARKS
    # ========================================================

    max_marks = to_decimal(
        exam_subject.max_marks
    )

    if max_marks <= 0:

        subject_max_marks = getattr(
            subject,
            "max_marks",
            None
        )

        max_marks = (
            to_decimal(subject_max_marks)
            if subject_max_marks is not None
            else Decimal("100")
        )

    # ========================================================
    # PASS MARKS
    # ========================================================

    pass_marks = to_decimal(
        exam_subject.pass_marks
    )

    if pass_marks <= 0:

        subject_pass_marks = getattr(
            subject,
            "pass_marks",
            None
        )

        pass_marks = (
            to_decimal(subject_pass_marks)
            if subject_pass_marks is not None
            else Decimal("50")
        )

    # ========================================================
    # STUDENTS / ENROLLMENTS
    # ========================================================

    enrollment_query = (
        StudentEnrollment.query
        .join(
            Student,
            Student.id == StudentEnrollment.student_id
        )
        .filter(
            StudentEnrollment.institution_id == institution_id,
            Student.institution_id == institution_id,

            StudentEnrollment.branch_id == branch_id,
            Student.branch_id == branch_id,

            StudentEnrollment.academic_year_id
            == academic_year_id,

            StudentEnrollment.program_id
            == program_id
        )
    )

    # ========================================================
    # CLASS FILTER
    # ========================================================

    if class_id:

        enrollment_query = enrollment_query.filter(
            StudentEnrollment.class_id == class_id
        )

    # ========================================================
    # SECTION FILTER
    # ========================================================

    if section_id:

        enrollment_query = enrollment_query.filter(
            StudentEnrollment.section_id == section_id
        )

    # ========================================================
    # ACTIVE ENROLLMENT
    # ========================================================

    if hasattr(StudentEnrollment, "status"):

        enrollment_query = enrollment_query.filter(
            StudentEnrollment.status == "active"
        )

    # ========================================================
    # ACTIVE STUDENT
    # ========================================================

    if hasattr(Student, "status"):

        enrollment_query = enrollment_query.filter(
            Student.status == "active"
        )

    # ========================================================
    # LOAD STUDENTS
    # ========================================================

    students = (
        enrollment_query
        .order_by(
            Student.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # STUDENT IDS
    # ========================================================

    student_ids = [
        enrollment.student_id
        for enrollment in students
    ]

    # ========================================================
    # EXISTING MARKS
    # ========================================================

    existing_marks = {}

    if student_ids:

        marks = (
            Mark.query
            .filter(
                Mark.exam_subject_id == exam_subject.id,
                Mark.student_id.in_(student_ids)
            )
            .all()
        )

        existing_marks = {
            mark.student_id: mark
            for mark in marks
        }

    # ========================================================
    # SUBMISSION STATUS
    # ========================================================

    total_student_count = len(student_ids)

    submitted_count = sum(
        1
        for student_id in student_ids
        if (
            existing_marks.get(student_id)
            and str(
                getattr(
                    existing_marks[student_id],
                    "status",
                    ""
                ) or ""
            ).lower().strip() == "submitted"
        )
    )

    marks_locked = (
        total_student_count > 0
        and submitted_count == total_student_count
    )

    submission_status = (
        "submitted"
        if marks_locked
        else "pending"
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        processed_student_ids = set()

        skipped_submitted_ids = set()

        try:

            # ====================================================
            # RE-CHECK TEACHER AUTHORIZATION
            # ====================================================

            if not teacher_assignment:
                abort(403)

            if teacher_assignment.teacher_id != teacher.id:
                abort(403)

            if teacher_assignment.institution_id != institution_id:
                abort(403)

            if teacher_assignment.program_id != program_id:
                abort(403)

            if teacher_assignment.subject_id != subject.id:
                abort(403)

            assignment_branch_id = getattr(
                teacher_assignment,
                "branch_id",
                None
            )

            if (
                assignment_branch_id is not None
                and assignment_branch_id != branch_id
            ):
                abort(403)

            # ====================================================
            # RE-CHECK EXAM SUBJECT TEACHER
            # ====================================================

            if (
                exam_subject.teacher_id is not None
                and exam_subject.teacher_id != teacher.id
            ):
                abort(403)

            # ====================================================
            # RELOAD CURRENT MARKS
            # ====================================================
            #
            # IMPORTANT:
            #
            # We reload marks inside POST because another request
            # could have submitted a mark after the GET request.
            #
            # ====================================================

            current_marks = (
                Mark.query
                .filter(
                    Mark.exam_subject_id == exam_subject.id,
                    Mark.student_id.in_(student_ids)
                )
                .all()
                if student_ids
                else []
            )

            current_marks_map = {
                mark.student_id: mark
                for mark in current_marks
            }

            # ====================================================
            # CHECK IF EVERYTHING IS ALREADY SUBMITTED
            # ====================================================

            current_submitted_count = sum(
                1
                for student_id in student_ids
                if (
                    current_marks_map.get(student_id)
                    and str(
                        getattr(
                            current_marks_map[student_id],
                            "status",
                            ""
                        ) or ""
                    ).lower().strip() == "submitted"
                )
            )

            current_total_count = len(student_ids)

            if (
                current_total_count > 0
                and current_submitted_count == current_total_count
            ):

                flash(
                    "Marks for this examination subject have already been submitted.",
                    "warning"
                )

                return redirect(
                    url_for(
                        "main.teacher_enter_marks",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ====================================================
            # PROCESS STUDENTS
            # ====================================================

            for enrollment in students:

                student_id = enrollment.student_id

                # ------------------------------------------------
                # EXISTING MARK
                # ------------------------------------------------

                mark = current_marks_map.get(
                    student_id
                )

                # ------------------------------------------------
                # IMPORTANT:
                #
                # If this student was already submitted,
                # DO NOT TOUCH THE RECORD.
                #
                # DO NOT raise ValueError.
                #
                # Simply skip this student and continue with
                # the remaining students.
                # ------------------------------------------------

                if mark is not None:

                    existing_status = str(
                        getattr(
                            mark,
                            "status",
                            ""
                        ) or ""
                    ).lower().strip()

                    if existing_status == "submitted":

                        skipped_submitted_ids.add(
                            student_id
                        )

                        continue

                # ------------------------------------------------
                # MARK
                # ------------------------------------------------

                if mark is None:

                    mark = Mark(
                        exam_subject_id=exam_subject.id,
                        student_id=student_id
                    )

                    db.session.add(mark)

                    current_marks_map[
                        student_id
                    ] = mark

                # ------------------------------------------------
                # RAW MARK
                # ------------------------------------------------

                raw_mark = request.form.get(
                    f"marks_{student_id}",
                    ""
                ).strip()

                # ------------------------------------------------
                # ABSENT
                # ------------------------------------------------

                absent = (
                    request.form.get(
                        f"absent_{student_id}"
                    ) == "1"
                )

                # ------------------------------------------------
                # EXEMPTED
                # ------------------------------------------------

                exempted = (
                    request.form.get(
                        f"exempted_{student_id}"
                    ) == "1"
                )

                # ------------------------------------------------
                # REMARKS
                # ------------------------------------------------

                remarks = request.form.get(
                    f"remarks_{student_id}",
                    ""
                ).strip()

                # ------------------------------------------------
                # FLAGS
                # ------------------------------------------------

                mark.is_absent = absent

                mark.is_exempted = exempted

                mark.remarks = (
                    remarks
                    if remarks
                    else None
                )

                mark.entered_by = teacher.id

                # ------------------------------------------------
                # MARK VALUE
                # ------------------------------------------------

                if absent or exempted:

                    mark.marks_obtained = None

                else:

                    if not raw_mark:

                        raise ValueError(
                            f"Please enter marks for "
                            f"{enrollment.student.full_name}."
                        )

                    try:

                        obtained = Decimal(
                            raw_mark
                        )

                    except (
                        InvalidOperation,
                        ValueError,
                        TypeError
                    ):

                        raise ValueError(
                            f"Invalid mark for "
                            f"{enrollment.student.full_name}."
                        )

                    # --------------------------------------------
                    # NEGATIVE
                    # --------------------------------------------

                    if obtained < 0:

                        raise ValueError(
                            f"Marks cannot be negative for "
                            f"{enrollment.student.full_name}."
                        )

                    # --------------------------------------------
                    # MAXIMUM
                    # --------------------------------------------

                    if obtained > max_marks:

                        raise ValueError(
                            f"{enrollment.student.full_name} "
                            f"cannot receive more than "
                            f"{max_marks}."
                        )

                    # --------------------------------------------
                    # SAVE MARK
                    # --------------------------------------------

                    mark.marks_obtained = (
                        obtained.quantize(
                            Decimal("0.01"),
                            rounding=ROUND_HALF_UP
                        )
                    )

                # ------------------------------------------------
                # SUBMIT
                # ------------------------------------------------

                mark.status = "submitted"

                mark.submitted_at = (
                    datetime.now(timezone.utc)
                )

                processed_student_ids.add(
                    student_id
                )

            # ====================================================
            # NOTHING NEW TO SAVE
            # ====================================================

            if not processed_student_ids:

                db.session.rollback()

                flash(
                    "All available student marks have already been submitted.",
                    "warning"
                )

                return redirect(
                    url_for(
                        "main.teacher_enter_marks",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ====================================================
            # FLUSH
            # ====================================================

            db.session.flush()

            # ====================================================
            # CALCULATE RESULTS
            # ====================================================
            #
            # Only students whose marks were processed in this
            # submission are recalculated here.
            #
            # Already-submitted students remain untouched.
            #
            # ====================================================

            for student_id in processed_student_ids:

                calculate_student_result(
                    exam=exam,
                    student_id=student_id,
                    institution_id=institution_id,
                    branch_id=branch_id
                )

            # ====================================================
            # COMMIT MARKS + RESULTS
            # ====================================================

            db.session.commit()

            # ====================================================
            # CALCULATE RANKINGS
            # ====================================================

            calculate_exam_rankings(
                exam_id=exam.id,
                institution_id=institution_id,
                branch_id=branch_id
            )

            db.session.commit()

            # ====================================================
            # SUCCESS MESSAGE
            # ====================================================

            if skipped_submitted_ids:

                flash(
                    "Student marks were successfully saved. "
                    "Previously submitted student marks were left unchanged.",
                    "success"
                )

            else:

                flash(
                    "Student marks were successfully saved and submitted.",
                    "success"
                )

            return redirect(
                url_for(
                    "main.teacher_enter_marks",
                    exam_subject_id=exam_subject.id
                )
            )

        # ========================================================
        # VALIDATION ERROR
        # ========================================================

        except ValueError as exc:

            db.session.rollback()

            flash(
                str(exc),
                "danger"
            )

        # ========================================================
        # UNEXPECTED ERROR
        # ========================================================

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Teacher mark submission failed."
            )

            flash(
                "Unable to save marks. Please check the data and try again.",
                "danger"
            )

        # ========================================================
        # RELOAD MARKS AFTER ROLLBACK
        # ========================================================

        existing_marks = {}

        if student_ids:

            marks = (
                Mark.query
                .filter(
                    Mark.exam_subject_id == exam_subject.id,
                    Mark.student_id.in_(student_ids)
                )
                .all()
            )

            existing_marks = {
                mark.student_id: mark
                for mark in marks
            }

    # ========================================================
    # RE-CALCULATE SUBMISSION STATUS
    # ========================================================

    total_student_count = len(student_ids)

    submitted_count = sum(
        1
        for student_id in student_ids
        if (
            existing_marks.get(student_id)
            and str(
                getattr(
                    existing_marks[student_id],
                    "status",
                    ""
                ) or ""
            ).lower().strip() == "submitted"
        )
    )

    marks_locked = (
        total_student_count > 0
        and submitted_count == total_student_count
    )

    submission_status = (
        "submitted"
        if marks_locked
        else "pending"
    )

    # ========================================================
    # PREPARE STUDENT ROWS
    # ========================================================

    student_rows = []

    for enrollment in students:

        student = enrollment.student

        mark = existing_marks.get(
            student.id
        )

        student_rows.append({

            "student": student,

            "enrollment": enrollment,

            "mark": mark,

            "marks_obtained": (
                mark.marks_obtained
                if mark
                else None
            ),

            "is_absent": (
                mark.is_absent
                if mark
                else False
            ),

            "is_exempted": (
                mark.is_exempted
                if mark
                else False
            ),

            "remarks": (
                mark.remarks
                if mark
                else ""
            ),

            "status": (
                mark.status
                if mark
                else "draft"
            )
        })

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/teacher/pages/add_exam_marks.html",

        teacher=teacher,

        exam=exam,

        exam_subject=exam_subject,

        subject=subject,

        program=program,

        selected_class=selected_class,

        selected_section=selected_section,

        students=student_rows,

        max_marks=max_marks,

        pass_marks=pass_marks,

        student_count=len(student_rows),

        # ----------------------------------------------------
        # SUBMISSION STATE
        # ----------------------------------------------------

        submitted_count=submitted_count,

        total_student_count=total_student_count,

        marks_locked=marks_locked,

        submission_status=submission_status
    )


# ============================================================
# GET STUDENT EXAM SUBJECTS
# ============================================================

def get_student_exam_subjects(
    exam,
    enrollment
):

    # ========================================================
    # BASIC VALUES
    # ========================================================

    student_class_id = getattr(
        enrollment,
        "class_id",
        None
    )

    student_section_id = getattr(
        enrollment,
        "section_id",
        None
    )

    student_program_id = getattr(
        enrollment,
        "program_id",
        None
    )

    institution_id = getattr(
        enrollment,
        "institution_id",
        None
    )

    branch_id = getattr(
        enrollment,
        "branch_id",
        None
    )

    # ========================================================
    # CLASS IS REQUIRED
    # ========================================================

    if not student_class_id:

        current_app.logger.warning(
            "Student enrollment has no class_id. "
            "Cannot safely calculate exam subjects. "
            "student_id=%s exam_id=%s",
            getattr(enrollment, "student_id", None),
            getattr(exam, "id", None)
        )

        return []

    # ========================================================
    # SAFETY:
    # ExamSubject MUST HAVE class_id
    # ========================================================

    if "class_id" not in ExamSubject.__table__.columns:

        current_app.logger.error(
            "ExamSubject.class_id does not exist. "
            "Class-level subject scoping cannot be enforced."
        )

        return []

    # ========================================================
    # SAFETY:
    # If ExamSubject has program_id, program must be known.
    # ========================================================

    if (
        "program_id" in ExamSubject.__table__.columns
        and not student_program_id
    ):

        current_app.logger.warning(
            "Student enrollment has no program_id. "
            "Cannot safely scope ExamSubjects by program. "
            "student_id=%s exam_id=%s",
            getattr(enrollment, "student_id", None),
            getattr(exam, "id", None)
        )

        return []

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = (
        ExamSubject.query
        .filter(
            ExamSubject.exam_id == exam.id,

            # ------------------------------------------------
            # CRITICAL CLASS FILTER
            # ------------------------------------------------
            ExamSubject.class_id == student_class_id
        )
    )

    # ========================================================
    # INSTITUTION SCOPE
    # ========================================================

    if (
        "institution_id"
        in ExamSubject.__table__.columns
        and institution_id is not None
    ):

        query = query.filter(
            ExamSubject.institution_id == institution_id
        )

    # ========================================================
    # BRANCH SCOPE
    # ========================================================

    if (
        "branch_id"
        in ExamSubject.__table__.columns
        and branch_id is not None
    ):

        query = query.filter(
            ExamSubject.branch_id == branch_id
        )

    # ========================================================
    # PROGRAM SCOPE
    # ========================================================

    if (
        "program_id"
        in ExamSubject.__table__.columns
        and student_program_id is not None
    ):

        query = query.filter(
            ExamSubject.program_id == student_program_id
        )

    # ========================================================
    # LOAD CANDIDATES
    # ========================================================

    candidates = (
        query
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # DEBUG LOG
    # ========================================================

    current_app.logger.info(
        "ExamSubject candidates | "
        "exam=%s student=%s institution=%s branch=%s "
        "program=%s class=%s section=%s count=%s",
        getattr(exam, "id", None),
        getattr(enrollment, "student_id", None),
        institution_id,
        branch_id,
        student_program_id,
        student_class_id,
        student_section_id,
        len(candidates)
    )

    # ========================================================
    # CANONICAL SUBJECT MAP
    #
    # KEY:
    #   subject_id
    #
    # VALUE:
    #   {
    #       "priority": ...,
    #       "exam_subject": ...
    #   }
    # ========================================================

    selected = {}

    for exam_subject in candidates:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )

        if not subject_id:
            continue

        # ====================================================
        # SECTION
        # ====================================================

        exam_subject_section_id = getattr(
            exam_subject,
            "section_id",
            None
        )

        # ====================================================
        # STUDENT HAS NO SECTION
        #
        # Only class-level assignments are valid.
        # ====================================================

        if student_section_id is None:

            if exam_subject_section_id is not None:
                continue

            priority = 1

        # ====================================================
        # STUDENT HAS SECTION
        # ====================================================

        else:

            # ------------------------------------------------
            # SECTION DOES NOT MATCH
            # ------------------------------------------------

            if exam_subject_section_id not in (
                None,
                student_section_id
            ):
                continue

            # ------------------------------------------------
            # SECTION-SPECIFIC = HIGHER PRIORITY
            # ------------------------------------------------

            if (
                exam_subject_section_id
                == student_section_id
            ):

                priority = 2

            else:

                # Class-level fallback
                priority = 1

        # ====================================================
        # SELECT CANONICAL ASSIGNMENT
        # ====================================================

        current = selected.get(
            subject_id
        )

        if current is None:

            selected[subject_id] = {
                "priority": priority,
                "exam_subject": exam_subject
            }

            continue

        current_priority = current["priority"]

        current_exam_subject = current[
            "exam_subject"
        ]

        # ----------------------------------------------------
        # HIGHER PRIORITY WINS
        # ----------------------------------------------------

        if priority > current_priority:

            selected[subject_id] = {
                "priority": priority,
                "exam_subject": exam_subject
            }

            continue

        # ----------------------------------------------------
        # SAME PRIORITY
        #
        # Use the lowest ExamSubject ID as canonical row.
        # ----------------------------------------------------

        if (
            priority == current_priority
            and exam_subject.id
            < current_exam_subject.id
        ):

            selected[subject_id] = {
                "priority": priority,
                "exam_subject": exam_subject
            }

    # ========================================================
    # FINAL SUBJECT LIST
    # ========================================================

    exam_subjects = [
        item["exam_subject"]
        for item in selected.values()
    ]

    # ========================================================
    # STABLE DISPLAY ORDER
    # ========================================================

    exam_subjects.sort(
        key=lambda item: (
            getattr(
                item,
                "display_order",
                None
            ) or 999999,
            item.id
        )
    )

    # ========================================================
    # DEBUG SELECTED
    # ========================================================

    current_app.logger.info(
        "ExamSubject selected | "
        "exam=%s student=%s class=%s section=%s "
        "selected_ids=%s subject_ids=%s",
        getattr(exam, "id", None),
        getattr(enrollment, "student_id", None),
        student_class_id,
        student_section_id,
        [
            item.id
            for item in exam_subjects
        ],
        [
            item.subject_id
            for item in exam_subjects
        ]
    )

    return exam_subjects


# ============================================================
# CALCULATE STUDENT RESULT
# ============================================================

def calculate_student_result(
    exam,
    student_id,
    institution_id,
    branch_id
):

    # ========================================================
    # VALIDATE EXAM
    # ========================================================

    if not exam:

        current_app.logger.warning(
            "Cannot calculate result: exam is None | "
            "student=%s institution=%s branch=%s",
            student_id,
            institution_id,
            branch_id
        )

        return None

    # ========================================================
    # GET ACTIVE ENROLLMENT FOR THIS EXAM
    # ========================================================

    enrollment = (
        StudentEnrollment.query
        .filter(
            StudentEnrollment.student_id == student_id,

            StudentEnrollment.institution_id
            == institution_id,

            StudentEnrollment.branch_id
            == branch_id,

            StudentEnrollment.academic_year_id
            == exam.academic_year_id,

            StudentEnrollment.status == "active"
        )
        .order_by(
            StudentEnrollment.id.desc()
        )
        .first()
    )

    if not enrollment:

        current_app.logger.warning(
            "No active enrollment found | "
            "student=%s exam=%s institution=%s branch=%s",
            student_id,
            exam.id,
            institution_id,
            branch_id
        )

        return None

    # ========================================================
    # GET ONLY THE STUDENT'S VALID EXAM SUBJECTS
    #
    # This helper must already implement:
    #
    # - institution scope
    # - branch scope
    # - program scope
    # - class scope
    # - section scope
    # - section-specific priority over class-level
    # - duplicate subject protection
    # ========================================================

    exam_subjects = get_student_exam_subjects(
        exam=exam,
        enrollment=enrollment
    )

    if not exam_subjects:

        current_app.logger.warning(
            "No scoped ExamSubjects found | "
            "student=%s exam=%s class=%s section=%s",
            student_id,
            exam.id,
            getattr(
                enrollment,
                "class_id",
                None
            ),
            getattr(
                enrollment,
                "section_id",
                None
            )
        )

        return None

    # ========================================================
    # REMOVE DUPLICATE SUBJECTS SAFELY
    #
    # One subject must be counted only once.
    #
    # get_student_exam_subjects() should already handle the
    # section-specific-over-class-level rule.
    #
    # This extra protection prevents accidental double counting.
    # ========================================================

    unique_exam_subjects = []

    seen_subject_ids = set()

    for exam_subject in exam_subjects:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )

        if subject_id is None:

            current_app.logger.warning(
                "ExamSubject has no subject_id | "
                "exam_subject=%s exam=%s",
                getattr(
                    exam_subject,
                    "id",
                    None
                ),
                exam.id
            )

            continue

        if subject_id in seen_subject_ids:

            current_app.logger.error(
                "Duplicate ExamSubject subject detected | "
                "exam=%s student=%s subject=%s "
                "exam_subject=%s",
                exam.id,
                student_id,
                subject_id,
                getattr(
                    exam_subject,
                    "id",
                    None
                )
            )

            continue

        seen_subject_ids.add(
            subject_id
        )

        unique_exam_subjects.append(
            exam_subject
        )

    # ========================================================
    # IF ALL EXAM SUBJECTS WERE INVALID
    # ========================================================

    if not unique_exam_subjects:

        current_app.logger.warning(
            "No valid unique ExamSubjects remain | "
            "student=%s exam=%s",
            student_id,
            exam.id
        )

        return None

    # ========================================================
    # GET EXAM SUBJECT IDS
    # ========================================================

    exam_subject_ids = [
        item.id
        for item in unique_exam_subjects
    ]

    # ========================================================
    # GET STUDENT MARKS
    # ========================================================

    marks = (
        Mark.query
        .filter(
            Mark.student_id == student_id,

            Mark.exam_subject_id.in_(
                exam_subject_ids
            )
        )
        .order_by(
            Mark.id.asc()
        )
        .all()
    )

    # ========================================================
    # BUILD MARK MAP
    #
    # If duplicate Mark rows somehow exist, keep the first
    # canonical row.
    # ========================================================

    marks_by_exam_subject = {}

    for mark in marks:

        exam_subject_id = (
            mark.exam_subject_id
        )

        if exam_subject_id in (
            marks_by_exam_subject
        ):

            current_app.logger.error(
                "Duplicate Mark detected | "
                "student=%s exam=%s "
                "exam_subject=%s "
                "existing_mark=%s "
                "duplicate_mark=%s",
                student_id,
                exam.id,
                exam_subject_id,
                marks_by_exam_subject[
                    exam_subject_id
                ].id,
                mark.id
            )

            continue

        marks_by_exam_subject[
            exam_subject_id
        ] = mark

    # ========================================================
    # CALCULATION VARIABLES
    # ========================================================

    total_marks = Decimal(
        "0.00"
    )

    total_possible = Decimal(
        "0.00"
    )

    # Number of subjects with an actual numeric mark.
    completed = 0

    # Number of subjects whose calculated percentage is < 50.
    failed = 0

    subject_results = []

    PASS_MARK = Decimal(
        "50.00"
    )

    # ========================================================
    # LOOP THROUGH ALL ASSIGNED SUBJECTS
    # ========================================================

    for exam_subject in unique_exam_subjects:

        # ====================================================
        # GET SUBJECT
        # ====================================================

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        if subject is None:

            current_app.logger.warning(
                "ExamSubject %s has no Subject | "
                "exam=%s student=%s",
                getattr(
                    exam_subject,
                    "id",
                    None
                ),
                exam.id,
                student_id
            )

            # No valid subject means it cannot safely be
            # included in calculation.
            continue

        # ====================================================
        # GET MAX MARKS
        # ====================================================

        max_marks = to_decimal(
            getattr(
                exam_subject,
                "max_marks",
                None
            )
        )

        if max_marks <= Decimal(
            "0.00"
        ):

            max_marks = to_decimal(
                getattr(
                    subject,
                    "max_marks",
                    100
                )
            )

        if max_marks <= Decimal(
            "0.00"
        ):

            max_marks = Decimal(
                "100.00"
            )

        # ====================================================
        # ALL ASSIGNED SUBJECTS ENTER DENOMINATOR
        #
        # IMPORTANT:
        # Even if there is NO Mark row, this subject still
        # contributes its max_marks.
        #
        # Example:
        #
        # 5 subjects × 100
        # total_possible = 500
        #
        # ====================================================

        total_possible += max_marks

        # ====================================================
        # GET MARK
        # ====================================================

        mark = marks_by_exam_subject.get(
            exam_subject.id
        )

        # ====================================================
        # DEFAULT:
        #
        # Missing = ZERO
        # ====================================================

        obtained = Decimal(
            "0.00"
        )

        has_numeric_mark = False

        # ====================================================
        # NO MARK ROW
        #
        # Missing subject = ZERO
        # ====================================================

        if mark is None:

            obtained = Decimal(
                "0.00"
            )

            current_app.logger.info(
                "Missing mark treated as ZERO | "
                "student=%s exam=%s "
                "exam_subject=%s subject=%s",
                student_id,
                exam.id,
                exam_subject.id,
                getattr(
                    subject,
                    "id",
                    None
                )
            )

        # ====================================================
        # ABSENT
        #
        # Absent = ZERO
        # ====================================================

        elif getattr(
            mark,
            "is_absent",
            False
        ):

            obtained = Decimal(
                "0.00"
            )

            current_app.logger.info(
                "Absent mark treated as ZERO | "
                "student=%s exam=%s "
                "exam_subject=%s mark=%s",
                student_id,
                exam.id,
                exam_subject.id,
                mark.id
            )

        # ====================================================
        # EXEMPTED
        #
        # Exempted = ZERO
        # ====================================================

        elif getattr(
            mark,
            "is_exempted",
            False
        ):

            obtained = Decimal(
                "0.00"
            )

            current_app.logger.info(
                "Exempted mark treated as ZERO | "
                "student=%s exam=%s "
                "exam_subject=%s mark=%s",
                student_id,
                exam.id,
                exam_subject.id,
                mark.id
            )

        # ====================================================
        # NULL MARK
        #
        # NULL = ZERO
        # ====================================================

        elif mark.marks_obtained is None:

            obtained = Decimal(
                "0.00"
            )

            current_app.logger.info(
                "NULL mark treated as ZERO | "
                "student=%s exam=%s "
                "exam_subject=%s mark=%s",
                student_id,
                exam.id,
                exam_subject.id,
                mark.id
            )

        # ====================================================
        # NUMERIC MARK
        # ====================================================

        else:

            obtained = to_decimal(
                mark.marks_obtained
            )

            has_numeric_mark = True

            # ----------------------------------------------
            # NEGATIVE SAFETY
            # ----------------------------------------------

            if obtained < Decimal(
                "0.00"
            ):

                obtained = Decimal(
                    "0.00"
                )

            # ----------------------------------------------
            # MAX MARK SAFETY
            # ----------------------------------------------

            if obtained > max_marks:

                obtained = max_marks

            # ----------------------------------------------
            # ACTUAL ENTERED MARK
            # ----------------------------------------------

            completed += 1

        # ====================================================
        # ADD OBTAINED MARK
        # ====================================================

        total_marks += obtained

        # ====================================================
        # SUBJECT PERCENTAGE
        # ====================================================

        if max_marks > Decimal(
            "0.00"
        ):

            subject_percentage = (
                obtained / max_marks
            ) * Decimal(
                "100.00"
            )

        else:

            subject_percentage = Decimal(
                "0.00"
            )

        subject_percentage = (
            subject_percentage.quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP
            )
        )

        # ====================================================
        # SUBJECT GRADE
        # ====================================================

        subject_grade = calculate_grade(
            subject_percentage
        )

        # ====================================================
        # SUBJECT PASS / FAIL
        #
        # Missing = 0%
        # Absent = 0%
        # Exempted = 0%
        #
        # Therefore all are FAIL when max_marks > 0.
        # ====================================================

        if subject_percentage < PASS_MARK:

            failed += 1

        # ====================================================
        # CREDIT HOURS
        # ====================================================

        credit_hours = getattr(
            subject,
            "credit_hours",
            None
        )

        # ====================================================
        # GPA INPUT
        #
        # Every assigned subject is included.
        # ====================================================

        subject_results.append({
            "grade": subject_grade,
            "credit_hours": credit_hours
        })

        # ====================================================
        # SUBJECT LOG
        # ====================================================

        current_app.logger.debug(
            "Subject result | "
            "student=%s exam=%s "
            "subject=%s exam_subject=%s "
            "mark=%s obtained=%s max=%s "
            "percentage=%s grade=%s "
            "numeric=%s",
            student_id,
            exam.id,
            getattr(
                subject,
                "id",
                None
            ),
            exam_subject.id,
            getattr(
                mark,
                "id",
                None
            ),
            obtained,
            max_marks,
            subject_percentage,
            subject_grade,
            has_numeric_mark
        )

    # ========================================================
    # TOTAL SUBJECTS
    # ========================================================

    subjects_total = len(
        unique_exam_subjects
    )

    # ========================================================
    # SAFETY
    #
    # If some ExamSubjects had no valid Subject relationship
    # and were skipped above, use actual calculated subjects.
    # ========================================================

    if len(subject_results) != subjects_total:

        subjects_total = len(
            subject_results
        )

    # ========================================================
    # OVERALL PERCENTAGE
    #
    # ALL ASSIGNED SUBJECTS are included.
    #
    # Example:
    #
    # Math    80
    # English 70
    # Somali  60
    # Biology 0   <-- missing
    # Physics 0   <-- missing
    #
    # total = 210
    # possible = 500
    # percentage = 42%
    #
    # ========================================================

    if total_possible > Decimal(
        "0.00"
    ):

        percentage = (
            total_marks / total_possible
        ) * Decimal(
            "100.00"
        )

    else:

        percentage = Decimal(
            "0.00"
        )

    percentage = percentage.quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP
    )

    # ========================================================
    # AVERAGE
    # ========================================================

    average = percentage.quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP
    )

    # ========================================================
    # OVERALL GRADE
    #
    # 49.99 -> F
    # 50.00 -> D
    # ========================================================

    grade = calculate_grade(
        percentage
    )

    # ========================================================
    # GPA
    #
    # Calculated from ALL assigned subjects.
    # ========================================================

    gpa = calculate_gpa_from_subjects(
        subject_results
    )

    # ========================================================
    # RESULT STATUS
    #
    # IMPORTANT:
    #
    # There is NO INCOMPLETE for missing subjects.
    #
    # Missing = ZERO
    #
    # Therefore:
    #
    # percentage >= 50 -> PASS
    # percentage <  50 -> FAIL
    #
    # ========================================================

    if percentage >= PASS_MARK:

        result_status = "pass"

    else:

        result_status = "fail"

    # ========================================================
    # FIND EXISTING STUDENT RESULT
    # ========================================================

    result = (
        StudentResult.query
        .filter(
            StudentResult.exam_id == exam.id,

            StudentResult.student_id
            == student_id
        )
        .first()
    )

    # ========================================================
    # CREATE RESULT IF NEEDED
    # ========================================================

    if not result:

        result = StudentResult(
            exam_id=exam.id,
            student_id=student_id
        )

        db.session.add(result)

    # ========================================================
    # BASIC DATA
    # ========================================================

    result.student_enrollment_id = (
        enrollment.id
    )

    result.institution_id = (
        institution_id
    )

    result.branch_id = (
        branch_id
    )

    result.program_id = (
        enrollment.program_id
    )

    result.academic_year_id = (
        enrollment.academic_year_id
    )

    result.term_id = (
        exam.term_id
    )

    result.class_id = (
        enrollment.class_id
    )

    result.section_id = (
        enrollment.section_id
    )

    # ========================================================
    # CALCULATED DATA
    # ========================================================

    result.total_marks = (
        total_marks.quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP
        )
    )

    result.total_possible_marks = (
        total_possible.quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP
        )
    )

    result.percentage = percentage

    result.average = average

    result.subjects_total = (
        subjects_total
    )

    result.subjects_completed = (
        completed
    )

    result.subjects_failed = (
        failed
    )

    result.grade = grade

    result.gpa = gpa

    result.result_status = (
        result_status
    )

    # ========================================================
    # WORKFLOW STATUS
    #
    # Any recalculation means the previous approval/publication
    # is no longer valid.
    # ========================================================

    result.status = "draft"

    # Clear approval/publication timestamps if those columns
    # exist on your StudentResult model.
    if hasattr(
        result,
        "approved_at"
    ):

        result.approved_at = None

    if hasattr(
        result,
        "published_at"
    ):

        result.published_at = None

    # ========================================================
    # CALCULATED TIME
    # ========================================================

    result.calculated_at = (
        datetime.now(
            timezone.utc
        )
    )

    # ========================================================
    # FLUSH
    # ========================================================

    db.session.flush()

    # ========================================================
    # FINAL LOG
    # ========================================================

    current_app.logger.info(
        "Student result calculated | "
        "student=%s exam=%s "
        "class=%s section=%s "
        "subjects=%s completed=%s failed=%s "
        "total=%s possible=%s "
        "percentage=%s grade=%s "
        "status=%s",
        student_id,
        exam.id,
        enrollment.class_id,
        enrollment.section_id,
        subjects_total,
        completed,
        failed,
        total_marks,
        total_possible,
        percentage,
        grade,
        result_status
    )

    return result

# ============================================================
# CALCULATE EXAM RANKINGS
# ============================================================

def calculate_exam_rankings(
    exam_id,
    institution_id,
    branch_id
):

    # ========================================================
    # GET EXAM
    # ========================================================

    exam = (
        Exam.query
        .filter(
            Exam.id == exam_id,
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )
        .first()
    )

    if not exam:

        current_app.logger.warning(
            "Exam not found for ranking | "
            "exam=%s institution=%s branch=%s",
            exam_id,
            institution_id,
            branch_id
        )

        return

    # ========================================================
    # GET ALL RESULTS FOR THIS EXAM + INSTITUTION
    # ========================================================

    institution_results = (
        StudentResult.query
        .filter(
            StudentResult.exam_id == exam_id,
            StudentResult.institution_id
            == institution_id
        )
        .order_by(
            StudentResult.percentage.desc(),
            StudentResult.gpa.desc(),
            StudentResult.student_id.asc()
        )
        .all()
    )

    if not institution_results:

        current_app.logger.info(
            "No student results for ranking | exam=%s",
            exam_id
        )

        return

    # ========================================================
    # RESET OLD RANK POSITIONS
    #
    # This prevents stale positions when students are added,
    # removed, or their marks change.
    # ========================================================

    for result in institution_results:

        result.institution_position = None

        result.branch_position = None

        result.program_position = None

        result.class_position = None

        result.section_position = None

    # ========================================================
    # POSITION HELPER
    #
    # Same percentage + same GPA = same position.
    # ========================================================

    def assign_positions(
        items
    ):

        position = 0

        previous_percentage = None

        previous_gpa = None

        for index, item in enumerate(
            items,
            start=1
        ):

            current_percentage = to_decimal(
                getattr(
                    item,
                    "percentage",
                    0
                )
            )

            current_gpa = to_decimal(
                getattr(
                    item,
                    "gpa",
                    0
                )
            )

            # =================================================
            # FIRST RESULT
            # =================================================

            if previous_percentage is None:

                position = 1

            # =================================================
            # SAME SCORE
            # =================================================

            elif (
                current_percentage
                == previous_percentage
                and
                current_gpa
                == previous_gpa
            ):

                # Same position.
                pass

            # =================================================
            # DIFFERENT SCORE
            # =================================================

            else:

                position = index

            item._calculated_position = (
                position
            )

            previous_percentage = (
                current_percentage
            )

            previous_gpa = (
                current_gpa
            )

    # ========================================================
    # INSTITUTION RANK
    # ========================================================

    assign_positions(
        institution_results
    )

    for result in institution_results:

        result.institution_position = (
            result._calculated_position
        )

    # ========================================================
    # BRANCH RESULTS
    # ========================================================

    branch_results = [
        result
        for result in institution_results
        if result.branch_id == branch_id
    ]

    # ========================================================
    # BRANCH RANK
    # ========================================================

    branch_results.sort(
        key=lambda result: (
            -float(
                to_decimal(
                    result.percentage
                )
            ),
            -float(
                to_decimal(
                    result.gpa
                )
            ),
            result.student_id
        )
    )

    assign_positions(
        branch_results
    )

    for result in branch_results:

        result.branch_position = (
            result._calculated_position
        )

    # ========================================================
    # PROGRAM RANK
    # ========================================================

    program_ids = {
        result.program_id
        for result in branch_results
        if result.program_id is not None
    }

    for current_program_id in program_ids:

        program_results = [
            result
            for result in branch_results
            if result.program_id
            == current_program_id
        ]

        program_results.sort(
            key=lambda result: (
                -float(
                    to_decimal(
                        result.percentage
                    )
                ),
                -float(
                    to_decimal(
                        result.gpa
                    )
                ),
                result.student_id
            )
        )

        assign_positions(
            program_results
        )

        for result in program_results:

            result.program_position = (
                result._calculated_position
            )

    # ========================================================
    # CLASS RANK
    # ========================================================

    class_ids = {
        result.class_id
        for result in branch_results
        if result.class_id is not None
    }

    for current_class_id in class_ids:

        class_results = [
            result
            for result in branch_results
            if result.class_id
            == current_class_id
        ]

        class_results.sort(
            key=lambda result: (
                -float(
                    to_decimal(
                        result.percentage
                    )
                ),
                -float(
                    to_decimal(
                        result.gpa
                    )
                ),
                result.student_id
            )
        )

        assign_positions(
            class_results
        )

        for result in class_results:

            result.class_position = (
                result._calculated_position
            )

    # ========================================================
    # SECTION RANK
    # ========================================================

    section_ids = {
        result.section_id
        for result in branch_results
        if result.section_id is not None
    }

    for current_section_id in section_ids:

        section_results = [
            result
            for result in branch_results
            if result.section_id
            == current_section_id
        ]

        section_results.sort(
            key=lambda result: (
                -float(
                    to_decimal(
                        result.percentage
                    )
                ),
                -float(
                    to_decimal(
                        result.gpa
                    )
                ),
                result.student_id
            )
        )

        assign_positions(
            section_results
        )

        for result in section_results:

            result.section_position = (
                result._calculated_position
            )

    # ========================================================
    # REMOVE TEMPORARY ATTRIBUTE
    #
    # Important:
    # institution_results contains everybody in institution,
    # not only the selected branch.
    # ========================================================

    for result in institution_results:

        if hasattr(
            result,
            "_calculated_position"
        ):

            delattr(
                result,
                "_calculated_position"
            )

    # ========================================================
    # FLUSH
    # ========================================================

    db.session.flush()

    # ========================================================
    # LOG
    # ========================================================

    current_app.logger.info(
        "Exam rankings calculated | "
        "exam=%s institution=%s branch=%s "
        "institution_students=%s branch_students=%s",
        exam_id,
        institution_id,
        branch_id,
        len(institution_results),
        len(branch_results)
    )
    


# ============================================================
# TEACHER - MY EXAMS
# ============================================================
@bp.route(
    "/teacher/my-exams",
    methods=["GET"]
)
@teacher_login_required
def teacher_my_exams():

    # ============================================================
    # TEACHER
    # ============================================================

    teacher = getattr(g, "teacher", None)

    if not teacher:
        abort(403)

    institution_id = getattr(
        teacher,
        "institution_id",
        None
    )

    branch_id = getattr(
        teacher,
        "branch_id",
        None
    )

    if not institution_id or not branch_id:
        flash(
            "Your teacher account is not assigned to an institution and branch.",
            "danger"
        )
        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ============================================================
    # TEACHER STATUS
    # ============================================================

    if not getattr(teacher, "is_active", False):

        flash(
            "Your teacher account is not active.",
            "danger"
        )

        abort(403)

    teacher_status = str(
        getattr(
            teacher,
            "status",
            ""
        ) or ""
    ).lower().strip()

    if teacher_status != "active":

        flash(
            "Your teacher account is not active.",
            "danger"
        )

        abort(403)

    # ============================================================
    # QUERY PARAMETERS
    # ============================================================

    search = (
        request.args.get(
            "search",
            ""
        )
        or ""
    ).strip()

    academic_year_id_raw = (
        request.args.get(
            "academic_year_id",
            ""
        )
        or ""
    ).strip()

    status = (
        request.args.get(
            "status",
            "all"
        )
        or "all"
    ).strip().lower()

    # ============================================================
    # ACADEMIC YEAR FILTER
    # ============================================================

    academic_year_id = None

    if academic_year_id_raw:

        try:
            academic_year_id = int(
                academic_year_id_raw
            )

        except (
            ValueError,
            TypeError
        ):

            academic_year_id = None

    # ============================================================
    # BASE QUERY
    #
    # IMPORTANT:
    # ExamSubject has NO institution_id / branch_id.
    #
    # Institution and branch scope therefore comes from Exam.
    # ============================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )
    )

    # ============================================================
    # ONLY SUBJECTS ASSIGNED TO THIS TEACHER
    #
    # Teacher assignment is ExamSubject.teacher_id.
    #
    # This means the My Exams page only shows ExamSubjects
    # directly assigned to this teacher.
    # ============================================================

    query = query.filter(
        ExamSubject.teacher_id == teacher.id
    )

    # ============================================================
    # SEARCH
    #
    # Search:
    # - Exam name
    # - Exam code
    # - Subject name
    # - Subject code
    # ============================================================

    if search:

        search_pattern = f"%{search}%"

        query = (
            query
            .join(
                Subject,
                Subject.id == ExamSubject.subject_id
            )
            .filter(
                db.or_(
                    Exam.name.ilike(
                        search_pattern
                    ),

                    Exam.code.ilike(
                        search_pattern
                    ),

                    Subject.name.ilike(
                        search_pattern
                    ),

                    Subject.code.ilike(
                        search_pattern
                    )
                )
            )
        )

    # ============================================================
    # ACADEMIC YEAR FILTER
    # ============================================================

    if academic_year_id:

        query = query.filter(
            Exam.academic_year_id == academic_year_id
        )

    # ============================================================
    # EXAM SUBJECT STATUS FILTER
    #
    # "active" / "inactive" belong to ExamSubject.
    # ============================================================

    if status == "active":

        query = query.filter(
            ExamSubject.status == "active"
        )

    elif status == "inactive":

        query = query.filter(
            ExamSubject.status != "active"
        )

    # ============================================================
    # LOAD EXAM SUBJECTS
    # ============================================================

    exam_subjects = (
        query
        .options(
            db.joinedload(
                ExamSubject.exam
            ),

            db.joinedload(
                ExamSubject.subject
            ),

            db.joinedload(
                ExamSubject.class_
            ),

            db.joinedload(
                ExamSubject.section
            ),

            db.joinedload(
                ExamSubject.teacher
            )
        )
        .order_by(
            Exam.start_date.asc().nullslast(),
            Exam.created_at.desc(),
            ExamSubject.display_order.asc(),
            ExamSubject.id.desc()
        )
        .all()
    )

    # ============================================================
    # ACADEMIC YEARS
    #
    # Only years used by this teacher's exams.
    # ============================================================

    academic_years = (
        AcademicYear.query
        .join(
            Exam,
            Exam.academic_year_id == AcademicYear.id
        )
        .join(
            ExamSubject,
            ExamSubject.exam_id == Exam.id
        )
        .filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id,
            ExamSubject.teacher_id == teacher.id
        )
        .distinct()
        .order_by(
            AcademicYear.name.desc()
        )
        .all()
    )

    # ============================================================
    # PREPARE SUBMISSION STATUS
    # ============================================================

    prepared_exam_subjects = []

    for exam_subject in exam_subjects:

        # --------------------------------------------------------
        # EXAM
        # --------------------------------------------------------

        exam = exam_subject.exam

        if not exam:
            continue

        # --------------------------------------------------------
        # SAFETY SCOPE
        # --------------------------------------------------------

        if exam.institution_id != institution_id:
            continue

        if exam.branch_id != branch_id:
            continue

        # --------------------------------------------------------
        # STUDENT SCOPE
        #
        # IMPORTANT:
        # This matches teacher_enter_marks().
        #
        # Students are selected from:
        #
        # institution
        # branch
        # academic year
        # program
        # class
        # section
        # active enrollment
        # active student
        # --------------------------------------------------------

        program_id = exam.program_id

        academic_year_id_for_exam = (
            exam.academic_year_id
        )

        class_id = exam_subject.class_id
        section_id = exam_subject.section_id

        enrollment_query = (
            StudentEnrollment.query
            .join(
                Student,
                Student.id == StudentEnrollment.student_id
            )
            .filter(
                StudentEnrollment.institution_id == institution_id,

                Student.institution_id == institution_id,

                StudentEnrollment.branch_id == branch_id,

                Student.branch_id == branch_id,

                StudentEnrollment.academic_year_id
                == academic_year_id_for_exam,

                StudentEnrollment.program_id
                == program_id
            )
        )

        # --------------------------------------------------------
        # CLASS
        # --------------------------------------------------------

        if class_id:

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.class_id
                    == class_id
                )
            )

        # --------------------------------------------------------
        # SECTION
        # --------------------------------------------------------

        if section_id:

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.section_id
                    == section_id
                )
            )

        # --------------------------------------------------------
        # ACTIVE ENROLLMENT
        # --------------------------------------------------------

        if hasattr(
            StudentEnrollment,
            "status"
        ):

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.status
                    == "active"
                )
            )

        # --------------------------------------------------------
        # ACTIVE STUDENT
        # --------------------------------------------------------

        if hasattr(
            Student,
            "status"
        ):

            enrollment_query = (
                enrollment_query.filter(
                    Student.status
                    == "active"
                )
            )

        # --------------------------------------------------------
        # GET STUDENTS
        # --------------------------------------------------------

        enrollments = (
            enrollment_query
            .order_by(
                Student.full_name.asc()
            )
            .all()
        )

        student_ids = [
            enrollment.student_id
            for enrollment in enrollments
        ]

        total_student_count = len(
            student_ids
        )

        # --------------------------------------------------------
        # EXISTING MARKS
        # --------------------------------------------------------

        submitted_count = 0

        if student_ids:

            submitted_count = (
                Mark.query
                .filter(
                    Mark.exam_subject_id
                    == exam_subject.id,

                    Mark.student_id.in_(
                        student_ids
                    ),

                    Mark.status
                    == "submitted"
                )
                .count()
            )

        # --------------------------------------------------------
        # LOCK ONLY WHEN ALL STUDENTS ARE SUBMITTED
        #
        # Example:
        #
        # 20 students
        # 0 submitted  -> unlocked
        # 5 submitted  -> unlocked
        # 19 submitted -> unlocked
        # 20 submitted -> LOCKED
        #
        # No students -> NOT locked.
        # --------------------------------------------------------

        marks_locked = (
            total_student_count > 0
            and submitted_count
            == total_student_count
        )

        # --------------------------------------------------------
        # SUBMISSION STATUS
        # --------------------------------------------------------

        if marks_locked:

            submission_status = "submitted"

        elif submitted_count > 0:

            submission_status = "partial"

        else:

            submission_status = "pending"

        # --------------------------------------------------------
        # ATTACH VALUES TO OBJECT
        #
        # SQLAlchemy model does not need new database columns for
        # these temporary template values.
        # --------------------------------------------------------

        exam_subject.marks_locked = (
            marks_locked
        )

        exam_subject.submitted_count = (
            submitted_count
        )

        exam_subject.total_student_count = (
            total_student_count
        )

        exam_subject.submission_status = (
            submission_status
        )

        # --------------------------------------------------------
        # ADD TO FINAL LIST
        # --------------------------------------------------------

        prepared_exam_subjects.append(
            exam_subject
        )

    # ============================================================
    # COUNTS
    # ============================================================

    total_exams = len(
        prepared_exam_subjects
    )

    active_exams = sum(
        1
        for item in prepared_exam_subjects
        if str(
            getattr(
                item,
                "status",
                ""
            ) or ""
        ).lower().strip()
        == "active"
    )

    inactive_exams = (
        total_exams
        - active_exams
    )

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(
        "backend/teacher/pages/my_exams.html",

        teacher=teacher,

        exam_subjects=prepared_exam_subjects,

        academic_years=academic_years,

        total_exams=total_exams,

        active_exams=active_exams,

        inactive_exams=inactive_exams,

        search=search,

        academic_year_id=academic_year_id,

        status=status
    )


