@bp.route(
    "/teacher/change-password",
    methods=["GET", "POST"]
)
@teacher_login_required
def teacher_change_password():

    # ========================================================
    # CURRENT TEACHER
    # ========================================================

    teacher = g.teacher

    if not teacher:
        abort(403)

    # ========================================================
    # CHANGE PASSWORD
    # ========================================================

    if request.method == "POST":

        current_password = request.form.get(
            "current_password",
            ""
        ).strip()

        new_password = request.form.get(
            "new_password",
            ""
        )

        confirm_password = request.form.get(
            "confirm_password",
            ""
        )

        # ====================================================
        # REQUIRED
        # ====================================================

        if not current_password:

            flash(
                "Current password is required.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        if not new_password:

            flash(
                "New password is required.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        if not confirm_password:

            flash(
                "Please confirm your new password.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        # ====================================================
        # CURRENT PASSWORD CHECK
        # ====================================================

        if not teacher.check_password(current_password):

            flash(
                "Current password is incorrect.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        # ====================================================
        # NEW PASSWORD LENGTH
        # ====================================================

        if len(new_password) < 6:

            flash(
                "New password must be at least 6 characters.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        # ====================================================
        # CONFIRM PASSWORD
        # ====================================================

        if new_password != confirm_password:

            flash(
                "New password and confirmation password do not match.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        # ====================================================
        # SAME PASSWORD CHECK
        # ====================================================

        if teacher.check_password(new_password):

            flash(
                "New password must be different from your current password.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        # ====================================================
        # SET NEW PASSWORD
        # ====================================================

        try:

            teacher.set_password(new_password)

            db.session.commit()

        except Exception:

            db.session.rollback()

            flash(
                "Something went wrong while changing your password. Please try again.",
                "error"
            )

            return render_template(
                "backend/teacher/pages/change_password.html",
                teacher=teacher
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            "Your password has been changed successfully.",
            "success"
        )

        return redirect(
            url_for("main.teacher_profile")
        )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/teacher/pages/change_password.html",
        teacher=teacher
    )







