# ================= REGISTER =================
@bp.route("/register", methods=["GET", "POST"])
def register():

    # ========================================================
    # ALREADY LOGGED IN
    # ========================================================

    if current_user.is_authenticated:

        flash(
            "You are already logged in.",
            "info"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # CHECK IF USERS ALREADY EXIST
    # ========================================================
    #
    # First registration only:
    # First user = Superadmin
    #
    # After the first user exists, public registration
    # is disabled.
    # ========================================================

    if User.query.first():

        flash(
            "Registration is currently closed.",
            "warning"
        )

        return redirect(
            url_for("main.login")
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM DATA
        # ====================================================

        username = request.form.get(
            "username",
            ""
        ).strip()

        email = request.form.get(
            "email",
            ""
        ).strip().lower()

        fullname = request.form.get(
            "fullname",
            ""
        ).strip()

        password = request.form.get(
            "password",
            ""
        )

        confirm_password = request.form.get(
            "confirm_password",
            ""
        )

        # ====================================================
        # VALIDATION
        # ====================================================

        if not username:

            flash(
                "Username is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if not email:

            flash(
                "Email is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if not fullname:

            flash(
                "Full name is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if not password:

            flash(
                "Password is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if password != confirm_password:

            flash(
                "Passwords do not match.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # CHECK USERNAME
        # ====================================================

        existing_username = User.query.filter_by(
            username=username
        ).first()

        if existing_username:

            flash(
                "Username already exists.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # CHECK EMAIL
        # ====================================================

        existing_email = User.query.filter_by(
            email=email
        ).first()

        if existing_email:

            flash(
                "Email already exists.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # CREATE FIRST USER
        # ====================================================

        user = User(
            username=username,
            email=email,
            fullname=fullname,

            # First and only public registration
            role=UserRole.superadmin.value,

            status=True,
            is_verified=True,
            auth_status="logout"
        )

        # ====================================================
        # PASSWORD
        # ====================================================

        user.set_password(
            password
        )

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(
                user
            )

            db.session.commit()

        except Exception as e:

            db.session.rollback()

            current_app.logger.exception(
                "Registration error"
            )

            flash(
                "An error occurred while creating "
                "your account.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            "Registration successful. "
            "Your Superadmin account has been created. "
            "Please login.",
            "success"
        )

        return redirect(
            url_for("main.login")
        )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/auth/register.html"
    )


# ============================================================
# DASHBOARD
# ============================================================
# ROLES:
#   1. superadmin
#   2. school_admin  -> Institution Admin
#   3. branch_admin  -> Branch Admin
#
# Dashboard template:
#   backend/home/dashboard.html
# ============================================================

@bp.route("/dashboard")
@login_required
def dashboard():

    # ========================================================
    # ROLE
    # ========================================================

    role = getattr(current_user, "role", None)

    # Enum -> value
    if hasattr(role, "value"):
        role = role.value

    role = (
        str(role).strip().lower()
        if role
        else ""
    )
    # ========================================================
    # INSTITUTION / BRANCH CONTEXT
    # ========================================================

    institution = None
    branch = None

    if role == "school_admin":
        if current_user.institution_id:
            institution = Institution.query.get(
                current_user.institution_id
            )

    elif role == "branch_admin":
        if current_user.institution_id:
            institution = Institution.query.get(
                current_user.institution_id
            )

        if current_user.branch_id:
            branch = Branch.query.get(
                current_user.branch_id
            )

    elif role == "superadmin":
        # Superadmin ma laha institution gaar ah.
        # Haddii current_user uu leeyahay institution_id,
        # isticmaal context-kaas.
        if getattr(current_user, "institution_id", None):
            institution = Institution.query.get(
                current_user.institution_id
            )

        if getattr(current_user, "branch_id", None):
            branch = Branch.query.get(
                current_user.branch_id
            )

    # ========================================================
    # DYNAMIC NAMES
    # ========================================================

    institution_name = (
        institution.name
        if institution and getattr(institution, "name", None)
        else "SOOYAAL Educational Institute"
    )

    branch_name = (
        branch.name
        if branch and getattr(branch, "name", None)
        else None
    )

    # ========================================================
    # DEFAULT DASHBOARD VALUES
    # ========================================================

    total_institutions = 0
    active_institutions = 0
    inactive_institutions = 0
    suspended_institutions = 0

    total_branches = 0
    total_users = 0
    total_teachers = 0
    total_students = 0
    total_classes = 0
    total_subjects = 0
    total_programs = 0
    total_exams = 0

    # ========================================================
    # 1. SUPERADMIN
    # ========================================================

    if role == "superadmin":

        # ----------------------------------------------------
        # INSTITUTIONS
        # ----------------------------------------------------

        total_institutions = Institution.query.count()

        active_institutions = Institution.query.filter(
            Institution.status == "active"
        ).count()

        inactive_institutions = Institution.query.filter(
            Institution.status == "inactive"
        ).count()

        suspended_institutions = Institution.query.filter(
            Institution.status == "suspended"
        ).count()

        # ----------------------------------------------------
        # BRANCHES
        # ----------------------------------------------------

        total_branches = Branch.query.count()

        # ----------------------------------------------------
        # USERS
        # ----------------------------------------------------

        total_users = User.query.count()

        # ----------------------------------------------------
        # TEACHERS
        # ----------------------------------------------------

        total_teachers = Teacher.query.count()

        # ----------------------------------------------------
        # STUDENTS
        # ----------------------------------------------------

        total_students = Student.query.count()

        # ----------------------------------------------------
        # CLASSES
        # ----------------------------------------------------

        total_classes = Class.query.count()

        # ----------------------------------------------------
        # SUBJECTS
        # ----------------------------------------------------

        total_subjects = Subject.query.count()

        # ----------------------------------------------------
        # PROGRAMS
        # ----------------------------------------------------

        total_programs = Program.query.count()

        # ----------------------------------------------------
        # EXAMS
        # ----------------------------------------------------

        total_exams = Exam.query.count()

    # ========================================================
    # 2. INSTITUTION ADMIN
    # ========================================================
    # Role:
    # school_admin
    # ========================================================

    elif role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        # ----------------------------------------------------
        # SECURITY
        # ----------------------------------------------------

        if not institution_id:
            abort(403)

        # ----------------------------------------------------
        # VERIFY INSTITUTION
        # ----------------------------------------------------

        institution = Institution.query.filter(
            Institution.id == institution_id
        ).first()

        if not institution:
            abort(403)

        # ----------------------------------------------------
        # BRANCHES
        # ----------------------------------------------------

        total_branches = Branch.query.filter(
            Branch.institution_id == institution_id
        ).count()

        # ----------------------------------------------------
        # USERS
        # ----------------------------------------------------

        total_users = User.query.filter(
            User.institution_id == institution_id
        ).count()

        # ----------------------------------------------------
        # TEACHERS
        # ----------------------------------------------------

        total_teachers = Teacher.query.filter(
            Teacher.institution_id == institution_id
        ).count()

        # ----------------------------------------------------
        # STUDENTS
        # ----------------------------------------------------

        total_students = Student.query.filter(
            Student.institution_id == institution_id
        ).count()

        # ----------------------------------------------------
        # CLASSES
        # ----------------------------------------------------

        total_classes = Class.query.filter(
            Class.institution_id == institution_id
        ).count()

        # ----------------------------------------------------
        # SUBJECTS
        # ----------------------------------------------------

        total_subjects = Subject.query.filter(
            Subject.institution_id == institution_id
        ).count()

        # ----------------------------------------------------
        # PROGRAMS
        # ----------------------------------------------------

        total_programs = Program.query.filter(
            Program.institution_id == institution_id
        ).count()

        # ----------------------------------------------------
        # EXAMS
        # ----------------------------------------------------

        total_exams = Exam.query.filter(
            Exam.institution_id == institution_id
        ).count()

    # ========================================================
    # 3. BRANCH ADMIN
    # ========================================================
    # Role:
    # branch_admin
    # ========================================================

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        # ----------------------------------------------------
        # SECURITY
        # ----------------------------------------------------

        if not institution_id or not branch_id:
            abort(403)

        # ----------------------------------------------------
        # VERIFY BRANCH BELONGS TO INSTITUTION
        # ----------------------------------------------------

        branch = Branch.query.filter(
            Branch.id == branch_id,
            Branch.institution_id == institution_id
        ).first()

        if not branch:
            abort(403)

        # ----------------------------------------------------
        # BRANCH
        # ----------------------------------------------------

        total_branches = 1

        # ----------------------------------------------------
        # USERS
        # ----------------------------------------------------

        total_users = User.query.filter(
            User.institution_id == institution_id,
            User.branch_id == branch_id
        ).count()

        # ----------------------------------------------------
        # TEACHERS
        # ----------------------------------------------------

        total_teachers = Teacher.query.filter(
            Teacher.institution_id == institution_id,
            Teacher.branch_id == branch_id
        ).count()

        # ----------------------------------------------------
        # STUDENTS
        # ----------------------------------------------------

        total_students = Student.query.filter(
            Student.institution_id == institution_id,
            Student.branch_id == branch_id
        ).count()

        # ----------------------------------------------------
        # CLASSES
        # ----------------------------------------------------

        total_classes = Class.query.filter(
            Class.institution_id == institution_id,
            Class.branch_id == branch_id
        ).count()

        # ----------------------------------------------------
        # SUBJECTS
        # ----------------------------------------------------

        total_subjects = Subject.query.filter(
            Subject.institution_id == institution_id,
            Subject.branch_id == branch_id
        ).count()

        # ----------------------------------------------------
        # PROGRAMS
        # ----------------------------------------------------
        # Programs can be:
        #   - branch-specific
        #   - institution-wide/shared (branch_id = NULL)
        # ----------------------------------------------------

        total_programs = Program.query.filter(
            Program.institution_id == institution_id,
            db.or_(
                Program.branch_id == branch_id,
                Program.branch_id.is_(None)
            )
        ).count()

        # ----------------------------------------------------
        # EXAMS
        # ----------------------------------------------------

        total_exams = Exam.query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        ).count()

    # ========================================================
    # OTHER ROLES
    # ========================================================

    else:

        abort(403)


    # hi kulmiye
    # ============================================================
    # TOP 10 STUDENTS WITH MOST ABSENCES
    # ============================================================
    #
    # RULES
    # ------------------------------------------------------------
    # SUPERADMIN:
    #     - All institutions
    #     - All branches
    #
    # SCHOOL ADMIN:
    #     - Current institution only
    #     - All branches inside that institution
    #
    # BRANCH ADMIN:
    #     - Current institution only
    #     - Current branch only
    #
    # RESULT:
    #     - Top 10 students with the highest absence count
    #     - Sorted from most absent -> least absent
    #     - Shows:
    #         student_name
    #         class_name
    #         section_name
    #         absent_count
    #         total_attendance
    #         absence_rate
    #         last_absent_date
    # ============================================================

    top_absent_students = []


    # ============================================================
    # ONLY ADMIN DASHBOARD ROLES
    # ============================================================

    if role in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        # ========================================================
        # BASE QUERY
        # ========================================================
        #
        # IMPORTANT:
        # AttendanceSession is JOINED ONLY ONCE.
        #
        # AttendanceRecord
        #       ↓
        # AttendanceSession
        #       ↓
        # Student
        #
        # This prevents:
        #
        # JOIN attendance_sessions ...
        # JOIN attendance_sessions ...
        #
        # ========================================================

        attendance_query = (
            db.session.query(
                AttendanceRecord
            )
            .join(
                AttendanceSession,
                AttendanceRecord.attendance_session_id
                == AttendanceSession.id
            )
            .join(
                Student,
                AttendanceRecord.student_id
                == Student.id
            )
        )


        # ========================================================
        # ROLE SCOPE
        # ========================================================

        # --------------------------------------------------------
        # SUPERADMIN
        # --------------------------------------------------------
        #
        # No institution / branch filter.
        #
        if role == "superadmin":

            pass


        # --------------------------------------------------------
        # SCHOOL ADMIN
        # --------------------------------------------------------
        #
        # Institution only.
        #
        elif role == "school_admin":

            attendance_query = attendance_query.filter(
                AttendanceSession.institution_id
                == current_user.institution_id
            )


        # --------------------------------------------------------
        # BRANCH ADMIN
        # --------------------------------------------------------
        #
        # Institution + own branch.
        #
        elif role == "branch_admin":

            attendance_query = attendance_query.filter(
                AttendanceSession.institution_id
                == current_user.institution_id,

                AttendanceSession.branch_id
                == current_user.branch_id
            )


        # ========================================================
        # ABSENT COUNT
        # ========================================================

        absent_count_expression = func.sum(
            case(
                (
                    AttendanceRecord.status == "absent",
                    1
                ),
                else_=0
            )
        )


        # ========================================================
        # TOTAL ATTENDANCE RECORDS
        # ========================================================

        total_attendance_expression = func.count(
            AttendanceRecord.id
        )


        # ========================================================
        # LAST ABSENT DATE
        # ========================================================

        last_absent_date_expression = func.max(
            case(
                (
                    AttendanceRecord.status == "absent",
                    AttendanceSession.attendance_date
                ),
                else_=None
            )
        )


        # ========================================================
        # TOP 10 QUERY
        # ========================================================

        top_absent_rows = (
            attendance_query

            .with_entities(

                # ------------------------------------------------
                # STUDENT
                # ------------------------------------------------

                Student.id.label(
                    "student_id"
                ),

                Student.full_name.label(
                    "student_name"
                ),

                # ------------------------------------------------
                # CLASS
                # ------------------------------------------------
                #
                # AttendanceSession already contains class_id.
                # We keep class_id here and resolve the actual
                # class name below.
                #
                AttendanceSession.class_id.label(
                    "class_id"
                ),

                # ------------------------------------------------
                # SECTION
                # ------------------------------------------------

                AttendanceSession.section_id.label(
                    "section_id"
                ),

                # ------------------------------------------------
                # ABSENCE COUNT
                # ------------------------------------------------

                absent_count_expression.label(
                    "absent_count"
                ),

                # ------------------------------------------------
                # TOTAL ATTENDANCE
                # ------------------------------------------------

                total_attendance_expression.label(
                    "total_attendance"
                ),

                # ------------------------------------------------
                # LAST ABSENT DATE
                # ------------------------------------------------

                last_absent_date_expression.label(
                    "last_absent_date"
                ),
            )

            # ----------------------------------------------------
            # GROUP
            # ----------------------------------------------------

            .group_by(
                Student.id,
                Student.full_name,
                AttendanceSession.class_id,
                AttendanceSession.section_id,
            )

            # ----------------------------------------------------
            # ONLY STUDENTS WHO HAVE ABSENCES
            # ----------------------------------------------------

            .having(
                absent_count_expression > 0
            )

            # ----------------------------------------------------
            # SORT
            # ----------------------------------------------------
            #
            # Most absent first.
            #
            .order_by(
                absent_count_expression.desc(),

                last_absent_date_expression.desc(),

                Student.full_name.asc()
            )

            # ----------------------------------------------------
            # TOP 10
            # ----------------------------------------------------

            .limit(10)

            .all()
        )


        # ========================================================
        # BUILD DASHBOARD DATA
        # ========================================================

        for row in top_absent_rows:

            # ====================================================
            # TOTAL ATTENDANCE
            # ====================================================

            total_count = int(
                row.total_attendance or 0
            )


            # ====================================================
            # ABSENT COUNT
            # ====================================================

            absent_count_value = int(
                row.absent_count or 0
            )


            # ====================================================
            # ABSENCE RATE
            # ====================================================
            #
            # Formula:
            #
            # absent / total attendance × 100
            #
            # Example:
            #
            # 5 absent / 50 attendance = 10%
            #
            # ====================================================

            if total_count > 0:

                absence_rate = (
                    absent_count_value
                    / total_count
                ) * 100

            else:

                absence_rate = 0


            # ====================================================
            # DEFAULT CLASS / SECTION
            # ====================================================

            class_name = "—"

            section_name = "—"


            # ====================================================
            # GET CLASS
            # ====================================================

            if row.class_id:

                class_obj = (
                    db.session.get(
                        Class,
                        row.class_id
                    )
                )

                if class_obj:

                    class_name = (
                        getattr(
                            class_obj,
                            "name",
                            None
                        )
                        or getattr(
                            class_obj,
                            "class_name",
                            None
                        )
                        or getattr(
                            class_obj,
                            "title",
                            None
                        )
                        or "—"
                    )


            # ====================================================
            # GET SECTION
            # ====================================================

            if row.section_id:

                section_obj = (
                    db.session.get(
                        Section,
                        row.section_id
                    )
                )

                if section_obj:

                    section_name = (
                        section_obj.name
                        or "—"
                    )


            # ====================================================
            # APPEND
            # ====================================================

            top_absent_students.append(
                {
                    "student_id": row.student_id,

                    "student_name": (
                        row.student_name
                        or "Unknown Student"
                    ),

                    "class_id": row.class_id,

                    "class_name": class_name,

                    "section_id": row.section_id,

                    "section_name": section_name,

                    "absent_count": (
                        absent_count_value
                    ),

                    "total_attendance": (
                        total_count
                    ),

                    "absence_rate": round(
                        absence_rate,
                        1
                    ),

                    "last_absent_date": (
                        row.last_absent_date
                    ),
                }
            )
        
    #== tag

    #resulting also
    # ============================================================
    # LATEST EXAM - TOP 10 STUDENTS
    # ============================================================
    #
    # RULES
    # ------------------------------------------------------------
    # SUPERADMIN:
    #     Latest exam from all institutions / branches
    #
    # SCHOOL ADMIN:
    #     Latest exam from current institution
    #
    # BRANCH ADMIN:
    #     Latest exam from current branch
    #
    # RESULT:
    #     Top 10 students from the latest exam
    #
    # SHOW:
    #     Student Name
    #     Branch
    #     Class
    #     Overall Average
    #     Grade
    #     Rank
    # ============================================================

    latest_exam = None
    latest_exam_top_students = []


    # ============================================================
    # ADMIN ROLES ONLY
    # ============================================================

    if role in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        # ========================================================
        # FIND LATEST EXAM
        # ========================================================

        latest_exam_query = (
            Exam.query
        )


        # ========================================================
        # SUPERADMIN
        # ========================================================

        if role == "superadmin":

            latest_exam = (
                latest_exam_query
                .order_by(
                    Exam.created_at.desc(),
                    Exam.id.desc()
                )
                .first()
            )


        # ========================================================
        # SCHOOL ADMIN
        # ========================================================

        elif role == "school_admin":

            latest_exam = (
                latest_exam_query
                .filter(
                    Exam.institution_id
                    == current_user.institution_id
                )
                .order_by(
                    Exam.created_at.desc(),
                    Exam.id.desc()
                )
                .first()
            )


        # ========================================================
        # BRANCH ADMIN
        # ========================================================

        elif role == "branch_admin":

            latest_exam = (
                latest_exam_query
                .filter(
                    Exam.institution_id
                    == current_user.institution_id,

                    Exam.branch_id
                    == current_user.branch_id
                )
                .order_by(
                    Exam.created_at.desc(),
                    Exam.id.desc()
                )
                .first()
            )


        # ========================================================
        # IF LATEST EXAM EXISTS
        # ========================================================

        if latest_exam:

            # ====================================================
            # GET STUDENT RESULTS FOR THIS EXAM
            # ====================================================

            result_query = (
                StudentResult.query
                .filter(
                    StudentResult.exam_id
                    == latest_exam.id
                )
            )


            # ====================================================
            # ROLE SCOPE
            # ====================================================

            # ----------------------------------------------------
            # SUPERADMIN
            # ----------------------------------------------------

            if role == "superadmin":

                pass


            # ----------------------------------------------------
            # SCHOOL ADMIN
            # ----------------------------------------------------

            elif role == "school_admin":

                result_query = result_query.filter(
                    StudentResult.institution_id
                    == current_user.institution_id
                )


            # ----------------------------------------------------
            # BRANCH ADMIN
            # ----------------------------------------------------

            elif role == "branch_admin":

                result_query = result_query.filter(
                    StudentResult.institution_id
                    == current_user.institution_id,

                    StudentResult.branch_id
                    == current_user.branch_id
                )


            # ====================================================
            # GET ALL RESULTS
            # ====================================================
            #
            # We sort by percentage first.
            #
            # Highest percentage = Rank 1
            #
            # ====================================================

            result_rows = (
                result_query
                .join(
                    Student,
                    StudentResult.student_id
                    == Student.id
                )
                .order_by(
                    StudentResult.percentage.desc(),

                    StudentResult.average.desc(),

                    Student.full_name.asc()
                )
                .limit(10)
                .all()
            )


            # ====================================================
            # BUILD TOP 10
            # ====================================================

            for index, result in enumerate(
                result_rows,
                start=1
            ):

                # =================================================
                # STUDENT
                # =================================================

                student_name = (
                    result.student.full_name
                    if result.student
                    else "Unknown Student"
                )


                # =================================================
                # BRANCH
                # =================================================

                branch_name = "—"

                if result.branch:

                    branch_name = (
                        getattr(
                            result.branch,
                            "name",
                            None
                        )
                        or getattr(
                            result.branch,
                            "branch_name",
                            None
                        )
                        or "—"
                    )


                # =================================================
                # CLASS
                # =================================================

                class_name = "—"

                if result.class_:

                    class_name = (
                        getattr(
                            result.class_,
                            "name",
                            None
                        )
                        or getattr(
                            result.class_,
                            "class_name",
                            None
                        )
                        or getattr(
                            result.class_,
                            "title",
                            None
                        )
                        or "—"
                    )


                # =================================================
                # AVERAGE
                # =================================================

                average_value = (
                    float(result.average or 0)
                )


                # =================================================
                # PERCENTAGE
                # =================================================

                percentage_value = (
                    float(result.percentage or 0)
                )


                # =================================================
                # GRADE
                # =================================================

                grade_value = (
                    result.grade
                    or "—"
                )


                # =================================================
                # RANK
                # =================================================

                rank_value = index


                # =================================================
                # POSITION VALUE
                # =================================================
                #
                # Keep the stored position as extra information.
                #
                # For branch admin:
                #     branch_position
                #
                # For school admin:
                #     institution_position
                #
                # For superadmin:
                #     institution_position
                #
                # But dashboard rank remains calculated from the
                # currently visible result set.
                #
                # =================================================

                stored_position = None

                if role == "branch_admin":

                    stored_position = (
                        result.branch_position
                    )

                else:

                    stored_position = (
                        result.institution_position
                    )


                # =================================================
                # APPEND
                # =================================================

                latest_exam_top_students.append(
                    {
                        "student_id": result.student_id,

                        "student_name": student_name,

                        "branch_name": branch_name,

                        "class_name": class_name,

                        "average": round(
                            average_value,
                            2
                        ),

                        "percentage": round(
                            percentage_value,
                            2
                        ),

                        "grade": grade_value,

                        "rank": rank_value,

                        "stored_position": stored_position,

                        "result_status": (
                            result.result_status
                        ),

                        "result_id": result.id,
                    }
                )

        


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/home/dashboard.html",

        # Current user
        user=current_user,

        # Current role
        role=role,
        #here
        latest_exam=latest_exam,
        latest_exam_top_students=latest_exam_top_students,

        # Current scope
        institution_id=getattr(
            current_user,
            "institution_id",
            None
        ),

        branch_id=getattr(
            current_user,
            "branch_id",
            None
        ),

        # ----------------------------------------------------
        # SUPERADMIN
        # ----------------------------------------------------

        total_institutions=total_institutions,
        active_institutions=active_institutions,
        inactive_institutions=inactive_institutions,
        suspended_institutions=suspended_institutions,

        # ----------------------------------------------------
        # ALL ROLES
        # ----------------------------------------------------

        total_branches=total_branches,
        total_users=total_users,
        total_teachers=total_teachers,
        total_students=total_students,
        total_classes=total_classes,
        total_subjects=total_subjects,
        total_programs=total_programs,
        total_exams=total_exams,

        # ========================================================
        # ATTENDANCE DASHBOARD
        # ========================================================

        top_absent_students=top_absent_students,

         institution=institution,
        branch=branch,

        institution_name=institution_name,
        branch_name=branch_name,

    )


# ============================================================
# GLOBAL TEMPLATE CONTEXT
# ============================================================

@bp.app_context_processor
def inject_global_template_data():

    role = getattr(current_user, "role", None)

    if hasattr(role, "value"):
        role = role.value

    role = (
        str(role).strip().lower()
        if role
        else ""
    )

    institution = None
    branch = None

    # ========================================================
    # INSTITUTION
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if institution_id:
        institution = Institution.query.get(
            institution_id
        )

    # ========================================================
    # BRANCH
    # ========================================================

    if branch_id:
        branch = Branch.query.get(
            branch_id
        )

    # ========================================================
    # DYNAMIC INSTITUTION NAME
    # ========================================================

    institution_name = (
        getattr(institution, "name", None)
        if institution
        else None
    )

    institution_name = (
        institution_name
        or "SOOYAAL Educational Institute"
    )

    # ========================================================
    # DYNAMIC BRANCH NAME
    # ========================================================

    branch_name = (
        getattr(branch, "name", None)
        if branch
        else None
    )

    return {
        "current_year": datetime.now().year,

        "current_role": role,

        "current_institution": institution,

        "current_branch": branch,

        "institution_name": institution_name,

        "branch_name": branch_name,
    }

# ============================================================
# PROFILE PHOTO VALIDATION
# ============================================================

def allowed_profile_photo(filename):

    if not filename:
        return False

    filename = secure_filename(filename)

    if "." not in filename:
        return False

    extension = (
        filename
        .rsplit(".", 1)[1]
        .lower()
    )

    return extension in ALLOWED_PROFILE_EXTENSIONS





