@bp.route(
    "/profile",
    methods=["GET", "POST"]
)
@login_required
def profile():

    # ========================================================
    # GET CURRENT USER
    # ========================================================

    user = User.query.get(current_user.id)

    if not user:

        logout_user()

        flash(
            "Your account could not be found.",
            "danger"
        )

        return redirect(
            url_for("main.login")
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # BASIC INFORMATION
        # ====================================================

        username = (
            request.form.get(
                "username",
                ""
            )
            .strip()
        )

        email = (
            request.form.get(
                "email",
                ""
            )
            .strip()
            .lower()
        )

        fullname = (
            request.form.get(
                "fullname",
                ""
            )
            .strip()
        )

        phone = (
            request.form.get(
                "phone",
                ""
            )
            .strip()
        )

        # ====================================================
        # LOCATION
        # ====================================================

        country = (
            request.form.get(
                "country",
                ""
            )
            .strip()
        )

        city = (
            request.form.get(
                "city",
                ""
            )
            .strip()
        )

        state = (
            request.form.get(
                "state",
                ""
            )
            .strip()
        )

        address = (
            request.form.get(
                "address",
                ""
            )
            .strip()
        )

        # ====================================================
        # BIO
        # ====================================================

        bio = (
            request.form.get(
                "bio",
                ""
            )
            .strip()
        )

        # ====================================================
        # PERSONAL INFORMATION
        # ====================================================

        gender = (
            request.form.get(
                "gender",
                ""
            )
            .strip()
        )

        pob = (
            request.form.get(
                "pob",
                ""
            )
            .strip()
        )

        dob = (
            request.form.get(
                "dob",
                ""
            )
            .strip()
        )

        # ====================================================
        # SOCIAL MEDIA
        # ====================================================

        facebook = (
            request.form.get(
                "facebook",
                ""
            )
            .strip()
            or None
        )

        twitter = (
            request.form.get(
                "twitter",
                ""
            )
            .strip()
            or None
        )

        google = (
            request.form.get(
                "google",
                ""
            )
            .strip()
            or None
        )

        linkedin = (
            request.form.get(
                "linkedin",
                ""
            )
            .strip()
            or None
        )

        skype = (
            request.form.get(
                "skype",
                ""
            )
            .strip()
            or None
        )

        whatsapp = (
            request.form.get(
                "whatsapp",
                ""
            )
            .strip()
            or None
        )

        instagram = (
            request.form.get(
                "instagram",
                ""
            )
            .strip()
            or None
        )

        github = (
            request.form.get(
                "github",
                ""
            )
            .strip()
            or None
        )

        # ====================================================
        # PHOTO VISIBILITY
        # ====================================================

        photo_visibility = (
            request.form.get(
                "photo_visibility",
                "everyone"
            )
            .strip()
            .lower()
        )

        allowed_visibility = {
            "everyone",
            "registered",
            "private"
        }

        if photo_visibility not in allowed_visibility:

            photo_visibility = "everyone"

        # ====================================================
        # PROFILE PHOTO
        # ====================================================

        profile_photo = request.files.get(
            "profile_photo"
        )

        # ====================================================
        # VALIDATION
        # ====================================================

        if not username:

            flash(
                "Username is required.",
                "danger"
            )

            return render_template(
                "backend/pages/users/profile_view.html",
                user=user
            )

        if not email:

            flash(
                "Email is required.",
                "danger"
            )

            return render_template(
                "backend/pages/users/profile_view.html",
                user=user
            )

        if not fullname:

            flash(
                "Full name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/users/profile_view.html",
                user=user
            )

        # ====================================================
        # USERNAME DUPLICATE
        # ====================================================

        existing_username = (
            User.query
            .filter(
                User.username == username,
                User.id != user.id
            )
            .first()
        )

        if existing_username:

            flash(
                "This username is already in use.",
                "danger"
            )

            return render_template(
                "backend/pages/users/profile_view.html",
                user=user
            )

        # ====================================================
        # EMAIL DUPLICATE
        # ====================================================

        existing_email = (
            User.query
            .filter(
                User.email == email,
                User.id != user.id
            )
            .first()
        )

        if existing_email:

            flash(
                "This email address is already in use.",
                "danger"
            )

            return render_template(
                "backend/pages/users/profile_view.html",
                user=user
            )

        # ====================================================
        # DATE OF BIRTH
        # ====================================================

        parsed_dob = None

        if dob:

            try:

                parsed_dob = datetime.strptime(
                    dob,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                flash(
                    "Invalid date of birth.",
                    "danger"
                )

                return render_template(
                    "backend/pages/users/profile_view.html",
                    user=user
                )

        # ====================================================
        # CLOUDINARY PHOTO
        # ====================================================

        new_photo_url = None

        if (
            profile_photo
            and profile_photo.filename
        ):

            # ------------------------------------------------
            # ALLOWED EXTENSIONS
            # ------------------------------------------------

            allowed_extensions = {
                "jpg",
                "jpeg",
                "png",
                "webp"
            }

            original_filename = (
                profile_photo.filename
                .strip()
            )

            extension = ""

            if "." in original_filename:

                extension = (
                    original_filename
                    .rsplit(".", 1)[1]
                    .lower()
                )

            if extension not in allowed_extensions:

                flash(
                    "Only JPG, JPEG, PNG and WEBP images are allowed.",
                    "danger"
                )

                return render_template(
                    "backend/pages/users/profile_view.html",
                    user=user
                )

            # ------------------------------------------------
            # FILE SIZE
            # ------------------------------------------------

            try:

                profile_photo.seek(
                    0,
                    os.SEEK_END
                )

                file_size = profile_photo.tell()

                profile_photo.seek(0)

            except Exception:

                flash(
                    "Unable to read the uploaded image.",
                    "danger"
                )

                return render_template(
                    "backend/pages/users/profile_view.html",
                    user=user
                )

            # ------------------------------------------------
            # MAX 5 MB
            # ------------------------------------------------

            if file_size > (
                5 * 1024 * 1024
            ):

                flash(
                    "Profile photo must not exceed 5 MB.",
                    "danger"
                )

                return render_template(
                    "backend/pages/users/profile_view.html",
                    user=user
                )

            # ------------------------------------------------
            # CLOUDINARY PUBLIC ID
            # ------------------------------------------------

            public_id = (
                "school_management/"
                "profile_photos/"
                f"user_{user.id}"
            )

            # ------------------------------------------------
            # CLOUDINARY UPLOAD
            # ------------------------------------------------

            try:

                upload_result = uploader.upload(
                    profile_photo,
                    public_id=public_id,
                    resource_type="image",
                    overwrite=True,
                    invalidate=True,
                    use_filename=False,
                    unique_filename=False,
                    transformation=[
                        {
                            "width": 600,
                            "height": 600,
                            "crop": "fill",
                            "gravity": "face"
                        }
                    ]
                )

                # --------------------------------------------
                # GET SECURE URL
                # --------------------------------------------

                new_photo_url = (
                    upload_result.get(
                        "secure_url"
                    )
                )

                if not new_photo_url:

                    current_app.logger.error(
                        "Cloudinary upload returned no secure_url: %s",
                        upload_result
                    )

                    flash(
                        "Cloudinary uploaded the image but did not return a valid URL.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/users/profile_view.html",
                        user=user
                    )

            except Exception as cloudinary_error:

                current_app.logger.exception(
                    "CLOUDINARY PROFILE PHOTO ERROR: %s",
                    cloudinary_error
                )

                flash(
                    "Unable to upload your profile photo. "
                    "Please check your Cloudinary configuration.",
                    "danger"
                )

                return render_template(
                    "backend/pages/users/profile_view.html",
                    user=user
                )

        # ====================================================
        # UPDATE BASIC INFORMATION
        # ====================================================

        user.username = username
        user.email = email
        user.fullname = fullname
        user.phone = phone or None

        # ====================================================
        # UPDATE LOCATION
        # ====================================================

        user.country = country or None
        user.city = city or None
        user.state = state or None
        user.address = address or None

        # ====================================================
        # UPDATE BIO
        # ====================================================

        user.bio = bio or None

        # ====================================================
        # UPDATE PERSONAL INFORMATION
        # ====================================================

        user.gender = gender or None
        user.pob = pob or None
        user.dob = parsed_dob

        # ====================================================
        # UPDATE SOCIAL MEDIA
        # ====================================================

        user.facebook = facebook
        user.twitter = twitter
        user.google = google
        user.linkedin = linkedin
        user.skype = skype
        user.whatsapp = whatsapp
        user.instagram = instagram
        user.github = github

        # ====================================================
        # UPDATE PHOTO VISIBILITY
        # ====================================================

        user.photo_visibility = photo_visibility

        # ====================================================
        # UPDATE PHOTO URL
        # ====================================================

        if new_photo_url:

            user.photo = new_photo_url

        # ====================================================
        # UPDATED TIMESTAMP
        # ====================================================

        user.updated_at = datetime.utcnow()

        # ====================================================
        # DATABASE COMMIT
        # ====================================================

        try:

            db.session.commit()

            flash(
                "Your profile has been updated successfully.",
                "success"
            )

            return redirect(
                url_for("main.profile")
            )

        except Exception as database_error:

            db.session.rollback()

            current_app.logger.exception(
                "PROFILE DATABASE UPDATE ERROR: %s",
                database_error
            )

            flash(
                "Unable to update your profile. Please try again.",
                "danger"
            )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/users/profile_view.html",
        user=user
    )


# ============================================================
# ACCOUNT SETTINGS
# ============================================================

@bp.route("/account-settings", methods=["GET", "POST"])
@login_required
def account_settings():

    # --------------------------------------------------------
    # GET CURRENT USER
    # --------------------------------------------------------

    user = User.query.get(int(current_user.get_id()))

    if not user:
        flash("User account could not be found.", "danger")
        return redirect(url_for("main.logout"))

    # --------------------------------------------------------
    # CHANGE PASSWORD
    # --------------------------------------------------------

    if request.method == "POST":

        current_password = request.form.get(
            "current_password",
            ""
        ).strip()

        new_password = request.form.get(
            "new_password",
            ""
        ).strip()

        confirm_password = request.form.get(
            "confirm_password",
            ""
        ).strip()

        # ----------------------------------------------------
        # REQUIRED FIELDS
        # ----------------------------------------------------

        if not current_password:
            flash(
                "Please enter your current password.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        if not new_password:
            flash(
                "Please enter your new password.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        if not confirm_password:
            flash(
                "Please confirm your new password.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # VERIFY CURRENT PASSWORD
        # ----------------------------------------------------

        if not user.check_password(current_password):

            flash(
                "Your current password is incorrect.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # NEW PASSWORD MATCH
        # ----------------------------------------------------

        if new_password != confirm_password:

            flash(
                "The new passwords do not match.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # PASSWORD LENGTH
        # ----------------------------------------------------

        if len(new_password) < 8:

            flash(
                "Your new password must contain at least 8 characters.",
                "danger"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # PREVENT SAME PASSWORD
        # ----------------------------------------------------

        if user.check_password(new_password):

            flash(
                "Your new password must be different from your current password.",
                "warning"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ----------------------------------------------------
        # SET NEW PASSWORD
        # ----------------------------------------------------

        user.set_password(new_password)

        # ----------------------------------------------------
        # UPDATE TIMESTAMP
        # ----------------------------------------------------

        user.updated_at = datetime.utcnow()

        # ----------------------------------------------------
        # SAVE
        # ----------------------------------------------------

        try:

            db.session.commit()

            flash(
                "Your password has been changed successfully.",
                "success"
            )

        except Exception as e:

            db.session.rollback()

            current_app.logger.exception(
                "Password change failed for user ID %s: %s",
                user.id,
                e
            )

            flash(
                "Unable to change your password. Please try again.",
                "danger"
            )

        return redirect(
            url_for("main.account_settings")
        )

    # --------------------------------------------------------
    # GET REQUEST
    # --------------------------------------------------------

    return render_template(
        "backend/pages/users/account_settings.html",
        user=user
    )



# ============================================================
# ALL USERS
# ============================================================

@bp.route("/all-users")
@login_required
def all_users():

    # ========================================================
    # SUPERADMIN ONLY
    # ========================================================

    if not current_user.is_authenticated:
        flash(
            "Authentication required.",
            "danger"
        )
        return redirect(
            url_for("main.login")
        )

    if not current_user.is_superadmin():
        flash(
            "You do not have permission to access all users.",
            "danger"
        )
        return redirect(
            url_for("main.dashboard")
        )


    # ========================================================
    # ALLOWED ROLES
    # ========================================================

    allowed_roles = [
        UserRole.superadmin.value,
        UserRole.school_admin.value,
        UserRole.branch_admin.value,
        UserRole.teacher.value,
        UserRole.student.value,
        UserRole.parent.value
    ]


    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    role = request.args.get(
        "role",
        "",
        type=str
    ).strip().lower()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    verification = request.args.get(
        "verification",
        "",
        type=str
    ).strip().lower()


    # --------------------------------------------------------
    # INSTITUTION FILTER
    # --------------------------------------------------------

    institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()


    # --------------------------------------------------------
    # BRANCH FILTER
    # --------------------------------------------------------

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()


    # ========================================================
    # SAFE INTEGER CONVERSION
    # ========================================================

    selected_institution_id = None
    selected_branch_id = None


    if institution_id:

        try:
            selected_institution_id = int(
                institution_id
            )

        except (TypeError, ValueError):

            selected_institution_id = None


    if branch_id:

        try:
            selected_branch_id = int(
                branch_id
            )

        except (TypeError, ValueError):

            selected_branch_id = None


    # ========================================================
    # LOAD INSTITUTIONS
    # ========================================================

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # ========================================================
    # LOAD BRANCHES
    #
    # If institution is selected, only branches belonging
    # to that institution are loaded.
    # ========================================================

    branches_query = Branch.query


    if selected_institution_id:

        branches_query = branches_query.filter(
            Branch.institution_id ==
            selected_institution_id
        )


    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )


    # ========================================================
    # VALIDATE SELECTED INSTITUTION
    # ========================================================

    selected_institution = None

    if selected_institution_id:

        selected_institution = (
            Institution.query
            .filter(
                Institution.id ==
                selected_institution_id
            )
            .first()
        )

        if not selected_institution:

            selected_institution_id = None
            institution_id = ""

            # Reload all branches because the selected
            # institution was invalid.
            branches = (
                Branch.query
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )


    # ========================================================
    # VALIDATE SELECTED BRANCH
    #
    # Branch must belong to the selected institution.
    # ========================================================

    selected_branch = None

    if selected_branch_id:

        branch_query = Branch.query.filter(
            Branch.id ==
            selected_branch_id
        )

        if selected_institution_id:

            branch_query = branch_query.filter(
                Branch.institution_id ==
                selected_institution_id
            )

        selected_branch = (
            branch_query
            .first()
        )

        if not selected_branch:

            selected_branch_id = None
            branch_id = ""


    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        20,
        type=int
    )


    if page < 1:
        page = 1


    allowed_per_page = [
        10,
        20,
        50,
        100
    ]


    if per_page not in allowed_per_page:
        per_page = 20


    # ========================================================
    # BASE QUERY
    # ========================================================

    query = User.query


    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_pattern = f"%{search}%"


        query = query.filter(
            db.or_(

                User.username.ilike(
                    search_pattern
                ),

                User.email.ilike(
                    search_pattern
                ),

                User.fullname.ilike(
                    search_pattern
                ),

                User.phone.ilike(
                    search_pattern
                ),

                User.country.ilike(
                    search_pattern
                ),

                User.city.ilike(
                    search_pattern
                ),

                User.state.ilike(
                    search_pattern
                ),

                User.address.ilike(
                    search_pattern
                )
            )
        )


    # ========================================================
    # ROLE FILTER
    # ========================================================

    if role and role in allowed_roles:

        query = query.filter(
            User.role == role
        )


    # ========================================================
    # STATUS FILTER
    # ========================================================

    if status == "active":

        query = query.filter(
            User.status.is_(True)
        )

    elif status == "inactive":

        query = query.filter(
            User.status.is_(False)
        )


    # ========================================================
    # VERIFICATION FILTER
    # ========================================================

    if verification == "verified":

        query = query.filter(
            User.is_verified.is_(True)
        )

    elif verification == "unverified":

        query = query.filter(
            User.is_verified.is_(False)
        )


    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    if selected_institution_id:

        query = query.filter(
            User.institution_id ==
            selected_institution_id
        )


    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if selected_branch_id:

        query = query.filter(
            User.branch_id ==
            selected_branch_id
        )


    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        User.created_at.desc(),
        User.id.desc()
    )


    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )


    users = pagination.items


    # ========================================================
    # GLOBAL USER STATISTICS
    #
    # These are global because superadmin is viewing the
    # complete user management system.
    # ========================================================

    total_users = (
        User.query.count()
    )


    active_users = (
        User.query
        .filter(
            User.status.is_(True)
        )
        .count()
    )


    inactive_users = (
        User.query
        .filter(
            User.status.is_(False)
        )
        .count()
    )


    verified_users = (
        User.query
        .filter(
            User.is_verified.is_(True)
        )
        .count()
    )


    unverified_users = (
        User.query
        .filter(
            User.is_verified.is_(False)
        )
        .count()
    )


    # ========================================================
    # ROLE STATISTICS
    # ========================================================

    superadmin_count = (
        User.query
        .filter(
            User.role ==
            UserRole.superadmin.value
        )
        .count()
    )


    school_admin_count = (
        User.query
        .filter(
            User.role ==
            UserRole.school_admin.value
        )
        .count()
    )


    branch_admin_count = (
        User.query
        .filter(
            User.role ==
            UserRole.branch_admin.value
        )
        .count()
    )


    teacher_count = (
        User.query
        .filter(
            User.role ==
            UserRole.teacher.value
        )
        .count()
    )


    student_count = (
        User.query
        .filter(
            User.role ==
            UserRole.student.value
        )
        .count()
    )


    parent_count = (
        User.query
        .filter(
            User.role ==
            UserRole.parent.value
        )
        .count()
    )


    # ========================================================
    # ONLINE USER COUNT
    #
    # User is considered online when last_active is within
    # the previous 30 seconds.
    # ========================================================

    online_threshold = (
        datetime.utcnow()
        - timedelta(seconds=30)
    )


    online_users = (
        User.query
        .filter(
            User.status.is_(True),
            User.last_active.isnot(None),
            User.last_active >= online_threshold
        )
        .count()
    )


    offline_users = max(
        0,
        total_users - online_users
    )


    # ========================================================
    # FILTERED STATISTICS
    #
    # These statistics change according to the selected
    # institution and branch.
    # ========================================================

    filtered_stats_query = User.query


    if selected_institution_id:

        filtered_stats_query = (
            filtered_stats_query
            .filter(
                User.institution_id ==
                selected_institution_id
            )
        )


    if selected_branch_id:

        filtered_stats_query = (
            filtered_stats_query
            .filter(
                User.branch_id ==
                selected_branch_id
            )
        )


    # --------------------------------------------------------
    # FILTERED TOTAL
    # --------------------------------------------------------

    filtered_total_users = (
        filtered_stats_query.count()
    )


    # --------------------------------------------------------
    # FILTERED ACTIVE
    # --------------------------------------------------------

    filtered_active_users = (
        filtered_stats_query
        .filter(
            User.status.is_(True)
        )
        .count()
    )


    # --------------------------------------------------------
    # FILTERED INACTIVE
    # --------------------------------------------------------

    filtered_inactive_users = (
        filtered_stats_query
        .filter(
            User.status.is_(False)
        )
        .count()
    )


    # --------------------------------------------------------
    # FILTERED VERIFIED
    # --------------------------------------------------------

    filtered_verified_users = (
        filtered_stats_query
        .filter(
            User.is_verified.is_(True)
        )
        .count()
    )


    # --------------------------------------------------------
    # FILTERED UNVERIFIED
    # --------------------------------------------------------

    filtered_unverified_users = (
        filtered_stats_query
        .filter(
            User.is_verified.is_(False)
        )
        .count()
    )


    # ========================================================
    # FILTERED ONLINE USERS
    # ========================================================

    filtered_online_users = (
        filtered_stats_query
        .filter(
            User.status.is_(True),
            User.last_active.isnot(None),
            User.last_active >= online_threshold
        )
        .count()
    )


    filtered_offline_users = max(
        0,
        filtered_total_users -
        filtered_online_users
    )


    # ========================================================
    # FILTERED ROLE STATISTICS
    # ========================================================

    filtered_superadmin_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.superadmin.value
        )
        .count()
    )


    filtered_school_admin_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.school_admin.value
        )
        .count()
    )


    filtered_branch_admin_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.branch_admin.value
        )
        .count()
    )


    filtered_teacher_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.teacher.value
        )
        .count()
    )


    filtered_student_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.student.value
        )
        .count()
    )


    filtered_parent_count = (
        filtered_stats_query
        .filter(
            User.role ==
            UserRole.parent.value
        )
        .count()
    )


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/users/all_users.html",

        # ----------------------------------------------------
        # CURRENT LOGGED-IN USER
        # ----------------------------------------------------

        user=current_user,


        # ----------------------------------------------------
        # USERS
        # ----------------------------------------------------

        users=users,


        # ----------------------------------------------------
        # PAGINATION
        # ----------------------------------------------------

        pagination=pagination,

        page=page,

        per_page=per_page,


        # ----------------------------------------------------
        # CURRENT FILTERS
        # ----------------------------------------------------

        search=search,

        selected_role=role,

        selected_status=status,

        selected_verification=verification,

        selected_institution_id=(
            selected_institution_id
        ),

        selected_branch_id=(
            selected_branch_id
        ),


        # ----------------------------------------------------
        # INSTITUTIONS / BRANCHES
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        selected_institution=(
            selected_institution
        ),

        selected_branch=(
            selected_branch
        ),


        # ----------------------------------------------------
        # ROLE LIST
        # ----------------------------------------------------

        roles=allowed_roles,


        # ====================================================
        # GLOBAL STATISTICS
        # ====================================================

        total_users=total_users,

        active_users=active_users,

        inactive_users=inactive_users,

        verified_users=verified_users,

        unverified_users=unverified_users,


        # ----------------------------------------------------
        # GLOBAL ONLINE STATISTICS
        # ----------------------------------------------------

        online_users=online_users,

        offline_users=offline_users,


        # ====================================================
        # GLOBAL ROLE STATISTICS
        # ====================================================

        superadmin_count=superadmin_count,

        school_admin_count=school_admin_count,

        branch_admin_count=branch_admin_count,

        teacher_count=teacher_count,

        student_count=student_count,

        parent_count=parent_count,


        # ====================================================
        # FILTERED STATISTICS
        # ====================================================

        filtered_total_users=(
            filtered_total_users
        ),

        filtered_active_users=(
            filtered_active_users
        ),

        filtered_inactive_users=(
            filtered_inactive_users
        ),

        filtered_verified_users=(
            filtered_verified_users
        ),

        filtered_unverified_users=(
            filtered_unverified_users
        ),


        # ----------------------------------------------------
        # FILTERED ONLINE STATISTICS
        # ----------------------------------------------------

        filtered_online_users=(
            filtered_online_users
        ),

        filtered_offline_users=(
            filtered_offline_users
        ),


        # ----------------------------------------------------
        # FILTERED ROLE STATISTICS
        # ----------------------------------------------------

        filtered_superadmin_count=(
            filtered_superadmin_count
        ),

        filtered_school_admin_count=(
            filtered_school_admin_count
        ),

        filtered_branch_admin_count=(
            filtered_branch_admin_count
        ),

        filtered_teacher_count=(
            filtered_teacher_count
        ),

        filtered_student_count=(
            filtered_student_count
        ),

        filtered_parent_count=(
            filtered_parent_count
        )
    )


