# ============================================================
# BRANCH IMAGE UPLOAD HELPER
# ============================================================
def upload_branch_image(file, folder="branches"):
    """
    Upload one branch image to Cloudinary.

    Cloudinary configuration is expected to be configured
    globally elsewhere in the application.

    Returns:
        secure_url or None

    Raises:
        ValueError for invalid files
        RuntimeError for upload/configuration errors
    """

    # ========================================================
    # NO FILE
    # ========================================================

    if not file:
        return None

    if not file.filename:
        return None


    # ========================================================
    # ALLOWED EXTENSIONS
    # ========================================================

    allowed_extensions = {
        "jpg",
        "jpeg",
        "png",
        "webp",
        "gif"
    }


    filename = file.filename.strip()


    if "." not in filename:

        raise ValueError(
            "Invalid image file."
        )


    extension = (
        filename
        .rsplit(".", 1)[1]
        .lower()
    )


    if extension not in allowed_extensions:

        raise ValueError(
            "Only JPG, JPEG, PNG, WEBP and GIF images are allowed."
        )


    # ========================================================
    # ALLOWED MIME TYPES
    # ========================================================

    allowed_mimetypes = {
        "image/jpeg",
        "image/png",
        "image/webp",
        "image/gif"
    }


    if file.mimetype not in allowed_mimetypes:

        raise ValueError(
            "Invalid image type."
        )


    # ========================================================
    # UPLOAD TO GLOBAL CLOUDINARY CONFIGURATION
    # ========================================================

    try:

        result = cloudinary.uploader.upload(

            file,

            folder=folder,

            resource_type="image",

            use_filename=True,

            unique_filename=True,

            overwrite=False,

            transformation=[
                {
                    "quality": "auto",
                    "fetch_format": "auto"
                }
            ]
        )


    except Exception as e:

        raise RuntimeError(
            f"Cloudinary upload failed: {str(e)}"
        )


    # ========================================================
    # GET SECURE URL
    # ========================================================

    secure_url = result.get(
        "secure_url"
    )


    if not secure_url:

        raise RuntimeError(
            "Cloudinary upload completed but no secure URL was returned."
        )


    return secure_url


