def _get_user_institution_id():

    # --------------------------------------------------------
    # Keep using your existing helper if already defined.
    # --------------------------------------------------------

    if hasattr(current_user, "institution_id"):
        return current_user.institution_id

    return None


# ============================================================
# ALL CLASSES
# ============================================================

@bp.route("/classes")
@login_required
def all_classes():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = _get_user_institution_id()

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # BRANCH ADMIN SECURITY
    #
    # Branch admin MUST have:
    #   institution_id
    #   branch_id
    # ========================================================

    if role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # TEACHER SECURITY
    # ========================================================

    if role == "teacher":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # REQUEST FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    selected_institution_id = request.args.get(
        "institution_id",
        type=int
    )

    selected_branch_id = request.args.get(
        "branch_id",
        type=int
    )

    selected_program_id = request.args.get(
        "program_id",
        type=int
    )

    selected_academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    selected_status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        20,
        type=int
    )

    if per_page not in [10, 20, 50, 100]:
        per_page = 20

    if page < 1:
        page = 1

    # ========================================================
    # BASE QUERY
    # ========================================================

    base_query = Class.query

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if user_institution_id is not None:

        base_query = base_query.filter(
            Class.institution_id
            == user_institution_id
        )

    # ========================================================
    # BRANCH SECURITY
    #
    # IMPORTANT:
    #
    # branch_admin / teacher:
    #   ONLY their own branch
    #
    # school_admin:
    #   all branches inside institution
    #
    # superadmin:
    #   all branches
    # ========================================================

    if role in {
        "branch_admin",
        "teacher",
    }:

        base_query = base_query.filter(
            Class.branch_id
            == user_branch_id
        )

    # ========================================================
    # STATISTICS
    #
    # Statistics must use the same security scope.
    # ========================================================

    total_classes = (
        base_query
        .count()
    )

    active_classes = (
        base_query
        .filter(
            Class.status == "active"
        )
        .count()
    )

    inactive_classes = (
        base_query
        .filter(
            Class.status == "inactive"
        )
        .count()
    )

    completed_classes = (
        base_query
        .filter(
            Class.status == "completed"
        )
        .count()
    )

    # ========================================================
    # CAPACITY STATISTICS
    # ========================================================

    classes_with_capacity = (
        base_query
        .filter(
            Class.capacity.isnot(None)
        )
        .count()
    )

    classes_without_capacity = (
        base_query
        .filter(
            Class.capacity.is_(None)
        )
        .count()
    )

    # ========================================================
    # FILTERED QUERY
    # ========================================================

    query = base_query

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_term = f"%{search}%"

        query = query.filter(
            or_(
                Class.name.ilike(
                    search_term
                ),

                Class.code.ilike(
                    search_term
                ),

                Class.level.ilike(
                    search_term
                ),

                Class.description.ilike(
                    search_term
                ),

                Class.institution.has(
                    Institution.name.ilike(
                        search_term
                    )
                ),

                Class.branch.has(
                    Branch.name.ilike(
                        search_term
                    )
                ),

                Class.program.has(
                    Program.name.ilike(
                        search_term
                    )
                ),

                Class.program.has(
                    Program.code.ilike(
                        search_term
                    )
                ),

                Class.academic_year.has(
                    AcademicYear.name.ilike(
                        search_term
                    )
                )
            )
        )

    # ========================================================
    # INSTITUTION FILTER
    #
    # SECURITY:
    # Non-superadmin cannot switch institution.
    # ========================================================

    if role == "superadmin":

        if selected_institution_id:

            query = query.filter(
                Class.institution_id
                == selected_institution_id
            )

    else:

        # Force user's institution

        if user_institution_id is not None:

            query = query.filter(
                Class.institution_id
                == user_institution_id
            )

            selected_institution_id = (
                user_institution_id
            )

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if role in {
        "branch_admin",
        "teacher",
    }:

        # NEVER allow them to select another branch.

        query = query.filter(
            Class.branch_id
            == user_branch_id
        )

        selected_branch_id = (
            user_branch_id
        )

    else:

        # superadmin / school_admin

        if selected_branch_id:

            query = query.filter(
                Class.branch_id
                == selected_branch_id
            )

    # ========================================================
    # PROGRAM FILTER
    # ========================================================

    if selected_program_id:

        query = query.filter(
            Class.program_id
            == selected_program_id
        )

    # ========================================================
    # ACADEMIC YEAR FILTER
    # ========================================================

    if selected_academic_year_id:

        query = query.filter(
            Class.academic_year_id
            == selected_academic_year_id
        )

    # ========================================================
    # STATUS FILTER
    # ========================================================

    allowed_statuses = {
        "active",
        "inactive",
        "completed"
    }

    if selected_status in allowed_statuses:

        query = query.filter(
            Class.status
            == selected_status
        )

    else:

        selected_status = ""

    # ========================================================
    # ORDERING
    # ========================================================

    query = query.order_by(
        Class.created_at.desc(),
        Class.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    classes = pagination.items

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institution_query = (
        Institution.query
    )

    # superadmin can see all institutions
    # everyone else sees only own institution

    if role != "superadmin":

        if user_institution_id is not None:

            institution_query = (
                institution_query
                .filter(
                    Institution.id
                    == user_institution_id
                )
            )

    institutions = (
        institution_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branch_query = (
        Branch.query
    )

    # --------------------------------------------------------
    # Institution scope
    # --------------------------------------------------------

    if role != "superadmin":

        if user_institution_id is not None:

            branch_query = (
                branch_query
                .filter(
                    Branch.institution_id
                    == user_institution_id
                )
            )

    # --------------------------------------------------------
    # Branch admin / teacher:
    # ONLY OWN BRANCH
    # --------------------------------------------------------

    if role in {
        "branch_admin",
        "teacher",
    }:

        branch_query = (
            branch_query
            .filter(
                Branch.id
                == user_branch_id
            )
        )

    branches = (
        branch_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    program_query = (
        Program.query
    )

    # Institution security

    if role != "superadmin":

        if user_institution_id is not None:

            program_query = (
                program_query
                .filter(
                    Program.institution_id
                    == user_institution_id
                )
            )

    # --------------------------------------------------------
    # Branch admin / teacher:
    #
    # Program.branch_id may be NULL because your system
    # supports programs shared across branches.
    #
    # Therefore:
    #   own branch program
    #   OR institution-level/shared program
    # --------------------------------------------------------

    if role in {
        "branch_admin",
        "teacher",
    }:

        program_query = (
            program_query
            .filter(
                or_(
                    Program.branch_id
                    == user_branch_id,

                    Program.branch_id.is_(None)
                )
            )
        )

    programs = (
        program_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = (
        AcademicYear.query
    )

    # --------------------------------------------------------
    # Institution security
    # --------------------------------------------------------

    if (
        role != "superadmin"
        and user_institution_id is not None
        and hasattr(
            AcademicYear,
            "institution_id"
        )
    ):

        academic_year_query = (
            academic_year_query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/classes/all_classes.html",

        classes=classes,
        pagination=pagination,

        institutions=institutions,
        branches=branches,
        programs=programs,
        academic_years=academic_years,

        search=search,

        selected_institution_id=(
            selected_institution_id
            if selected_institution_id
            else ""
        ),

        selected_branch_id=(
            selected_branch_id
            if selected_branch_id
            else ""
        ),

        selected_program_id=(
            selected_program_id
            if selected_program_id
            else ""
        ),

        selected_academic_year_id=(
            selected_academic_year_id
            if selected_academic_year_id
            else ""
        ),

        selected_status=selected_status,

        per_page=per_page,

        total_classes=total_classes,
        active_classes=active_classes,
        inactive_classes=inactive_classes,
        completed_classes=completed_classes,

        classes_with_capacity=classes_with_capacity,
        classes_without_capacity=classes_without_capacity,

        user=current_user,

        current_role=role
    )




# ============================================================
# ADD CLASS
# ============================================================
@bp.route(
    "/classes/add",
    methods=["GET", "POST"]
)
@login_required
def add_class():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        # "teacher",   # Ku dar haddii teacher loo oggol yahay
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    user_institution_id = (
        _get_user_institution_id()
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    if role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # SCHOOL ADMIN SECURITY
    # ========================================================

    if role == "school_admin":

        if user_institution_id is None:
            abort(403)

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institution_query = Institution.query

    if (
        role != "superadmin"
        and user_institution_id is not None
    ):

        institution_query = (
            institution_query
            .filter(
                Institution.id
                == user_institution_id
            )
        )

    institutions = (
        institution_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        name = request.form.get(
            "name",
            "",
            type=str
        ).strip()

        code = request.form.get(
            "code",
            "",
            type=str
        ).strip()

        level = request.form.get(
            "level",
            "",
            type=str
        ).strip()

        capacity_raw = request.form.get(
            "capacity",
            "",
            type=str
        ).strip()

        description = request.form.get(
            "description",
            "",
            type=str
        ).strip()

        status = request.form.get(
            "status",
            "active",
            type=str
        ).strip().lower()

        # ====================================================
        # NORMALIZE
        # ====================================================

        code = code.upper()

        if not level:
            level = None

        if not description:
            description = None

        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if not institution_id:

            flash(
                "Institution is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        if not branch_id:

            flash(
                "Branch is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        if not program_id:

            flash(
                "Program is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        if not academic_year_id:

            flash(
                "Academic year is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        if not name:

            flash(
                "Class name is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        if not code:

            flash(
                "Class code is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # STATUS VALIDATION
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "completed"
        }

        if status not in allowed_statuses:

            flash(
                "Invalid class status.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # CAPACITY
        # ====================================================

        capacity = None

        if capacity_raw:

            try:

                capacity = int(
                    capacity_raw
                )

            except ValueError:

                flash(
                    "Capacity must be a valid number.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_class"
                    )
                )

            if capacity < 0:

                flash(
                    "Capacity cannot be negative.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_class"
                    )
                )

        # ====================================================
        # INSTITUTION SECURITY
        # ====================================================

        if (
            role != "superadmin"
            and user_institution_id is not None
            and institution_id
            != user_institution_id
        ):

            flash(
                "You are not authorized to create a class for this institution.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.all_classes"
                )
            )

        # ====================================================
        # BRANCH SECURITY
        # ====================================================

        # branch_admin MUST use own branch.
        if role == "branch_admin":

            if branch_id != user_branch_id:

                flash(
                    "You are not authorized to create a class for this branch.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.all_classes"
                    )
                )

        # ====================================================
        # TEACHER SECURITY
        # ====================================================

        if role == "teacher":

            if (
                user_branch_id is None
                or branch_id != user_branch_id
            ):

                flash(
                    "You are not authorized to create a class for this branch.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.all_classes"
                    )
                )

        # ====================================================
        # VERIFY INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id
                == institution_id
            )
            .first()
        )

        if institution is None:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # VERIFY BRANCH
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id
                == branch_id
            )
            .first()
        )

        if branch is None:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # Branch MUST belong to institution.
        if (
            branch.institution_id
            != institution_id
        ):

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # VERIFY PROGRAM
        # ====================================================

        program = (
            Program.query
            .filter(
                Program.id
                == program_id
            )
            .first()
        )

        if program is None:

            flash(
                "Selected program was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # Program MUST belong to institution.
        if (
            program.institution_id
            != institution_id
        ):

            flash(
                "Selected program does not belong to the selected institution.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # PROGRAM BRANCH SECURITY
        # ====================================================

        # Program can be:
        #
        # 1. Branch-specific
        # 2. Shared across branches (branch_id = NULL)
        #
        # branch_admin can use only:
        # own branch program OR shared program.

        if role == "branch_admin":

            program_branch_id = getattr(
                program,
                "branch_id",
                None
            )

            if (
                program_branch_id is not None
                and program_branch_id
                != user_branch_id
            ):

                flash(
                    "This program is not available for your branch.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_class"
                    )
                )

        # ====================================================
        # TEACHER PROGRAM SECURITY
        # ====================================================

        if role == "teacher":

            program_branch_id = getattr(
                program,
                "branch_id",
                None
            )

            if (
                program_branch_id is not None
                and program_branch_id
                != user_branch_id
            ):

                flash(
                    "This program is not available for your branch.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_class"
                    )
                )

        # ====================================================
        # VERIFY ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
            .first()
        )

        if academic_year is None:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # ACADEMIC YEAR INSTITUTION SECURITY
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_year_institution_id = getattr(
                academic_year,
                "institution_id",
                None
            )

            if (
                academic_year_institution_id
                is not None
                and academic_year_institution_id
                != institution_id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_class"
                    )
                )

        # ====================================================
        # DUPLICATE CODE
        # ====================================================

        existing_code = (
            Class.query
            .filter(
                Class.branch_id
                == branch_id,

                Class.academic_year_id
                == academic_year_id,

                Class.code
                == code
            )
            .first()
        )

        if existing_code:

            flash(
                "A class with this code already exists in this branch and academic year.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # DUPLICATE NAME
        # ====================================================

        existing_name = (
            Class.query
            .filter(
                Class.branch_id
                == branch_id,

                Class.academic_year_id
                == academic_year_id,

                Class.name
                == name
            )
            .first()
        )

        if existing_name:

            flash(
                "A class with this name already exists in this branch and academic year.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        # ====================================================
        # CREATE CLASS
        # ====================================================

        new_class = Class(

            institution_id=institution_id,

            branch_id=branch_id,

            program_id=program_id,

            academic_year_id=academic_year_id,

            name=name,

            code=code,

            level=level,

            capacity=capacity,

            description=description,

            status=status
        )

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(
                new_class
            )

            db.session.commit()

            flash(
                "Class created successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.view_class",
                    class_id=new_class.id
                )
            )

        except IntegrityError:

            db.session.rollback()

            flash(
                "Unable to create class. The class code or name may already exist.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Error creating class"
            )

            flash(
                "An unexpected error occurred while creating the class.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_class"
                )
            )

    # ========================================================
    # GET DATA — BRANCHES
    # ========================================================

    branch_query = Branch.query

    if (
        role != "superadmin"
        and user_institution_id is not None
    ):

        branch_query = (
            branch_query
            .filter(
                Branch.institution_id
                == user_institution_id
            )
        )

    # branch_admin sees ONLY own branch.
    if role == "branch_admin":

        branch_query = (
            branch_query
            .filter(
                Branch.id
                == user_branch_id
            )
        )

    # teacher, if enabled, also sees own branch.
    if role == "teacher":

        branch_query = (
            branch_query
            .filter(
                Branch.id
                == user_branch_id
            )
        )

    branches = (
        branch_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # GET DATA — PROGRAMS
    # ========================================================

    program_query = Program.query

    if (
        role != "superadmin"
        and user_institution_id is not None
    ):

        program_query = (
            program_query
            .filter(
                Program.institution_id
                == user_institution_id
            )
        )

    # branch_admin / teacher:
    #
    # own branch programs
    # OR shared programs (branch_id IS NULL)

    if role in {
        "branch_admin",
        "teacher"
    }:

        program_query = (
            program_query
            .filter(
                or_(
                    Program.branch_id
                    == user_branch_id,

                    Program.branch_id.is_(None)
                )
            )
        )

    programs = (
        program_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # GET DATA — ACADEMIC YEARS
    # ========================================================

    academic_year_query = (
        AcademicYear.query
    )

    if (
        role != "superadmin"
        and user_institution_id is not None
        and hasattr(
            AcademicYear,
            "institution_id"
        )
    ):

        academic_year_query = (
            academic_year_query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/classes/add_class.html",

        institutions=institutions,

        branches=branches,

        programs=programs,

        academic_years=academic_years,

        user=current_user,

        current_role=role,

        user_institution_id=user_institution_id,

        user_branch_id=user_branch_id
    )

# ============================================================
# VIEW CLASS
# ============================================================

@bp.route(
    "/classes/<int:class_id>"
)
@login_required
def view_class(class_id):

    # ========================================================
    # FIND CLASS
    # ========================================================

    class_obj = (
        Class.query
        .filter(
            Class.id == class_id
        )
        .first_or_404()
    )

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    user_institution_id = (
        _get_user_institution_id()
    )

    if (
        user_institution_id is not None
        and class_obj.institution_id
        != user_institution_id
    ):

        flash(
            "You are not authorized to view this class.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_classes"
            )
        )

    # ========================================================
    # RELATED DATA
    # ========================================================

    institution = (
        class_obj.institution
    )

    branch = (
        class_obj.branch
    )

    program = (
        class_obj.program
    )

    academic_year = (
        class_obj.academic_year
    )

    # ========================================================
    # RELATED CLASSES
    # SAME BRANCH + ACADEMIC YEAR
    # ========================================================

    related_classes = (
        Class.query
        .filter(

            Class.branch_id
            == class_obj.branch_id,

            Class.academic_year_id
            == class_obj.academic_year_id,

            Class.id
            != class_obj.id
        )
        .order_by(
            Class.name.asc(),
            Class.id.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAM CLASSES
    # ========================================================

    program_classes = (
        Class.query
        .filter(

            Class.program_id
            == class_obj.program_id,

            Class.id
            != class_obj.id
        )
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASS STATS
    # ========================================================

    total_related_classes = (
        len(related_classes) + 1
    )

    total_program_classes = (
        len(program_classes) + 1
    )

    return render_template(
        "backend/pages/classes/view_class.html",

        class_obj=class_obj,

        institution=institution,

        branch=branch,

        program=program,

        academic_year=academic_year,

        related_classes=related_classes,

        program_classes=program_classes,

        total_related_classes=(
            total_related_classes
        ),

        total_program_classes=(
            total_program_classes
        ),

        user=current_user
    )


# ============================================================
# EDIT CLASS
# ============================================================
@bp.route(
    "/classes/<int:class_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_class(class_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        # "teacher",  # Ku dar haddii teacher loo oggol yahay edit
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    user_institution_id = (
        _get_user_institution_id()
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE REQUIREMENTS
    # ========================================================

    if role == "school_admin":

        if user_institution_id is None:
            abort(403)

    if role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # FIND CLASS
    # ========================================================

    class_obj = (
        Class.query
        .filter(
            Class.id == class_id
        )
        .first_or_404()
    )

    # ========================================================
    # EXISTING CLASS INSTITUTION SECURITY
    # ========================================================

    if (
        role != "superadmin"
        and user_institution_id is not None
        and class_obj.institution_id
        != user_institution_id
    ):

        flash(
            "You are not authorized to edit this class.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_classes"
            )
        )

    # ========================================================
    # EXISTING CLASS BRANCH SECURITY
    # ========================================================

    if role == "branch_admin":

        if (
            class_obj.branch_id
            != user_branch_id
        ):

            flash(
                "You are not authorized to edit a class from another branch.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.all_classes"
                )
            )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        name = request.form.get(
            "name",
            "",
            type=str
        ).strip()

        level = request.form.get(
            "level",
            "",
            type=str
        ).strip()

        capacity_raw = request.form.get(
            "capacity",
            "",
            type=str
        ).strip()

        description = request.form.get(
            "description",
            "",
            type=str
        ).strip()

        status = request.form.get(
            "status",
            "active",
            type=str
        ).strip().lower()

        # ====================================================
        # NORMALIZE
        # ====================================================

        if not level:
            level = None

        if not description:
            description = None

        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if not institution_id:

            flash(
                "Institution is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        if not branch_id:

            flash(
                "Branch is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        if not program_id:

            flash(
                "Program is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        if not academic_year_id:

            flash(
                "Academic year is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        if not name:

            flash(
                "Class name is required.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # GENERATE CLASS CODE
        # ====================================================

        import re
        import unicodedata

        def generate_class_code(value):

            value = unicodedata.normalize(
                "NFD",
                value
            ).encode(
                "ascii",
                "ignore"
            ).decode(
                "ascii"
            )

            value = value.upper()

            value = value.replace(
                "&",
                " AND "
            )

            value = value.replace(
                "+",
                " PLUS "
            )

            value = re.sub(
                r"[^A-Z0-9\s-]",
                "",
                value
            )

            value = re.sub(
                r"\s+",
                "-",
                value.strip()
            )

            value = re.sub(
                r"-+",
                "-",
                value
            )

            value = value.strip("-")

            return value[:50]

        code = generate_class_code(
            name
        )

        # ====================================================
        # CODE VALIDATION
        # ====================================================

        if not code:

            flash(
                "Unable to generate a valid class code from the class name.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # STATUS VALIDATION
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "completed"
        }

        if status not in allowed_statuses:

            flash(
                "Invalid class status.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # CAPACITY
        # ====================================================

        capacity = None

        if capacity_raw:

            try:

                capacity = int(
                    capacity_raw
                )

            except (
                ValueError,
                TypeError
            ):

                flash(
                    "Capacity must be a valid whole number.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_class",
                        class_id=class_id
                    )
                )

            if capacity < 0:

                flash(
                    "Capacity cannot be negative.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_class",
                        class_id=class_id
                    )
                )

        # ====================================================
        # INSTITUTION SECURITY
        # ====================================================

        if (
            role != "superadmin"
            and user_institution_id is not None
            and institution_id
            != user_institution_id
        ):

            flash(
                "You are not authorized to move this class to another institution.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.all_classes"
                )
            )

        # ====================================================
        # BRANCH SECURITY
        # ====================================================

        # Branch admin cannot move class
        # to another branch.

        if role == "branch_admin":

            if branch_id != user_branch_id:

                flash(
                    "You are not authorized to move this class to another branch.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.all_classes"
                    )
                )

        # ====================================================
        # VERIFY INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id
                == institution_id
            )
            .first()
        )

        if institution is None:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # VERIFY BRANCH
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id
                == branch_id
            )
            .first()
        )

        if branch is None:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # Branch must belong to selected institution.
        if (
            branch.institution_id
            != institution_id
        ):

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # VERIFY PROGRAM
        # ====================================================

        program = (
            Program.query
            .filter(
                Program.id
                == program_id
            )
            .first()
        )

        if program is None:

            flash(
                "Selected program was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # Program must belong to institution.
        if (
            program.institution_id
            != institution_id
        ):

            flash(
                "Selected program does not belong to the selected institution.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # PROGRAM BRANCH SECURITY
        # ====================================================

        program_branch_id = getattr(
            program,
            "branch_id",
            None
        )

        # branch_admin:
        #
        # own branch program
        # OR shared program

        if role == "branch_admin":

            if (
                program_branch_id is not None
                and program_branch_id
                != user_branch_id
            ):

                flash(
                    "This program is not available for your branch.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_class",
                        class_id=class_id
                    )
                )

        # ====================================================
        # VERIFY ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
            .first()
        )

        if academic_year is None:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # ACADEMIC YEAR INSTITUTION SECURITY
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_year_institution_id = getattr(
                academic_year,
                "institution_id",
                None
            )

            if (
                academic_year_institution_id
                is not None
                and academic_year_institution_id
                != institution_id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_class",
                        class_id=class_id
                    )
                )

        # ====================================================
        # DUPLICATE CODE
        # ====================================================

        duplicate_code = (
            Class.query
            .filter(
                Class.branch_id
                == branch_id,

                Class.academic_year_id
                == academic_year_id,

                Class.code
                == code,

                Class.id
                != class_obj.id
            )
            .first()
        )

        if duplicate_code:

            flash(
                f'Another class with code "{code}" already exists in this branch and academic year.',
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # DUPLICATE NAME
        # ====================================================

        duplicate_name = (
            Class.query
            .filter(
                Class.branch_id
                == branch_id,

                Class.academic_year_id
                == academic_year_id,

                Class.name
                == name,

                Class.id
                != class_obj.id
            )
            .first()
        )

        if duplicate_name:

            flash(
                f'Another class named "{name}" already exists in this branch and academic year.',
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        # ====================================================
        # UPDATE CLASS
        # ====================================================

        class_obj.institution_id = (
            institution_id
        )

        class_obj.branch_id = (
            branch_id
        )

        class_obj.program_id = (
            program_id
        )

        class_obj.academic_year_id = (
            academic_year_id
        )

        class_obj.name = (
            name
        )

        class_obj.code = (
            code
        )

        class_obj.level = (
            level
        )

        class_obj.capacity = (
            capacity
        )

        class_obj.description = (
            description
        )

        class_obj.status = (
            status
        )

        # ====================================================
        # COMMIT
        # ====================================================

        try:

            db.session.commit()

            flash(
                "Class updated successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.view_class",
                    class_id=class_obj.id
                )
            )

        except IntegrityError:

            db.session.rollback()

            flash(
                "Unable to update class. The class code or name may already exist.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Error updating class"
            )

            flash(
                "An unexpected error occurred while updating the class.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_class",
                    class_id=class_id
                )
            )

    # ========================================================
    # GET DATA
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institution_query = (
        Institution.query
    )

    if (
        role != "superadmin"
        and user_institution_id is not None
    ):

        institution_query = (
            institution_query
            .filter(
                Institution.id
                == user_institution_id
            )
        )

    institutions = (
        institution_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branch_query = Branch.query

    if (
        role != "superadmin"
        and user_institution_id is not None
    ):

        branch_query = (
            branch_query
            .filter(
                Branch.institution_id
                == user_institution_id
            )
        )

    # Branch admin sees own branch only.
    if role == "branch_admin":

        branch_query = (
            branch_query
            .filter(
                Branch.id
                == user_branch_id
            )
        )

    branches = (
        branch_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    program_query = Program.query

    if (
        role != "superadmin"
        and user_institution_id is not None
    ):

        program_query = (
            program_query
            .filter(
                Program.institution_id
                == user_institution_id
            )
        )

    # Branch admin:
    #
    # own branch programs
    # OR shared programs.

    if role == "branch_admin":

        program_query = (
            program_query
            .filter(
                or_(
                    Program.branch_id
                    == user_branch_id,

                    Program.branch_id.is_(None)
                )
            )
        )

    programs = (
        program_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = (
        AcademicYear.query
    )

    if (
        role != "superadmin"
        and user_institution_id is not None
        and hasattr(
            AcademicYear,
            "institution_id"
        )
    ):

        academic_year_query = (
            academic_year_query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/classes/edit_class.html",

        class_obj=class_obj,

        institutions=institutions,

        branches=branches,

        programs=programs,

        academic_years=academic_years,

        user=current_user,

        current_role=role,

        user_institution_id=user_institution_id,

        user_branch_id=user_branch_id
    )


# ============================================================
# DELETE CLASS
# ============================================================

@bp.route(
    "/classes/<int:class_id>/delete",
    methods=["POST"]
)
@login_required
def delete_class(class_id):

    # ========================================================
    # FIND CLASS
    # ========================================================

    class_obj = (
        Class.query
        .filter(
            Class.id == class_id
        )
        .first_or_404()
    )

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    user_institution_id = (
        _get_user_institution_id()
    )

    if (
        user_institution_id is not None
        and class_obj.institution_id
        != user_institution_id
    ):

        return jsonify(
            {
                "success": False,
                "message": (
                    "You are not authorized "
                    "to delete this class."
                )
            }
        ), 403

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            class_obj
        )

        db.session.commit()

        return jsonify(
            {
                "success": True,
                "message": (
                    "Class deleted successfully."
                )
            }
        )

    except IntegrityError:

        db.session.rollback()

        return jsonify(
            {
                "success": False,
                "message": (
                    "This class cannot be deleted "
                    "because it is linked to other "
                    "records."
                )
            }
        ), 409

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "Error deleting class"
        )

        return jsonify(
            {
                "success": False,
                "message": (
                    "An unexpected error occurred "
                    "while deleting the class."
                )
            }
        ), 500



# ============================================================
# SECTION ROUTES
# PostgreSQL / Neon
# ============================================================

def generate_section_code(name):
    """
    Generate automatic section code.

    Examples:
        A           -> A
        B           -> B
        Morning A   -> MORNING-A
        Evening B   -> EVENING-B
        Section 1   -> SECTION-1
    """

    if not name:
        return ""

    value = unicodedata.normalize(
        "NFD",
        name
    ).encode(
        "ascii",
        "ignore"
    ).decode("ascii")

    value = value.upper()

    value = value.replace(
        "&",
        " AND "
    )

    value = value.replace(
        "+",
        " PLUS "
    )

    value = re.sub(
        r"[^A-Z0-9\s-]",
        "",
        value
    )

    value = re.sub(
        r"\s+",
        "-",
        value.strip()
    )

    value = re.sub(
        r"-+",
        "-",
        value
    )

    value = value.strip("-")

    return value[:50]


# ============================================================
# USER INSTITUTION HELPER
# ============================================================

def _section_user_institution_id():
    """
    Use the existing application institution helper.

    Superadmin/global users:
        returns None

    Institution-scoped users:
        returns institution ID
    """

    return _get_user_institution_id()


# ============================================================
# COMMON SECTION TEMPLATE CONTEXT
# ============================================================

def _section_template_context(
    institutions=None,
    branches=None,
    classes=None,
    academic_years=None,
):
    """
    Common template context.

    IMPORTANT:
        user=current_user is intentionally passed to every
        Section template.
    """

    return {
        "institutions": institutions or [],
        "branches": branches or [],
        "classes": classes or [],
        "academic_years": academic_years or [],
        "user": current_user,
    }


# ============================================================
# GET SECTION
# Institution scoped
# ============================================================

def _get_section_or_404(section_id):

    institution_id = _section_user_institution_id()

    query = Section.query

    # --------------------------------------------------------
    # Institution security
    # --------------------------------------------------------

    if institution_id is not None:

        query = query.filter(
            Section.institution_id == institution_id
        )

    return query.filter(
        Section.id == section_id
    ).first_or_404()


# ============================================================
# GET ALLOWED INSTITUTIONS
# ============================================================

def _section_allowed_institutions():

    institution_id = _section_user_institution_id()

    # --------------------------------------------------------
    # Superadmin / global user
    # --------------------------------------------------------

    if institution_id is None:

        return (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # --------------------------------------------------------
    # Institution-scoped user
    # --------------------------------------------------------

    return (
        Institution.query
        .filter(
            Institution.id == institution_id
        )
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


# ============================================================
# GET SECTION FORM DATA
# ============================================================

def _get_section_form_data():

    user_institution_id = (
        _section_user_institution_id()
    )

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institutions = (
        _section_allowed_institutions()
    )

    allowed_institution_ids = [
        item.id
        for item in institutions
    ]

    # ========================================================
    # BRANCHES
    # ========================================================

    if allowed_institution_ids:

        branches = (
            Branch.query
            .filter(
                Branch.institution_id.in_(
                    allowed_institution_ids
                )
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        branches = []

    # ========================================================
    # CLASSES
    # ========================================================

    if allowed_institution_ids:

        classes = (
            Class.query
            .filter(
                Class.institution_id.in_(
                    allowed_institution_ids
                )
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    else:

        classes = []

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = AcademicYear.query

    if (
        hasattr(
            AcademicYear,
            "institution_id"
        )
        and user_institution_id is not None
    ):

        academic_year_query = (
            academic_year_query.filter(
                AcademicYear.institution_id
                == user_institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    return (
        institutions,
        branches,
        classes,
        academic_years,
    )


# ============================================================
# ALL SECTIONS
# ============================================================
@bp.route(
    "/sections",
    methods=["GET"]
)
@login_required
def all_sections():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = (
        _section_user_institution_id()
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE REQUIREMENTS
    # ========================================================

    if role == "school_admin":

        if user_institution_id is None:
            abort(403)

    if role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    if role == "teacher":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    class_id = request.args.get(
        "class_id",
        "",
        type=str
    ).strip()

    academic_year_id = request.args.get(
        "academic_year_id",
        "",
        type=str
    ).strip()

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = Section.query

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if (
        role != "superadmin"
        and user_institution_id is not None
    ):

        query = query.filter(
            Section.institution_id
            == user_institution_id
        )

        # Prevent URL manipulation.
        institution_id = str(
            user_institution_id
        )

    elif role == "superadmin" and institution_id:

        try:

            institution_id_int = int(
                institution_id
            )

            query = query.filter(
                Section.institution_id
                == institution_id_int
            )

        except (
            ValueError,
            TypeError
        ):

            institution_id = ""

    # ========================================================
    # BRANCH SECURITY
    # ========================================================

    # branch_admin and teacher:
    # OWN BRANCH ONLY.
    #
    # This is the important security layer.
    # Even if the URL contains another branch_id,
    # the query still cannot return another branch.

    if role in {
        "branch_admin",
        "teacher",
    }:

        query = query.filter(
            Section.branch_id
            == user_branch_id
        )

        branch_id = str(
            user_branch_id
        )

    elif branch_id:

        # superadmin / school_admin
        # may use branch filter,
        # but only within the institution scope.

        try:

            branch_id_int = int(
                branch_id
            )

            query = query.filter(
                Section.branch_id
                == branch_id_int
            )

        except (
            ValueError,
            TypeError
        ):

            branch_id = ""

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        pattern = f"%{search}%"

        query = query.filter(
            db.or_(
                Section.name.ilike(
                    pattern
                ),

                Section.code.ilike(
                    pattern
                ),

                Section.description.ilike(
                    pattern
                ),
            )
        )

    # ========================================================
    # STATUS
    # ========================================================

    allowed_statuses = {
        "active",
        "inactive",
        "suspended",
    }

    if status in allowed_statuses:

        query = query.filter(
            Section.status
            == status
        )

    else:

        status = ""

    # ========================================================
    # CLASS FILTER
    # ========================================================

    if class_id:

        try:

            class_id_int = int(
                class_id
            )

            query = query.filter(
                Section.class_id
                == class_id_int
            )

        except (
            ValueError,
            TypeError
        ):

            class_id = ""

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        try:

            academic_year_id_int = int(
                academic_year_id
            )

            query = query.filter(
                Section.academic_year_id
                == academic_year_id_int
            )

        except (
            ValueError,
            TypeError
        ):

            academic_year_id = ""

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        Section.created_at.desc(),
        Section.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    per_page = request.args.get(
        "per_page",
        20,
        type=int
    )

    if per_page not in {
        10,
        20,
        50,
        100,
    }:

        per_page = 20

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    sections = pagination.items

    # ========================================================
    # FORM / FILTER DATA
    # ========================================================

    (
        institutions,
        branches,
        classes,
        academic_years,
    ) = _get_section_form_data()

    # ========================================================
    # ADDITIONAL FILTER DATA SECURITY
    # ========================================================
    #
    # Haddii helper-ka _get_section_form_data()
    # uu soo celiyo branches/classes badan,
    # waxaan halkan ku xaddideynaa kuwa muuqda.
    #
    # Database query-ga kore ayaa ah security-ga dhabta ah.
    #

    if role in {
        "branch_admin",
        "teacher",
    }:

        branches = [
            branch
            for branch in branches
            if branch.id
            == user_branch_id
        ]

        classes = [
            class_obj
            for class_obj in classes
            if class_obj.branch_id
            == user_branch_id
        ]

    elif (
        role != "superadmin"
        and user_institution_id is not None
    ):

        branches = [
            branch
            for branch in branches
            if branch.institution_id
            == user_institution_id
        ]

        classes = [
            class_obj
            for class_obj in classes
            if class_obj.institution_id
            == user_institution_id
        ]

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/sections/all_sections.html",

        sections=sections,

        pagination=pagination,

        institutions=institutions,

        branches=branches,

        classes=classes,

        academic_years=academic_years,

        search=search,

        status=status,

        institution_filter=(
            institution_id
            if institution_id
            else ""
        ),

        branch_filter=(
            branch_id
            if branch_id
            else ""
        ),

        class_filter=(
            class_id
            if class_id
            else ""
        ),

        academic_year_filter=(
            academic_year_id
            if academic_year_id
            else ""
        ),

        per_page=per_page,

        user=current_user,

        current_role=role,

        user_institution_id=(
            user_institution_id
        ),

        user_branch_id=(
            user_branch_id
        ),
    )

# ============================================================
# ADD SECTION
# ============================================================

# ============================================================
# SECTION ROUTES
# PostgreSQL / Neon
