# ============================================================
# USER INSTITUTION HELPER
# ============================================================

def _get_user_institution_id():
    """
    Return institution ID for institution-scoped users.

    Global users / superadmins:
        None

    Institution-scoped users:
        their institution ID
    """

    role = getattr(current_user, "role", None)

    # Global users
    if role in [
        "superadmin",
        "super_admin",
        "admin",
        "system_admin",
    ]:
        return None

    return getattr(
        current_user,
        "institution_id",
        None
    )


# ============================================================
# SECTION FORM DATA
# ============================================================

def _get_section_form_data():
    """
    Load all data required by add/edit section forms.
    """

    institution_id = _get_user_institution_id()

    # --------------------------------------------------------
    # Institutions
    # --------------------------------------------------------

    institution_query = Institution.query

    if institution_id:
        institution_query = institution_query.filter(
            Institution.id == institution_id
        )

    institutions = institution_query.order_by(
        Institution.name.asc()
    ).all()

    # --------------------------------------------------------
    # Branches
    # --------------------------------------------------------

    branch_query = Branch.query

    if institution_id:
        branch_query = branch_query.filter(
            Branch.institution_id == institution_id
        )

    branches = branch_query.order_by(
        Branch.name.asc()
    ).all()

    # --------------------------------------------------------
    # Classes
    # --------------------------------------------------------

    class_query = Class.query

    if institution_id:
        class_query = class_query.filter(
            Class.institution_id == institution_id
        )

    classes = class_query.order_by(
        Class.name.asc()
    ).all()

    # --------------------------------------------------------
    # Academic Years
    # --------------------------------------------------------

    academic_year_query = AcademicYear.query

    # Only apply institution filter when the model has
    # institution_id.
    if hasattr(AcademicYear, "institution_id"):
        if institution_id:
            academic_year_query = academic_year_query.filter(
                AcademicYear.institution_id == institution_id
            )

    academic_years = academic_year_query.order_by(
        AcademicYear.name.desc()
    ).all()

    return (
        institutions,
        branches,
        classes,
        academic_years,
    )


# ============================================================
# SECTION TEMPLATE CONTEXT
# ============================================================

def _section_template_context(**kwargs):

    (
        institutions,
        branches,
        classes,
        academic_years,
    ) = _get_section_form_data()

    context = {
        "institutions": institutions,
        "branches": branches,
        "classes": classes,
        "academic_years": academic_years,
        "user": current_user,
    }

    context.update(kwargs)

    return context


# ============================================================
# ADD SECTION
# ============================================================
@bp.route(
    "/sections/add",
    methods=["GET", "POST"]
)
@login_required
def add_section():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = _get_user_institution_id()

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE REQUIREMENTS
    # ========================================================

    # school_admin MUST have an institution
    if role == "school_admin":

        if user_institution_id is None:
            abort(403)

    # branch_admin MUST have institution + branch
    elif role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # GET FORM DATA
    # ========================================================

    (
        institutions,
        branches,
        classes,
        academic_years,
    ) = _get_section_form_data()

    # ========================================================
    # FORM DATA SECURITY / ROLE SCOPE
    # ========================================================

    if role == "superadmin":

        # ----------------------------------------------------
        # SUPERADMIN
        #
        # Can access:
        # - All institutions
        # - All branches
        # - All classes
        # ----------------------------------------------------

        pass

    elif role == "school_admin":

        # ----------------------------------------------------
        # SCHOOL ADMIN
        #
        # Can access:
        # - Own institution ONLY
        # - ALL branches inside own institution
        # - ALL classes inside own institution
        # ----------------------------------------------------

        institutions = [
            institution
            for institution in institutions
            if institution.id == user_institution_id
        ]

        branches = [
            branch
            for branch in branches
            if branch.institution_id == user_institution_id
        ]

        classes = [
            class_obj
            for class_obj in classes
            if class_obj.institution_id == user_institution_id
        ]

        # Academic year scope
        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id
                == user_institution_id
            ]

    elif role == "branch_admin":

        # ----------------------------------------------------
        # BRANCH ADMIN
        #
        # Can access:
        # - Own institution ONLY
        # - Own branch ONLY
        # - Classes belonging to own branch ONLY
        # ----------------------------------------------------

        institutions = [
            institution
            for institution in institutions
            if institution.id == user_institution_id
        ]

        branches = [
            branch
            for branch in branches
            if (
                branch.id == user_branch_id
                and branch.institution_id
                == user_institution_id
            )
        ]

        classes = [
            class_obj
            for class_obj in classes
            if (
                class_obj.institution_id
                == user_institution_id
                and class_obj.branch_id
                == user_branch_id
            )
        ]

        # Academic year scope
        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id
                == user_institution_id
            ]

    # ========================================================
    # SAFE FORM RENDER HELPER
    # ========================================================

    def render_form(
        institution_id=None,
        branch_id=None,
        class_id=None,
        academic_year_id=None,
        name="",
        capacity="",
        description="",
        status="active",
    ):

        context = _section_template_context(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity,
            description=description,
            status=status,
        )

        # ----------------------------------------------------
        # IMPORTANT:
        # Use update() instead of passing duplicate **kwargs.
        #
        # This prevents:
        # TypeError:
        # render_template() got multiple values
        # for keyword argument 'user'
        # ----------------------------------------------------

        context.update({
            "current_role": role,
            "user_institution_id": user_institution_id,
            "user_branch_id": user_branch_id,
        })

        return render_template(
            "backend/pages/sections/add_section.html",
            **context
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        class_id = request.form.get(
            "class_id",
            type=int
        )

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        name = (
            request.form.get(
                "name",
                ""
            )
            .strip()
        )

        capacity_raw = (
            request.form.get(
                "capacity",
                ""
            )
            .strip()
        )

        description = (
            request.form.get(
                "description",
                ""
            )
            .strip()
        )

        status = (
            request.form.get(
                "status",
                "active"
            )
            .strip()
            .lower()
        )

        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if not institution_id:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        if not branch_id:

            flash(
                "Please select a branch.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        if not class_id:

            flash(
                "Please select a class.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        if not academic_year_id:

            flash(
                "Please select an academic year.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        if not name:

            flash(
                "Section name is required.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # ROLE SCOPE SECURITY
        # ====================================================

        # ----------------------------------------------------
        # SCHOOL ADMIN
        # Own institution ONLY
        # ----------------------------------------------------

        if role == "school_admin":

            if (
                user_institution_id is None
                or institution_id != user_institution_id
            ):

                abort(403)

        # ----------------------------------------------------
        # BRANCH ADMIN
        # Own institution + own branch ONLY
        # ----------------------------------------------------

        elif role == "branch_admin":

            if (
                user_institution_id is None
                or user_branch_id is None
            ):

                abort(403)

            if institution_id != user_institution_id:
                abort(403)

            if branch_id != user_branch_id:
                abort(403)

        # ----------------------------------------------------
        # SUPERADMIN
        # No institution/branch restriction
        # ----------------------------------------------------

        elif role == "superadmin":

            pass

        # ====================================================
        # NAME LENGTH
        # ====================================================

        if len(name) > 150:

            flash(
                "Section name cannot exceed 150 characters.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # DESCRIPTION LENGTH
        # ====================================================

        if len(description) > 1000:

            flash(
                "Description cannot exceed 1000 characters.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # STATUS VALIDATION
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "suspended",
        }

        if status not in allowed_statuses:

            flash(
                "Invalid section status.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status="active",
            )

        # ====================================================
        # CAPACITY
        # ====================================================

        capacity = None

        if capacity_raw:

            try:

                capacity = int(
                    capacity_raw
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Capacity must be a valid whole number.",
                    "danger"
                )

                return render_form(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )

            if capacity < 0:

                flash(
                    "Capacity cannot be negative.",
                    "danger"
                )

                return render_form(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )

            if capacity > 10000:

                flash(
                    "Capacity cannot exceed 10,000 students.",
                    "danger"
                )

                return render_form(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )

        # ====================================================
        # LOAD INSTITUTION
        # ====================================================

        institution = Institution.query.filter(
            Institution.id == institution_id
        ).first()

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # LOAD BRANCH
        # ====================================================

        branch = Branch.query.filter(
            Branch.id == branch_id
        ).first()

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # BRANCH MUST BELONG TO INSTITUTION
        # ====================================================

        if branch.institution_id != institution_id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # EXTRA SCHOOL ADMIN SECURITY
        # ====================================================

        if role == "school_admin":

            if branch.institution_id != user_institution_id:
                abort(403)

        # ====================================================
        # EXTRA BRANCH ADMIN SECURITY
        # ====================================================

        if role == "branch_admin":

            if (
                branch.institution_id != user_institution_id
                or branch.id != user_branch_id
            ):
                abort(403)

        # ====================================================
        # LOAD CLASS
        # ====================================================

        class_obj = Class.query.filter(
            Class.id == class_id
        ).first()

        if not class_obj:

            flash(
                "Selected class was not found.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # CLASS MUST BELONG TO INSTITUTION
        # ====================================================

        if class_obj.institution_id != institution_id:

            flash(
                "Selected class does not belong to the selected institution.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # CLASS MUST BELONG TO BRANCH
        # ====================================================

        if class_obj.branch_id != branch_id:

            flash(
                "Selected class does not belong to the selected branch.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # SCHOOL ADMIN CLASS SECURITY
        # ====================================================

        if role == "school_admin":

            if class_obj.institution_id != user_institution_id:
                abort(403)

        # ====================================================
        # BRANCH ADMIN CLASS SECURITY
        # ====================================================

        if role == "branch_admin":

            if (
                class_obj.institution_id
                != user_institution_id
                or class_obj.branch_id
                != user_branch_id
            ):
                abort(403)

        # ====================================================
        # LOAD ACADEMIC YEAR
        # ====================================================

        academic_year = AcademicYear.query.filter(
            AcademicYear.id == academic_year_id
        ).first()

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # ACADEMIC YEAR INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution_id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_form(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )

        # ====================================================
        # CLASS / ACADEMIC YEAR MATCH
        # ====================================================

        if hasattr(
            Class,
            "academic_year_id"
        ):

            if (
                class_obj.academic_year_id
                != academic_year_id
            ):

                flash(
                    "Selected class does not belong to the selected academic year.",
                    "danger"
                )

                return render_form(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )

        # ====================================================
        # AUTO GENERATE SECTION CODE
        # ====================================================

        code = generate_section_code(
            name
        )

        if not code:

            flash(
                "Unable to generate section code from the section name.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # DUPLICATE NAME CHECK
        # ====================================================

        existing_section = Section.query.filter(
            Section.institution_id == institution_id,
            Section.branch_id == branch_id,
            Section.class_id == class_id,
            Section.academic_year_id == academic_year_id,
            func.lower(
                Section.name
            ) == name.lower()
        ).first()

        if existing_section:

            flash(
                "A section with this name already exists for the selected class and academic year.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # DUPLICATE CODE CHECK
        # ====================================================

        existing_code = Section.query.filter(
            Section.institution_id == institution_id,
            Section.branch_id == branch_id,
            Section.class_id == class_id,
            Section.academic_year_id == academic_year_id,
            func.upper(
                Section.code
            ) == code.upper()
        ).first()

        if existing_code:

            flash(
                f"The generated section code '{code}' already exists for this class and academic year.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # CREATE SECTION
        # ====================================================

        section = Section(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            code=code,
            capacity=capacity,
            description=description or None,
            status=status,
        )

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(
                section
            )

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Error creating section: %s",
                exc
            )

            flash(
                "An error occurred while creating the section. Please try again.",
                "danger"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            f"Section '{section.name}' ({section.code}) was created successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.view_section",
                section_id=section.id
            )
        )

    # ========================================================
    # GET DEFAULT VALUES
    # ========================================================

    default_institution_id = None
    default_branch_id = None

    # --------------------------------------------------------
    # Superadmin
    #
    # If only one institution exists, select it automatically.
    # Otherwise allow all institutions.
    # --------------------------------------------------------

    if role == "superadmin":

        if len(institutions) == 1:

            default_institution_id = (
                institutions[0].id
            )

    # --------------------------------------------------------
    # School admin
    #
    # Institution is ALWAYS their institution.
    # Branch remains selectable among all branches.
    # --------------------------------------------------------

    elif role == "school_admin":

        default_institution_id = (
            user_institution_id
        )

    # --------------------------------------------------------
    # Branch admin
    #
    # Institution + branch are ALWAYS locked to their scope.
    # --------------------------------------------------------

    elif role == "branch_admin":

        default_institution_id = (
            user_institution_id
        )

        default_branch_id = (
            user_branch_id
        )

    # ========================================================
    # RENDER GET
    # ========================================================

    return render_form(
        institution_id=default_institution_id,
        branch_id=default_branch_id,
        class_id=None,
        academic_year_id=None,
        name="",
        capacity="",
        description="",
        status="active",
    )



# ============================================================
# VIEW SECTION
# ============================================================

@bp.route(
    "/sections/<int:section_id>",
    methods=["GET"]
)
@login_required
def view_section(section_id):

    section = _get_section_or_404(
        section_id
    )

    return render_template(
        "backend/pages/sections/view_section.html",

        section=section,

        # IMPORTANT
        user=current_user,
    )


# ============================================================
# EDIT SECTION
# ============================================================

@bp.route(
    "/sections/<int:section_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_section(section_id):

    # ============================================================
    # ROLE SECURITY
    # ============================================================

    role = getattr(current_user, "role", None)

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ============================================================
    # CURRENT USER SCOPE
    # ============================================================

    user_institution_id = _get_user_institution_id()
    user_branch_id = getattr(current_user, "branch_id", None)

    # ------------------------------------------------------------
    # SCHOOL ADMIN
    # Must belong to an institution
    # ------------------------------------------------------------

    if role == "school_admin":
        if user_institution_id is None:
            abort(403)

    # ------------------------------------------------------------
    # BRANCH ADMIN
    # Must belong to an institution + branch
    # ------------------------------------------------------------

    if role == "branch_admin":
        if user_institution_id is None:
            abort(403)

        if user_branch_id is None:
            abort(403)

    # ============================================================
    # LOAD SECTION
    # ============================================================

    section = (
        Section.query
        .filter(Section.id == section_id)
        .first_or_404()
    )

    # ============================================================
    # SECTION OWNERSHIP / SCOPE SECURITY
    # ============================================================

    # ------------------------------------------------------------
    # SUPERADMIN
    # Can edit any section
    # ------------------------------------------------------------

    if role == "superadmin":
        pass

    # ------------------------------------------------------------
    # SCHOOL ADMIN
    # Can edit sections belonging to own institution only
    # ------------------------------------------------------------

    elif role == "school_admin":

        if section.institution_id != user_institution_id:
            abort(403)

    # ------------------------------------------------------------
    # BRANCH ADMIN
    # Can edit sections belonging to own institution + branch only
    # ------------------------------------------------------------

    elif role == "branch_admin":

        if section.institution_id != user_institution_id:
            abort(403)

        if section.branch_id != user_branch_id:
            abort(403)

    # ============================================================
    # FORM DATA
    # ============================================================

    (
        institutions,
        branches,
        classes,
        academic_years
    ) = _get_section_form_data()

    # ============================================================
    # SERVER-SIDE FORM DATA SCOPE
    # ============================================================

    # ------------------------------------------------------------
    # SUPERADMIN
    # ------------------------------------------------------------

    if role == "superadmin":

        # No filtering
        pass

    # ------------------------------------------------------------
    # SCHOOL ADMIN
    # ------------------------------------------------------------

    elif role == "school_admin":

        # Only own institution
        institutions = [
            institution
            for institution in institutions
            if institution.id == user_institution_id
        ]

        # All branches inside own institution
        branches = [
            branch
            for branch in branches
            if branch.institution_id == user_institution_id
        ]

        # All classes inside own institution
        classes = [
            class_obj
            for class_obj in classes
            if class_obj.institution_id == user_institution_id
        ]

        # Academic years belonging to own institution
        if hasattr(AcademicYear, "institution_id"):
            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id == user_institution_id
            ]

    # ------------------------------------------------------------
    # BRANCH ADMIN
    # ------------------------------------------------------------

    elif role == "branch_admin":

        # Only own institution
        institutions = [
            institution
            for institution in institutions
            if institution.id == user_institution_id
        ]

        # Only own branch
        branches = [
            branch
            for branch in branches
            if (
                branch.id == user_branch_id
                and branch.institution_id == user_institution_id
            )
        ]

        # Only classes belonging to own branch
        classes = [
            class_obj
            for class_obj in classes
            if (
                class_obj.institution_id == user_institution_id
                and class_obj.branch_id == user_branch_id
            )
        ]

        # Academic years belonging to own institution
        if hasattr(AcademicYear, "institution_id"):
            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id == user_institution_id
            ]

    # ============================================================
    # RENDER FORM HELPER
    # ============================================================

    def render_form(
        institution_id=None,
        branch_id=None,
        class_id=None,
        academic_year_id=None,
        name="",
        capacity="",
        description="",
        status="active",
    ):

        # --------------------------------------------------------
        # Build context safely
        # --------------------------------------------------------

        context = _section_template_context(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity,
            description=description,
            status=status,
        )

        # --------------------------------------------------------
        # IMPORTANT:
        # Override form lists with already-scoped server data.
        #
        # This prevents _section_template_context() from
        # accidentally sending all institutions/branches/classes.
        # --------------------------------------------------------

        context.update({
            "institutions": institutions,
            "branches": branches,
            "classes": classes,
            "academic_years": academic_years,

            "section": section,

            "current_role": role,
            "user_institution_id": user_institution_id,
            "user_branch_id": user_branch_id,
        })

        return render_template(
            "backend/pages/sections/edit_section.html",
            **context
        )

    # ============================================================
    # GET
    # ============================================================

    if request.method == "GET":

        return render_form(
            institution_id=section.institution_id,
            branch_id=section.branch_id,
            class_id=section.class_id,
            academic_year_id=getattr(
                section,
                "academic_year_id",
                None
            ),
            name=section.name or "",
            capacity=(
                section.capacity
                if section.capacity is not None
                else ""
            ),
            description=section.description or "",
            status=section.status or "active",
        )

    # ============================================================
    # POST
    # ============================================================

    # ------------------------------------------------------------
    # Read submitted values
    # ------------------------------------------------------------

    submitted_institution_id = request.form.get(
        "institution_id",
        type=int
    )

    submitted_branch_id = request.form.get(
        "branch_id",
        type=int
    )

    submitted_class_id = request.form.get(
        "class_id",
        type=int
    )

    submitted_academic_year_id = request.form.get(
        "academic_year_id",
        type=int
    )

    name = (
        request.form.get("name", "")
        .strip()
    )

    capacity_raw = (
        request.form.get("capacity", "")
        .strip()
    )

    description = (
        request.form.get("description", "")
        .strip()
    )

    status = (
        request.form.get("status", "active")
        .strip()
        .lower()
    )

    # ============================================================
    # ROLE-BASED SERVER ENFORCEMENT
    # ============================================================
    #
    # NEVER trust institution_id / branch_id submitted by browser.
    #
    # This is especially important for branch_admin.
    # ============================================================

    if role == "school_admin":

        # Force institution to user's institution
        institution_id = user_institution_id

        # Branch may be selected, but must later be verified
        branch_id = submitted_branch_id

    elif role == "branch_admin":

        # Force both values to user's scope
        institution_id = user_institution_id
        branch_id = user_branch_id

    else:
        # superadmin
        institution_id = submitted_institution_id
        branch_id = submitted_branch_id

    class_id = submitted_class_id
    academic_year_id = submitted_academic_year_id

    # ============================================================
    # REQUIRED FIELD VALIDATION
    # ============================================================

    if not institution_id:
        flash(
            "Please select an institution.",
            "error"
        )

        return render_form(
            institution_id=(
                user_institution_id
                if role != "superadmin"
                else submitted_institution_id
            ),
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    if not branch_id:
        flash(
            "Please select a branch.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    if not class_id:
        flash(
            "Please select a class.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    if not academic_year_id:
        flash(
            "Please select an academic year.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    if not name:
        flash(
            "Section name is required.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # NAME VALIDATION
    # ============================================================

    if len(name) > 150:
        flash(
            "Section name cannot exceed 150 characters.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # CAPACITY VALIDATION
    # ============================================================

    capacity = None

    if capacity_raw:

        try:
            capacity = int(capacity_raw)

        except (TypeError, ValueError):

            flash(
                "Capacity must be a valid number.",
                "error"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

        if capacity < 0:

            flash(
                "Capacity cannot be negative.",
                "error"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

    # ============================================================
    # DESCRIPTION VALIDATION
    # ============================================================

    if len(description) > 1000:

        flash(
            "Description cannot exceed 1000 characters.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # STATUS VALIDATION
    # ============================================================

    allowed_statuses = {
        "active",
        "inactive",
        "suspended",
    }

    if status not in allowed_statuses:

        flash(
            "Invalid section status.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status="active",
        )

    # ============================================================
    # LOAD INSTITUTION
    # ============================================================

    institution = (
        Institution.query
        .filter(
            Institution.id == institution_id
        )
        .first()
    )

    if institution is None:

        flash(
            "Selected institution was not found.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # INSTITUTION SCOPE SECURITY
    # ============================================================

    if role in {
        "school_admin",
        "branch_admin",
    }:

        if institution.id != user_institution_id:

            abort(403)

    # ============================================================
    # LOAD BRANCH
    # ============================================================

    branch = (
        Branch.query
        .filter(
            Branch.id == branch_id
        )
        .first()
    )

    if branch is None:

        flash(
            "Selected branch was not found.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # BRANCH → INSTITUTION VALIDATION
    # ============================================================

    if branch.institution_id != institution.id:

        flash(
            "Selected branch does not belong to the selected institution.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # SCHOOL ADMIN BRANCH SECURITY
    # ============================================================

    if role == "school_admin":

        if branch.institution_id != user_institution_id:

            abort(403)

    # ============================================================
    # BRANCH ADMIN BRANCH SECURITY
    # ============================================================

    if role == "branch_admin":

        if branch.id != user_branch_id:

            abort(403)

        if branch.institution_id != user_institution_id:

            abort(403)

    # ============================================================
    # LOAD CLASS
    # ============================================================

    class_obj = (
        Class.query
        .filter(
            Class.id == class_id
        )
        .first()
    )

    if class_obj is None:

        flash(
            "Selected class was not found.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # CLASS → INSTITUTION VALIDATION
    # ============================================================

    if class_obj.institution_id != institution.id:

        flash(
            "Selected class does not belong to the selected institution.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # CLASS → BRANCH VALIDATION
    # ============================================================

    if class_obj.branch_id != branch.id:

        flash(
            "Selected class does not belong to the selected branch.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # BRANCH ADMIN CLASS SECURITY
    # ============================================================

    if role == "branch_admin":

        if class_obj.institution_id != user_institution_id:
            abort(403)

        if class_obj.branch_id != user_branch_id:
            abort(403)

    # ============================================================
    # SCHOOL ADMIN CLASS SECURITY
    # ============================================================

    if role == "school_admin":

        if class_obj.institution_id != user_institution_id:
            abort(403)

    # ============================================================
    # LOAD ACADEMIC YEAR
    # ============================================================

    academic_year = (
        AcademicYear.query
        .filter(
            AcademicYear.id == academic_year_id
        )
        .first()
    )

    if academic_year is None:

        flash(
            "Selected academic year was not found.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # ACADEMIC YEAR → INSTITUTION SECURITY
    # ============================================================

    if hasattr(academic_year, "institution_id"):

        if academic_year.institution_id is not None:

            if academic_year.institution_id != institution.id:

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "error"
                )

                return render_form(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )

            if role in {
                "school_admin",
                "branch_admin",
            }:

                if academic_year.institution_id != user_institution_id:
                    abort(403)

    # ============================================================
    # CLASS → ACADEMIC YEAR VALIDATION
    # ============================================================

    if hasattr(class_obj, "academic_year_id"):

        if (
            class_obj.academic_year_id is not None
            and class_obj.academic_year_id != academic_year.id
        ):

            flash(
                "Selected academic year does not match the selected class.",
                "error"
            )

            return render_form(
                institution_id=institution_id,
                branch_id=branch_id,
                class_id=class_id,
                academic_year_id=academic_year_id,
                name=name,
                capacity=capacity_raw,
                description=description,
                status=status,
            )

    # ============================================================
    # GENERATE SECTION CODE
    # ============================================================

    new_code = generate_section_code(name)

    # ============================================================
    # DUPLICATE SECTION CHECK
    # ============================================================
    #
    # Exclude the current section itself.
    # ============================================================

    duplicate_query = (
        Section.query
        .filter(
            Section.id != section.id,
            Section.institution_id == institution.id,
            Section.branch_id == branch.id,
            Section.class_id == class_obj.id,
            Section.name.ilike(name),
        )
    )

    if hasattr(Section, "academic_year_id"):

        duplicate_query = duplicate_query.filter(
            Section.academic_year_id == academic_year.id
        )

    existing_section = (
        duplicate_query
        .first()
    )

    if existing_section:

        flash(
            "Another section with the same name already exists for this class.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # DUPLICATE CODE CHECK
    # ============================================================

    duplicate_code_query = (
        Section.query
        .filter(
            Section.id != section.id,
            Section.institution_id == institution.id,
            Section.branch_id == branch.id,
            Section.code == new_code,
        )
    )

    existing_code_section = (
        duplicate_code_query
        .first()
    )

    if existing_code_section:

        flash(
            "The generated section code already exists. Please use a different section name.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )

    # ============================================================
    # UPDATE SECTION
    # ============================================================

    section.institution_id = institution.id
    section.branch_id = branch.id
    section.class_id = class_obj.id
    section.name = name
    section.code = new_code
    section.capacity = capacity
    section.description = description or None
    section.status = status

    # Academic year
    if hasattr(section, "academic_year_id"):
        section.academic_year_id = academic_year.id

    # ============================================================
    # SAVE
    # ============================================================

    try:

        db.session.commit()

        flash(
            f'Section "{section.name}" updated successfully.',
            "success"
        )

        return redirect(
            url_for(
                "main.all_sections"
            )
        )

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "Error updating section %s: %s",
            section_id,
            exc
        )

        flash(
            "An error occurred while updating the section. Please try again.",
            "error"
        )

        return render_form(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            capacity=capacity_raw,
            description=description,
            status=status,
        )





# ============================================================
# DELETE SECTION
# ============================================================

@bp.route(
    "/sections/<int:section_id>/delete",
    methods=["POST"]
)
@login_required
def delete_section(section_id):

    section = _get_section_or_404(
        section_id
    )

    section_name = section.name

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            section
        )

        db.session.commit()

    except IntegrityError:

        db.session.rollback()

        flash(
            (
                f'Unable to delete section "{section_name}". '
                "This section may already be connected to "
                "other academic records. Please set it to "
                "inactive instead."
            ),
            "danger"
        )

        return redirect(
            url_for(
                "main.view_section",
                section_id=section.id
            )
        )

    # ========================================================
    # SUCCESS
    # ========================================================

    flash(
        f'Section "{section_name}" was deleted successfully.',
        "success"
    )

    return redirect(
        url_for(
            "main.all_sections"
        )
    )



