# ============================================================
# SUBJECT CONSTANTS
# ============================================================

SUBJECT_TYPES = [
    "academic",
    "practical",
    "language",
    "religious",
    "vocational",
    "elective",
    "compulsory",
    "skill",
]

SUBJECT_STATUSES = [
    "active",
    "inactive",
    "suspended",
]


# ============================================================
# USER / INSTITUTION HELPERS
# ============================================================

def _subject_is_global_user():
    """
    Returns True when the current user is allowed to
    manage data across all institutions.
    """

    role = (
        getattr(current_user, "role", None)
        or ""
    ).lower().strip()

    return role in {
        "superadmin",
        "super_admin",
        "admin",
        "system_admin",
    }


def _subject_get_user_institution_id():
    """
    Returns the institution ID belonging to the current user.

    Global users return None.
    """

    if _subject_is_global_user():
        return None

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    if institution_id is None:
        return None

    try:
        return int(institution_id)
    except (TypeError, ValueError):
        return None


def _subject_get_user_branch_id():
    """
    Returns the user's branch ID when available.
    """

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if branch_id is None:
        return None

    try:
        return int(branch_id)
    except (TypeError, ValueError):
        return None


def _subject_can_manage_global():
    """
    Determines whether the user can see/manage subjects
    belonging to all branches of their institution.

    Institution admins generally can manage all branches.
    Branch admins are restricted to their branch.
    """

    role = (
        getattr(current_user, "role", None)
        or ""
    ).lower().strip()

    return role in {
        "superadmin",
        "super_admin",
        "admin",
        "system_admin",
        "institution_admin",
    }


# ============================================================
# SUBJECT SCOPE
# ============================================================

def _subject_scope_query(query):
    """
    Apply institution/branch security to a Subject query.

    Global users:
        all institutions.

    Institution admins:
        only their institution.

    Branch admins / teachers:
        their institution + branch.

    Other scoped users:
        their institution and, when available, branch.
    """

    institution_id = _subject_get_user_institution_id()

    # Global user
    if institution_id is None:
        return query

    query = query.filter(
        Subject.institution_id == institution_id
    )

    # Institution-level administrators can manage
    # all branches inside their institution.
    if _subject_can_manage_global():
        return query

    branch_id = _subject_get_user_branch_id()

    if branch_id is not None:
        query = query.filter(
            Subject.branch_id == branch_id
        )

    return query


# ============================================================
# PARSE DECIMAL
# ============================================================

def _subject_parse_decimal(
    value,
    field_name,
    errors,
    allow_empty=True
):
    """
    Safely parse Decimal values.
    """

    value = (
        str(value).strip()
        if value is not None
        else ""
    )

    if not value:

        if allow_empty:
            return None

        errors[field_name] = (
            f"{field_name.replace('_', ' ').title()} "
            "is required."
        )

        return None

    try:

        return Decimal(value)

    except (InvalidOperation, ValueError):

        errors[field_name] = (
            f"Invalid {field_name.replace('_', ' ')}."
        )

        return None


# ============================================================
# VALIDATE SUBJECT RELATIONSHIPS
# ============================================================

def _validate_subject_relationships(
    institution_id,
    branch_id,
    program_id,
    errors
):
    """
    Validates institution, branch and program relationships.
    """

    institution = None
    branch = None
    program = None


    # --------------------------------------------------------
    # Institution
    # --------------------------------------------------------

    if not institution_id:

        errors["institution_id"] = (
            "Institution is required."
        )

    else:

        try:
            institution_id = int(institution_id)

        except (TypeError, ValueError):

            errors["institution_id"] = (
                "Invalid institution."
            )

        else:

            institution = Institution.query.get(
                institution_id
            )

            if not institution:

                errors["institution_id"] = (
                    "Selected institution was not found."
                )


    # --------------------------------------------------------
    # Security: institution
    # --------------------------------------------------------

    user_institution_id = (
        _subject_get_user_institution_id()
    )

    if (
        user_institution_id is not None
        and institution_id is not None
        and institution_id != user_institution_id
    ):

        errors["institution_id"] = (
            "You are not allowed to use this institution."
        )


    # --------------------------------------------------------
    # Branch
    # --------------------------------------------------------

    if branch_id:

        try:
            branch_id = int(branch_id)

        except (TypeError, ValueError):

            errors["branch_id"] = (
                "Invalid branch."
            )

        else:

            branch = Branch.query.get(
                branch_id
            )

            if not branch:

                errors["branch_id"] = (
                    "Selected branch was not found."
                )

            elif (
                institution_id is not None
                and branch.institution_id != institution_id
            ):

                errors["branch_id"] = (
                    "Selected branch does not belong "
                    "to the selected institution."
                )


            # Branch security
            user_branch_id = (
                _subject_get_user_branch_id()
            )

            if (
                not _subject_can_manage_global()
                and user_branch_id is not None
                and branch_id != user_branch_id
            ):

                errors["branch_id"] = (
                    "You are not allowed to use this branch."
                )


    # --------------------------------------------------------
    # Program
    # --------------------------------------------------------

    if program_id:

        try:
            program_id = int(program_id)

        except (TypeError, ValueError):

            errors["program_id"] = (
                "Invalid program."
            )

        else:

            program = Program.query.get(
                program_id
            )

            if not program:

                errors["program_id"] = (
                    "Selected program was not found."
                )

            elif (
                institution_id is not None
                and program.institution_id != institution_id
            ):

                errors["program_id"] = (
                    "Selected program does not belong "
                    "to the selected institution."
                )

    return institution, branch, program


# ============================================================
# ALL SUBJECTS
# ============================================================

@bp.route(
    "/subjects",
    methods=["GET"]
)
@login_required
def all_subjects():

    # ========================================================
    # CURRENT USER ROLE
    # ========================================================

    current_role = (
        getattr(
            current_user,
            "role",
            None
        ) or ""
    ).strip().lower()

    # ========================================================
    # ALLOWED ROLES
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to view subjects.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # ROLE FLAGS
    # ========================================================

    is_superadmin = (
        current_role == "superadmin"
    )

    is_school_admin = (
        current_role == "school_admin"
    )

    is_branch_admin = (
        current_role == "branch_admin"
    )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # REQUIRED SCOPE
    # ========================================================

    if is_school_admin:

        if current_institution_id is None:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    if is_branch_admin:

        if current_institution_id is None:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        if current_branch_id is None:

            flash(
                "Your account is not assigned to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # FILTERS
    # ========================================================

    search = (
        request.args.get(
            "search",
            ""
        ) or ""
    ).strip()

    institution_filter = (
        request.args.get(
            "institution_id",
            ""
        ) or ""
    ).strip()

    branch_filter = (
        request.args.get(
            "branch_id",
            ""
        ) or ""
    ).strip()

    program_filter = (
        request.args.get(
            "program_id",
            ""
        ) or ""
    ).strip()

    subject_type_filter = (
        request.args.get(
            "subject_type",
            ""
        ) or ""
    ).strip().lower()

    status_filter = (
        request.args.get(
            "status",
            ""
        ) or ""
    ).strip().lower()

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    if page < 1:
        page = 1

    if per_page not in {
        10,
        25,
        50,
        100
    }:
        per_page = 25

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = Subject.query

    # ========================================================
    # SECURITY SCOPE
    #
    # SUPERADMIN
    #     All subjects.
    #
    # SCHOOL ADMIN
    #     Subjects inside own institution.
    #
    # BRANCH ADMIN
    #     Subjects inside own branch ONLY.
    # ========================================================

    if is_superadmin:

        # ----------------------------------------------------
        # No restriction
        # ----------------------------------------------------

        pass

    elif is_school_admin:

        query = query.filter(
            Subject.institution_id
            == current_institution_id
        )

    elif is_branch_admin:

        # ----------------------------------------------------
        # IMPORTANT:
        # Branch Admin MUST NEVER see:
        #
        # - another institution
        # - another branch
        # - institution-wide subjects
        #
        # Only exact current branch.
        # ----------------------------------------------------

        query = query.filter(
            Subject.institution_id
            == current_institution_id,
            Subject.branch_id
            == current_branch_id
        )

    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    if institution_filter:

        try:

            institution_id = int(
                institution_filter
            )

            if institution_id > 0:

                # --------------------------------------------
                # BRANCH ADMIN
                # --------------------------------------------

                if is_branch_admin:

                    # Never allow the URL filter to escape
                    # the user's institution.

                    if (
                        institution_id
                        != current_institution_id
                    ):

                        # Force impossible query.
                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.institution_id
                            == current_institution_id
                        )

                # --------------------------------------------
                # SCHOOL ADMIN
                # --------------------------------------------

                elif is_school_admin:

                    if (
                        institution_id
                        != current_institution_id
                    ):

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.institution_id
                            == institution_id
                        )

                # --------------------------------------------
                # SUPERADMIN
                # --------------------------------------------

                else:

                    query = query.filter(
                        Subject.institution_id
                        == institution_id
                    )

        except (TypeError, ValueError):

            pass

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if branch_filter:

        try:

            branch_id = int(
                branch_filter
            )

            if branch_id > 0:

                # --------------------------------------------
                # BRANCH ADMIN
                # --------------------------------------------

                if is_branch_admin:

                    # Cannot select another branch.

                    if (
                        branch_id
                        != current_branch_id
                    ):

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.branch_id
                            == current_branch_id
                        )

                # --------------------------------------------
                # SCHOOL ADMIN
                # --------------------------------------------

                elif is_school_admin:

                    selected_branch = (
                        Branch.query.filter(
                            Branch.id
                            == branch_id,
                            Branch.institution_id
                            == current_institution_id
                        ).first()
                    )

                    if selected_branch is None:

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.branch_id
                            == branch_id
                        )

                # --------------------------------------------
                # SUPERADMIN
                # --------------------------------------------

                else:

                    query = query.filter(
                        Subject.branch_id
                        == branch_id
                    )

        except (TypeError, ValueError):

            pass

    # ========================================================
    # PROGRAM FILTER
    # ========================================================

    if program_filter:

        try:

            program_id = int(
                program_filter
            )

            if program_id > 0:

                # --------------------------------------------
                # BRANCH ADMIN
                # --------------------------------------------

                if is_branch_admin:

                    selected_program = (
                        Program.query.filter(
                            Program.id
                            == program_id,
                            Program.institution_id
                            == current_institution_id,
                            db.or_(
                                Program.branch_id
                                == current_branch_id,
                                Program.branch_id.is_(None)
                            )
                        ).first()
                    )

                    if selected_program is None:

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.program_id
                            == program_id
                        )

                # --------------------------------------------
                # SCHOOL ADMIN
                # --------------------------------------------

                elif is_school_admin:

                    selected_program = (
                        Program.query.filter(
                            Program.id
                            == program_id,
                            Program.institution_id
                            == current_institution_id
                        ).first()
                    )

                    if selected_program is None:

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.program_id
                            == program_id
                        )

                # --------------------------------------------
                # SUPERADMIN
                # --------------------------------------------

                else:

                    query = query.filter(
                        Subject.program_id
                        == program_id
                    )

        except (TypeError, ValueError):

            pass

    # ========================================================
    # SUBJECT TYPE FILTER
    # ========================================================

    if subject_type_filter:

        if (
            subject_type_filter
            in SUBJECT_TYPES
        ):

            query = query.filter(
                Subject.subject_type
                == subject_type_filter
            )

    # ========================================================
    # STATUS FILTER
    # ========================================================

    if status_filter:

        if (
            status_filter
            in SUBJECT_STATUSES
        ):

            query = query.filter(
                Subject.status
                == status_filter
            )

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_pattern = (
            f"%{search}%"
        )

        query = query.filter(
            db.or_(
                Subject.name.ilike(
                    search_pattern
                ),
                Subject.code.ilike(
                    search_pattern
                ),
                Subject.short_name.ilike(
                    search_pattern
                )
            )
        )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        Subject.name.asc(),
        Subject.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    subjects = pagination.items

    # ========================================================
    # FILTER DATA
    #
    # Do NOT blindly use global helper functions here.
    # Build the lists according to the user's scope.
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    if is_superadmin:

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query.filter(
                Institution.id
                == current_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ========================================================
    # BRANCHES
    # ========================================================

    if is_superadmin:

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif is_school_admin:

        branches = (
            Branch.query.filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        # ----------------------------------------------------
        # BRANCH ADMIN:
        # EXACTLY ONE BRANCH
        # ----------------------------------------------------

        branches = (
            Branch.query.filter(
                Branch.id
                == current_branch_id,
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    # ========================================================
    # PROGRAMS
    # ========================================================

    if is_superadmin:

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif is_school_admin:

        programs = (
            Program.query.filter(
                Program.institution_id
                == current_institution_id
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    else:

        # ----------------------------------------------------
        # BRANCH ADMIN
        #
        # Programs allowed:
        #
        # 1. Current branch programs
        # 2. Institution-wide programs
        # ----------------------------------------------------

        programs = (
            Program.query.filter(
                Program.institution_id
                == current_institution_id,
                db.or_(
                    Program.branch_id
                    == current_branch_id,
                    Program.branch_id.is_(None)
                )
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/subjects/all_subjects.html",

        # ----------------------------------------------------
        # DATA
        # ----------------------------------------------------

        subjects=subjects,
        pagination=pagination,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        institutions=institutions,
        branches=branches,
        programs=programs,

        subject_types=SUBJECT_TYPES,
        subject_statuses=SUBJECT_STATUSES,

        # ----------------------------------------------------
        # CURRENT FILTERS
        # ----------------------------------------------------

        search=search,
        institution_filter=institution_filter,
        branch_filter=branch_filter,
        program_filter=program_filter,
        subject_type_filter=subject_type_filter,
        status_filter=status_filter,

        # ----------------------------------------------------
        # ROLE / SCOPE DATA
        # ----------------------------------------------------

        is_superadmin=is_superadmin,
        is_school_admin=is_school_admin,
        is_branch_admin=is_branch_admin,

        current_user_institution_id=(
            current_institution_id
        ),

        current_user_branch_id=(
            current_branch_id
        ),

        # ----------------------------------------------------
        # CURRENT USER
        # ----------------------------------------------------

        user=current_user
    )


# ============================================================
# SUBJECT CONSTANTS
# ============================================================

SUBJECT_TEACHING_DAYS_PER_WEEK = Decimal("5")
SUBJECT_HOURS_PER_DAY = Decimal("1")
SUBJECT_WEEKS_PER_YEAR = Decimal("52")
SUBJECT_MONTHS_PER_YEAR = Decimal("12")
SUBJECT_HOURS_PER_CREDIT = Decimal("15")


# ============================================================
# NORMALIZE SUBJECT NAME
# ============================================================

def _normalize_subject_name(value):
    """
    Normalize subject names for duplicate detection.

    Examples:
        "English Language"
        " english   language "
        "ENGLISH LANGUAGE"

    All become the same normalized value.
    """

    if value is None:
        return ""

    value = str(value)

    # Remove leading/trailing spaces
    value = value.strip()

    # Convert multiple spaces to one
    value = " ".join(value.split())

    # Case-insensitive comparison
    return value.casefold()


# ============================================================
# PARSE SUBJECT MARK
# ============================================================

def _parse_subject_mark(value):
    """
    Convert a subject mark into Decimal.

    Blank:
        None

    Invalid:
        None

    Valid:
        Decimal("100")
        Decimal("50")
        Decimal("75.50")
    """

    if value is None:
        return None

    value = str(value).strip()

    # Optional field
    if not value:
        return None

    try:
        number = Decimal(value)

    except (
        InvalidOperation,
        TypeError,
        ValueError
    ):
        return None

    # Reject NaN / Infinity
    if not number.is_finite():
        return None

    # Store consistently as 2 decimal places
    return number.quantize(
        Decimal("0.01")
    )


# ============================================================
# GENERATE SUBJECT SHORT NAME
# ============================================================

def _generate_subject_short_name(subject_name):
    """
    Generate short name from first three words.

    Examples:

        Basic English Grammar
        -> BEG

        Advanced Computer Science
        -> ACS

        Introduction to Computer Science
        -> ITC

        English Language
        -> EL

        Mathematics
        -> M
    """

    if not subject_name:
        return None

    words = [
        word.strip()
        for word in str(subject_name).split()
        if word.strip()
    ]

    if not words:
        return None

    short_name = "".join(
        word[0]
        for word in words[:3]
    ).upper()

    # Safety limit
    short_name = short_name[:10]

    return (
        short_name
        if short_name
        else None
    )


# ============================================================
# CALCULATE SUBJECT HOURS AND CREDITS
# ============================================================

def _calculate_subject_hours_and_credits(duration_months):
    """
    Calculate subject workload from program duration.

    Rules:

        Teaching days per week = 5
        Hours per teaching day = 1

        Weekly hours = 5

        Program weeks =
            duration_months * 52 / 12

        Total program hours =
            weekly_hours * program_weeks

        Credit hours =
            total_program_hours / 15

    Examples:

        12 months
            = 52 weeks
            = 260 hours
            = 17.33 credits

        6 months
            = 26 weeks
            = 130 hours
            = 8.67 credits
    """

    if duration_months is None:
        return None, None, None

    try:
        duration_months = Decimal(
            str(duration_months)
        )

    except (
        InvalidOperation,
        TypeError,
        ValueError
    ):
        return None, None, None

    if duration_months <= Decimal("0"):
        return None, None, None

    # --------------------------------------------------------
    # WEEKLY HOURS
    # --------------------------------------------------------

    weekly_hours = (
        SUBJECT_TEACHING_DAYS_PER_WEEK
        * SUBJECT_HOURS_PER_DAY
    )

    # --------------------------------------------------------
    # PROGRAM WEEKS
    # --------------------------------------------------------

    program_weeks = (
        duration_months
        * SUBJECT_WEEKS_PER_YEAR
        / SUBJECT_MONTHS_PER_YEAR
    )

    # --------------------------------------------------------
    # TOTAL PROGRAM HOURS
    # --------------------------------------------------------

    total_program_hours = (
        weekly_hours
        * program_weeks
    )

    # --------------------------------------------------------
    # CREDIT HOURS
    # --------------------------------------------------------

    credit_hours = (
        total_program_hours
        / SUBJECT_HOURS_PER_CREDIT
    )

    return (
        weekly_hours.quantize(
            Decimal("0.01")
        ),
        total_program_hours.quantize(
            Decimal("0.01")
        ),
        credit_hours.quantize(
            Decimal("0.01")
        )
    )


# ============================================================
# GENERATE NEXT SUBJECT CODE
# ============================================================

def _generate_next_subject_code(
    institution_id,
    branch_id
):
    """
    Generate Subject code.

    IMPORTANT RULE:

        Counter is scoped ONLY by:

            institution
            branch

        Program is NOT part of the counter.

    Example:

        Branch A:

            Nursing:
                SUB001
                SUB002

            IT:
                SUB003
                SUB004

            Business:
                SUB005

        Branch B:

            SUB001
    """

    query = (
        Subject.query
        .filter(
            Subject.institution_id
            == institution_id
        )
    )

    # --------------------------------------------------------
    # BRANCH-SCOPED SUBJECTS
    # --------------------------------------------------------

    if branch_id is not None:

        query = query.filter(
            Subject.branch_id
            == branch_id
        )

    # --------------------------------------------------------
    # NULL BRANCH SAFETY
    # --------------------------------------------------------

    else:

        query = query.filter(
            Subject.branch_id.is_(None)
        )

    rows = (
        query
        .with_entities(
            Subject.code
        )
        .all()
    )

    highest_number = 0

    for row in rows:

        existing_code = (
            row[0]
            if row
            else ""
        )

        if not existing_code:
            continue

        existing_code = (
            str(existing_code)
            .strip()
            .upper()
        )

        if not existing_code.startswith(
            "SUB"
        ):
            continue

        number_part = existing_code[3:]

        if not number_part.isdigit():
            continue

        number = int(number_part)

        if number > highest_number:
            highest_number = number

    return (
        f"SUB{highest_number + 1:03d}"
    )


# ============================================================
# GET SUBJECT TYPES
# ============================================================

def _get_subject_type_values():
    """
    Normalize SUBJECT_TYPES enum/list values.
    """

    values = set()

    for item in SUBJECT_TYPES:

        item_value = getattr(
            item,
            "value",
            item
        )

        if item_value is None:
            continue

        value = (
            str(item_value)
            .strip()
            .lower()
        )

        if value:
            values.add(value)

    return values


# ============================================================
# GET SUBJECT STATUS VALUES
# ============================================================

def _get_subject_status_values():
    """
    Normalize SUBJECT_STATUSES enum/list values.
    """

    values = set()

    for item in SUBJECT_STATUSES:

        item_value = getattr(
            item,
            "value",
            item
        )

        if item_value is None:
            continue

        value = (
            str(item_value)
            .strip()
            .lower()
        )

        if value:
            values.add(value)

    return values


# ============================================================
# DATABASE ERROR MESSAGE
# ============================================================

def _subject_integrity_error_message(
    exc,
    subject_code=None,
    short_name=None
):
    """
    Convert PostgreSQL / SQLAlchemy IntegrityError
    into a useful user-facing message.
    """

    original_error = getattr(
        exc,
        "orig",
        exc
    )

    database_error = str(
        original_error
    ).strip()

    error_lower = database_error.lower()

    # --------------------------------------------------------
    # PASS MARKS NOT NULL
    # --------------------------------------------------------

    if (
        "pass_marks" in error_lower
        and (
            "not-null" in error_lower
            or "null value" in error_lower
            or "not null" in error_lower
        )
    ):

        return (
            "Subject could not be created because "
            "the database still requires Pass Marks. "
            "Pass Marks is optional in the application. "
            "Change subjects.pass_marks to nullable=True "
            "and run the database migration."
        )

    # --------------------------------------------------------
    # SUBJECT CODE UNIQUE
    # --------------------------------------------------------

    if (
        "code" in error_lower
        and (
            "duplicate" in error_lower
            or "unique" in error_lower
        )
    ):

        if subject_code:

            return (
                f"Subject code '{subject_code}' "
                "already exists in the database. "
                "Please retry so a new code can be generated."
            )

        return (
            "Subject code already exists in the database."
        )

    # --------------------------------------------------------
    # SHORT NAME UNIQUE
    # --------------------------------------------------------

    if (
        "short_name" in error_lower
        and (
            "duplicate" in error_lower
            or "unique" in error_lower
        )
    ):

        if short_name:

            return (
                f"Short name '{short_name}' "
                "already exists under a database "
                "UNIQUE constraint."
            )

        return (
            "Subject short name already exists "
            "under a database UNIQUE constraint."
        )

    # --------------------------------------------------------
    # SUBJECT NAME UNIQUE
    # --------------------------------------------------------

    if (
        "name" in error_lower
        and (
            "duplicate" in error_lower
            or "unique" in error_lower
        )
    ):

        return (
            "A subject with this name already exists "
            "under a database UNIQUE constraint."
        )

    # --------------------------------------------------------
    # FOREIGN KEY
    # --------------------------------------------------------

    if (
        "foreign key" in error_lower
        or "violates foreign key constraint"
        in error_lower
    ):

        return (
            "The selected institution, branch, or program "
            "is no longer valid. Please reload the page "
            "and try again."
        )

    # --------------------------------------------------------
    # GENERIC UNIQUE ERROR
    # --------------------------------------------------------

    if (
        "unique constraint" in error_lower
        or "duplicate key" in error_lower
        or "duplicate" in error_lower
    ):

        return (
            "A database UNIQUE constraint was violated. "
            "Please check the subject code, short name, "
            "or other unique fields."
        )

    # --------------------------------------------------------
    # GENERIC CONSTRAINT
    # --------------------------------------------------------

    return (
        "Unable to create subject because the database "
        "rejected the record. Please check the Subject "
        "model constraints and database schema."
    )

# ============================================================
# ADD SUBJECT
# ============================================================

@bp.route(
    "/subjects/add",
    methods=["GET", "POST"]
)
@login_required
def add_subject():

    # ========================================================
    # CURRENT USER
    # ========================================================

    user = current_user

    # ========================================================
    # SECURITY
    # ========================================================

    if not user.is_authenticated:
        abort(403)

    # ========================================================
    # NORMALIZE ROLE
    # ========================================================

    role = getattr(
        user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    # ========================================================
    # ALLOWED ROLES
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin"
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # ROLE FLAGS
    # ========================================================

    is_superadmin = (
        role == "superadmin"
    )

    is_school_admin = (
        role == "school_admin"
    )

    is_branch_admin = (
        role == "branch_admin"
    )

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        user,
        "branch_id",
        None
    )

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    if is_branch_admin:

        if not user_institution_id:
            abort(403)

        if not user_branch_id:
            abort(403)

    # ========================================================
    # DEFAULT FORM VALUES
    # ========================================================

    institution_raw = ""
    branch_raw = ""
    program_raw = ""

    name = ""
    short_name = ""

    subject_type = ""

    max_marks_raw = "100"
    pass_marks_raw = ""

    description = ""

    status = "active"

    # ========================================================
    # SELECTED IDS
    # ========================================================

    institution_id = None
    branch_id = None
    program_id = None

    # ========================================================
    # DEFAULT SCOPE FOR GET
    # ========================================================

    if request.method == "GET":

        # ----------------------------------------------------
        # SUPERADMIN
        # ----------------------------------------------------

        if is_superadmin:

            institution_id = None

        # ----------------------------------------------------
        # SCHOOL ADMIN
        # ----------------------------------------------------

        elif is_school_admin:

            institution_id = (
                user_institution_id
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        elif is_branch_admin:

            institution_id = (
                user_institution_id
            )

            branch_id = (
                user_branch_id
            )

    # ========================================================
    # READ POST DATA
    # ========================================================

    if request.method == "POST":

        institution_raw = (
            request.form.get(
                "institution_id"
            )
            or ""
        ).strip()

        branch_raw = (
            request.form.get(
                "branch_id"
            )
            or ""
        ).strip()

        program_raw = (
            request.form.get(
                "program_id"
            )
            or ""
        ).strip()

        name = (
            request.form.get(
                "name"
            )
            or ""
        ).strip()

        short_name = (
            request.form.get(
                "short_name"
            )
            or ""
        ).strip()

        subject_type = (
            request.form.get(
                "subject_type"
            )
            or ""
        ).strip().lower()

        max_marks_raw = (
            request.form.get(
                "max_marks"
            )
            or "100"
        ).strip()

        # IMPORTANT:
        # Pass marks is OPTIONAL.

        pass_marks_raw = (
            request.form.get(
                "pass_marks"
            )
            or ""
        ).strip()

        description = (
            request.form.get(
                "description"
            )
            or ""
        ).strip()

        status = (
            request.form.get(
                "status"
            )
            or "active"
        ).strip().lower()

    # ========================================================
    # ERRORS
    # ========================================================

    errors = {}

    # ========================================================
    # PARSE INSTITUTION
    # ========================================================

    if institution_raw:

        try:

            institution_id = int(
                institution_raw
            )

        except (
            TypeError,
            ValueError
        ):

            errors[
                "institution_id"
            ] = "Invalid institution."

            institution_id = None

    # ========================================================
    # SCHOOL ADMIN INSTITUTION LOCK
    # ========================================================

    if is_school_admin:

        institution_id = (
            user_institution_id
        )

    # ========================================================
    # BRANCH ADMIN INSTITUTION LOCK
    # ========================================================

    elif is_branch_admin:

        institution_id = (
            user_institution_id
        )

    # ========================================================
    # PARSE BRANCH
    # ========================================================

    if branch_raw:

        try:

            branch_id = int(
                branch_raw
            )

        except (
            TypeError,
            ValueError
        ):

            errors[
                "branch_id"
            ] = "Invalid branch."

            branch_id = None

    # ========================================================
    # BRANCH ADMIN BRANCH LOCK
    # ========================================================

    if is_branch_admin:

        branch_id = (
            user_branch_id
        )

    # ========================================================
    # PARSE PROGRAM
    # ========================================================

    if program_raw:

        try:

            program_id = int(
                program_raw
            )

        except (
            TypeError,
            ValueError
        ):

            errors[
                "program_id"
            ] = "Invalid program."

            program_id = None

    # ========================================================
    # INSTITUTION REQUIRED
    # ========================================================

    if not institution_id:

        errors[
            "institution_id"
        ] = "Institution is required."

    # ========================================================
    # BRANCH REQUIRED
    # ========================================================

    if not branch_id:

        errors[
            "branch_id"
        ] = "Branch is required."

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    if (
        is_branch_admin
        and branch_id
        and branch_id != user_branch_id
    ):

        errors[
            "branch_id"
        ] = (
            "You can only manage subjects "
            "in your own branch."
        )

    # ========================================================
    # LOAD INSTITUTION
    # ========================================================

    institution = None

    if institution_id:

        institution = (
            Institution.query
            .filter(
                Institution.id
                == institution_id
            )
            .first()
        )

        if not institution:

            errors[
                "institution_id"
            ] = (
                "Selected institution "
                "does not exist."
            )

    # ========================================================
    # INSTITUTION SCOPE SECURITY
    # ========================================================

    if (
        institution
        and not is_superadmin
        and institution.id
        != user_institution_id
    ):

        errors[
            "institution_id"
        ] = (
            "You can only manage subjects "
            "inside your own institution."
        )

    # ========================================================
    # LOAD BRANCH
    # ========================================================

    branch = None

    if branch_id:

        branch = (
            Branch.query
            .filter(
                Branch.id
                == branch_id
            )
            .first()
        )

        if not branch:

            errors[
                "branch_id"
            ] = (
                "Selected branch "
                "does not exist."
            )

    # ========================================================
    # BRANCH → INSTITUTION VALIDATION
    # ========================================================

    if (
        branch
        and institution
        and branch.institution_id
        != institution.id
    ):

        errors[
            "branch_id"
        ] = (
            "Selected branch does not "
            "belong to the selected institution."
        )

    # ========================================================
    # BRANCH ADMIN OWN BRANCH VALIDATION
    # ========================================================

    if (
        is_branch_admin
        and branch
        and branch.id != user_branch_id
    ):

        errors[
            "branch_id"
        ] = (
            "You can only use your own branch."
        )

    # ========================================================
    # SUBJECT NAME VALIDATION
    # ========================================================

    if not name:

        errors[
            "name"
        ] = "Subject name is required."

    elif len(name) > 200:

        errors[
            "name"
        ] = "Subject name is too long."

    # ========================================================
    # GENERATE SHORT NAME SERVER-SIDE
    # ========================================================

    generated_short_name = (
        _generate_subject_short_name(
            name
        )
        if name
        else None
    )

    if generated_short_name:

        short_name = (
            generated_short_name
        )

    # ========================================================
    # SHORT NAME VALIDATION
    # ========================================================

    if not short_name:

        errors[
            "short_name"
        ] = (
            "Short name could not "
            "be generated."
        )

    elif len(short_name) > 50:

        errors[
            "short_name"
        ] = (
            "Short name is too long."
        )

    # ========================================================
    # SUBJECT TYPE VALUES
    # ========================================================

    valid_subject_types = (
        _get_subject_type_values()
    )

    # ========================================================
    # SUBJECT TYPE VALIDATION
    # ========================================================

    if not subject_type:

        errors[
            "subject_type"
        ] = (
            "Subject type is required."
        )

    elif (
        subject_type
        not in valid_subject_types
    ):

        errors[
            "subject_type"
        ] = (
            "Invalid subject type."
        )

    # ========================================================
    # SUBJECT STATUS VALUES
    # ========================================================

    valid_subject_statuses = (
        _get_subject_status_values()
    )

    # ========================================================
    # STATUS VALIDATION
    # ========================================================

    if (
        status
        not in valid_subject_statuses
    ):

        errors[
            "status"
        ] = (
            "Invalid subject status."
        )

    # ========================================================
    # MAX MARKS
    # ========================================================

    max_marks = _parse_subject_mark(
        max_marks_raw
    )

    if max_marks is None:

        errors[
            "max_marks"
        ] = (
            "Maximum marks must be "
            "a valid number."
        )

    elif max_marks <= Decimal("0"):

        errors[
            "max_marks"
        ] = (
            "Maximum marks must be "
            "greater than zero."
        )

    # ========================================================
    # PASS MARKS
    # ========================================================
    #
    # OPTIONAL
    #
    # Blank = None
    #
    # ========================================================

    pass_marks = None

    if pass_marks_raw:

        pass_marks = _parse_subject_mark(
            pass_marks_raw
        )

        if pass_marks is None:

            errors[
                "pass_marks"
            ] = (
                "Pass marks must be "
                "a valid number."
            )

        elif pass_marks < Decimal("0"):

            errors[
                "pass_marks"
            ] = (
                "Pass marks cannot "
                "be negative."
            )

    # ========================================================
    # PASS MARKS <= MAX MARKS
    # ========================================================

    if (
        max_marks is not None
        and pass_marks is not None
        and pass_marks > max_marks
    ):

        errors[
            "pass_marks"
        ] = (
            "Pass marks cannot be "
            "greater than maximum marks."
        )

    # ========================================================
    # LOAD PROGRAM
    # ========================================================

    program = None

    # --------------------------------------------------------
    # PROGRAM REQUIRED
    # --------------------------------------------------------

    if not program_id:

        errors[
            "program_id"
        ] = "Program is required."

    # --------------------------------------------------------
    # PROGRAM VALIDATION
    # --------------------------------------------------------

    elif institution:

        program = (
            Program.query
            .filter(
                Program.id
                == program_id
            )
            .first()
        )

        if not program:

            errors[
                "program_id"
            ] = (
                "Selected program "
                "does not exist."
            )

        else:

            # ------------------------------------------------
            # PROGRAM → INSTITUTION
            # ------------------------------------------------

            if (
                program.institution_id
                != institution.id
            ):

                errors[
                    "program_id"
                ] = (
                    "Selected program does not "
                    "belong to the selected institution."
                )

            # ------------------------------------------------
            # PROGRAM → BRANCH
            # ------------------------------------------------
            #
            # branch_id NULL = institution-wide
            #
            # branch_id set = branch-specific
            #
            # ------------------------------------------------

            elif (
                branch
                and program.branch_id is not None
                and program.branch_id
                != branch.id
            ):

                errors[
                    "program_id"
                ] = (
                    "Selected program is not "
                    "available in this branch."
                )

    # ========================================================
    # PROGRAM DURATION
    # ========================================================

    weekly_hours = None
    total_program_hours = None
    credit_hours = None

    if program:

        duration_months = getattr(
            program,
            "duration_months",
            None
        )

        try:

            duration_decimal = Decimal(
                str(duration_months)
            )

        except (
            InvalidOperation,
            TypeError,
            ValueError
        ):

            duration_decimal = None

        # ----------------------------------------------------
        # DURATION REQUIRED
        # ----------------------------------------------------

        if (
            duration_decimal is None
            or duration_decimal
            <= Decimal("0")
        ):

            errors[
                "program_id"
            ] = (
                "The selected program must "
                "have a valid duration in months."
            )

        # ----------------------------------------------------
        # CALCULATE
        # ----------------------------------------------------

        else:

            (
                weekly_hours,
                total_program_hours,
                credit_hours
            ) = (
                _calculate_subject_hours_and_credits(
                    duration_decimal
                )
            )

            if (
                weekly_hours is None
                or total_program_hours is None
                or credit_hours is None
            ):

                errors[
                    "program_id"
                ] = (
                    "Unable to calculate subject "
                    "hours and credits from the "
                    "program duration."
                )

    # ========================================================
    # DUPLICATE SUBJECT CHECK
    # ========================================================
    #
    # SAME:
    #   institution
    #   branch
    #   program
    #   normalized name
    #
    # DIFFERENT PROGRAM = ALLOWED
    #
    # ========================================================

    if (
        institution
        and branch
        and program
        and name
    ):

        normalized_new_name = (
            _normalize_subject_name(
                name
            )
        )

        existing_subjects = (
            Subject.query
            .filter(
                Subject.institution_id
                == institution.id,

                Subject.branch_id
                == branch.id,

                Subject.program_id
                == program.id
            )
            .all()
        )

        duplicate_subject = None

        for existing_subject in (
            existing_subjects
        ):

            existing_name = (
                _normalize_subject_name(
                    existing_subject.name
                )
            )

            if (
                existing_name
                == normalized_new_name
            ):

                duplicate_subject = (
                    existing_subject
                )

                break

        if duplicate_subject:

            errors[
                "name"
            ] = (
                "This subject already exists "
                "in the selected program "
                "and branch."
            )

    # ========================================================
    # CREATE SUBJECT
    # ========================================================

    if not errors:

        # ----------------------------------------------------
        # GENERATE SERVER-SIDE CODE
        # ----------------------------------------------------

        subject_code = (
            _generate_next_subject_code(
                institution_id=institution.id,
                branch_id=branch.id
            )
        )

        # ----------------------------------------------------
        # CREATE OBJECT
        # ----------------------------------------------------

        subject = Subject(

            institution_id=(
                institution.id
            ),

            branch_id=(
                branch.id
            ),

            program_id=(
                program.id
            ),

            # IMPORTANT:
            # Never trust code from the form.
            code=subject_code,

            name=name,

            short_name=(
                short_name
            ),

            subject_type=(
                subject_type
            ),

            max_marks=(
                max_marks
            ),

            # IMPORTANT:
            # Optional.
            # Blank -> None.
            pass_marks=(
                pass_marks
            ),

            weekly_hours=(
                weekly_hours
            ),

            credit_hours=(
                credit_hours
            ),

            description=(
                description
                if description
                else None
            ),

            status=(
                status
            )
        )

        # ----------------------------------------------------
        # SAVE
        # ----------------------------------------------------

        try:

            db.session.add(
                subject
            )

            db.session.commit()

            # ------------------------------------------------
            # SUCCESS
            # ------------------------------------------------

            flash(
                (
                    f"Subject '{subject.name}' "
                    f"created successfully with "
                    f"code {subject.code}."
                ),
                "success"
            )

            return redirect(
                url_for(
                    "main.add_subject"
                )
            )

        # ----------------------------------------------------
        # DATABASE ERROR
        # ----------------------------------------------------

        except IntegrityError as exc:

            db.session.rollback()

            error_message = (
                _subject_integrity_error_message(
                    exc,
                    subject_code=(
                        subject_code
                    ),
                    short_name=(
                        short_name
                    )
                )
            )

            flash(
                error_message,
                "danger"
            )

    # ========================================================
    # SELECTED VALUES
    # ========================================================

    selected_institution_id = (
        institution_id
    )

    selected_branch_id = (
        branch_id
    )

    selected_program_id = (
        program_id
    )

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    if is_superadmin:

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == user_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = Branch.query

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if is_superadmin:

        if institution_id:

            branches_query = (
                branches_query
                .filter(
                    Branch.institution_id
                    == institution_id
                )
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN / BRANCH ADMIN
    # --------------------------------------------------------

    else:

        branches_query = (
            branches_query
            .filter(
                Branch.institution_id
                == user_institution_id
            )
        )

    # --------------------------------------------------------
    # BRANCH ADMIN OWN BRANCH ONLY
    # --------------------------------------------------------

    if is_branch_admin:

        branches_query = (
            branches_query
            .filter(
                Branch.id
                == user_branch_id
            )
        )

    # --------------------------------------------------------
    # LOAD BRANCHES
    # --------------------------------------------------------

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    programs_query = Program.query

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if is_superadmin:

        if institution_id:

            programs_query = (
                programs_query
                .filter(
                    Program.institution_id
                    == institution_id
                )
            )

        else:

            # No institution selected.
            # Return empty program list.
            programs_query = (
                programs_query
                .filter(
                    Program.institution_id
                    == -1
                )
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN / BRANCH ADMIN
    # --------------------------------------------------------

    else:

        programs_query = (
            programs_query
            .filter(
                Program.institution_id
                == user_institution_id
            )
        )

    # --------------------------------------------------------
    # BRANCH PROGRAM FILTER
    # --------------------------------------------------------
    #
    # Program.branch_id NULL:
    #   Institution-wide
    #
    # Program.branch_id = selected branch:
    #   Branch-specific
    #
    # --------------------------------------------------------

    if branch_id:

        programs_query = (
            programs_query
            .filter(
                db.or_(
                    Program.branch_id
                    == branch_id,

                    Program.branch_id.is_(None)
                )
            )
        )

    # --------------------------------------------------------
    # LOAD PROGRAMS
    # --------------------------------------------------------

    programs = (
        programs_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER TEMPLATE
    # ========================================================

    return render_template(
        "backend/pages/subjects/add_subject.html",

        # ----------------------------------------------------
        # USER
        # ----------------------------------------------------

        user=user,

        # ----------------------------------------------------
        # SELECT OPTIONS
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        programs=programs,

        # ----------------------------------------------------
        # SELECTED VALUES
        # ----------------------------------------------------

        selected_institution_id=(
            selected_institution_id
        ),

        selected_branch_id=(
            selected_branch_id
        ),

        selected_program_id=(
            selected_program_id
        ),

        # ----------------------------------------------------
        # SUBJECT FIELDS
        # ----------------------------------------------------

        name=name,

        short_name=short_name,

        subject_type=subject_type,

        max_marks=(
            max_marks_raw
            if max_marks_raw
            else "100"
        ),

        # IMPORTANT:
        # Blank is preserved.
        # Do NOT convert blank to 0 or 50.

        pass_marks=(
            pass_marks_raw
        ),

        description=description,

        status=status,

        # ----------------------------------------------------
        # VALIDATION ERRORS
        # ----------------------------------------------------

        errors=errors,

        # ----------------------------------------------------
        # CALCULATED VALUES
        # ----------------------------------------------------

        weekly_hours=(
            weekly_hours
        ),

        total_program_hours=(
            total_program_hours
        ),

        credit_hours=(
            credit_hours
        ),

        # ----------------------------------------------------
        # ENUM / CHOICES
        # ----------------------------------------------------

        subject_types=(
            SUBJECT_TYPES
        ),

        subject_statuses=(
            SUBJECT_STATUSES
        )
    )



# ============================================================
# VIEW SUBJECT
# ============================================================

@bp.route(
    "/subjects/<int:subject_id>",
    methods=["GET"]
)
@login_required
def view_subject(subject_id):

    # ========================================================
    # GET SUBJECT
    # ========================================================

    query = Subject.query.filter(
        Subject.id == subject_id
    )

    query = _subject_scope_query(
        query
    )

    subject = query.first()


    # ========================================================
    # NOT FOUND
    # ========================================================

    if not subject:

        flash(
            "Subject not found or you do not have permission to view it.",
            "warning"
        )

        return redirect(
            url_for("main.all_subjects")
        )


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/subjects/view_subject.html",
        subject=subject,
        user=current_user
    )


# ============================================================
# EDIT SUBJECT
# ============================================================
# ============================================================
# EDIT SUBJECT
# ============================================================

@bp.route(
    "/subjects/<int:subject_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_subject(subject_id):

    # ========================================================
    # GET SUBJECT
    # ========================================================

    subject = Subject.query.get_or_404(
        subject_id
    )

    # ========================================================
    # CURRENT USER
    # ========================================================

    user = current_user

    # ========================================================
    # CURRENT USER ROLE
    # ========================================================

    current_role = getattr(
        user,
        "role",
        None
    )

    # --------------------------------------------------------
    # ENUM SAFE
    # --------------------------------------------------------

    current_role = getattr(
        current_role,
        "value",
        current_role
    )

    current_role = (
        str(current_role).strip().lower()
        if current_role
        else None
    )

    # ========================================================
    # ALLOWED ROLES
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin"
    }

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to edit subjects.",
            "danger"
        )

        return redirect(
            url_for("main.subjects")
        )

    # ========================================================
    # ROLE FLAGS
    # ========================================================

    is_superadmin = (
        current_role == "superadmin"
    )

    is_school_admin = (
        current_role == "school_admin"
    )

    is_branch_admin = (
        current_role == "branch_admin"
    )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        user,
        "branch_id",
        None
    )

    # ========================================================
    # REQUIRED USER SCOPE
    # ========================================================

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if is_school_admin:

        if not current_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.subjects")
            )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    if is_branch_admin:

        if not current_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.subjects")
            )

        if not current_branch_id:

            flash(
                "Your account is not assigned to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.subjects")
            )

    # ========================================================
    # EXISTING SUBJECT SECURITY
    # ========================================================

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if is_school_admin:

        if (
            subject.institution_id
            != current_institution_id
        ):

            flash(
                "You are not authorized to edit this subject.",
                "danger"
            )

            return redirect(
                url_for("main.subjects")
            )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif is_branch_admin:

        # ----------------------------------------------------
        # INSTITUTION MUST MATCH
        # ----------------------------------------------------

        if (
            subject.institution_id
            != current_institution_id
        ):

            flash(
                "You are not authorized to edit this subject.",
                "danger"
            )

            return redirect(
                url_for("main.subjects")
            )

        # ----------------------------------------------------
        # BRANCH MUST MATCH EXACTLY
        #
        # branch_id=None is not editable by branch_admin.
        # ----------------------------------------------------

        if (
            subject.branch_id
            != current_branch_id
        ):

            flash(
                "You are not authorized to edit a subject "
                "outside your assigned branch.",
                "danger"
            )

            return redirect(
                url_for("main.subjects")
            )

    # ========================================================
    # FORM VALUES
    # ========================================================

    errors = {}

    # ========================================================
    # DEFAULT VALUES FROM EXISTING SUBJECT
    # ========================================================

    institution_id = (
        subject.institution_id
    )

    branch_id = (
        subject.branch_id
    )

    program_id = (
        subject.program_id
    )

    name = (
        subject.name or ""
    ).strip()

    short_name = (
        subject.short_name or ""
    ).strip()

    subject_type = (
        subject.subject_type or ""
    ).strip().lower()

    status = (
        subject.status or "active"
    ).strip().lower()

    max_marks_raw = (
        str(subject.max_marks)
        if subject.max_marks is not None
        else "100"
    )

    pass_marks_raw = (
        str(subject.pass_marks)
        if subject.pass_marks is not None
        else ""
    )

    description = (
        subject.description or ""
    ).strip()

    weekly_hours = (
        subject.weekly_hours
    )

    total_program_hours = None

    credit_hours = (
        subject.credit_hours
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # READ FORM
        # ====================================================

        institution_raw = (
            request.form.get(
                "institution_id"
            )
            or ""
        ).strip()

        branch_raw = (
            request.form.get(
                "branch_id"
            )
            or ""
        ).strip()

        program_raw = (
            request.form.get(
                "program_id"
            )
            or ""
        ).strip()

        name = (
            request.form.get(
                "name"
            )
            or ""
        ).strip()

        max_marks_raw = (
            request.form.get(
                "max_marks"
            )
            or "100"
        ).strip()

        pass_marks_raw = (
            request.form.get(
                "pass_marks"
            )
            or ""
        ).strip()

        description = (
            request.form.get(
                "description"
            )
            or ""
        ).strip()

        subject_type = (
            request.form.get(
                "subject_type"
            )
            or "academic"
        ).strip().lower()

        status = (
            request.form.get(
                "status"
            )
            or "active"
        ).strip().lower()

        # ====================================================
        # IMPORTANT:
        # SHORT NAME IS NOT TRUSTED FROM FORM
        # ====================================================

        short_name = ""

        # ====================================================
        # IMPORTANT:
        # SUBJECT CODE IS NEVER READ FROM FORM
        # ====================================================

        code = (
            subject.code or ""
        ).strip().upper()

        # ====================================================
        # INSTITUTION
        # ====================================================

        if is_superadmin:

            if not institution_raw:

                errors[
                    "institution_id"
                ] = (
                    "Institution is required."
                )

            else:

                try:

                    institution_id = int(
                        institution_raw
                    )

                    if institution_id <= 0:
                        raise ValueError

                except (
                    TypeError,
                    ValueError
                ):

                    institution_id = None

                    errors[
                        "institution_id"
                    ] = (
                        "Invalid institution."
                    )

        else:

            # ------------------------------------------------
            # NEVER TRUST FORM FOR ADMIN SCOPE
            # ------------------------------------------------

            institution_id = (
                current_institution_id
            )

        # ====================================================
        # BRANCH
        # ====================================================

        if is_branch_admin:

            # ------------------------------------------------
            # FORCE CURRENT BRANCH
            # ------------------------------------------------

            branch_id = (
                current_branch_id
            )

        else:

            if not branch_raw:

                errors[
                    "branch_id"
                ] = (
                    "Branch is required."
                )

                branch_id = None

            else:

                try:

                    branch_id = int(
                        branch_raw
                    )

                    if branch_id <= 0:
                        raise ValueError

                except (
                    TypeError,
                    ValueError
                ):

                    branch_id = None

                    errors[
                        "branch_id"
                    ] = (
                        "Invalid branch."
                    )

        # ====================================================
        # PROGRAM
        # ====================================================

        if not program_raw:

            program_id = None

            errors[
                "program_id"
            ] = (
                "Program is required."
            )

        else:

            try:

                program_id = int(
                    program_raw
                )

                if program_id <= 0:
                    raise ValueError

            except (
                TypeError,
                ValueError
            ):

                program_id = None

                errors[
                    "program_id"
                ] = (
                    "Invalid program."
                )

        # ====================================================
        # SUBJECT NAME
        # ====================================================

        if not name:

            errors[
                "name"
            ] = (
                "Subject name is required."
            )

        elif len(name) > 150:

            errors[
                "name"
            ] = (
                "Subject name cannot exceed "
                "150 characters."
            )

        # ====================================================
        # GENERATE SHORT NAME
        # ====================================================

        generated_short_name = (
            _generate_subject_short_name(
                name
            )
            if name
            else None
        )

        if generated_short_name:

            short_name = (
                generated_short_name
            )

        else:

            errors[
                "short_name"
            ] = (
                "Unable to generate subject short name."
            )

        # ====================================================
        # SUBJECT CODE
        # ====================================================
        #
        # Existing code is preserved.
        #
        # Edit route NEVER generates a new code.
        #
        # ====================================================

        if not code:

            errors[
                "code"
            ] = (
                "This subject does not have "
                "a valid subject code."
            )

        # ====================================================
        # SUBJECT TYPE
        # ====================================================

        valid_subject_types = (
            _get_subject_type_values()
        )

        if not subject_type:

            errors[
                "subject_type"
            ] = (
                "Subject type is required."
            )

        elif (
            subject_type
            not in valid_subject_types
        ):

            errors[
                "subject_type"
            ] = (
                "Invalid subject type."
            )

        # ====================================================
        # STATUS
        # ====================================================

        valid_subject_statuses = (
            _get_subject_status_values()
        )

        if (
            status
            not in valid_subject_statuses
        ):

            errors[
                "status"
            ] = (
                "Invalid subject status."
            )

        # ====================================================
        # MAX MARKS
        # ====================================================

        max_marks = _parse_subject_mark(
            max_marks_raw
        )

        if max_marks is None:

            errors[
                "max_marks"
            ] = (
                "Maximum marks must be "
                "a valid number."
            )

        elif max_marks <= Decimal("0"):

            errors[
                "max_marks"
            ] = (
                "Maximum marks must be "
                "greater than zero."
            )

        # ====================================================
        # PASS MARKS
        # ====================================================
        #
        # OPTIONAL
        #
        # Blank = None
        #
        # ====================================================

        pass_marks = None

        if pass_marks_raw:

            pass_marks = _parse_subject_mark(
                pass_marks_raw
            )

            if pass_marks is None:

                errors[
                    "pass_marks"
                ] = (
                    "Pass marks must be "
                    "a valid number."
                )

            elif pass_marks < Decimal("0"):

                errors[
                    "pass_marks"
                ] = (
                    "Pass marks cannot "
                    "be negative."
                )

        # ====================================================
        # PASS MARKS <= MAX MARKS
        # ====================================================

        if (
            max_marks is not None
            and pass_marks is not None
            and pass_marks > max_marks
        ):

            errors[
                "pass_marks"
            ] = (
                "Pass marks cannot be greater "
                "than maximum marks."
            )

        # ====================================================
        # INSTITUTION VALIDATION
        # ====================================================

        institution = None

        if institution_id:

            institution = (
                Institution.query
                .filter(
                    Institution.id
                    == institution_id
                )
                .first()
            )

            if not institution:

                errors[
                    "institution_id"
                ] = (
                    "Selected institution "
                    "does not exist."
                )

        else:

            errors[
                "institution_id"
            ] = (
                "Institution is required."
            )

        # ====================================================
        # USER INSTITUTION SCOPE
        # ====================================================

        if (
            institution
            and not is_superadmin
            and institution.id
            != current_institution_id
        ):

            errors[
                "institution_id"
            ] = (
                "You can only manage subjects "
                "inside your own institution."
            )

        # ====================================================
        # BRANCH VALIDATION
        # ====================================================

        branch = None

        if branch_id:

            branch = (
                Branch.query
                .filter(
                    Branch.id
                    == branch_id
                )
                .first()
            )

            if not branch:

                errors[
                    "branch_id"
                ] = (
                    "Selected branch "
                    "does not exist."
                )

        else:

            errors[
                "branch_id"
            ] = (
                "Branch is required."
            )

        # ====================================================
        # BRANCH → INSTITUTION
        # ====================================================

        if (
            branch
            and institution
            and branch.institution_id
            != institution.id
        ):

            errors[
                "branch_id"
            ] = (
                "Selected branch does not "
                "belong to the selected institution."
            )

        # ====================================================
        # BRANCH ADMIN → OWN BRANCH
        # ====================================================

        if (
            is_branch_admin
            and branch
            and branch.id
            != current_branch_id
        ):

            errors[
                "branch_id"
            ] = (
                "You can only use your own branch."
            )

        # ====================================================
        # PROGRAM VALIDATION
        # ====================================================

        program = None

        if program_id:

            program = (
                Program.query
                .filter(
                    Program.id
                    == program_id
                )
                .first()
            )

            if not program:

                errors[
                    "program_id"
                ] = (
                    "Selected program "
                    "does not exist."
                )

        # ====================================================
        # PROGRAM → INSTITUTION
        # ====================================================

        if (
            program
            and institution
            and program.institution_id
            != institution.id
        ):

            errors[
                "program_id"
            ] = (
                "Selected program does not "
                "belong to the selected institution."
            )

        # ====================================================
        # PROGRAM → BRANCH
        # ====================================================
        #
        # Allowed:
        #
        # program.branch_id == selected branch
        #
        # OR:
        #
        # program.branch_id == NULL
        #
        # ====================================================

        if (
            program
            and branch
            and program.branch_id is not None
            and program.branch_id
            != branch.id
        ):

            errors[
                "program_id"
            ] = (
                "Selected program is not "
                "available in this branch."
            )

        # ====================================================
        # BRANCH ADMIN → PROGRAM SECURITY
        # ====================================================

        if (
            is_branch_admin
            and program
        ):

            if (
                program.institution_id
                != current_institution_id
            ):

                errors[
                    "program_id"
                ] = (
                    "You cannot use a program "
                    "outside your institution."
                )

            elif (
                program.branch_id is not None
                and program.branch_id
                != current_branch_id
            ):

                errors[
                    "program_id"
                ] = (
                    "You cannot use a program "
                    "outside your assigned branch."
                )

        # ====================================================
        # PROGRAM DURATION
        # ====================================================
        #
        # Weekly hours and credit hours are recalculated
        # from Program.duration_months.
        #
        # Do NOT trust values from form.
        #
        # ====================================================

        weekly_hours = None
        total_program_hours = None
        credit_hours = None

        if program:

            duration_months = getattr(
                program,
                "duration_months",
                None
            )

            try:

                duration_decimal = Decimal(
                    str(duration_months)
                )

            except (
                InvalidOperation,
                TypeError,
                ValueError
            ):

                duration_decimal = None

            if (
                duration_decimal is None
                or duration_decimal
                <= Decimal("0")
            ):

                errors[
                    "program_id"
                ] = (
                    "The selected program must "
                    "have a valid duration in months."
                )

            else:

                (
                    weekly_hours,
                    total_program_hours,
                    credit_hours
                ) = (
                    _calculate_subject_hours_and_credits(
                        duration_decimal
                    )
                )

                if (
                    weekly_hours is None
                    or total_program_hours is None
                    or credit_hours is None
                ):

                    errors[
                        "program_id"
                    ] = (
                        "Unable to calculate subject "
                        "hours and credits from the "
                        "program duration."
                    )

        # ====================================================
        # DUPLICATE SUBJECT NAME
        # ====================================================
        #
        # IMPORTANT:
        #
        # Same name in different programs = ALLOWED
        #
        # Same name in same:
        #
        # institution
        # branch
        # program
        #
        # = NOT ALLOWED
        #
        # ====================================================

        if (
            institution
            and branch
            and program
            and name
        ):

            normalized_new_name = (
                _normalize_subject_name(
                    name
                )
            )

            existing_subjects = (
                Subject.query
                .filter(
                    Subject.institution_id
                    == institution.id,

                    Subject.branch_id
                    == branch.id,

                    Subject.program_id
                    == program.id,

                    Subject.id
                    != subject.id
                )
                .all()
            )

            duplicate_subject = None

            for existing_subject in (
                existing_subjects
            ):

                existing_name = (
                    _normalize_subject_name(
                        existing_subject.name
                    )
                )

                if (
                    existing_name
                    == normalized_new_name
                ):

                    duplicate_subject = (
                        existing_subject
                    )

                    break

            if duplicate_subject:

                errors[
                    "name"
                ] = (
                    "This subject already exists "
                    "in the selected program "
                    "and branch."
                )

        # ====================================================
        # DUPLICATE SUBJECT CODE
        # ====================================================
        #
        # Code remains unchanged.
        #
        # Code uniqueness:
        #
        # institution + branch + code
        #
        # ====================================================

        if (
            institution
            and branch
            and code
        ):

            duplicate_code = (
                Subject.query
                .filter(
                    Subject.id
                    != subject.id,

                    Subject.institution_id
                    == institution.id,

                    Subject.branch_id
                    == branch.id,

                    db.func.upper(
                        Subject.code
                    )
                    == code.upper()
                )
                .first()
            )

            if duplicate_code:

                errors[
                    "code"
                ] = (
                    f"Subject code '{code}' "
                    "is already used in this "
                    "institution and branch."
                )

        # ====================================================
        # VALIDATION FAILED
        # ====================================================

        if errors:

            # ------------------------------------------------
            # FLASH UNIQUE ERRORS
            # ------------------------------------------------

            for message in errors.values():

                flash(
                    message,
                    "danger"
                )

            # ------------------------------------------------
            # LOAD FORM OPTIONS
            # ------------------------------------------------

            if is_superadmin:

                institutions = (
                    Institution.query
                    .order_by(
                        Institution.name.asc()
                    )
                    .all()
                )

                branches_query = Branch.query

                if institution_id:

                    branches_query = (
                        branches_query
                        .filter(
                            Branch.institution_id
                            == institution_id
                        )
                    )

                branches = (
                    branches_query
                    .order_by(
                        Branch.name.asc()
                    )
                    .all()
                )

                programs_query = Program.query

                if institution_id:

                    programs_query = (
                        programs_query
                        .filter(
                            Program.institution_id
                            == institution_id
                        )
                    )

                else:

                    programs_query = (
                        programs_query
                        .filter(
                            Program.id == -1
                        )
                    )

                if branch_id:

                    programs_query = (
                        programs_query
                        .filter(
                            db.or_(
                                Program.branch_id
                                == branch_id,

                                Program.branch_id.is_(None)
                            )
                        )
                    )

                programs = (
                    programs_query
                    .order_by(
                        Program.name.asc()
                    )
                    .all()
                )

            elif is_school_admin:

                institutions = (
                    Institution.query
                    .filter(
                        Institution.id
                        == current_institution_id
                    )
                    .order_by(
                        Institution.name.asc()
                    )
                    .all()
                )

                branches = (
                    Branch.query
                    .filter(
                        Branch.institution_id
                        == current_institution_id
                    )
                    .order_by(
                        Branch.name.asc()
                    )
                    .all()
                )

                programs_query = (
                    Program.query
                    .filter(
                        Program.institution_id
                        == current_institution_id
                    )
                )

                if branch_id:

                    programs_query = (
                        programs_query
                        .filter(
                            db.or_(
                                Program.branch_id
                                == branch_id,

                                Program.branch_id.is_(None)
                            )
                        )
                    )

                programs = (
                    programs_query
                    .order_by(
                        Program.name.asc()
                    )
                    .all()
                )

            else:

                # ------------------------------------------------
                # BRANCH ADMIN
                # ------------------------------------------------

                institutions = (
                    Institution.query
                    .filter(
                        Institution.id
                        == current_institution_id
                    )
                    .order_by(
                        Institution.name.asc()
                    )
                    .all()
                )

                branches = (
                    Branch.query
                    .filter(
                        Branch.id
                        == current_branch_id,

                        Branch.institution_id
                        == current_institution_id
                    )
                    .order_by(
                        Branch.name.asc()
                    )
                    .all()
                )

                programs = (
                    Program.query
                    .filter(
                        Program.institution_id
                        == current_institution_id,

                        db.or_(
                            Program.branch_id
                            == current_branch_id,

                            Program.branch_id.is_(None)
                        )
                    )
                    .order_by(
                        Program.name.asc()
                    )
                    .all()
                )

            # ------------------------------------------------
            # RENDER AGAIN
            # ------------------------------------------------

            return render_template(
                "backend/pages/subjects/edit_subject.html",

                user=user,

                institutions=institutions,

                branches=branches,

                programs=programs,

                subject=subject,

                is_superadmin=(
                    is_superadmin
                ),

                is_school_admin=(
                    is_school_admin
                ),

                is_branch_admin=(
                    is_branch_admin
                ),

                current_user_institution_id=(
                    current_institution_id
                ),

                current_user_branch_id=(
                    current_branch_id
                ),

                selected_institution_id=(
                    institution_id
                ),

                selected_branch_id=(
                    branch_id
                ),

                selected_program_id=(
                    program_id
                ),

                # --------------------------------------------
                # FORM VALUES
                # --------------------------------------------

                name=name,

                short_name=short_name,

                subject_type=subject_type,

                max_marks=max_marks_raw,

                pass_marks=pass_marks_raw,

                description=description,

                status=status,

                # --------------------------------------------
                # CALCULATED VALUES
                # --------------------------------------------

                weekly_hours=(
                    weekly_hours
                ),

                total_program_hours=(
                    total_program_hours
                ),

                credit_hours=(
                    credit_hours
                ),

                # --------------------------------------------
                # ENUM VALUES
                # --------------------------------------------

                subject_types=(
                    SUBJECT_TYPES
                ),

                subject_statuses=(
                    SUBJECT_STATUSES
                ),

                # --------------------------------------------
                # ERRORS
                # --------------------------------------------

                errors=errors
            )

        # ====================================================
        # UPDATE SUBJECT
        # ====================================================

        try:

            # ------------------------------------------------
            # INSTITUTION
            # ------------------------------------------------

            subject.institution_id = (
                institution.id
            )

            # ------------------------------------------------
            # BRANCH
            # ------------------------------------------------

            subject.branch_id = (
                branch.id
            )

            # ------------------------------------------------
            # PROGRAM
            # ------------------------------------------------

            subject.program_id = (
                program.id
            )

            # ------------------------------------------------
            # SUBJECT NAME
            # ------------------------------------------------

            subject.name = (
                name
            )

            # ------------------------------------------------
            # SHORT NAME
            # ------------------------------------------------
            #
            # Generated server-side.
            #
            # ------------------------------------------------

            subject.short_name = (
                short_name
            )

            # ------------------------------------------------
            # CODE
            # ------------------------------------------------
            #
            # NEVER CHANGE CODE DURING EDIT.
            #
            # ------------------------------------------------

            subject.code = (
                code
            )

            # ------------------------------------------------
            # SUBJECT TYPE
            # ------------------------------------------------

            subject.subject_type = (
                subject_type
            )

            # ------------------------------------------------
            # WEEKLY HOURS
            # ------------------------------------------------

            subject.weekly_hours = (
                weekly_hours
            )

            # ------------------------------------------------
            # CREDIT HOURS
            # ------------------------------------------------

            subject.credit_hours = (
                credit_hours
            )

            # ------------------------------------------------
            # MAX MARKS
            # ------------------------------------------------

            subject.max_marks = (
                max_marks
            )

            # ------------------------------------------------
            # PASS MARKS
            # ------------------------------------------------
            #
            # Optional.
            #
            # Blank = None.
            #
            # ------------------------------------------------

            subject.pass_marks = (
                pass_marks
            )

            # ------------------------------------------------
            # DESCRIPTION
            # ------------------------------------------------

            subject.description = (
                description
            )

            # ------------------------------------------------
            # STATUS
            # ------------------------------------------------

            subject.status = (
                status
            )

            # ------------------------------------------------
            # UPDATED TIMESTAMP
            # ------------------------------------------------

            subject.updated_at = (
                datetime.utcnow()
            )

            # ------------------------------------------------
            # SAVE
            # ------------------------------------------------

            db.session.commit()

            # ------------------------------------------------
            # SUCCESS
            # ------------------------------------------------

            flash(
                (
                    f'Subject "{subject.name}" '
                    f'updated successfully.'
                ),
                "success"
            )

            return redirect(
                url_for(
                    "main.view_subject",
                    subject_id=subject.id
                )
            )

        # ====================================================
        # DATABASE INTEGRITY ERROR
        # ====================================================

        except IntegrityError as exc:

            db.session.rollback()

            current_app.logger.exception(
                "IntegrityError while editing "
                "subject ID %s",
                subject.id
            )

            error_message = (
                _subject_integrity_error_message(
                    exc,
                    subject_code=code,
                    short_name=short_name
                )
            )

            flash(
                error_message,
                "danger"
            )

        # ====================================================
        # GENERAL ERROR
        # ====================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Unexpected error while updating "
                "subject ID %s: %s",
                subject.id,
                exc
            )

            flash(
                "An unexpected error occurred while "
                "updating the subject.",
                "danger"
            )

    # ========================================================
    # GET / FAILED POST AFTER DATABASE ERROR
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    if is_superadmin:

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == current_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = Branch.query

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if is_superadmin:

        if institution_id:

            branches_query = (
                branches_query
                .filter(
                    Branch.institution_id
                    == institution_id
                )
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    else:

        branches_query = (
            branches_query
            .filter(
                Branch.institution_id
                == current_institution_id
            )
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    if is_branch_admin:

        branches_query = (
            branches_query
            .filter(
                Branch.id
                == current_branch_id
            )
        )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    programs_query = Program.query

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if is_superadmin:

        if institution_id:

            programs_query = (
                programs_query
                .filter(
                    Program.institution_id
                    == institution_id
                )
            )

        else:

            programs_query = (
                programs_query
                .filter(
                    Program.id == -1
                )
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN / BRANCH ADMIN
    # --------------------------------------------------------

    else:

        programs_query = (
            programs_query
            .filter(
                Program.institution_id
                == current_institution_id
            )
        )

    # --------------------------------------------------------
    # BRANCH PROGRAMS
    # --------------------------------------------------------

    if branch_id:

        programs_query = (
            programs_query
            .filter(
                db.or_(
                    Program.branch_id
                    == branch_id,

                    Program.branch_id.is_(None)
                )
            )
        )

    # --------------------------------------------------------
    # LOAD PROGRAMS
    # --------------------------------------------------------

    programs = (
        programs_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER EDIT PAGE
    # ========================================================

    return render_template(
        "backend/pages/subjects/edit_subject.html",

        # ----------------------------------------------------
        # USER
        # ----------------------------------------------------

        user=user,

        # ----------------------------------------------------
        # SELECT OPTIONS
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        programs=programs,

        # ----------------------------------------------------
        # SUBJECT
        # ----------------------------------------------------

        subject=subject,

        # ----------------------------------------------------
        # ROLE FLAGS
        # ----------------------------------------------------

        is_superadmin=(
            is_superadmin
        ),

        is_school_admin=(
            is_school_admin
        ),

        is_branch_admin=(
            is_branch_admin
        ),

        # ----------------------------------------------------
        # USER SCOPE
        # ----------------------------------------------------

        current_user_institution_id=(
            current_institution_id
        ),

        current_user_branch_id=(
            current_branch_id
        ),

        # ----------------------------------------------------
        # SELECTED VALUES
        # ----------------------------------------------------

        selected_institution_id=(
            subject.institution_id
        ),

        selected_branch_id=(
            subject.branch_id
        ),

        selected_program_id=(
            subject.program_id
        ),

        # ----------------------------------------------------
        # FORM VALUES
        # ----------------------------------------------------

        name=name,

        short_name=short_name,

        subject_type=subject_type,

        max_marks=max_marks_raw,

        pass_marks=pass_marks_raw,

        description=description,

        status=status,

        # ----------------------------------------------------
        # CALCULATED VALUES
        # ----------------------------------------------------

        weekly_hours=(
            weekly_hours
        ),

        total_program_hours=(
            total_program_hours
        ),

        credit_hours=(
            credit_hours
        ),

        # ----------------------------------------------------
        # CHOICES
        # ----------------------------------------------------

        subject_types=(
            SUBJECT_TYPES
        ),

        subject_statuses=(
            SUBJECT_STATUSES
        ),

        # ----------------------------------------------------
        # ERRORS
        # ----------------------------------------------------

        errors=errors
    )

# ============================================================
# GLOBAL INSTITUTION / BRANCH CONTEXT
# ============================================================

@bp.app_context_processor
def inject_global_school_context():

    institution = None
    branch = None

    try:

        # ----------------------------------------------------
        # Current logged-in user
        # ----------------------------------------------------

        if current_user.is_authenticated:

            # ------------------------------------------------
            # Institution
            # ------------------------------------------------

            if getattr(current_user, "institution_id", None):

                institution = Institution.query.get(
                    current_user.institution_id
                )

            # ------------------------------------------------
            # Branch
            # ------------------------------------------------

            if getattr(current_user, "branch_id", None):

                branch = Branch.query.get(
                    current_user.branch_id
                )

    except Exception:

        # Global template context waa inuusan page-ka
        # jabin haddii record-ku uusan jirin.
        institution = None
        branch = None

    return {
        "institution": institution,
        "branch": branch,
    }

# ============================================================
# DELETE SUBJECT
# ============================================================

@bp.route(
    "/subjects/<int:subject_id>/delete",
    methods=["POST"]
)
@login_required
def delete_subject(subject_id):

    # ========================================================
    # GET SUBJECT WITH SECURITY SCOPE
    # ========================================================

    query = Subject.query.filter(
        Subject.id == subject_id
    )

    query = _subject_scope_query(
        query
    )

    subject = query.first()


    # ========================================================
    # NOT FOUND
    # ========================================================

    if not subject:

        flash(
            "Subject not found or you do not have permission to delete it.",
            "warning"
        )

        return redirect(
            url_for("main.all_subjects")
        )


    subject_name = (
        subject.name
    )


    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            subject
        )

        db.session.commit()

        flash(
            f'Subject "{subject_name}" was deleted successfully.',
            "success"
        )


    except IntegrityError:

        db.session.rollback()

        flash(
            "This subject cannot be deleted because it is "
            "currently referenced by other academic records.",
            "danger"
        )


    except Exception:

        db.session.rollback()

        flash(
            "An unexpected error occurred while deleting the subject.",
            "danger"
        )


    return redirect(
        url_for(
            "main.all_subjects"
        )
    )


# ============================================================
# TEACHER ROUTES
# PostgreSQL / Neon
# ============================================================

# ============================================================
# TEACHER CONSTANTS
# ============================================================

TEACHER_GENDERS = [
    "male",
    "female",
    "other",
]

TEACHER_STATUSES = [
    "active",
    "inactive",
    "suspended",
    "resigned",
]


# ============================================================
# TEACHER ACCESS HELPERS
# ============================================================

def _teacher_is_global_user():
    """
    Global users can manage teachers across institutions.
    """

    return (
        getattr(current_user, "role", None)
        in {
            "superadmin",
            "super_admin",
            "admin",
            "system_admin",
        }
    )


def _teacher_get_user_institution_id():
    """
    Return current user's institution ID.

    Global users:
        None

    Institution-scoped users:
        institution_id
    """

    if _teacher_is_global_user():
        return None

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    if institution_id:
        try:
            return int(institution_id)
        except (TypeError, ValueError):
            return None

    return None


def _teacher_get_user_branch_id():
    """
    Return current user's branch ID.
    """

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if branch_id:
        try:
            return int(branch_id)
        except (TypeError, ValueError):
            return None

    return None


def _teacher_can_manage():
    """
    Roles allowed to manage teachers.
    """

    return (
        getattr(current_user, "role", None)
        in {
            "superadmin",
            "super_admin",
            "admin",
            "system_admin",
            "institution_admin",
            "branch_admin",
        }
    )


# ============================================================
# ALLOWED INSTITUTIONS
# ============================================================

def _teacher_allowed_institutions():

    if _teacher_is_global_user():

        return Institution.query.order_by(
            Institution.name.asc()
        ).all()

    institution_id = _teacher_get_user_institution_id()

    if institution_id is None:
        return []

    institution = Institution.query.filter(
        Institution.id == institution_id
    ).first()

    return [institution] if institution else []


# ============================================================
# ALLOWED BRANCHES
# ============================================================

def _teacher_allowed_branches(institution_id=None):

    query = Branch.query

    if institution_id is not None:

        query = query.filter(
            Branch.institution_id == institution_id
        )

    if not _teacher_is_global_user():

        user_institution_id = (
            _teacher_get_user_institution_id()
        )

        if user_institution_id is None:
            return []

        query = query.filter(
            Branch.institution_id == user_institution_id
        )

        if getattr(current_user, "role", None) == "branch_admin":

            user_branch_id = (
                _teacher_get_user_branch_id()
            )

            if user_branch_id is None:
                return []

            query = query.filter(
                Branch.id == user_branch_id
            )

    return query.order_by(
        Branch.name.asc()
    ).all()


# ============================================================
# TEACHER FORM CONTEXT
# ============================================================

def _teacher_form_context(institution_id=None):

    return {
        "user": current_user,

        "institutions":
            _teacher_allowed_institutions(),

        "branches":
            _teacher_allowed_branches(institution_id),

        "teacher_genders":
            TEACHER_GENDERS,

        "teacher_statuses":
            TEACHER_STATUSES,
    }


# ============================================================
# VALIDATE INSTITUTION / BRANCH
# ============================================================

def _validate_teacher_relationships(
    institution_id,
    branch_id,
    errors
):

    if not institution_id:
        errors.append(
            "Institution is required."
        )
        return

    institution = Institution.query.filter(
        Institution.id == institution_id
    ).first()

    if not institution:
        errors.append(
            "Selected institution was not found."
        )
        return

    # --------------------------------------------------------
    # Scoped user cannot select another institution
    # --------------------------------------------------------

    if not _teacher_is_global_user():

        user_institution_id = (
            _teacher_get_user_institution_id()
        )

        if (
            user_institution_id is None
            or institution_id != user_institution_id
        ):
            errors.append(
                "You are not allowed to use this institution."
            )

    # --------------------------------------------------------
    # Branch required
    # --------------------------------------------------------

    if not branch_id:

        errors.append(
            "Branch is required."
        )

        return

    branch = Branch.query.filter(
        Branch.id == branch_id
    ).first()

    if not branch:

        errors.append(
            "Selected branch was not found."
        )

        return

    # --------------------------------------------------------
    # Branch must belong to institution
    # --------------------------------------------------------

    if branch.institution_id != institution_id:

        errors.append(
            "Selected branch does not belong "
            "to the selected institution."
        )

    # --------------------------------------------------------
    # Branch-admin restriction
    # --------------------------------------------------------

    if (
        not _teacher_is_global_user()
        and getattr(current_user, "role", None)
        == "branch_admin"
    ):

        user_branch_id = (
            _teacher_get_user_branch_id()
        )

        if (
            user_branch_id is None
            or branch_id != user_branch_id
        ):

            errors.append(
                "You are not allowed to use this branch."
            )


# ============================================================
# AUTO GENERATE TEACHER ROLL NUMBER
# ============================================================

def _generate_teacher_roll_no(institution_id):
    """
    Generate:

        T001
        T002
        T003

    Roll number is unique within institution.
    """

    prefix = "T"

    teachers = Teacher.query.filter(
        Teacher.institution_id == institution_id
    ).all()

    used_numbers = set()

    for teacher in teachers:

        if not teacher.roll_no:
            continue

        roll = teacher.roll_no.strip().upper()

        if not roll.startswith(prefix):
            continue

        numeric_part = roll[len(prefix):]

        if numeric_part.isdigit():

            used_numbers.add(
                int(numeric_part)
            )

    number = 1

    while number in used_numbers:
        number += 1

    return f"{prefix}{number:03d}"


# ============================================================
# TEACHER DETAIL ACCESS
# ============================================================

def _teacher_can_access(teacher):

    if _teacher_is_global_user():
        return True

    institution_id = (
        _teacher_get_user_institution_id()
    )

    if (
        institution_id is None
        or teacher.institution_id != institution_id
    ):
        return False

    if getattr(current_user, "role", None) == "branch_admin":

        branch_id = _teacher_get_user_branch_id()

        if (
            branch_id is None
            or teacher.branch_id != branch_id
        ):
            return False

    return True


# ============================================================
# 1. ALL TEACHERS
# ============================================================

@bp.route(
    "/teachers",
    methods=["GET"]
)
@login_required
def all_teachers():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:

        flash(
            "You are not authorized to manage teachers.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = (
        _teacher_get_user_institution_id()
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE REQUIREMENTS
    # ========================================================

    if role == "school_admin":

        if user_institution_id is None:

            abort(403)

    if role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):

            abort(403)

    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    gender = request.args.get(
        "gender",
        "",
        type=str
    ).strip().lower()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    active = request.args.get(
        "active",
        "",
        type=str
    ).strip().lower()

    verified = request.args.get(
        "verified",
        "",
        type=str
    ).strip().lower()

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:

        per_page = 25

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = Teacher.query

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if role == "superadmin":

        # Superadmin may filter by institution

        if institution_id:

            try:

                selected_institution_id = int(
                    institution_id
                )

                query = query.filter(
                    Teacher.institution_id
                    == selected_institution_id
                )

            except (
                ValueError,
                TypeError
            ):

                institution_id = ""

    else:

        # ----------------------------------------------------
        # school_admin / branch_admin
        # ----------------------------------------------------

        query = query.filter(
            Teacher.institution_id
            == user_institution_id
        )

        # Prevent URL manipulation

        institution_id = str(
            user_institution_id
        )

    # ========================================================
    # BRANCH SECURITY
    # ========================================================

    if role == "branch_admin":

        # Branch admin MUST remain in own branch

        query = query.filter(
            Teacher.branch_id
            == user_branch_id
        )

        # Prevent URL manipulation

        branch_id = str(
            user_branch_id
        )

    elif branch_id:

        # ----------------------------------------------------
        # Superadmin / school_admin may use branch filter
        # ----------------------------------------------------

        try:

            selected_branch_id = int(
                branch_id
            )

            # Make sure selected branch belongs
            # to the current institution.

            branch = (
                Branch.query
                .filter(
                    Branch.id
                    == selected_branch_id
                )
                .first()
            )

            if not branch:

                branch_id = ""

            elif role != "superadmin":

                if (
                    branch.institution_id
                    != user_institution_id
                ):

                    # Do not allow another institution branch

                    branch_id = ""

                else:

                    query = query.filter(
                        Teacher.branch_id
                        == selected_branch_id
                    )

            else:

                # Superadmin can use any valid branch

                query = query.filter(
                    Teacher.branch_id
                    == selected_branch_id
                )

        except (
            ValueError,
            TypeError
        ):

            branch_id = ""

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_value = (
            f"%{search}%"
        )

        query = query.filter(
            or_(
                Teacher.full_name.ilike(
                    search_value
                ),

                Teacher.username.ilike(
                    search_value
                ),

                Teacher.email.ilike(
                    search_value
                ),

                Teacher.phone.ilike(
                    search_value
                ),

                Teacher.qualification.ilike(
                    search_value
                ),

                Teacher.specialization.ilike(
                    search_value
                ),
            )
        )

    # ========================================================
    # GENDER
    # ========================================================

    if gender in TEACHER_GENDERS:

        query = query.filter(
            func.lower(
                Teacher.gender
            )
            == gender
        )

    else:

        gender = ""

    # ========================================================
    # STATUS
    # ========================================================

    if status in TEACHER_STATUSES:

        query = query.filter(
            Teacher.status
            == status
        )

    else:

        status = ""

    # ========================================================
    # ACTIVE
    # ========================================================

    if active == "1":

        query = query.filter(
            Teacher.is_active.is_(True)
        )

    elif active == "0":

        query = query.filter(
            Teacher.is_active.is_(False)
        )

    else:

        active = ""

    # ========================================================
    # VERIFIED
    # ========================================================

    if verified == "1":

        query = query.filter(
            Teacher.is_verified.is_(True)
        )

    elif verified == "0":

        query = query.filter(
            Teacher.is_verified.is_(False)
        )

    else:

        verified = ""

    # ========================================================
    # ORDERING
    # ========================================================

    query = query.order_by(
        Teacher.full_name.asc(),
        Teacher.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    teachers = pagination.items

    # ========================================================
    # FILTER DROPDOWN DATA
    # ========================================================

    institutions = (
        _teacher_allowed_institutions()
    )

    # --------------------------------------------------------
    # Institution selection for branch dropdown
    # --------------------------------------------------------

    selected_institution_for_branches = None

    if role == "branch_admin":

        selected_institution_for_branches = (
            user_institution_id
        )

    elif role == "school_admin":

        selected_institution_for_branches = (
            user_institution_id
        )

    elif institution_id:

        try:

            selected_institution_for_branches = int(
                institution_id
            )

        except (
            ValueError,
            TypeError
        ):

            selected_institution_for_branches = None

    # ========================================================
    # BRANCH DROPDOWN
    # ========================================================

    branches = _teacher_allowed_branches(
        selected_institution_for_branches
    )

    # ========================================================
    # EXTRA DROPDOWN SECURITY
    # ========================================================

    if role == "branch_admin":

        branches = [
            branch
            for branch in branches
            if branch.id
            == user_branch_id
        ]

    elif role == "school_admin":

        branches = [
            branch
            for branch in branches
            if branch.institution_id
            == user_institution_id
        ]

    # ========================================================
    # STATISTICS
    # ========================================================

    scoped_query = Teacher.query

    # --------------------------------------------------------
    # Institution scope
    # --------------------------------------------------------

    if role != "superadmin":

        scoped_query = scoped_query.filter(
            Teacher.institution_id
            == user_institution_id
        )

    # --------------------------------------------------------
    # Branch scope
    # --------------------------------------------------------

    if role == "branch_admin":

        scoped_query = scoped_query.filter(
            Teacher.branch_id
            == user_branch_id
        )

    # ========================================================
    # STATISTICS
    # ========================================================

    total_teachers = (
        scoped_query.count()
    )

    active_teachers = (
        scoped_query
        .filter(
            Teacher.is_active.is_(True),
            Teacher.status == "active"
        )
        .count()
    )

    inactive_teachers = (
        scoped_query
        .filter(
            Teacher.is_active.is_(False)
        )
        .count()
    )

    verified_teachers = (
        scoped_query
        .filter(
            Teacher.is_verified.is_(True)
        )
        .count()
    )

    suspended_teachers = (
        scoped_query
        .filter(
            Teacher.status == "suspended"
        )
        .count()
    )

    resigned_teachers = (
        scoped_query
        .filter(
            Teacher.status == "resigned"
        )
        .count()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/teachers/all_teachers.html",

        # ----------------------------------------------------
        # Data
        # ----------------------------------------------------

        teachers=teachers,

        pagination=pagination,

        institutions=institutions,

        branches=branches,

        # ----------------------------------------------------
        # Teacher options
        # ----------------------------------------------------

        teacher_genders=TEACHER_GENDERS,

        teacher_statuses=TEACHER_STATUSES,

        # ----------------------------------------------------
        # Filters
        # ----------------------------------------------------

        search=search,

        institution_id=institution_id,

        branch_id=branch_id,

        gender=gender,

        status=status,

        active=active,

        verified=verified,

        per_page=per_page,

        # ----------------------------------------------------
        # Statistics
        # ----------------------------------------------------

        total_teachers=total_teachers,

        active_teachers=active_teachers,

        inactive_teachers=inactive_teachers,

        verified_teachers=verified_teachers,

        suspended_teachers=suspended_teachers,

        resigned_teachers=resigned_teachers,

        # ----------------------------------------------------
        # Current user / scope
        # ----------------------------------------------------

        user=current_user,

        current_role=role,

        user_institution_id=(
            user_institution_id
        ),

        user_branch_id=(
            user_branch_id
        ),
    )



# ============================================================
# ADD TEACHER
# ============================================================

@bp.route("/teachers/add", methods=["GET", "POST"])
@login_required
def add_teacher():

    # --------------------------------------------------------
    # AUTHORIZATION
    # --------------------------------------------------------
    if not _teacher_can_manage():
        flash(
            "You are not authorized to add teachers.",
            "danger"
        )
        return redirect(
            url_for("main.all_teachers")
        )

    # --------------------------------------------------------
    # DEFAULT INSTITUTION
    # --------------------------------------------------------
    default_institution_id = (
        _teacher_get_user_institution_id()
    )

    # Current institution used by the form
    institution_id = default_institution_id

    # ========================================================
    # POST
    # ========================================================
    if request.method == "POST":

        errors = []

        # ====================================================
        # INSTITUTION
        # ====================================================
        institution_raw = request.form.get(
            "institution_id",
            ""
        ).strip()

        try:

            institution_id = (
                int(institution_raw)
                if institution_raw
                else None
            )

        except (ValueError, TypeError):

            institution_id = None

            errors.append(
                "Invalid institution."
            )

        # ====================================================
        # BRANCH
        # ====================================================
        branch_raw = request.form.get(
            "branch_id",
            ""
        ).strip()

        try:

            branch_id = (
                int(branch_raw)
                if branch_raw
                else None
            )

        except (ValueError, TypeError):

            branch_id = None

            errors.append(
                "Invalid branch."
            )

        # ====================================================
        # BASIC INFORMATION
        # ====================================================
        username = request.form.get(
            "username",
            ""
        ).strip()

        email = request.form.get(
            "email",
            ""
        ).strip().lower()

        full_name = request.form.get(
            "full_name",
            ""
        ).strip()

        gender = request.form.get(
            "gender",
            ""
        ).strip().lower()

        # ====================================================
        # PERSONAL INFORMATION
        # ====================================================
        date_of_birth_raw = request.form.get(
            "date_of_birth",
            ""
        ).strip()

        phone = request.form.get(
            "phone",
            ""
        ).strip()

        address = request.form.get(
            "address",
            ""
        ).strip()

        city = request.form.get(
            "city",
            ""
        ).strip()

        # ====================================================
        # PROFESSIONAL INFORMATION
        # ====================================================
        qualification = request.form.get(
            "qualification",
            ""
        ).strip()

        specialization = request.form.get(
            "specialization",
            ""
        ).strip()

        experience_raw = request.form.get(
            "experience_years",
            ""
        ).strip()

        hire_date_raw = request.form.get(
            "hire_date",
            ""
        ).strip()

        # ====================================================
        # PASSWORD
        # ====================================================
        password = request.form.get(
            "password",
            ""
        )

        confirm_password = request.form.get(
            "confirm_password",
            ""
        )

        # ====================================================
        # STATUS
        # ====================================================
        status = request.form.get(
            "status",
            "active"
        ).strip().lower()

        # ====================================================
        # CHECKBOXES
        # ====================================================
        is_active = (
            request.form.get("is_active")
            in {
                "1",
                "true",
                "on",
                "yes"
            }
        )

        is_verified = (
            request.form.get("is_verified")
            in {
                "1",
                "true",
                "on",
                "yes"
            }
        )

        # ====================================================
        # NOTES
        # ====================================================
        notes = request.form.get(
            "notes",
            ""
        ).strip()

        # ====================================================
        # PHOTO
        # ====================================================
        photo = request.files.get("photo")

        if not photo:
            photo = request.files.get(
                "profile_image"
            )

        # ====================================================
        # VALIDATE FULL NAME
        # ====================================================
        if not full_name:

            errors.append(
                "Teacher full name is required."
            )

        elif len(full_name) > 200:

            errors.append(
                "Teacher name cannot exceed "
                "200 characters."
            )

        # ====================================================
        # VALIDATE USERNAME
        # ====================================================
        if not username:

            errors.append(
                "Username is required."
            )

        elif len(username) > 150:

            errors.append(
                "Username cannot exceed "
                "150 characters."
            )

        # ====================================================
        # VALIDATE EMAIL
        # ====================================================
        if email and len(email) > 150:

            errors.append(
                "Email cannot exceed "
                "150 characters."
            )

        # ====================================================
        # VALIDATE GENDER
        # ====================================================
        if gender and gender not in TEACHER_GENDERS:

            errors.append(
                "Invalid gender selected."
            )

        # ====================================================
        # VALIDATE STATUS
        # ====================================================
        if status not in TEACHER_STATUSES:

            errors.append(
                "Invalid teacher status."
            )

        # ====================================================
        # VALIDATE PASSWORD
        # ====================================================
        if not password:

            errors.append(
                "Password is required."
            )

        elif len(password) < 6:

            errors.append(
                "Password must contain at least "
                "6 characters."
            )

        if password != confirm_password:

            errors.append(
                "Password confirmation does not match."
            )

        # ====================================================
        # DATE OF BIRTH
        # ====================================================
        date_of_birth = None

        if date_of_birth_raw:

            try:

                date_of_birth = datetime.strptime(
                    date_of_birth_raw,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                errors.append(
                    "Invalid date of birth."
                )

        # ====================================================
        # HIRE DATE
        # ====================================================
        hire_date = None

        if hire_date_raw:

            try:

                hire_date = datetime.strptime(
                    hire_date_raw,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                errors.append(
                    "Invalid hire date."
                )

        # ====================================================
        # EXPERIENCE
        # ====================================================
        experience_years = None

        if experience_raw:

            try:

                experience_years = int(
                    experience_raw
                )

                if experience_years < 0:

                    errors.append(
                        "Experience years cannot "
                        "be negative."
                    )

            except (ValueError, TypeError):

                errors.append(
                    "Experience years must be "
                    "a valid number."
                )

        # ====================================================
        # INSTITUTION + BRANCH VALIDATION
        # ====================================================
        if not institution_id:

            errors.append(
                "Institution is required."
            )

        if not branch_id:

            errors.append(
                "Branch is required."
            )

        if institution_id and branch_id:

            _validate_teacher_relationships(
                institution_id,
                branch_id,
                errors
            )

        # ====================================================
        # USERNAME DUPLICATE CHECK
        # ====================================================
        if username:

            existing_teacher_username = (
                Teacher.query
                .filter(
                    func.lower(
                        Teacher.username
                    ) == username.lower()
                )
                .first()
            )

            if existing_teacher_username:

                errors.append(
                    "This username is already in use "
                    "by another teacher."
                )

            existing_user_username = (
                User.query
                .filter(
                    func.lower(
                        User.username
                    ) == username.lower()
                )
                .first()
            )

            if existing_user_username:

                errors.append(
                    "This username is already in use "
                    "by a user account."
                )

        # ====================================================
        # EMAIL DUPLICATE CHECK
        # ====================================================
        if email:

            existing_teacher_email = (
                Teacher.query
                .filter(
                    func.lower(
                        Teacher.email
                    ) == email.lower()
                )
                .first()
            )

            if existing_teacher_email:

                errors.append(
                    "This email is already in use "
                    "by another teacher."
                )

            existing_user_email = (
                User.query
                .filter(
                    func.lower(
                        User.email
                    ) == email.lower()
                )
                .first()
            )

            if existing_user_email:

                errors.append(
                    "This email is already in use "
                    "by a user account."
                )

        # ====================================================
        # VALIDATION ERRORS
        # ====================================================
        if errors:

            for error in errors:

                flash(
                    error,
                    "danger"
                )

        # ====================================================
        # CREATE TEACHER
        # ====================================================
        if not errors:

            # ------------------------------------------------
            # AUTO ROLL NUMBER
            # ------------------------------------------------
            roll_no = _generate_teacher_roll_no(
                institution_id
            )

            # ------------------------------------------------
            # TEACHER
            # ------------------------------------------------
            teacher = Teacher(

                institution_id=institution_id,

                branch_id=branch_id,

                username=username,

                email=email or None,

                role="teacher",

                roll_no=roll_no,

                full_name=full_name,

                gender=gender or None,

                date_of_birth=date_of_birth,

                phone=phone or None,

                address=address or None,

                city=city or None,

                qualification=qualification or None,

                specialization=specialization or None,

                experience_years=experience_years,

                hire_date=hire_date,

                is_active=is_active,

                is_verified=is_verified,

                status=status,

                notes=notes or None,

                created_at=datetime.utcnow(),

                updated_at=datetime.utcnow(),
            )

            # ------------------------------------------------
            # PASSWORD
            # ------------------------------------------------
            teacher.set_password(
                password
            )

            # =================================================
            # CLOUDINARY
            # =================================================
            if photo and photo.filename:

                try:

                    folder_name = (
                        f"teachers/"
                        f"institution_{institution_id}/"
                        f"branch_{branch_id}"
                    )

                    uploaded_photo = (
                        cloudinary.uploader.upload(

                            photo,

                            folder=folder_name,

                            resource_type="image",

                            transformation=[
                                {
                                    "width": 800,
                                    "height": 800,
                                    "crop": "limit",
                                    "quality": "auto",
                                    "fetch_format": "auto",
                                }
                            ]
                        )
                    )

                    teacher.profile_image = (
                        uploaded_photo.get(
                            "secure_url"
                        )
                    )

                    teacher.profile_image_public_id = (
                        uploaded_photo.get(
                            "public_id"
                        )
                    )

                except Exception as cloudinary_error:

                    current_app.logger.exception(
                        "Cloudinary teacher image "
                        "upload failed: %s",
                        cloudinary_error
                    )

                    flash(
                        "Teacher photo could not be "
                        "uploaded. Please try again.",
                        "danger"
                    )

                    # ----------------------------------------
                    # IMPORTANT:
                    # institution_id is passed here so
                    # _teacher_allowed_branches()
                    # returns correct branches.
                    # ----------------------------------------
                    context = _teacher_form_context(
                        institution_id
                    )

                    return render_template(
                        "backend/pages/teachers/"
                        "add_teacher.html",
                        **context
                    )

            # =================================================
            # DATABASE SAVE
            # =================================================
            try:

                db.session.add(
                    teacher
                )

                db.session.commit()

                flash(
                    f"Teacher {teacher.full_name} "
                    f"was created successfully. "
                    f"Roll No: {teacher.roll_no}",
                    "success"
                )

                return redirect(
                    url_for(
                        "main.view_teacher",
                        teacher_id=teacher.id
                    )
                )

            except IntegrityError as exc:

                db.session.rollback()

                current_app.logger.exception(
                    "Teacher integrity error: %s",
                    exc
                )

                flash(
                    "Unable to create teacher. "
                    "Username, email, roll number, "
                    "or another unique value may "
                    "already exist.",
                    "danger"
                )

            except Exception as exc:

                db.session.rollback()

                current_app.logger.exception(
                    "Error creating teacher: %s",
                    exc
                )

                flash(
                    "An unexpected error occurred "
                    "while creating the teacher.",
                    "danger"
                )

    # ========================================================
    # FORM CONTEXT
    # ========================================================
    context = _teacher_form_context(
        institution_id
    )

    # --------------------------------------------------------
    # Explicit values for template
    # --------------------------------------------------------
    context["institution_id"] = (
        institution_id
    )

    context["default_institution_id"] = (
        default_institution_id
    )

    # ========================================================
    # RENDER
    # ========================================================
    return render_template(
        "backend/pages/teachers/add_teacher.html",
        **context
    )


# ============================================================
# 3. VIEW TEACHER
# ============================================================

@bp.route("/teachers/<int:teacher_id>", methods=["GET"])
@login_required
def view_teacher(teacher_id):

    # ========================================================
    # AUTHORIZATION
    # ========================================================

    if not _teacher_can_manage():
        flash(
            "You are not authorized to view teachers.",
            "danger"
        )

        return redirect(
            url_for("main.all_teachers")
        )

    # ========================================================
    # GET TEACHER
    # ========================================================

    teacher = Teacher.query.get_or_404(teacher_id)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = (
        _teacher_get_user_institution_id()
    )

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if current_institution_id is not None:

        if teacher.institution_id != current_institution_id:

            flash(
                "You are not authorized to view this teacher.",
                "danger"
            )

            return redirect(
                url_for("main.all_teachers")
            )

    # ========================================================
    # BRANCH SECURITY
    #
    # If your current user has a branch_id, make sure they
    # cannot view teachers belonging to another branch.
    # ========================================================

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    current_role = (
        getattr(current_user, "role", "") or ""
    ).strip().lower()

    branch_scoped_roles = {
        "branch_admin",
        "teacher"
    }

    if (
        current_branch_id is not None
        and current_role in branch_scoped_roles
    ):

        if teacher.branch_id != current_branch_id:

            flash(
                "You are not authorized to view "
                "this teacher from another branch.",
                "danger"
            )

            return redirect(
                url_for("main.all_teachers")
            )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/teachers/view_teacher.html",
        teacher=teacher,
        user=current_user
    )



# ============================================================
# 4. EDIT TEACHER
# ============================================================

@bp.route("/teachers/<int:teacher_id>/edit", methods=["GET", "POST"])
@login_required
def edit_teacher(teacher_id):

    # --------------------------------------------------------
    # AUTHORIZATION
    # --------------------------------------------------------
    if not _teacher_can_manage():
        flash("You are not authorized to edit teachers.", "danger")
        return redirect(url_for("main.all_teachers"))

    # --------------------------------------------------------
    # GET TEACHER
    # --------------------------------------------------------
    teacher = Teacher.query.get_or_404(teacher_id)

    # --------------------------------------------------------
    # CURRENT USER INSTITUTION
    # --------------------------------------------------------
    current_institution_id = _teacher_get_user_institution_id()

    # --------------------------------------------------------
    # SECURITY:
    # Institution admins / branch admins should only edit
    # teachers belonging to their institution.
    # --------------------------------------------------------
    if current_institution_id is not None:
        if teacher.institution_id != current_institution_id:
            flash(
                "You are not authorized to edit this teacher.",
                "danger"
            )
            return redirect(url_for("main.all_teachers"))

    # --------------------------------------------------------
    # POST
    # --------------------------------------------------------
    if request.method == "POST":

        errors = []

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_raw = request.form.get(
            "institution_id",
            ""
        ).strip()

        branch_raw = request.form.get(
            "branch_id",
            ""
        ).strip()

        username = request.form.get(
            "username",
            ""
        ).strip()

        email = request.form.get(
            "email",
            ""
        ).strip().lower()

        full_name = request.form.get(
            "full_name",
            ""
        ).strip()

        gender = request.form.get(
            "gender",
            ""
        ).strip().lower()

        date_of_birth_raw = request.form.get(
            "date_of_birth",
            ""
        ).strip()

        phone = request.form.get(
            "phone",
            ""
        ).strip()

        address = request.form.get(
            "address",
            ""
        ).strip()

        city = request.form.get(
            "city",
            ""
        ).strip()

        qualification = request.form.get(
            "qualification",
            ""
        ).strip()

        specialization = request.form.get(
            "specialization",
            ""
        ).strip()

        experience_raw = request.form.get(
            "experience_years",
            ""
        ).strip()

        hire_date_raw = request.form.get(
            "hire_date",
            ""
        ).strip()

        password = request.form.get(
            "password",
            ""
        )

        confirm_password = request.form.get(
            "confirm_password",
            ""
        )

        status = request.form.get(
            "status",
            "active"
        ).strip().lower()

        is_active = request.form.get(
            "is_active"
        ) in {"1", "true", "on", "yes"}

        is_verified = request.form.get(
            "is_verified"
        ) in {"1", "true", "on", "yes"}

        notes = request.form.get(
            "notes",
            ""
        ).strip()

        # ====================================================
        # PHOTO
        # ====================================================

        photo_file = request.files.get("photo")

        # ====================================================
        # INSTITUTION ID
        # ====================================================

        institution_id = None

        try:
            if institution_raw:
                institution_id = int(institution_raw)
            else:
                errors.append("Institution is required.")
        except (TypeError, ValueError):
            errors.append("Invalid institution.")

        # ====================================================
        # BRANCH ID
        # ====================================================

        branch_id = None

        try:
            if branch_raw:
                branch_id = int(branch_raw)
            else:
                errors.append("Branch is required.")
        except (TypeError, ValueError):
            errors.append("Invalid branch.")

        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if not username:
            errors.append("Username is required.")

        if not full_name:
            errors.append("Full name is required.")

        # ====================================================
        # USERNAME VALIDATION
        # ====================================================

        if username:

            existing_teacher = (
                Teacher.query
                .filter(
                    func.lower(Teacher.username) == username.lower(),
                    Teacher.id != teacher.id
                )
                .first()
            )

            if existing_teacher:
                errors.append(
                    "This username is already used by another teacher."
                )

            # ------------------------------------------------
            # CHECK LOGIN USERS TABLE
            # ------------------------------------------------

            existing_user = (
                User.query
                .filter(
                    func.lower(User.username) == username.lower()
                )
                .first()
            )

            if existing_user:
                errors.append(
                    "This username is already used by a login user."
                )

        # ====================================================
        # EMAIL VALIDATION
        # ====================================================

        if email:

            existing_teacher_email = (
                Teacher.query
                .filter(
                    func.lower(Teacher.email) == email.lower(),
                    Teacher.id != teacher.id
                )
                .first()
            )

            if existing_teacher_email:
                errors.append(
                    "This email is already used by another teacher."
                )

            # ------------------------------------------------
            # CHECK LOGIN USERS TABLE
            # ------------------------------------------------

            existing_user_email = (
                User.query
                .filter(
                    func.lower(User.email) == email.lower()
                )
                .first()
            )

            if existing_user_email:
                errors.append(
                    "This email is already used by a login user."
                )

        # ====================================================
        # GENDER
        # ====================================================

        if gender:

            valid_genders = {
                str(value).lower()
                for value in TEACHER_GENDERS
            }

            if gender not in valid_genders:
                errors.append("Invalid gender.")

        # ====================================================
        # STATUS
        # ====================================================

        if status:

            valid_statuses = {
                str(value).lower()
                for value in TEACHER_STATUSES
            }

            if status not in valid_statuses:
                errors.append("Invalid teacher status.")

        # ====================================================
        # DATE OF BIRTH
        # ====================================================

        date_of_birth = None

        if date_of_birth_raw:

            try:
                date_of_birth = datetime.strptime(
                    date_of_birth_raw,
                    "%Y-%m-%d"
                ).date()

            except ValueError:
                errors.append(
                    "Invalid date of birth."
                )

        # ====================================================
        # HIRE DATE
        # ====================================================

        hire_date = None

        if hire_date_raw:

            try:
                hire_date = datetime.strptime(
                    hire_date_raw,
                    "%Y-%m-%d"
                ).date()

            except ValueError:
                errors.append(
                    "Invalid hire date."
                )

        # ====================================================
        # EXPERIENCE YEARS
        # ====================================================

        experience_years = 0

        if experience_raw:

            try:
                experience_years = int(
                    experience_raw
                )

                if experience_years < 0:
                    errors.append(
                        "Experience years cannot be negative."
                    )

            except (TypeError, ValueError):

                errors.append(
                    "Experience years must be a valid number."
                )

        # ====================================================
        # PASSWORD
        # Only change password when user enters a new one.
        # ====================================================

        if password:

            if len(password) < 6:
                errors.append(
                    "Password must be at least 6 characters."
                )

            if password != confirm_password:
                errors.append(
                    "Password confirmation does not match."
                )

        # ====================================================
        # RELATIONSHIP VALIDATION
        # ====================================================

        if institution_id and branch_id:

            _validate_teacher_relationships(
                institution_id,
                branch_id,
                errors
            )

        # ====================================================
        # PHOTO VALIDATION
        # ====================================================

        photo_url = teacher.photo
        uploaded_public_id = None

        if photo_file and photo_file.filename:

            filename = secure_filename(
                photo_file.filename
            )

            extension = ""

            if "." in filename:
                extension = filename.rsplit(
                    ".",
                    1
                )[1].lower()

            allowed_extensions = {
                "jpg",
                "jpeg",
                "png",
                "webp"
            }

            allowed_mimetypes = {
                "image/jpeg",
                "image/png",
                "image/webp"
            }

            if extension not in allowed_extensions:
                errors.append(
                    "Invalid photo format. "
                    "Allowed: JPG, JPEG, PNG and WEBP."
                )

            if (
                photo_file.mimetype
                and photo_file.mimetype.lower()
                not in allowed_mimetypes
            ):
                errors.append(
                    "Invalid photo file type."
                )

            # ------------------------------------------------
            # MAX SIZE = 2 MB
            # ------------------------------------------------

            try:

                photo_file.stream.seek(
                    0,
                    os.SEEK_END
                )

                photo_size = (
                    photo_file.stream.tell()
                )

                photo_file.stream.seek(
                    0
                )

                max_photo_size = (
                    2 * 1024 * 1024
                )

                if photo_size > max_photo_size:
                    errors.append(
                        "Photo size must not exceed 2 MB."
                    )

            except Exception:
                errors.append(
                    "Unable to validate the photo."
                )

        # ====================================================
        # IF VALIDATION FAILED
        # ====================================================

        if errors:

            for error in errors:
                flash(error, "danger")

            context = _teacher_form_context(
                institution_id
                if institution_id
                else current_institution_id
            )

            return render_template(
                "backend/pages/teachers/edit_teacher.html",
                teacher=teacher,
                form_data=request.form,
                **context
            )

        # ====================================================
        # CLOUDINARY UPLOAD
        # ====================================================

        try:

            if photo_file and photo_file.filename:

                upload_result = (
                    cloudinary.uploader.upload(
                        photo_file,
                        folder="teachers",
                        resource_type="image",
                        use_filename=False,
                        unique_filename=True,
                        overwrite=False
                    )
                )

                photo_url = upload_result.get(
                    "secure_url"
                )

                uploaded_public_id = (
                    upload_result.get("public_id")
                )

                if not photo_url:
                    raise Exception(
                        "Cloudinary did not return a secure URL."
                    )

        except Exception as cloudinary_error:

            db.session.rollback()

            current_app.logger.exception(
                "Teacher photo upload failed: %s",
                cloudinary_error
            )

            flash(
                "Teacher photo upload failed. "
                "Please try again.",
                "danger"
            )

            context = _teacher_form_context(
                institution_id
                if institution_id
                else current_institution_id
            )

            return render_template(
                "backend/pages/teachers/edit_teacher.html",
                teacher=teacher,
                form_data=request.form,
                **context
            )

        # ====================================================
        # UPDATE TEACHER
        # ====================================================

        try:

            teacher.institution_id = institution_id
            teacher.branch_id = branch_id

            teacher.username = username
            teacher.email = email or None

            teacher.full_name = full_name
            teacher.gender = gender or None

            teacher.date_of_birth = date_of_birth

            teacher.phone = phone or None
            teacher.address = address or None
            teacher.city = city or None

            teacher.qualification = (
                qualification or None
            )

            teacher.specialization = (
                specialization or None
            )

            teacher.experience_years = (
                experience_years
            )

            teacher.hire_date = hire_date

            teacher.status = status

            teacher.is_active = is_active
            teacher.is_verified = is_verified

            teacher.notes = notes or None

            # ------------------------------------------------
            # UPDATE PHOTO ONLY IF NEW PHOTO WAS UPLOADED
            # ------------------------------------------------

            if photo_url:
                teacher.photo = photo_url

            # ------------------------------------------------
            # PASSWORD
            # Only update when provided.
            # ------------------------------------------------

            if password:
                teacher.set_password(password)

            # ------------------------------------------------
            # UPDATED AT
            # ------------------------------------------------

            teacher.updated_at = datetime.utcnow()

            db.session.commit()

            flash(
                f"Teacher '{teacher.full_name}' "
                "was updated successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.view_teacher",
                    teacher_id=teacher.id
                )
            )

        except IntegrityError as exc:

            db.session.rollback()

            # ------------------------------------------------
            # CLEAN UP NEW CLOUDINARY FILE IF DB FAILED
            # ------------------------------------------------

            if uploaded_public_id:

                try:

                    cloudinary.uploader.destroy(
                        uploaded_public_id,
                        resource_type="image"
                    )

                except Exception:

                    current_app.logger.exception(
                        "Failed to cleanup Cloudinary "
                        "teacher image after DB error."
                    )

            current_app.logger.exception(
                "Integrity error while updating teacher: %s",
                exc
            )

            flash(
                "Unable to update teacher because "
                "some information already exists.",
                "danger"
            )

        except Exception as exc:

            db.session.rollback()

            # ------------------------------------------------
            # CLEAN UP NEW CLOUDINARY FILE
            # ------------------------------------------------

            if uploaded_public_id:

                try:

                    cloudinary.uploader.destroy(
                        uploaded_public_id,
                        resource_type="image"
                    )

                except Exception:

                    current_app.logger.exception(
                        "Failed to cleanup Cloudinary "
                        "teacher image after update error."
                    )

            current_app.logger.exception(
                "Unexpected error while updating teacher: %s",
                exc
            )

            flash(
                "An unexpected error occurred "
                "while updating the teacher.",
                "danger"
            )

        # ====================================================
        # RENDER AGAIN AFTER DATABASE ERROR
        # ====================================================

        context = _teacher_form_context(
            institution_id
            if institution_id
            else current_institution_id
        )

        return render_template(
            "backend/pages/teachers/edit_teacher.html",
            teacher=teacher,
            form_data=request.form,
            **context
        )

    # ========================================================
    # GET
    # ========================================================

    context = _teacher_form_context(
        teacher.institution_id
        if teacher.institution_id
        else current_institution_id
    )

    return render_template(
        "backend/pages/teachers/edit_teacher.html",
        teacher=teacher,
        form_data=None,
        **context
    )


# ============================================================
# 5. DELETE TEACHER
# ============================================================

@bp.route(
    "/teachers/<int:teacher_id>/delete",
    methods=["POST"]
)
@login_required
def delete_teacher(teacher_id):

    if not _teacher_can_manage():

        flash(
            "You are not authorized to delete teachers.",
            "danger"
        )

        return redirect(
            url_for("main.all_teachers")
        )

    teacher = Teacher.query.get_or_404(
        teacher_id
    )

    if not _teacher_can_access(teacher):

        flash(
            "You are not authorized to delete this teacher.",
            "danger"
        )

        return redirect(
            url_for("main.all_teachers")
        )

    teacher_name = teacher.full_name
    teacher_roll = teacher.roll_no

    try:

        db.session.delete(
            teacher
        )

        db.session.commit()

        flash(
            f"Teacher {teacher_name} "
            f"({teacher_roll}) was deleted successfully.",
            "success"
        )

    except IntegrityError:

        db.session.rollback()

        flash(
            "This teacher cannot be deleted because "
            "other records are linked to this teacher.",
            "danger"
        )

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "Error deleting teacher: %s",
            exc
        )

        flash(
            "An unexpected error occurred "
            "while deleting the teacher.",
            "danger"
        )

    return redirect(
        url_for("main.all_teachers")
    )



# ============================================================
# TEACHER SUBJECT ROUTES
# PostgreSQL / Neon
# ============================================================


# ============================================================
# CONSTANTS
# ============================================================

TEACHER_SUBJECT_TYPES = [
    "teacher",
    "assistant",
    "coordinator",
    "substitute",
]

TEACHER_SUBJECT_STATUSES = [
    "active",
    "inactive",
    "suspended",
]


# ============================================================
# AUTHORIZATION
# ============================================================

def _teacher_subject_can_manage():
    """
    Users allowed to manage teacher-subject assignments.
    """

    if not current_user.is_authenticated:
        return False

    role = getattr(current_user, "role", None)

    return role in {
        "superadmin",
        "institution_admin",
        "branch_admin",
    }


# ============================================================
# CURRENT USER INSTITUTION
# ============================================================

def _teacher_subject_user_institution_id():
    """
    Return institution_id for institution/branch scoped users.
    Superadmin returns None.
    """

    role = getattr(current_user, "role", None)

    if role == "superadmin":
        return None

    return getattr(current_user, "institution_id", None)


# ============================================================
# CURRENT USER BRANCH
# ============================================================

def _teacher_subject_user_branch_id():
    """
    Return branch_id for branch scoped users.
    """

    role = getattr(current_user, "role", None)

    if role in {"superadmin", "institution_admin"}:
        return None

    return getattr(current_user, "branch_id", None)


# ============================================================
# ALLOWED INSTITUTIONS
# ============================================================

def _teacher_subject_allowed_institutions():

    query = Institution.query

    institution_id = _teacher_subject_user_institution_id()

    if institution_id:
        query = query.filter(
            Institution.id == institution_id
        )

    return query.order_by(
        Institution.name.asc()
    ).all()


# ============================================================
# ALLOWED BRANCHES
# ============================================================

def _teacher_subject_allowed_branches(institution_id=None):

    query = Branch.query

    role = getattr(current_user, "role", None)

    user_institution_id = _teacher_subject_user_institution_id()
    user_branch_id = _teacher_subject_user_branch_id()

    # --------------------------------------------------------
    # Institution filter
    # --------------------------------------------------------

    if institution_id:
        query = query.filter(
            Branch.institution_id == institution_id
        )
    elif user_institution_id:
        query = query.filter(
            Branch.institution_id == user_institution_id
        )

    # --------------------------------------------------------
    # Branch admin can only see own branch
    # --------------------------------------------------------

    if role == "branch_admin" and user_branch_id:
        query = query.filter(
            Branch.id == user_branch_id
        )

    return query.order_by(
        Branch.name.asc()
    ).all()



# ============================================================
# ALL TEACHER SUBJECTS
# ============================================================

@bp.route("/teacher-subjects", methods=["GET"])
@login_required
def all_teacher_subjects():

    if not _teacher_subject_can_manage():
        flash(
            "You are not authorized to manage teacher subject assignments.",
            "danger"
        )
        return redirect(url_for("main.dashboard"))

    query = TeacherSubject.query

    role = getattr(current_user, "role", None)

    user_institution_id = _teacher_subject_user_institution_id()
    user_branch_id = _teacher_subject_user_branch_id()

    # ========================================================
    # SECURITY SCOPE
    # ========================================================

    if user_institution_id:
        query = query.filter(
            TeacherSubject.institution_id == user_institution_id
        )

    if role == "branch_admin" and user_branch_id:
        query = query.filter(
            TeacherSubject.branch_id == user_branch_id
        )

    # ========================================================
    # FILTER VALUES
    # ========================================================

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    subject_id = request.args.get(
        "subject_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    teaching_type = request.args.get(
        "teaching_type",
        "",
        type=str
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip()

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    # ========================================================
    # SECURITY: INSTITUTION
    # ========================================================

    if user_institution_id:
        institution_id = user_institution_id

    elif institution_id:
        query = query.filter(
            TeacherSubject.institution_id == institution_id
        )

    # ========================================================
    # BRANCH
    # ========================================================

    if role == "branch_admin":
        branch_id = user_branch_id

    if branch_id:
        query = query.filter(
            TeacherSubject.branch_id == branch_id
        )

    # ========================================================
    # TEACHER
    # ========================================================

    if teacher_id:
        query = query.filter(
            TeacherSubject.teacher_id == teacher_id
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    if subject_id:
        query = query.filter(
            TeacherSubject.subject_id == subject_id
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    if program_id:
        query = query.filter(
            TeacherSubject.program_id == program_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:
        query = query.filter(
            TeacherSubject.class_id == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:
        query = query.filter(
            TeacherSubject.section_id == section_id
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:
        query = query.filter(
            TeacherSubject.academic_year_id ==
            academic_year_id
        )

    # ========================================================
    # TEACHING TYPE
    # ========================================================

    if teaching_type:
        query = query.filter(
            TeacherSubject.teaching_type ==
            teaching_type
        )

    # ========================================================
    # STATUS
    # ========================================================

    if status:
        query = query.filter(
            TeacherSubject.status == status
        )

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        query = query.join(
            Teacher,
            Teacher.id == TeacherSubject.teacher_id
        ).join(
            Subject,
            Subject.id == TeacherSubject.subject_id
        ).filter(
            or_(
                Teacher.full_name.ilike(
                    f"%{search}%"
                ),
                Teacher.username.ilike(
                    f"%{search}%"
                ),
                Subject.name.ilike(
                    f"%{search}%"
                ),
                Subject.code.ilike(
                    f"%{search}%"
                )
            )
        )

    # ========================================================
    # RESULTS
    # ========================================================

    teacher_subjects = query.order_by(
        TeacherSubject.created_at.desc()
    ).all()

    # ========================================================
    # FORM/FILTER DATA
    # ========================================================

    institutions = _teacher_subject_allowed_institutions()

    branches = _teacher_subject_allowed_branches(
        institution_id
    )

    # ========================================================
    # TEACHERS
    # ========================================================

    teacher_query = Teacher.query

    if institution_id:
        teacher_query = teacher_query.filter(
            Teacher.institution_id == institution_id
        )

    if branch_id:
        teacher_query = teacher_query.filter(
            Teacher.branch_id == branch_id
        )

    teachers = teacher_query.order_by(
        Teacher.full_name.asc()
    ).all()

    # ========================================================
    # SUBJECTS
    # ========================================================

    subject_query = Subject.query

    if institution_id:
        subject_query = subject_query.filter(
            Subject.institution_id == institution_id
        )

    if branch_id and hasattr(Subject, "branch_id"):
        subject_query = subject_query.filter(
            Subject.branch_id == branch_id
        )

    subjects = subject_query.order_by(
        Subject.name.asc()
    ).all()

    # ========================================================
    # PROGRAMS
    # ========================================================

    program_query = Program.query

    if institution_id:
        program_query = program_query.filter(
            Program.institution_id == institution_id
        )

    if branch_id and hasattr(Program, "branch_id"):
        program_query = program_query.filter(
            Program.branch_id == branch_id
        )

    programs = program_query.order_by(
        Program.name.asc()
    ).all()

    # ========================================================
    # CLASSES
    # ========================================================

    class_query = Class.query

    if institution_id:
        class_query = class_query.filter(
            Class.institution_id == institution_id
        )

    if branch_id and hasattr(Class, "branch_id"):
        class_query = class_query.filter(
            Class.branch_id == branch_id
        )

    classes = class_query.order_by(
        Class.name.asc()
    ).all()

    # ========================================================
    # SECTIONS
    # ========================================================

    section_query = Section.query

    if institution_id:
        section_query = section_query.filter(
            Section.institution_id == institution_id
        )

    if branch_id and hasattr(Section, "branch_id"):
        section_query = section_query.filter(
            Section.branch_id == branch_id
        )

    sections = section_query.order_by(
        Section.name.asc()
    ).all()

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = AcademicYear.query

    if (
        institution_id
        and hasattr(AcademicYear, "institution_id")
    ):
        academic_year_query = academic_year_query.filter(
            AcademicYear.institution_id == institution_id
        )

    academic_years = academic_year_query.order_by(
        AcademicYear.id.desc()
    ).all()

    # ========================================================
    # FILTER OBJECT
    # ========================================================

    filters = {
        "institution_id": institution_id,
        "branch_id": branch_id,
        "teacher_id": teacher_id,
        "subject_id": subject_id,
        "program_id": program_id,
        "class_id": class_id,
        "section_id": section_id,
        "academic_year_id": academic_year_id,
        "teaching_type": teaching_type,
        "status": status,
        "search": search,
    }

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/teacher_subjects/all_teacher_subjects.html",

        user=current_user,

        teacher_subjects=teacher_subjects,

        institutions=institutions,
        branches=branches,
        teachers=teachers,
        subjects=subjects,
        programs=programs,
        classes=classes,
        sections=sections,
        academic_years=academic_years,

        teacher_subject_types=
            TEACHER_SUBJECT_TYPES,

        teacher_subject_statuses=
            TEACHER_SUBJECT_STATUSES,

        filters=filters,
    )


# ============================================================
# ADD TEACHER SUBJECT
# ============================================================

@bp.route("/teacher-subjects/options", methods=["GET"])
@login_required
def teacher_subject_options():

    # ============================================================
    # ROLE SECURITY
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if getattr(current_user, "role", None) not in allowed_roles:
        abort(403)

    # ============================================================
    # PARAMETERS
    # ============================================================

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    # ============================================================
    # REQUIRED VALIDATION
    # ============================================================

    if not institution_id:
        return jsonify({
            "success": False,
            "message": "Institution is required."
        }), 400

    if not branch_id:
        return jsonify({
            "success": False,
            "message": "Branch is required."
        }), 400

    if not academic_year_id:
        return jsonify({
            "success": False,
            "message": "Academic Year is required."
        }), 400

    if not teacher_id:
        return jsonify({
            "success": False,
            "message": "Teacher is required."
        }), 400

    # ============================================================
    # INSTITUTION
    # ============================================================

    institution = (
        Institution.query
        .filter(
            Institution.id == institution_id
        )
        .first()
    )

    if not institution:
        return jsonify({
            "success": False,
            "message": "Institution not found."
        }), 404

    # ============================================================
    # BRANCH
    # ============================================================

    branch = (
        Branch.query
        .filter(
            Branch.id == branch_id,
            Branch.institution_id == institution_id
        )
        .first()
    )

    if not branch:
        return jsonify({
            "success": False,
            "message": "Invalid branch."
        }), 404

    # ============================================================
    # ACADEMIC YEAR
    # ============================================================

    academic_year = (
        AcademicYear.query
        .filter(
            AcademicYear.id == academic_year_id,
            AcademicYear.institution_id == institution_id
        )
        .first()
    )

    if not academic_year:
        return jsonify({
            "success": False,
            "message": "Invalid academic year."
        }), 404

    # ============================================================
    # TEACHER
    # ============================================================

    teacher = (
        Teacher.query
        .filter(
            Teacher.id == teacher_id,
            Teacher.institution_id == institution_id,
            Teacher.branch_id == branch_id
        )
        .first()
    )

    if not teacher:
        return jsonify({
            "success": False,
            "message": (
                "Teacher does not belong to the selected "
                "institution and branch."
            )
        }), 404

    # ============================================================
    # PROGRAMS
    #
    # Show all active programs available to this branch.
    # ============================================================

    programs = (
        Program.query
        .filter(
            Program.institution_id == institution_id,
            Program.status == "active"
        )
        .filter(
            db.or_(
                Program.branch_id == branch_id,
                Program.branch_id.is_(None)
            )
        )
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ============================================================
    # CLASSES
    #
    # IMPORTANT:
    # Class has:
    #
    # institution_id -> NOT NULL
    # branch_id      -> NOT NULL
    # program_id     -> NOT NULL
    # academic_year_id -> NOT NULL
    #
    # Therefore use EXACT matching.
    # ============================================================

    classes = []

    if program_id:

        # First verify selected program belongs to this scope.

        selected_program = (
            Program.query
            .filter(
                Program.id == program_id,
                Program.institution_id == institution_id,
                Program.status == "active"
            )
            .filter(
                db.or_(
                    Program.branch_id == branch_id,
                    Program.branch_id.is_(None)
                )
            )
            .first()
        )

        if not selected_program:
            return jsonify({
                "success": False,
                "message": "Invalid program."
            }), 404

        # --------------------------------------------------------
        # GET ALL CLASSES OF SELECTED PROGRAM
        # --------------------------------------------------------

        classes = (
            Class.query
            .filter(
                Class.institution_id == institution_id,

                Class.branch_id == branch_id,

                Class.program_id == program_id,

                Class.academic_year_id == academic_year_id,

                Class.status == "active"
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ============================================================
    # SUBJECTS
    #
    # Subject.program_id is nullable.
    #
    # For this page we only want subjects belonging to
    # the selected program.
    # ============================================================

    subjects = []

    if program_id:

        subjects = (
            Subject.query
            .filter(
                Subject.institution_id == institution_id,

                Subject.program_id == program_id,

                Subject.status == "active"
            )
            .filter(
                db.or_(
                    Subject.branch_id == branch_id,
                    Subject.branch_id.is_(None)
                )
            )
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    # ============================================================
    # SECTIONS
    #
    # Sections belong to a specific class.
    # ============================================================

    sections = []

    if class_id:

        # --------------------------------------------------------
        # Verify class belongs to selected scope
        # --------------------------------------------------------

        selected_class = (
            Class.query
            .filter(
                Class.id == class_id,

                Class.institution_id == institution_id,

                Class.branch_id == branch_id,

                Class.academic_year_id == academic_year_id
            )
            .first()
        )

        if selected_class:

            sections = (
                Section.query
                .filter(
                    Section.institution_id == institution_id,

                    Section.branch_id == branch_id,

                    Section.class_id == class_id,

                    Section.academic_year_id == academic_year_id,

                    Section.status == "active"
                )
                .order_by(
                    Section.name.asc()
                )
                .all()
            )

    # ============================================================
    # RESPONSE
    # ============================================================

    return jsonify({

        "success": True,

        "teacher_id": teacher_id,

        "institution_id": institution_id,

        "branch_id": branch_id,

        "academic_year_id": academic_year_id,

        "selected_program_id": program_id,

        "selected_class_id": class_id,

        # ========================================================
        # PROGRAMS
        # ========================================================

        "programs": [

            {
                "id": program.id,

                "name": program.name,

                "code": getattr(
                    program,
                    "code",
                    None
                ),

                "institution_id":
                    program.institution_id,

                "branch_id":
                    program.branch_id
            }

            for program in programs
        ],

        # ========================================================
        # CLASSES
        # ========================================================

        "classes": [

            {
                "id": item.id,

                "name": item.name,

                "code": item.code,

                "level": item.level,

                "capacity": item.capacity,

                "program_id": item.program_id,

                "institution_id":
                    item.institution_id,

                "branch_id":
                    item.branch_id,

                "academic_year_id":
                    item.academic_year_id,

                "status": item.status
            }

            for item in classes
        ],

        # ========================================================
        # SUBJECTS
        # ========================================================

        "subjects": [

            {
                "id": item.id,

                "name": item.name,

                "code": item.code,

                "short_name":
                    item.short_name,

                "program_id":
                    item.program_id,

                "institution_id":
                    item.institution_id,

                "branch_id":
                    item.branch_id,

                "subject_type":
                    item.subject_type,

                "max_marks":
                    float(item.max_marks)
                    if item.max_marks is not None
                    else None,

                "pass_marks":
                    float(item.pass_marks)
                    if item.pass_marks is not None
                    else None
            }

            for item in subjects
        ],

        # ========================================================
        # SECTIONS
        # ========================================================

        "sections": [

            {
                "id": item.id,

                "name": item.name,

                "code": item.code,

                "capacity": item.capacity,

                "class_id":
                    item.class_id,

                "institution_id":
                    item.institution_id,

                "branch_id":
                    item.branch_id,

                "academic_year_id":
                    item.academic_year_id,

                "status":
                    item.status
            }

            for item in sections
        ]
    })



@bp.route(
    "/teacher-subjects/add",
    methods=["GET", "POST"]
)
@login_required
def add_teacher_subject():

    # ============================================================
    # ROLE SECURITY
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = (
        getattr(current_user, "role", None) or ""
    ).strip().lower()

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to create teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ============================================================
    # CURRENT USER SCOPE
    # ============================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ============================================================
    # ROLE SCOPE VALIDATION
    # ============================================================

    if current_role == "branch_admin":

        if not current_institution_id:

            flash(
                "Your branch admin account is not linked to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        if not current_branch_id:

            flash(
                "Your branch admin account is not linked to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    elif current_role == "school_admin":

        if not current_institution_id:

            flash(
                "Your school admin account is not linked to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ============================================================
    # INITIAL DATA
    # ============================================================

    institutions = []
    branches = []
    academic_years = []
    teachers = []
    programs = []
    classes = []
    subjects = []
    sections = []

    # ============================================================
    # SAFE INTEGER
    # ============================================================

    def safe_int(value):

        try:

            if value is None:
                return None

            value = str(value).strip()

            if not value:
                return None

            return int(value)

        except (TypeError, ValueError):

            return None

    # ============================================================
    # SAFE LIST VALUE
    # ============================================================

    def get_list_value(values, index):

        if index >= len(values):
            return None

        value = (
            values[index]
            or ""
        ).strip()

        return value or None

    # ============================================================
    # LOAD INSTITUTIONS
    # ============================================================

    if current_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institution = (
            Institution.query
            .filter(
                Institution.id == current_institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Institution not found.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        institutions = [institution]

    # ============================================================
    # POST
    # ============================================================

    if request.method == "POST":

        try:

            # ====================================================
            # GLOBAL FORM VALUES
            # ====================================================

            institution_id_raw = (
                request.form.get(
                    "institution_id"
                )
                or ""
            ).strip()

            branch_id_raw = (
                request.form.get(
                    "branch_id"
                )
                or ""
            ).strip()

            academic_year_id_raw = (
                request.form.get(
                    "academic_year_id"
                )
                or ""
            ).strip()

            teaching_type = (
                request.form.get(
                    "teaching_type"
                )
                or "teacher"
            ).strip().lower()

            status = (
                request.form.get(
                    "status"
                )
                or "active"
            ).strip().lower()

            start_date_raw = (
                request.form.get(
                    "start_date"
                )
                or ""
            ).strip()

            end_date_raw = (
                request.form.get(
                    "end_date"
                )
                or ""
            ).strip()

            notes = (
                request.form.get(
                    "notes"
                )
                or ""
            ).strip()

            is_primary = (
                request.form.get(
                    "is_primary"
                ) == "1"
            )

            # ====================================================
            # MULTIPLE ROWS
            # ====================================================

            teacher_ids = request.form.getlist(
                "teacher_ids"
            )

            assignment_types = request.form.getlist(
                "assignment_type"
            )

            program_ids = request.form.getlist(
                "program_ids"
            )

            class_ids = request.form.getlist(
                "class_ids"
            )

            subject_ids = request.form.getlist(
                "subject_ids"
            )

            section_ids = request.form.getlist(
                "section_ids"
            )

            # ====================================================
            # REQUIRED GLOBAL VALUES
            # ====================================================

            if not teacher_ids:

                raise ValueError(
                    "Please add at least one teacher assignment."
                )

            if not institution_id_raw:

                raise ValueError(
                    "Institution is required."
                )

            if not branch_id_raw:

                raise ValueError(
                    "Branch is required."
                )

            if not academic_year_id_raw:

                raise ValueError(
                    "Academic Year is required."
                )

            # ====================================================
            # CONVERT IDS
            # ====================================================

            submitted_institution_id = safe_int(
                institution_id_raw
            )

            submitted_branch_id = safe_int(
                branch_id_raw
            )

            academic_year_id = safe_int(
                academic_year_id_raw
            )

            if not submitted_institution_id:

                raise ValueError(
                    "Invalid institution."
                )

            if not submitted_branch_id:

                raise ValueError(
                    "Invalid branch."
                )

            if not academic_year_id:

                raise ValueError(
                    "Invalid academic year."
                )

            # ====================================================
            # INSTITUTION SECURITY
            # ====================================================

            if current_role == "superadmin":

                institution_id = (
                    submitted_institution_id
                )

            else:

                institution_id = (
                    current_institution_id
                )

                if (
                    submitted_institution_id
                    != current_institution_id
                ):

                    raise ValueError(
                        "You cannot create assignments for another institution."
                    )

            # ====================================================
            # BRANCH SECURITY
            # ====================================================

            branch_id = submitted_branch_id

            if current_role == "branch_admin":

                if branch_id != current_branch_id:

                    raise ValueError(
                        "You can only create assignments for your own branch."
                    )

            # ====================================================
            # INSTITUTION VALIDATION
            # ====================================================

            institution = (
                Institution.query
                .filter(
                    Institution.id == institution_id
                )
                .first()
            )

            if not institution:

                raise ValueError(
                    "Selected institution does not exist."
                )

            # ====================================================
            # BRANCH VALIDATION
            # ====================================================

            branch_query = (
                Branch.query
                .filter(
                    Branch.id == branch_id,
                    Branch.institution_id == institution_id,
                )
            )

            if current_role == "branch_admin":

                branch_query = (
                    branch_query
                    .filter(
                        Branch.id == current_branch_id
                    )
                )

            branch = (
                branch_query
                .first()
            )

            if not branch:

                raise ValueError(
                    "Selected branch is not available for your account."
                )

            # ====================================================
            # ACADEMIC YEAR
            # ====================================================

            academic_year = (
                AcademicYear.query
                .filter(
                    AcademicYear.id == academic_year_id,
                    AcademicYear.institution_id == institution_id,
                )
                .first()
            )

            if not academic_year:

                raise ValueError(
                    "Selected academic year does not belong to this institution."
                )

            # ====================================================
            # TEACHING TYPE
            # ====================================================

            allowed_teaching_types = {
                "teacher",
                "assistant",
                "coordinator",
                "substitute",
            }

            if teaching_type not in allowed_teaching_types:

                raise ValueError(
                    "Invalid teaching type."
                )

            # ====================================================
            # STATUS
            # ====================================================

            allowed_statuses = {
                "active",
                "inactive",
            }

            if status not in allowed_statuses:

                raise ValueError(
                    "Invalid assignment status."
                )

            # ====================================================
            # DATE PARSING
            # ====================================================

            start_date = None
            end_date = None

            if start_date_raw:

                try:

                    start_date = datetime.strptime(
                        start_date_raw,
                        "%Y-%m-%d"
                    ).date()

                except ValueError:

                    raise ValueError(
                        "Invalid start date."
                    )

            if end_date_raw:

                try:

                    end_date = datetime.strptime(
                        end_date_raw,
                        "%Y-%m-%d"
                    ).date()

                except ValueError:

                    raise ValueError(
                        "Invalid end date."
                    )

            # ====================================================
            # DATE RANGE
            # ====================================================

            if (
                start_date
                and end_date
                and end_date < start_date
            ):

                raise ValueError(
                    "End Date cannot be earlier than Start Date."
                )

            # ====================================================
            # ROW COUNT
            # ====================================================

            row_count = len(
                teacher_ids
            )

            if len(assignment_types) != row_count:

                raise ValueError(
                    "Assignment data is incomplete. "
                    "Please make sure every row has an assignment type."
                )

            # ====================================================
            # ALLOWED ASSIGNMENT TYPES
            # ====================================================

            allowed_assignment_types = {
                "program",
                "class",
                "subject",
                "section",
            }

            # ====================================================
            # FORM DUPLICATE TARGETS
            #
            # IMPORTANT:
            #
            # Teacher A -> English
            # Teacher A -> Somali
            #
            # are DIFFERENT targets.
            #
            # Teacher A -> English
            # Teacher B -> English
            #
            # same target => conflict unless assistant.
            # ====================================================

            submitted_non_assistant_targets = set()

            # ====================================================
            # PROCESS EACH ROW
            # ====================================================

            created_count = 0

            for index in range(row_count):

                row_number = index + 1

                # ==================================================
                # TEACHER
                # ==================================================

                teacher_id = safe_int(
                    get_list_value(
                        teacher_ids,
                        index
                    )
                )

                if not teacher_id:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Teacher is required."
                    )

                # ==================================================
                # ASSIGNMENT TYPE
                # ==================================================

                assignment_type = (
                    get_list_value(
                        assignment_types,
                        index
                    )
                    or ""
                ).lower()

                if assignment_type not in allowed_assignment_types:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Invalid assignment type."
                    )

                # ==================================================
                # TEACHER VALIDATION
                #
                # Teacher branch_id:
                #
                # specific branch -> that branch only
                # NULL            -> can work in selected branch
                # ==================================================

                teacher = (
                    Teacher.query
                    .filter(
                        Teacher.id == teacher_id,
                        Teacher.institution_id == institution_id,
                        db.or_(
                            Teacher.branch_id == branch_id,
                            Teacher.branch_id.is_(None)
                        )
                    )
                    .first()
                )

                if not teacher:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Selected teacher does not belong "
                        "to the selected institution or branch."
                    )

                # ==================================================
                # PROGRAM
                # ==================================================

                program_id_raw = get_list_value(
                    program_ids,
                    index
                )

                if not program_id_raw:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Program is required."
                    )

                program_id = safe_int(
                    program_id_raw
                )

                if not program_id:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Invalid program."
                    )

                # ==================================================
                # PROGRAM VALIDATION
                # ==================================================

                program = (
                    Program.query
                    .filter(
                        Program.id == program_id,
                        Program.institution_id == institution_id,
                    )
                    .first()
                )

                if not program:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Selected program does not belong "
                        "to this institution."
                    )

                # Program can be:
                #
                # branch-specific
                # OR
                # institution-wide (NULL branch)

                if (
                    program.branch_id is not None
                    and program.branch_id != branch_id
                ):

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Selected program does not belong "
                        "to this branch."
                    )

                if (
                    getattr(
                        program,
                        "status",
                        "active"
                    )
                    != "active"
                ):

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Selected program is not active."
                    )

                # ==================================================
                # CLASS
                # ==================================================

                class_id = None

                class_id_raw = get_list_value(
                    class_ids,
                    index
                )

                if assignment_type in {
                    "class",
                    "subject",
                    "section",
                }:

                    if not class_id_raw:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Class is required."
                        )

                    class_id = safe_int(
                        class_id_raw
                    )

                    if not class_id:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Invalid class."
                        )

                    class_obj = (
                        Class.query
                        .filter(
                            Class.id == class_id,
                            Class.institution_id == institution_id,
                            Class.branch_id == branch_id,
                            Class.program_id == program_id,
                            Class.academic_year_id == academic_year_id,
                        )
                        .first()
                    )

                    if not class_obj:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected class does not match "
                            "the selected program, branch, "
                            "or academic year."
                        )

                # ==================================================
                # SUBJECT
                # ==================================================

                subject_id = None

                subject_id_raw = get_list_value(
                    subject_ids,
                    index
                )

                if assignment_type in {
                    "subject",
                    "section",
                }:

                    if not subject_id_raw:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Subject is required."
                        )

                    subject_id = safe_int(
                        subject_id_raw
                    )

                    if not subject_id:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Invalid subject."
                        )

                    subject = (
                        Subject.query
                        .filter(
                            Subject.id == subject_id,
                            Subject.institution_id == institution_id,
                        )
                        .first()
                    )

                    if not subject:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject does not belong "
                            "to this institution."
                        )

                    # Branch-specific subject
                    # OR institution-wide subject

                    if (
                        subject.branch_id is not None
                        and subject.branch_id != branch_id
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject does not belong "
                            "to this branch."
                        )

                    subject_program_id = getattr(
                        subject,
                        "program_id",
                        None
                    )

                    if (
                        subject_program_id is not None
                        and subject_program_id != program_id
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject does not belong "
                            "to the selected program."
                        )

                    if (
                        getattr(
                            subject,
                            "status",
                            "active"
                        )
                        != "active"
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject is not active."
                        )

                # ==================================================
                # SECTION
                # ==================================================

                section_id = None

                section_id_raw = get_list_value(
                    section_ids,
                    index
                )

                if assignment_type == "section":

                    if not section_id_raw:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Section is required."
                        )

                    section_id = safe_int(
                        section_id_raw
                    )

                    if not section_id:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Invalid section."
                        )

                    section = (
                        Section.query
                        .filter(
                            Section.id == section_id,
                            Section.institution_id == institution_id,
                            Section.branch_id == branch_id,
                            Section.class_id == class_id,
                            Section.academic_year_id == academic_year_id,
                        )
                        .first()
                    )

                    if not section:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected section does not belong "
                            "to the selected class, branch, "
                            "or academic year."
                        )

                # ==================================================
                # NORMALIZE HIERARCHY
                #
                # PROGRAM
                #   program only
                #
                # CLASS
                #   program + class
                #
                # SUBJECT
                #   program + class + subject
                #
                # SECTION
                #   program + class + subject + section
                # ==================================================

                if assignment_type == "program":

                    class_id = None
                    subject_id = None
                    section_id = None

                elif assignment_type == "class":

                    subject_id = None
                    section_id = None

                elif assignment_type == "subject":

                    section_id = None

                # ==================================================
                # EXACT TARGET KEY
                #
                # NOTE:
                # teacher_id IS NOT included here.
                #
                # This is intentional.
                #
                # The conflict is about the teaching target,
                # not about the teacher.
                #
                # Therefore:
                #
                # Teacher A -> English
                # Teacher A -> Somali
                #
                # are both allowed.
                #
                # But:
                #
                # Teacher A -> English
                # Teacher B -> English
                #
                # conflicts when both are normal teachers.
                # ==================================================

                target_key = (
                    institution_id,
                    branch_id,
                    academic_year_id,
                    assignment_type,
                    program_id,
                    class_id,
                    subject_id,
                    section_id,
                )

                # ==================================================
                # SAME POST TARGET CONFLICT
                # ==================================================

                if teaching_type != "assistant":

                    if target_key in submitted_non_assistant_targets:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "This target is already assigned "
                            "to another non-assistant teacher "
                            "in this submission."
                        )

                    submitted_non_assistant_targets.add(
                        target_key
                    )

                # ==================================================
                # DATABASE TARGET CONFLICT
                #
                # IMPORTANT:
                #
                # Search ONLY by target.
                #
                # Do NOT search by teacher_id here.
                #
                # This allows one teacher to have many targets.
                # ==================================================

                if teaching_type != "assistant":

                    conflict_query = (
                        TeacherSubject.query
                        .filter(
                            TeacherSubject.institution_id
                            == institution_id,

                            TeacherSubject.branch_id
                            == branch_id,

                            TeacherSubject.academic_year_id
                            == academic_year_id,

                            TeacherSubject.assignment_type
                            == assignment_type,

                            TeacherSubject.scope
                            == "specific",

                            TeacherSubject.status
                            == "active",

                            TeacherSubject.teaching_type
                            != "assistant",
                        )
                    )

                    # ----------------------------------------------
                    # PROGRAM
                    # ----------------------------------------------

                    if program_id is None:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.program_id.is_(None)
                            )
                        )

                    else:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.program_id
                                == program_id
                            )
                        )

                    # ----------------------------------------------
                    # CLASS
                    # ----------------------------------------------

                    if class_id is None:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.class_id.is_(None)
                            )
                        )

                    else:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.class_id
                                == class_id
                            )
                        )

                    # ----------------------------------------------
                    # SUBJECT
                    # ----------------------------------------------

                    if subject_id is None:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.subject_id.is_(None)
                            )
                        )

                    else:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.subject_id
                                == subject_id
                            )
                        )

                    # ----------------------------------------------
                    # SECTION
                    # ----------------------------------------------

                    if section_id is None:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.section_id.is_(None)
                            )
                        )

                    else:

                        conflict_query = (
                            conflict_query
                            .filter(
                                TeacherSubject.section_id
                                == section_id
                            )
                        )

                    existing_conflict = (
                        conflict_query
                        .first()
                    )

                    if existing_conflict:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "This target is already assigned "
                            "to a non-assistant teacher. "
                            "Only an assistant can share this target."
                        )

                # ==================================================
                # SAME TEACHER EXACT DUPLICATE
                #
                # This check DOES include teacher_id.
                #
                # So:
                #
                # Teacher A -> English
                # Teacher A -> Somali
                #
                # allowed.
                #
                # Teacher A -> English
                # Teacher A -> English
                #
                # blocked.
                # ==================================================

                teacher_duplicate_query = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.institution_id
                        == institution_id,

                        TeacherSubject.branch_id
                        == branch_id,

                        TeacherSubject.academic_year_id
                        == academic_year_id,

                        TeacherSubject.teacher_id
                        == teacher_id,

                        TeacherSubject.assignment_type
                        == assignment_type,

                        TeacherSubject.scope
                        == "specific",

                        TeacherSubject.status
                        == "active",
                    )
                )

                # ----------------------------------------------
                # PROGRAM
                # ----------------------------------------------

                if program_id is None:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.program_id.is_(None)
                        )
                    )

                else:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.program_id
                            == program_id
                        )
                    )

                # ----------------------------------------------
                # CLASS
                # ----------------------------------------------

                if class_id is None:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.class_id.is_(None)
                        )
                    )

                else:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.class_id
                            == class_id
                        )
                    )

                # ----------------------------------------------
                # SUBJECT
                # ----------------------------------------------

                if subject_id is None:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.subject_id.is_(None)
                        )
                    )

                else:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.subject_id
                            == subject_id
                        )
                    )

                # ----------------------------------------------
                # SECTION
                # ----------------------------------------------

                if section_id is None:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.section_id.is_(None)
                        )
                    )

                else:

                    teacher_duplicate_query = (
                        teacher_duplicate_query
                        .filter(
                            TeacherSubject.section_id
                            == section_id
                        )
                    )

                same_teacher_existing = (
                    teacher_duplicate_query
                    .first()
                )

                if same_teacher_existing:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "This teacher is already assigned "
                        "to the selected target."
                    )

                # ==================================================
                # CREATE ASSIGNMENT
                # ==================================================

                assignment = TeacherSubject(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    teacher_id=teacher_id,
                    program_id=program_id,
                    class_id=class_id,
                    subject_id=subject_id,
                    section_id=section_id,
                    academic_year_id=academic_year_id,
                    assignment_type=assignment_type,
                    scope="specific",
                    teaching_type=teaching_type,
                    is_primary=is_primary,
                    status=status,
                    start_date=start_date,
                    end_date=end_date,
                    notes=notes or None,
                )

                db.session.add(
                    assignment
                )

                created_count += 1

            # ====================================================
            # COMMIT
            # ====================================================

            db.session.commit()

            flash(
                f"{created_count} teacher assignment(s) "
                "created successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_teacher_subjects"
                )
            )

        # ========================================================
        # VALIDATION ERROR
        # ========================================================

        except ValueError as exc:

            db.session.rollback()

            flash(
                str(exc),
                "danger"
            )

        # ========================================================
        # DATABASE ERROR
        # ========================================================

        except IntegrityError:

            db.session.rollback()

            current_app.logger.exception(
                "Teacher assignment IntegrityError"
            )

            flash(
                "Unable to save teacher assignment because "
                "of a database constraint.",
                "danger"
            )

        # ========================================================
        # GENERAL ERROR
        # ========================================================

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Teacher assignment creation failed"
            )

            flash(
                "An unexpected error occurred while creating "
                "teacher assignments.",
                "danger"
            )

    # ============================================================
    # SELECTED INSTITUTION
    # ============================================================

    selected_institution_id = None

    if current_role == "superadmin":

        if request.method == "POST":

            selected_institution_id = safe_int(
                request.form.get(
                    "institution_id"
                )
            )

    else:

        selected_institution_id = (
            current_institution_id
        )

    # ============================================================
    # SELECTED BRANCH
    # ============================================================

    selected_branch_id = None

    if current_role == "branch_admin":

        selected_branch_id = (
            current_branch_id
        )

    elif request.method == "POST":

        selected_branch_id = safe_int(
            request.form.get(
                "branch_id"
            )
        )

    # ============================================================
    # SELECTED ACADEMIC YEAR
    # ============================================================

    selected_academic_year_id = None

    if request.method == "POST":

        selected_academic_year_id = safe_int(
            request.form.get(
                "academic_year_id"
            )
        )

    # ============================================================
    # LOAD BRANCHES
    # ============================================================

    if current_role == "superadmin":

        if selected_institution_id:

            branches = (
                Branch.query
                .filter(
                    Branch.institution_id
                    == selected_institution_id
                )
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

    elif current_role == "school_admin":

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif current_role == "branch_admin":

        current_branch = (
            Branch.query
            .filter(
                Branch.id == current_branch_id,
                Branch.institution_id
                == current_institution_id,
            )
            .first()
        )

        if current_branch:

            branches = [
                current_branch
            ]

    # ============================================================
    # LOAD ACADEMIC YEARS
    # ============================================================

    if selected_institution_id:

        academic_years = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == selected_institution_id
            )
            .order_by(
                AcademicYear.start_date.desc()
            )
            .all()
        )

    # ============================================================
    # LOAD TEACHERS
    #
    # Specific branch teachers
    # +
    # institution-wide teachers
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
    ):

        teachers = (
            Teacher.query
            .filter(
                Teacher.institution_id
                == selected_institution_id
            )
            .filter(
                db.or_(
                    Teacher.branch_id
                    == selected_branch_id,

                    Teacher.branch_id.is_(None)
                )
            )
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD PROGRAMS
    # ============================================================

    if selected_institution_id:

        program_query = (
            Program.query
            .filter(
                Program.institution_id
                == selected_institution_id
            )
        )

        if selected_branch_id:

            program_query = (
                program_query
                .filter(
                    db.or_(
                        Program.branch_id
                        == selected_branch_id,

                        Program.branch_id.is_(None)
                    )
                )
            )

        programs = (
            program_query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD CLASSES
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
        and selected_academic_year_id
    ):

        classes = (
            Class.query
            .filter(
                Class.institution_id
                == selected_institution_id,

                Class.branch_id
                == selected_branch_id,

                Class.academic_year_id
                == selected_academic_year_id,
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD SUBJECTS
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
    ):

        subject_query = (
            Subject.query
            .filter(
                Subject.institution_id
                == selected_institution_id
            )
            .filter(
                db.or_(
                    Subject.branch_id
                    == selected_branch_id,

                    Subject.branch_id.is_(None)
                )
            )
        )

        subjects = (
            subject_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD SECTIONS
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
        and selected_academic_year_id
    ):

        sections = (
            Section.query
            .filter(
                Section.institution_id
                == selected_institution_id,

                Section.branch_id
                == selected_branch_id,

                Section.academic_year_id
                == selected_academic_year_id,
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ============================================================
    # FORM VALUES
    # ============================================================

    form_values = {

        "institution_id": (
            selected_institution_id
            or ""
        ),

        "branch_id": (
            selected_branch_id
            or ""
        ),

        "academic_year_id": (
            selected_academic_year_id
            or ""
        ),

        "teaching_type": (
            request.form.get(
                "teaching_type",
                "teacher"
            )
            if request.method == "POST"
            else "teacher"
        ),

        "status": (
            request.form.get(
                "status",
                "active"
            )
            if request.method == "POST"
            else "active"
        ),

        "start_date": (
            request.form.get(
                "start_date",
                ""
            )
            if request.method == "POST"
            else ""
        ),

        "end_date": (
            request.form.get(
                "end_date",
                ""
            )
            if request.method == "POST"
            else ""
        ),

        "notes": (
            request.form.get(
                "notes",
                ""
            )
            if request.method == "POST"
            else ""
        ),

        "is_primary": (
            request.form.get(
                "is_primary"
            ) == "1"
            if request.method == "POST"
            else True
        ),
    }

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(

        "backend/pages/teacher_subjects/"
        "add_teacher_subject.html",

        institutions=institutions,
        branches=branches,
        academic_years=academic_years,
        teachers=teachers,
        programs=programs,
        classes=classes,
        subjects=subjects,
        sections=sections,

        form_values=form_values,

        user=current_user,
        current_user=current_user,

        current_role=current_role,

        is_superadmin=(
            current_role == "superadmin"
        ),

        is_school_admin=(
            current_role == "school_admin"
        ),

        is_branch_admin=(
            current_role == "branch_admin"
        ),

        current_institution_id=(
            current_institution_id
        ),

        current_branch_id=(
            current_branch_id
        ),

        branch_locked=(
            current_role == "branch_admin"
        ),
    )



# ============================================================
# VIEW TEACHER SUBJECT
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>",
    methods=["GET"]
)
@login_required
def view_teacher_subject(teacher_subject_id):

    # ========================================================
    # AUTHORIZATION
    # ========================================================

    allowed_roles = {
        "superadmin",
        "institution_admin",
        "branch_admin",
        "teacher",
    }

    if (
        not _teacher_can_manage()
        and getattr(current_user, "role", None)
        not in allowed_roles
    ):
        flash(
            "You are not authorized to view teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # LOAD ASSIGNMENT
    # ========================================================

    assignment = (
        TeacherSubject.query
        .options(
            db.joinedload(
                TeacherSubject.institution
            ),

            db.joinedload(
                TeacherSubject.branch
            ),

            db.joinedload(
                TeacherSubject.teacher
            ),

            db.joinedload(
                TeacherSubject.subject
            ),

            db.joinedload(
                TeacherSubject.program
            ),

            db.joinedload(
                TeacherSubject.class_
            ),

            db.joinedload(
                TeacherSubject.section
            ),

            db.joinedload(
                TeacherSubject.academic_year
            ),
        )
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first()
    )

    # ========================================================
    # NOT FOUND
    # ========================================================

    if not assignment:

        flash(
            "Teacher subject assignment was not found.",
            "warning"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # CURRENT USER ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    # ========================================================
    # SUPERADMIN
    # ========================================================

    if role == "superadmin":

        pass

    # ========================================================
    # INSTITUTION ADMIN
    # ========================================================

    elif role == "institution_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if (
            not user_institution_id
            or assignment.institution_id
            != user_institution_id
        ):

            flash(
                "You are not authorized to view this assignment.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

    # ========================================================
    # BRANCH ADMIN
    # ========================================================

    elif role == "branch_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        user_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not user_institution_id
            or not user_branch_id
            or assignment.institution_id
            != user_institution_id
            or assignment.branch_id
            != user_branch_id
        ):

            flash(
                "You are not authorized to view this assignment.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

    # ========================================================
    # TEACHER
    # ========================================================

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        # ----------------------------------------------------
        # Teacher must have a linked teacher record
        # ----------------------------------------------------

        if current_teacher_id is None:

            flash(
                "Your teacher account is not linked to a teacher record.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

        # ----------------------------------------------------
        # Only own assignment
        # ----------------------------------------------------

        if (
            assignment.teacher_id
            != current_teacher_id
        ):

            flash(
                "You are not authorized to view this assignment.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

    # ========================================================
    # OTHER ROLES
    # ========================================================

    else:

        flash(
            "You are not authorized to view teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # RENDER TEMPLATE
    # ========================================================

    return render_template(
        "backend/pages/teacher_subjects/view_teacher_subject.html",
        assignment=assignment,
        user=current_user,
    )

# ============================================================
# EDIT TEACHER SUBJECT
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_teacher_subject(teacher_subject_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = (
        getattr(current_user, "role", None) or ""
    ).strip().lower()

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to edit teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # GET CURRENT USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD ASSIGNMENT
    # ========================================================

    assignment = (
        TeacherSubject.query
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first()
    )

    if not assignment:

        flash(
            "Teacher assignment not found.",
            "danger"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # ASSIGNMENT ACCESS SECURITY
    # ========================================================

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":

        assignment_query = TeacherSubject.query.filter(
            TeacherSubject.id == teacher_subject_id
        )

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        if not user_institution_id:

            flash(
                "Your account is not linked to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

        assignment_query = TeacherSubject.query.filter(
            TeacherSubject.id == teacher_subject_id,
            TeacherSubject.institution_id == user_institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    else:

        if not user_institution_id or not user_branch_id:

            flash(
                "Your account is not properly linked to an institution and branch.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

        assignment_query = TeacherSubject.query.filter(
            TeacherSubject.id == teacher_subject_id,
            TeacherSubject.institution_id == user_institution_id,
            TeacherSubject.branch_id == user_branch_id
        )

    assignment = assignment_query.first()

    if not assignment:

        flash(
            "You do not have permission to edit this teacher assignment.",
            "danger"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # FORM VALUES
    # ========================================================

    form_values = {}

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ----------------------------------------------------
        # READ FORM VALUES
        # ----------------------------------------------------

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        teacher_id = request.form.get(
            "teacher_id",
            type=int
        )

        assignment_type = (
            request.form.get(
                "assignment_type",
                ""
            )
            .strip()
            .lower()
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        class_id = request.form.get(
            "class_id",
            type=int
        )

        subject_id = request.form.get(
            "subject_id",
            type=int
        )

        section_id = request.form.get(
            "section_id",
            type=int
        )

        teaching_type = (
            request.form.get(
                "teaching_type",
                "teacher"
            )
            .strip()
            .lower()
        )

        status = (
            request.form.get(
                "status",
                "active"
            )
            .strip()
            .lower()
        )

        start_date = (
            request.form.get(
                "start_date",
                ""
            )
            .strip()
            or None
        )

        end_date = (
            request.form.get(
                "end_date",
                ""
            )
            .strip()
            or None
        )

        is_primary = (
            request.form.get("is_primary")
            in {
                "1",
                "true",
                "True",
                "on",
                "yes"
            }
        )

        notes = (
            request.form.get(
                "notes",
                ""
            )
            .strip()
            or None
        )

        scope = (
            request.form.get(
                "scope",
                "specific"
            )
            .strip()
            .lower()
        )

        # ----------------------------------------------------
        # KEEP FORM VALUES FOR ERROR RENDERING
        # ----------------------------------------------------

        form_values = {
            "institution_id": institution_id,
            "branch_id": branch_id,
            "academic_year_id": academic_year_id,
            "teacher_id": teacher_id,
            "assignment_type": assignment_type,
            "program_id": program_id,
            "class_id": class_id,
            "subject_id": subject_id,
            "section_id": section_id,
            "teaching_type": teaching_type,
            "status": status,
            "start_date": start_date or "",
            "end_date": end_date or "",
            "is_primary": is_primary,
            "notes": notes or "",
            "scope": scope,
        }

        # ====================================================
        # ROLE-BASED INSTITUTION / BRANCH SECURITY
        # ====================================================

        if current_role == "school_admin":

            institution_id = user_institution_id

            form_values["institution_id"] = institution_id

            if not institution_id:

                flash(
                    "Your account is not linked to an institution.",
                    "danger"
                )

                return redirect(
                    url_for("main.all_teacher_subjects")
                )

        elif current_role == "branch_admin":

            institution_id = user_institution_id
            branch_id = user_branch_id

            form_values["institution_id"] = institution_id
            form_values["branch_id"] = branch_id

            if not institution_id or not branch_id:

                flash(
                    "Your account is not properly linked to an institution and branch.",
                    "danger"
                )

                return redirect(
                    url_for("main.all_teacher_subjects")
                )

        # ====================================================
        # BASIC VALIDATION
        # ====================================================

        errors = []

        if not institution_id:
            errors.append(
                "Institution is required."
            )

        if not branch_id:
            errors.append(
                "Branch is required."
            )

        if not academic_year_id:
            errors.append(
                "Academic year is required."
            )

        if not teacher_id:
            errors.append(
                "Teacher is required."
            )

        allowed_assignment_types = {
            "program",
            "class",
            "subject",
            "section",
        }

        if assignment_type not in allowed_assignment_types:

            errors.append(
                "Invalid assignment type."
            )

        allowed_teaching_types = {
            "teacher",
            "assistant",
            "coordinator",
            "substitute",
        }

        if teaching_type not in allowed_teaching_types:

            errors.append(
                "Invalid teaching type."
            )

        allowed_statuses = {
            "active",
            "inactive",
        }

        if status not in allowed_statuses:

            errors.append(
                "Invalid assignment status."
            )

        # ====================================================
        # SCOPE
        # ====================================================

        # TeacherSubject currently represents a specific
        # assignment, therefore force scope=specific.

        scope = "specific"

        # ====================================================
        # ASSIGNMENT HIERARCHY VALIDATION
        # ====================================================

        # ----------------------------------------------------
        # PROGRAM
        # ----------------------------------------------------

        if assignment_type in {
            "program",
            "class",
            "subject",
            "section",
        }:

            if not program_id:

                errors.append(
                    "Program is required for this assignment type."
                )

        # ----------------------------------------------------
        # CLASS
        # ----------------------------------------------------

        if assignment_type in {
            "class",
            "subject",
            "section",
        }:

            if not class_id:

                errors.append(
                    "Class is required for this assignment type."
                )

        # ----------------------------------------------------
        # SUBJECT
        # ----------------------------------------------------

        if assignment_type in {
            "subject",
            "section",
        }:

            if not subject_id:

                errors.append(
                    "Subject is required for this assignment type."
                )

        # ----------------------------------------------------
        # SECTION
        # ----------------------------------------------------

        if assignment_type == "section":

            if not section_id:

                errors.append(
                    "Section is required for section assignment."
                )

        # ----------------------------------------------------
        # CLEAR UNUSED HIERARCHY VALUES
        # ----------------------------------------------------

        if assignment_type == "program":

            class_id = None
            subject_id = None
            section_id = None

        elif assignment_type == "class":

            subject_id = None
            section_id = None

        elif assignment_type == "subject":

            section_id = None

        form_values["program_id"] = program_id
        form_values["class_id"] = class_id
        form_values["subject_id"] = subject_id
        form_values["section_id"] = section_id

        # ====================================================
        # DATE VALIDATION
        # ====================================================

        parsed_start_date = None
        parsed_end_date = None

        if start_date:

            try:

                parsed_start_date = datetime.strptime(
                    start_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                errors.append(
                    "Start date must be a valid date."
                )

        if end_date:

            try:

                parsed_end_date = datetime.strptime(
                    end_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                errors.append(
                    "End date must be a valid date."
                )

        if (
            parsed_start_date
            and parsed_end_date
            and parsed_end_date < parsed_start_date
        ):

            errors.append(
                "End date cannot be earlier than start date."
            )

        # ====================================================
        # INSTITUTION VALIDATION
        # ====================================================

        institution = None

        if institution_id:

            institution = (
                Institution.query
                .filter(
                    Institution.id == institution_id
                )
                .first()
            )

            if not institution:

                errors.append(
                    "Selected institution does not exist."
                )

        # ====================================================
        # BRANCH VALIDATION
        # ====================================================

        branch = None

        if branch_id:

            branch = (
                Branch.query
                .filter(
                    Branch.id == branch_id
                )
                .first()
            )

            if not branch:

                errors.append(
                    "Selected branch does not exist."
                )

            elif institution and branch.institution_id != institution.id:

                errors.append(
                    "Selected branch does not belong to the selected institution."
                )

        # ====================================================
        # ACADEMIC YEAR VALIDATION
        # ====================================================

        academic_year = None

        if academic_year_id:

            academic_year = (
                AcademicYear.query
                .filter(
                    AcademicYear.id == academic_year_id
                )
                .first()
            )

            if not academic_year:

                errors.append(
                    "Selected academic year does not exist."
                )

            elif (
                institution
                and academic_year.institution_id
                != institution.id
            ):

                errors.append(
                    "Selected academic year does not belong to the selected institution."
                )

        # ====================================================
        # TEACHER VALIDATION
        # ====================================================

        teacher = None

        if teacher_id:

            teacher = (
                Teacher.query
                .filter(
                    Teacher.id == teacher_id
                )
                .first()
            )

            if not teacher:

                errors.append(
                    "Selected teacher does not exist."
                )

            else:

                if (
                    institution
                    and teacher.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected teacher does not belong to the selected institution."
                    )

                if (
                    branch
                    and teacher.branch_id
                    != branch.id
                ):

                    errors.append(
                        "Selected teacher does not belong to the selected branch."
                    )

        # ====================================================
        # PROGRAM VALIDATION
        # ====================================================

        program = None

        if program_id:

            program = (
                Program.query
                .filter(
                    Program.id == program_id
                )
                .first()
            )

            if not program:

                errors.append(
                    "Selected program does not exist."
                )

            else:

                if (
                    institution
                    and program.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected program does not belong to the selected institution."
                    )

                # Program branch can be NULL, meaning
                # institution-wide program.

                if (
                    branch
                    and program.branch_id is not None
                    and program.branch_id != branch.id
                ):

                    errors.append(
                        "Selected program is not available in the selected branch."
                    )

        # ====================================================
        # CLASS VALIDATION
        # ====================================================

        class_obj = None

        if class_id:

            class_obj = (
                Class.query
                .filter(
                    Class.id == class_id
                )
                .first()
            )

            if not class_obj:

                errors.append(
                    "Selected class does not exist."
                )

            else:

                if (
                    institution
                    and class_obj.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected institution."
                    )

                if (
                    branch
                    and class_obj.branch_id
                    != branch.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected branch."
                    )

                if (
                    academic_year
                    and class_obj.academic_year_id
                    != academic_year.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected academic year."
                    )

                if (
                    program
                    and class_obj.program_id
                    != program.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected program."
                    )

        # ====================================================
        # SUBJECT VALIDATION
        # ====================================================

        subject = None

        if subject_id:

            subject = (
                Subject.query
                .filter(
                    Subject.id == subject_id
                )
                .first()
            )

            if not subject:

                errors.append(
                    "Selected subject does not exist."
                )

            else:

                if (
                    institution
                    and subject.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected subject does not belong to the selected institution."
                    )

                # Subject branch may be NULL,
                # meaning institution-wide subject.

                if (
                    branch
                    and subject.branch_id is not None
                    and subject.branch_id != branch.id
                ):

                    errors.append(
                        "Selected subject is not available in the selected branch."
                    )

                # Subject program may be NULL,
                # meaning it can be institution/branch-wide.

                if (
                    program
                    and subject.program_id is not None
                    and subject.program_id != program.id
                ):

                    errors.append(
                        "Selected subject does not belong to the selected program."
                    )

        # ====================================================
        # SECTION VALIDATION
        # ====================================================

        section = None

        if section_id:

            section = (
                Section.query
                .filter(
                    Section.id == section_id
                )
                .first()
            )

            if not section:

                errors.append(
                    "Selected section does not exist."
                )

            else:

                if (
                    institution
                    and section.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected institution."
                    )

                if (
                    branch
                    and section.branch_id
                    != branch.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected branch."
                    )

                if (
                    academic_year
                    and section.academic_year_id
                    != academic_year.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected academic year."
                    )

                if (
                    class_obj
                    and section.class_id
                    != class_obj.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected class."
                    )

        # ====================================================
        # STOP IF VALIDATION ERRORS
        # ====================================================

        if errors:

            for error in errors:

                flash(
                    error,
                    "danger"
                )

        else:

            try:

                # ====================================================
                # DUPLICATE ASSIGNMENT CHECK
                # ====================================================

                duplicate_query = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.id != assignment.id,

                        TeacherSubject.institution_id
                        == institution_id,

                        TeacherSubject.branch_id
                        == branch_id,

                        TeacherSubject.teacher_id
                        == teacher_id,

                        TeacherSubject.academic_year_id
                        == academic_year_id,

                        TeacherSubject.assignment_type
                        == assignment_type,

                        TeacherSubject.program_id
                        == program_id,

                        TeacherSubject.class_id
                        == class_id,

                        TeacherSubject.subject_id
                        == subject_id,

                        TeacherSubject.section_id
                        == section_id,

                        TeacherSubject.status
                        == "active",
                    )
                )

                duplicate = duplicate_query.first()

                if duplicate:

                    flash(
                        "This teacher assignment already exists.",
                        "danger"
                    )

                else:

                    # ====================================================
                    # UPDATE ASSIGNMENT
                    # ====================================================

                    assignment.institution_id = (
                        institution_id
                    )

                    assignment.branch_id = (
                        branch_id
                    )

                    assignment.teacher_id = (
                        teacher_id
                    )

                    assignment.program_id = (
                        program_id
                    )

                    assignment.subject_id = (
                        subject_id
                    )

                    assignment.class_id = (
                        class_id
                    )

                    assignment.section_id = (
                        section_id
                    )

                    assignment.academic_year_id = (
                        academic_year_id
                    )

                    assignment.assignment_type = (
                        assignment_type
                    )

                    assignment.scope = (
                        "specific"
                    )

                    assignment.teaching_type = (
                        teaching_type
                    )

                    assignment.is_primary = (
                        is_primary
                    )

                    assignment.status = (
                        status
                    )

                    assignment.start_date = (
                        parsed_start_date
                    )

                    assignment.end_date = (
                        parsed_end_date
                    )

                    assignment.notes = (
                        notes
                    )

                    # ====================================================
                    # SAVE
                    # ====================================================

                    db.session.commit()

                    flash(
                        "Teacher assignment updated successfully.",
                        "success"
                    )

                    return redirect(
                        url_for(
                            "main.all_teacher_subjects"
                        )
                    )

            except IntegrityError as exc:

                db.session.rollback()

                current_app.logger.exception(
                    "IntegrityError while updating TeacherSubject %s",
                    teacher_subject_id
                )

                flash(
                    "Could not update the teacher assignment because of a database constraint.",
                    "danger"
                )

            except Exception as exc:

                db.session.rollback()

                current_app.logger.exception(
                    "Error while updating TeacherSubject %s",
                    teacher_subject_id
                )

                flash(
                    "An unexpected error occurred while updating the teacher assignment.",
                    "danger"
                )

    # ========================================================
    # GET / RENDER DATA
    # ========================================================

    # --------------------------------------------------------
    # INSTITUTIONS
    # --------------------------------------------------------

    if current_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == user_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # --------------------------------------------------------
    # BRANCHES
    # --------------------------------------------------------

    if current_role == "superadmin":

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            branches = (
                Branch.query
                .filter(
                    Branch.id == user_branch_id,
                    Branch.institution_id
                    == user_institution_id
                )
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

        else:

            branches = (
                Branch.query
                .filter(
                    Branch.institution_id
                    == user_institution_id
                )
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

    else:

        branches = []

    # --------------------------------------------------------
    # ACADEMIC YEARS
    # --------------------------------------------------------

    if current_role == "superadmin":

        academic_years = (
            AcademicYear.query
            .order_by(
                AcademicYear.name.desc()
            )
            .all()
        )

    elif user_institution_id:

        academic_years = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
            .order_by(
                AcademicYear.name.desc()
            )
            .all()
        )

    else:

        academic_years = []

    # --------------------------------------------------------
    # TEACHERS
    # --------------------------------------------------------

    if current_role == "superadmin":

        teachers = (
            Teacher.query
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    elif current_role == "branch_admin":

        teachers = (
            Teacher.query
            .filter(
                Teacher.institution_id
                == user_institution_id,
                Teacher.branch_id
                == user_branch_id
            )
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    else:

        teachers = (
            Teacher.query
            .filter(
                Teacher.institution_id
                == user_institution_id
            )
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    # --------------------------------------------------------
    # PROGRAMS
    # --------------------------------------------------------

    if current_role == "superadmin":

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            programs = (
                Program.query
                .filter(
                    Program.institution_id
                    == user_institution_id,

                    db.or_(
                        Program.branch_id
                        == user_branch_id,

                        Program.branch_id.is_(None)
                    )
                )
                .order_by(
                    Program.name.asc()
                )
                .all()
            )

        else:

            programs = (
                Program.query
                .filter(
                    Program.institution_id
                    == user_institution_id
                )
                .order_by(
                    Program.name.asc()
                )
                .all()
            )

    else:

        programs = []

    # --------------------------------------------------------
    # CLASSES
    # --------------------------------------------------------

    if current_role == "superadmin":

        classes = (
            Class.query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            classes = (
                Class.query
                .filter(
                    Class.institution_id
                    == user_institution_id,

                    Class.branch_id
                    == user_branch_id
                )
                .order_by(
                    Class.name.asc()
                )
                .all()
            )

        else:

            classes = (
                Class.query
                .filter(
                    Class.institution_id
                    == user_institution_id
                )
                .order_by(
                    Class.name.asc()
                )
                .all()
            )

    else:

        classes = []

    # --------------------------------------------------------
    # SUBJECTS
    # --------------------------------------------------------

    if current_role == "superadmin":

        subjects = (
            Subject.query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            subjects = (
                Subject.query
                .filter(
                    Subject.institution_id
                    == user_institution_id,

                    db.or_(
                        Subject.branch_id
                        == user_branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
                .order_by(
                    Subject.name.asc()
                )
                .all()
            )

        else:

            subjects = (
                Subject.query
                .filter(
                    Subject.institution_id
                    == user_institution_id
                )
                .order_by(
                    Subject.name.asc()
                )
                .all()
            )

    else:

        subjects = []

    # --------------------------------------------------------
    # SECTIONS
    # --------------------------------------------------------

    if current_role == "superadmin":

        sections = (
            Section.query
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            sections = (
                Section.query
                .filter(
                    Section.institution_id
                    == user_institution_id,

                    Section.branch_id
                    == user_branch_id
                )
                .order_by(
                    Section.name.asc()
                )
                .all()
            )

        else:

            sections = (
                Section.query
                .filter(
                    Section.institution_id
                    == user_institution_id
                )
                .order_by(
                    Section.name.asc()
                )
                .all()
            )

    else:

        sections = []

    # ========================================================
    # CURRENT IDS
    # ========================================================

    current_institution_id = (
        form_values.get(
            "institution_id"
        )
        if request.method == "POST" and form_values
        else assignment.institution_id
    )

    current_branch_id = (
        form_values.get(
            "branch_id"
        )
        if request.method == "POST" and form_values
        else assignment.branch_id
    )

    current_academic_year_id = (
        form_values.get(
            "academic_year_id"
        )
        if request.method == "POST" and form_values
        else assignment.academic_year_id
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/teacher_subjects/edit_teacher_subject.html",

        assignment=assignment,

        institutions=institutions,
        branches=branches,
        academic_years=academic_years,
        teachers=teachers,
        programs=programs,
        classes=classes,
        subjects=subjects,
        sections=sections,

        form_values=form_values,

        current_role=current_role,

        current_institution_id=current_institution_id,
        current_branch_id=current_branch_id,
        current_academic_year_id=current_academic_year_id,

        is_superadmin=(
            current_role == "superadmin"
        ),

        is_school_admin=(
            current_role == "school_admin"
        ),

        is_branch_admin=(
            current_role == "branch_admin"
        ),
    )


# ============================================================
# DELETE TEACHER SUBJECT
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>/delete",
    methods=["POST"]
)
@login_required
def delete_teacher_subject(teacher_subject_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    role = getattr(
        current_user,
        "role",
        None
    )

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # GET ASSIGNMENT
    # ========================================================

    teacher_subject = (
        TeacherSubject.query
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first()
    )

    if teacher_subject is None:

        flash(
            "Teacher subject assignment was not found.",
            "error"
        )

        return redirect(
            url_for(
                "main.all_teacher_subjects"
            )
        )

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    assignment_institution_id = getattr(
        teacher_subject,
        "institution_id",
        None
    )

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    if role != "superadmin":

        if not current_institution_id:
            abort(403)

        if (
            assignment_institution_id
            and
            assignment_institution_id != current_institution_id
        ):
            abort(403)

    # ========================================================
    # BRANCH SECURITY
    # ========================================================

    if role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        assignment_branch_id = getattr(
            teacher_subject,
            "branch_id",
            None
        )

        if not current_branch_id:
            abort(403)

        if (
            assignment_branch_id
            and
            assignment_branch_id != current_branch_id
        ):
            abort(403)

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            teacher_subject
        )

        db.session.commit()

        flash(
            "Teacher subject assignment deleted successfully.",
            "success"
        )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Error deleting TeacherSubject ID %s: %s",
            teacher_subject_id,
            e
        )

        flash(
            "Unable to delete teacher subject assignment.",
            "error"
        )

    # ========================================================
    # REDIRECT
    # ========================================================

    return redirect(
        url_for(
            "main.all_teacher_subjects"
        )
    )



# ============================================================
# TOGGLE TEACHER SUBJECT STATUS
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>/toggle-status",
    methods=["POST"]
)
@login_required
def toggle_teacher_subject_status(teacher_subject_id):

    # ========================================================
    # AUTHORIZATION
    # ========================================================

    if not _teacher_subject_can_manage():
        flash(
            "You are not authorized to change assignment status.",
            "danger"
        )
        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # LOAD
    # ========================================================

    teacher_subject = (
        TeacherSubject.query
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first_or_404()
    )

    # ========================================================
    # SECURITY
    # ========================================================

    user_institution_id = (
        _teacher_subject_user_institution_id()
    )

    user_branch_id = (
        _teacher_subject_user_branch_id()
    )

    role = getattr(
        current_user,
        "role",
        None
    )

    if (
        role != "superadmin"
        and user_institution_id
        and teacher_subject.institution_id
        != user_institution_id
    ):
        abort(403)

    if (
        role == "branch_admin"
        and user_branch_id
        and teacher_subject.branch_id
        != user_branch_id
    ):
        abort(403)

    # ========================================================
    # TOGGLE
    # ========================================================

    try:

        if teacher_subject.status == "active":

            teacher_subject.status = "inactive"

            message = (
                "Teacher subject assignment "
                "deactivated successfully."
            )

        else:

            teacher_subject.status = "active"

            message = (
                "Teacher subject assignment "
                "activated successfully."
            )

        db.session.commit()

        flash(
            message,
            "success"
        )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Error toggling TeacherSubject status: %s",
            e
        )

        flash(
            "Unable to change assignment status.",
            "danger"
        )

    return redirect(
        request.referrer
        or url_for(
            "main.all_teacher_subjects"
        )
    )


# ============================================================
# TOGGLE TEACHER SUBJECT PRIMARY
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>/toggle-primary",
    methods=["POST"]
)
@login_required
def toggle_teacher_subject_primary(
    teacher_subject_id
):

    # ========================================================
    # AUTHORIZATION
    # ========================================================

    if not _teacher_subject_can_manage():
        flash(
            "You are not authorized to change primary assignment.",
            "danger"
        )
        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # LOAD
    # ========================================================

    teacher_subject = (
        TeacherSubject.query
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first_or_404()
    )

    # ========================================================
    # SECURITY
    # ========================================================

    user_institution_id = (
        _teacher_subject_user_institution_id()
    )

    user_branch_id = (
        _teacher_subject_user_branch_id()
    )

    role = getattr(
        current_user,
        "role",
        None
    )

    if (
        role != "superadmin"
        and user_institution_id
        and teacher_subject.institution_id
        != user_institution_id
    ):
        abort(403)

    if (
        role == "branch_admin"
        and user_branch_id
        and teacher_subject.branch_id
        != user_branch_id
    ):
        abort(403)

    # ========================================================
    # TOGGLE
    # ========================================================

    try:

        teacher_subject.is_primary = (
            not teacher_subject.is_primary
        )

        db.session.commit()

        if teacher_subject.is_primary:

            flash(
                "Teacher subject assignment is now Primary.",
                "success"
            )

        else:

            flash(
                "Teacher subject assignment is now Secondary.",
                "info"
            )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Error toggling TeacherSubject primary: %s",
            e
        )

        flash(
            "Unable to change primary assignment.",
            "danger"
        )

    return redirect(
        request.referrer
        or url_for(
            "main.view_teacher_subject",
            teacher_subject_id=teacher_subject.id
        )
    )


