# ============================================================
# AUTHORIZATION
# ============================================================

def _student_can_manage():
    """
    Student CRUD maamulka waxaa geli kara:
    superadmin
    institution_admin
    branch_admin
    """

    role = getattr(current_user, "role", None)

    return role in {
        "superadmin",
        "institution_admin",
        "branch_admin",
    }



def _student_user_institution_id():
    return getattr(current_user, "institution_id", None)


def _student_user_branch_id():
    return getattr(current_user, "branch_id", None)


# ============================================================
# ACCESS CHECK
# ============================================================

def _student_has_access(student):
    """
    Hubi in current admin uu arki/khanayn karo student-ka.
    """

    role = getattr(current_user, "role", None)

    if role == "superadmin":
        return True

    user_institution_id = _student_user_institution_id()
    user_branch_id = _student_user_branch_id()

    if role == "institution_admin":
        return (
            student.institution_id == user_institution_id
        )

    if role == "branch_admin":
        return (
            student.institution_id == user_institution_id
            and
            student.branch_id == user_branch_id
        )

    return False


# ============================================================
# ALL STUDENTS
# ============================================================
@bp.route("/students", methods=["GET"])
@login_required
def all_students():
    """
    ALL STUDENTS
    ============================================================
    Student management/list page.

    Supported roles:
        superadmin
        school_admin
        branch_admin

    Features:
        - Role-based security
        - Institution filter
        - Branch filter
        - Search
        - Status filter
        - Pagination
        - Accurate statistics
        - Student-only records
    """

    # ============================================================
    # IMPORTS
    # ============================================================

    from flask import (
        flash,
        redirect,
        render_template,
        request,
        url_for,
    )

    from flask_login import (
        current_user,
        login_required,
    )

    from sqlalchemy import or_, func

    # ============================================================
    # ACCESS CONTROL
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None,
    )

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to manage students.",
            "danger",
        )

        return redirect(
            url_for(
                "main.dashboard"
            )
        )

    # ============================================================
    # CURRENT USER SCOPE
    # ============================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None,
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None,
    )

    # ============================================================
    # ROLE SCOPE VALIDATION
    # ============================================================

    if current_role == "school_admin":

        if not current_institution_id:

            flash(
                "Your account is not linked to an institution.",
                "warning",
            )

            return redirect(
                url_for(
                    "main.dashboard"
                )
            )

    elif current_role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):

            flash(
                "Your account is not linked to an institution and branch.",
                "warning",
            )

            return redirect(
                url_for(
                    "main.dashboard"
                )
            )

    # ============================================================
    # REQUEST FILTERS
    # ============================================================

    search = request.args.get(
        "search",
        "",
        type=str,
    ).strip()

    institution_id_raw = request.args.get(
        "institution_id",
        "",
        type=str,
    ).strip()

    branch_id_raw = request.args.get(
        "branch_id",
        "",
        type=str,
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str,
    ).strip().lower()

    page = request.args.get(
        "page",
        1,
        type=int,
    )

    per_page = request.args.get(
        "per_page",
        20,
        type=int,
    )

    # ============================================================
    # PAGINATION VALIDATION
    # ============================================================

    if page < 1:
        page = 1

    allowed_per_page = {
        10,
        20,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 20

    # ============================================================
    # VALID STUDENT STATUSES
    # ============================================================

    allowed_statuses = {
        "active",
        "inactive",
        "graduated",
        "transferred",
        "suspended",
        "withdrawn",
    }

    if status not in allowed_statuses:
        status = ""

    # ============================================================
    # PARSE FILTER IDS
    # ============================================================

    selected_institution_id = None
    selected_branch_id = None

    # ------------------------------------------------------------
    # Institution
    # ------------------------------------------------------------

    if institution_id_raw:

        try:
            selected_institution_id = int(
                institution_id_raw
            )
        except (
            TypeError,
            ValueError,
        ):
            selected_institution_id = None

    # ------------------------------------------------------------
    # Branch
    # ------------------------------------------------------------

    if branch_id_raw:

        try:
            selected_branch_id = int(
                branch_id_raw
            )
        except (
            TypeError,
            ValueError,
        ):
            selected_branch_id = None

    # ============================================================
    # ENFORCE ROLE SCOPE ON FILTERS
    # ============================================================

    # ------------------------------------------------------------
    # SUPERADMIN
    # ------------------------------------------------------------

    if current_role == "superadmin":

        # Superadmin may use the submitted filters.
        pass

    # ------------------------------------------------------------
    # SCHOOL ADMIN
    # ------------------------------------------------------------

    elif current_role == "school_admin":

        # School admin can ONLY see own institution.
        selected_institution_id = (
            current_institution_id
        )

        # If selected branch is supplied, verify it belongs
        # to the current institution.
        if selected_branch_id:

            valid_branch = (
                Branch.query
                .filter(
                    Branch.id
                    == selected_branch_id,

                    Branch.institution_id
                    == current_institution_id,
                )
                .first()
            )

            if not valid_branch:

                selected_branch_id = None

    # ------------------------------------------------------------
    # BRANCH ADMIN
    # ------------------------------------------------------------

    elif current_role == "branch_admin":

        # Branch admin can ONLY see own institution + branch.
        selected_institution_id = (
            current_institution_id
        )

        selected_branch_id = (
            current_branch_id
        )

    # ============================================================
    # BASE STUDENT QUERY
    # ============================================================
    #
    # Always restrict to actual students.
    #

    base_query = (
        Student.query
        .filter(
            Student.role == "student"
        )
    )

    # ============================================================
    # APPLY ROLE SCOPE
    # ============================================================

    if current_role == "school_admin":

        base_query = base_query.filter(
            Student.institution_id
            == current_institution_id
        )

    elif current_role == "branch_admin":

        base_query = base_query.filter(
            Student.institution_id
            == current_institution_id,

            Student.branch_id
            == current_branch_id,
        )

    # ============================================================
    # APPLY INSTITUTION FILTER
    # ============================================================

    if selected_institution_id:

        base_query = base_query.filter(
            Student.institution_id
            == selected_institution_id
        )

    # ============================================================
    # APPLY BRANCH FILTER
    # ============================================================

    if selected_branch_id:

        base_query = base_query.filter(
            Student.branch_id
            == selected_branch_id
        )

    # ============================================================
    # SEARCH FILTER
    # ============================================================

    if search:

        search_pattern = (
            f"%{search}%"
        )

        base_query = base_query.filter(
            or_(
                Student.full_name.ilike(
                    search_pattern
                ),

                Student.username.ilike(
                    search_pattern
                ),

                Student.email.ilike(
                    search_pattern
                ),

                Student.admission_no.ilike(
                    search_pattern
                ),

                Student.roll_no.ilike(
                    search_pattern
                ),

                Student.phone.ilike(
                    search_pattern
                ),

                Student.city.ilike(
                    search_pattern
                ),

                Student.parent_name.ilike(
                    search_pattern
                ),

                Student.parent_phone.ilike(
                    search_pattern
                ),

                Student.parent_email.ilike(
                    search_pattern
                ),
            )
        )

    # ============================================================
    # STATUS FILTER
    # ============================================================

    if status:

        base_query = base_query.filter(
            Student.status == status
        )

    # ============================================================
    # STATISTICS
    # ============================================================
    #
    # These statistics represent the CURRENT FILTERED RESULT:
    #
    # search + institution + branch + status
    #
    # This is useful for cards at the top of the page.
    #

    total_students = (
        base_query
        .with_entities(
            func.count(Student.id)
        )
        .scalar()
        or 0
    )

    active_students = (
        base_query
        .filter(
            Student.status == "active"
        )
        .with_entities(
            func.count(Student.id)
        )
        .scalar()
        or 0
    )

    inactive_students = (
        base_query
        .filter(
            Student.status == "inactive"
        )
        .with_entities(
            func.count(Student.id)
        )
        .scalar()
        or 0
    )

    graduated_students = (
        base_query
        .filter(
            Student.status == "graduated"
        )
        .with_entities(
            func.count(Student.id)
        )
        .scalar()
        or 0
    )

    transferred_students = (
        base_query
        .filter(
            Student.status == "transferred"
        )
        .with_entities(
            func.count(Student.id)
        )
        .scalar()
        or 0
    )

    suspended_students = (
        base_query
        .filter(
            Student.status == "suspended"
        )
        .with_entities(
            func.count(Student.id)
        )
        .scalar()
        or 0
    )

    withdrawn_students = (
        base_query
        .filter(
            Student.status == "withdrawn"
        )
        .with_entities(
            func.count(Student.id)
        )
        .scalar()
        or 0
    )

    # ============================================================
    # ORDERING
    # ============================================================

    students_query = (
        base_query
        .order_by(
            Student.full_name.asc(),
            Student.id.desc(),
        )
    )

    # ============================================================
    # PAGINATION
    # ============================================================

    pagination = (
        students_query
        .paginate(
            page=page,
            per_page=per_page,
            error_out=False,
        )
    )

    students = pagination.items

    # ============================================================
    # INSTITUTIONS FOR FILTER
    # ============================================================

    if current_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == current_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ============================================================
    # BRANCHES FOR FILTER
    # ============================================================

    if current_role == "superadmin":

        if selected_institution_id:

            branches = (
                Branch.query
                .filter(
                    Branch.institution_id
                    == selected_institution_id
                )
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

        else:

            branches = (
                Branch.query
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

    elif current_role == "school_admin":

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        branches = (
            Branch.query
            .filter(
                Branch.id
                == current_branch_id,

                Branch.institution_id
                == current_institution_id,
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    # ============================================================
    # FINAL SELECTED VALUES
    # ============================================================

    if current_role == "school_admin":

        selected_institution_id = (
            current_institution_id
        )

    elif current_role == "branch_admin":

        selected_institution_id = (
            current_institution_id
        )

        selected_branch_id = (
            current_branch_id
        )

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(
        "backend/pages/students/all_students.html",

        # --------------------------------------------------------
        # Students
        # --------------------------------------------------------

        students=students,

        pagination=pagination,

        # --------------------------------------------------------
        # Filters
        # --------------------------------------------------------

        search=search,

        selected_institution_id=(
            selected_institution_id
        ),

        selected_branch_id=(
            selected_branch_id
        ),

        selected_status=status,

        per_page=per_page,

        # --------------------------------------------------------
        # Filter data
        # --------------------------------------------------------

        institutions=institutions,

        branches=branches,

        # --------------------------------------------------------
        # Statistics
        # --------------------------------------------------------

        total_students=(
            total_students
        ),

        active_students=(
            active_students
        ),

        inactive_students=(
            inactive_students
        ),

        graduated_students=(
            graduated_students
        ),

        transferred_students=(
            transferred_students
        ),

        suspended_students=(
            suspended_students
        ),

        withdrawn_students=(
            withdrawn_students
        ),

        # --------------------------------------------------------
        # Current user
        # --------------------------------------------------------

        user=current_user,

        current_role=current_role,

        current_institution_id=(
            current_institution_id
        ),

        current_branch_id=(
            current_branch_id
        ),
    )



