# ============================================================
# PARENT / GUARDIAN PRESELECTOR
# ============================================================

@bp.route("/student-parent-search", methods=["GET"])
@login_required
def student_parent_search():

    # ============================================================
    # SEARCH TEXT
    # ============================================================

    q = (request.args.get("q") or "").strip()

    if len(q) < 2:
        return jsonify({
            "results": []
        })

    # ============================================================
    # CURRENT USER ROLE
    # ============================================================

    role = getattr(current_user, "role", "")

    if hasattr(role, "value"):
        role = role.value

    role = str(role).lower().strip()

    # ============================================================
    # OPTIONAL SELECTED CONTEXT FROM FRONTEND
    # ============================================================

    selected_institution_id = (
        request.args.get("institution_id", type=int)
    )

    selected_branch_id = (
        request.args.get("branch_id", type=int)
    )

    # ============================================================
    # BASE QUERY
    # ============================================================

    query = Student.query

    # ============================================================
    # INSTITUTION SECURITY
    # ============================================================

    if role == "superadmin":

        # Superadmin can search selected institution
        if selected_institution_id:
            query = query.filter(
                Student.institution_id == selected_institution_id
            )

    else:

        # Non-superadmin must stay inside own institution
        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if user_institution_id:
            query = query.filter(
                Student.institution_id == user_institution_id
            )

    # ============================================================
    # BRANCH SECURITY / FILTER
    # ============================================================

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if role == "branch_admin":

        # Branch admin can ONLY search own branch
        if user_branch_id:
            query = query.filter(
                Student.branch_id == user_branch_id
            )

    elif selected_branch_id:

        # Selected branch for superadmin / school_admin
        query = query.filter(
            Student.branch_id == selected_branch_id
        )

    elif user_branch_id and role != "school_admin":

        # If another role has a fixed branch
        query = query.filter(
            Student.branch_id == user_branch_id
        )

    # ============================================================
    # SEARCH CONDITIONS
    # ============================================================

    search_pattern = f"%{q}%"

    search_conditions = [
        # Parent / Guardian
        Student.parent_name.ilike(search_pattern),
        Student.parent_phone.ilike(search_pattern),
        Student.parent_email.ilike(search_pattern),

        # Student
        Student.full_name.ilike(search_pattern),
        Student.admission_no.ilike(search_pattern),
    ]

    # ============================================================
    # ROLL NUMBER
    # ============================================================

    # Student model-kaaga haddii roll_no leeyahay,
    # search-ka waa lagu daraa.
    if hasattr(Student, "roll_no"):
        search_conditions.append(
            Student.roll_no.ilike(search_pattern)
        )

    query = query.filter(
        or_(*search_conditions)
    )

    # ============================================================
    # ONLY STUDENTS WITH PARENT/GUARDIAN INFORMATION
    # ============================================================

    query = query.filter(
        or_(
            and_(
                Student.parent_name.isnot(None),
                func.trim(Student.parent_name) != ""
            ),
            and_(
                Student.parent_phone.isnot(None),
                func.trim(Student.parent_phone) != ""
            ),
            and_(
                Student.parent_email.isnot(None),
                func.trim(Student.parent_email) != ""
            )
        )
    )

    # ============================================================
    # ORDER + LIMIT
    # ============================================================

    students = (
        query
        .order_by(
            Student.parent_name.asc(),
            Student.full_name.asc()
        )
        .limit(30)
        .all()
    )

    # ============================================================
    # BUILD RESULTS
    # ============================================================

    results = []

    # Prevent duplicate parent records
    seen = set()

    for student in students:

        parent_name = (
            getattr(student, "parent_name", None)
            or ""
        ).strip()

        parent_phone = (
            getattr(student, "parent_phone", None)
            or ""
        ).strip()

        parent_email = (
            getattr(student, "parent_email", None)
            or ""
        ).strip()

        parent_address = (
            getattr(student, "parent_address", None)
            or ""
        ).strip()

        relationship = (
            getattr(
                student,
                "relationship_to_student",
                None
            )
            or ""
        ).strip()

        student_name = (
            getattr(student, "full_name", None)
            or ""
        ).strip()

        admission_no = (
            getattr(student, "admission_no", None)
            or ""
        ).strip()

        roll_no = (
            getattr(student, "roll_no", None)
            or ""
        ).strip()

        # ========================================================
        # SKIP EMPTY PARENT
        # ========================================================

        if not (
            parent_name
            or parent_phone
            or parent_email
        ):
            continue

        # ========================================================
        # UNIQUE PARENT KEY
        # ========================================================

        unique_key = (
            parent_email.lower()
            if parent_email
            else (
                parent_phone
                if parent_phone
                else parent_name.lower()
            )
        )

        if unique_key in seen:
            continue

        seen.add(unique_key)

        # ========================================================
        # RESULT
        # ========================================================

        results.append({
            "id": student.id,

            # Parent IDs / names
            "parent_id": student.id,
            "name": parent_name,
            "parent_name": parent_name,
            "full_name": parent_name,
            "guardian_name": parent_name,

            # Relationship
            "relationship": relationship,
            "relationship_to_student": relationship,

            # Contact
            "phone": parent_phone,
            "parent_phone": parent_phone,

            "email": parent_email,
            "parent_email": parent_email,

            "address": parent_address,
            "parent_address": parent_address,

            # Related student
            "student_id": student.id,
            "student_name": student_name,
            "admission_no": admission_no,
            "roll_no": roll_no,

            # Institution / branch
            "institution_id": getattr(
                student,
                "institution_id",
                None
            ),

            "branch_id": getattr(
                student,
                "branch_id",
                None
            )
        })

    # ============================================================
    # JSON RESPONSE
    # ============================================================

    return jsonify({
        "success": True,
        "results": results,
        "parents": results,
        "count": len(results)
    })




# ============================================================
# ADD STUDENT
# ============================================================

@bp.route("/add-student", methods=["GET", "POST"])
@login_required
def add_student():

    # ========================================================
    # IMPORTS
    # ========================================================

    import os
    import secrets
    import string

    from datetime import date, datetime
    from decimal import Decimal, InvalidOperation

    from flask import (
        current_app,
        flash,
        redirect,
        render_template,
        request,
        session,
        url_for,
    )

    from sqlalchemy import or_

    from werkzeug.utils import secure_filename

    # ========================================================
    # ACCESS CONTROL
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if getattr(
        current_user,
        "role",
        None
    ) not in allowed_roles:

        flash(
            "You do not have permission to add students.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # HELPERS
    # ========================================================

    def _clean(value):

        if value is None:
            return ""

        return str(value).strip()

    # --------------------------------------------------------

    def _decimal(
        value,
        default=Decimal("0.00")
    ):

        value = _clean(value)

        if not value:
            return default

        try:

            value = value.replace(",", "")

            return Decimal(
                value
            ).quantize(
                Decimal("0.01")
            )

        except (
            InvalidOperation,
            ValueError,
        ):

            return default

    # --------------------------------------------------------

    def _parse_date(
        value,
        default=None
    ):

        value = _clean(value)

        if not value:
            return default

        formats = (
            "%Y-%m-%d",
            "%d-%m-%Y",
            "%d/%m/%Y",
        )

        for fmt in formats:

            try:

                return datetime.strptime(
                    value,
                    fmt
                ).date()

            except ValueError:

                continue

        return default

    # --------------------------------------------------------

    def _random_password(
        length=10
    ):

        chars = (
            string.ascii_letters
            + string.digits
        )

        return "".join(
            secrets.choice(chars)
            for _ in range(length)
        )

    # --------------------------------------------------------

    def _first_name(
        full_name
    ):

        name = _clean(
            full_name
        )

        if not name:
            return "student"

        return (
            name
            .split()[0]
            .lower()
        )

    # --------------------------------------------------------

    def _institution_prefix(
        institution
    ):

        if not institution:
            return "STU"

        short_name = _clean(
            getattr(
                institution,
                "short_name",
                ""
            )
        )

        name = _clean(
            getattr(
                institution,
                "name",
                ""
            )
        )

        source = (
            short_name
            or name
        )

        if not source:
            return "STU"

        letters = [
            char.upper()
            for char in source
            if char.isalpha()
        ]

        if len(letters) >= 3:

            return "".join(
                letters[:3]
            )

        if letters:

            return "".join(
                letters
            ).ljust(
                3,
                "X"
            )

        return "STU"

    # --------------------------------------------------------

    def _next_student_sequence(
        institution_id
    ):

        students = (
            Student.query
            .filter(
                Student.institution_id
                == institution_id
            )
            .all()
        )

        highest = 0

        for student in students:

            value = _clean(
                getattr(
                    student,
                    "admission_no",
                    ""
                )
            )

            if not value:
                continue

            digits = "".join(
                char
                for char in value
                if char.isdigit()
            )

            if not digits:
                continue

            try:

                number = int(
                    digits
                )

                if number > highest:
                    highest = number

            except ValueError:

                continue

        return highest + 1

    # --------------------------------------------------------

    def _generate_student_numbers(
        institution
    ):

        prefix = _institution_prefix(
            institution
        )

        sequence = (
            _next_student_sequence(
                institution.id
            )
        )

        year = date.today().year

        admission_no = (
            f"{prefix}-"
            f"{year}-"
            f"{sequence:05d}"
        )

        roll_no = str(
            sequence
        )

        return (
            admission_no,
            roll_no
        )

    # --------------------------------------------------------

    def _generate_username(
        full_name
    ):

        base = _first_name(
            full_name
        )

        base = "".join(
            char
            for char in base
            if char.isalnum()
        ).lower()

        if not base:
            base = "student"

        year = date.today().year

        username = (
            f"{base}{year}"
        )

        original = username

        counter = 1

        while (
            Student.query
            .filter(
                Student.username
                == username
            )
            .first()
            is not None
        ):

            counter += 1

            username = (
                f"{original}{counter}"
            )

        return username

    # --------------------------------------------------------

    def _generate_email(
        full_name,
        admission_no
    ):

        base = _first_name(
            full_name
        )

        base = "".join(
            char
            for char in base
            if char.isalnum()
        ).lower()

        if not base:
            base = "student"

        domain = (
            current_app.config.get(
                "STUDENT_EMAIL_DOMAIN"
            )
            or "student.local"
        )

        email_base = (
            f"{base}."
            f"{str(admission_no).lower()}"
        )

        email = (
            f"{email_base}@{domain}"
        )

        counter = 1

        while (
            Student.query
            .filter(
                Student.email
                == email
            )
            .first()
            is not None
        ):

            email = (
                f"{email_base}"
                f"{counter}@{domain}"
            )

            counter += 1

        return email

    # --------------------------------------------------------

    def _generate_enrollment_no(
        admission_no,
        index
    ):

        return (
            f"{admission_no}-"
            f"E{index + 1:02d}"
        )

    # --------------------------------------------------------

    def _form_list_value(
        values,
        index
    ):

        if index >= len(values):
            return ""

        return _clean(
            values[index]
        )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        try:

            # ====================================================
            # STUDENT BASIC INFORMATION
            # ====================================================

            full_name = _clean(
                request.form.get(
                    "full_name"
                )
            )

            gender = _clean(
                request.form.get(
                    "gender"
                )
            )

            date_of_birth = _parse_date(
                request.form.get(
                    "date_of_birth"
                )
            )

            place_of_birth = _clean(
                request.form.get(
                    "place_of_birth"
                )
            )

            nationality = _clean(
                request.form.get(
                    "nationality"
                )
            )

            phone = _clean(
                request.form.get(
                    "phone"
                )
            )

            email = _clean(
                request.form.get(
                    "email"
                )
            )

            address = _clean(
                request.form.get(
                    "address"
                )
            )

            city = _clean(
                request.form.get(
                    "city"
                )
            )

            status = (
                _clean(
                    request.form.get(
                        "status"
                    )
                )
                or "active"
            )

            notes = _clean(
                request.form.get(
                    "notes"
                )
            )

            # ====================================================
            # THESE FIELDS MAY EXIST IN TEMPLATE
            # BUT ARE NOT IN Student MODEL.
            #
            # We intentionally READ them only so the form
            # remains compatible.
            # ====================================================

            country = _clean(
                request.form.get(
                    "country"
                )
            )

            phone_country = _clean(
                request.form.get(
                    "phone_country"
                )
            )

            state = _clean(
                request.form.get(
                    "state"
                )
            )

            # ====================================================
            # PARENT / GUARDIAN
            # ====================================================

            parent_name = _clean(
                request.form.get(
                    "parent_name"
                )
            )

            relationship_to_student = _clean(
                request.form.get(
                    "relationship_to_student"
                )
            )

            parent_phone = _clean(
                request.form.get(
                    "parent_phone"
                )
            )

            parent_email = _clean(
                request.form.get(
                    "parent_email"
                )
            )

            parent_address = _clean(
                request.form.get(
                    "parent_address"
                )
            )

            # ====================================================
            # VALIDATE NAME
            # ====================================================

            if not full_name:

                raise ValueError(
                    "Student full name is required."
                )

            # ====================================================
            # INSTITUTION
            # ====================================================

            submitted_institution_id = (
                request.form.get(
                    "institution_id",
                    type=int
                )
            )

            if current_user.role == "superadmin":

                institution_id = (
                    submitted_institution_id
                )

            else:

                institution_id = (
                    current_institution_id
                )

                if (
                    submitted_institution_id
                    and
                    submitted_institution_id
                    != institution_id
                ):

                    raise ValueError(
                        "You cannot add a student "
                        "to another institution."
                    )

            if not institution_id:

                raise ValueError(
                    "Institution is required."
                )

            # ====================================================
            # GET INSTITUTION
            # ====================================================

            institution = (
                Institution.query
                .filter(
                    Institution.id
                    == institution_id
                )
                .first()
            )

            if not institution:

                raise ValueError(
                    "Selected institution was not found."
                )

            # ====================================================
            # BRANCH
            # ====================================================

            submitted_branch_id = (
                request.form.get(
                    "branch_id",
                    type=int
                )
            )

            if (
                current_user.role
                == "branch_admin"
            ):

                branch_id = (
                    current_branch_id
                )

            else:

                branch_id = (
                    submitted_branch_id
                )

            if not branch_id:

                raise ValueError(
                    "Branch is required."
                )

            # ====================================================
            # GET BRANCH
            # ====================================================

            branch = (
                Branch.query
                .filter(
                    Branch.id
                    == branch_id,

                    Branch.institution_id
                    == institution_id
                )
                .first()
            )

            if not branch:

                raise ValueError(
                    "Selected branch does not "
                    "belong to the selected institution."
                )

            # ====================================================
            # BRANCH ADMIN SECURITY
            # ====================================================

            if (
                current_user.role
                == "branch_admin"
            ):

                if (
                    current_institution_id
                    != institution_id
                ):

                    raise ValueError(
                        "Invalid institution access."
                    )

                if (
                    current_branch_id
                    != branch_id
                ):

                    raise ValueError(
                        "Invalid branch access."
                    )

            # ====================================================
            # SCHOOL ADMIN SECURITY
            # ====================================================

            if (
                current_user.role
                == "school_admin"
            ):

                if (
                    current_institution_id
                    != institution_id
                ):

                    raise ValueError(
                        "You can only add students "
                        "to your institution."
                    )

            # ====================================================
            # STATUS
            # ====================================================

            allowed_student_statuses = {
                "active",
                "inactive",
                "graduated",
                "transferred",
                "suspended",
                "withdrawn",
            }

            if (
                status
                not in allowed_student_statuses
            ):

                status = "active"

            # ====================================================
            # GENERATE STUDENT NUMBERS
            # ====================================================

            (
                admission_no,
                roll_no
            ) = _generate_student_numbers(
                institution
            )

            # ====================================================
            # USERNAME
            # ====================================================

            username = _generate_username(
                full_name
            )

            # ====================================================
            # PASSWORD
            # ====================================================

            generated_password = (
                _random_password(10)
            )

            # ====================================================
            # EMAIL
            # ====================================================

            if email:

                existing_email = (
                    Student.query
                    .filter(
                        Student.email
                        == email
                    )
                    .first()
                )

                if existing_email:

                    raise ValueError(
                        "The email address is already "
                        "used by another student."
                    )

            else:

                email = _generate_email(
                    full_name,
                    admission_no
                )

            # ====================================================
            # CREATE STUDENT
            #
            # IMPORTANT:
            # No country
            # No phone_country
            # No state
            #
            # because these fields DO NOT EXIST
            # in the supplied Student model.
            # ====================================================

            student = Student(

                institution_id=(
                    institution_id
                ),

                branch_id=(
                    branch_id
                ),

                username=(
                    username
                ),

                email=(
                    email
                ),

                password="",

                role="student",

                is_active=(
                    status == "active"
                ),

                is_verified=False,

                admission_no=(
                    admission_no
                ),

                roll_no=(
                    roll_no
                ),

                full_name=(
                    full_name
                ),

                gender=(
                    gender or None
                ),

                date_of_birth=(
                    date_of_birth
                ),

                place_of_birth=(
                    place_of_birth or None
                ),

                nationality=(
                    nationality or None
                ),

                phone=(
                    phone or None
                ),

                address=(
                    address or None
                ),

                city=(
                    city or None
                ),

                parent_name=(
                    parent_name or None
                ),

                parent_phone=(
                    parent_phone or None
                ),

                parent_email=(
                    parent_email or None
                ),

                parent_address=(
                    parent_address or None
                ),

                relationship_to_student=(
                    relationship_to_student
                    or None
                ),

                status=(
                    status
                ),

                notes=(
                    notes or None
                ),
            )

            # ====================================================
            # PASSWORD HASH
            # ====================================================

            student.set_password(
                generated_password
            )

            # ====================================================
            # PHOTO
            # ====================================================

            photo = request.files.get(
                "photo"
            )

            if (
                photo
                and
                photo.filename
            ):

                original_filename = (
                    secure_filename(
                        photo.filename
                    )
                )

                extension = ""

                if "." in original_filename:

                    extension = (
                        original_filename
                        .rsplit(
                            ".",
                            1
                        )[1]
                        .lower()
                    )

                allowed_extensions = {
                    "jpg",
                    "jpeg",
                    "png",
                    "webp",
                }

                if (
                    extension
                    not in allowed_extensions
                ):

                    raise ValueError(
                        "Invalid photo format. "
                        "Use JPG, JPEG, PNG or WEBP."
                    )

                upload_directory = os.path.join(
                    current_app.root_path,
                    "static",
                    "uploads",
                    "students"
                )

                os.makedirs(
                    upload_directory,
                    exist_ok=True
                )

                filename = (
                    "student_"
                    f"{secrets.token_hex(10)}."
                    f"{extension}"
                )

                absolute_path = os.path.join(
                    upload_directory,
                    filename
                )

                photo.save(
                    absolute_path
                )

                student.photo = (
                    f"uploads/students/{filename}"
                )

            # ====================================================
            # ADD STUDENT
            # ====================================================

            db.session.add(
                student
            )

            db.session.flush()

            # ====================================================
            # ENROLLMENT ARRAYS
            # ====================================================

            academic_year_ids = (
                request.form.getlist(
                    "academic_year_id[]"
                )
            )

            program_ids = (
                request.form.getlist(
                    "program_id[]"
                )
            )

            class_ids = (
                request.form.getlist(
                    "class_id[]"
                )
            )

            section_ids = (
                request.form.getlist(
                    "section_id[]"
                )
            )

            enrollment_dates = (
                request.form.getlist(
                    "enrollment_date[]"
                )
            )

            enrollment_statuses = (
                request.form.getlist(
                    "enrollment_status[]"
                )
            )

            enrollment_notes = (
                request.form.getlist(
                    "enrollment_notes[]"
                )
            )

            # ====================================================
            # ENROLLMENT RECORDS
            # ====================================================

            enrollment_records = []

            max_enrollments = max(
                len(academic_year_ids),
                len(program_ids),
                len(class_ids),
                len(section_ids),
                len(enrollment_dates),
                len(enrollment_statuses),
                len(enrollment_notes),
                0
            )

            # ====================================================
            # ENROLLMENT STATUS
            # ====================================================

            allowed_enrollment_statuses = {
                "active",
                "completed",
                "transferred",
                "withdrawn",
                "suspended",
                "promoted",
            }

            # ====================================================
            # PROCESS ENROLLMENTS
            # ====================================================

            for index in range(
                max_enrollments
            ):

                academic_year_raw = (
                    _form_list_value(
                        academic_year_ids,
                        index
                    )
                )

                program_raw = (
                    _form_list_value(
                        program_ids,
                        index
                    )
                )

                class_raw = (
                    _form_list_value(
                        class_ids,
                        index
                    )
                )

                section_raw = (
                    _form_list_value(
                        section_ids,
                        index
                    )
                )

                enrollment_date_raw = (
                    _form_list_value(
                        enrollment_dates,
                        index
                    )
                )

                enrollment_status = (
                    _form_list_value(
                        enrollment_statuses,
                        index
                    )
                    or "active"
                )

                enrollment_note = (
                    _form_list_value(
                        enrollment_notes,
                        index
                    )
                )

                # ----------------------------------------------
                # EMPTY ROW
                # ----------------------------------------------

                if not (
                    academic_year_raw
                    or program_raw
                    or class_raw
                    or section_raw
                ):

                    continue

                # ----------------------------------------------
                # IDs
                # ----------------------------------------------

                if not academic_year_raw.isdigit():

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Academic year is required."
                    )

                if not program_raw.isdigit():

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Program is required."
                    )

                if not class_raw.isdigit():

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Class is required."
                    )

                academic_year_id = int(
                    academic_year_raw
                )

                program_id = int(
                    program_raw
                )

                class_id = int(
                    class_raw
                )

                section_id = None

                if section_raw.isdigit():

                    section_id = int(
                        section_raw
                    )

                # ----------------------------------------------
                # ACADEMIC YEAR
                # ----------------------------------------------

                academic_year = (
                    AcademicYear.query
                    .filter(
                        AcademicYear.id
                        == academic_year_id,

                        AcademicYear.institution_id
                        == institution_id
                    )
                    .first()
                )

                if not academic_year:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Invalid academic year."
                    )

                # ----------------------------------------------
                # PROGRAM
                # ----------------------------------------------

                program = (
                    Program.query
                    .filter(
                        Program.id
                        == program_id,

                        Program.institution_id
                        == institution_id,

                        or_(
                            Program.branch_id
                            == branch_id,

                            Program.branch_id.is_(None)
                        )
                    )
                    .first()
                )

                if not program:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Invalid program for this branch."
                    )

                # ----------------------------------------------
                # CLASS
                # ----------------------------------------------

                selected_class = (
                    Class.query
                    .filter(
                        Class.id
                        == class_id,

                        Class.institution_id
                        == institution_id,

                        Class.branch_id
                        == branch_id
                    )
                    .first()
                )

                if not selected_class:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Invalid class for this branch."
                    )

                # ----------------------------------------------
                # CLASS → PROGRAM
                # ----------------------------------------------

                class_program_id = getattr(
                    selected_class,
                    "program_id",
                    None
                )

                if (
                    class_program_id
                    and
                    class_program_id
                    != program_id
                ):

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Selected class does not "
                        "belong to selected program."
                    )

                # ----------------------------------------------
                # SECTION
                # ----------------------------------------------

                if section_id:

                    selected_section = (
                        Section.query
                        .filter(
                            Section.id
                            == section_id,

                            Section.institution_id
                            == institution_id,

                            Section.branch_id
                            == branch_id,

                            Section.class_id
                            == class_id
                        )
                        .first()
                    )

                    if not selected_section:

                        raise ValueError(
                            f"Enrollment #{index + 1}: "
                            "Invalid section for selected class."
                        )

                # ----------------------------------------------
                # ENROLLMENT STATUS
                # ----------------------------------------------

                if (
                    enrollment_status
                    not in allowed_enrollment_statuses
                ):

                    enrollment_status = (
                        "active"
                    )

                # ----------------------------------------------
                # DUPLICATE
                # ----------------------------------------------

                duplicate = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.student_id
                        == student.id,

                        StudentEnrollment.academic_year_id
                        == academic_year_id
                    )
                    .first()
                )

                if duplicate:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Student already has an "
                        "enrollment for this academic year."
                    )

                # ----------------------------------------------
                # DATE
                # ----------------------------------------------

                enrollment_date = (
                    _parse_date(
                        enrollment_date_raw,
                        default=date.today()
                    )
                )

                # ----------------------------------------------
                # ENROLLMENT NUMBER
                # ----------------------------------------------

                enrollment_no = (
                    _generate_enrollment_no(
                        admission_no,
                        index
                    )
                )

                # ----------------------------------------------
                # SAFETY CHECK
                # ----------------------------------------------

                existing_enrollment_no = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.institution_id
                        == institution_id,

                        StudentEnrollment.enrollment_no
                        == enrollment_no
                    )
                    .first()
                )

                if existing_enrollment_no:

                    enrollment_no = (
                        f"{admission_no}-"
                        f"E{index + 1:02d}-"
                        f"{secrets.token_hex(2).upper()}"
                    )

                # ----------------------------------------------
                # CREATE ENROLLMENT
                # ----------------------------------------------

                enrollment = StudentEnrollment(

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        branch_id
                    ),

                    student_id=(
                        student.id
                    ),

                    academic_year_id=(
                        academic_year_id
                    ),

                    program_id=(
                        program_id
                    ),

                    class_id=(
                        class_id
                    ),

                    section_id=(
                        section_id
                    ),

                    enrollment_no=(
                        enrollment_no
                    ),

                    enrollment_date=(
                        enrollment_date
                    ),

                    status=(
                        enrollment_status
                    ),

                    notes=(
                        enrollment_note
                        or None
                    ),
                )

                db.session.add(
                    enrollment
                )

                enrollment_records.append({
                    "enrollment": enrollment,
                    "academic_year": academic_year,
                    "program": program,
                    "index": index,
                })

            # ====================================================
            # REQUIRE ENROLLMENT
            # ====================================================

            if not enrollment_records:

                raise ValueError(
                    "At least one academic enrollment "
                    "is required."
                )

            db.session.flush()

            # ====================================================
            # AUTOMATIC REGISTRATION FEE
            # ====================================================

            first_record = (
                enrollment_records[0]
            )

            first_enrollment = (
                first_record["enrollment"]
            )

            first_academic_year = (
                first_record["academic_year"]
            )

            first_program = (
                first_record["program"]
            )

            registration_amount = (
                Decimal("5.00")
            )

            registration_charge = (
                StudentCharge(

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        branch_id
                    ),

                    student_id=(
                        student.id
                    ),

                    enrollment_id=(
                        first_enrollment.id
                    ),

                    academic_year_id=(
                        first_academic_year.id
                    ),

                    charge_type=(
                        "registration"
                    ),

                    charge_name=(
                        "Registration Fee"
                    ),

                    description=(
                        "Automatic registration fee"
                    ),

                    amount=(
                        registration_amount
                    ),

                    discount=(
                        Decimal("0.00")
                    ),

                    net_amount=(
                        registration_amount
                    ),

                    paid_amount=(
                        Decimal("0.00")
                    ),

                    balance=(
                        registration_amount
                    ),

                    due_date=(
                        date.today()
                    ),

                    status=(
                        "unpaid"
                    ),

                    created_by=(
                        getattr(
                            current_user,
                            "id",
                            None
                        )
                    ),
                )
            )

            db.session.add(
                registration_charge
            )

            # ====================================================
            # AUTOMATIC PROGRAM FEE
            # ====================================================

            program_price = _decimal(
                getattr(
                    first_program,
                    "price",
                    0
                )
            )

            if (
                program_price
                > Decimal("0.00")
            ):

                program_name = (
                    _clean(
                        getattr(
                            first_program,
                            "name",
                            ""
                        )
                    )
                    or "Program"
                )

                program_charge = (
                    StudentCharge(

                        institution_id=(
                            institution_id
                        ),

                        branch_id=(
                            branch_id
                        ),

                        student_id=(
                            student.id
                        ),

                        enrollment_id=(
                            first_enrollment.id
                        ),

                        academic_year_id=(
                            first_academic_year.id
                        ),

                        charge_type=(
                            "program_fee"
                        ),

                        charge_name=(
                            f"{program_name} Fee"
                        ),

                        description=(
                            "Automatic program fee"
                        ),

                        amount=(
                            program_price
                        ),

                        discount=(
                            Decimal("0.00")
                        ),

                        net_amount=(
                            program_price
                        ),

                        paid_amount=(
                            Decimal("0.00")
                        ),

                        balance=(
                            program_price
                        ),

                        due_date=(
                            date.today()
                        ),

                        status=(
                            "unpaid"
                        ),

                        created_by=(
                            getattr(
                                current_user,
                                "id",
                                None
                            )
                        ),
                    )
                )

                db.session.add(
                    program_charge
                )

            # ====================================================
            # MANUAL CHARGES
            # ====================================================

            charge_types = (
                request.form.getlist(
                    "charge_type[]"
                )
            )

            charge_names = (
                request.form.getlist(
                    "charge_name[]"
                )
            )

            charge_amounts = (
                request.form.getlist(
                    "charge_amount[]"
                )
            )

            charge_discounts = (
                request.form.getlist(
                    "charge_discount[]"
                )
            )

            charge_paid_amounts = (
                request.form.getlist(
                    "charge_paid_amount[]"
                )
            )

            charge_due_dates = (
                request.form.getlist(
                    "charge_due_date[]"
                )
            )

            charge_enrollment_values = (
                request.form.getlist(
                    "charge_enrollment[]"
                )
            )

            # Compatibility with old template

            if not charge_enrollment_values:

                charge_enrollment_values = (
                    request.form.getlist(
                        "charge_enrollment_index[]"
                    )
                )

            charge_descriptions = (
                request.form.getlist(
                    "charge_description[]"
                )
            )

            allowed_charge_types = {
                "registration",
                "program_fee",
                "tuition",
                "exam",
                "admission",
                "id_card",
                "uniform",
                "books",
                "transport",
                "laboratory",
                "library",
                "certificate",
                "other",
            }

            max_charges = max(
                len(charge_types),
                len(charge_names),
                len(charge_amounts),
                len(charge_discounts),
                len(charge_paid_amounts),
                len(charge_due_dates),
                len(charge_enrollment_values),
                len(charge_descriptions),
                0
            )

            for index in range(
                max_charges
            ):

                charge_type = (
                    _form_list_value(
                        charge_types,
                        index
                    )
                    .lower()
                )

                charge_name = (
                    _form_list_value(
                        charge_names,
                        index
                    )
                )

                amount = _decimal(
                    _form_list_value(
                        charge_amounts,
                        index
                    )
                )

                discount = _decimal(
                    _form_list_value(
                        charge_discounts,
                        index
                    )
                )

                paid_amount = _decimal(
                    _form_list_value(
                        charge_paid_amounts,
                        index
                    )
                )

                due_date = _parse_date(
                    _form_list_value(
                        charge_due_dates,
                        index
                    ),
                    default=date.today()
                )

                description = (
                    _form_list_value(
                        charge_descriptions,
                        index
                    )
                )

                enrollment_index_raw = (
                    _form_list_value(
                        charge_enrollment_values,
                        index
                    )
                )

                enrollment_index = 0

                if enrollment_index_raw.isdigit():

                    enrollment_index = int(
                        enrollment_index_raw
                    )

                # ----------------------------------------------
                # EMPTY ROW
                # ----------------------------------------------

                if not (
                    charge_type
                    or charge_name
                    or amount
                ):

                    continue

                # ----------------------------------------------
                # AUTO CHARGES
                # ----------------------------------------------

                if charge_type in {
                    "registration",
                    "program_fee",
                }:

                    continue

                # ----------------------------------------------
                # VALID TYPE
                # ----------------------------------------------

                if (
                    charge_type
                    not in allowed_charge_types
                ):

                    charge_type = "other"

                # ----------------------------------------------
                # NORMALIZE MONEY
                # ----------------------------------------------

                if amount < 0:

                    raise ValueError(
                        f"Charge #{index + 1}: "
                        "Amount cannot be negative."
                    )

                if discount < 0:

                    discount = Decimal(
                        "0.00"
                    )

                if paid_amount < 0:

                    paid_amount = Decimal(
                        "0.00"
                    )

                if discount > amount:

                    discount = amount

                net_amount = (
                    amount - discount
                )

                if paid_amount > net_amount:

                    paid_amount = net_amount

                balance = (
                    net_amount
                    - paid_amount
                )

                # ----------------------------------------------
                # STATUS
                # ----------------------------------------------

                if balance <= 0:

                    charge_status = "paid"

                    balance = Decimal(
                        "0.00"
                    )

                elif paid_amount > 0:

                    charge_status = "partial"

                else:

                    charge_status = "unpaid"

                # ----------------------------------------------
                # ENROLLMENT INDEX
                # ----------------------------------------------

                if (
                    enrollment_index < 0
                    or
                    enrollment_index
                    >= len(
                        enrollment_records
                    )
                ):

                    enrollment_index = 0

                charge_enrollment_record = (
                    enrollment_records[
                        enrollment_index
                    ]
                )

                charge_enrollment = (
                    charge_enrollment_record[
                        "enrollment"
                    ]
                )

                charge_academic_year = (
                    charge_enrollment_record[
                        "academic_year"
                    ]
                )

                # ----------------------------------------------
                # NAME
                # ----------------------------------------------

                if not charge_name:

                    charge_name = (
                        charge_type
                        .replace(
                            "_",
                            " "
                        )
                        .title()
                    )

                # ----------------------------------------------
                # CREATE
                # ----------------------------------------------

                manual_charge = (
                    StudentCharge(

                        institution_id=(
                            institution_id
                        ),

                        branch_id=(
                            branch_id
                        ),

                        student_id=(
                            student.id
                        ),

                        enrollment_id=(
                            charge_enrollment.id
                        ),

                        academic_year_id=(
                            charge_academic_year.id
                        ),

                        charge_type=(
                            charge_type
                        ),

                        charge_name=(
                            charge_name
                        ),

                        description=(
                            description
                            or None
                        ),

                        amount=(
                            amount
                        ),

                        discount=(
                            discount
                        ),

                        net_amount=(
                            net_amount
                        ),

                        paid_amount=(
                            paid_amount
                        ),

                        balance=(
                            balance
                        ),

                        due_date=(
                            due_date
                        ),

                        status=(
                            charge_status
                        ),

                        created_by=(
                            getattr(
                                current_user,
                                "id",
                                None
                            )
                        ),
                    )
                )

                db.session.add(
                    manual_charge
                )

            # ====================================================
            # FINAL FLUSH
            # ====================================================

            db.session.flush()

            # ====================================================
            # COMMIT
            # ====================================================

            db.session.commit()

            # ====================================================
            # SAVE GENERATED LOGIN DETAILS
            # ====================================================

            session[
                "new_student_credentials"
            ] = {

                "student_id": student.id,

                "full_name": student.full_name,

                "admission_no": (
                    student.admission_no
                ),

                "roll_no": (
                    student.roll_no
                ),

                "username": (
                    student.username
                ),

                "email": (
                    student.email
                ),

                "password": (
                    generated_password
                ),
            }

            # ====================================================
            # SUCCESS
            # ====================================================

            flash(
                (
                    f"Student "
                    f"{student.full_name} "
                    f"was added successfully."
                ),
                "success"
            )

            # ====================================================
            # REDIRECT
            # ====================================================

            if (
                "main.view_student"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.view_student",
                        student_id=student.id
                    )
                )

            if (
                "main.all_students"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.all_students"
                    )
                )

            return redirect(
                url_for(
                    "main.dashboard"
                )
            )

        # ========================================================
        # VALIDATION ERROR
        # ========================================================

        except ValueError as exc:

            db.session.rollback()

            current_app.logger.warning(
                "Add student validation error: %s",
                exc
            )

            flash(
                str(exc),
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_student"
                )
            )

        # ========================================================
        # DATABASE / UNEXPECTED ERROR
        # ========================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Unexpected error while adding student"
            )

            flash(
                (
                    "Unable to add student. "
                    f"Error: {exc}"
                ),
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_student"
                )
            )

    # ========================================================
    # GET
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    if current_user.role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = []

        if current_institution_id:

            current_institution_for_list = (
                Institution.query
                .filter(
                    Institution.id
                    == current_institution_id
                )
                .first()
            )

            if current_institution_for_list:

                institutions = [
                    current_institution_for_list
                ]

    # ========================================================
    # BRANCHES
    # ========================================================

    if (
        current_user.role
        == "branch_admin"
    ):

        branches = (
            Branch.query
            .filter(
                Branch.id
                == current_branch_id,

                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif (
        current_user.role
        == "school_admin"
    ):

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    # ========================================================
    # CURRENT INSTITUTION
    # ========================================================

    current_institution = None

    if current_institution_id:

        current_institution = (
            Institution.query
            .filter(
                Institution.id
                == current_institution_id
            )
            .first()
        )

    # ========================================================
    # CURRENT BRANCH
    # ========================================================

    current_branch = None

    if current_branch_id:

        current_branch = (
            Branch.query
            .filter(
                Branch.id
                == current_branch_id
            )
            .first()
        )

    # ========================================================
    # DEFAULT BRANCH
    # ========================================================

    default_branch_id = (
        current_branch_id
        if current_user.role
        == "branch_admin"
        else None
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    if (
        current_institution_id
        and default_branch_id
    ):

        programs = (
            Program.query
            .filter(
                Program.institution_id
                == current_institution_id,

                or_(
                    Program.branch_id
                    == default_branch_id,

                    Program.branch_id.is_(None)
                )
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        programs = (
            Program.query
            .filter(
                Program.institution_id
                == current_institution_id
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    else:

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    if (
        current_institution_id
        and default_branch_id
    ):

        classes = (
            Class.query
            .filter(
                Class.institution_id
                == current_institution_id,

                Class.branch_id
                == default_branch_id
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        classes = (
            Class.query
            .filter(
                Class.institution_id
                == current_institution_id
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    else:

        classes = (
            Class.query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    if (
        current_institution_id
        and default_branch_id
    ):

        sections = (
            Section.query
            .filter(
                Section.institution_id
                == current_institution_id,

                Section.branch_id
                == default_branch_id
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        sections = (
            Section.query
            .filter(
                Section.institution_id
                == current_institution_id
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    else:

        sections = (
            Section.query
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    if current_institution_id:

        academic_years = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == current_institution_id
            )
            .order_by(
                AcademicYear.is_current.desc(),
                AcademicYear.id.desc()
            )
            .all()
        )

    else:

        academic_years = (
            AcademicYear.query
            .order_by(
                AcademicYear.is_current.desc(),
                AcademicYear.id.desc()
            )
            .all()
        )

    # ========================================================
    # COUNTRIES
    # ========================================================

    try:

        all_countries = (
            get_all_countries()
        )

    except Exception:

        all_countries = []

    # ========================================================
    # TODAY
    # ========================================================

    today = (
        date.today()
        .isoformat()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/students/add_student.html",
        user=current_user,

        institutions=institutions,

        branches=branches,

        programs=programs,

        classes=classes,

        sections=sections,

        academic_years=academic_years,

        all_countries=all_countries,

        current_institution=(
            current_institution
        ),

        current_branch=(
            current_branch
        ),

        current_institution_id=(
            current_institution_id
        ),

        current_branch_id=(
            current_branch_id
        ),

        default_branch_id=(
            default_branch_id
        ),

        today=today,

        registration_fee=(
            Decimal("5.00")
        ),
    )





# ============================================================
# VIEW STUDENT
# ============================================================

@bp.route("/students/<int:student_id>", methods=["GET"])
@login_required
def view_student(student_id):
    """
    View a single student profile.

    Access:
        - superadmin   -> all students
        - school_admin -> students belonging to their institution
        - branch_admin -> students belonging to their institution + branch

    Template:
        backend/pages/students/view_student.html
    """

    # ============================================================
    # IMPORTS
    # ============================================================

    from flask import abort, render_template, flash, redirect, url_for
    from sqlalchemy.orm import joinedload

    # ============================================================
    # ALLOWED ROLES
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_user.role not in allowed_roles:
        abort(403)

    # ============================================================
    # BASIC USER SCOPE VALIDATION
    # ============================================================

    if current_user.role == "school_admin":
        if not current_user.institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )
            return redirect(url_for("main.dashboard"))

    if current_user.role == "branch_admin":
        if (
            not current_user.institution_id
            or not current_user.branch_id
        ):
            flash(
                "Your account is not assigned to an institution and branch.",
                "danger"
            )
            return redirect(url_for("main.dashboard"))

    # ============================================================
    # GET STUDENT
    #
    # Eager-load the relationships needed by view_student.html
    # ============================================================

    student_query = (
        Student.query
        .options(
            joinedload(Student.institution),
            joinedload(Student.branch),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.academic_year),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.program),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.class_),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.section),

            joinedload(Student.charges)
                .joinedload(StudentCharge.academic_year),

            joinedload(Student.charges)
                .joinedload(StudentCharge.enrollment)
        )
        .filter(
            Student.id == student_id,
            Student.role == "student"
        )
    )

    # ============================================================
    # ROLE-BASED SECURITY SCOPE
    # ============================================================

    if current_user.role == "school_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id
        )

    elif current_user.role == "branch_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id,
            Student.branch_id == current_user.branch_id
        )

    # superadmin:
    # no institution/branch restriction

    # ============================================================
    # FETCH STUDENT
    # ============================================================

    student = student_query.first()

    if not student:
        abort(404)

    # ============================================================
    # SORT ENROLLMENTS
    # ============================================================

    enrollments = list(student.enrollments or [])

    enrollments.sort(
        key=lambda e: (
            e.enrollment_date is None,
            e.enrollment_date or date.min,
            e.id or 0
        ),
        reverse=True
    )

    # ============================================================
    # SORT CHARGES
    # ============================================================

    charges = list(student.charges or [])

    charges.sort(
        key=lambda c: (
            c.due_date is None,
            c.due_date or date.min,
            c.id or 0
        )
    )

    # ============================================================
    # ENROLLMENT STATISTICS
    # ============================================================

    total_enrollments = len(enrollments)

    active_enrollments = [
        enrollment
        for enrollment in enrollments
        if enrollment.status == "active"
    ]

    active_enrollment_count = len(active_enrollments)

    # ============================================================
    # PROGRAM / COURSE COUNT
    #
    # Count unique programs from enrollments
    # ============================================================

    program_ids = {
        enrollment.program_id
        for enrollment in enrollments
        if enrollment.program_id is not None
    }

    total_programs = len(program_ids)

    # ============================================================
    # FINANCIAL CALCULATIONS
    #
    # Use Decimal for money calculations.
    # ============================================================

    total_amount = Decimal("0.00")
    total_discount = Decimal("0.00")
    total_net_amount = Decimal("0.00")
    total_paid_amount = Decimal("0.00")
    total_balance = Decimal("0.00")

    for charge in charges:

        amount = (
            charge.amount
            if charge.amount is not None
            else Decimal("0.00")
        )

        discount = (
            charge.discount
            if charge.discount is not None
            else Decimal("0.00")
        )

        net_amount = (
            charge.net_amount
            if charge.net_amount is not None
            else amount - discount
        )

        paid_amount = (
            charge.paid_amount
            if charge.paid_amount is not None
            else Decimal("0.00")
        )

        balance = (
            charge.balance
            if charge.balance is not None
            else net_amount - paid_amount
        )

        total_amount += Decimal(str(amount))
        total_discount += Decimal(str(discount))
        total_net_amount += Decimal(str(net_amount))
        total_paid_amount += Decimal(str(paid_amount))
        total_balance += Decimal(str(balance))

    # ============================================================
    # CHARGE STATISTICS
    # ============================================================

    total_charges = len(charges)

    paid_charges = sum(
        1
        for charge in charges
        if charge.status == "paid"
    )

    partial_charges = sum(
        1
        for charge in charges
        if charge.status == "partial"
    )

    unpaid_charges = sum(
        1
        for charge in charges
        if charge.status == "unpaid"
    )

    overdue_charges = sum(
        1
        for charge in charges
        if charge.status == "overdue"
    )

    cancelled_charges = sum(
        1
        for charge in charges
        if charge.status == "cancelled"
    )

    # ============================================================
    # CURRENT / ACTIVE ENROLLMENT
    # ============================================================

    current_enrollment = None

    for enrollment in enrollments:
        if enrollment.status == "active":
            current_enrollment = enrollment
            break

    # If there is no active enrollment, use latest enrollment
    if current_enrollment is None and enrollments:
        current_enrollment = enrollments[0]

    # ============================================================
    # CURRENT PROGRAM / CLASS / SECTION
    # ============================================================

    current_program = None
    current_class = None
    current_section = None
    current_academic_year = None

    if current_enrollment:

        current_program = current_enrollment.program

        current_class = current_enrollment.class_

        current_section = current_enrollment.section

        current_academic_year = current_enrollment.academic_year

    # ============================================================
    # INSTITUTIONS
    #
    # Useful if the template displays institution information.
    # ============================================================

    institution = student.institution
    branch = student.branch

    # ============================================================
    # TODAY
    # ============================================================

    today = date.today()

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(
        "backend/pages/students/view_student.html",

        # --------------------------------------------------------
        # Student
        # --------------------------------------------------------

        student=student,
        user=current_user,

        # --------------------------------------------------------
        # Institution / Branch
        # --------------------------------------------------------

        institution=institution,
        branch=branch,

        # --------------------------------------------------------
        # Academic data
        # --------------------------------------------------------

        enrollments=enrollments,
        current_enrollment=current_enrollment,
        current_program=current_program,
        current_class=current_class,
        current_section=current_section,
        current_academic_year=current_academic_year,

        # --------------------------------------------------------
        # Charges
        # --------------------------------------------------------

        charges=charges,

        # --------------------------------------------------------
        # Enrollment statistics
        # --------------------------------------------------------

        total_enrollments=total_enrollments,
        active_enrollment_count=active_enrollment_count,
        total_programs=total_programs,

        # --------------------------------------------------------
        # Financial statistics
        # --------------------------------------------------------

        total_charges=total_charges,
        total_amount=total_amount,
        total_discount=total_discount,
        total_net_amount=total_net_amount,
        total_paid_amount=total_paid_amount,
        total_balance=total_balance,

        # --------------------------------------------------------
        # Charge status statistics
        # --------------------------------------------------------

        paid_charges=paid_charges,
        partial_charges=partial_charges,
        unpaid_charges=unpaid_charges,
        overdue_charges=overdue_charges,
        cancelled_charges=cancelled_charges,

        # --------------------------------------------------------
        # Current user
        # --------------------------------------------------------

        current_role=current_user.role,
        current_institution_id=current_user.institution_id,
        current_branch_id=current_user.branch_id,

        # --------------------------------------------------------
        # Date
        # --------------------------------------------------------

        today=today,
    )



# ============================================================
# EDIT STUDENT
# ============================================================

@bp.route("/edit-student/<int:student_id>", methods=["GET", "POST"])
@login_required
def edit_student(student_id):
    """
    EDIT STUDENT
    ============================================================
    Compatible with:

        Student
        StudentEnrollment
        StudentCharge
        Institution
        Branch
        Program
        Class
        Section
        AcademicYear

    IMPORTANT
    ------------------------------------------------------------
    Student DOES NOT have:

        country
        phone_country
        state

    Those fields may exist in the HTML form, but they are
    intentionally NOT saved to Student.

    Student statuses:
        active
        inactive
        graduated
        transferred
        suspended
        withdrawn

    Enrollment statuses:
        active
        completed
        transferred
        withdrawn
        suspended
        promoted

    Charge types:
        registration
        program_fee
        tuition
        exam
        admission
        id_card
        uniform
        books
        transport
        laboratory
        library
        certificate
        other
    """

    # ============================================================
    # IMPORTS
    # ============================================================

    import os
    from datetime import date, datetime
    from decimal import Decimal, InvalidOperation

    from flask import (
        current_app,
        flash,
        redirect,
        render_template,
        request,
        url_for,
    )

    from flask_login import current_user, login_required
    from sqlalchemy import or_
    from werkzeug.utils import secure_filename

    # ============================================================
    # ROLE SECURITY
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_user_role = getattr(
        current_user,
        "role",
        None,
    )

    if current_user_role not in allowed_roles:
        flash(
            "You do not have permission to edit students.",
            "danger",
        )
        return redirect(
            url_for("main.dashboard")
        )

    # ============================================================
    # HELPERS
    # ============================================================

    def _clean(value):
        if value is None:
            return ""

        return str(value).strip()

    def _int_or_none(value):
        value = _clean(value)

        if not value:
            return None

        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _decimal(
        value,
        default=Decimal("0.00"),
    ):
        value = _clean(value)

        if not value:
            return default

        try:
            return Decimal(
                value
            ).quantize(
                Decimal("0.01")
            )
        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):
            return default

    def _parse_date(value):
        value = _clean(value)

        if not value:
            return None

        try:
            return datetime.strptime(
                value,
                "%Y-%m-%d",
            ).date()

        except ValueError:
            return None

    def _valid_student_status(value):
        return value in {
            "active",
            "inactive",
            "graduated",
            "transferred",
            "suspended",
            "withdrawn",
        }

    valid_enrollment_statuses = {
        "active",
        "completed",
        "transferred",
        "withdrawn",
        "suspended",
        "promoted",
    }

    valid_charge_types = {
        "registration",
        "program_fee",
        "tuition",
        "exam",
        "admission",
        "id_card",
        "uniform",
        "books",
        "transport",
        "laboratory",
        "library",
        "certificate",
        "other",
    }

    # ============================================================
    # CURRENT USER SCOPE
    # ============================================================

    current_user_institution_id = getattr(
        current_user,
        "institution_id",
        None,
    )

    current_user_branch_id = getattr(
        current_user,
        "branch_id",
        None,
    )

    # ============================================================
    # GET STUDENT
    # ============================================================

    student_query = (
        Student.query
        .filter(
            Student.id == student_id,
            Student.role == "student",
        )
    )

    # ============================================================
    # STUDENT SECURITY SCOPE
    # ============================================================

    if current_user_role == "school_admin":

        if not current_user_institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger",
            )
            return redirect(
                url_for("main.all_students")
            )

        student_query = student_query.filter(
            Student.institution_id
            == current_user_institution_id
        )

    elif current_user_role == "branch_admin":

        if (
            not current_user_institution_id
            or not current_user_branch_id
        ):
            flash(
                "Your account is not assigned to a valid institution and branch.",
                "danger",
            )
            return redirect(
                url_for("main.all_students")
            )

        student_query = student_query.filter(
            Student.institution_id
            == current_user_institution_id,
            Student.branch_id
            == current_user_branch_id,
        )

    student = (
        student_query
        .first_or_404()
    )

    # ============================================================
    # POST
    # ============================================================

    if request.method == "POST":

        uploaded_photo_path = None

        try:

            # ====================================================
            # BASIC STUDENT INFORMATION
            # ====================================================

            full_name = _clean(
                request.form.get(
                    "full_name"
                )
            )

            email = _clean(
                request.form.get(
                    "email"
                )
            ).lower()

            gender = _clean(
                request.form.get(
                    "gender"
                )
            )

            date_of_birth = _parse_date(
                request.form.get(
                    "date_of_birth"
                )
            )

            place_of_birth = _clean(
                request.form.get(
                    "place_of_birth"
                )
            )

            nationality = _clean(
                request.form.get(
                    "nationality"
                )
            )

            phone = _clean(
                request.form.get(
                    "phone"
                )
            )

            city = _clean(
                request.form.get(
                    "city"
                )
            )

            address = _clean(
                request.form.get(
                    "address"
                )
            )

            status = _clean(
                request.form.get(
                    "status"
                )
            ).lower()

            notes = _clean(
                request.form.get(
                    "notes"
                )
            )

            # ====================================================
            # FORM FIELDS THAT ARE NOT STUDENT COLUMNS
            # ====================================================
            #
            # These are intentionally read only if the template
            # sends them. They are NEVER assigned to Student.
            #

            _country_form = _clean(
                request.form.get(
                    "country"
                )
            )

            _phone_country_form = _clean(
                request.form.get(
                    "phone_country"
                )
            )

            _state_form = _clean(
                request.form.get(
                    "state"
                )
            )

            _parent_id_form = _clean(
                request.form.get(
                    "parent_id"
                )
            )

            # ====================================================
            # VALIDATE NAME
            # ====================================================

            if not full_name:
                raise ValueError(
                    "Student full name is required."
                )

            # ====================================================
            # VALIDATE STUDENT STATUS
            # ====================================================

            if not _valid_student_status(
                status
            ):
                raise ValueError(
                    "Invalid student status."
                )

            # ====================================================
            # PARENT / GUARDIAN
            # ====================================================

            parent_name = _clean(
                request.form.get(
                    "parent_name"
                )
            )

            relationship_to_student = _clean(
                request.form.get(
                    "relationship_to_student"
                )
            )

            parent_phone = _clean(
                request.form.get(
                    "parent_phone"
                )
            )

            parent_email = _clean(
                request.form.get(
                    "parent_email"
                )
            ).lower()

            parent_address = _clean(
                request.form.get(
                    "parent_address"
                )
            )

            # ====================================================
            # INSTITUTION / BRANCH
            # ====================================================

            submitted_institution_id = (
                _int_or_none(
                    request.form.get(
                        "institution_id"
                    )
                )
            )

            submitted_branch_id = (
                _int_or_none(
                    request.form.get(
                        "branch_id"
                    )
                )
            )

            # ====================================================
            # DETERMINE NEW INSTITUTION
            # ====================================================

            if current_user_role == "superadmin":

                if not submitted_institution_id:
                    raise ValueError(
                        "Please select an institution."
                    )

                new_institution_id = (
                    submitted_institution_id
                )

            else:

                if not current_user_institution_id:
                    raise ValueError(
                        "Your account is not assigned to an institution."
                    )

                new_institution_id = (
                    current_user_institution_id
                )

            # ====================================================
            # DETERMINE NEW BRANCH
            # ====================================================

            if current_user_role == "branch_admin":

                if not current_user_branch_id:
                    raise ValueError(
                        "Your account is not assigned to a branch."
                    )

                new_branch_id = (
                    current_user_branch_id
                )

            else:

                if not submitted_branch_id:
                    raise ValueError(
                        "Please select a branch."
                    )

                new_branch_id = (
                    submitted_branch_id
                )

            # ====================================================
            # VERIFY INSTITUTION
            # ====================================================

            institution = (
                Institution.query
                .filter(
                    Institution.id
                    == new_institution_id
                )
                .first()
            )

            if not institution:
                raise ValueError(
                    "Selected institution was not found."
                )

            # ====================================================
            # VERIFY BRANCH
            # ============================================================

            branch = (
                Branch.query
                .filter(
                    Branch.id
                    == new_branch_id,
                    Branch.institution_id
                    == new_institution_id,
                )
                .first()
            )

            if not branch:
                raise ValueError(
                    "Selected branch does not belong to the selected institution."
                )

            # ====================================================
            # ROLE-SPECIFIC BRANCH SECURITY
            # ============================================================

            if current_user_role == "school_admin":

                if (
                    new_institution_id
                    != current_user_institution_id
                ):
                    raise ValueError(
                        "You cannot move a student outside your institution."
                    )

            elif current_user_role == "branch_admin":

                if (
                    new_institution_id
                    != current_user_institution_id
                    or new_branch_id
                    != current_user_branch_id
                ):
                    raise ValueError(
                        "You cannot move a student outside your branch."
                    )

            # ====================================================
            # EMAIL DUPLICATE
            # ============================================================

            if email:

                duplicate_email = (
                    Student.query
                    .filter(
                        Student.email == email,
                        Student.id != student.id,
                    )
                    .first()
                )

                if duplicate_email:
                    raise ValueError(
                        "This email address is already used by another student."
                    )

            # ====================================================
            # UPDATE STUDENT
            # ============================================================

            student.institution_id = (
                new_institution_id
            )

            student.branch_id = (
                new_branch_id
            )

            student.full_name = (
                full_name
            )

            student.email = (
                email or None
            )

            student.gender = (
                gender or None
            )

            student.date_of_birth = (
                date_of_birth
            )

            student.place_of_birth = (
                place_of_birth or None
            )

            student.nationality = (
                nationality or None
            )

            student.phone = (
                phone or None
            )

            student.city = (
                city or None
            )

            student.address = (
                address or None
            )

            student.parent_name = (
                parent_name or None
            )

            student.relationship_to_student = (
                relationship_to_student or None
            )

            student.parent_phone = (
                parent_phone or None
            )

            student.parent_email = (
                parent_email or None
            )

            student.parent_address = (
                parent_address or None
            )

            student.status = (
                status
            )

            student.is_active = (
                status == "active"
            )

            student.notes = (
                notes or None
            )

            # ====================================================
            # PHOTO UPLOAD
            # ====================================================

            photo_file = request.files.get(
                "photo"
            )

            if (
                photo_file
                and photo_file.filename
            ):

                original_filename = secure_filename(
                    photo_file.filename
                )

                if not original_filename:
                    raise ValueError(
                        "Invalid photo filename."
                    )

                extension = ""

                if "." in original_filename:
                    extension = (
                        original_filename
                        .rsplit(".", 1)[1]
                        .lower()
                    )

                allowed_extensions = {
                    "jpg",
                    "jpeg",
                    "png",
                    "webp",
                }

                if extension not in allowed_extensions:
                    raise ValueError(
                        "Invalid photo format. "
                        "Use JPG, JPEG, PNG or WebP."
                    )

                upload_folder = os.path.join(
                    current_app.root_path,
                    "static",
                    "uploads",
                    "students",
                )

                os.makedirs(
                    upload_folder,
                    exist_ok=True,
                )

                unique_filename = (
                    f"student_{student.id}_"
                    f"{int(datetime.utcnow().timestamp())}_"
                    f"{os.urandom(4).hex()}."
                    f"{extension}"
                )

                absolute_photo_path = os.path.join(
                    upload_folder,
                    unique_filename,
                )

                photo_file.save(
                    absolute_photo_path
                )

                uploaded_photo_path = (
                    absolute_photo_path
                )

                student.photo = (
                    "uploads/students/"
                    + unique_filename
                )

            # ====================================================
            # ENROLLMENT ARRAYS
            # ====================================================

            existing_enrollment_ids = (
                request.form.getlist(
                    "existing_enrollment_id[]"
                )
            )

            academic_year_ids = (
                request.form.getlist(
                    "academic_year_id[]"
                )
            )

            program_ids = (
                request.form.getlist(
                    "program_id[]"
                )
            )

            class_ids = (
                request.form.getlist(
                    "class_id[]"
                )
            )

            section_ids = (
                request.form.getlist(
                    "section_id[]"
                )
            )

            enrollment_dates = (
                request.form.getlist(
                    "enrollment_date[]"
                )
            )

            enrollment_statuses = (
                request.form.getlist(
                    "enrollment_status[]"
                )
            )

            enrollment_notes = (
                request.form.getlist(
                    "enrollment_notes[]"
                )
            )

            # ====================================================
            # DETERMINE NUMBER OF ENROLLMENT ROWS
            # ====================================================

            max_enrollment_rows = max(
                len(existing_enrollment_ids),
                len(academic_year_ids),
                len(program_ids),
                len(class_ids),
                len(section_ids),
                len(enrollment_dates),
                len(enrollment_statuses),
                len(enrollment_notes),
                0,
            )

            # ====================================================
            # EXISTING ENROLLMENT MAP
            # ====================================================

            existing_enrollment_map = {
                enrollment.id: enrollment
                for enrollment
                in list(student.enrollments)
            }

            submitted_existing_enrollment_ids = set()

            # ====================================================
            # ENROLLMENT RECORDS
            # ====================================================

            enrollment_records = []

            # Maps:
            # row index -> enrollment object
            enrollment_by_row = {}

            # Maps:
            # old enrollment id -> enrollment object
            enrollment_by_old_id = {}

            # ====================================================
            # PROCESS ENROLLMENTS
            # ====================================================

            for index in range(
                max_enrollment_rows
            ):

                # ------------------------------------------------
                # SAFE ARRAY ACCESS
                # ------------------------------------------------

                existing_raw = (
                    existing_enrollment_ids[index]
                    if index
                    < len(existing_enrollment_ids)
                    else ""
                )

                academic_year_raw = (
                    academic_year_ids[index]
                    if index
                    < len(academic_year_ids)
                    else ""
                )

                program_raw = (
                    program_ids[index]
                    if index
                    < len(program_ids)
                    else ""
                )

                class_raw = (
                    class_ids[index]
                    if index
                    < len(class_ids)
                    else ""
                )

                section_raw = (
                    section_ids[index]
                    if index
                    < len(section_ids)
                    else ""
                )

                enrollment_date_raw = (
                    enrollment_dates[index]
                    if index
                    < len(enrollment_dates)
                    else ""
                )

                enrollment_status_raw = (
                    enrollment_statuses[index]
                    if index
                    < len(enrollment_statuses)
                    else "active"
                )

                enrollment_note_raw = (
                    enrollment_notes[index]
                    if index
                    < len(enrollment_notes)
                    else ""
                )

                # ------------------------------------------------
                # EXISTING ID
                # ------------------------------------------------

                existing_id = _int_or_none(
                    existing_raw
                )

                # ------------------------------------------------
                # EMPTY ROW
                # ------------------------------------------------

                if not any(
                    [
                        academic_year_raw,
                        program_raw,
                        class_raw,
                        section_raw,
                        enrollment_date_raw,
                        enrollment_note_raw,
                        existing_id,
                    ]
                ):
                    continue

                # ------------------------------------------------
                # REQUIRED FIELDS
                # ------------------------------------------------

                academic_year_id = _int_or_none(
                    academic_year_raw
                )

                program_id = _int_or_none(
                    program_raw
                )

                class_id = _int_or_none(
                    class_raw
                )

                section_id = _int_or_none(
                    section_raw
                )

                if not academic_year_id:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Academic Year is required."
                    )

                if not program_id:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Program is required."
                    )

                if not class_id:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Class is required."
                    )

                # ------------------------------------------------
                # DATE
                # ------------------------------------------------

                enrollment_date = (
                    _parse_date(
                        enrollment_date_raw
                    )
                    or date.today()
                )

                # ------------------------------------------------
                # STATUS
                # ------------------------------------------------

                enrollment_status = (
                    _clean(
                        enrollment_status_raw
                    )
                    or "active"
                ).lower()

                if (
                    enrollment_status
                    not in valid_enrollment_statuses
                ):
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Invalid enrollment status."
                    )

                enrollment_note = (
                    _clean(
                        enrollment_note_raw
                    )
                    or None
                )

                # =================================================
                # ACADEMIC YEAR VALIDATION
                # =================================================

                academic_year = (
                    AcademicYear.query
                    .filter(
                        AcademicYear.id
                        == academic_year_id,
                        AcademicYear.institution_id
                        == new_institution_id,
                    )
                    .first()
                )

                if not academic_year:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Academic Year does not belong to the selected institution."
                    )

                # =================================================
                # PROGRAM VALIDATION
                # =================================================

                program = (
                    Program.query
                    .filter(
                        Program.id
                        == program_id,
                        Program.institution_id
                        == new_institution_id,
                        or_(
                            Program.branch_id
                            == new_branch_id,
                            Program.branch_id.is_(None),
                        ),
                    )
                    .first()
                )

                if not program:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Program does not belong to the selected institution/branch."
                    )

                # =================================================
                # CLASS VALIDATION
                # =================================================

                selected_class = (
                    Class.query
                    .filter(
                        Class.id
                        == class_id,
                        Class.institution_id
                        == new_institution_id,
                        Class.branch_id
                        == new_branch_id,
                    )
                    .first()
                )

                if not selected_class:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Class does not belong to the selected branch."
                    )

                # =================================================
                # CLASS → PROGRAM VALIDATION
                # =================================================

                class_program_id = getattr(
                    selected_class,
                    "program_id",
                    None,
                )

                if (
                    class_program_id is not None
                    and class_program_id
                    != program.id
                ):
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Selected class does not belong to selected program."
                    )

                # =================================================
                # SECTION VALIDATION
                # =================================================

                section = None

                if section_id:

                    section = (
                        Section.query
                        .filter(
                            Section.id
                            == section_id,
                            Section.institution_id
                            == new_institution_id,
                            Section.branch_id
                            == new_branch_id,
                            Section.class_id
                            == class_id,
                        )
                        .first()
                    )

                    if not section:
                        raise ValueError(
                            f"Enrollment row {index + 1}: "
                            "Selected section does not belong to selected class."
                        )

                # =================================================
                # EXISTING ENROLLMENT
                # =================================================

                enrollment = None

                if existing_id:

                    enrollment = (
                        existing_enrollment_map
                        .get(existing_id)
                    )

                    if not enrollment:
                        raise ValueError(
                            f"Enrollment row {index + 1}: "
                            "Invalid existing enrollment."
                        )

                    submitted_existing_enrollment_ids.add(
                        existing_id
                    )

                # =================================================
                # DUPLICATE ACADEMIC YEAR
                # =================================================

                duplicate_query = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.student_id
                        == student.id,
                        StudentEnrollment.academic_year_id
                        == academic_year.id,
                    )
                )

                if enrollment:
                    duplicate_query = (
                        duplicate_query
                        .filter(
                            StudentEnrollment.id
                            != enrollment.id
                        )
                    )

                duplicate_enrollment = (
                    duplicate_query.first()
                )

                if duplicate_enrollment:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "This student already has another enrollment for the selected academic year."
                    )

                # =================================================
                # UPDATE EXISTING
                # =================================================

                if enrollment:

                    enrollment.institution_id = (
                        new_institution_id
                    )

                    enrollment.branch_id = (
                        new_branch_id
                    )

                    enrollment.student_id = (
                        student.id
                    )

                    enrollment.academic_year_id = (
                        academic_year.id
                    )

                    enrollment.program_id = (
                        program.id
                    )

                    enrollment.class_id = (
                        selected_class.id
                    )

                    enrollment.section_id = (
                        section.id
                        if section
                        else None
                    )

                    enrollment.enrollment_date = (
                        enrollment_date
                    )

                    enrollment.status = (
                        enrollment_status
                    )

                    enrollment.notes = (
                        enrollment_note
                    )

                # =================================================
                # CREATE NEW
                # =================================================

                else:

                    # --------------------------------------------
                    # Generate a safer enrollment number
                    # --------------------------------------------

                    base_enrollment_no = (
                        f"{student.admission_no}-E"
                    )

                    enrollment_no = (
                        base_enrollment_no
                        + str(index + 1)
                    )

                    # --------------------------------------------
                    # Avoid duplicate enrollment number
                    # --------------------------------------------

                    counter = 1

                    while (
                        StudentEnrollment.query
                        .filter(
                            StudentEnrollment.institution_id
                            == new_institution_id,
                            StudentEnrollment.enrollment_no
                            == enrollment_no,
                        )
                        .first()
                    ):

                        counter += 1

                        enrollment_no = (
                            f"{base_enrollment_no}"
                            f"{index + 1}-{counter}"
                        )

                    enrollment = StudentEnrollment(
                        institution_id=(
                            new_institution_id
                        ),
                        branch_id=(
                            new_branch_id
                        ),
                        student_id=(
                            student.id
                        ),
                        academic_year_id=(
                            academic_year.id
                        ),
                        program_id=(
                            program.id
                        ),
                        class_id=(
                            selected_class.id
                        ),
                        section_id=(
                            section.id
                            if section
                            else None
                        ),
                        enrollment_no=(
                            enrollment_no
                        ),
                        enrollment_date=(
                            enrollment_date
                        ),
                        status=(
                            enrollment_status
                        ),
                        notes=(
                            enrollment_note
                        ),
                    )

                    db.session.add(
                        enrollment
                    )

                # ------------------------------------------------
                # Keep mapping
                # ------------------------------------------------

                enrollment_by_row[
                    index
                ] = enrollment

                if existing_id:
                    enrollment_by_old_id[
                        existing_id
                    ] = enrollment

                enrollment_records.append(
                    {
                        "row_index": index,
                        "enrollment": enrollment,
                        "academic_year": academic_year,
                        "program": program,
                        "class": selected_class,
                        "section": section,
                    }
                )

            # ====================================================
            # REQUIRE ENROLLMENT
            # ====================================================

            if not enrollment_records:
                raise ValueError(
                    "Student must have at least one enrollment."
                )

            # ====================================================
            # FLUSH
            # ====================================================

            db.session.flush()

            # ====================================================
            # DELETE REMOVED ENROLLMENTS
            # ====================================================
            #
            # Charges use SET NULL, but before deletion we
            # explicitly detach them to avoid stale references.
            #

            for old_enrollment in list(
                student.enrollments
            ):

                if (
                    old_enrollment.id
                    not in submitted_existing_enrollment_ids
                    and old_enrollment.id
                    not in enrollment_by_old_id
                ):

                    # --------------------------------------------
                    # Detach charges
                    # --------------------------------------------

                    for charge in list(
                        old_enrollment.charges
                    ):
                        charge.enrollment_id = None

                        # If possible, attach to first enrollment.
                        if enrollment_records:
                            replacement = (
                                enrollment_records[0]
                                ["enrollment"]
                            )

                            charge.enrollment_id = (
                                replacement.id
                            )

                            charge.academic_year_id = (
                                replacement.academic_year_id
                            )

                    db.session.delete(
                        old_enrollment
                    )

            # ====================================================
            # FLUSH AGAIN
            # ====================================================

            db.session.flush()

            # ====================================================
            # FIRST ENROLLMENT
            # ====================================================

            first_record = (
                enrollment_records[0]
            )

            first_enrollment = (
                first_record["enrollment"]
            )

            first_academic_year = (
                first_record["academic_year"]
            )

            first_program = (
                first_record["program"]
            )

            # ====================================================
            # CHARGE FORM ARRAYS
            # ====================================================

            existing_charge_ids = (
                request.form.getlist(
                    "existing_charge_id[]"
                )
            )

            charge_types = (
                request.form.getlist(
                    "charge_type[]"
                )
            )

            charge_names = (
                request.form.getlist(
                    "charge_name[]"
                )
            )

            charge_amounts = (
                request.form.getlist(
                    "charge_amount[]"
                )
            )

            charge_discounts = (
                request.form.getlist(
                    "charge_discount[]"
                )
            )

            # ----------------------------------------------------
            # Support BOTH names:
            #
            # charge_paid[]
            # charge_paid_amount[]
            # ----------------------------------------------------

            charge_paid = (
                request.form.getlist(
                    "charge_paid[]"
                )
            )

            if not charge_paid:
                charge_paid = (
                    request.form.getlist(
                        "charge_paid_amount[]"
                    )
                )

            charge_due_dates = (
                request.form.getlist(
                    "charge_due_date[]"
                )
            )

            charge_descriptions = (
                request.form.getlist(
                    "charge_description[]"
                )
            )

            # ----------------------------------------------------
            # Support:
            #
            # charge_enrollment[]
            #
            # AND:
            #
            # charge_enrollment_index[]
            # ----------------------------------------------------

            charge_enrollment_values = (
                request.form.getlist(
                    "charge_enrollment[]"
                )
            )

            if not charge_enrollment_values:
                charge_enrollment_values = (
                    request.form.getlist(
                        "charge_enrollment_index[]"
                    )
                )

            # ====================================================
            # EXISTING CHARGE MAP
            # ====================================================

            existing_charge_map = {
                charge.id: charge
                for charge
                in list(student.charges)
            }

            # ====================================================
            # MANUAL CHARGE IDs SUBMITTED
            # ====================================================

            submitted_manual_charge_ids = set()

            for raw_charge_id in (
                existing_charge_ids
            ):

                charge_id = _int_or_none(
                    raw_charge_id
                )

                if charge_id:
                    submitted_manual_charge_ids.add(
                        charge_id
                    )

            # ====================================================
            # DELETE REMOVED MANUAL CHARGES
            # ====================================================
            #
            # Automatic:
            #   registration
            #   program_fee
            #
            # are protected and handled below.
            #

            for existing_charge in list(
                student.charges
            ):

                if (
                    existing_charge.charge_type
                    in {
                        "registration",
                        "program_fee",
                    }
                ):
                    continue

                if (
                    existing_charge.id
                    not in submitted_manual_charge_ids
                ):
                    db.session.delete(
                        existing_charge
                    )

            # ====================================================
            # REGISTRATION FEE
            # ====================================================

            registration_charge = (
                StudentCharge.query
                .filter(
                    StudentCharge.student_id
                    == student.id,
                    StudentCharge.charge_type
                    == "registration",
                )
                .order_by(
                    StudentCharge.id.asc()
                )
                .first()
            )

            if registration_charge:

                registration_charge.institution_id = (
                    new_institution_id
                )

                registration_charge.branch_id = (
                    new_branch_id
                )

                registration_charge.student_id = (
                    student.id
                )

                registration_charge.enrollment_id = (
                    first_enrollment.id
                )

                registration_charge.academic_year_id = (
                    first_academic_year.id
                )

                registration_charge.charge_type = (
                    "registration"
                )

                registration_charge.charge_name = (
                    "Registration Fee"
                )

                registration_charge.description = (
                    "Automatic registration fee"
                )

                registration_charge.amount = (
                    Decimal("5.00")
                )

                # Preserve existing discount/paid amount.
                if registration_charge.discount is None:
                    registration_charge.discount = (
                        Decimal("0.00")
                    )

                if registration_charge.paid_amount is None:
                    registration_charge.paid_amount = (
                        Decimal("0.00")
                    )

                if not registration_charge.due_date:
                    registration_charge.due_date = (
                        date.today()
                    )

            else:

                registration_charge = StudentCharge(
                    institution_id=(
                        new_institution_id
                    ),
                    branch_id=(
                        new_branch_id
                    ),
                    student_id=(
                        student.id
                    ),
                    enrollment_id=(
                        first_enrollment.id
                    ),
                    academic_year_id=(
                        first_academic_year.id
                    ),
                    charge_type=(
                        "registration"
                    ),
                    charge_name=(
                        "Registration Fee"
                    ),
                    description=(
                        "Automatic registration fee"
                    ),
                    amount=(
                        Decimal("5.00")
                    ),
                    discount=(
                        Decimal("0.00")
                    ),
                    paid_amount=(
                        Decimal("0.00")
                    ),
                    due_date=(
                        date.today()
                    ),
                    created_by=(
                        current_user.id
                    ),
                )

                db.session.add(
                    registration_charge
                )

            registration_charge.calculate_balance()

            # ====================================================
            # PROGRAM FEE
            # ====================================================

            program_price = _decimal(
                getattr(
                    first_program,
                    "price",
                    0,
                )
            )

            program_charge = (
                StudentCharge.query
                .filter(
                    StudentCharge.student_id
                    == student.id,
                    StudentCharge.charge_type
                    == "program_fee",
                )
                .order_by(
                    StudentCharge.id.asc()
                )
                .first()
            )

            if (
                program_price
                > Decimal("0.00")
            ):

                if program_charge:

                    program_charge.institution_id = (
                        new_institution_id
                    )

                    program_charge.branch_id = (
                        new_branch_id
                    )

                    program_charge.student_id = (
                        student.id
                    )

                    program_charge.enrollment_id = (
                        first_enrollment.id
                    )

                    program_charge.academic_year_id = (
                        first_academic_year.id
                    )

                    program_charge.charge_type = (
                        "program_fee"
                    )

                    program_charge.charge_name = (
                        "Program Fee"
                    )

                    program_charge.description = (
                        "Automatic program fee - "
                        + str(
                            getattr(
                                first_program,
                                "name",
                                "Program",
                            )
                        )
                    )

                    program_charge.amount = (
                        program_price
                    )

                    if program_charge.discount is None:
                        program_charge.discount = (
                            Decimal("0.00")
                        )

                    if program_charge.paid_amount is None:
                        program_charge.paid_amount = (
                            Decimal("0.00")
                        )

                    if not program_charge.due_date:
                        program_charge.due_date = (
                            date.today()
                        )

                else:

                    program_charge = StudentCharge(
                        institution_id=(
                            new_institution_id
                        ),
                        branch_id=(
                            new_branch_id
                        ),
                        student_id=(
                            student.id
                        ),
                        enrollment_id=(
                            first_enrollment.id
                        ),
                        academic_year_id=(
                            first_academic_year.id
                        ),
                        charge_type=(
                            "program_fee"
                        ),
                        charge_name=(
                            "Program Fee"
                        ),
                        description=(
                            "Automatic program fee - "
                            + str(
                                getattr(
                                    first_program,
                                    "name",
                                    "Program",
                                )
                            )
                        ),
                        amount=(
                            program_price
                        ),
                        discount=(
                            Decimal("0.00")
                        ),
                        paid_amount=(
                            Decimal("0.00")
                        ),
                        due_date=(
                            date.today()
                        ),
                        created_by=(
                            current_user.id
                        ),
                    )

                    db.session.add(
                        program_charge
                    )

                program_charge.calculate_balance()

            else:

                # ------------------------------------------------
                # No program price.
                #
                # Delete only if nothing has been paid.
                # ------------------------------------------------

                if program_charge:

                    paid = _decimal(
                        program_charge.paid_amount
                    )

                    if paid <= Decimal("0.00"):

                        db.session.delete(
                            program_charge
                        )

            # ====================================================
            # MANUAL CHARGES
            # ====================================================

            max_charge_rows = max(
                len(existing_charge_ids),
                len(charge_types),
                len(charge_names),
                len(charge_amounts),
                len(charge_discounts),
                len(charge_paid),
                len(charge_due_dates),
                len(charge_descriptions),
                len(charge_enrollment_values),
                0,
            )

            for index in range(
                max_charge_rows
            ):

                # ------------------------------------------------
                # SAFE VALUES
                # ------------------------------------------------

                raw_existing_charge_id = (
                    existing_charge_ids[index]
                    if index
                    < len(existing_charge_ids)
                    else ""
                )

                charge_type = _clean(
                    charge_types[index]
                    if index
                    < len(charge_types)
                    else ""
                ).lower()

                charge_name = _clean(
                    charge_names[index]
                    if index
                    < len(charge_names)
                    else ""
                )

                amount = _decimal(
                    charge_amounts[index]
                    if index
                    < len(charge_amounts)
                    else "0"
                )

                discount = _decimal(
                    charge_discounts[index]
                    if index
                    < len(charge_discounts)
                    else "0"
                )

                paid_amount = _decimal(
                    charge_paid[index]
                    if index
                    < len(charge_paid)
                    else "0"
                )

                due_date = _parse_date(
                    charge_due_dates[index]
                    if index
                    < len(charge_due_dates)
                    else ""
                )

                description = _clean(
                    charge_descriptions[index]
                    if index
                    < len(charge_descriptions)
                    else ""
                )

                enrollment_value = _clean(
                    charge_enrollment_values[index]
                    if index
                    < len(charge_enrollment_values)
                    else ""
                )

                existing_charge_id = (
                    _int_or_none(
                        raw_existing_charge_id
                    )
                )

                # ------------------------------------------------
                # EMPTY ROW
                # ------------------------------------------------

                if not any(
                    [
                        charge_type,
                        charge_name,
                        amount != Decimal("0.00"),
                        discount != Decimal("0.00"),
                        paid_amount != Decimal("0.00"),
                        due_date,
                        description,
                        enrollment_value,
                        existing_charge_id,
                    ]
                ):
                    continue

                # ------------------------------------------------
                # AUTOMATIC TYPES
                # ------------------------------------------------

                if charge_type in {
                    "registration",
                    "program_fee",
                }:
                    continue

                # ------------------------------------------------
                # DEFAULT TYPE
                # ------------------------------------------------

                if not charge_type:
                    charge_type = "other"

                if (
                    charge_type
                    not in valid_charge_types
                ):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Invalid charge type."
                    )

                # ------------------------------------------------
                # NAME
                # ------------------------------------------------

                if not charge_name:
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Charge name is required."
                    )

                # ------------------------------------------------
                # AMOUNT
                # ------------------------------------------------

                if amount < Decimal("0.00"):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Amount cannot be negative."
                    )

                # ------------------------------------------------
                # DISCOUNT
                # ------------------------------------------------

                if discount < Decimal("0.00"):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Discount cannot be negative."
                    )

                if discount > amount:
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Discount cannot be greater than amount."
                    )

                # ------------------------------------------------
                # PAID
                # ------------------------------------------------

                if paid_amount < Decimal("0.00"):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Paid amount cannot be negative."
                    )

                net_amount = (
                    amount - discount
                )

                if paid_amount > net_amount:
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Paid amount cannot exceed net amount."
                    )

                # =================================================
                # FIND ATTACHED ENROLLMENT
                # =================================================

                charge_enrollment = None

                if enrollment_value:

                    enrollment_number = (
                        _int_or_none(
                            enrollment_value
                        )
                    )

                    if enrollment_number is None:
                        raise ValueError(
                            f"Charge row {index + 1}: "
                            "Invalid enrollment selection."
                        )

                    # ------------------------------------------------
                    # FIRST:
                    # Treat value as ROW INDEX.
                    #
                    # This matches the current edit template.
                    # ------------------------------------------------

                    if (
                        enrollment_number
                        in enrollment_by_row
                    ):

                        charge_enrollment = (
                            enrollment_by_row[
                                enrollment_number
                            ]
                        )

                    # ------------------------------------------------
                    # SECOND:
                    # Treat value as actual enrollment ID.
                    #
                    # This makes route compatible with a template
                    # that sends enrollment.id.
                    # ------------------------------------------------

                    else:

                        charge_enrollment = (
                            StudentEnrollment.query
                            .filter(
                                StudentEnrollment.id
                                == enrollment_number,
                                StudentEnrollment.student_id
                                == student.id,
                            )
                            .first()
                        )

                        if not charge_enrollment:

                            raise ValueError(
                                f"Charge row {index + 1}: "
                                "Selected enrollment does not exist."
                            )

                else:

                    # ------------------------------------------------
                    # Default to first enrollment
                    # ------------------------------------------------

                    charge_enrollment = (
                        first_enrollment
                    )

                # =================================================
                # VERIFY ENROLLMENT BELONGS TO STUDENT
                # =================================================

                if (
                    not charge_enrollment
                    or charge_enrollment.student_id
                    != student.id
                ):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Selected enrollment does not belong to this student."
                    )

                # =================================================
                # FIND EXISTING CHARGE
                # =================================================

                existing_charge = None

                if existing_charge_id:

                    existing_charge = (
                        existing_charge_map
                        .get(
                            existing_charge_id
                        )
                    )

                    if not existing_charge:
                        raise ValueError(
                            f"Charge row {index + 1}: "
                            "Invalid existing charge."
                        )

                    # --------------------------------------------
                    # Never allow automatic charge editing through
                    # manual charge rows.
                    # --------------------------------------------

                    if (
                        existing_charge.charge_type
                        in {
                            "registration",
                            "program_fee",
                        }
                    ):
                        continue

                # =================================================
                # UPDATE EXISTING MANUAL CHARGE
                # =================================================

                if existing_charge:

                    existing_charge.institution_id = (
                        new_institution_id
                    )

                    existing_charge.branch_id = (
                        new_branch_id
                    )

                    existing_charge.student_id = (
                        student.id
                    )

                    existing_charge.enrollment_id = (
                        charge_enrollment.id
                    )

                    existing_charge.academic_year_id = (
                        charge_enrollment.academic_year_id
                    )

                    existing_charge.charge_type = (
                        charge_type
                    )

                    existing_charge.charge_name = (
                        charge_name
                    )

                    existing_charge.description = (
                        description or None
                    )

                    existing_charge.amount = (
                        amount
                    )

                    existing_charge.discount = (
                        discount
                    )

                    existing_charge.paid_amount = (
                        paid_amount
                    )

                    existing_charge.due_date = (
                        due_date
                    )

                    existing_charge.calculate_balance()

                # =================================================
                # CREATE NEW MANUAL CHARGE
                # =================================================

                else:

                    new_charge = StudentCharge(
                        institution_id=(
                            new_institution_id
                        ),
                        branch_id=(
                            new_branch_id
                        ),
                        student_id=(
                            student.id
                        ),
                        enrollment_id=(
                            charge_enrollment.id
                        ),
                        academic_year_id=(
                            charge_enrollment
                            .academic_year_id
                        ),
                        charge_type=(
                            charge_type
                        ),
                        charge_name=(
                            charge_name
                        ),
                        description=(
                            description or None
                        ),
                        amount=(
                            amount
                        ),
                        discount=(
                            discount
                        ),
                        paid_amount=(
                            paid_amount
                        ),
                        due_date=(
                            due_date
                        ),
                        created_by=(
                            current_user.id
                        ),
                    )

                    new_charge.calculate_balance()

                    db.session.add(
                        new_charge
                    )

            # ====================================================
            # UPDATE TIMESTAMP
            # ====================================================

            student.updated_at = (
                datetime.utcnow()
            )

            # ====================================================
            # FINAL FLUSH
            # ============================================================

            db.session.flush()

            # ====================================================
            # COMMIT
            # ============================================================

            db.session.commit()

            # ====================================================
            # SUCCESS
            # ============================================================

            flash(
                f"Student '{student.full_name}' was updated successfully.",
                "success",
            )

            # ====================================================
            # REDIRECT
            # ============================================================

            if (
                "main.view_student"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.view_student",
                        student_id=student.id,
                    )
                )

            if (
                "main.student_profile"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.student_profile",
                        student_id=student.id,
                    )
                )

            return redirect(
                url_for(
                    "main.all_students"
                )
            )

        # ========================================================
        # VALUE / VALIDATION ERROR
        # ========================================================

        except ValueError as exc:

            db.session.rollback()

            if (
                uploaded_photo_path
                and os.path.exists(
                    uploaded_photo_path
                )
            ):

                try:
                    os.remove(
                        uploaded_photo_path
                    )
                except OSError:
                    pass

            flash(
                f"Unable to update student. Error: {exc}",
                "danger",
            )

            return redirect(
                request.url
            )

        # ========================================================
        # DATABASE / GENERAL ERROR
        # ========================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Error updating student %s",
                student_id,
            )

            if (
                uploaded_photo_path
                and os.path.exists(
                    uploaded_photo_path
                )
            ):

                try:
                    os.remove(
                        uploaded_photo_path
                    )
                except OSError:
                    pass

            flash(
                f"Unable to update student. Error: {exc}",
                "danger",
            )

            return redirect(
                request.url
            )

    # ============================================================
    # GET DATA
    # ============================================================

    # ============================================================
    # INSTITUTIONS
    # ============================================================

    if current_user_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == current_user_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ============================================================
    # BRANCHES
    # ============================================================

    if current_user_role == "superadmin":

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif current_user_role == "school_admin":

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_user_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        branches = (
            Branch.query
            .filter(
                Branch.id
                == current_user_branch_id,
                Branch.institution_id
                == current_user_institution_id,
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    # ============================================================
    # PROGRAMS
    # ============================================================

    programs = (
        Program.query
        .filter(
            Program.institution_id
            == student.institution_id,
            or_(
                Program.branch_id
                == student.branch_id,
                Program.branch_id.is_(None),
            ),
        )
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ============================================================
    # CLASSES
    # ============================================================

    classes = (
        Class.query
        .filter(
            Class.institution_id
            == student.institution_id,
            Class.branch_id
            == student.branch_id,
        )
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ============================================================
    # SECTIONS
    # ============================================================

    sections = (
        Section.query
        .filter(
            Section.institution_id
            == student.institution_id,
            Section.branch_id
            == student.branch_id,
        )
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ============================================================
    # ACADEMIC YEARS
    # ============================================================

    academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.institution_id
            == student.institution_id
        )
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ============================================================
    # COUNTRIES
    # ============================================================

    try:

        countries = get_all_countries()

    except Exception:

        countries = []

    # ============================================================
    # CURRENT INSTITUTION
    # ============================================================

    current_institution = (
        Institution.query
        .filter(
            Institution.id
            == student.institution_id
        )
        .first()
    )

    # ============================================================
    # CURRENT BRANCH
    # ============================================================

    current_branch = (
        Branch.query
        .filter(
            Branch.id
            == student.branch_id
        )
        .first()
    )

    # ============================================================
    # EXISTING ENROLLMENTS
    # ============================================================

    enrollments = (
        StudentEnrollment.query
        .filter(
            StudentEnrollment.student_id
            == student.id
        )
        .order_by(
            StudentEnrollment.id.asc()
        )
        .all()
    )

    # ============================================================
    # EXISTING CHARGES
    # ============================================================

    charges = (
        StudentCharge.query
        .filter(
            StudentCharge.student_id
            == student.id
        )
        .order_by(
            StudentCharge.id.asc()
        )
        .all()
    )

    # ============================================================
    # RENDER TEMPLATE
    # ============================================================

    return render_template(
        "backend/pages/students/edit_student.html",

        # --------------------------------------------------------
        # Student
        # --------------------------------------------------------

        student=student,

        # --------------------------------------------------------
        # Scope
        # --------------------------------------------------------

        institutions=institutions,
        branches=branches,
        programs=programs,
        classes=classes,
        sections=sections,
        academic_years=academic_years,

        # --------------------------------------------------------
        # Countries
        # --------------------------------------------------------

        countries=countries,
        all_countries=countries,

        # --------------------------------------------------------
        # Current institution / branch
        # --------------------------------------------------------

        current_institution=current_institution,
        current_branch=current_branch,

        current_institution_id=(
            student.institution_id
        ),

        current_branch_id=(
            student.branch_id
        ),

        current_role=current_user_role,

        # --------------------------------------------------------
        # Existing enrollments
        # --------------------------------------------------------

        enrollments=enrollments,

        # --------------------------------------------------------
        # Existing charges
        # --------------------------------------------------------

        charges=charges,

        # --------------------------------------------------------
        # Today
        # --------------------------------------------------------

        today=date.today().isoformat(),

        # --------------------------------------------------------
        # Logged-in user
        # --------------------------------------------------------

        user=current_user,
    )


# ============================================================
# TOGGLE STUDENT ACCOUNT STATUS
# ============================================================

@bp.route(
    "/students/<int:student_id>/toggle-status",
    methods=["POST"]
)
@login_required
def toggle_student_status(student_id):

    # ========================================================
    # ACCESS CONTROL
    # ========================================================

    allowed_roles = {
        "superadmin",
        "institution_admin",
        "branch_admin",
    }

    if getattr(current_user, "role", None) not in allowed_roles:

        flash(
            "You do not have permission to change student status.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )


    # ========================================================
    # GET STUDENT
    # ========================================================

    student = Student.query.get_or_404(student_id)


    # ========================================================
    # CURRENT USER
    # ========================================================

    current_role = getattr(
        current_user,
        "role",
        None
    )

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )


    # ========================================================
    # INSTITUTION ADMIN ACCESS
    # ========================================================

    if current_role == "institution_admin":

        if student.institution_id != current_institution_id:

            flash(
                "You cannot change the status of a student from another institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )


    # ========================================================
    # BRANCH ADMIN ACCESS
    # ========================================================

    if current_role == "branch_admin":

        if (
            student.institution_id != current_institution_id
            or
            student.branch_id != current_branch_id
        ):

            flash(
                "You cannot change the status of this student.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )


    # ========================================================
    # TOGGLE ACCOUNT STATUS
    # ========================================================

    student.is_active = not student.is_active

    student.updated_at = datetime.utcnow()


    # ========================================================
    # SAVE
    # ========================================================

    try:

        db.session.commit()

        if student.is_active:

            flash(
                f"{student.full_name} account has been activated.",
                "success"
            )

        else:

            flash(
                f"{student.full_name} account has been deactivated.",
                "warning"
            )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Failed to toggle student status: %s",
            e
        )

        flash(
            "Unable to update student account status.",
            "danger"
        )


    # ========================================================
    # RETURN
    # ========================================================

    return redirect(
        url_for("main.all_students")
    )


# ============================================================
# DELETE STUDENT
# ============================================================
@bp.route(
    "/students/<int:student_id>/delete",
    methods=["POST"]
)
@login_required
def delete_student(student_id):

    # ============================================================
    # ALLOWED ROLES
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_user.role not in allowed_roles:
        abort(403)

    # ============================================================
    # ROLE VALIDATION
    # ============================================================

    if current_user.role == "school_admin":
        if not current_user.institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )
            return redirect(url_for("main.all_students"))

    if current_user.role == "branch_admin":
        if (
            not current_user.institution_id
            or not current_user.branch_id
        ):
            flash(
                "Your account is not assigned to an institution and branch.",
                "danger"
            )
            return redirect(url_for("main.all_students"))

    # ============================================================
    # GET STUDENT
    # ============================================================

    student_query = (
        Student.query
        .filter(
            Student.id == student_id,
            Student.role == "student"
        )
    )

    # ============================================================
    # SECURITY SCOPE
    # ============================================================

    if current_user.role == "school_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id
        )

    elif current_user.role == "branch_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id,
            Student.branch_id == current_user.branch_id
        )

    # ============================================================
    # FETCH STUDENT
    # ============================================================

    student = student_query.first()

    if not student:
        flash(
            "Student not found or you do not have permission to delete this student.",
            "danger"
        )
        return redirect(url_for("main.all_students"))

    # ============================================================
    # KEEP NAME FOR SUCCESS MESSAGE
    # ============================================================

    student_name = (
        student.full_name
        or student.username
        or f"Student #{student.id}"
    )

    # ============================================================
    # DELETE EVERYTHING RELATED TO THE STUDENT
    # ============================================================

    try:

        # --------------------------------------------------------
        # 1. DELETE STUDENT CHARGES
        #
        # StudentCharge has:
        # student_id -> students.id
        # enrollment_id -> student_enrollments.id
        # --------------------------------------------------------

        StudentCharge.query.filter(
            StudentCharge.student_id == student.id
        ).delete(
            synchronize_session=False
        )

        # --------------------------------------------------------
        # 2. DELETE STUDENT ENROLLMENTS
        # --------------------------------------------------------

        StudentEnrollment.query.filter(
            StudentEnrollment.student_id == student.id
        ).delete(
            synchronize_session=False
        )

        # --------------------------------------------------------
        # 3. DELETE STUDENT
        # --------------------------------------------------------

        db.session.delete(student)

        # --------------------------------------------------------
        # 4. COMMIT EVERYTHING
        # --------------------------------------------------------

        db.session.commit()

        flash(
            f"Student '{student_name}' and all related enrollment and charge records were deleted successfully.",
            "success"
        )

    except Exception as exc:

        # --------------------------------------------------------
        # ROLLBACK
        # --------------------------------------------------------

        db.session.rollback()

        current_app.logger.exception(
            "Failed to delete student ID %s: %s",
            student_id,
            exc
        )

        flash(
            "Unable to delete the student. No changes were saved.",
            "danger"
        )

    # ============================================================
    # RETURN TO STUDENT LIST
    # ============================================================

    return redirect(
        url_for("main.all_students")
    )





# ============================================================
# STUDENT FULL IMPORT SAMPLE CSV
# Student + Enrollment + StudentCharge
# ============================================================
@bp.route(
    "/students/import/sample",
    methods=["GET"]
)
@login_required
def export_student_import_sample():

    import csv
    import io

    from flask import Response, abort, flash, redirect, url_for
    from sqlalchemy import or_

    # ============================================================
    # PERMISSION
    # ============================================================

    if not _student_can_manage():
        abort(403)

    # ============================================================
    # CURRENT USER
    # ============================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if not institution_id:
        flash(
            "Your account is not linked to an institution.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ============================================================
    # ACADEMIC YEAR
    # ============================================================
    #
    # Priority:
    # 1. Current
    # 2. Active
    # 3. Latest
    #
    # ============================================================

    academic_year = None

    # ------------------------------------------------------------
    # Try current / active
    # ------------------------------------------------------------

    try:

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id == institution_id
            )
            .filter(
                or_(
                    AcademicYear.is_current.is_(True),
                    AcademicYear.status == "active"
                )
            )
            .order_by(
                AcademicYear.id.desc()
            )
            .first()
        )

    except Exception:

        academic_year = None

    # ------------------------------------------------------------
    # Fallback latest
    # ------------------------------------------------------------

    if not academic_year:

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id == institution_id
            )
            .order_by(
                AcademicYear.id.desc()
            )
            .first()
        )

    if not academic_year:

        flash(
            "No Academic Year was found for this institution.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ============================================================
    # ACADEMIC YEAR DISPLAY VALUE
    # ============================================================

    academic_year_name = (
        getattr(
            academic_year,
            "name",
            None
        )
        or getattr(
            academic_year,
            "academic_year",
            None
        )
        or getattr(
            academic_year,
            "title",
            None
        )
        or getattr(
            academic_year,
            "year_name",
            None
        )
        or getattr(
            academic_year,
            "code",
            None
        )
        or str(academic_year.id)
    )

    # ============================================================
    # PROGRAM
    # ============================================================
    #
    # Program:
    #
    #   institution = current institution
    #
    # AND:
    #
    #   branch = current branch
    #
    # OR:
    #
    #   branch = NULL
    #
    # NULL = institution-wide program
    #
    # ============================================================

    program = None

    if branch_id:

        program_query = (
            Program.query
            .filter(
                Program.institution_id == institution_id
            )
            .filter(
                or_(
                    Program.branch_id == branch_id,
                    Program.branch_id.is_(None)
                )
            )
        )

        # --------------------------------------------------------
        # Prefer active
        # --------------------------------------------------------

        try:

            program = (
                program_query
                .filter(
                    Program.status == "active"
                )
                .order_by(
                    (Program.branch_id == branch_id).desc(),
                    Program.id.asc()
                )
                .first()
            )

        except Exception:

            program = None

        # --------------------------------------------------------
        # Fallback without status
        # --------------------------------------------------------

        if not program:

            program = (
                program_query
                .order_by(
                    (Program.branch_id == branch_id).desc(),
                    Program.id.asc()
                )
                .first()
            )

    else:

        # --------------------------------------------------------
        # Institution-level user
        # --------------------------------------------------------

        program_query = (
            Program.query
            .filter(
                Program.institution_id == institution_id
            )
        )

        try:

            program = (
                program_query
                .filter(
                    Program.status == "active"
                )
                .order_by(
                    Program.id.asc()
                )
                .first()
            )

        except Exception:

            program = None

        if not program:

            program = (
                program_query
                .order_by(
                    Program.id.asc()
                )
                .first()
            )

    if not program:

        flash(
            "No Program was found for this institution/branch.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ============================================================
    # PROGRAM DISPLAY NAME
    # ============================================================

    program_name = (
        getattr(
            program,
            "name",
            None
        )
        or getattr(
            program,
            "title",
            None
        )
        or getattr(
            program,
            "short_name",
            None
        )
        or getattr(
            program,
            "code",
            None
        )
        or str(program.id)
    )

    # ============================================================
    # CLASS
    # ============================================================
    #
    # CLASS IS NOT REQUIRED.
    #
    # We try several possibilities:
    #
    # 1. Class.program_id = Program.id
    # 2. Class branch = current branch
    # 3. Class institution = current institution
    #
    # If no class exists:
    #
    #   Class = ""
    #   Section = ""
    #
    # ============================================================

    student_class = None

    # ------------------------------------------------------------
    # Base class query
    # ------------------------------------------------------------

    class_query = (
        Class.query
        .filter(
            Class.institution_id == institution_id
        )
    )

    # ------------------------------------------------------------
    # Branch filtering
    # ------------------------------------------------------------

    if branch_id:

        class_query = (
            class_query
            .filter(
                or_(
                    Class.branch_id == branch_id,
                    Class.branch_id.is_(None)
                )
            )
        )

    # ============================================================
    # FIRST TRY:
    # CLASS -> PROGRAM
    # ============================================================

    if hasattr(Class, "program_id"):

        try:

            program_class_query = (
                class_query
                .filter(
                    Class.program_id == program.id
                )
            )

            # ----------------------------------------------------
            # Active first
            # ----------------------------------------------------

            try:

                student_class = (
                    program_class_query
                    .filter(
                        Class.status == "active"
                    )
                    .order_by(
                        (
                            Class.branch_id == branch_id
                        ).desc()
                        if branch_id
                        else Class.id.asc()
                    )
                    .first()
                )

            except Exception:

                student_class = None

            # ----------------------------------------------------
            # Fallback
            # ----------------------------------------------------

            if not student_class:

                student_class = (
                    program_class_query
                    .order_by(
                        Class.id.asc()
                    )
                    .first()
                )

        except Exception:

            student_class = None

    # ============================================================
    # SECOND TRY:
    # CLASS WITHOUT PROGRAM RELATIONSHIP
    # ============================================================
    #
    # If Class.program_id does not match anything, we still use
    # the real Class belonging to current branch.
    #
    # ============================================================

    if not student_class:

        try:

            # ----------------------------------------------------
            # Active class first
            # ----------------------------------------------------

            try:

                student_class = (
                    class_query
                    .filter(
                        Class.status == "active"
                    )
                    .order_by(
                        (
                            Class.branch_id == branch_id
                        ).desc()
                        if branch_id
                        else Class.id.asc()
                    )
                    .first()
                )

            except Exception:

                student_class = None

            # ----------------------------------------------------
            # Fallback
            # ----------------------------------------------------

            if not student_class:

                student_class = (
                    class_query
                    .order_by(
                        Class.id.asc()
                    )
                    .first()
                )

        except Exception:

            student_class = None

    # ============================================================
    # CLASS NAME
    # ============================================================

    class_name = ""

    if student_class:

        class_name = (
            getattr(
                student_class,
                "name",
                None
            )
            or getattr(
                student_class,
                "class_name",
                None
            )
            or getattr(
                student_class,
                "title",
                None
            )
            or getattr(
                student_class,
                "code",
                None
            )
            or str(student_class.id)
        )

    # ============================================================
    # SECTION
    # ============================================================
    #
    # SECTION IS OPTIONAL.
    #
    # If Class exists:
    #
    #     search Section.class_id
    #
    # If no section:
    #
    #     ""
    #
    # ============================================================

    section = None

    if student_class and hasattr(Section, "class_id"):

        try:

            section_query = (
                Section.query
                .filter(
                    Section.class_id == student_class.id
                )
                .filter(
                    Section.institution_id == institution_id
                )
            )

            # ----------------------------------------------------
            # Branch
            # ----------------------------------------------------

            if branch_id:

                section_query = (
                    section_query
                    .filter(
                        or_(
                            Section.branch_id == branch_id,
                            Section.branch_id.is_(None)
                        )
                    )
                )

            # ----------------------------------------------------
            # Active first
            # ----------------------------------------------------

            try:

                section = (
                    section_query
                    .filter(
                        Section.status == "active"
                    )
                    .order_by(
                        (
                            Section.branch_id == branch_id
                        ).desc()
                        if branch_id
                        else Section.id.asc()
                    )
                    .first()
                )

            except Exception:

                section = None

            # ----------------------------------------------------
            # Fallback
            # ----------------------------------------------------

            if not section:

                section = (
                    section_query
                    .order_by(
                        Section.id.asc()
                    )
                    .first()
                )

        except Exception:

            section = None

    # ============================================================
    # SECTION NAME
    # ============================================================

    section_name = ""

    if section:

        section_name = (
            getattr(
                section,
                "name",
                None
            )
            or getattr(
                section,
                "section_name",
                None
            )
            or getattr(
                section,
                "title",
                None
            )
            or getattr(
                section,
                "code",
                None
            )
            or str(section.id)
        )

    # ============================================================
    # EXCEL-SAFE PHONE NUMBERS
    # ============================================================

    sample_phone = '="0612345678"'

    sample_parent_phone = '="0611111111"'

    # ============================================================
    # CSV HEADERS
    # ============================================================

    headers = [

        # --------------------------------------------------------
        # STUDENT
        # --------------------------------------------------------

        "Admission No",
        "Roll No",
        "Username",
        "Email",
        "Full Name",
        "Gender",
        "Date of Birth",
        "Place of Birth",
        "Nationality",
        "Phone",
        "Address",
        "City",

        # --------------------------------------------------------
        # PARENT
        # --------------------------------------------------------

        "Parent Name",
        "Parent Phone",
        "Parent Email",
        "Parent Address",
        "Relationship to Student",

        # --------------------------------------------------------
        # STUDENT STATUS
        # --------------------------------------------------------

        "Student Status",
        "Student Notes",

        # --------------------------------------------------------
        # ENROLLMENT
        # --------------------------------------------------------

        "Academic Year",
        "Program",
        "Class",
        "Section",
        "Enrollment No",
        "Enrollment Date",
        "Enrollment Status",
        "Enrollment Notes",

        # --------------------------------------------------------
        # CHARGE
        # --------------------------------------------------------

        "Charge Type",
        "Charge Name",
        "Charge Description",
        "Amount",
        "Discount",
        "Paid Amount",
        "Due Date",
    ]

    # ============================================================
    # SAMPLE ROW
    # ============================================================

    sample_row = [

        # --------------------------------------------------------
        # STUDENT
        # --------------------------------------------------------

        "STU001",
        "R001",
        "STU001",
        "student001@example.com",
        "Ahmed Mohamed Ali",
        "Male",
        "2010-05-15",
        "Mogadishu",
        "Somali",

        # Excel-safe phone
        sample_phone,

        "Hodan",
        "Mogadishu",

        # --------------------------------------------------------
        # PARENT
        # --------------------------------------------------------

        "Mohamed Ali Hassan",

        # Excel-safe parent phone
        sample_parent_phone,

        "parent001@example.com",
        "Hodan, Mogadishu",
        "Father",

        # --------------------------------------------------------
        # STUDENT STATUS
        # --------------------------------------------------------

        "active",
        "New student registration",

        # --------------------------------------------------------
        # REAL DATABASE RELATIONSHIPS
        # --------------------------------------------------------

        academic_year_name,
        program_name,
        class_name,
        section_name,

        # --------------------------------------------------------
        # ENROLLMENT
        # --------------------------------------------------------

        "ENR001",
        "2026-09-20",
        "active",
        "First enrollment",

        # --------------------------------------------------------
        # CHARGE
        # --------------------------------------------------------

        "registration",
        "Registration Fee",
        "Student registration fee",
        "50.00",
        "0.00",
        "0.00",
        "2026-09-30",
    ]

    # ============================================================
    # CREATE CSV
    # ============================================================

    output = io.StringIO(
        newline=""
    )

    writer = csv.writer(
        output,
        delimiter=",",
        quotechar='"',
        quoting=csv.QUOTE_MINIMAL,
        lineterminator="\r\n"
    )

    # Header
    writer.writerow(headers)

    # Real-data sample
    writer.writerow(sample_row)

    # ============================================================
    # UTF-8 BOM
    # ============================================================

    csv_content = (
        "\ufeff"
        + output.getvalue()
    )

    output.close()

    # ============================================================
    # RESPONSE
    # ============================================================

    return Response(
        csv_content,
        mimetype="text/csv; charset=utf-8",
        headers={
            "Content-Disposition":
                "attachment; "
                "filename=student_import_sample.csv"
        }
    )


# ============================================================
# IMPORT STUDENTS
# ============================================================

@bp.route(
    "/students/import",
    methods=["POST"]
)
@login_required
def import_students_full():

    import csv
    import io
    import secrets
    import re

    from datetime import datetime, date
    from decimal import Decimal, InvalidOperation

    from flask import (
        request,
        redirect,
        url_for,
        flash,
        current_app,
        session,
        abort,
    )

    # ========================================================
    # ACCESS CHECK
    # ========================================================

    if not _student_can_manage():
        abort(403)

    # ========================================================
    # CURRENT USER
    # ========================================================

    current_user_obj = current_user

    role = getattr(
        current_user_obj,
        "role",
        None
    )

    institution_id = getattr(
        current_user_obj,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user_obj,
        "branch_id",
        None
    )

    if not institution_id:

        flash(
            "Institution information could not be determined.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # BRANCH SECURITY
    # ========================================================

    if role == "branch_admin":

        if not user_branch_id:

            flash(
                "Your branch could not be determined.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )

    # --------------------------------------------------------
    # For branch restricted users, always force own branch.
    # --------------------------------------------------------

    import_branch_id = user_branch_id

    # ========================================================
    # FILE
    # ========================================================

    file = request.files.get("file")

    if not file or not file.filename:

        flash(
            "Please select a CSV file.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    if not file.filename.lower().endswith(".csv"):

        flash(
            "Only CSV files are allowed.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # READ FILE
    # ========================================================

    try:

        raw_data = file.read()

        if not raw_data:

            flash(
                "The CSV file is empty.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )

        text_data = raw_data.decode(
            "utf-8-sig"
        )

    except UnicodeDecodeError:

        flash(
            "CSV file must be UTF-8 encoded.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # CSV READER
    # ========================================================

    stream = io.StringIO(
        text_data,
        newline=""
    )

    reader = csv.DictReader(stream)

    if not reader.fieldnames:

        flash(
            "CSV file has no header row.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # REQUIRED COLUMNS
    # ========================================================
    #
    # ONLY Full Name is required from student identity.
    #
    # Admission No
    # Roll No
    # Username
    # Email
    #
    # can all be generated automatically.
    #
    # ========================================================

    required_columns = {
        "Full Name",
        "Academic Year",
        "Program",
        "Class",
        "Enrollment No",
        "Charge Type",
        "Charge Name",
        "Amount",
        "Discount",
        "Paid Amount",
    }

    actual_columns = {
        str(column).strip()
        for column in reader.fieldnames
        if column
    }

    missing_columns = (
        required_columns - actual_columns
    )

    if missing_columns:

        flash(
            "Missing CSV columns: "
            + ", ".join(
                sorted(missing_columns)
            ),
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # HELPER FUNCTIONS
    # ========================================================

    def clean(value):

        if value is None:
            return None

        value = str(value).strip()

        return value if value else None

    # ========================================================
    # DATE
    # ========================================================

    def parse_date(
        value,
        field_name
    ):

        value = clean(value)

        if not value:
            return None

        formats = [
            "%Y-%m-%d",
            "%Y/%m/%d",
            "%d-%m-%Y",
            "%d/%m/%Y",
        ]

        for fmt in formats:

            try:

                return datetime.strptime(
                    value,
                    fmt
                ).date()

            except ValueError:
                continue

        raise ValueError(
            f"{field_name} has invalid date "
            f"'{value}'. Use YYYY-MM-DD."
        )

    # ========================================================
    # DECIMAL
    # ========================================================

    def decimal_value(
        value,
        field_name,
        default="0"
    ):

        value = clean(value)

        if not value:
            value = default

        try:

            amount = Decimal(
                value.replace(",", "")
            )

        except (
            InvalidOperation,
            ValueError
        ):

            raise ValueError(
                f"{field_name} has invalid amount "
                f"'{value}'."
            )

        if amount < 0:

            raise ValueError(
                f"{field_name} cannot be negative."
            )

        return amount.quantize(
            Decimal("0.01")
        )

    # ========================================================
    # NORMALIZE
    # ========================================================

    def normalize(value):

        value = clean(value)

        if not value:
            return ""

        return value.lower().strip()

    # ========================================================
    # SAFE USERNAME BASE
    # ========================================================

    def make_username_base(
        full_name,
        admission_no=None
    ):

        name = clean(full_name) or "student"

        name = name.lower()

        name = re.sub(
            r"[^a-z0-9]+",
            ".",
            name
        )

        name = name.strip(".")

        if not name:
            name = "student"

        if admission_no:

            admission_clean = re.sub(
                r"[^a-z0-9]+",
                "",
                admission_no.lower()
            )

            if admission_clean:

                name = (
                    f"{name}.{admission_clean}"
                )

        return name[:120]

    # ========================================================
    # GENERATE UNIQUE USERNAME
    # ========================================================

    def generate_unique_username(
        full_name,
        admission_no=None
    ):

        base = make_username_base(
            full_name,
            admission_no
        )

        candidate = base

        counter = 1

        while True:

            exists = (
                Student.query
                .filter(
                    Student.username
                    == candidate
                )
                .first()
            )

            if not exists:
                return candidate

            candidate = (
                f"{base}.{counter}"
            )

            counter += 1

    # ========================================================
    # GENERATE UNIQUE ADMISSION NO
    # ========================================================

    def generate_unique_admission_no():

        year = datetime.utcnow().year

        while True:

            number = (
                secrets.randbelow(900000)
                + 100000
            )

            candidate = (
                f"STU-{year}-{number}"
            )

            exists = (
                Student.query
                .filter(
                    Student.institution_id
                    == institution_id,

                    Student.admission_no
                    == candidate,
                )
                .first()
            )

            if not exists:
                return candidate

    # ========================================================
    # GENERATE UNIQUE ROLL NO
    # ========================================================

    def generate_unique_roll_no():

        while True:

            number = (
                secrets.randbelow(900000)
                + 100000
            )

            candidate = str(number)

            exists = (
                Student.query
                .filter(
                    Student.institution_id
                    == institution_id,

                    Student.branch_id
                    == import_branch_id,

                    Student.roll_no
                    == candidate,
                )
                .first()
            )

            if not exists:
                return candidate

    # ========================================================
    # GENERATE EMAIL
    # ========================================================
    #
    # IMPORTANT:
    # This is a system-generated email.
    # It is NOT a real email inbox.
    #
    # Example:
    # stu-2026-123456@student.sooyaal.local
    #
    # ========================================================

    def generate_unique_email(
        admission_no
    ):

        safe_admission = re.sub(
            r"[^a-zA-Z0-9]+",
            "-",
            admission_no
        ).strip("-").lower()

        base = (
            f"stu-{safe_admission}"
        )

        domain = (
            current_app.config.get(
                "STUDENT_IMPORT_EMAIL_DOMAIN",
                "student.sooyaal.local"
            )
        )

        candidate = (
            f"{base}@{domain}"
        )

        counter = 1

        while True:

            exists = (
                Student.query
                .filter(
                    db.func.lower(
                        Student.email
                    )
                    == candidate.lower()
                )
                .first()
            )

            if not exists:
                return candidate

            candidate = (
                f"{base}-{counter}"
                f"@{domain}"
            )

            counter += 1

    # ========================================================
    # GENERATE PASSWORD
    # ========================================================

    def generate_student_password():

        # Example:
        # Stu@A8k29LmQ7
        #
        # Password is returned only for newly
        # created students.

        alphabet = (
            "ABCDEFGHJKLMNPQRSTUVWXYZ"
            "abcdefghijkmnopqrstuvwxyz"
            "23456789"
        )

        random_part = "".join(
            secrets.choice(alphabet)
            for _ in range(10)
        )

        return (
            f"Stu@{random_part}"
        )

    # ========================================================
    # GENERIC MODEL RESOLVER
    # ========================================================

    def resolve_model(
        model,
        value,
        model_name,
        institution_id=None,
        branch_id=None,
    ):

        value = clean(value)

        if not value:

            raise ValueError(
                f"{model_name} is required."
            )

        query = model.query

        # ----------------------------------------------------
        # Institution
        # ----------------------------------------------------

        if institution_id is not None:

            if hasattr(
                model,
                "institution_id"
            ):

                query = query.filter(
                    model.institution_id
                    == institution_id
                )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if branch_id is not None:

            if hasattr(
                model,
                "branch_id"
            ):

                query = query.filter(
                    model.branch_id
                    == branch_id
                )

        # ----------------------------------------------------
        # Exact fields
        # ----------------------------------------------------

        possible_fields = [
            "name",
            "title",
            "code",
            "label",
            "academic_year",
        ]

        for field_name in possible_fields:

            column = getattr(
                model,
                field_name,
                None
            )

            if column is None:
                continue

            obj = (
                query
                .filter(
                    column == value
                )
                .first()
            )

            if obj:
                return obj

        # ----------------------------------------------------
        # Case insensitive
        # ----------------------------------------------------

        for field_name in possible_fields:

            column = getattr(
                model,
                field_name,
                None
            )

            if column is None:
                continue

            try:

                obj = (
                    query
                    .filter(
                        db.func.lower(
                            column
                        )
                        == normalize(value)
                    )
                    .first()
                )

                if obj:
                    return obj

            except Exception:
                continue

        raise ValueError(
            f"{model_name} '{value}' was not found."
        )

    # ========================================================
    # COUNTERS
    # ========================================================

    created_students = 0
    updated_students = 0
    created_enrollments = 0
    updated_enrollments = 0
    created_charges = 0

    generated_credentials = []

    errors = []

    # ========================================================
    # PROCESS
    # ========================================================

    try:

        rows = list(reader)

        if not rows:

            flash(
                "CSV file contains no student records.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )

        # ====================================================
        # LOOP
        # ====================================================

        for row_number, raw_row in enumerate(
            rows,
            start=2
        ):

            try:

                # --------------------------------------------
                # CLEAN ROW
                # --------------------------------------------

                row = {
                    str(key).strip(): clean(value)
                    for key, value in raw_row.items()
                    if key
                }

                # =================================================
                # FULL NAME
                # =================================================

                full_name = clean(
                    row.get("Full Name")
                )

                if not full_name:

                    raise ValueError(
                        "Full Name is required."
                    )

                # =================================================
                # STUDENT STATUS
                # =================================================

                student_status = (
                    clean(
                        row.get(
                            "Student Status"
                        )
                    )
                    or "active"
                ).lower()

                allowed_student_statuses = {
                    "active",
                    "inactive",
                    "graduated",
                    "transferred",
                    "suspended",
                    "withdrawn",
                }

                if student_status not in (
                    allowed_student_statuses
                ):

                    raise ValueError(
                        f"Invalid Student Status "
                        f"'{student_status}'."
                    )

                # =================================================
                # ADMISSION NUMBER
                # =================================================

                admission_no = clean(
                    row.get("Admission No")
                )

                # -------------------------------------------------
                # Generate if missing
                # -------------------------------------------------

                if not admission_no:

                    admission_no = (
                        generate_unique_admission_no()
                    )

                # =================================================
                # FIND EXISTING STUDENT
                # =================================================

                student = (
                    Student.query
                    .filter(
                        Student.institution_id
                        == institution_id,

                        Student.admission_no
                        == admission_no,
                    )
                    .first()
                )

                # =================================================
                # NEW STUDENT
                # =================================================

                if not student:

                    # =============================================
                    # BRANCH
                    # =============================================

                    student_branch_id = (
                        import_branch_id
                    )

                    if not student_branch_id:

                        csv_branch_value = clean(
                            row.get("Branch")
                        )

                        if csv_branch_value:

                            branch_obj = resolve_model(
                                Branch,
                                csv_branch_value,
                                "Branch",
                                institution_id=(
                                    institution_id
                                ),
                            )

                            student_branch_id = (
                                branch_obj.id
                            )

                    if not student_branch_id:

                        raise ValueError(
                            "Student branch could "
                            "not be determined."
                        )

                    # ---------------------------------------------
                    # BRANCH SECURITY
                    # ---------------------------------------------

                    if role == "branch_admin":

                        if (
                            student_branch_id
                            != user_branch_id
                        ):

                            raise ValueError(
                                "You cannot import "
                                "students into another branch."
                            )

                    # =================================================
                    # USERNAME
                    # =================================================

                    username = clean(
                        row.get("Username")
                    )

                    if not username:

                        username = (
                            generate_unique_username(
                                full_name,
                                admission_no
                            )
                        )

                    else:

                        username_exists = (
                            Student.query
                            .filter(
                                db.func.lower(
                                    Student.username
                                )
                                == username.lower()
                            )
                            .first()
                        )

                        if username_exists:

                            raise ValueError(
                                f"Username "
                                f"'{username}' "
                                f"already exists."
                            )

                    # =================================================
                    # EMAIL
                    # =================================================

                    email = clean(
                        row.get("Email")
                    )

                    if email:

                        email_exists = (
                            Student.query
                            .filter(
                                db.func.lower(
                                    Student.email
                                )
                                == email.lower()
                            )
                            .first()
                        )

                        if email_exists:

                            raise ValueError(
                                f"Email '{email}' "
                                f"already exists."
                            )

                    else:

                        email = (
                            generate_unique_email(
                                admission_no
                            )
                        )

                    # =================================================
                    # ROLL NUMBER
                    # =================================================

                    roll_no = clean(
                        row.get("Roll No")
                    )

                    if not roll_no:

                        roll_no = (
                            generate_unique_roll_no()
                        )

                    # =================================================
                    # PASSWORD
                    # =================================================

                    temporary_password = (
                        generate_student_password()
                    )

                    # =================================================
                    # CREATE STUDENT
                    # =================================================

                    student = Student(

                        institution_id=(
                            institution_id
                        ),

                        branch_id=(
                            student_branch_id
                        ),

                        username=username,

                        email=email,

                        admission_no=(
                            admission_no
                        ),

                        roll_no=roll_no,

                        full_name=full_name,

                        gender=clean(
                            row.get("Gender")
                        ),

                        date_of_birth=parse_date(
                            row.get(
                                "Date of Birth"
                            ),
                            "Date of Birth"
                        ),

                        place_of_birth=clean(
                            row.get(
                                "Place of Birth"
                            )
                        ),

                        nationality=clean(
                            row.get(
                                "Nationality"
                            )
                        ),

                        phone=clean(
                            row.get("Phone")
                        ),

                        address=clean(
                            row.get("Address")
                        ),

                        city=clean(
                            row.get("City")
                        ),

                        parent_name=clean(
                            row.get(
                                "Parent Name"
                            )
                        ),

                        parent_phone=clean(
                            row.get(
                                "Parent Phone"
                            )
                        ),

                        parent_email=clean(
                            row.get(
                                "Parent Email"
                            )
                        ),

                        parent_address=clean(
                            row.get(
                                "Parent Address"
                            )
                        ),

                        relationship_to_student=clean(
                            row.get(
                                "Relationship to Student"
                            )
                        ),

                        status=student_status,

                        notes=clean(
                            row.get(
                                "Student Notes"
                            )
                        ),

                        role="student",

                        is_active=(
                            student_status
                            == "active"
                        ),

                        is_verified=False,
                    )

                    # ---------------------------------------------
                    # HASH PASSWORD
                    # ---------------------------------------------

                    student.set_password(
                        temporary_password
                    )

                    db.session.add(
                        student
                    )

                    db.session.flush()

                    created_students += 1

                    # ---------------------------------------------
                    # SAVE GENERATED LOGIN DETAILS
                    # ---------------------------------------------

                    generated_credentials.append({

                        "row": row_number,

                        "student_id": (
                            student.id
                        ),

                        "full_name": (
                            student.full_name
                        ),

                        "admission_no": (
                            student.admission_no
                        ),

                        "roll_no": (
                            student.roll_no
                        ),

                        "username": (
                            student.username
                        ),

                        "email": (
                            student.email
                        ),

                        "password": (
                            temporary_password
                        ),
                    })

                # =================================================
                # EXISTING STUDENT
                # =================================================

                else:

                    # ---------------------------------------------
                    # ACCESS CHECK
                    # ---------------------------------------------

                    if not _student_has_access(
                        student
                    ):

                        raise ValueError(
                            f"Access denied for "
                            f"student "
                            f"'{admission_no}'."
                        )

                    # ---------------------------------------------
                    # Branch
                    # ---------------------------------------------

                    if role == "branch_admin":

                        if (
                            student.branch_id
                            != user_branch_id
                        ):

                            raise ValueError(
                                "You cannot update "
                                "a student from "
                                "another branch."
                            )

                    # ---------------------------------------------
                    # Optional username
                    # ---------------------------------------------

                    csv_username = clean(
                        row.get("Username")
                    )

                    if csv_username:

                        username_exists = (
                            Student.query
                            .filter(
                                db.func.lower(
                                    Student.username
                                )
                                == csv_username.lower(),

                                Student.id
                                != student.id,
                            )
                            .first()
                        )

                        if username_exists:

                            raise ValueError(
                                f"Username "
                                f"'{csv_username}' "
                                f"already belongs "
                                f"to another student."
                            )

                        student.username = (
                            csv_username
                        )

                    # ---------------------------------------------
                    # Optional email
                    # ---------------------------------------------

                    csv_email = clean(
                        row.get("Email")
                    )

                    if csv_email:

                        email_exists = (
                            Student.query
                            .filter(
                                db.func.lower(
                                    Student.email
                                )
                                == csv_email.lower(),

                                Student.id
                                != student.id,
                            )
                            .first()
                        )

                        if email_exists:

                            raise ValueError(
                                f"Email "
                                f"'{csv_email}' "
                                f"already belongs "
                                f"to another student."
                            )

                        student.email = (
                            csv_email
                        )

                    # ---------------------------------------------
                    # Roll No
                    # ---------------------------------------------

                    csv_roll_no = clean(
                        row.get("Roll No")
                    )

                    if csv_roll_no:

                        student.roll_no = (
                            csv_roll_no
                        )

                    # ---------------------------------------------
                    # Full name
                    # ---------------------------------------------

                    student.full_name = (
                        full_name
                    )

                    # ---------------------------------------------
                    # Personal information
                    # ---------------------------------------------

                    if clean(
                        row.get("Gender")
                    ):

                        student.gender = clean(
                            row.get("Gender")
                        )

                    dob = parse_date(
                        row.get(
                            "Date of Birth"
                        ),
                        "Date of Birth"
                    )

                    if dob:

                        student.date_of_birth = (
                            dob
                        )

                    if clean(
                        row.get(
                            "Place of Birth"
                        )
                    ):

                        student.place_of_birth = (
                            clean(
                                row.get(
                                    "Place of Birth"
                                )
                            )
                        )

                    if clean(
                        row.get(
                            "Nationality"
                        )
                    ):

                        student.nationality = (
                            clean(
                                row.get(
                                    "Nationality"
                                )
                            )
                        )

                    if clean(
                        row.get("Phone")
                    ):

                        student.phone = clean(
                            row.get("Phone")
                        )

                    if clean(
                        row.get("Address")
                    ):

                        student.address = clean(
                            row.get("Address")
                        )

                    if clean(
                        row.get("City")
                    ):

                        student.city = clean(
                            row.get("City")
                        )

                    # ---------------------------------------------
                    # Parent
                    # ---------------------------------------------

                    if clean(
                        row.get("Parent Name")
                    ):

                        student.parent_name = clean(
                            row.get("Parent Name")
                        )

                    if clean(
                        row.get("Parent Phone")
                    ):

                        student.parent_phone = clean(
                            row.get("Parent Phone")
                        )

                    if clean(
                        row.get("Parent Email")
                    ):

                        student.parent_email = clean(
                            row.get("Parent Email")
                        )

                    if clean(
                        row.get("Parent Address")
                    ):

                        student.parent_address = clean(
                            row.get("Parent Address")
                        )

                    if clean(
                        row.get(
                            "Relationship to Student"
                        )
                    ):

                        student.relationship_to_student = (
                            clean(
                                row.get(
                                    "Relationship to Student"
                                )
                            )
                        )

                    # ---------------------------------------------
                    # Status
                    # ---------------------------------------------

                    student.status = (
                        student_status
                    )

                    student.is_active = (
                        student_status
                        == "active"
                    )

                    if clean(
                        row.get(
                            "Student Notes"
                        )
                    ):

                        student.notes = clean(
                            row.get(
                                "Student Notes"
                            )
                        )

                    db.session.flush()

                    updated_students += 1

                # =================================================
                # EFFECTIVE BRANCH
                # =================================================

                effective_branch_id = (
                    student.branch_id
                )

                if not effective_branch_id:

                    raise ValueError(
                        "Student branch could "
                        "not be determined."
                    )

                # =================================================
                # ACADEMIC YEAR
                # =================================================

                academic_year = resolve_model(
                    AcademicYear,

                    row.get(
                        "Academic Year"
                    ),

                    "Academic Year",

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        effective_branch_id
                    ),
                )

                # =================================================
                # PROGRAM
                # =================================================

                program = resolve_model(
                    Program,

                    row.get(
                        "Program"
                    ),

                    "Program",

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        effective_branch_id
                    ),
                )

                # =================================================
                # CLASS
                # =================================================

                class_obj = resolve_model(
                    Class,

                    row.get(
                        "Class"
                    ),

                    "Class",

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        effective_branch_id
                    ),
                )

                # =================================================
                # SECTION
                # =================================================

                section_value = clean(
                    row.get(
                        "Section"
                    )
                )

                section = None

                if section_value:

                    section = resolve_model(
                        Section,

                        section_value,

                        "Section",

                        institution_id=(
                            institution_id
                        ),

                        branch_id=(
                            effective_branch_id
                        ),
                    )

                # =================================================
                # ENROLLMENT
                # =================================================

                enrollment_no = clean(
                    row.get(
                        "Enrollment No"
                    )
                )

                if not enrollment_no:

                    raise ValueError(
                        "Enrollment No is required."
                    )

                enrollment_date = (
                    parse_date(
                        row.get(
                            "Enrollment Date"
                        ),
                        "Enrollment Date"
                    )
                    or date.today()
                )

                enrollment_status = (
                    clean(
                        row.get(
                            "Enrollment Status"
                        )
                    )
                    or "active"
                ).lower()

                allowed_enrollment_statuses = {
                    "active",
                    "completed",
                    "transferred",
                    "withdrawn",
                    "suspended",
                    "promoted",
                }

                if enrollment_status not in (
                    allowed_enrollment_statuses
                ):

                    raise ValueError(
                        f"Invalid Enrollment Status "
                        f"'{enrollment_status}'."
                    )

                # =================================================
                # EXISTING ENROLLMENT
                # =================================================

                enrollment = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.student_id
                        == student.id,

                        StudentEnrollment.academic_year_id
                        == academic_year.id,
                    )
                    .first()
                )

                if enrollment:

                    enrollment.branch_id = (
                        effective_branch_id
                    )

                    enrollment.program_id = (
                        program.id
                    )

                    enrollment.class_id = (
                        class_obj.id
                    )

                    enrollment.section_id = (
                        section.id
                        if section
                        else None
                    )

                    enrollment.enrollment_no = (
                        enrollment_no
                    )

                    enrollment.enrollment_date = (
                        enrollment_date
                    )

                    enrollment.status = (
                        enrollment_status
                    )

                    enrollment.notes = clean(
                        row.get(
                            "Enrollment Notes"
                        )
                    )

                    db.session.flush()

                    updated_enrollments += 1

                # =================================================
                # NEW ENROLLMENT
                # =================================================

                else:

                    enrollment_no_exists = (
                        StudentEnrollment.query
                        .filter(
                            StudentEnrollment
                            .institution_id
                            == institution_id,

                            StudentEnrollment
                            .enrollment_no
                            == enrollment_no,
                        )
                        .first()
                    )

                    if enrollment_no_exists:

                        raise ValueError(
                            f"Enrollment No "
                            f"'{enrollment_no}' "
                            f"already exists."
                        )

                    enrollment = (
                        StudentEnrollment(

                            institution_id=(
                                institution_id
                            ),

                            branch_id=(
                                effective_branch_id
                            ),

                            student_id=(
                                student.id
                            ),

                            academic_year_id=(
                                academic_year.id
                            ),

                            program_id=(
                                program.id
                            ),

                            class_id=(
                                class_obj.id
                            ),

                            section_id=(
                                section.id
                                if section
                                else None
                            ),

                            enrollment_no=(
                                enrollment_no
                            ),

                            enrollment_date=(
                                enrollment_date
                            ),

                            status=(
                                enrollment_status
                            ),

                            notes=clean(
                                row.get(
                                    "Enrollment Notes"
                                )
                            ),
                        )
                    )

                    db.session.add(
                        enrollment
                    )

                    db.session.flush()

                    created_enrollments += 1

                # =================================================
                # CHARGE
                # =================================================

                charge_type = (
                    clean(
                        row.get(
                            "Charge Type"
                        )
                    )
                    or "other"
                ).lower()

                allowed_charge_types = {
                    "registration",
                    "program_fee",
                    "tuition",
                    "exam",
                    "admission",
                    "id_card",
                    "uniform",
                    "books",
                    "transport",
                    "laboratory",
                    "library",
                    "certificate",
                    "other",
                }

                if charge_type not in (
                    allowed_charge_types
                ):

                    raise ValueError(
                        f"Invalid Charge Type "
                        f"'{charge_type}'."
                    )

                charge_name = clean(
                    row.get(
                        "Charge Name"
                    )
                )

                if not charge_name:

                    raise ValueError(
                        "Charge Name is required."
                    )

                amount = decimal_value(
                    row.get(
                        "Amount"
                    ),
                    "Amount"
                )

                discount = decimal_value(
                    row.get(
                        "Discount"
                    ),
                    "Discount"
                )

                paid_amount = decimal_value(
                    row.get(
                        "Paid Amount"
                    ),
                    "Paid Amount"
                )

                if discount > amount:

                    raise ValueError(
                        "Discount cannot be greater "
                        "than Amount."
                    )

                net_amount = (
                    amount - discount
                )

                if paid_amount > net_amount:

                    raise ValueError(
                        "Paid Amount cannot be "
                        "greater than Net Amount."
                    )

                balance = (
                    net_amount
                    - paid_amount
                )

                if balance <= 0:

                    charge_status = "paid"

                elif paid_amount > 0:

                    charge_status = "partial"

                else:

                    charge_status = "unpaid"

                due_date = parse_date(
                    row.get(
                        "Due Date"
                    ),
                    "Due Date"
                )

                charge = StudentCharge(

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        effective_branch_id
                    ),

                    student_id=(
                        student.id
                    ),

                    enrollment_id=(
                        enrollment.id
                    ),

                    academic_year_id=(
                        academic_year.id
                    ),

                    charge_type=(
                        charge_type
                    ),

                    charge_name=(
                        charge_name
                    ),

                    description=clean(
                        row.get(
                            "Charge Description"
                        )
                    ),

                    amount=amount,

                    discount=discount,

                    net_amount=net_amount,

                    paid_amount=paid_amount,

                    balance=balance,

                    due_date=due_date,

                    status=charge_status,

                    created_by=(
                        current_user_obj.id
                        if getattr(
                            current_user_obj,
                            "id",
                            None
                        )
                        else None
                    ),
                )

                db.session.add(
                    charge
                )

                db.session.flush()

                created_charges += 1

            # ====================================================
            # ROW ERROR
            # ====================================================

            except Exception as row_error:

                errors.append(
                    f"Row {row_number}: "
                    f"{str(row_error)}"
                )

                raise

        # ========================================================
        # COMMIT
        # ========================================================

        db.session.commit()

    # ========================================================
    # ROLLBACK
    # ========================================================

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "Student full CSV import failed: %s",
            exc
        )

        error_message = (
            errors[0]
            if errors
            else str(exc)
        )

        flash(
            "Import failed. No records were saved. "
            + error_message,
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # SAVE GENERATED CREDENTIALS FOR DISPLAY
    # ========================================================
    #
    # Passwords are NOT stored in database as plain text.
    # They are only temporarily stored in session so an
    # admin can see/download them after import.
    #
    # ========================================================

    if generated_credentials:

        session[
            "student_import_credentials"
        ] = generated_credentials

    # ========================================================
    # SUCCESS MESSAGE
    # ========================================================

    flash(
        "Student import completed successfully. "
        f"Students created: {created_students}, "
        f"students updated: {updated_students}, "
        f"enrollments created: {created_enrollments}, "
        f"enrollments updated: {updated_enrollments}, "
        f"charges created: {created_charges}.",
        "success"
    )

    # ========================================================
    # REDIRECT
    # ========================================================

    return redirect(
        url_for(
            "main.student_import_credentials"
        )
        if generated_credentials
        else url_for(
            "main.all_students"
        )
    )

# ============================================================
# EXAM ROLE SECURITY
# ============================================================

EXAM_MANAGE_ROLES = {
    "superadmin",
    "school_admin",
    "branch_admin",
}

EXAM_VIEW_ROLES = {
    "superadmin",
    "school_admin",
    "branch_admin",
    "teacher",
}


def _exam_can_manage():
    """
    Exam create/edit/delete access.
    """

    return getattr(current_user, "role", None) in EXAM_MANAGE_ROLES


def _exam_can_view():
    """
    Exam view access.
    """

    return getattr(current_user, "role", None) in EXAM_VIEW_ROLES


# ============================================================
# EXAM ACCESS FILTER
# ============================================================

def _exam_scope_query(query):
    """
    Restrict exams according to logged-in user's institution/branch.

    superadmin:
        Can see all exams.

    school_admin:
        Can see exams belonging to their institution.

    branch_admin / teacher:
        Can see exams belonging to their branch.
    """

    role = getattr(current_user, "role", None)

    if role == "superadmin":
        return query

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if role == "school_admin":

        if not institution_id:
            return query.filter(
                db.literal(False)
            )

        return query.filter(
            Exam.institution_id == institution_id
        )

    if role in {
        "branch_admin",
        "teacher",
    }:

        if not institution_id or not branch_id:
            return query.filter(
                db.literal(False)
            )

        return query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    return query.filter(
        db.literal(False)
    )



# ============================================================
# ALL EXAMS
# ============================================================

@bp.route("/exams", methods=["GET"])
@login_required
def all_exams():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to access examinations.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # SCHOOL ADMIN / BRANCH ADMIN MUST HAVE INSTITUTION
    # ========================================================

    if current_role in {
        "school_admin",
        "branch_admin",
    }:

        if not user_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # BRANCH ADMIN MUST HAVE BRANCH
    # ========================================================

    if current_role == "branch_admin":

        if not user_branch_id:

            flash(
                "Your account is not assigned to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # REQUEST FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    term_id = request.args.get(
        "term_id",
        type=int
    )

    exam_type = request.args.get(
        "exam_type",
        "",
        type=str
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip()

    # ========================================================
    # PER PAGE
    # ========================================================

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # PAGE
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = (
        Exam.query
        .options(
            db.joinedload(
                Exam.institution
            ),

            db.joinedload(
                Exam.branch
            ),

            db.joinedload(
                Exam.program
            ),

            db.joinedload(
                Exam.assessment_plan
            ),

            db.joinedload(
                Exam.academic_year
            ),

            db.joinedload(
                Exam.term
            ),
        )
    )

    # ========================================================
    # ROLE DATA SCOPE
    # ========================================================

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":

        if institution_id:

            query = query.filter(
                Exam.institution_id
                == institution_id
            )

        if branch_id:

            query = query.filter(
                Exam.branch_id
                == branch_id
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        # NEVER allow another institution
        query = query.filter(
            Exam.institution_id
            == user_institution_id
        )

        # If branch selected, it must belong
        # to this institution.
        if branch_id:

            valid_branch = (
                Branch.query
                .filter(
                    Branch.id == branch_id,
                    Branch.institution_id
                    == user_institution_id
                )
                .first()
            )

            if not valid_branch:

                flash(
                    "You do not have permission to access this branch.",
                    "danger"
                )

                return redirect(
                    url_for("main.all_exams")
                )

            query = query.filter(
                Exam.branch_id == branch_id
            )

        institution_id = user_institution_id

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        # Branch admin is locked to:
        #
        # institution_id = current user's institution
        # branch_id      = current user's branch

        query = query.filter(
            Exam.institution_id
            == user_institution_id,

            Exam.branch_id
            == user_branch_id
        )

        # Ignore manipulated URL values.
        institution_id = user_institution_id
        branch_id = user_branch_id

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_pattern = f"%{search}%"

        query = query.filter(
            db.or_(
                Exam.name.ilike(
                    search_pattern
                ),

                Exam.code.ilike(
                    search_pattern
                ),

                Exam.description.ilike(
                    search_pattern
                ),
            )
        )

    # ========================================================
    # PROGRAM FILTER
    # ========================================================

    if program_id:

        program_query = (
            Program.query
            .filter(
                Program.id == program_id
            )
        )

        # Non-superadmin cannot use
        # another institution's program.

        if current_role != "superadmin":

            program_query = program_query.filter(
                Program.institution_id
                == user_institution_id
            )

        elif institution_id:

            program_query = program_query.filter(
                Program.institution_id
                == institution_id
            )

        valid_program = (
            program_query.first()
        )

        if valid_program:

            query = query.filter(
                Exam.program_id
                == program_id
            )

        else:

            # Invalid program for this user's scope
            query = query.filter(
                db.false()
            )

    # ========================================================
    # ACADEMIC YEAR FILTER
    # ========================================================

    if academic_year_id:

        academic_year_query = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
        )

        if current_role != "superadmin":

            academic_year_query = (
                academic_year_query
                .filter(
                    AcademicYear.institution_id
                    == user_institution_id
                )
            )

        elif institution_id:

            academic_year_query = (
                academic_year_query
                .filter(
                    AcademicYear.institution_id
                    == institution_id
                )
            )

        valid_academic_year = (
            academic_year_query.first()
        )

        if valid_academic_year:

            query = query.filter(
                Exam.academic_year_id
                == academic_year_id
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # TERM FILTER
    # ========================================================

    if term_id:

        term_query = (
            Term.query
            .filter(
                Term.id == term_id
            )
        )

        if current_role != "superadmin":

            term_query = term_query.filter(
                Term.institution_id
                == user_institution_id
            )

        elif institution_id:

            term_query = term_query.filter(
                Term.institution_id
                == institution_id
            )

        if academic_year_id:

            term_query = term_query.filter(
                Term.academic_year_id
                == academic_year_id
            )

        valid_term = (
            term_query.first()
        )

        if valid_term:

            query = query.filter(
                Exam.term_id == term_id
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # EXAM TYPE
    # ========================================================

    allowed_exam_types = {
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    }

    if exam_type:

        if exam_type in allowed_exam_types:

            query = query.filter(
                Exam.exam_type
                == exam_type
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # STATUS
    # ========================================================

    allowed_statuses = {
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    }

    if status:

        if status in allowed_statuses:

            query = query.filter(
                Exam.status == status
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        Exam.start_date.asc().nullslast(),
        Exam.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    exams = pagination.items

    # ========================================================
    # INSTITUTIONS DROPDOWN
    # ========================================================

    if current_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == user_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ========================================================
    # BRANCHES DROPDOWN
    # ========================================================

    if current_role == "superadmin":

        branch_query = Branch.query

        if institution_id:

            branch_query = (
                branch_query
                .filter(
                    Branch.institution_id
                    == institution_id
                )
            )

    elif current_role == "school_admin":

        branch_query = (
            Branch.query
            .filter(
                Branch.institution_id
                == user_institution_id
            )
        )

    else:

        # branch_admin sees ONLY own branch
        branch_query = (
            Branch.query
            .filter(
                Branch.id
                == user_branch_id,

                Branch.institution_id
                == user_institution_id
            )
        )

    branches = (
        branch_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS DROPDOWN
    # ========================================================

    program_query = Program.query

    if current_role != "superadmin":

        program_query = (
            program_query
            .filter(
                Program.institution_id
                == user_institution_id
            )
        )

    elif institution_id:

        program_query = (
            program_query
            .filter(
                Program.institution_id
                == institution_id
            )
        )

    programs = (
        program_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACADEMIC YEARS DROPDOWN
    # ========================================================

    academic_year_query = (
        AcademicYear.query
    )

    if current_role != "superadmin":

        academic_year_query = (
            academic_year_query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
        )

    elif institution_id:

        academic_year_query = (
            academic_year_query
            .filter(
                AcademicYear.institution_id
                == institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # TERMS DROPDOWN
    # ========================================================

    term_query = Term.query

    if current_role != "superadmin":

        term_query = (
            term_query
            .filter(
                Term.institution_id
                == user_institution_id
            )
        )

    elif institution_id:

        term_query = (
            term_query
            .filter(
                Term.institution_id
                == institution_id
            )
        )

    if academic_year_id:

        term_query = (
            term_query
            .filter(
                Term.academic_year_id
                == academic_year_id
            )
        )

    terms = (
        term_query
        .order_by(
            Term.id.desc()
        )
        .all()
    )

    # ========================================================
    # STATUS COUNTS
    #
    # Counts are based on USER'S DATA SCOPE,
    # not on arbitrary URL filters.
    # ========================================================

    count_query = Exam.query

    # --------------------------------------------------------
    # SUPERADMIN COUNT SCOPE
    # --------------------------------------------------------

    if current_role == "superadmin":

        if institution_id:

            count_query = count_query.filter(
                Exam.institution_id
                == institution_id
            )

        if branch_id:

            count_query = count_query.filter(
                Exam.branch_id
                == branch_id
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN COUNT SCOPE
    # --------------------------------------------------------

    elif current_role == "school_admin":

        count_query = count_query.filter(
            Exam.institution_id
            == user_institution_id
        )

        if branch_id:

            count_query = count_query.filter(
                Exam.branch_id
                == branch_id
            )

    # --------------------------------------------------------
    # BRANCH ADMIN COUNT SCOPE
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        count_query = count_query.filter(
            Exam.institution_id
            == user_institution_id,

            Exam.branch_id
            == user_branch_id
        )

    # ========================================================
    # COUNTS
    # ========================================================

    total_count = (
        count_query
        .count()
    )

    draft_count = (
        count_query
        .filter(
            Exam.status == "draft"
        )
        .count()
    )

    scheduled_count = (
        count_query
        .filter(
            Exam.status == "scheduled"
        )
        .count()
    )

    ongoing_count = (
        count_query
        .filter(
            Exam.status == "ongoing"
        )
        .count()
    )

    completed_count = (
        count_query
        .filter(
            Exam.status == "completed"
        )
        .count()
    )

    published_count = (
        count_query
        .filter(
            Exam.status == "published"
        )
        .count()
    )

    cancelled_count = (
        count_query
        .filter(
            Exam.status == "cancelled"
        )
        .count()
    )

    # ========================================================
    # EXAM TYPES
    # ========================================================

    exam_types = [
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    ]

    # ========================================================
    # STATUSES
    # ========================================================

    statuses = [
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    ]

    # ========================================================
    # RENDER TEMPLATE
    # ========================================================

    return render_template(
        "backend/pages/exams/all_exams.html",

        # ----------------------------------------------------
        # DATA
        # ----------------------------------------------------

        exams=exams,
        pagination=pagination,

        # ----------------------------------------------------
        # CURRENT ROLE
        # ----------------------------------------------------

        current_role=current_role,
        user=current_user,

        # ----------------------------------------------------
        # FILTER VALUES
        # ----------------------------------------------------

        search=search,

        institution_id=(
            institution_id
        ),

        branch_id=(
            branch_id
        ),

        program_id=(
            program_id
        ),

        academic_year_id=(
            academic_year_id
        ),

        term_id=(
            term_id
        ),

        exam_type=(
            exam_type
        ),

        status=(
            status
        ),

        per_page=(
            per_page
        ),

        # ----------------------------------------------------
        # DROPDOWNS
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        programs=programs,

        academic_years=academic_years,

        terms=terms,

        # ----------------------------------------------------
        # OPTIONS
        # ----------------------------------------------------

        exam_types=exam_types,

        statuses=statuses,

        # ----------------------------------------------------
        # STATISTICS
        # ----------------------------------------------------

        total_count=total_count,

        draft_count=draft_count,

        scheduled_count=scheduled_count,

        ongoing_count=ongoing_count,

        completed_count=completed_count,

        published_count=published_count,

        cancelled_count=cancelled_count,
    )




# ============================================================
# ADD EXAM
# ============================================================

@bp.route(
    "/exams/add",
    methods=["GET", "POST"]
)
@login_required
def add_exam():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # ROLE / USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # EXAM TYPE
    # ========================================================

    allowed_exam_types = {
        "term",
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    }

    # ========================================================
    # EXAM STATUS
    # ========================================================

    allowed_statuses = {
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    }

    # ========================================================
    # GET DATA FOR FORM
    # ========================================================

    institutions_query = Institution.query

    branches_query = Branch.query

    programs_query = Program.query

    assessment_plans_query = AssessmentPlan.query

    academic_years_query = AcademicYear.query

    terms_query = Term.query

    # ========================================================
    # ROLE SCOPE
    # ========================================================

    if current_role != "superadmin":

        if not user_institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        institutions_query = institutions_query.filter(
            Institution.id == user_institution_id
        )

        branches_query = branches_query.filter(
            Branch.institution_id == user_institution_id
        )

        programs_query = programs_query.filter(
            Program.institution_id == user_institution_id
        )

        # ----------------------------------------------------
        # Assessment Plans
        # ----------------------------------------------------

        if hasattr(
            AssessmentPlan,
            "institution_id"
        ):
            assessment_plans_query = (
                assessment_plans_query.filter(
                    AssessmentPlan.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # Academic Years
        # ----------------------------------------------------

        if hasattr(
            AcademicYear,
            "institution_id"
        ):
            academic_years_query = (
                academic_years_query.filter(
                    AcademicYear.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # Branch Admin
        # ----------------------------------------------------

        if (
            current_role == "branch_admin"
            and user_branch_id
        ):

            branches_query = branches_query.filter(
                Branch.id == user_branch_id
            )

            # Programs may either have:
            #
            # 1. branch_id = current branch
            # 2. branch_id = NULL
            #
            # NULL means the program can be used
            # in multiple branches.

            programs_query = programs_query.filter(
                db.or_(
                    Program.branch_id == user_branch_id,
                    Program.branch_id.is_(None)
                )
            )

    # ========================================================
    # EXECUTE GET QUERIES
    # ========================================================

    institutions = (
        institutions_query
        .order_by(Institution.name.asc())
        .all()
    )

    branches = (
        branches_query
        .order_by(Branch.name.asc())
        .all()
    )

    programs = (
        programs_query
        .order_by(Program.name.asc())
        .all()
    )

    assessment_plans = (
        assessment_plans_query
        .order_by(AssessmentPlan.name.asc())
        .all()
    )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    terms = (
        terms_query
        .order_by(
            Term.id.desc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # GET FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        # ----------------------------------------------------
        # OPTIONAL ASSESSMENT PLAN
        # ----------------------------------------------------

        assessment_plan_id = request.form.get(
            "assessment_plan_id",
            type=int
        )

        # Empty string should become None
        if not assessment_plan_id:
            assessment_plan_id = None

        # ----------------------------------------------------
        # ACADEMIC YEAR
        # ----------------------------------------------------

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        # ----------------------------------------------------
        # TERM
        # ----------------------------------------------------

        term_id = request.form.get(
            "term_id",
            type=int
        )

        # ----------------------------------------------------
        # EXAM INFORMATION
        # ----------------------------------------------------

        name = (
            request.form.get("name", "")
            .strip()
        )

        code = (
            request.form.get("code", "")
            .strip()
            .upper()
        )

        exam_type = (
            request.form.get(
                "exam_type",
                "term"
            )
            .strip()
            .lower()
        )

        description = (
            request.form.get(
                "description",
                ""
            )
            .strip()
        )

        # ----------------------------------------------------
        # DATES
        # ----------------------------------------------------

        start_date = (
            request.form.get(
                "start_date",
                ""
            )
            .strip()
        )

        end_date = (
            request.form.get(
                "end_date",
                ""
            )
            .strip()
        )

        # ----------------------------------------------------
        # STATUS
        # ----------------------------------------------------

        status = (
            request.form.get(
                "status",
                "draft"
            )
            .strip()
            .lower()
        )

        # ====================================================
        # BASIC VALIDATION
        # ====================================================

        if not institution_id:
            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not branch_id:
            flash(
                "Please select a branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not program_id:
            flash(
                "Please select a program.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not academic_year_id:
            flash(
                "Please select an academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not name:
            flash(
                "Exam name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # EXAM TYPE VALIDATION
        # ====================================================

        if exam_type not in allowed_exam_types:

            flash(
                "Invalid exam type selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # STATUS VALIDATION
        # ====================================================

        if status not in allowed_statuses:

            flash(
                "Invalid exam status selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # GET INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # USER INSTITUTION SECURITY
        # ====================================================

        if (
            current_role != "superadmin"
            and institution.id != user_institution_id
        ):

            abort(403)

        # ====================================================
        # GET BRANCH
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id
            )
            .first()
        )

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # BRANCH → INSTITUTION
        # ====================================================

        if branch.institution_id != institution.id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # BRANCH ADMIN SECURITY
        # ====================================================

        if (
            current_role == "branch_admin"
            and user_branch_id
            and branch.id != user_branch_id
        ):

            abort(403)

        # ====================================================
        # GET PROGRAM
        # ====================================================

        program = (
            Program.query
            .filter(
                Program.id == program_id
            )
            .first()
        )

        if not program:

            flash(
                "Selected program was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # PROGRAM → INSTITUTION
        # ====================================================

        if program.institution_id != institution.id:

            flash(
                "Selected program does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # PROGRAM → BRANCH
        #
        # branch_id = NULL means multi-branch program
        # ====================================================

        if (
            getattr(program, "branch_id", None)
            and program.branch_id != branch.id
        ):

            flash(
                "Selected program is not available in this branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # GET ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id == academic_year_id
            )
            .first()
        )

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # ACADEMIC YEAR → INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution.id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

        # ====================================================
        # OPTIONAL TERM VALIDATION
        # ====================================================

        term = None

        if term_id:

            term = (
                Term.query
                .filter(
                    Term.id == term_id
                )
                .first()
            )

            if not term:

                flash(
                    "Selected term was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

            # ------------------------------------------------
            # TERM → ACADEMIC YEAR
            # ------------------------------------------------

            if hasattr(
                Term,
                "academic_year_id"
            ):

                if (
                    term.academic_year_id
                    != academic_year.id
                ):

                    flash(
                        "Selected term does not belong to the selected academic year.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

        # ====================================================
        # OPTIONAL ASSESSMENT PLAN
        # ====================================================

        assessment_plan = None

        if assessment_plan_id:

            assessment_plan = (
                AssessmentPlan.query
                .filter(
                    AssessmentPlan.id
                    == assessment_plan_id
                )
                .first()
            )

            if not assessment_plan:

                flash(
                    "Selected assessment plan was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

            # ------------------------------------------------
            # ASSESSMENT PLAN → INSTITUTION
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "institution_id"
            ):

                if (
                    assessment_plan.institution_id
                    != institution.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected institution.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

            # ------------------------------------------------
            # ASSESSMENT PLAN → PROGRAM
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "program_id"
            ):

                if (
                    assessment_plan.program_id
                    != program.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected program.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

        # ====================================================
        # DATE VALIDATION
        # ====================================================

        parsed_start_date = None
        parsed_end_date = None

        if start_date:

            try:
                parsed_start_date = datetime.strptime(
                    start_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                flash(
                    "Invalid start date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

        if end_date:

            try:
                parsed_end_date = datetime.strptime(
                    end_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                flash(
                    "Invalid end date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

        if (
            parsed_start_date
            and parsed_end_date
            and parsed_end_date < parsed_start_date
        ):

            flash(
                "End date cannot be earlier than start date.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # GENERATE CODE IF EMPTY
        # ====================================================

        if not code:

            # ------------------------------------------------
            # PROGRAM CODE
            # ------------------------------------------------

            program_code = (
                getattr(
                    program,
                    "code",
                    None
                )
                or getattr(
                    program,
                    "short_name",
                    None
                )
                or getattr(
                    program,
                    "name",
                    "PRG"
                )
            )

            # ------------------------------------------------
            # ACADEMIC YEAR CODE
            # ------------------------------------------------

            year_code = (
                getattr(
                    academic_year,
                    "name",
                    None
                )
                or getattr(
                    academic_year,
                    "code",
                    None
                )
                or getattr(
                    academic_year,
                    "academic_year",
                    None
                )
                or str(
                    academic_year.id
                )
            )

            # ------------------------------------------------
            # EXAM TYPE CODE
            # ------------------------------------------------

            exam_type_codes = {
                "term": "TERM",
                "monthly": "MON",
                "bi_monthly": "BIM",
                "quarterly": "QTR",
                "semester": "SEM",
                "midterm": "MID",
                "final": "FIN",
                "annual": "ANN",
                "mock": "MOCK",
                "entrance": "ENT",
                "supplementary": "SUP",
                "resit": "RES",
                "special": "SPC",
            }

            type_code = exam_type_codes.get(
                exam_type,
                exam_type.upper()[:5]
            )

            # ------------------------------------------------
            # CLEAN CODE
            # ------------------------------------------------

            import re

            program_code = re.sub(
                r"[^A-Z0-9]+",
                "-",
                str(
                    program_code
                ).upper()
            ).strip("-")

            if not program_code:
                program_code = "PRG"

            program_code = program_code[:12]

            year_code = re.sub(
                r"[^A-Z0-9]+",
                "-",
                str(
                    year_code
                ).upper()
            ).strip("-")

            if not year_code:
                year_code = str(
                    academic_year.id
                )

            # ------------------------------------------------
            # BASE CODE
            # ------------------------------------------------

            base_code = (
                f"{program_code}-"
                f"{type_code}-"
                f"{year_code}"
            )

            # ------------------------------------------------
            # UNIQUE SEQUENCE
            # ------------------------------------------------

            sequence = 1

            while True:

                generated_code = (
                    f"{base_code}-"
                    f"{sequence:03d}"
                )

                existing_exam = (
                    Exam.query
                    .filter(
                        Exam.code
                        == generated_code
                    )
                    .first()
                )

                if not existing_exam:
                    code = generated_code
                    break

                sequence += 1

                if sequence > 9999:

                    flash(
                        "Unable to generate a unique exam code.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

        # ====================================================
        # CODE DUPLICATE CHECK
        # ====================================================

        existing_code = (
            Exam.query
            .filter(
                db.func.upper(
                    Exam.code
                ) == code.upper()
            )
            .first()
        )

        if existing_code:

            flash(
                f"Exam code '{code}' already exists.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # CREATE EXAM
        # ====================================================

        exam = Exam(
            institution_id=institution.id,
            branch_id=branch.id,
            program_id=program.id,

            # Optional
            assessment_plan_id=(
                assessment_plan.id
                if assessment_plan
                else None
            ),

            academic_year_id=academic_year.id,

            # Optional
            term_id=(
                term.id
                if term
                else None
            ),

            name=name,
            code=code,
            exam_type=exam_type,
            description=(
                description
                if description
                else None
            ),

            start_date=parsed_start_date,
            end_date=parsed_end_date,

            status=status,
        )

        # ====================================================
        # OPTIONAL USER CREATOR
        # ====================================================
        #
        # Only enable this section if Exam model has
        # created_by / created_by_id.
        #
        # Example:
        #
        # exam.created_by = current_user.id
        #
        # ====================================================

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(exam)

            db.session.commit()

            flash(
                f"Exam '{exam.name}' was created successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_exams"
                )
            )

        except Exception as e:

            db.session.rollback()

            current_app.logger.exception(
                "Error while creating exam"
            )

            flash(
                "An error occurred while creating the exam. Please try again.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/exams/add_exam.html",

        # ----------------------------------------------
        # ORGANIZATION
        # ----------------------------------------------

        institutions=institutions,
        branches=branches,
        programs=programs,

        # ----------------------------------------------
        # OPTIONAL ASSESSMENT PLANS
        # ----------------------------------------------

        assessment_plans=assessment_plans,

        # ----------------------------------------------
        # ACADEMIC PERIOD
        # ----------------------------------------------

        academic_years=academic_years,
        terms=terms,

        # ----------------------------------------------
        # EXTRA
        # ----------------------------------------------

        allowed_exam_types=allowed_exam_types,
        allowed_statuses=allowed_statuses,
        user=current_user
    )




# ============================================================
# GENERATE EXAM CODE
# ============================================================

@bp.route(
    "/exams/generate-code",
    methods=["GET"]
)
@login_required
def generate_exam_code():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # GET REQUEST PARAMETERS
    # ========================================================

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    exam_type = (
        request.args.get(
            "exam_type",
            "term"
        )
        .strip()
        .lower()
    )

    # ========================================================
    # REQUIRED DATA
    # ========================================================

    if not institution_id:
        return {
            "success": False,
            "message": "Institution is required."
        }, 400

    if not branch_id:
        return {
            "success": False,
            "message": "Branch is required."
        }, 400

    if not program_id:
        return {
            "success": False,
            "message": "Program is required."
        }, 400

    if not academic_year_id:
        return {
            "success": False,
            "message": "Academic year is required."
        }, 400

    # ========================================================
    # INSTITUTION
    # ========================================================

    institution = (
        Institution.query
        .filter_by(
            id=institution_id
        )
        .first()
    )

    if not institution:
        return {
            "success": False,
            "message": "Institution not found."
        }, 404

    # ========================================================
    # BRANCH
    # ========================================================

    branch = (
        Branch.query
        .filter_by(
            id=branch_id
        )
        .first()
    )

    if not branch:
        return {
            "success": False,
            "message": "Branch not found."
        }, 404

    # Branch must belong to institution
    if branch.institution_id != institution.id:
        return {
            "success": False,
            "message": "Selected branch does not belong to the selected institution."
        }, 400

    # ========================================================
    # PROGRAM
    # ========================================================

    program = (
        Program.query
        .filter_by(
            id=program_id
        )
        .first()
    )

    if not program:
        return {
            "success": False,
            "message": "Program not found."
        }, 404

    # Program must belong to institution
    if program.institution_id != institution.id:
        return {
            "success": False,
            "message": "Selected program does not belong to the selected institution."
        }, 400

    # ========================================================
    # PROGRAM BRANCH VALIDATION
    # ========================================================

    # Program.branch_id can be NULL because
    # the program may be available to multiple branches.

    if (
        getattr(program, "branch_id", None)
        and program.branch_id != branch.id
    ):
        return {
            "success": False,
            "message": "Selected program is not available in this branch."
        }, 400

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    academic_year = (
        AcademicYear.query
        .filter_by(
            id=academic_year_id
        )
        .first()
    )

    if not academic_year:
        return {
            "success": False,
            "message": "Academic year not found."
        }, 404

    # ========================================================
    # YEAR CODE
    # ========================================================

    year_code = None

    # Try common academic-year fields
    if hasattr(academic_year, "name"):
        year_code = academic_year.name

    elif hasattr(academic_year, "code"):
        year_code = academic_year.code

    elif hasattr(academic_year, "academic_year"):
        year_code = academic_year.academic_year

    else:
        year_code = str(academic_year_id)

    # Clean year
    year_code = str(
        year_code
    ).strip().upper()

    # ========================================================
    # PROGRAM CODE
    # ========================================================

    program_code = getattr(
        program,
        "code",
        None
    )

    if not program_code:
        program_code = getattr(
            program,
            "short_name",
            None
        )

    if not program_code:
        program_code = getattr(
            program,
            "name",
            "PRG"
        )

    # ========================================================
    # EXAM TYPE CODE
    # ========================================================

    exam_type_codes = {

        "term": "TERM",

        "monthly": "MON",

        "bi_monthly": "BIM",

        "quarterly": "QTR",

        "semester": "SEM",

        "midterm": "MID",

        "final": "FIN",

        "annual": "ANN",

        "mock": "MOCK",

        "entrance": "ENT",

        "supplementary": "SUP",

        "resit": "RES",

        "special": "SPC",

    }

    type_code = exam_type_codes.get(
        exam_type,
        exam_type.upper()[:5]
    )

    # ========================================================
    # CLEAN PROGRAM CODE
    # ========================================================

    import re

    program_code = re.sub(
        r"[^A-Z0-9]+",
        "-",
        str(program_code).upper()
    ).strip("-")

    if not program_code:
        program_code = "PRG"

    # Keep code manageable
    program_code = program_code[:12]

    # ========================================================
    # CLEAN YEAR CODE
    # ========================================================

    year_code = re.sub(
        r"[^A-Z0-9]+",
        "-",
        year_code
    ).strip("-")

    if not year_code:
        year_code = str(
            getattr(
                academic_year,
                "id",
                academic_year_id
            )
        )

    # ========================================================
    # BASE CODE
    # ========================================================

    base_code = (
        f"{program_code}-"
        f"{type_code}-"
        f"{year_code}"
    )

    # ========================================================
    # FIND NEXT NUMBER
    # ========================================================

    sequence = 1

    while True:

        generated_code = (
            f"{base_code}-"
            f"{sequence:03d}"
        )

        # ====================================================
        # CHECK DUPLICATE
        # ====================================================

        existing_exam = (
            Exam.query
            .filter(
                Exam.code == generated_code
            )
            .first()
        )

        if not existing_exam:
            break

        sequence += 1

        # Safety protection
        if sequence > 9999:

            return {
                "success": False,
                "message": "Unable to generate a unique exam code."
            }, 500

    # ========================================================
    # RETURN JSON
    # ========================================================

    return {
        "success": True,
        "code": generated_code
    }, 200



# ============================================================
# VIEW EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>",
    methods=["GET"]
)
@login_required
def view_exam(exam_id):

    if not _exam_can_view():
        abort(403)

    query = _exam_scope_query(
        Exam.query
    )

    exam = (
        query
        .filter(
            Exam.id == exam_id
        )
        .first_or_404()
    )

    return render_template(
        "backend/pages/exams/view_exam.html",
        exam=exam,
    )


# ============================================================
# EDIT EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam(exam_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # GET EXAM
    # ========================================================

    exam = (
        Exam.query
        .filter(
            Exam.id == exam_id
        )
        .first()
    )

    if not exam:
        flash(
            "Exam not found.",
            "danger"
        )

        return redirect(
            url_for("main.all_exams")
        )

    # ========================================================
    # EXAM INSTITUTION SECURITY
    # ========================================================

    if (
        current_role != "superadmin"
        and user_institution_id
        and exam.institution_id
        != user_institution_id
    ):
        abort(403)

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    if (
        current_role == "branch_admin"
        and user_branch_id
        and exam.branch_id != user_branch_id
    ):
        abort(403)

    # ========================================================
    # ALLOWED EXAM TYPES
    # ========================================================

    allowed_exam_types = {
        "term",
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    }

    # ========================================================
    # ALLOWED STATUS
    # ========================================================

    allowed_statuses = {
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    }

    # ========================================================
    # FORM DATA
    # ========================================================

    institutions_query = Institution.query
    branches_query = Branch.query
    programs_query = Program.query
    assessment_plans_query = AssessmentPlan.query
    academic_years_query = AcademicYear.query
    terms_query = Term.query

    # ========================================================
    # USER SCOPE
    # ========================================================

    if current_role != "superadmin":

        if not user_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        # ----------------------------------------------------
        # INSTITUTIONS
        # ----------------------------------------------------

        institutions_query = (
            institutions_query.filter(
                Institution.id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # BRANCHES
        # ----------------------------------------------------

        branches_query = (
            branches_query.filter(
                Branch.institution_id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # PROGRAMS
        # ----------------------------------------------------

        programs_query = (
            programs_query.filter(
                Program.institution_id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # ASSESSMENT PLANS
        # ----------------------------------------------------

        if hasattr(
            AssessmentPlan,
            "institution_id"
        ):

            assessment_plans_query = (
                assessment_plans_query.filter(
                    AssessmentPlan.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # ACADEMIC YEARS
        # ----------------------------------------------------

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years_query = (
                academic_years_query.filter(
                    AcademicYear.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        if (
            current_role == "branch_admin"
            and user_branch_id
        ):

            branches_query = (
                branches_query.filter(
                    Branch.id
                    == user_branch_id
                )
            )

            programs_query = (
                programs_query.filter(
                    or_(
                        Program.branch_id
                        == user_branch_id,

                        Program.branch_id.is_(None)
                    )
                )
            )

    # ========================================================
    # EXECUTE QUERIES
    # ========================================================

    institutions = (
        institutions_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    programs = (
        programs_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    assessment_plans = (
        assessment_plans_query
        .order_by(
            AssessmentPlan.name.asc()
        )
        .all()
    )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    terms = (
        terms_query
        .order_by(
            Term.id.desc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        assessment_plan_id = request.form.get(
            "assessment_plan_id",
            type=int
        )

        if not assessment_plan_id:
            assessment_plan_id = None

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        term_id = request.form.get(
            "term_id",
            type=int
        )

        if not term_id:
            term_id = None

        name = (
            request.form.get(
                "name",
                ""
            )
            .strip()
        )

        code = (
            request.form.get(
                "code",
                ""
            )
            .strip()
            .upper()
        )

        exam_type = (
            request.form.get(
                "exam_type",
                "term"
            )
            .strip()
            .lower()
        )

        description = (
            request.form.get(
                "description",
                ""
            )
            .strip()
        )

        start_date = (
            request.form.get(
                "start_date",
                ""
            )
            .strip()
        )

        end_date = (
            request.form.get(
                "end_date",
                ""
            )
            .strip()
        )

        status = (
            request.form.get(
                "status",
                "draft"
            )
            .strip()
            .lower()
        )

        # ====================================================
        # BASIC VALIDATION
        # ====================================================

        if not institution_id:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not branch_id:

            flash(
                "Please select a branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not program_id:

            flash(
                "Please select a program.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not academic_year_id:

            flash(
                "Please select an academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not name:

            flash(
                "Exam name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # EXAM TYPE
        # ====================================================

        if exam_type not in allowed_exam_types:

            flash(
                "Invalid exam type selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # STATUS
        # ====================================================

        if status not in allowed_statuses:

            flash(
                "Invalid exam status selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id
                == institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # INSTITUTION SCOPE
        # ====================================================

        if (
            current_role != "superadmin"
            and institution.id
            != user_institution_id
        ):
            abort(403)

        # ====================================================
        # BRANCH
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id
            )
            .first()
        )

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # BRANCH → INSTITUTION
        # ====================================================

        if branch.institution_id != institution.id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # BRANCH ADMIN SCOPE
        # ====================================================

        if (
            current_role == "branch_admin"
            and user_branch_id
            and branch.id != user_branch_id
        ):
            abort(403)

        # ====================================================
        # PROGRAM
        # ====================================================

        program = (
            Program.query
            .filter(
                Program.id == program_id
            )
            .first()
        )

        if not program:

            flash(
                "Selected program was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # PROGRAM → INSTITUTION
        # ====================================================

        if program.institution_id != institution.id:

            flash(
                "Selected program does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # PROGRAM → BRANCH
        #
        # NULL = available to multiple branches
        # ====================================================

        if (
            getattr(
                program,
                "branch_id",
                None
            )
            and program.branch_id
            != branch.id
        ):

            flash(
                "Selected program is not available in this branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
            .first()
        )

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # ACADEMIC YEAR → INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution.id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        # ====================================================
        # TERM - OPTIONAL
        # ====================================================

        term = None

        if term_id:

            term = (
                Term.query
                .filter(
                    Term.id == term_id
                )
                .first()
            )

            if not term:

                flash(
                    "Selected term was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

            # ------------------------------------------------
            # TERM → ACADEMIC YEAR
            # ------------------------------------------------

            if hasattr(
                Term,
                "academic_year_id"
            ):

                if (
                    term.academic_year_id
                    != academic_year.id
                ):

                    flash(
                        "Selected term does not belong to the selected academic year.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

        # ====================================================
        # ASSESSMENT PLAN - OPTIONAL
        # ====================================================

        assessment_plan = None

        if assessment_plan_id:

            assessment_plan = (
                AssessmentPlan.query
                .filter(
                    AssessmentPlan.id
                    == assessment_plan_id
                )
                .first()
            )

            if not assessment_plan:

                flash(
                    "Selected assessment plan was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

            # ------------------------------------------------
            # PLAN → INSTITUTION
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "institution_id"
            ):

                if (
                    assessment_plan.institution_id
                    != institution.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected institution.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

            # ------------------------------------------------
            # PLAN → PROGRAM
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "program_id"
            ):

                if (
                    assessment_plan.program_id
                    != program.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected program.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

        # ====================================================
        # DATE VALIDATION
        # ====================================================

        parsed_start_date = None
        parsed_end_date = None

        if start_date:

            try:

                parsed_start_date = (
                    datetime.strptime(
                        start_date,
                        "%Y-%m-%d"
                    ).date()
                )

            except ValueError:

                flash(
                    "Invalid start date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        if end_date:

            try:

                parsed_end_date = (
                    datetime.strptime(
                        end_date,
                        "%Y-%m-%d"
                    ).date()
                )

            except ValueError:

                flash(
                    "Invalid end date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        if (
            parsed_start_date
            and parsed_end_date
            and parsed_end_date < parsed_start_date
        ):

            flash(
                "End date cannot be earlier than start date.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # CODE VALIDATION
        # ====================================================

        if not code:

            flash(
                "Exam code is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # DUPLICATE CODE CHECK
        #
        # Ignore current exam itself
        # ====================================================

        duplicate_exam = (
            Exam.query
            .filter(
                db.func.upper(
                    Exam.code
                ) == code.upper(),

                Exam.id != exam.id
            )
            .first()
        )

        if duplicate_exam:

            flash(
                f"Exam code '{code}' is already used by another exam.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # UPDATE EXAM
        # ====================================================

        exam.institution_id = institution.id

        exam.branch_id = branch.id

        exam.program_id = program.id

        # Optional
        exam.assessment_plan_id = (
            assessment_plan.id
            if assessment_plan
            else None
        )

        exam.academic_year_id = (
            academic_year.id
        )

        # Optional
        exam.term_id = (
            term.id
            if term
            else None
        )

        exam.name = name

        exam.code = code

        exam.exam_type = exam_type

        exam.description = (
            description
            if description
            else None
        )

        exam.start_date = parsed_start_date

        exam.end_date = parsed_end_date

        exam.status = status

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.commit()

            flash(
                f"Exam '{exam.name}' was updated successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_exams"
                )
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Error while updating exam"
            )

            flash(
                "An error occurred while updating the exam. Please try again.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/exams/edit_exam.html",

        exam=exam,

        institutions=institutions,

        branches=branches,

        programs=programs,

        assessment_plans=assessment_plans,

        academic_years=academic_years,

        terms=terms,

        allowed_exam_types=allowed_exam_types,

        allowed_statuses=allowed_statuses,
        user=current_user
    )




# ============================================================
# DELETE EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam(exam_id):

    if not _exam_can_manage():
        abort(403)

    # --------------------------------------------------------
    # GET EXAM WITH USER SCOPE
    # --------------------------------------------------------

    query = _exam_scope_query(
        Exam.query
    )

    exam = (
        query
        .filter(
            Exam.id == exam_id
        )
        .first_or_404()
    )

    try:

        db.session.delete(
            exam
        )

        db.session.commit()

        flash(
            "Exam deleted successfully.",
            "success"
        )

    except Exception as e:

        db.session.rollback()

        flash(
            "This exam cannot be deleted because it may already have related examination records.",
            "danger"
        )

    return redirect(
        url_for(
            "main.all_exams"
        )
    )





# ============================================================
# EXAM SUBJECT ROUTES
# ============================================================

def _exam_subject_can_manage():

    role = getattr(
        current_user,
        "role",
        None
    )

    return role in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }


# ============================================================
# ROLE PERMISSION - VIEW
# ============================================================

def _exam_subject_can_view():

    role = getattr(
        current_user,
        "role",
        None
    )

    return role in {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }


# ============================================================
# HELPER
# CURRENT USER INSTITUTION / BRANCH SCOPE
# ============================================================

def _exam_subject_scope_query(query):

    role = getattr(
        current_user,
        "role",
        None
    )

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if role == "superadmin":
        return query

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:
            return query.filter(False)

        return query.filter(
            Exam.institution_id == institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    if role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:
            return query.filter(False)

        return query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    # --------------------------------------------------------
    # OTHER ROLES
    # --------------------------------------------------------

    return query.filter(False)


# ============================================================
# ADD EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/add",
    methods=["GET", "POST"]
)
@login_required
def add_exam_subject():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # EXAM QUERY
    # ========================================================

    exams_query = (
        Exam.query
        .join(
            Program,
            Program.id == Exam.program_id
        )
    )

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":

        pass

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        if not institution_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # EXAM
        # ====================================================

        exam_id = request.form.get(
            "exam_id",
            type=int
        )

        if not exam_id:

            flash(
                "Please select an exam.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # LOAD EXAM WITH SECURITY
        # ====================================================

        exam_query = Exam.query.filter(
            Exam.id == exam_id
        )

        if current_role == "school_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id
            )

        elif current_role == "branch_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

        exam = exam_query.first()

        if not exam:

            flash(
                "The selected exam does not exist or you do not have permission to manage it.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # PROGRAM
        # ====================================================

        if not exam.program_id:

            flash(
                "The selected exam has no program assigned.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        program = (
            Program.query
            .filter(
                Program.id == exam.program_id
            )
            .first()
        )

        if not program:

            flash(
                "The program assigned to this exam was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # SUBJECT IDS
        #
        # Accept BOTH:
        #
        # subject_ids[]
        # subject_id[]
        #
        # This prevents template naming mismatch.
        # ====================================================

        subject_ids = request.form.getlist(
            "subject_ids[]"
        )

        if not subject_ids:

            subject_ids = request.form.getlist(
                "subject_id[]"
            )

        # ====================================================
        # CLASS IDS
        # ====================================================

        class_ids = request.form.getlist(
            "class_ids[]"
        )

        if not class_ids:

            class_ids = request.form.getlist(
                "class_id[]"
            )

        # ====================================================
        # SECTION IDS
        # ====================================================

        section_ids = request.form.getlist(
            "section_ids[]"
        )

        if not section_ids:

            section_ids = request.form.getlist(
                "section_id[]"
            )

        # ====================================================
        # TEACHER IDS
        # ====================================================

        teacher_ids = request.form.getlist(
            "teacher_ids[]"
        )

        if not teacher_ids:

            teacher_ids = request.form.getlist(
                "teacher_id[]"
            )

        # ====================================================
        # MAX MARKS
        # ====================================================

        max_marks_list = request.form.getlist(
            "max_marks[]"
        )

        # ====================================================
        # PASS MARKS
        # ====================================================

        pass_marks_list = request.form.getlist(
            "pass_marks[]"
        )

        # ====================================================
        # WEIGHT
        # ====================================================

        weight_list = request.form.getlist(
            "weight[]"
        )

        # ====================================================
        # DISPLAY ORDER
        # ====================================================

        display_order_list = request.form.getlist(
            "display_order[]"
        )

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # CHECK SUBJECT ROWS
        # ====================================================

        if not subject_ids:

            flash(
                "Please add at least one subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # ROW COUNT
        # ====================================================

        row_count = len(subject_ids)

        # ====================================================
        # NORMALIZE LIST LENGTHS
        # ========================================================

        def normalize_list(
            values,
            count,
            default_value=""
        ):

            values = list(values)

            if len(values) < count:

                values.extend(
                    [default_value]
                    * (
                        count
                        - len(values)
                    )
                )

            elif len(values) > count:

                values = values[:count]

            return values

        class_ids = normalize_list(
            class_ids,
            row_count,
            ""
        )

        section_ids = normalize_list(
            section_ids,
            row_count,
            ""
        )

        teacher_ids = normalize_list(
            teacher_ids,
            row_count,
            ""
        )

        max_marks_list = normalize_list(
            max_marks_list,
            row_count,
            "100"
        )

        pass_marks_list = normalize_list(
            pass_marks_list,
            row_count,
            "50"
        )

        weight_list = normalize_list(
            weight_list,
            row_count,
            "100"
        )

        display_order_list = normalize_list(
            display_order_list,
            row_count,
            ""
        )

        # ====================================================
        # VALID PROGRAM SUBJECTS
        #
        # Subject must belong to:
        #
        # Exam.program_id
        #
        # AND
        #
        # Exam.institution_id
        # ====================================================

        valid_subject_query = (
            Subject.query
            .filter(
                Subject.program_id == exam.program_id,
                Subject.institution_id == exam.institution_id,
                Subject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Branch
        #
        # branch_id NULL = shared subject
        # ----------------------------------------------------

        if exam.branch_id:

            valid_subject_query = (
                valid_subject_query
                .filter(
                    db.or_(
                        Subject.branch_id == exam.branch_id,
                        Subject.branch_id.is_(None)
                    )
                )
            )

        valid_subjects = (
            valid_subject_query
            .all()
        )

        valid_subject_map = {
            int(subject.id): subject
            for subject in valid_subjects
        }

        # ====================================================
        # VALID PROGRAM CLASSES
        # ====================================================

        valid_classes_query = (
            Class.query
            .filter(
                Class.program_id == exam.program_id,
                Class.institution_id == exam.institution_id
            )
        )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if exam.branch_id:

            valid_classes_query = (
                valid_classes_query
                .filter(
                    Class.branch_id == exam.branch_id
                )
            )

        # ----------------------------------------------------
        # Academic Year
        # ----------------------------------------------------

        if exam.academic_year_id:

            valid_classes_query = (
                valid_classes_query
                .filter(
                    Class.academic_year_id ==
                    exam.academic_year_id
                )
            )

        valid_classes = (
            valid_classes_query
            .all()
        )

        valid_class_map = {
            int(item.id): item
            for item in valid_classes
        }

        # ====================================================
        # VALID SECTIONS
        # ====================================================

        valid_class_ids = list(
            valid_class_map.keys()
        )

        valid_section_map = {}

        if valid_class_ids:

            valid_sections = (
                Section.query
                .filter(
                    Section.class_id.in_(
                        valid_class_ids
                    )
                )
                .all()
            )

            valid_section_map = {
                int(section.id): section
                for section in valid_sections
            }

        # ====================================================
        # VALID TEACHERS
        #
        # Teacher must be assigned through TeacherSubject.
        #
        # Program:
        #
        # Exam
        #   ↓
        # Program
        #   ↓
        # TeacherSubject
        #   ↓
        # Teacher
        # ====================================================

        valid_teacher_query = (
            Teacher.query
            .join(
                TeacherSubject,
                TeacherSubject.teacher_id ==
                Teacher.id
            )
            .filter(
                Teacher.institution_id ==
                exam.institution_id,

                Teacher.is_active.is_(True),

                Teacher.status == "active",

                TeacherSubject.institution_id ==
                exam.institution_id,

                TeacherSubject.program_id ==
                exam.program_id,

                TeacherSubject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if exam.branch_id:

            valid_teacher_query = (
                valid_teacher_query
                .filter(
                    Teacher.branch_id ==
                    exam.branch_id
                )
                .filter(
                    db.or_(
                        TeacherSubject.branch_id ==
                        exam.branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        valid_teachers = (
            valid_teacher_query
            .distinct()
            .all()
        )

        valid_teacher_map = {
            int(teacher.id): teacher
            for teacher in valid_teachers
        }

        # ====================================================
        # EXISTING EXAM SUBJECTS
        # ====================================================

        existing_rows = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id ==
                exam.id
            )
            .all()
        )

        existing_combinations = set()

        for item in existing_rows:

            existing_combinations.add(
                (
                    int(item.subject_id),

                    int(item.class_id)
                    if item.class_id is not None
                    else None,

                    int(item.section_id)
                    if item.section_id is not None
                    else None
                )
            )

        # ====================================================
        # REQUEST DUPLICATES
        # ====================================================

        request_combinations = set()

        # ====================================================
        # NEW OBJECTS
        # ====================================================

        new_exam_subjects = []

        # ====================================================
        # PROCESS EACH ROW
        # ====================================================

        for index in range(row_count):

            row_number = index + 1

            # ==================================================
            # SUBJECT
            # ==================================================

            raw_subject_id = (
                subject_ids[index]
                if index < len(subject_ids)
                else ""
            )

            raw_subject_id = (
                str(raw_subject_id).strip()
            )

            if not raw_subject_id:

                flash(
                    f"Please select a subject on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            try:

                subject_id = int(
                    raw_subject_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid subject on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            subject = valid_subject_map.get(
                subject_id
            )

            if not subject:

                flash(
                    f"Subject on row {row_number} does not belong to the selected exam program.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # CLASS
            # ==================================================

            raw_class_id = (
                class_ids[index]
                if index < len(class_ids)
                else ""
            )

            raw_class_id = (
                str(raw_class_id).strip()
                if raw_class_id
                else ""
            )

            class_id = None
            selected_class = None

            if raw_class_id:

                try:

                    class_id = int(
                        raw_class_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid class on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                selected_class = (
                    valid_class_map.get(
                        class_id
                    )
                )

                if not selected_class:

                    flash(
                        f"Class on row {row_number} does not belong to the selected exam program.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # SECTION
            # ==================================================

            raw_section_id = (
                section_ids[index]
                if index < len(section_ids)
                else ""
            )

            raw_section_id = (
                str(raw_section_id).strip()
                if raw_section_id
                else ""
            )

            section_id = None

            if raw_section_id:

                # ----------------------------------------------
                # Section requires Class
                # ----------------------------------------------

                if not class_id:

                    flash(
                        f"Please select a class before selecting a section on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                try:

                    section_id = int(
                        raw_section_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid section on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                section = (
                    valid_section_map.get(
                        section_id
                    )
                )

                if not section:

                    flash(
                        f"Section on row {row_number} is not valid.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                if int(section.class_id) != int(
                    class_id
                ):

                    flash(
                        f"Section on row {row_number} does not belong to the selected class.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # TEACHER
            # ==================================================

            raw_teacher_id = (
                teacher_ids[index]
                if index < len(teacher_ids)
                else ""
            )

            raw_teacher_id = (
                str(raw_teacher_id).strip()
                if raw_teacher_id
                else ""
            )

            teacher_id = None

            if raw_teacher_id:

                try:

                    teacher_id = int(
                        raw_teacher_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid teacher on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                teacher = valid_teacher_map.get(
                    teacher_id
                )

                if not teacher:

                    flash(
                        f"Teacher on row {row_number} is not assigned to the selected program.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                # ----------------------------------------------
                # Verify TeacherSubject
                # Program + Subject
                # ----------------------------------------------

                teacher_assignment_query = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.teacher_id ==
                        teacher_id,

                        TeacherSubject.program_id ==
                        exam.program_id,

                        TeacherSubject.subject_id ==
                        subject_id,

                        TeacherSubject.institution_id ==
                        exam.institution_id,

                        TeacherSubject.status ==
                        "active"
                    )
                )

                # ------------------------------------------------
                # Branch assignment
                # ------------------------------------------------

                if exam.branch_id:

                    teacher_assignment_query = (
                        teacher_assignment_query
                        .filter(
                            db.or_(
                                TeacherSubject.branch_id ==
                                exam.branch_id,

                                TeacherSubject.branch_id.is_(None)
                            )
                        )
                    )

                teacher_assignment = (
                    teacher_assignment_query
                    .first()
                )

                # ------------------------------------------------
                # If no subject-specific assignment exists,
                # allow program-level assignment.
                # ------------------------------------------------

                if not teacher_assignment:

                    teacher_assignment_query = (
                        TeacherSubject.query
                        .filter(
                            TeacherSubject.teacher_id ==
                            teacher_id,

                            TeacherSubject.program_id ==
                            exam.program_id,

                            TeacherSubject.institution_id ==
                            exam.institution_id,

                            TeacherSubject.status ==
                            "active",

                            db.or_(
                                TeacherSubject.subject_id.is_(None),
                                TeacherSubject.subject_id ==
                                subject_id
                            )
                        )
                    )

                    if exam.branch_id:

                        teacher_assignment_query = (
                            teacher_assignment_query
                            .filter(
                                db.or_(
                                    TeacherSubject.branch_id ==
                                    exam.branch_id,

                                    TeacherSubject.branch_id.is_(None)
                                )
                            )
                        )

                    teacher_assignment = (
                        teacher_assignment_query
                        .first()
                    )

                if not teacher_assignment:

                    flash(
                        f"{teacher.full_name} is not assigned to {subject.name}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # MAX MARKS
            # ==================================================

            raw_max_marks = (
                max_marks_list[index]
                if index < len(max_marks_list)
                else "100"
            )

            try:

                max_marks = float(
                    raw_max_marks
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid maximum marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if max_marks <= 0:

                flash(
                    f"Maximum marks must be greater than zero on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # PASS MARKS
            # ==================================================

            raw_pass_marks = (
                pass_marks_list[index]
                if index < len(pass_marks_list)
                else "50"
            )

            try:

                pass_marks = float(
                    raw_pass_marks
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid pass marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if pass_marks < 0:

                flash(
                    f"Pass marks cannot be negative on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if pass_marks > max_marks:

                flash(
                    f"Pass marks cannot exceed maximum marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # WEIGHT
            # ==================================================

            raw_weight = (
                weight_list[index]
                if index < len(weight_list)
                else "100"
            )

            try:

                weight = float(
                    raw_weight
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid weight on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if weight <= 0:

                flash(
                    f"Weight must be greater than zero on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # DISPLAY ORDER
            # ==================================================

            raw_display_order = (
                display_order_list[index]
                if index < len(display_order_list)
                else ""
            )

            try:

                display_order = int(
                    raw_display_order
                )

            except (
                TypeError,
                ValueError
            ):

                display_order = (
                    index + 1
                )

            if display_order <= 0:

                display_order = (
                    index + 1
                )

            # ==================================================
            # DUPLICATE KEY
            #
            # exam + subject + class + section
            # ==================================================

            combination = (
                subject_id,
                class_id,
                section_id
            )

            # ==================================================
            # DUPLICATE IN CURRENT REQUEST
            # ==================================================

            if combination in request_combinations:

                class_text = (
                    selected_class.name
                    if selected_class
                    else "All Classes"
                )

                flash(
                    f"{subject.name} is duplicated on row {row_number} for {class_text}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            request_combinations.add(
                combination
            )

            # ==================================================
            # DUPLICATE IN DATABASE
            # ==================================================

            if combination in existing_combinations:

                class_text = (
                    selected_class.name
                    if selected_class
                    else "All Classes"
                )

                flash(
                    f"{subject.name} already exists for {class_text}.",
                    "warning"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # CREATE EXAM SUBJECT
            # ==================================================

            exam_subject = ExamSubject(
                exam_id=exam.id,

                subject_id=subject_id,

                class_id=class_id,

                section_id=section_id,

                teacher_id=teacher_id,

                max_marks=max_marks,

                pass_marks=pass_marks,

                weight=weight,

                display_order=display_order,

                status=status
            )

            new_exam_subjects.append(
                exam_subject
            )

        # ====================================================
        # NOTHING TO SAVE
        # ====================================================

        if not new_exam_subjects:

            flash(
                "No exam subjects were prepared.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SAVE ALL
        # ====================================================

        try:

            db.session.add_all(
                new_exam_subjects
            )

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Failed to create multiple exam subjects: %s",
                exc
            )

            flash(
                "An error occurred while adding the exam subjects. No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            f"{len(new_exam_subjects)} exam subject(s) added successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects",
                exam_id=exam.id
            )
        )

    # ========================================================
    # GET DATA
    # ========================================================

    # ========================================================
    # AVAILABLE PROGRAM IDS
    # ========================================================

    program_ids = list({
        int(exam.program_id)
        for exam in exams
        if exam.program_id
    })

    # ========================================================
    # SUBJECTS
    #
    # IMPORTANT:
    # All subjects belonging to available programs.
    # ========================================================

    subjects = []

    if program_ids:

        subjects_query = (
            Subject.query
            .filter(
                Subject.program_id.in_(
                    program_ids
                ),
                Subject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Institution
        # ----------------------------------------------------

        if current_role != "superadmin":

            subjects_query = (
                subjects_query
                .filter(
                    Subject.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # Branch
        #
        # NULL branch = shared subject
        # ----------------------------------------------------

        if current_role == "branch_admin":

            subjects_query = (
                subjects_query
                .filter(
                    db.or_(
                        Subject.branch_id ==
                        branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
            )

        subjects = (
            subjects_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    classes = []

    if program_ids:

        classes_query = (
            Class.query
            .filter(
                Class.program_id.in_(
                    program_ids
                )
            )
        )

        # ----------------------------------------------------
        # Institution
        # ----------------------------------------------------

        if current_role != "superadmin":

            classes_query = (
                classes_query
                .filter(
                    Class.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if current_role == "branch_admin":

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id ==
                    branch_id
                )
            )

        classes = (
            classes_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections = []

    available_class_ids = [
        int(item.id)
        for item in classes
    ]

    if available_class_ids:

        sections = (
            Section.query
            .filter(
                Section.class_id.in_(
                    available_class_ids
                )
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # TEACHERS
    #
    # ONLY PROGRAM ASSIGNED TEACHERS
    #
    # NOT ALL BRANCH TEACHERS
    # ========================================================

    teachers = []

    if program_ids:

        teachers_query = (
            Teacher.query
            .join(
                TeacherSubject,
                TeacherSubject.teacher_id ==
                Teacher.id
            )
            .filter(
                Teacher.is_active.is_(True),

                Teacher.status == "active",

                TeacherSubject.program_id.in_(
                    program_ids
                ),

                TeacherSubject.status == "active"
            )
        )

        # ----------------------------------------------------
        # SUPERADMIN
        # ----------------------------------------------------

        if current_role == "superadmin":

            pass

        # ----------------------------------------------------
        # SCHOOL ADMIN
        # ----------------------------------------------------

        elif current_role == "school_admin":

            if not institution_id:
                abort(403)

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.institution_id ==
                    institution_id,

                    TeacherSubject.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        elif current_role == "branch_admin":

            if not institution_id or not branch_id:
                abort(403)

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.institution_id ==
                    institution_id,

                    Teacher.branch_id ==
                    branch_id,

                    db.or_(
                        TeacherSubject.branch_id ==
                        branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        teachers = (
            teachers_query
            .distinct()
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    # ========================================================
    # SELECTED EXAM
    # ========================================================

    selected_exam_id = request.args.get(
        "exam_id",
        type=int
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/add_exam_subject.html",

        exams=exams,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        selected_exam_id=selected_exam_id,

        user=current_user
    )

# ============================================================
# BULK ADD EXAM SUBJECTS
# ============================================================

@bp.route(
    "/exam-subjects/bulk-add",
    methods=["GET", "POST"]
)
@login_required
def bulk_add_exam_subjects():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    raw_role = getattr(
        current_user,
        "role",
        None
    )

    if hasattr(raw_role, "value"):
        current_role = raw_role.value
    else:
        current_role = str(
            raw_role or ""
        )

    current_role = (
        current_role
        .strip()
        .lower()
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD AVAILABLE EXAMS
    # ========================================================

    exams_query = (
        Exam.query
        .join(
            Program,
            Program.id == Exam.program_id
        )
        .filter(
            Exam.program_id.isnot(None)
        )
    )

    # ========================================================
    # SUPERADMIN
    # ========================================================

    if current_role == "superadmin":

        pass

    # ========================================================
    # SCHOOL ADMIN
    # ========================================================

    elif current_role == "school_admin":

        if not institution_id:
            abort(403)

        exams_query = (
            exams_query
            .filter(
                Exam.institution_id ==
                institution_id
            )
        )

    # ========================================================
    # BRANCH ADMIN
    # ========================================================

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exams_query = (
            exams_query
            .filter(
                Exam.institution_id ==
                institution_id,

                Exam.branch_id ==
                branch_id
            )
        )

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # EXAM ID
        # ====================================================

        exam_id = request.form.get(
            "exam_id",
            type=int
        )

        if not exam_id:

            flash(
                "Please select an exam.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects"
                )
            )

        # ====================================================
        # LOAD EXAM WITH SECURITY
        # ====================================================

        exam_query = (
            Exam.query
            .filter(
                Exam.id ==
                exam_id
            )
        )

        if current_role == "school_admin":

            exam_query = (
                exam_query
                .filter(
                    Exam.institution_id ==
                    institution_id
                )
            )

        elif current_role == "branch_admin":

            exam_query = (
                exam_query
                .filter(
                    Exam.institution_id ==
                    institution_id,

                    Exam.branch_id ==
                    branch_id
                )
            )

        exam = exam_query.first()

        if not exam:

            flash(
                "The selected exam does not exist or you do not have permission to manage it.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects"
                )
            )

        # ====================================================
        # PROGRAM
        # ====================================================

        if not exam.program_id:

            flash(
                "The selected exam has no program assigned.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        program = (
            Program.query
            .filter(
                Program.id ==
                exam.program_id,

                Program.institution_id ==
                exam.institution_id
            )
            .first()
        )

        if not program:

            flash(
                "The program assigned to this exam was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # MAX MARKS
        # ====================================================

        raw_max_marks = request.form.get(
            "max_marks",
            "100"
        )

        try:

            max_marks = float(
                raw_max_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Maximum marks must be a valid number.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if max_marks <= 0:

            flash(
                "Maximum marks must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # PASS MARKS
        # ====================================================

        raw_pass_marks = request.form.get(
            "pass_marks",
            "50"
        )

        try:

            pass_marks = float(
                raw_pass_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Pass marks must be a valid number.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if pass_marks < 0:

            flash(
                "Pass marks cannot be negative.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if pass_marks > max_marks:

            flash(
                "Pass marks cannot exceed maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # WEIGHT
        # ====================================================

        raw_weight = request.form.get(
            "weight",
            "100"
        )

        try:

            weight = float(
                raw_weight
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Weight must be a valid number.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        if weight <= 0:

            flash(
                "Weight must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # LOAD SUBJECTS
        # ====================================================

        subjects_query = (
            Subject.query
            .filter(
                Subject.program_id ==
                exam.program_id,

                Subject.institution_id ==
                exam.institution_id,

                Subject.status ==
                "active"
            )
        )

        if exam.branch_id:

            subjects_query = (
                subjects_query
                .filter(
                    db.or_(
                        Subject.branch_id ==
                        exam.branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
            )

        subjects = (
            subjects_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

        if not subjects:

            flash(
                "No active subjects were found for this exam program.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # LOAD CLASSES
        # ====================================================

        classes_query = (
            Class.query
            .filter(
                Class.program_id ==
                exam.program_id,

                Class.institution_id ==
                exam.institution_id
            )
        )

        if exam.branch_id:

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id ==
                    exam.branch_id
                )
            )

        if exam.academic_year_id:

            classes_query = (
                classes_query
                .filter(
                    Class.academic_year_id ==
                    exam.academic_year_id
                )
            )

        classes = (
            classes_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

        if not classes:

            flash(
                "No classes were found for this exam program.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # EXISTING EXAM SUBJECTS
        # ====================================================

        existing_rows = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id ==
                exam.id
            )
            .all()
        )

        existing_combinations = {
            (
                int(row.subject_id),

                int(row.class_id)
                if row.class_id is not None
                else None,

                int(row.section_id)
                if row.section_id is not None
                else None
            )
            for row in existing_rows
        }

        # ====================================================
        # LOAD ACTIVE TEACHER ASSIGNMENTS
        #
        # IMPORTANT:
        #
        # A TeacherSubject row is an assignment.
        #
        # Multiple rows belonging to the SAME teacher do not
        # mean multiple teachers.
        #
        # Example:
        #
        # Teacher A -> English
        # Teacher A -> Mathematics
        # Teacher A -> Somali
        #
        # This is VALID.
        # ====================================================

        teacher_query = (
            db.session.query(
                TeacherSubject,
                Teacher
            )
            .join(
                Teacher,
                Teacher.id ==
                TeacherSubject.teacher_id
            )
            .filter(
                Teacher.institution_id ==
                exam.institution_id,

                Teacher.is_active.is_(True),

                Teacher.status ==
                "active",

                TeacherSubject.institution_id ==
                exam.institution_id,

                TeacherSubject.program_id ==
                exam.program_id,

                TeacherSubject.status ==
                "active",

                TeacherSubject.subject_id.isnot(None)
            )
        )

        # ====================================================
        # BRANCH SECURITY
        # ====================================================

        if exam.branch_id:

            teacher_query = (
                teacher_query
                .filter(
                    Teacher.branch_id ==
                    exam.branch_id,

                    db.or_(
                        TeacherSubject.branch_id ==
                        exam.branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        teacher_rows = (
            teacher_query
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

        # ====================================================
        # BUILD TEACHER ASSIGNMENT MAP
        #
        # Structure:
        #
        # teacher_assignments[
        #     subject_id
        # ][
        #     class_id
        # ] = {
        #     teacher_id: {
        #         "teacher": Teacher,
        #         "specificity": number,
        #         "assignment": TeacherSubject
        #     }
        # }
        #
        # class_id = None:
        #     global assignment
        #
        # class_id = X:
        #     class-specific assignment
        #
        # section_id:
        #     used to determine specificity.
        # ====================================================

        teacher_assignments = {}

        for assignment, teacher in teacher_rows:

            if assignment.subject_id is None:
                continue

            subject_id = int(
                assignment.subject_id
            )

            teacher_id = int(
                teacher.id
            )

            assignment_class_id = (
                int(assignment.class_id)
                if assignment.class_id is not None
                else None
            )

            assignment_section_id = (
                int(assignment.section_id)
                if assignment.section_id is not None
                else None
            )

            # ------------------------------------------------
            # SPECIFICITY
            #
            # section-specific = 2
            # class-specific   = 1
            # global           = 0
            # ------------------------------------------------

            if assignment_class_id is not None:

                if assignment_section_id is not None:
                    specificity = 2
                else:
                    specificity = 1

            else:

                specificity = 0

            subject_map = (
                teacher_assignments
                .setdefault(
                    subject_id,
                    {}
                )
            )

            class_map = (
                subject_map
                .setdefault(
                    assignment_class_id,
                    {}
                )
            )

            # ------------------------------------------------
            # SAME TEACHER
            #
            # If same teacher has several assignments, retain
            # only the most specific one.
            # ------------------------------------------------

            existing = (
                class_map.get(
                    teacher_id
                )
            )

            if existing is None:

                class_map[
                    teacher_id
                ] = {
                    "teacher": teacher,
                    "specificity": specificity,
                    "assignment": assignment
                }

            else:

                if (
                    specificity >
                    existing["specificity"]
                ):

                    class_map[
                        teacher_id
                    ] = {
                        "teacher": teacher,
                        "specificity": specificity,
                        "assignment": assignment
                    }

        # ====================================================
        # HELPER:
        # GET TEACHERS FOR SUBJECT + CLASS
        #
        # Priority:
        #
        # 1. class-specific assignment
        # 2. global assignment
        #
        # If class-specific exists, global assignment is NOT
        # combined with it.
        # ====================================================

        def get_teacher_candidates(
            subject_id,
            class_id
        ):

            subject_id = int(
                subject_id
            )

            class_id = int(
                class_id
            )

            subject_map = (
                teacher_assignments.get(
                    subject_id,
                    {}
                )
            )

            # ------------------------------------------------
            # CLASS-SPECIFIC
            # ------------------------------------------------

            class_specific = (
                subject_map.get(
                    class_id,
                    {}
                )
            )

            if class_specific:

                return list(
                    class_specific.values()
                )

            # ------------------------------------------------
            # GLOBAL
            # ------------------------------------------------

            global_assignments = (
                subject_map.get(
                    None,
                    {}
                )
            )

            return list(
                global_assignments.values()
            )

        # ====================================================
        # TEACHER SELECTION
        #
        # KEY:
        #
        #     (subject_id, class_id)
        #
        # NOT:
        #
        #     subject_id only
        #
        # This is what allows:
        #
        # English:
        #     KD20 -> Teacher A
        #     KD21 -> Teacher B
        #
        # without considering that a conflict.
        # ====================================================

        selected_teacher_by_combination = {}

        missing_teacher_combinations = []

        multiple_teacher_combinations = []

        # ====================================================
        # EVALUATE EVERY SUBJECT × CLASS
        # ====================================================

        for class_item in classes:

            class_id_value = int(
                class_item.id
            )

            for subject in subjects:

                subject_id_value = int(
                    subject.id
                )

                candidates = (
                    get_teacher_candidates(
                        subject_id_value,
                        class_id_value
                    )
                )

                # ------------------------------------------------
                # NO TEACHER
                # ------------------------------------------------

                if not candidates:

                    missing_teacher_combinations.append(
                        (
                            subject.name,
                            class_item.name
                        )
                    )

                    continue

                # ------------------------------------------------
                # DISTINCT TEACHERS
                #
                # IMPORTANT:
                #
                # Same teacher appearing multiple times is still
                # ONE teacher.
                # ------------------------------------------------

                distinct_teachers = {}

                for candidate in candidates:

                    teacher = candidate["teacher"]

                    teacher_id = int(
                        teacher.id
                    )

                    distinct_teachers[
                        teacher_id
                    ] = candidate

                # ------------------------------------------------
                # MULTIPLE DISTINCT TEACHERS
                # ------------------------------------------------

                if len(distinct_teachers) > 1:

                    multiple_teacher_combinations.append(
                        (
                            subject.name,
                            class_item.name
                        )
                    )

                    continue

                # ------------------------------------------------
                # ONE DISTINCT TEACHER
                # ------------------------------------------------

                candidate = next(
                    iter(
                        distinct_teachers.values()
                    )
                )

                selected_teacher_by_combination[
                    (
                        subject_id_value,
                        class_id_value
                    )
                ] = candidate["teacher"]

        # ====================================================
        # BUILD NEW EXAM SUBJECTS
        # ====================================================

        new_exam_subjects = []

        request_combinations = set()

        # ====================================================
        # DISPLAY ORDER
        # ====================================================

        display_order = (
            db.session.query(
                db.func.max(
                    ExamSubject.display_order
                )
            )
            .filter(
                ExamSubject.exam_id ==
                exam.id
            )
            .scalar()
            or 0
        )

        try:

            display_order = int(
                display_order
            )

        except (
            TypeError,
            ValueError
        ):

            display_order = 0

        # ====================================================
        # SKIPPED
        # ====================================================

        skipped_existing = []

        skipped_no_teacher = []

        skipped_multiple_teachers = []

        # ====================================================
        # SUBJECT × CLASS
        # ====================================================

        for class_item in classes:

            class_id_value = int(
                class_item.id
            )

            for subject in subjects:

                subject_id_value = int(
                    subject.id
                )

                combination = (
                    subject_id_value,
                    class_id_value,
                    None
                )

                # ------------------------------------------------
                # EXISTING
                # ------------------------------------------------

                if combination in existing_combinations:

                    skipped_existing.append(
                        f"{subject.name} - "
                        f"{class_item.name}"
                    )

                    continue

                # ------------------------------------------------
                # DUPLICATE REQUEST
                # ------------------------------------------------

                if combination in request_combinations:
                    continue

                request_combinations.add(
                    combination
                )

                # ------------------------------------------------
                # SELECTED TEACHER
                # ------------------------------------------------

                teacher = (
                    selected_teacher_by_combination.get(
                        (
                            subject_id_value,
                            class_id_value
                        )
                    )
                )

                # ------------------------------------------------
                # NO TEACHER
                # ------------------------------------------------

                if teacher is None:

                    combination_label = (
                        f"{subject.name} - "
                        f"{class_item.name}"
                    )

                    # --------------------------------------------
                    # Determine reason
                    # --------------------------------------------

                    is_multiple = (
                        (
                            subject.name,
                            class_item.name
                        )
                        in multiple_teacher_combinations
                    )

                    if is_multiple:

                        skipped_multiple_teachers.append(
                            combination_label
                        )

                    else:

                        skipped_no_teacher.append(
                            combination_label
                        )

                    continue

                # ------------------------------------------------
                # DISPLAY ORDER
                # ------------------------------------------------

                display_order += 1

                # ------------------------------------------------
                # CREATE EXAM SUBJECT
                # ------------------------------------------------

                exam_subject = ExamSubject(

                    exam_id=exam.id,

                    subject_id=subject.id,

                    class_id=class_item.id,

                    # --------------------------------------------
                    # SECTION
                    #
                    # NULL means the exam subject applies to
                    # ALL sections belonging to this class.
                    # --------------------------------------------

                    section_id=None,

                    teacher_id=teacher.id,

                    max_marks=max_marks,

                    pass_marks=pass_marks,

                    weight=weight,

                    display_order=display_order,

                    status=status
                )

                new_exam_subjects.append(
                    exam_subject
                )

        # ====================================================
        # NOTHING NEW
        # ====================================================

        if not new_exam_subjects:

            # ------------------------------------------------
            # EXISTING
            # ------------------------------------------------

            if skipped_existing:

                flash(
                    "All assigned subject/class combinations already exist for this exam.",
                    "warning"
                )

            # ------------------------------------------------
            # MULTIPLE TEACHERS
            # ------------------------------------------------

            if skipped_multiple_teachers:

                preview = ", ".join(
                    skipped_multiple_teachers[:10]
                )

                if len(
                    skipped_multiple_teachers
                ) > 10:

                    preview += " ..."

                flash(
                    "These subject/class combinations have multiple "
                    f"active teachers and were skipped: {preview}. "
                    "One teacher must be selected for each affected "
                    "subject/class combination.",
                    "warning"
                )

            # ------------------------------------------------
            # NO TEACHER
            # ------------------------------------------------

            if skipped_no_teacher:

                preview = ", ".join(
                    skipped_no_teacher[:10]
                )

                if len(
                    skipped_no_teacher
                ) > 10:

                    preview += " ..."

                flash(
                    "These subject/class combinations have no active "
                    f"teacher assignment and were skipped: {preview}.",
                    "warning"
                )

            # ------------------------------------------------
            # FALLBACK
            # ------------------------------------------------

            if (
                not skipped_existing
                and not skipped_multiple_teachers
                and not skipped_no_teacher
            ):

                flash(
                    "No new exam subjects were prepared.",
                    "warning"
                )

            return redirect(
                url_for(
                    "main.all_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add_all(
                new_exam_subjects
            )

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Bulk exam subject creation failed: %s",
                exc
            )

            flash(
                "An error occurred while creating the exam subjects. "
                "No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.bulk_add_exam_subjects",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SUCCESS MESSAGE
        # ====================================================

        success_message = (
            f"{len(new_exam_subjects)} exam subject(s) "
            f"were created successfully for "
            f"{len(classes)} class(es) and "
            f"{len(subjects)} subject(s)."
        )

        if skipped_existing:

            success_message += (
                f" {len(skipped_existing)} existing "
                f"combination(s) were skipped."
            )

        flash(
            success_message,
            "success"
        )

        # ====================================================
        # WARNING: NO TEACHER
        # ====================================================

        if skipped_no_teacher:

            preview = ", ".join(
                skipped_no_teacher[:10]
            )

            if len(
                skipped_no_teacher
            ) > 10:

                preview += " ..."

            flash(
                "Skipped subject/class combinations without "
                f"an active teacher: {preview}.",
                "warning"
            )

        # ====================================================
        # WARNING: MULTIPLE TEACHERS
        # ====================================================

        if skipped_multiple_teachers:

            preview = ", ".join(
                skipped_multiple_teachers[:10]
            )

            if len(
                skipped_multiple_teachers
            ) > 10:

                preview += " ..."

            flash(
                "Skipped subject/class combinations with "
                f"multiple active teachers: {preview}. "
                "Choose one teacher for each affected "
                "combination.",
                "warning"
            )

        # ====================================================
        # REDIRECT
        # ====================================================

        return redirect(
            url_for(
                "main.all_exam_subjects",
                exam_id=exam.id
            )
        )

    # ========================================================
    # GET
    # ========================================================

    selected_exam_id = request.args.get(
        "exam_id",
        type=int
    )

    # ========================================================
    # DEFAULT GET DATA
    # ========================================================

    selected_exam = None

    subjects = []

    classes = []

    # IMPORTANT:
    #
    # This MUST remain:
    #
    #     subject_id -> LIST[Teacher]
    #
    # because the existing Jinja template uses:
    #
    #     subject_teachers[0].full_name
    #
    teachers_by_subject = {}

    assigned_subject_ids = set()

    missing_teacher_subject_ids = set()

    multiple_teacher_subject_ids = set()

    # ========================================================
    # SELECTED EXAM
    # ========================================================

    if selected_exam_id:

        # ====================================================
        # SECURITY
        # ====================================================

        selected_exam_query = (
            Exam.query
            .filter(
                Exam.id ==
                selected_exam_id
            )
        )

        if current_role == "school_admin":

            selected_exam_query = (
                selected_exam_query
                .filter(
                    Exam.institution_id ==
                    institution_id
                )
            )

        elif current_role == "branch_admin":

            selected_exam_query = (
                selected_exam_query
                .filter(
                    Exam.institution_id ==
                    institution_id,

                    Exam.branch_id ==
                    branch_id
                )
            )

        selected_exam = (
            selected_exam_query
            .first()
        )

        # ====================================================
        # EXAM HAS PROGRAM
        # ====================================================

        if (
            selected_exam
            and selected_exam.program_id
        ):

            # =================================================
            # SUBJECTS
            # =================================================

            subjects_query = (
                Subject.query
                .filter(
                    Subject.program_id ==
                    selected_exam.program_id,

                    Subject.institution_id ==
                    selected_exam.institution_id,

                    Subject.status ==
                    "active"
                )
            )

            if selected_exam.branch_id:

                subjects_query = (
                    subjects_query
                    .filter(
                        db.or_(
                            Subject.branch_id ==
                            selected_exam.branch_id,

                            Subject.branch_id.is_(None)
                        )
                    )
                )

            subjects = (
                subjects_query
                .order_by(
                    Subject.name.asc()
                )
                .all()
            )

            # =================================================
            # CLASSES
            # =================================================

            classes_query = (
                Class.query
                .filter(
                    Class.program_id ==
                    selected_exam.program_id,

                    Class.institution_id ==
                    selected_exam.institution_id
                )
            )

            if selected_exam.branch_id:

                classes_query = (
                    classes_query
                    .filter(
                        Class.branch_id ==
                        selected_exam.branch_id
                    )
                )

            if selected_exam.academic_year_id:

                classes_query = (
                    classes_query
                    .filter(
                        Class.academic_year_id ==
                        selected_exam.academic_year_id
                    )
                )

            classes = (
                classes_query
                .order_by(
                    Class.name.asc()
                )
                .all()
            )

            # =================================================
            # TEACHER ASSIGNMENTS
            # =================================================

            teacher_query = (
                db.session.query(
                    TeacherSubject,
                    Teacher
                )
                .join(
                    Teacher,
                    Teacher.id ==
                    TeacherSubject.teacher_id
                )
                .filter(
                    Teacher.institution_id ==
                    selected_exam.institution_id,

                    Teacher.is_active.is_(True),

                    Teacher.status ==
                    "active",

                    TeacherSubject.institution_id ==
                    selected_exam.institution_id,

                    TeacherSubject.program_id ==
                    selected_exam.program_id,

                    TeacherSubject.status ==
                    "active",

                    TeacherSubject.subject_id.isnot(None)
                )
            )

            # =================================================
            # BRANCH SECURITY
            # =================================================

            if selected_exam.branch_id:

                teacher_query = (
                    teacher_query
                    .filter(
                        Teacher.branch_id ==
                        selected_exam.branch_id,

                        db.or_(
                            TeacherSubject.branch_id ==
                            selected_exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            teacher_rows = (
                teacher_query
                .order_by(
                    Teacher.full_name.asc()
                )
                .all()
            )

            # =================================================
            # GET DISTINCT TEACHERS BY SUBJECT
            #
            # IMPORTANT:
            #
            # The resulting value is:
            #
            #     teachers_by_subject[subject_id]
            #
            # as a LIST.
            #
            # This preserves compatibility with:
            #
            #     subject_teachers[0].full_name
            # =================================================

            temporary_teacher_map = {}

            for assignment, teacher in teacher_rows:

                if assignment.subject_id is None:
                    continue

                subject_id = int(
                    assignment.subject_id
                )

                teacher_id = int(
                    teacher.id
                )

                subject_map = (
                    temporary_teacher_map
                    .setdefault(
                        subject_id,
                        {}
                    )
                )

                # ---------------------------------------------
                # DISTINCT TEACHER
                # ---------------------------------------------

                subject_map[
                    teacher_id
                ] = teacher

            # =================================================
            # CONVERT TO LIST
            # =================================================

            for subject_id, teacher_map in (
                temporary_teacher_map.items()
            ):

                teacher_list = list(
                    teacher_map.values()
                )

                # ------------------------------------------------
                # STABLE ORDER
                # ------------------------------------------------

                teacher_list.sort(
                    key=lambda teacher: (
                        (
                            teacher.full_name
                            or ""
                        ).lower(),
                        int(teacher.id)
                    )
                )

                teachers_by_subject[
                    subject_id
                ] = teacher_list

            # =================================================
            # ASSIGNMENT STATUS
            # =================================================

            for subject in subjects:

                subject_id = int(
                    subject.id
                )

                subject_teachers = (
                    teachers_by_subject.get(
                        subject_id,
                        []
                    )
                )

                # ------------------------------------------------
                # NO TEACHER
                # ------------------------------------------------

                if not subject_teachers:

                    missing_teacher_subject_ids.add(
                        subject_id
                    )

                    continue

                # ------------------------------------------------
                # EXACTLY ONE DISTINCT TEACHER
                # ------------------------------------------------

                if len(subject_teachers) == 1:

                    assigned_subject_ids.add(
                        subject_id
                    )

                # ------------------------------------------------
                # MULTIPLE DISTINCT TEACHERS
                # ------------------------------------------------

                else:

                    multiple_teacher_subject_ids.add(
                        subject_id
                    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/bulk_add_exam_subjects.html",

        exams=exams,

        selected_exam_id=selected_exam_id,

        selected_exam=selected_exam,

        subjects=subjects,

        classes=classes,

        teachers_by_subject=teachers_by_subject,

        assigned_subject_ids=assigned_subject_ids,

        missing_teacher_subject_ids=missing_teacher_subject_ids,

        multiple_teacher_subject_ids=multiple_teacher_subject_ids,

        user=current_user
    )





# ============================================================
# VIEW SINGLE EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>",
    methods=["GET"]
)
@login_required
def view_exam_subject(exam_subject_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_view():
        abort(403)

    # ========================================================
    # QUERY
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    # ========================================================
    # SCOPE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        query = query.filter(
            Exam.institution_id == institution_id
        )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        query = query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    elif role == "teacher":

        # Teacher can see only subjects assigned to them.
        teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if teacher_id:

            query = query.filter(
                ExamSubject.teacher_id == teacher_id
            )

        else:

            query = query.filter(False)

    exam_subject = query.first()

    if not exam_subject:
        abort(404)

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/view_exam_subject.html",
        exam_subject=exam_subject,
    )


# ============================================================
# ALL EXAM SUBJECTS
# ============================================================

@bp.route(
    "/exam-subjects",
    methods=["GET"]
)
@login_required
def all_exam_subjects():

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_view():
        abort(403)

    # ========================================================
    # CURRENT ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    # ========================================================
    # FILTERS
    # ========================================================

    search = (
        request.args.get(
            "search",
            ""
        )
        .strip()
    )

    status = (
        request.args.get(
            "status",
            ""
        )
        .strip()
        .lower()
    )

    exam_id = request.args.get(
        "exam_id",
        type=int
    )

    subject_id = request.args.get(
        "subject_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .join(
            Subject,
            Subject.id == ExamSubject.subject_id
        )
    )

    # ========================================================
    # ROLE SCOPE
    # ========================================================

    if role == "superadmin":

        # Superadmin can see everything.
        pass

    elif role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:

            query = query.filter(False)

        else:

            query = query.filter(
                Exam.institution_id == institution_id
            )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:

            query = query.filter(False)

        else:

            query = query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if not current_teacher_id:

            query = query.filter(False)

        else:

            query = query.filter(
                ExamSubject.teacher_id ==
                current_teacher_id
            )

    else:

        query = query.filter(False)

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_term = f"%{search}%"

        query = query.filter(
            db.or_(
                Exam.name.ilike(search_term),
                Exam.code.ilike(search_term),
                Subject.name.ilike(search_term),
                Subject.code.ilike(search_term),
            )
        )

    # ========================================================
    # STATUS
    # ========================================================

    if status:

        query = query.filter(
            ExamSubject.status == status
        )

    # ========================================================
    # EXAM
    # ========================================================

    if exam_id:

        query = query.filter(
            ExamSubject.exam_id == exam_id
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    if subject_id:

        query = query.filter(
            ExamSubject.subject_id == subject_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:

        query = query.filter(
            ExamSubject.class_id == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        query = query.filter(
            ExamSubject.section_id == section_id
        )

    # ========================================================
    # TEACHER
    # ========================================================

    if teacher_id:

        query = query.filter(
            ExamSubject.teacher_id == teacher_id
        )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        ExamSubject.display_order.asc(),
        ExamSubject.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    # ========================================================
    # FILTER DATA
    # ========================================================

    # --------------------------------------------------------
    # EXAMS
    # --------------------------------------------------------

    exams_query = Exam.query

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id
        )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            exams_query = (
                exams_query
                .join(
                    ExamSubject,
                    ExamSubject.exam_id == Exam.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            exams_query = exams_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }:

        exams_query = exams_query.filter(False)

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # SUBJECTS
    # --------------------------------------------------------

    subjects_query = Subject.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            subjects_query = (
                subjects_query
                .join(
                    ExamSubject,
                    ExamSubject.subject_id == Subject.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            subjects_query = subjects_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        subjects_query = subjects_query.filter(False)

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # CLASSES
    # --------------------------------------------------------

    classes_query = Class.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            classes_query = (
                classes_query
                .join(
                    ExamSubject,
                    ExamSubject.class_id == Class.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            classes_query = classes_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        classes_query = classes_query.filter(False)

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # SECTIONS
    # --------------------------------------------------------

    sections_query = Section.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            sections_query = (
                sections_query
                .join(
                    ExamSubject,
                    ExamSubject.section_id == Section.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            sections_query = sections_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        sections_query = sections_query.filter(False)

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # TEACHERS
    # --------------------------------------------------------

    teachers_query = Teacher.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            teachers_query = teachers_query.filter(
                Teacher.id == current_teacher_id
            )

        else:

            teachers_query = teachers_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        teachers_query = teachers_query.filter(False)

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
            if hasattr(Teacher, "full_name")
            else Teacher.id.asc()
        )
        .all()
    )

    # ========================================================
    # STATISTICS
    # ========================================================

    # --------------------------------------------------------
    # Statistics query
    #
    # IMPORTANT:
    # We use the same ROLE SCOPE but do NOT use the
    # user's current filters.
    # --------------------------------------------------------

    stats_query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
    )

    # ========================================================
    # STATISTICS ROLE SCOPE
    # ========================================================

    if role == "superadmin":

        pass

    elif role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                Exam.institution_id == institution_id
            )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if not current_teacher_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                ExamSubject.teacher_id ==
                current_teacher_id
            )

    else:

        stats_query = stats_query.filter(False)

    # ========================================================
    # TOTAL
    # ========================================================

    total_exam_subjects = (
        stats_query
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # ACTIVE
    # ========================================================

    active_exam_subjects = (
        stats_query
        .filter(
            ExamSubject.status == "active"
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # INACTIVE
    # ========================================================

    inactive_exam_subjects = (
        stats_query
        .filter(
            ExamSubject.status == "inactive"
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TEACHER ASSIGNED
    # ========================================================

    exam_subjects_with_teacher = (
        stats_query
        .filter(
            ExamSubject.teacher_id.isnot(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TEACHER NOT ASSIGNED
    # ========================================================

    exam_subjects_without_teacher = (
        stats_query
        .filter(
            ExamSubject.teacher_id.is_(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # CLASS ASSIGNED
    # ========================================================

    exam_subjects_with_class = (
        stats_query
        .filter(
            ExamSubject.class_id.isnot(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/exam_subjects/all_exam_subjects.html",

        # ----------------------------------------------------
        # MAIN DATA
        # ----------------------------------------------------

        exam_subjects=pagination.items,

        pagination=pagination,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        exams=exams,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        # ----------------------------------------------------
        # FILTER VALUES
        # ----------------------------------------------------

        search=search,

        status=status,

        selected_exam_id=exam_id,

        selected_subject_id=subject_id,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_teacher_id=teacher_id,

        selected_status=status,

        per_page=per_page,

        # ----------------------------------------------------
        # STATISTICS
        # ----------------------------------------------------

        total_exam_subjects=total_exam_subjects,

        active_exam_subjects=active_exam_subjects,

        inactive_exam_subjects=inactive_exam_subjects,

        exam_subjects_with_teacher=
            exam_subjects_with_teacher,

        exam_subjects_without_teacher=
            exam_subjects_without_teacher,

        exam_subjects_with_class=
            exam_subjects_with_class,

        # ----------------------------------------------------
        # CURRENT USER
        # ----------------------------------------------------

        user=current_user
    )


# ============================================================
# EDIT EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam_subject(exam_subject_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD EXAM SUBJECT
    # ========================================================

    exam_subject_query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    # ========================================================
    # INSTITUTION / BRANCH SECURITY
    # ========================================================

    if current_role == "school_admin":

        if not institution_id:
            abort(403)

        exam_subject_query = (
            exam_subject_query
            .filter(
                Exam.institution_id == institution_id
            )
        )

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exam_subject_query = (
            exam_subject_query
            .filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )
        )

    # ========================================================
    # GET EXAM SUBJECT
    # ========================================================

    exam_subject = (
        exam_subject_query
        .first()
    )

    if not exam_subject:
        abort(404)

    # ========================================================
    # EXAM
    # ========================================================

    exam = exam_subject.exam

    if not exam:
        abort(404)

    # ========================================================
    # PROGRAM
    # ========================================================

    if not exam.program_id:
        flash(
            "The exam has no program assigned.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    program = (
        Program.query
        .filter(
            Program.id == exam.program_id
        )
        .first()
    )

    if not program:
        flash(
            "The program assigned to this exam was not found.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # SUBJECT
        # ====================================================

        raw_subject_id = request.form.get(
            "subject_id"
        )

        raw_subject_id = (
            str(raw_subject_id).strip()
            if raw_subject_id
            else ""
        )

        if not raw_subject_id:

            flash(
                "Please select a subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        try:

            subject_id = int(
                raw_subject_id
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # VALID SUBJECT
        #
        # Subject must belong to:
        #
        # Exam.program_id
        # Exam.institution_id
        #
        # Branch can be:
        #
        #   exam.branch_id
        #   NULL/shared
        # ====================================================

        subject_query = (
            Subject.query
            .filter(
                Subject.id == subject_id,
                Subject.program_id == exam.program_id,
                Subject.institution_id == exam.institution_id,
                Subject.status == "active"
            )
        )

        if exam.branch_id:

            subject_query = (
                subject_query
                .filter(
                    db.or_(
                        Subject.branch_id == exam.branch_id,
                        Subject.branch_id.is_(None)
                    )
                )
            )

        subject = (
            subject_query
            .first()
        )

        if not subject:

            flash(
                "The selected subject does not belong to the selected exam program.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # CLASS
        # ====================================================

        raw_class_id = request.form.get(
            "class_id"
        )

        raw_class_id = (
            str(raw_class_id).strip()
            if raw_class_id
            else ""
        )

        class_id = None
        selected_class = None

        if raw_class_id:

            try:

                class_id = int(
                    raw_class_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid class.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            class_query = (
                Class.query
                .filter(
                    Class.id == class_id,
                    Class.program_id == exam.program_id,
                    Class.institution_id == exam.institution_id
                )
            )

            # ------------------------------------------------
            # Branch
            # ------------------------------------------------

            if exam.branch_id:

                class_query = (
                    class_query
                    .filter(
                        Class.branch_id == exam.branch_id
                    )
                )

            # ------------------------------------------------
            # Academic Year
            # ------------------------------------------------

            if exam.academic_year_id:

                class_query = (
                    class_query
                    .filter(
                        Class.academic_year_id ==
                        exam.academic_year_id
                    )
                )

            selected_class = (
                class_query
                .first()
            )

            if not selected_class:

                flash(
                    "The selected class does not belong to the exam program.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # SECTION
        # ====================================================

        raw_section_id = request.form.get(
            "section_id"
        )

        raw_section_id = (
            str(raw_section_id).strip()
            if raw_section_id
            else ""
        )

        section_id = None
        selected_section = None

        if raw_section_id:

            # ------------------------------------------------
            # Section requires class
            # ------------------------------------------------

            if not class_id:

                flash(
                    "Please select a class before selecting a section.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            try:

                section_id = int(
                    raw_section_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid section.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            selected_section = (
                Section.query
                .filter(
                    Section.id == section_id,
                    Section.class_id == class_id
                )
                .first()
            )

            if not selected_section:

                flash(
                    "The selected section does not belong to the selected class.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # TEACHER
        # ====================================================

        raw_teacher_id = request.form.get(
            "teacher_id"
        )

        raw_teacher_id = (
            str(raw_teacher_id).strip()
            if raw_teacher_id
            else ""
        )

        teacher_id = None
        teacher = None

        if raw_teacher_id:

            try:

                teacher_id = int(
                    raw_teacher_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid teacher.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # Teacher base validation
            # ------------------------------------------------

            teacher_query = (
                Teacher.query
                .filter(
                    Teacher.id == teacher_id,
                    Teacher.institution_id ==
                    exam.institution_id,
                    Teacher.is_active.is_(True),
                    Teacher.status == "active"
                )
            )

            if exam.branch_id:

                teacher_query = (
                    teacher_query
                    .filter(
                        Teacher.branch_id ==
                        exam.branch_id
                    )
                )

            teacher = (
                teacher_query
                .first()
            )

            if not teacher:

                flash(
                    "The selected teacher is not available for this exam.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # TeacherSubject
            #
            # Program + Subject
            # ------------------------------------------------

            teacher_assignment_query = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id ==
                    teacher_id,

                    TeacherSubject.program_id ==
                    exam.program_id,

                    TeacherSubject.institution_id ==
                    exam.institution_id,

                    TeacherSubject.status ==
                    "active",

                    db.or_(
                        TeacherSubject.subject_id.is_(None),
                        TeacherSubject.subject_id ==
                        subject_id
                    )
                )
            )

            # ------------------------------------------------
            # Branch
            # ------------------------------------------------

            if exam.branch_id:

                teacher_assignment_query = (
                    teacher_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.branch_id ==
                            exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            # ------------------------------------------------
            # Academic Year
            # ------------------------------------------------

            if exam.academic_year_id:

                teacher_assignment_query = (
                    teacher_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.academic_year_id ==
                            exam.academic_year_id,

                            TeacherSubject.academic_year_id.is_(None)
                        )
                    )
                )

            teacher_assignment = (
                teacher_assignment_query
                .first()
            )

            if not teacher_assignment:

                flash(
                    f"{teacher.full_name} is not assigned to {subject.name}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # Class / Section compatibility
            #
            # TeacherSubject class_id NULL
            # = program-wide assignment
            #
            # TeacherSubject section_id NULL
            # = all sections
            # ------------------------------------------------

            compatible_assignment_query = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id ==
                    teacher_id,

                    TeacherSubject.program_id ==
                    exam.program_id,

                    TeacherSubject.institution_id ==
                    exam.institution_id,

                    TeacherSubject.status ==
                    "active",

                    db.or_(
                        TeacherSubject.subject_id.is_(None),
                        TeacherSubject.subject_id ==
                        subject_id
                    )
                )
            )

            if exam.branch_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.branch_id ==
                            exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            if exam.academic_year_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.academic_year_id ==
                            exam.academic_year_id,

                            TeacherSubject.academic_year_id.is_(None)
                        )
                    )
                )

            # ------------------------------------------------
            # Class compatibility
            # ------------------------------------------------

            if class_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.class_id.is_(None),
                            TeacherSubject.class_id ==
                            class_id
                        )
                    )
                )

            else:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        TeacherSubject.class_id.is_(None)
                    )
                )

            # ------------------------------------------------
            # Section compatibility
            # ------------------------------------------------

            if section_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.section_id.is_(None),
                            TeacherSubject.section_id ==
                            section_id
                        )
                    )
                )

            else:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        TeacherSubject.section_id.is_(None)
                    )
                )

            compatible_assignment = (
                compatible_assignment_query
                .first()
            )

            if not compatible_assignment:

                flash(
                    f"{teacher.full_name} is not assigned to the selected class/section for {subject.name}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # MAX MARKS
        # ====================================================

        raw_max_marks = request.form.get(
            "max_marks",
            "100"
        )

        try:

            max_marks = float(
                raw_max_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if max_marks <= 0:

            flash(
                "Maximum marks must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # PASS MARKS
        # ====================================================

        raw_pass_marks = request.form.get(
            "pass_marks",
            "50"
        )

        try:

            pass_marks = float(
                raw_pass_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid pass marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if pass_marks < 0:

            flash(
                "Pass marks cannot be negative.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if pass_marks > max_marks:

            flash(
                "Pass marks cannot exceed maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # WEIGHT
        # ====================================================

        raw_weight = request.form.get(
            "weight",
            "100"
        )

        try:

            weight = float(
                raw_weight
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid weight.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if weight <= 0:

            flash(
                "Weight must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # DISPLAY ORDER
        # ====================================================

        raw_display_order = request.form.get(
            "display_order",
            "1"
        )

        try:

            display_order = int(
                raw_display_order
            )

        except (
            TypeError,
            ValueError
        ):

            display_order = 1

        if display_order <= 0:

            display_order = 1

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # DUPLICATE PROTECTION
        #
        # exam + subject + class + section
        #
        # EXCLUDE CURRENT RECORD
        # ====================================================

        duplicate_query = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id == exam.id,

                ExamSubject.subject_id ==
                subject_id,

                ExamSubject.id !=
                exam_subject.id
            )
        )

        # ----------------------------------------------------
        # Class
        # ----------------------------------------------------

        if class_id is None:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.class_id.is_(None)
                )
            )

        else:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.class_id ==
                    class_id
                )
            )

        # ----------------------------------------------------
        # Section
        # ----------------------------------------------------

        if section_id is None:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.section_id.is_(None)
                )
            )

        else:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.section_id ==
                    section_id
                )
            )

        duplicate = (
            duplicate_query
            .first()
        )

        if duplicate:

            class_text = (
                selected_class.name
                if selected_class
                else "All Classes"
            )

            section_text = (
                selected_section.name
                if selected_section
                else "All Sections"
            )

            flash(
                f"{subject.name} already exists for {class_text} / {section_text}.",
                "warning"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # UPDATE
        # ====================================================

        exam_subject.subject_id = subject_id
        exam_subject.class_id = class_id
        exam_subject.section_id = section_id
        exam_subject.teacher_id = teacher_id
        exam_subject.max_marks = max_marks
        exam_subject.pass_marks = pass_marks
        exam_subject.weight = weight
        exam_subject.display_order = display_order
        exam_subject.status = status

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Failed to update exam subject %s: %s",
                exam_subject_id,
                exc
            )

            flash(
                "An error occurred while updating the exam subject. No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            "Exam subject updated successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.view_exam_subject",
                exam_subject_id=exam_subject.id
            )
        )

    # ========================================================
    # GET DATA
    # ========================================================

    # ========================================================
    # SUBJECTS
    #
    # Only subjects belonging to this exam's program.
    # ========================================================

    subjects_query = (
        Subject.query
        .filter(
            Subject.program_id == exam.program_id,
            Subject.institution_id == exam.institution_id,
            Subject.status == "active"
        )
    )

    if exam.branch_id:

        subjects_query = (
            subjects_query
            .filter(
                db.or_(
                    Subject.branch_id == exam.branch_id,
                    Subject.branch_id.is_(None)
                )
            )
        )

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    #
    # Optional.
    #
    # Some programs have no classes.
    # ========================================================

    classes_query = (
        Class.query
        .filter(
            Class.program_id == exam.program_id,
            Class.institution_id == exam.institution_id
        )
    )

    if exam.branch_id:

        classes_query = (
            classes_query
            .filter(
                Class.branch_id == exam.branch_id
            )
        )

    if exam.academic_year_id:

        classes_query = (
            classes_query
            .filter(
                Class.academic_year_id ==
                exam.academic_year_id
            )
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    class_ids = [
        int(item.id)
        for item in classes
    ]

    sections = []

    if class_ids:

        sections = (
            Section.query
            .filter(
                Section.class_id.in_(
                    class_ids
                )
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # PROGRAM TEACHERS
    #
    # IMPORTANT:
    # NOT ALL BRANCH TEACHERS.
    #
    # Only teachers assigned to:
    #
    # Exam Program
    #      ↓
    # TeacherSubject
    #      ↓
    # Teacher
    # ========================================================

    teachers_query = (
        Teacher.query
        .join(
            TeacherSubject,
            TeacherSubject.teacher_id ==
            Teacher.id
        )
        .filter(
            Teacher.institution_id ==
            exam.institution_id,

            Teacher.is_active.is_(True),

            Teacher.status == "active",

            TeacherSubject.institution_id ==
            exam.institution_id,

            TeacherSubject.program_id ==
            exam.program_id,

            TeacherSubject.status ==
            "active"
        )
    )

    # ========================================================
    # BRANCH
    # ========================================================

    if exam.branch_id:

        teachers_query = (
            teachers_query
            .filter(
                Teacher.branch_id ==
                exam.branch_id,

                db.or_(
                    TeacherSubject.branch_id ==
                    exam.branch_id,

                    TeacherSubject.branch_id.is_(None)
                )
            )
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if exam.academic_year_id:

        teachers_query = (
            teachers_query
            .filter(
                db.or_(
                    TeacherSubject.academic_year_id ==
                    exam.academic_year_id,

                    TeacherSubject.academic_year_id.is_(None)
                )
            )
        )

    teachers = (
        teachers_query
        .distinct()
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/edit_exam_subject.html",

        exam_subject=exam_subject,

        exam=exam,

        program=program,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        user=current_user
    )




# ============================================================
# DELETE EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_subject(exam_subject_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_manage():
        abort(403)

    # ========================================================
    # LOAD WITH SCOPE
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    query = _exam_subject_scope_query(
        query
    )

    exam_subject = query.first()

    if not exam_subject:

        # AJAX / FETCH REQUEST
        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": False,
                "message": "Exam subject was not found."
            }), 404

        abort(404)

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            exam_subject
        )

        db.session.commit()

        # ====================================================
        # AJAX RESPONSE
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": True,
                "message": "Exam subject deleted successfully."
            }), 200

        # ====================================================
        # NORMAL POST RESPONSE
        # ====================================================

        flash(
            "Exam subject deleted successfully.",
            "success"
        )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Error deleting ExamSubject ID %s: %s",
            exam_subject_id,
            e
        )

        # ====================================================
        # AJAX ERROR
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": False,
                "message": "Unable to delete exam subject."
            }), 500

        # ====================================================
        # NORMAL POST ERROR
        # ====================================================

        flash(
            "Unable to delete exam subject.",
            "danger"
        )

    # ========================================================
    # NORMAL POST REDIRECT
    # ========================================================

    return redirect(
        url_for(
            "main.all_exam_subjects"
        )
    )

# ============================================================
# DELETE ENTIRE EXAM
# ============================================================

@bp.route(
    "/exam/<int:exam_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_subjs(exam_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_can_manage():
        abort(403)

    # ========================================================
    # LOAD EXAM WITH USER SCOPE
    # ========================================================

    query = (
        Exam.query
        .filter(
            Exam.id == exam_id
        )
    )

    query = _exam_scope_query(
        query
    )

    exam = query.first()

    # ========================================================
    # EXAM NOT FOUND
    # ========================================================

    if not exam:

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({
                "success": False,
                "message": "Exam was not found."
            }), 404

        flash(
            "Exam was not found.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    # ========================================================
    # EXAM INFORMATION
    # ========================================================

    exam_name = (
        getattr(
            exam,
            "name",
            None
        )
        or
        getattr(
            exam,
            "title",
            None
        )
        or
        f"Exam #{exam.id}"
    )

    exam_id_value = exam.id

    # ========================================================
    # DELETE EXAM SUBJECTS ONLY
    # ========================================================

    try:

        # ----------------------------------------------------
        # DELETE ALL EXAM SUBJECTS BELONGING TO THIS EXAM
        # ----------------------------------------------------

        deleted_exam_subjects = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id == exam.id
            )
            .delete(
                synchronize_session=False
            )
        )

        # ====================================================
        # COMMIT
        # ====================================================

        db.session.commit()

        # ====================================================
        # SUCCESS
        # ====================================================

        message = (
            f"{deleted_exam_subjects} exam subject(s) "
            f"from {exam_name} were deleted successfully."
        )

        # ====================================================
        # AJAX RESPONSE
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({

                "success": True,

                "message": message,

                "exam_id": exam_id_value,

                "deleted_exam_subjects":
                    deleted_exam_subjects

            }), 200

        # ====================================================
        # NORMAL RESPONSE
        # ====================================================

        flash(
            message,
            "success"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    # ========================================================
    # ERROR
    # ========================================================

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "Unable to delete ExamSubjects for Exam ID %s",
            exam_id_value
        )

        # ====================================================
        # AJAX ERROR
        # ====================================================

        if request.headers.get(
            "X-Requested-With"
        ) == "XMLHttpRequest":

            return jsonify({

                "success": False,

                "message":
                    "Unable to delete the exam subjects. "
                    "They may have other related records."

            }), 500

        # ====================================================
        # NORMAL ERROR
        # ====================================================

        flash(
            "Unable to delete the exam subjects. "
            "They may have other related records.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )


# ============================================================
# ALL STUDENT ATTENDANCE
# SUPERADMIN / SCHOOL ADMIN / BRANCH ADMIN
# ============================================================

@bp.route(
    "/attendance/students",
    methods=["GET"]
)
@login_required
def all_student_attendance():

    # ========================================================
    # SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "institution_admin",
        "branch_admin",
    }

    raw_role = getattr(
        current_user,
        "role",
        None
    )

    user_role = (
        raw_role.value
        if hasattr(raw_role, "value")
        else str(raw_role or "")
    ).strip().lower()

    if user_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE SCOPE VALIDATION
    # ========================================================

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        if not user_institution_id:
            abort(403)

    elif user_role == "branch_admin":

        if not user_institution_id:
            abort(403)

        if not user_branch_id:
            abort(403)

    # ========================================================
    # SAFE INTEGER PARSER
    # ========================================================

    def parse_optional_id(
        value,
        field_name
    ):

        if value in (
            None,
            "",
            "None",
            "null",
        ):
            return None

        try:
            parsed = int(value)

        except (
            TypeError,
            ValueError
        ):
            abort(
                400,
                description=f"Invalid {field_name}."
            )

        if parsed <= 0:
            abort(
                400,
                description=f"Invalid {field_name}."
            )

        return parsed

    # ========================================================
    # REQUEST FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    class_id = request.args.get(
        "class_id",
        "",
        type=str
    ).strip()

    section_id = request.args.get(
        "section_id",
        "",
        type=str
    ).strip()

    subject_id = request.args.get(
        "subject_id",
        "",
        type=str
    ).strip()

    teacher_id = request.args.get(
        "teacher_id",
        "",
        type=str
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    session_type = request.args.get(
        "session_type",
        "",
        type=str
    ).strip().lower()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ========================================================
    # PARSE IDs
    # ========================================================

    requested_institution_id = parse_optional_id(
        institution_id,
        "institution_id"
    )

    requested_branch_id = parse_optional_id(
        branch_id,
        "branch_id"
    )

    requested_class_id = parse_optional_id(
        class_id,
        "class_id"
    )

    requested_section_id = parse_optional_id(
        section_id,
        "section_id"
    )

    requested_subject_id = parse_optional_id(
        subject_id,
        "subject_id"
    )

    requested_teacher_id = parse_optional_id(
        teacher_id,
        "teacher_id"
    )

    # ========================================================
    # ROLE-BASED FILTER SECURITY
    # ========================================================

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        if requested_institution_id is not None:

            if requested_institution_id != int(
                user_institution_id
            ):
                abort(403)

    elif user_role == "branch_admin":

        if requested_institution_id is not None:

            if requested_institution_id != int(
                user_institution_id
            ):
                abort(403)

        if requested_branch_id is not None:

            if requested_branch_id != int(
                user_branch_id
            ):
                abort(403)

    # ========================================================
    # ALLOWED ATTENDANCE STATUSES
    # ========================================================

    allowed_attendance_statuses = {
        "present",
        "absent",
        "late",
        "excused",
        "sick",
        "leave",
    }

    if status:

        if status not in allowed_attendance_statuses:

            abort(
                400,
                description="Invalid attendance status."
            )

    # ========================================================
    # ALLOWED SESSION TYPES
    # ========================================================

    allowed_session_types = {
        "class",
        "subject",
        "morning",
        "afternoon",
        "exam",
        "other",
    }

    if session_type:

        if session_type not in allowed_session_types:

            abort(
                400,
                description="Invalid attendance session type."
            )

    # ========================================================
    # DATE PARSING
    # ========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = datetime.strptime(
                date_from,
                "%Y-%m-%d"
            ).date()

        except ValueError:

            abort(
                400,
                description="Invalid date_from. Use YYYY-MM-DD."
            )

    if date_to:

        try:

            parsed_date_to = datetime.strptime(
                date_to,
                "%Y-%m-%d"
            ).date()

        except ValueError:

            abort(
                400,
                description="Invalid date_to. Use YYYY-MM-DD."
            )

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from > parsed_date_to
    ):

        abort(
            400,
            description="date_from cannot be after date_to."
        )

    # ========================================================
    # PAGINATION
    # ========================================================

    try:

        page = int(
            request.args.get(
                "page",
                1
            )
        )

    except (
        TypeError,
        ValueError
    ):

        page = 1

    try:

        per_page = int(
            request.args.get(
                "per_page",
                25
            )
        )

    except (
        TypeError,
        ValueError
    ):

        per_page = 25

    if page < 1:
        page = 1

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # COMMON ATTENDANCE QUERY
    #
    # IMPORTANT:
    # Main records and statistics MUST use
    # exactly the same base query.
    # ========================================================

    base_query = (
        AttendanceRecord.query

        # Attendance Session
        .join(
            AttendanceRecord.session
        )

        # Student
        .join(
            AttendanceRecord.student
        )

        # Enrollment
        .outerjoin(
            AttendanceRecord.enrollment
        )

        # Teacher
        .join(
            Teacher,
            AttendanceSession.teacher_id
            == Teacher.id
        )

        # Subject
        .outerjoin(
            Subject,
            AttendanceSession.subject_id
            == Subject.id
        )

        # Class
        .join(
            Class,
            AttendanceSession.class_id
            == Class.id
        )

        # Section
        .outerjoin(
            Section,
            AttendanceSession.section_id
            == Section.id
        )
    )

    # ========================================================
    # SECURITY SCOPE
    # ========================================================

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        base_query = base_query.filter(
            AttendanceSession.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        base_query = base_query.filter(
            AttendanceSession.institution_id
            == user_institution_id,

            AttendanceSession.branch_id
            == user_branch_id
        )

    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    if requested_institution_id is not None:

        base_query = base_query.filter(
            AttendanceSession.institution_id
            == requested_institution_id
        )

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if requested_branch_id is not None:

        base_query = base_query.filter(
            AttendanceSession.branch_id
            == requested_branch_id
        )

    # ========================================================
    # CLASS FILTER
    # ========================================================

    if requested_class_id is not None:

        base_query = base_query.filter(
            AttendanceSession.class_id
            == requested_class_id
        )

    # ========================================================
    # SECTION FILTER
    # ========================================================

    if requested_section_id is not None:

        base_query = base_query.filter(
            AttendanceSession.section_id
            == requested_section_id
        )

    # ========================================================
    # SUBJECT FILTER
    # ========================================================

    if requested_subject_id is not None:

        base_query = base_query.filter(
            AttendanceSession.subject_id
            == requested_subject_id
        )

    # ========================================================
    # TEACHER FILTER
    # ========================================================

    if requested_teacher_id is not None:

        base_query = base_query.filter(
            AttendanceSession.teacher_id
            == requested_teacher_id
        )

    # ========================================================
    # STATUS FILTER
    # ========================================================

    if status:

        base_query = base_query.filter(
            AttendanceRecord.status
            == status
        )

    # ========================================================
    # SESSION TYPE FILTER
    # ========================================================

    if session_type:

        base_query = base_query.filter(
            AttendanceSession.session_type
            == session_type
        )

    # ========================================================
    # DATE FROM
    # ========================================================

    if parsed_date_from:

        base_query = base_query.filter(
            AttendanceSession.attendance_date
            >= parsed_date_from
        )

    # ========================================================
    # DATE TO
    # ========================================================

    if parsed_date_to:

        base_query = base_query.filter(
            AttendanceSession.attendance_date
            <= parsed_date_to
        )

    # ========================================================
    # SEARCH
    #
    # IMPORTANT:
    # Teacher.roll_no has been REMOVED.
    # Your Teacher model does not have roll_no.
    # ========================================================

    if search:

        search_pattern = f"%{search}%"

        search_conditions = [

            # ------------------------------------------------
            # STUDENT
            # ------------------------------------------------

            Student.full_name.ilike(
                search_pattern
            ),

            Student.admission_no.ilike(
                search_pattern
            ),

            Student.roll_no.ilike(
                search_pattern
            ),

            Student.username.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # TEACHER
            # ------------------------------------------------

            Teacher.full_name.ilike(
                search_pattern
            ),

            Teacher.username.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # SUBJECT
            # ------------------------------------------------

            Subject.name.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # CLASS
            # ------------------------------------------------

            Class.name.ilike(
                search_pattern
            ),

            # ------------------------------------------------
            # SECTION
            # ------------------------------------------------

            Section.name.ilike(
                search_pattern
            ),
        ]

        base_query = base_query.filter(
            or_(
                *search_conditions
            )
        )

    # ========================================================
    # MAIN RECORDS
    # ========================================================

    records_query = (
        base_query
        .order_by(
            AttendanceSession.attendance_date.desc(),
            AttendanceRecord.created_at.desc(),
            AttendanceRecord.id.desc()
        )
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = records_query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    attendance_records = pagination.items

    # ========================================================
    # STATISTICS
    #
    # SAME base_query.
    #
    # This fixes the problem where:
    #
    # records = 2
    # statistics = 0
    #
    # ========================================================

    from sqlalchemy import func, case

    stats_row = (
        base_query
        .with_entities(

            func.count(
                AttendanceRecord.id
            ).label(
                "total_attendance"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "present",
                        1
                    ),
                    else_=0
                )
            ).label(
                "present_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "absent",
                        1
                    ),
                    else_=0
                )
            ).label(
                "absent_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "late",
                        1
                    ),
                    else_=0
                )
            ).label(
                "late_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "excused",
                        1
                    ),
                    else_=0
                )
            ).label(
                "excused_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "sick",
                        1
                    ),
                    else_=0
                )
            ).label(
                "sick_count"
            ),

            func.sum(
                case(
                    (
                        AttendanceRecord.status
                        == "leave",
                        1
                    ),
                    else_=0
                )
            ).label(
                "leave_count"
            ),
        )
        .first()
    )

    # ========================================================
    # SAFE STATISTICS VALUES
    # ========================================================

    total_attendance = int(
        stats_row.total_attendance or 0
    )

    present_count = int(
        stats_row.present_count or 0
    )

    absent_count = int(
        stats_row.absent_count or 0
    )

    late_count = int(
        stats_row.late_count or 0
    )

    excused_count = int(
        stats_row.excused_count or 0
    )

    sick_count = int(
        stats_row.sick_count or 0
    )

    leave_count = int(
        stats_row.leave_count or 0
    )

    # ========================================================
    # ATTENDANCE PERCENTAGE
    # ========================================================

    if total_attendance > 0:

        attendance_percentage = round(
            (
                present_count
                / total_attendance
            ) * 100,
            2
        )

    else:

        attendance_percentage = 0

    # ========================================================
    # FILTER DATA
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institutions_query = Institution.query

    if user_role in {
        "school_admin",
        "institution_admin",
        "branch_admin",
    }:

        institutions_query = institutions_query.filter(
            Institution.id
            == user_institution_id
        )

    institutions = (
        institutions_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = Branch.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        branches_query = branches_query.filter(
            Branch.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        branches_query = branches_query.filter(
            Branch.institution_id
            == user_institution_id,

            Branch.id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            branches_query = branches_query.filter(
                Branch.institution_id
                == requested_institution_id
            )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    classes_query = Class.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        classes_query = classes_query.filter(
            Class.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        classes_query = classes_query.filter(
            Class.institution_id
            == user_institution_id,

            Class.branch_id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            classes_query = classes_query.filter(
                Class.institution_id
                == requested_institution_id
            )

        if requested_branch_id is not None:

            classes_query = classes_query.filter(
                Class.branch_id
                == requested_branch_id
            )

    # --------------------------------------------------------
    # APPLY SELECTED FILTERS
    # --------------------------------------------------------

    if requested_institution_id is not None:

        classes_query = classes_query.filter(
            Class.institution_id
            == requested_institution_id
        )

    if requested_branch_id is not None:

        classes_query = classes_query.filter(
            Class.branch_id
            == requested_branch_id
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections_query = Section.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        sections_query = sections_query.filter(
            Section.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        sections_query = sections_query.filter(
            Section.institution_id
            == user_institution_id,

            Section.branch_id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            sections_query = sections_query.filter(
                Section.institution_id
                == requested_institution_id
            )

        if requested_branch_id is not None:

            sections_query = sections_query.filter(
                Section.branch_id
                == requested_branch_id
            )

    if requested_class_id is not None:

        sections_query = sections_query.filter(
            Section.class_id
            == requested_class_id
        )

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECTS
    # ========================================================

    subjects_query = Subject.query

    if user_role in {
        "school_admin",
        "institution_admin",
        "branch_admin",
    }:

        subjects_query = subjects_query.filter(
            Subject.institution_id
            == user_institution_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            subjects_query = subjects_query.filter(
                Subject.institution_id
                == requested_institution_id
            )

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # TEACHERS
    # ========================================================

    teachers_query = Teacher.query

    if user_role in {
        "school_admin",
        "institution_admin",
    }:

        teachers_query = teachers_query.filter(
            Teacher.institution_id
            == user_institution_id
        )

    elif user_role == "branch_admin":

        teachers_query = teachers_query.filter(
            Teacher.institution_id
            == user_institution_id,

            Teacher.branch_id
            == user_branch_id
        )

    elif user_role == "superadmin":

        if requested_institution_id is not None:

            teachers_query = teachers_query.filter(
                Teacher.institution_id
                == requested_institution_id
            )

        if requested_branch_id is not None:

            teachers_query = teachers_query.filter(
                Teacher.branch_id
                == requested_branch_id
            )

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/attendance/all_student_attendance.html",

        # ====================================================
        # RECORDS
        # ====================================================

        attendance_records=attendance_records,

        pagination=pagination,

        page=page,

        per_page=per_page,

        # ====================================================
        # FILTER VALUES
        # ====================================================

        search=search,

        selected_institution_id=institution_id,

        selected_branch_id=branch_id,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_subject_id=subject_id,

        selected_teacher_id=teacher_id,

        selected_status=status,

        selected_session_type=session_type,

        selected_date_from=date_from,
        user=current_user,

        selected_date_to=date_to,

        # ====================================================
        # FILTER DATA
        # ====================================================

        institutions=institutions,

        branches=branches,

        classes=classes,

        sections=sections,

        subjects=subjects,

        teachers=teachers,

        # ====================================================
        # STATISTICS
        # ====================================================

        total_attendance=total_attendance,

        present_count=present_count,

        absent_count=absent_count,

        late_count=late_count,

        excused_count=excused_count,

        sick_count=sick_count,

        leave_count=leave_count,

        attendance_percentage=attendance_percentage,

        # ====================================================
        # OPTIONS
        # ====================================================

        attendance_statuses=[
            "present",
            "absent",
            "late",
            "excused",
            "sick",
            "leave",
        ],

        session_types=[
            "class",
            "subject",
            "morning",
            "afternoon",
            "exam",
            "other",
        ],
    )





@bp.route(
    "/attendance/record/<int:record_id>/status",
    methods=["POST"]
)
@login_required
def update_attendance_record_status(record_id):

    # ============================================================
    # ROLE SECURITY
    # ============================================================

    role = current_user.role

    if hasattr(role, "value"):
        role = role.value

    role = str(role or "").strip().lower()

    allowed_roles = {
        "superadmin",
        "school_admin",
        "institution_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        return jsonify({
            "success": False,
            "message": "You are not authorized to update attendance."
        }), 403


    # ============================================================
    # LOAD ATTENDANCE RECORD
    # ============================================================

    record = (
        AttendanceRecord.query
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .filter(
            AttendanceRecord.id == record_id
        )
        .first()
    )

    if not record:
        return jsonify({
            "success": False,
            "message": "Attendance record was not found."
        }), 404


    # ============================================================
    # LOAD SESSION
    # ============================================================

    session = record.session

    if not session:
        return jsonify({
            "success": False,
            "message": "Attendance session was not found."
        }), 404


    # ============================================================
    # INSTITUTION / BRANCH SECURITY
    # ============================================================

    if role != "superadmin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        # --------------------------------------------------------
        # USER MUST BELONG TO AN INSTITUTION
        # --------------------------------------------------------

        if not user_institution_id:
            return jsonify({
                "success": False,
                "message": (
                    "Your account is not linked to an institution."
                )
            }), 403


        # --------------------------------------------------------
        # INSTITUTION SCOPE
        # --------------------------------------------------------

        if session.institution_id != user_institution_id:
            return jsonify({
                "success": False,
                "message": (
                    "You cannot update attendance outside "
                    "your institution."
                )
            }), 403


        # --------------------------------------------------------
        # BRANCH ADMIN SCOPE
        # --------------------------------------------------------

        if role == "branch_admin":

            user_branch_id = getattr(
                current_user,
                "branch_id",
                None
            )

            if not user_branch_id:
                return jsonify({
                    "success": False,
                    "message": (
                        "Your account is not linked to a branch."
                    )
                }), 403


            if session.branch_id != user_branch_id:
                return jsonify({
                    "success": False,
                    "message": (
                        "You cannot update attendance outside "
                        "your branch."
                    )
                }), 403


    # ============================================================
    # SESSION STATUS SECURITY
    # ============================================================

    session_status = (
        str(session.status or "")
        .strip()
        .lower()
    )

    if session_status in {
        "locked",
        "cancelled",
    }:

        return jsonify({
            "success": False,
            "message": (
                "This attendance session is "
                "locked or cancelled and cannot be changed."
            )
        }), 409


    # ============================================================
    # REQUEST DATA
    # ============================================================

    data = request.get_json(silent=True)

    if not data:
        data = request.form


    # ============================================================
    # STATUS
    # ============================================================

    status = str(
        data.get("status", "")
    ).strip().lower()


    # ============================================================
    # NOTES
    # ============================================================

    notes = data.get("notes")

    if notes is not None:

        notes = str(notes).strip()

        if not notes:
            notes = None


    # ============================================================
    # ALLOWED ATTENDANCE STATUSES
    # ============================================================

    allowed_statuses = {
        "present",
        "absent",
        "late",
        "excused",
    }

    if status not in allowed_statuses:

        return jsonify({
            "success": False,
            "message": (
                "Invalid attendance status. "
                "Allowed statuses are Present, Absent, "
                "Late, and Excused."
            )
        }), 400


    # ============================================================
    # OLD STATUS
    # ============================================================

    old_status = (
        str(record.status).strip().lower()
        if record.status
        else None
    )


    # ============================================================
    # MINUTES LATE
    # ============================================================

    minutes_late = None


    if status == "late":

        raw_minutes_late = data.get(
            "minutes_late"
        )


        # --------------------------------------------------------
        # DEFAULT TO 1 MINUTE IF NOT PROVIDED
        # --------------------------------------------------------

        if raw_minutes_late in (
            None,
            "",
        ):

            minutes_late = 1

        else:

            try:

                # Prevent values such as 10.5
                # from silently becoming 10.

                if isinstance(
                    raw_minutes_late,
                    str
                ):

                    raw_minutes_late = (
                        raw_minutes_late.strip()
                    )


                minutes_late = int(
                    raw_minutes_late
                )

            except (
                TypeError,
                ValueError
            ):

                return jsonify({
                    "success": False,
                    "message": (
                        "Minutes late must be "
                        "a valid whole number."
                    )
                }), 400


        # --------------------------------------------------------
        # NEGATIVE VALUE
        # --------------------------------------------------------

        if minutes_late < 0:

            return jsonify({
                "success": False,
                "message": (
                    "Minutes late cannot be negative."
                )
            }), 400


        # --------------------------------------------------------
        # OPTIONAL SAFETY LIMIT
        # --------------------------------------------------------
        #
        # 24 hours = 1440 minutes.
        #
        # This prevents accidental values such as
        # 999999 from being stored.
        #

        if minutes_late > 1440:

            return jsonify({
                "success": False,
                "message": (
                    "Minutes late cannot be greater "
                    "than 1440 minutes."
                )
            }), 400


    # ============================================================
    # UPDATE STATUS
    # ============================================================

    record.status = status


    # ============================================================
    # UPDATE NOTES
    # ============================================================

    record.notes = notes


    # ============================================================
    # PRESENT
    # ============================================================

    if status == "present":

        # --------------------------------------------------------
        # Present means the student attended normally.
        #
        # We intentionally do not create a fake check-in time.
        # We also clear minutes_late because the student is no
        # longer marked as late.
        # --------------------------------------------------------

        record.minutes_late = None


    # ============================================================
    # ABSENT
    # ============================================================

    elif status == "absent":

        # --------------------------------------------------------
        # Absent student should not retain timing information.
        # --------------------------------------------------------

        record.check_in = None
        record.check_out = None
        record.minutes_late = None


    # ============================================================
    # LATE
    # ============================================================

    elif status == "late":

        # --------------------------------------------------------
        # Late student attended but arrived late.
        #
        # We store the exact number of minutes provided by the
        # administrator.
        # --------------------------------------------------------

        record.minutes_late = minutes_late


    # ============================================================
    # EXCUSED
    # ============================================================

    elif status == "excused":

        # --------------------------------------------------------
        # Excused means the student is officially excused from
        # attendance.
        #
        # No late information should remain.
        # --------------------------------------------------------

        record.check_in = None
        record.check_out = None
        record.minutes_late = None


    # ============================================================
    # UPDATED TIME
    # ============================================================

    record.updated_at = datetime.utcnow()


    # ============================================================
    # SAVE DATABASE
    # ============================================================

    try:

        db.session.commit()

    except Exception:

        db.session.rollback()

        return jsonify({
            "success": False,
            "message": (
                "Attendance could not be updated. "
                "Please try again."
            )
        }), 500


    # ============================================================
    # RESPONSE
    # ============================================================

    return jsonify({
        "success": True,
        "message": "Attendance updated successfully.",

        "record_id": record.id,

        "old_status": old_status,

        "status": record.status,

        "status_label": (
            record.status.capitalize()
        ),

        "minutes_late": (
            record.minutes_late
            if record.minutes_late is not None
            else None
        ),

        "notes": record.notes or "",

    }), 200



# ============================================================
# DELETE ATTENDANCE RECORD
# ============================================================

@bp.route(
    "/attendance-record/<int:record_id>/delete",
    methods=["POST"]
)
@login_required
def delete_attendance_record(record_id):

    # ========================================================
    # GET CURRENT USER ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    # ========================================================
    # ALLOWED ROLES
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:

        flash(
            "You are not authorized to delete attendance.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.attendance_reports")
        )

    # ========================================================
    # FIND ATTENDANCE RECORD
    # ========================================================
    #
    # The button sends record.id.
    #
    # We use the record to locate the AttendanceSession.
    #
    # ========================================================

    record = (
        AttendanceRecord.query
        .filter(
            AttendanceRecord.id == record_id
        )
        .first()
    )

    if not record:

        flash(
            "Attendance record was not found.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.attendance_reports")
        )

    # ========================================================
    # GET ATTENDANCE SESSION
    # ========================================================

    attendance_session = record.session

    if not attendance_session:

        flash(
            "The attendance session associated with this record "
            "could not be found.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.attendance_reports")
        )

    # ========================================================
    # SESSION STATUS
    # ========================================================

    session_status = (
        str(
            attendance_session.status
        ).strip().lower()
        if attendance_session.status
        else None
    )

    # ========================================================
    # LOCKED SESSION
    # ========================================================
    #
    # Locked attendance must never be deleted.
    #
    # ========================================================

    if session_status == "locked":

        flash(
            "This attendance session is locked "
            "and cannot be deleted.",
            "warning"
        )

        return redirect(
            request.referrer
            or url_for("main.attendance_reports")
        )

    # ========================================================
    # CANCELLED SESSION
    # ========================================================

    if session_status == "cancelled":

        flash(
            "This attendance session is cancelled "
            "and cannot be deleted.",
            "warning"
        )

        return redirect(
            request.referrer
            or url_for("main.attendance_reports")
        )

    # ========================================================
    # SESSION INFORMATION
    # ========================================================
    #
    # Save these before deleting the session.
    #
    # ========================================================

    session_id = attendance_session.id

    institution_id = attendance_session.institution_id

    branch_id = attendance_session.branch_id

    teacher_id = attendance_session.teacher_id

    class_id = attendance_session.class_id

    section_id = attendance_session.section_id

    subject_id = attendance_session.subject_id

    attendance_date = attendance_session.attendance_date

    # ========================================================
    # STUDENT COUNT
    # ========================================================
    #
    # Used for success message.
    #
    # ========================================================

    record_count = (
        AttendanceRecord.query
        .filter(
            AttendanceRecord.attendance_session_id
            == session_id
        )
        .count()
    )

    # ========================================================
    # ROLE: SUPERADMIN
    # ========================================================

    if role == "superadmin":

        # Global access.
        pass

    # ========================================================
    # ROLE: SCHOOL ADMIN
    # ========================================================

    elif role == "school_admin":

        current_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not current_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

        # ----------------------------------------------------
        # Institution scope
        # ----------------------------------------------------

        if institution_id != current_institution_id:

            flash(
                "You are not authorized to delete "
                "this attendance session.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

    # ========================================================
    # ROLE: BRANCH ADMIN
    # ========================================================

    elif role == "branch_admin":

        current_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not current_institution_id
            or not current_branch_id
        ):

            flash(
                "Your account is not assigned to "
                "an institution and branch.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

        # ----------------------------------------------------
        # Institution + Branch scope
        # ----------------------------------------------------

        if (
            institution_id
            != current_institution_id
            or
            branch_id
            != current_branch_id
        ):

            flash(
                "You are not authorized to delete "
                "this attendance session.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

    # ========================================================
    # ROLE: TEACHER
    # ========================================================

    elif role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:

            flash(
                "Teacher account could not be verified.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

        # ----------------------------------------------------
        # Institution protection
        # ----------------------------------------------------

        if (
            institution_id
            != teacher.institution_id
        ):

            flash(
                "You are not authorized to delete "
                "this attendance session.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

        # ----------------------------------------------------
        # Branch protection
        # ----------------------------------------------------

        if (
            branch_id
            != teacher.branch_id
        ):

            flash(
                "You are not authorized to delete "
                "this attendance session.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

        # ----------------------------------------------------
        # Teacher ownership
        # ----------------------------------------------------

        if (
            teacher_id
            != teacher.id
        ):

            flash(
                "You can only delete attendance sessions "
                "created by you.",
                "danger"
            )

            return redirect(
                request.referrer
                or url_for("main.attendance_reports")
            )

    # ========================================================
    # FINAL SESSION EXISTENCE CHECK
    # ========================================================

    session_exists = (
        AttendanceSession.query
        .filter(
            AttendanceSession.id == session_id
        )
        .first()
    )

    if not session_exists:

        flash(
            "Attendance session no longer exists.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.attendance_reports")
        )

    # ========================================================
    # DELETE
    # ========================================================
    #
    # IMPORTANT:
    #
    # We delete AttendanceSession.
    #
    # Because AttendanceRecord has:
    #
    #     ForeignKey(
    #         "attendance_sessions.id",
    #         ondelete="CASCADE"
    #     )
    #
    # all related AttendanceRecords are deleted.
    #
    # SQLAlchemy relationship also has:
    #
    #     cascade="all, delete-orphan"
    #
    # ========================================================

    try:

        db.session.delete(
            attendance_session
        )

        db.session.commit()

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "Failed to delete attendance session %s "
            "and its records: %s",
            session_id,
            exc
        )

        flash(
            "Unable to delete the attendance session "
            "and its records. Please try again.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.attendance_reports")
        )

    # ========================================================
    # SUCCESS
    # ========================================================

    flash(
        f"Attendance session deleted successfully. "
        f"{record_count} student attendance record(s) "
        f"were also deleted.",
        "success"
    )

    # ========================================================
    # RETURN
    # ========================================================

    return redirect(
        request.referrer
        or url_for("main.attendance_reports")
    )


# ============================================================
# ATTENDANCE REPORTS
# ============================================================

@bp.route(
    "/attendance/reports",
    methods=["GET"]
)
@login_required
def attendance_reports():

    # ========================================================
    # SECURITY
    # ========================================================

    user = current_user

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if not user.is_authenticated:
        abort(403)

    # --------------------------------------------------------
    # NORMALIZE ROLE
    # --------------------------------------------------------

    user_role = getattr(
        user,
        "role",
        None
    )

    user_role = getattr(
        user_role,
        "value",
        user_role
    )

    user_role = (
        str(user_role).strip().lower()
        if user_role
        else None
    )

    if user_role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    institution_id = getattr(
        user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        user,
        "branch_id",
        None
    )

    # --------------------------------------------------------
    # Non-superadmin must belong to institution
    # --------------------------------------------------------

    if (
        user_role != "superadmin"
        and not institution_id
    ):
        abort(403)

    # --------------------------------------------------------
    # Branch admin must have branch
    # --------------------------------------------------------

    if (
        user_role == "branch_admin"
        and not user_branch_id
    ):
        abort(403)

    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    subject_id = request.args.get(
        "subject_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ========================================================
    # VALID ATTENDANCE STATUSES
    # ========================================================

    valid_statuses = {
        "present",
        "absent",
        "late",
        "excused",
        "sick",
        "leave",
    }

    if status not in valid_statuses:
        status = ""

    # ========================================================
    # DATE PARSING
    # ========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = datetime.strptime(
                date_from,
                "%Y-%m-%d"
            ).date()

        except (
            TypeError,
            ValueError
        ):

            parsed_date_from = None

    if date_to:

        try:

            parsed_date_to = datetime.strptime(
                date_to,
                "%Y-%m-%d"
            ).date()

        except (
            TypeError,
            ValueError
        ):

            parsed_date_to = None

    # ========================================================
    # FIX INVALID DATE RANGE
    # ========================================================

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from > parsed_date_to
    ):

        parsed_date_from, parsed_date_to = (
            parsed_date_to,
            parsed_date_from
        )

        date_from = (
            parsed_date_from.isoformat()
        )

        date_to = (
            parsed_date_to.isoformat()
        )

    # ========================================================
    # PAGINATION
    # ========================================================

    allowed_per_page = (
        10,
        25,
        50,
        100,
    )

    try:

        per_page = int(
            request.args.get(
                "per_page",
                25
            )
        )

    except (
        TypeError,
        ValueError
    ):

        per_page = 25

    if per_page not in allowed_per_page:
        per_page = 25

    try:

        page = int(
            request.args.get(
                "page",
                1
            )
        )

    except (
        TypeError,
        ValueError
    ):

        page = 1

    if page < 1:
        page = 1

    # ========================================================
    # TEACHER LOGIN SCOPE
    # ========================================================

    current_teacher_id = None

    if user_role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:
            abort(403)

        current_teacher_id = getattr(
            teacher,
            "id",
            None
        )

        if not current_teacher_id:
            abort(403)

    # ========================================================
    # EFFECTIVE BRANCH
    # ========================================================

    effective_branch_id = branch_id

    if user_role == "branch_admin":

        # ----------------------------------------------------
        # Branch admin is permanently locked to own branch
        # ----------------------------------------------------

        if effective_branch_id is None:

            effective_branch_id = (
                user_branch_id
            )

        elif (
            effective_branch_id
            != user_branch_id
        ):

            abort(403)

    # ========================================================
    # EFFECTIVE TEACHER
    # ========================================================

    effective_teacher_id = teacher_id

    if user_role == "teacher":

        if effective_teacher_id is None:

            effective_teacher_id = (
                current_teacher_id
            )

        elif (
            effective_teacher_id
            != current_teacher_id
        ):

            abort(403)

    # ========================================================
    # STUDENT SEARCH CONDITIONS
    # ========================================================

    student_search_conditions = []

    if search:

        search_pattern = (
            f"%{search}%"
        )

        # ----------------------------------------------------
        # Student name
        # ----------------------------------------------------

        if hasattr(
            Student,
            "name"
        ):

            student_search_conditions.append(
                Student.name.ilike(
                    search_pattern
                )
            )

        # ----------------------------------------------------
        # Student full name
        # ----------------------------------------------------

        if hasattr(
            Student,
            "full_name"
        ):

            student_search_conditions.append(
                Student.full_name.ilike(
                    search_pattern
                )
            )

        # ----------------------------------------------------
        # Admission number
        # ----------------------------------------------------

        if hasattr(
            Student,
            "admission_no"
        ):

            student_search_conditions.append(
                Student.admission_no.ilike(
                    search_pattern
                )
            )

        # ----------------------------------------------------
        # Student ID
        #
        # cast is used so this also works if student_id
        # happens to be numeric.
        # ----------------------------------------------------

        if hasattr(
            Student,
            "student_id"
        ):

            student_search_conditions.append(
                cast(
                    Student.student_id,
                    db.String
                ).ilike(
                    search_pattern
                )
            )

        # ----------------------------------------------------
        # Roll number
        # ----------------------------------------------------

        if hasattr(
            Student,
            "roll_no"
        ):

            student_search_conditions.append(
                cast(
                    Student.roll_no,
                    db.String
                ).ilike(
                    search_pattern
                )
            )

    # ========================================================
    # BASE FILTERED ATTENDANCE QUERY
    #
    # IMPORTANT:
    # --------------------------------------------------------
    # This query represents ALL attendance records matching
    # the selected filters.
    #
    # It is NOT grouped yet.
    #
    # This allows us to reuse the exact same filtered dataset
    # for:
    #
    #   1. student summary
    #   2. statistics
    #   3. branch/class/section names
    # ========================================================

    filtered_query = (
        db.session.query(
            AttendanceRecord
        )
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .join(
            Student,
            AttendanceRecord.student_id
            == Student.id
        )
        .filter(
            AttendanceRecord.student_id.isnot(None)
        )
    )

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if user_role != "superadmin":

        filtered_query = filtered_query.filter(
            AttendanceSession.institution_id
            == institution_id
        )

    # ========================================================
    # BRANCH SECURITY / FILTER
    # ========================================================

    if effective_branch_id:

        filtered_query = filtered_query.filter(
            AttendanceSession.branch_id
            == effective_branch_id
        )

    # ========================================================
    # TEACHER SECURITY / FILTER
    # ========================================================

    if effective_teacher_id:

        filtered_query = filtered_query.filter(
            AttendanceSession.teacher_id
            == effective_teacher_id
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        filtered_query = filtered_query.filter(
            AttendanceSession.academic_year_id
            == academic_year_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:

        filtered_query = filtered_query.filter(
            AttendanceSession.class_id
            == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        filtered_query = filtered_query.filter(
            AttendanceSession.section_id
            == section_id
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    if subject_id:

        filtered_query = filtered_query.filter(
            AttendanceSession.subject_id
            == subject_id
        )

    # ========================================================
    # STATUS
    # ========================================================

    if status:

        filtered_query = filtered_query.filter(
            AttendanceRecord.status
            == status
        )

    # ========================================================
    # DATE FROM
    # ========================================================

    if parsed_date_from:

        filtered_query = filtered_query.filter(
            AttendanceSession.attendance_date
            >= parsed_date_from
        )

    # ========================================================
    # DATE TO
    # ========================================================

    if parsed_date_to:

        filtered_query = filtered_query.filter(
            AttendanceSession.attendance_date
            <= parsed_date_to
        )

    # ========================================================
    # STUDENT SEARCH
    # ========================================================

    if student_search_conditions:

        filtered_query = filtered_query.filter(
            or_(
                *student_search_conditions
            )
        )

    # ========================================================
    # STUDENT SUMMARY
    #
    # CRITICAL FIX
    # --------------------------------------------------------
    # GROUP ONLY BY student_id.
    #
    # DO NOT group by:
    #
    #   branch_id
    #   class_id
    #   section_id
    #   academic_year_id
    #
    # Otherwise one student can produce multiple rows.
    # ========================================================

    summary_query = (
        filtered_query
        .with_entities(

            AttendanceRecord.student_id.label(
                "student_id"
            ),

            func.count(
                AttendanceRecord.id
            ).label(
                "total_attendance"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "present",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "present_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "absent",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "absent_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "late",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "late_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "excused",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "excused_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "sick",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "sick_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "leave",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "leave_count"
            ),
        )
        .group_by(
            AttendanceRecord.student_id
        )
    )

    # ========================================================
    # COUNT UNIQUE STUDENT SUMMARY ROWS
    #
    # CRITICAL FIX
    # --------------------------------------------------------
    # Do NOT do:
    #
    #   grouped_query.scalar()
    #
    # because the grouped query returns multiple rows.
    #
    # Instead:
    #
    #   SELECT COUNT(*)
    #   FROM (
    #       grouped student summary
    #   ) AS student_summary
    # ========================================================

    summary_subquery = (
        summary_query
        .subquery()
    )

    total_students = (
        db.session.query(
            func.count()
        )
        .select_from(
            summary_subquery
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TOTAL PAGES
    # ========================================================

    if total_students > 0:

        total_pages = (
            (
                total_students
                + per_page
                - 1
            )
            // per_page
        )

    else:

        total_pages = 0

    # ========================================================
    # FIX INVALID PAGE
    # ========================================================

    if (
        total_pages > 0
        and page > total_pages
    ):

        page = total_pages

    elif (
        total_pages == 0
        and page > 1
    ):

        page = 1

    # ========================================================
    # OFFSET
    # ========================================================

    offset = (
        (
            page
            - 1
        )
        * per_page
    )

    # ========================================================
    # FETCH CURRENT PAGE STUDENT SUMMARIES
    # ========================================================

    summary_rows = (
        summary_query
        .order_by(
            AttendanceRecord.student_id.asc()
        )
        .offset(
            offset
        )
        .limit(
            per_page
        )
        .all()
    )

    # ========================================================
    # CURRENT PAGE STUDENT IDS
    # ========================================================

    student_ids = [
        row.student_id
        for row in summary_rows
        if row.student_id is not None
    ]

    # ========================================================
    # LOAD STUDENTS
    # ========================================================

    students_by_id = {}

    if student_ids:

        students = (
            Student.query
            .filter(
                Student.id.in_(
                    student_ids
                )
            )
            .all()
        )

        students_by_id = {
            student.id: student
            for student in students
        }

    # ========================================================
    # PAGE ATTENDANCE CONTEXT
    #
    # We separately collect all branch/class/section values
    # for the students on the current page.
    #
    # This does NOT affect student grouping.
    # ========================================================

    context_rows = []

    if student_ids:

        context_query = (
            db.session.query(
                AttendanceRecord.student_id.label(
                    "student_id"
                ),

                AttendanceSession.branch_id.label(
                    "branch_id"
                ),

                AttendanceSession.class_id.label(
                    "class_id"
                ),

                AttendanceSession.section_id.label(
                    "section_id"
                ),
            )
            .join(
                AttendanceSession,
                AttendanceRecord.attendance_session_id
                == AttendanceSession.id
            )
            .filter(
                AttendanceRecord.student_id.in_(
                    student_ids
                )
            )
        )

        # ----------------------------------------------------
        # Repeat EXACT security/filter scope
        # ----------------------------------------------------

        if user_role != "superadmin":

            context_query = context_query.filter(
                AttendanceSession.institution_id
                == institution_id
            )

        if effective_branch_id:

            context_query = context_query.filter(
                AttendanceSession.branch_id
                == effective_branch_id
            )

        if effective_teacher_id:

            context_query = context_query.filter(
                AttendanceSession.teacher_id
                == effective_teacher_id
            )

        if academic_year_id:

            context_query = context_query.filter(
                AttendanceSession.academic_year_id
                == academic_year_id
            )

        if class_id:

            context_query = context_query.filter(
                AttendanceSession.class_id
                == class_id
            )

        if section_id:

            context_query = context_query.filter(
                AttendanceSession.section_id
                == section_id
            )

        if subject_id:

            context_query = context_query.filter(
                AttendanceSession.subject_id
                == subject_id
            )

        if status:

            context_query = context_query.filter(
                AttendanceRecord.status
                == status
            )

        if parsed_date_from:

            context_query = context_query.filter(
                AttendanceSession.attendance_date
                >= parsed_date_from
            )

        if parsed_date_to:

            context_query = context_query.filter(
                AttendanceSession.attendance_date
                <= parsed_date_to
            )

        context_rows = (
            context_query
            .distinct()
            .all()
        )

    # ========================================================
    # COLLECT IDS PER STUDENT
    # ========================================================

    student_branch_ids = {}
    student_class_ids = {}
    student_section_ids = {}

    for row in context_rows:

        sid = row.student_id

        if not sid:
            continue

        student_branch_ids.setdefault(
            sid,
            set()
        )

        student_class_ids.setdefault(
            sid,
            set()
        )

        student_section_ids.setdefault(
            sid,
            set()
        )

        if row.branch_id:

            student_branch_ids[
                sid
            ].add(
                row.branch_id
            )

        if row.class_id:

            student_class_ids[
                sid
            ].add(
                row.class_id
            )

        if row.section_id:

            student_section_ids[
                sid
            ].add(
                row.section_id
            )

    # ========================================================
    # LOAD BRANCHES
    # ========================================================

    all_branch_ids = set()

    for ids in student_branch_ids.values():

        all_branch_ids.update(
            ids
        )

    branches_by_id = {}

    if all_branch_ids:

        branch_items = (
            Branch.query
            .filter(
                Branch.id.in_(
                    all_branch_ids
                )
            )
            .all()
        )

        branches_by_id = {
            item.id: item
            for item in branch_items
        }

    # ========================================================
    # LOAD CLASSES
    # ========================================================

    all_class_ids = set()

    for ids in student_class_ids.values():

        all_class_ids.update(
            ids
        )

    classes_by_id = {}

    if all_class_ids:

        class_items = (
            Class.query
            .filter(
                Class.id.in_(
                    all_class_ids
                )
            )
            .all()
        )

        classes_by_id = {
            item.id: item
            for item in class_items
        }

    # ========================================================
    # LOAD SECTIONS
    # ========================================================

    all_section_ids = set()

    for ids in student_section_ids.values():

        all_section_ids.update(
            ids
        )

    sections_by_id = {}

    if all_section_ids:

        section_items = (
            Section.query
            .filter(
                Section.id.in_(
                    all_section_ids
                )
            )
            .all()
        )

        sections_by_id = {
            item.id: item
            for item in section_items
        }

    # ========================================================
    # BUILD FINAL STUDENT REPORT
    # ========================================================

    attendance_reports_data = []

    for row in summary_rows:

        student = students_by_id.get(
            row.student_id
        )

        if not student:
            continue

        # ----------------------------------------------------
        # COUNTS
        # ----------------------------------------------------

        total = int(
            row.total_attendance
            or 0
        )

        present = int(
            row.present_count
            or 0
        )

        absent = int(
            row.absent_count
            or 0
        )

        late = int(
            row.late_count
            or 0
        )

        excused = int(
            row.excused_count
            or 0
        )

        sick = int(
            row.sick_count
            or 0
        )

        leave = int(
            row.leave_count
            or 0
        )

        # ----------------------------------------------------
        # ATTENDANCE RATE
        #
        # Present + Late = attended
        # ----------------------------------------------------

        attendance_rate = 0.0

        if total > 0:

            attendance_rate = round(
                (
                    present
                    + late
                )
                / total
                * 100,
                1
            )

        # ----------------------------------------------------
        # STUDENT NAME
        # ----------------------------------------------------

        student_name = (
            getattr(
                student,
                "full_name",
                None
            )
            or getattr(
                student,
                "name",
                None
            )
            or ""
        )

        # ----------------------------------------------------
        # ADMISSION NUMBER
        # ----------------------------------------------------

        admission_no = (
            getattr(
                student,
                "admission_no",
                None
            )
            or ""
        )

        # ----------------------------------------------------
        # ROLL NUMBER
        # ----------------------------------------------------

        roll_no = (
            getattr(
                student,
                "roll_no",
                None
            )
            or ""
        )

        # ----------------------------------------------------
        # PHOTO
        # ----------------------------------------------------

        student_photo = (
            getattr(
                student,
                "photo",
                None
            )
            or getattr(
                student,
                "photo_url",
                None
            )
            or getattr(
                student,
                "image",
                None
            )
            or getattr(
                student,
                "profile_photo",
                None
            )
            or ""
        )

        # ----------------------------------------------------
        # BRANCH NAMES
        # ----------------------------------------------------

        branch_names_list = []

        for branch_id_value in sorted(
            student_branch_ids.get(
                row.student_id,
                set()
            )
        ):

            branch_item = branches_by_id.get(
                branch_id_value
            )

            if branch_item:

                branch_name = getattr(
                    branch_item,
                    "name",
                    None
                )

                if branch_name:

                    branch_names_list.append(
                        str(branch_name)
                    )

        branch_names = ", ".join(
            dict.fromkeys(
                branch_names_list
            )
        )

        # ----------------------------------------------------
        # CLASS NAMES
        # ----------------------------------------------------

        class_names_list = []

        for class_id_value in sorted(
            student_class_ids.get(
                row.student_id,
                set()
            )
        ):

            class_item = classes_by_id.get(
                class_id_value
            )

            if class_item:

                class_name = getattr(
                    class_item,
                    "name",
                    None
                )

                if class_name:

                    class_names_list.append(
                        str(class_name)
                    )

        class_names = ", ".join(
            dict.fromkeys(
                class_names_list
            )
        )

        # ----------------------------------------------------
        # SECTION NAMES
        # ----------------------------------------------------

        section_names_list = []

        for section_id_value in sorted(
            student_section_ids.get(
                row.student_id,
                set()
            )
        ):

            section_item = sections_by_id.get(
                section_id_value
            )

            if section_item:

                section_name = getattr(
                    section_item,
                    "name",
                    None
                )

                if section_name:

                    section_names_list.append(
                        str(section_name)
                    )

        section_names = ", ".join(
            dict.fromkeys(
                section_names_list
            )
        )

        # ----------------------------------------------------
        # PRIMARY CLASS ID
        # ----------------------------------------------------

        primary_class_id = None

        class_id_values = list(
            student_class_ids.get(
                row.student_id,
                set()
            )
        )

        if class_id_values:

            primary_class_id = sorted(
                class_id_values
            )[0]

        # ----------------------------------------------------
        # PRIMARY SECTION ID
        # ----------------------------------------------------

        primary_section_id = None

        section_id_values = list(
            student_section_ids.get(
                row.student_id,
                set()
            )
        )

        if section_id_values:

            primary_section_id = sorted(
                section_id_values
            )[0]

        # ----------------------------------------------------
        # FINAL REPORT ROW
        # ----------------------------------------------------

        attendance_reports_data.append({

            "student": student,

            "student_id": (
                row.student_id
            ),

            "student_name": (
                student_name
            ),

            "student_photo": (
                student_photo
            ),

            "admission_no": (
                admission_no
            ),

            "roll_no": (
                roll_no
            ),

            "branch_names": (
                branch_names
            ),

            "class_names": (
                class_names
            ),

            "section_names": (
                section_names
            ),

            "class_id": (
                primary_class_id
            ),

            "section_id": (
                primary_section_id
            ),

            "total_attendance": (
                total
            ),

            "present_count": (
                present
            ),

            "absent_count": (
                absent
            ),

            "late_count": (
                late
            ),

            "excused_count": (
                excused
            ),

            "sick_count": (
                sick
            ),

            "leave_count": (
                leave
            ),

            "attendance_rate": (
                attendance_rate
            ),
        })

    # ========================================================
    # STATISTICS
    #
    # IMPORTANT
    # --------------------------------------------------------
    # Use ONE aggregate query.
    #
    # This prevents MultipleResultsFound errors.
    #
    # There is NO:
    #
    #     group_by(status).scalar()
    #
    # ========================================================

    stats_row = (
        filtered_query
        .with_entities(

            func.count(
                AttendanceRecord.id
            ).label(
                "total_attendance"
            ),

            func.count(
                func.distinct(
                    AttendanceRecord.student_id
                )
            ).label(
                "unique_students"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "present",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "present_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "absent",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "absent_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "late",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "late_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "excused",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "excused_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "sick",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "sick_count"
            ),

            func.coalesce(
                func.sum(
                    case(
                        (
                            AttendanceRecord.status
                            == "leave",
                            1
                        ),
                        else_=0
                    )
                ),
                0
            ).label(
                "leave_count"
            ),
        )
        .first()
    )

    # ========================================================
    # STATISTICS VALUES
    # ========================================================

    if stats_row:

        total_attendance = int(
            getattr(
                stats_row,
                "total_attendance",
                0
            )
            or 0
        )

        unique_student_count = int(
            getattr(
                stats_row,
                "unique_students",
                0
            )
            or 0
        )

        present_count = int(
            getattr(
                stats_row,
                "present_count",
                0
            )
            or 0
        )

        absent_count = int(
            getattr(
                stats_row,
                "absent_count",
                0
            )
            or 0
        )

        late_count = int(
            getattr(
                stats_row,
                "late_count",
                0
            )
            or 0
        )

        excused_count = int(
            getattr(
                stats_row,
                "excused_count",
                0
            )
            or 0
        )

        sick_count = int(
            getattr(
                stats_row,
                "sick_count",
                0
            )
            or 0
        )

        leave_count = int(
            getattr(
                stats_row,
                "leave_count",
                0
            )
            or 0
        )

    else:

        total_attendance = 0

        unique_student_count = 0

        present_count = 0

        absent_count = 0

        late_count = 0

        excused_count = 0

        sick_count = 0

        leave_count = 0

    # ========================================================
    # OVERALL ATTENDANCE RATE
    # ========================================================

    attendance_rate = 0.0

    if total_attendance > 0:

        attendance_rate = round(
            (
                present_count
                + late_count
            )
            / total_attendance
            * 100,
            1
        )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = (
        AcademicYear.query
    )

    if user_role != "superadmin":

        academic_year_query = (
            academic_year_query.filter(
                AcademicYear.institution_id
                == institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branch_query = Branch.query

    if user_role != "superadmin":

        branch_query = (
            branch_query.filter(
                Branch.institution_id
                == institution_id
            )
        )

    if user_role == "branch_admin":

        branch_query = (
            branch_query.filter(
                Branch.id
                == user_branch_id
            )
        )

    branches = (
        branch_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    class_query = Class.query

    if hasattr(
        Class,
        "institution_id"
    ):

        if user_role != "superadmin":

            class_query = (
                class_query.filter(
                    Class.institution_id
                    == institution_id
                )
            )

    if hasattr(
        Class,
        "branch_id"
    ):

        if effective_branch_id:

            class_query = (
                class_query.filter(
                    Class.branch_id
                    == effective_branch_id
                )
            )

    classes = (
        class_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACCESSIBLE CLASS IDS
    # ========================================================

    accessible_class_ids = {
        item.id
        for item in classes
        if getattr(
            item,
            "id",
            None
        )
    }

    # ========================================================
    # SECTIONS
    # ========================================================

    section_query = Section.query

    if class_id:

        if (
            accessible_class_ids
            and class_id
            not in accessible_class_ids
        ):

            section_query = (
                section_query.filter(
                    Section.id == -1
                )
            )

        else:

            section_query = (
                section_query.filter(
                    Section.class_id
                    == class_id
                )
            )

    else:

        if accessible_class_ids:

            section_query = (
                section_query.filter(
                    Section.class_id.in_(
                        accessible_class_ids
                    )
                )
            )

        else:

            section_query = (
                section_query.filter(
                    Section.id == -1
                )
            )

    sections = (
        section_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECTS
    # ========================================================

    subject_query = Subject.query

    if hasattr(
        Subject,
        "institution_id"
    ):

        if user_role != "superadmin":

            subject_query = (
                subject_query.filter(
                    Subject.institution_id
                    == institution_id
                )
            )

    subjects = (
        subject_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # TEACHERS
    # ========================================================

    teacher_query = Teacher.query

    if hasattr(
        Teacher,
        "institution_id"
    ):

        if user_role != "superadmin":

            teacher_query = (
                teacher_query.filter(
                    Teacher.institution_id
                    == institution_id
                )
            )

    if hasattr(
        Teacher,
        "branch_id"
    ):

        if effective_branch_id:

            teacher_query = (
                teacher_query.filter(
                    Teacher.branch_id
                    == effective_branch_id
                )
            )

    # --------------------------------------------------------
    # Teacher login only sees self
    # --------------------------------------------------------

    if user_role == "teacher":

        teacher_query = (
            teacher_query.filter(
                Teacher.id
                == current_teacher_id
            )
        )

    teachers = (
        teacher_query
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # PAGINATION CLASS
    # ========================================================

    class AttendanceStudentPagination:

        def __init__(
            self,
            items,
            page,
            per_page,
            total
        ):

            self.items = items

            self.page = page

            self.per_page = per_page

            self.total = total

            self.pages = (
                (
                    total
                    + per_page
                    - 1
                )
                // per_page
                if total
                else 0
            )

        # ----------------------------------------------------
        # HAS PREVIOUS
        # ----------------------------------------------------

        @property
        def has_prev(self):

            return self.page > 1

        # ----------------------------------------------------
        # HAS NEXT
        # ----------------------------------------------------

        @property
        def has_next(self):

            return (
                self.pages > 0
                and self.page < self.pages
            )

        # ----------------------------------------------------
        # PREVIOUS PAGE
        # ----------------------------------------------------

        @property
        def prev_num(self):

            if self.has_prev:

                return self.page - 1

            return None

        # ----------------------------------------------------
        # NEXT PAGE
        # ----------------------------------------------------

        @property
        def next_num(self):

            if self.has_next:

                return self.page + 1

            return None

        # ----------------------------------------------------
        # FIRST ITEM NUMBER
        # ----------------------------------------------------

        @property
        def first(self):

            if self.total == 0:
                return 0

            return (
                (
                    self.page
                    - 1
                )
                * self.per_page
            ) + 1

        # ----------------------------------------------------
        # LAST ITEM NUMBER
        # ----------------------------------------------------

        @property
        def last(self):

            if self.total == 0:
                return 0

            return min(
                self.page
                * self.per_page,
                self.total
            )

    # ========================================================
    # PAGINATION OBJECT
    # ========================================================

    pagination = (
        AttendanceStudentPagination(
            attendance_reports_data,
            page,
            per_page,
            total_students
        )
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/attendance/attendance_reports.html",

        # ====================================================
        # STUDENT SUMMARY
        # ====================================================

        attendance_reports=(
            attendance_reports_data
        ),

        # ====================================================
        # PAGINATION
        # ====================================================

        pagination=pagination,

        # ====================================================
        # STATISTICS
        # ====================================================

        total_students=(
            unique_student_count
        ),

        total_attendance=(
            total_attendance
        ),

        present_count=(
            present_count
        ),

        absent_count=(
            absent_count
        ),

        late_count=(
            late_count
        ),

        excused_count=(
            excused_count
        ),

        sick_count=(
            sick_count
        ),

        leave_count=(
            leave_count
        ),

        attendance_rate=(
            attendance_rate
        ),

        # ====================================================
        # FILTER VALUES
        # ====================================================

        search=search,

        academic_year_id=(
            academic_year_id
        ),

        branch_id=(
            branch_id
        ),

        class_id=(
            class_id
        ),

        section_id=(
            section_id
        ),

        subject_id=(
            subject_id
        ),

        teacher_id=(
            teacher_id
        ),

        status=status,

        date_from=date_from,

        date_to=date_to,

        per_page=per_page,

        page=page,

        # ====================================================
        # EFFECTIVE SECURITY
        # ====================================================

        effective_branch_id=(
            effective_branch_id
        ),

        effective_teacher_id=(
            effective_teacher_id
        ),

        # ====================================================
        # FILTER OPTIONS
        # ====================================================

        academic_years=(
            academic_years
        ),

        branches=(
            branches
        ),

        classes=(
            classes
        ),

        sections=(
            sections
        ),

        subjects=(
            subjects
        ),

        teachers=(
            teachers
        ),

        # ====================================================
        # CURRENT USER
        # ====================================================

        user=current_user
    )

    
# ============================================================
# ABSENT REPORTS
# ============================================================

@bp.route(
    "/attendance/absent-reports",
    methods=["GET"]
)
@login_required
def absent_reports():

    # ========================================================
    # SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT TEACHER
    # ========================================================

    teacher = None

    if role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:
            abort(403)

    # ========================================================
    # INSTITUTION SCOPE
    # ========================================================

    if role == "teacher":

        institution_id = getattr(
            teacher,
            "institution_id",
            None
        )

    else:

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

    if not institution_id:
        abort(403)

    # ========================================================
    # PRINT MODE
    # ========================================================

    print_mode = (
        request.args.get(
            "print",
            "",
            type=str
        ).lower()
        in {
            "1",
            "true",
            "yes",
        }
    )

    # ========================================================
    # FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    academic_year_id = request.args.get(
        "academic_year_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    teacher_id = request.args.get(
        "teacher_id",
        "",
        type=str
    ).strip()

    class_id = request.args.get(
        "class_id",
        "",
        type=str
    ).strip()

    section_id = request.args.get(
        "section_id",
        "",
        type=str
    ).strip()

    subject_id = request.args.get(
        "subject_id",
        "",
        type=str
    ).strip()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ========================================================
    # PER PAGE
    # ========================================================

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # PAGE
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    # ========================================================
    # DATE PARSING
    # ========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = (
                datetime.strptime(
                    date_from,
                    "%Y-%m-%d"
                ).date()
            )

        except (
            ValueError,
            TypeError
        ):

            date_from = ""
            parsed_date_from = None

    if date_to:

        try:

            parsed_date_to = (
                datetime.strptime(
                    date_to,
                    "%Y-%m-%d"
                ).date()
            )

        except (
            ValueError,
            TypeError
        ):

            date_to = ""
            parsed_date_to = None

    # ========================================================
    # FIX REVERSED DATES
    # ========================================================

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from
        > parsed_date_to
    ):

        parsed_date_from, parsed_date_to = (
            parsed_date_to,
            parsed_date_from
        )

        date_from = (
            parsed_date_from.strftime(
                "%Y-%m-%d"
            )
        )

        date_to = (
            parsed_date_to.strftime(
                "%Y-%m-%d"
            )
        )

    # ========================================================
    # BASE ATTENDANCE QUERY
    # ========================================================
    #
    # IMPORTANT:
    #
    # This query contains ALL matching attendance records.
    #
    # It is NOT absent-only.
    #
    # This is required to calculate the student's
    # real absence rate.
    #
    # ========================================================

    attendance_query = (
        db.session.query(
            AttendanceRecord
        )
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .filter(
            AttendanceSession.institution_id
            == institution_id
        )
    )

    # ========================================================
    # TEACHER SECURITY
    # ========================================================

    if role == "teacher":

        attendance_query = (
            attendance_query
            .filter(
                AttendanceSession.teacher_id
                == teacher.id
            )
        )

        if teacher.branch_id:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.branch_id
                    == teacher.branch_id
                )
            )

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.branch_id
                    == current_branch_id
                )
            )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        try:

            academic_year_value = int(
                academic_year_id
            )

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.academic_year_id
                    == academic_year_value
                )
            )

        except (
            ValueError,
            TypeError
        ):

            academic_year_id = ""

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if branch_id:

        try:

            requested_branch_id = int(
                branch_id
            )

            # ------------------------------------------------
            # TEACHER CANNOT ESCAPE OWN BRANCH
            # ------------------------------------------------

            if role == "teacher":

                if (
                    teacher.branch_id
                    and requested_branch_id
                    != teacher.branch_id
                ):
                    abort(403)

            # ------------------------------------------------
            # BRANCH ADMIN CANNOT ESCAPE OWN BRANCH
            # ------------------------------------------------

            if role == "branch_admin":

                current_branch_id = getattr(
                    current_user,
                    "branch_id",
                    None
                )

                if (
                    current_branch_id
                    and requested_branch_id
                    != current_branch_id
                ):
                    abort(403)

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.branch_id
                    == requested_branch_id
                )
            )

        except (
            ValueError,
            TypeError
        ):

            branch_id = ""

    # ========================================================
    # TEACHER FILTER
    # ========================================================

    if teacher_id:

        try:

            requested_teacher_id = int(
                teacher_id
            )

            # ------------------------------------------------
            # TEACHER CAN ONLY SELECT HIMSELF
            # ------------------------------------------------

            if role == "teacher":

                if (
                    requested_teacher_id
                    != teacher.id
                ):
                    abort(403)

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.teacher_id
                    == requested_teacher_id
                )
            )

        except (
            ValueError,
            TypeError
        ):

            teacher_id = ""

    # ========================================================
    # CLASS FILTER
    # ========================================================

    if class_id:

        try:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.class_id
                    == int(class_id)
                )
            )

        except (
            ValueError,
            TypeError
        ):

            class_id = ""

    # ========================================================
    # SECTION FILTER
    # ========================================================

    if section_id:

        try:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.section_id
                    == int(section_id)
                )
            )

        except (
            ValueError,
            TypeError
        ):

            section_id = ""

    # ========================================================
    # SUBJECT FILTER
    # ========================================================

    if subject_id:

        try:

            attendance_query = (
                attendance_query
                .filter(
                    AttendanceSession.subject_id
                    == int(subject_id)
                )
            )

        except (
            ValueError,
            TypeError
        ):

            subject_id = ""

    # ========================================================
    # DATE FROM
    # ========================================================

    if parsed_date_from:

        attendance_query = (
            attendance_query
            .filter(
                AttendanceSession.attendance_date
                >= parsed_date_from
            )
        )

    # ========================================================
    # DATE TO
    # ========================================================

    if parsed_date_to:

        attendance_query = (
            attendance_query
            .filter(
                AttendanceSession.attendance_date
                <= parsed_date_to
            )
        )

    # ========================================================
    # SEARCH
    # ========================================================
    #
    # Student:
    #   admission_no
    #   roll_no
    #   name
    #
    # ========================================================

    if search:

        search_pattern = (
            f"%{search}%"
        )

        attendance_query = (
            attendance_query
            .join(
                Student,
                AttendanceRecord.student_id
                == Student.id
            )
            .filter(
                or_(
                    Student.admission_no.ilike(
                        search_pattern
                    ),

                    Student.roll_no.ilike(
                        search_pattern
                    ),

                    Student.name.ilike(
                        search_pattern
                    )
                )
            )
        )

    # ========================================================
    # ABSENT CONDITION
    # ========================================================

    absent_condition = (
        func.lower(
            func.trim(
                AttendanceRecord.status
            )
        ) == "absent"
    )

    # ========================================================
    # TOTAL ATTENDANCE
    # ========================================================

    total_attendance = (
        attendance_query
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TOTAL ABSENT
    # ========================================================

    total_absent = (
        attendance_query
        .filter(
            absent_condition
        )
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TOTAL ABSENT STUDENTS
    # ========================================================

    total_absent_students = (
        attendance_query
        .filter(
            absent_condition
        )
        .with_entities(
            func.count(
                func.distinct(
                    AttendanceRecord.student_id
                )
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TOTAL ABSENT DAYS
    # ========================================================
    #
    # Same student absent in multiple subjects
    # on same date = ONE absent day.
    #
    # ========================================================

    absent_day_rows = (
        attendance_query
        .filter(
            absent_condition
        )
        .with_entities(
            AttendanceRecord.student_id,
            AttendanceSession.attendance_date
        )
        .distinct()
        .all()
    )

    total_absent_days = len(
        absent_day_rows
    )

    # ========================================================
    # OVERALL ABSENCE RATE
    # ========================================================

    if total_attendance > 0:

        overall_absence_rate = (
            total_absent
            / total_attendance
        ) * 100

    else:

        overall_absence_rate = 0.0

    # ========================================================
    # STUDENT STATISTICS
    # ========================================================
    #
    # Each student:
    #
    # total_attendance
    # absent_count
    # absence_rate
    #
    # ========================================================

    student_stats_query = (
        attendance_query
        .with_entities(

            AttendanceRecord.student_id.label(
                "student_id"
            ),

            func.count(
                AttendanceRecord.id
            ).label(
                "student_total_attendance"
            ),

            func.sum(
                case(
                    (
                        absent_condition,
                        1
                    ),
                    else_=0
                )
            ).label(
                "student_absent_count"
            )
        )
        .group_by(
            AttendanceRecord.student_id
        )
    )

    student_stats = {}

    for row in student_stats_query.all():

        student_total = int(
            row.student_total_attendance
            or 0
        )

        student_absent = int(
            row.student_absent_count
            or 0
        )

        if student_total > 0:

            student_rate = (
                student_absent
                / student_total
            ) * 100

        else:

            student_rate = 0.0

        student_stats[
            row.student_id
        ] = {
            "total_attendance":
                student_total,

            "absent_count":
                student_absent,

            "absence_rate":
                student_rate,
        }

    # ========================================================
    # ABSENT ONLY QUERY
    # ========================================================

    absent_query = (
        attendance_query
        .filter(
            absent_condition
        )
    )

    # ========================================================
    # LOAD ABSENT RECORDS
    # ========================================================

    absent_records = (
        absent_query
        .options(

            # ------------------------------------------------
            # STUDENT
            # ------------------------------------------------

            joinedload(
                AttendanceRecord.student
            ),

            # ------------------------------------------------
            # SESSION
            # ------------------------------------------------

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.class_
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.section
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.subject
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.teacher
            ),

            # ------------------------------------------------
            # MARKED BY TEACHER
            # ------------------------------------------------

            joinedload(
                AttendanceRecord.marked_by_teacher
            )
        )
        .all()
    )

    # ========================================================
    # ATTACH STATISTICS
    # ========================================================

    for record in absent_records:

        stats = student_stats.get(
            record.student_id,
            {
                "total_attendance": 0,
                "absent_count": 0,
                "absence_rate": 0.0,
            }
        )

        record.total_attendance = int(
            stats[
                "total_attendance"
            ]
        )

        record.absent_count = int(
            stats[
                "absent_count"
            ]
        )

        record.absence_rate = float(
            stats[
                "absence_rate"
            ]
        )

    # ========================================================
    # SORT
    # ========================================================
    #
    # HIGHEST ABSENCE RATE
    #          ↓
    # LOWEST ABSENCE RATE
    #
    # 1. Rate DESC
    # 2. Absent count DESC
    # 3. Date DESC
    # 4. Record ID DESC
    #
    # ========================================================

    def absent_sort_key(
        record
    ):

        rate = float(
            getattr(
                record,
                "absence_rate",
                0
            )
            or 0
        )

        absent_count = int(
            getattr(
                record,
                "absent_count",
                0
            )
            or 0
        )

        session = getattr(
            record,
            "session",
            None
        )

        attendance_date = getattr(
            session,
            "attendance_date",
            None
        )

        if not attendance_date:

            attendance_date = date.min

        record_id = int(
            getattr(
                record,
                "id",
                0
            )
            or 0
        )

        return (
            rate,
            absent_count,
            attendance_date,
            record_id,
        )

    absent_records.sort(
        key=absent_sort_key,
        reverse=True
    )

    # ========================================================
    # TOTAL REPORT RECORDS
    # ========================================================

    total_records = len(
        absent_records
    )

    # ========================================================
    # PRINT MODE
    # ========================================================
    #
    # Print page shows ALL filtered records.
    #
    # It does NOT paginate.
    #
    # ========================================================

    if print_mode:

        print_records = (
            absent_records
        )

    else:

        print_records = (
            absent_records
        )

    # ========================================================
    # PAGINATION
    # ========================================================

    total_pages = (
        math.ceil(
            total_records
            / per_page
        )
        if total_records
        else 1
    )

    if page > total_pages:

        page = total_pages

    # ========================================================
    # CURRENT PAGE
    # ========================================================

    if print_mode:

        paginated_records = (
            print_records
        )

    else:

        start_index = (
            (page - 1)
            * per_page
        )

        end_index = (
            start_index
            + per_page
        )

        paginated_records = (
            absent_records[
                start_index:end_index
            ]
        )

    # ========================================================
    # PAGINATION CLASS
    # ========================================================

    class ManualPagination:

        def __init__(
            self,
            items,
            page,
            per_page,
            total
        ):

            self.items = items

            self.page = page

            self.per_page = per_page

            self.total = total

            self.pages = (
                math.ceil(
                    total
                    / per_page
                )
                if total
                else 1
            )

        @property
        def has_prev(self):

            return (
                self.page > 1
            )

        @property
        def has_next(self):

            return (
                self.page
                < self.pages
            )

        @property
        def prev_num(self):

            if self.has_prev:

                return (
                    self.page - 1
                )

            return None

        @property
        def next_num(self):

            if self.has_next:

                return (
                    self.page + 1
                )

            return None

        def iter_pages(
            self,
            left_edge=2,
            left_current=2,
            right_current=3,
            right_edge=2
        ):

            last = 0

            for number in range(
                1,
                self.pages + 1
            ):

                if (
                    number
                    <= left_edge

                    or

                    (
                        number
                        >=
                        self.page
                        - left_current

                        and

                        number
                        <=
                        self.page
                        + right_current
                    )

                    or

                    number
                    >
                    self.pages
                    - right_edge
                ):

                    if (
                        last + 1
                        != number
                    ):

                        yield None

                    yield number

                    last = number

    # ========================================================
    # PAGINATION INSTANCE
    # ========================================================

    pagination = ManualPagination(
        paginated_records,
        page,
        per_page,
        total_records
    )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.institution_id
            == institution_id
        )
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = (
        Branch.query
        .filter(
            Branch.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        if teacher.branch_id:

            branches_query = (
                branches_query
                .filter(
                    Branch.id
                    == teacher.branch_id
                )
            )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            branches_query = (
                branches_query
                .filter(
                    Branch.id
                    == current_branch_id
                )
            )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # TEACHERS
    # ========================================================
    #
    # IMPORTANT:
    #
    # Teacher model has:
    #   full_name
    #
    # NOT:
    #   name
    #
    # ========================================================

    teachers_query = (
        Teacher.query
        .filter(
            Teacher.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        teachers_query = (
            teachers_query
            .filter(
                Teacher.id
                == teacher.id
            )
        )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.branch_id
                    == current_branch_id
                )
            )

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    classes_query = (
        Class.query
        .filter(
            Class.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        if teacher.branch_id:

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id
                    == teacher.branch_id
                )
            )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id
                    == current_branch_id
                )
            )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections_query = (
        Section.query
        .filter(
            Section.institution_id
            == institution_id
        )
    )

    if role == "teacher":

        if teacher.branch_id:

            sections_query = (
                sections_query
                .filter(
                    Section.branch_id
                    == teacher.branch_id
                )
            )

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            sections_query = (
                sections_query
                .filter(
                    Section.branch_id
                    == current_branch_id
                )
            )

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECTS
    # ========================================================

    subjects_query = (
        Subject.query
        .filter(
            Subject.institution_id
            == institution_id
        )
    )

    # --------------------------------------------------------
    # TEACHER SUBJECT SECURITY
    # --------------------------------------------------------

    if role == "teacher":

        subjects_query = (
            subjects_query
            .join(
                TeacherSubject,
                TeacherSubject.subject_id
                == Subject.id
            )
            .filter(
                TeacherSubject.teacher_id
                == teacher.id
            )
        )

    # --------------------------------------------------------
    # BRANCH ADMIN SUBJECT SECURITY
    # --------------------------------------------------------

    elif role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            subjects_query = (
                subjects_query
                .filter(
                    or_(
                        Subject.branch_id
                        == current_branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
            )

    subjects = (
        subjects_query
        .distinct()
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACTIVE FILTER COUNT
    # ========================================================

    active_filters = sum(
        1
        for value in (
            search,
            academic_year_id,
            branch_id,
            teacher_id,
            class_id,
            section_id,
            subject_id,
            date_from,
            date_to,
        )
        if value
    )

    # ========================================================
    # FILTER SUMMARY
    # ========================================================

    filter_summary = {
        "search": search,
        "academic_year_id": academic_year_id,
        "branch_id": branch_id,
        "teacher_id": teacher_id,
        "class_id": class_id,
        "section_id": section_id,
        "subject_id": subject_id,
        "date_from": date_from,
        "date_to": date_to,
    }

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/attendance/absent_reports.html",

        # ====================================================
        # REPORT
        # ====================================================

        absent_reports=paginated_records,

        pagination=pagination,

        # ====================================================
        # FILTERS
        # ====================================================

        search=search,

        academic_year_id=academic_year_id,

        branch_id=branch_id,

        teacher_id=teacher_id,

        class_id=class_id,

        section_id=section_id,

        subject_id=subject_id,

        date_from=date_from,

        date_to=date_to,

        per_page=per_page,

        page=page,

        # ====================================================
        # DROPDOWNS
        # ====================================================

        academic_years=academic_years,

        branches=branches,

        teachers=teachers,

        classes=classes,

        sections=sections,

        subjects=subjects,

        # ====================================================
        # STATISTICS
        # ====================================================

        total_absent=total_absent,

        total_absent_students=(
            total_absent_students
        ),

        total_absent_days=(
            total_absent_days
        ),

        total_attendance=(
            total_attendance
        ),

        overall_absence_rate=(
            overall_absence_rate
        ),

        total_records=total_records,

        # ====================================================
        # FILTER INFORMATION
        # ====================================================

        active_filters=active_filters,

        filter_summary=filter_summary,

        # ====================================================
        # SORT
        # ====================================================

        sort_by="absence_rate",

        sort_direction="desc",

        sort_label=(
            "Highest Absence Rate"
        ),

        # ====================================================
        # PRINT
        # ====================================================

        print_mode=print_mode,
        user=current_user

    )


@bp.route(
    "/attendance/absent-reports/print",
    methods=["GET"]
)
@login_required
def print_absent_reports():

    # ==========================================================
    # SECURITY / ROLE
    # ==========================================================

    role = getattr(current_user, "role", None)

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ==========================================================
    # CURRENT TEACHER
    # ==========================================================

    teacher = None

    if role == "teacher":

        teacher = getattr(g, "teacher", None)

        if not teacher:
            abort(403)

    # ==========================================================
    # INSTITUTION
    # ==========================================================

    if role == "teacher":

        institution_id = getattr(
            teacher,
            "institution_id",
            None
        )

    else:

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

    if not institution_id:
        abort(403)

    # ==========================================================
    # FILTERS
    # ==========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    academic_year_id = request.args.get(
        "academic_year_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    teacher_id = request.args.get(
        "teacher_id",
        "",
        type=str
    ).strip()

    class_id = request.args.get(
        "class_id",
        "",
        type=str
    ).strip()

    section_id = request.args.get(
        "section_id",
        "",
        type=str
    ).strip()

    subject_id = request.args.get(
        "subject_id",
        "",
        type=str
    ).strip()

    date_from = request.args.get(
        "date_from",
        "",
        type=str
    ).strip()

    date_to = request.args.get(
        "date_to",
        "",
        type=str
    ).strip()

    # ==========================================================
    # DATE PARSING
    # ==========================================================

    parsed_date_from = None
    parsed_date_to = None

    if date_from:

        try:

            parsed_date_from = datetime.strptime(
                date_from,
                "%Y-%m-%d"
            ).date()

        except (ValueError, TypeError):

            date_from = ""
            parsed_date_from = None

    if date_to:

        try:

            parsed_date_to = datetime.strptime(
                date_to,
                "%Y-%m-%d"
            ).date()

        except (ValueError, TypeError):

            date_to = ""
            parsed_date_to = None

    # ==========================================================
    # SWAP INVALID DATE RANGE
    # ==========================================================

    if (
        parsed_date_from
        and parsed_date_to
        and parsed_date_from > parsed_date_to
    ):

        parsed_date_from, parsed_date_to = (
            parsed_date_to,
            parsed_date_from
        )

        date_from = parsed_date_from.strftime(
            "%Y-%m-%d"
        )

        date_to = parsed_date_to.strftime(
            "%Y-%m-%d"
        )

    # ==========================================================
    # BASE ATTENDANCE QUERY
    # ==========================================================

    attendance_query = (
        db.session.query(AttendanceRecord)
        .join(
            AttendanceSession,
            AttendanceRecord.attendance_session_id
            == AttendanceSession.id
        )
        .filter(
            AttendanceSession.institution_id
            == institution_id
        )
    )

    # ==========================================================
    # TEACHER SCOPE
    # ==========================================================

    teacher_branch_id = None
    current_teacher_id = None

    if role == "teacher":

        current_teacher_id = getattr(
            teacher,
            "id",
            None
        )

        teacher_branch_id = getattr(
            teacher,
            "branch_id",
            None
        )

        if current_teacher_id:

            attendance_query = attendance_query.filter(
                AttendanceSession.teacher_id
                == current_teacher_id
            )

        if teacher_branch_id:

            attendance_query = attendance_query.filter(
                AttendanceSession.branch_id
                == teacher_branch_id
            )

    # ==========================================================
    # BRANCH ADMIN SCOPE
    # ==========================================================

    current_branch_id = None

    if role == "branch_admin":

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if current_branch_id:

            attendance_query = attendance_query.filter(
                AttendanceSession.branch_id
                == current_branch_id
            )

    # ==========================================================
    # ACADEMIC YEAR FILTER
    # ==========================================================

    academic_year_value = None

    if academic_year_id:

        try:

            academic_year_value = int(
                academic_year_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.academic_year_id
                == academic_year_value
            )

        except (ValueError, TypeError):

            academic_year_id = ""
            academic_year_value = None

    # ==========================================================
    # BRANCH FILTER
    # ==========================================================

    branch_value = None

    if branch_id:

        try:

            branch_value = int(
                branch_id
            )

            # ----------------------------------------------
            # TEACHER SECURITY
            # ----------------------------------------------

            if role == "teacher":

                if (
                    teacher_branch_id
                    and branch_value
                    != teacher_branch_id
                ):

                    abort(403)

            # ----------------------------------------------
            # BRANCH ADMIN SECURITY
            # ----------------------------------------------

            if role == "branch_admin":

                if (
                    current_branch_id
                    and branch_value
                    != current_branch_id
                ):

                    abort(403)

            attendance_query = attendance_query.filter(
                AttendanceSession.branch_id
                == branch_value
            )

        except (ValueError, TypeError):

            branch_id = ""
            branch_value = None

    # ==========================================================
    # TEACHER FILTER
    # ==========================================================

    teacher_value = None

    if teacher_id:

        try:

            teacher_value = int(
                teacher_id
            )

            # ----------------------------------------------
            # TEACHER CAN ONLY PRINT OWN RECORDS
            # ----------------------------------------------

            if role == "teacher":

                if (
                    current_teacher_id
                    and teacher_value
                    != current_teacher_id
                ):

                    abort(403)

            attendance_query = attendance_query.filter(
                AttendanceSession.teacher_id
                == teacher_value
            )

        except (ValueError, TypeError):

            teacher_id = ""
            teacher_value = None

    # ==========================================================
    # CLASS FILTER
    # ==========================================================

    class_value = None

    if class_id:

        try:

            class_value = int(
                class_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.class_id
                == class_value
            )

        except (ValueError, TypeError):

            class_id = ""
            class_value = None

    # ==========================================================
    # SECTION FILTER
    # ==========================================================

    section_value = None

    if section_id:

        try:

            section_value = int(
                section_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.section_id
                == section_value
            )

        except (ValueError, TypeError):

            section_id = ""
            section_value = None

    # ==========================================================
    # SUBJECT FILTER
    # ==========================================================

    subject_value = None

    if subject_id:

        try:

            subject_value = int(
                subject_id
            )

            attendance_query = attendance_query.filter(
                AttendanceSession.subject_id
                == subject_value
            )

        except (ValueError, TypeError):

            subject_id = ""
            subject_value = None

    # ==========================================================
    # DATE FILTER
    # ==========================================================

    if parsed_date_from:

        attendance_query = attendance_query.filter(
            AttendanceSession.attendance_date
            >= parsed_date_from
        )

    if parsed_date_to:

        attendance_query = attendance_query.filter(
            AttendanceSession.attendance_date
            <= parsed_date_to
        )

    # ==========================================================
    # STUDENT SEARCH
    # ==========================================================

    if search:

        search_pattern = f"%{search}%"

        attendance_query = (
            attendance_query
            .join(
                Student,
                AttendanceRecord.student_id
                == Student.id
            )
            .filter(
                or_(
                    Student.admission_no.ilike(
                        search_pattern
                    ),
                    Student.roll_no.ilike(
                        search_pattern
                    ),
                    Student.name.ilike(
                        search_pattern
                    )
                )
            )
        )

    # ==========================================================
    # ABSENT CONDITION
    # ==========================================================

    absent_condition = (
        func.lower(
            func.trim(
                AttendanceRecord.status
            )
        ) == "absent"
    )

    # ==========================================================
    # TOTAL ATTENDANCE
    # ==========================================================

    total_attendance = (
        attendance_query
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ==========================================================
    # TOTAL ABSENT
    # ==========================================================

    total_absent = (
        attendance_query
        .filter(absent_condition)
        .with_entities(
            func.count(
                AttendanceRecord.id
            )
        )
        .scalar()
        or 0
    )

    # ==========================================================
    # UNIQUE ABSENT STUDENTS
    # ==========================================================

    total_absent_students = (
        attendance_query
        .filter(absent_condition)
        .with_entities(
            func.count(
                func.distinct(
                    AttendanceRecord.student_id
                )
            )
        )
        .scalar()
        or 0
    )

    # ==========================================================
    # ABSENT DAYS
    # ==========================================================

    absent_day_rows = (
        attendance_query
        .filter(absent_condition)
        .with_entities(
            AttendanceRecord.student_id,
            AttendanceSession.attendance_date
        )
        .distinct()
        .all()
    )

    total_absent_days = len(
        absent_day_rows
    )

    # ==========================================================
    # OVERALL ABSENCE RATE
    # ==========================================================

    overall_absence_rate = (
        (
            total_absent
            / total_attendance
        ) * 100
        if total_attendance
        else 0.0
    )

    # ==========================================================
    # STUDENT STATISTICS
    # ==========================================================

    student_stats_query = (
        attendance_query
        .with_entities(
            AttendanceRecord.student_id.label(
                "student_id"
            ),

            func.count(
                AttendanceRecord.id
            ).label(
                "student_total_attendance"
            ),

            func.sum(
                case(
                    (
                        absent_condition,
                        1
                    ),
                    else_=0
                )
            ).label(
                "student_absent_count"
            )
        )
        .group_by(
            AttendanceRecord.student_id
        )
    )

    student_stats = {}

    for row in student_stats_query.all():

        student_total = int(
            row.student_total_attendance
            or 0
        )

        student_absent = int(
            row.student_absent_count
            or 0
        )

        absence_rate = (
            (
                student_absent
                / student_total
            ) * 100
            if student_total
            else 0.0
        )

        student_stats[
            row.student_id
        ] = {

            "total_attendance":
                student_total,

            "absent_count":
                student_absent,

            "absence_rate":
                absence_rate,
        }

    # ==========================================================
    # ABSENT RECORDS
    # ==========================================================

    absent_records = (
        attendance_query
        .filter(absent_condition)
        .options(

            joinedload(
                AttendanceRecord.student
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.class_
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.section
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.subject
            ),

            joinedload(
                AttendanceRecord.session
            ).joinedload(
                AttendanceSession.teacher
            ),

            joinedload(
                AttendanceRecord.marked_by_teacher
            )
        )
        .all()
    )

    # ==========================================================
    # ATTACH STUDENT STATISTICS
    # ==========================================================

    for record in absent_records:

        stats = student_stats.get(
            record.student_id,
            {
                "total_attendance": 0,
                "absent_count": 0,
                "absence_rate": 0.0,
            }
        )

        record.total_attendance = int(
            stats["total_attendance"]
        )

        record.absent_count = int(
            stats["absent_count"]
        )

        record.absence_rate = float(
            stats["absence_rate"]
        )

    # ==========================================================
    # SORT
    # ==========================================================

    def absent_sort_key(record):

        record_rate = float(
            getattr(
                record,
                "absence_rate",
                0
            )
            or 0
        )

        record_absent_count = int(
            getattr(
                record,
                "absent_count",
                0
            )
            or 0
        )

        session = getattr(
            record,
            "session",
            None
        )

        attendance_date = getattr(
            session,
            "attendance_date",
            None
        )

        if not attendance_date:

            attendance_date = date.min

        record_id = int(
            getattr(
                record,
                "id",
                0
            )
            or 0
        )

        return (
            record_rate,
            record_absent_count,
            attendance_date,
            record_id,
        )

    absent_records.sort(
        key=absent_sort_key,
        reverse=True
    )

    # ==========================================================
    # SELECTED BRANCH
    # ==========================================================

    selected_branch = None

    effective_branch_id = None

    if branch_value:

        effective_branch_id = branch_value

    elif role == "teacher":

        effective_branch_id = teacher_branch_id

    elif role == "branch_admin":

        effective_branch_id = current_branch_id

    if effective_branch_id:

        selected_branch = (
            Branch.query
            .filter(
                Branch.id
                == effective_branch_id,

                Branch.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED ACADEMIC YEAR
    # ==========================================================

    selected_academic_year = None

    if academic_year_value:

        selected_academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_value,

                AcademicYear.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED TEACHER
    # ==========================================================

    selected_teacher = None

    if teacher_value:

        selected_teacher = (
            Teacher.query
            .filter(
                Teacher.id
                == teacher_value,

                Teacher.institution_id
                == institution_id
            )
            .first()
        )

    elif role == "teacher":

        selected_teacher = teacher

    # ==========================================================
    # SELECTED CLASS
    # ==========================================================

    selected_class = None

    if class_value:

        selected_class = (
            Class.query
            .filter(
                Class.id
                == class_value,

                Class.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED SECTION
    # ==========================================================

    selected_section = None

    if section_value:

        selected_section = (
            Section.query
            .filter(
                Section.id
                == section_value,

                Section.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SELECTED SUBJECT
    # ==========================================================

    selected_subject = None

    if subject_value:

        selected_subject = (
            Subject.query
            .filter(
                Subject.id
                == subject_value,

                Subject.institution_id
                == institution_id
            )
            .first()
        )

    # ==========================================================
    # SITE SETTINGS
    # ==========================================================
    #
    # Haddii SiteSettings uu yahay model-kaaga branding-ka.
    # Haddii aad site_settings global context hore u isticmaasho,
    # waxaad ka saari kartaa query-kan.
    #
    # ==========================================================

    site_settings = None

    try:

        site_settings = (
            SiteSettings.query
            .filter(
                SiteSettings.institution_id
                == institution_id
            )
            .first()
        )

    except NameError:

        # Haddii SiteSettings model uusan route-kan
        # scope-giisa ku jirin, template-ku fallback
        # ayuu isticmaali karaa.

        site_settings = None

    # ==========================================================
    # ACADEMIC YEAR DISPLAY NAME
    # ==========================================================

    academic_year_name = None

    if selected_academic_year:

        academic_year_name = (
            getattr(
                selected_academic_year,
                "name",
                None
            )
            or
            getattr(
                selected_academic_year,
                "year",
                None
            )
            or
            getattr(
                selected_academic_year,
                "title",
                None
            )
        )

    # ==========================================================
    # DISPLAY NAMES
    # ==========================================================

    teacher_name = None

    if selected_teacher:

        teacher_name = (
            getattr(
                selected_teacher,
                "full_name",
                None
            )
            or
            getattr(
                selected_teacher,
                "username",
                None
            )
        )

    class_name = None

    if selected_class:

        class_name = getattr(
            selected_class,
            "name",
            None
        )

    section_name = None

    if selected_section:

        section_name = getattr(
            selected_section,
            "name",
            None
        )

    subject_name = None

    if selected_subject:

        subject_name = getattr(
            selected_subject,
            "name",
            None
        )

    # ==========================================================
    # BRANCH DISPLAY
    # ==========================================================

    branch_name = None
    branch_code = None

    if selected_branch:

        branch_name = getattr(
            selected_branch,
            "name",
            None
        )

        branch_code = getattr(
            selected_branch,
            "code",
            None
        )

    # ==========================================================
    # REPORT FILTER COUNT
    # ==========================================================

    active_filters = 0

    for value in (
        search,
        academic_year_id,
        branch_id,
        teacher_id,
        class_id,
        section_id,
        subject_id,
        date_from,
        date_to,
    ):

        if value:

            active_filters += 1

    # ==========================================================
    # RENDER PRINT PAGE
    # ==========================================================

    return render_template(
        "backend/pages/attendance/print_absent_reports.html",

        # ------------------------------------------------------
        # RECORDS
        # ------------------------------------------------------

        absent_reports=absent_records,

        # ------------------------------------------------------
        # RAW FILTER VALUES
        # ------------------------------------------------------

        search=search,
        user=current_user,
        academic_year_id=academic_year_id,

        branch_id=branch_id,

        teacher_id=teacher_id,

        class_id=class_id,

        section_id=section_id,

        subject_id=subject_id,

        date_from=date_from,

        date_to=date_to,

        # ------------------------------------------------------
        # SELECTED OBJECTS
        # ------------------------------------------------------

        selected_academic_year=
            selected_academic_year,

        selected_branch=
            selected_branch,

        selected_teacher=
            selected_teacher,

        selected_class=
            selected_class,

        selected_section=
            selected_section,

        selected_subject=
            selected_subject,

        # ------------------------------------------------------
        # DISPLAY NAMES
        # ------------------------------------------------------

        academic_year_name=
            academic_year_name,

        branch_name=
            branch_name,

        branch_code=
            branch_code,

        teacher_name=
            teacher_name,

        class_name=
            class_name,

        section_name=
            section_name,

        subject_name=
            subject_name,

        # ------------------------------------------------------
        # SITE SETTINGS / BRANDING
        # ------------------------------------------------------

        site_settings=
            site_settings,

        # ------------------------------------------------------
        # STATISTICS
        # ------------------------------------------------------

        total_absent=
            total_absent,

        total_absent_students=
            total_absent_students,

        total_absent_days=
            total_absent_days,

        total_attendance=
            total_attendance,

        overall_absence_rate=
            overall_absence_rate,

        # ------------------------------------------------------
        # REPORT INFORMATION
        # ------------------------------------------------------

        active_filters=
            active_filters,

        generated_at=
            datetime.utcnow(),
    )

    


# ============================================================
# STUDENT FULL REPORT
# PostgreSQL / Neon
# ============================================================

@bp.route(
    "/student-report",
    methods=["GET"]
)
@login_required
def student_report():

    # ========================================================
    # HELPERS
    # ========================================================

    def first_value(obj, *names, default=None):
        """
        Safely return the first existing/non-empty attribute.
        """
        if obj is None:
            return default

        for name in names:
            try:
                value = getattr(obj, name, None)
            except Exception:
                value = None

            if value is not None and value != "":
                return value

        return default


    def object_name(obj, default="—"):
        """
        Safely get display name from any related object.
        """

        if obj is None:
            return default

        value = first_value(
            obj,
            "name",
            "full_name",
            "student_name",
            "title",
            "class_name",
            "section_name",
            "subject_name",
            "program_name",
            "academic_year_name",
            "term_name",
            "short_name",
            "code",
            default=None
        )

        if value is not None:
            return str(value)

        first_name = first_value(
            obj,
            "first_name",
            default=""
        )

        last_name = first_value(
            obj,
            "last_name",
            default=""
        )

        full = f"{first_name or ''} {last_name or ''}".strip()

        return full or default


    def normalize_id(value):
        """
        Convert query-string IDs safely.
        """
        if value in (None, "", "null", "None"):
            return None

        try:
            return int(value)
        except (TypeError, ValueError):
            return None


    def apply_optional_filter(query, model, field_name, value):
        """
        Apply a filter only if the model actually has the column.
        This prevents route crashes when an optional field is absent.
        """

        if value is None:
            return query

        column = getattr(model, field_name, None)

        if column is None:
            return query

        return query.filter(column == value)


    def normalize_status(value):
        if value is None:
            return ""

        return str(value).strip().lower()


    # ========================================================
    # CURRENT USER
    # ========================================================

    current_user = getattr(g, "user", None)

    if current_user is None:
        current_user = current_user if "current_user" in locals() else None

    # Flask-Login current_user fallback
    try:
        from flask_login import current_user as flask_current_user

        if current_user is None or not getattr(
            current_user,
            "is_authenticated",
            True
        ):
            current_user = flask_current_user

    except Exception:
        pass


    # ========================================================
    # ROLE
    # ========================================================

    user_role = str(
        first_value(
            current_user,
            "role",
            default=""
        ) or ""
    ).lower().strip()


    allowed_roles = {
        "superadmin",
        "school_admin",
        "institution_admin",
        "branch_admin",
        "teacher",
    }

    if user_role not in allowed_roles:
        abort(403)


    # ========================================================
    # CURRENT INSTITUTION / BRANCH
    # ========================================================

    user_institution_id = first_value(
        current_user,
        "institution_id",
        default=None
    )

    user_branch_id = first_value(
        current_user,
        "branch_id",
        default=None
    )


    # Teacher fallback
    teacher = getattr(g, "teacher", None)

    if user_role == "teacher" and teacher:

        if user_institution_id is None:
            user_institution_id = getattr(
                teacher,
                "institution_id",
                None
            )

        if user_branch_id is None:
            user_branch_id = getattr(
                teacher,
                "branch_id",
                None
            )


    # ========================================================
    # REQUEST FILTERS
    # ========================================================

    search = (
        request.args.get("search", "", type=str)
        .strip()
    )

    student_id = normalize_id(
        request.args.get("student_id")
    )

    academic_year_id = normalize_id(
        request.args.get("academic_year_id")
    )

    term_id = normalize_id(
        request.args.get("term_id")
    )


    # ========================================================
    # STUDENT QUERY
    #
    # IMPORTANT:
    # Do NOT load all students.
    # Only return limited search suggestions.
    # Suitable for very large databases.
    # ========================================================

    student_query = Student.query


    # ========================================================
    # ROLE SCOPING
    # ========================================================

    if user_role != "superadmin":

        if user_institution_id is not None:

            student_query = student_query.filter(
                Student.institution_id == user_institution_id
            )

        else:
            abort(403)


    # Branch admin / teacher
    if user_role in {
        "branch_admin",
        "teacher",
    }:

        if user_branch_id is not None:

            student_query = student_query.filter(
                Student.branch_id == user_branch_id
            )

        else:
            abort(403)


    # ========================================================
    # STUDENT SEARCH SUGGESTIONS
    # ========================================================

    student_results = []

    if search:

        search_pattern = f"%{search}%"

        search_conditions = []

        possible_student_fields = [
            "admission_no",
            "roll_no",
            "name",
            "full_name",
            "student_name",
            "first_name",
            "last_name",
        ]

        for field_name in possible_student_fields:

            column = getattr(
                Student,
                field_name,
                None
            )

            if column is not None:

                search_conditions.append(
                    column.ilike(search_pattern)
                )


        if search_conditions:

            student_results = (
                student_query
                .filter(or_(*search_conditions))
                .order_by(
                    getattr(
                        Student,
                        "name",
                        getattr(
                            Student,
                            "full_name",
                            Student.id
                        )
                    )
                )
                .limit(50)
                .all()
            )


    # ========================================================
    # LOAD EXACT STUDENT
    # ========================================================

    student = None

    if student_id:

        student = (
            student_query
            .filter(Student.id == student_id)
            .first()
        )

        if not student:
            abort(404)


    # ========================================================
    # IF SEARCH MATCHES EXACTLY ONE STUDENT
    #
    # We do NOT automatically select random first student.
    # If one exact match exists, select it.
    # ========================================================

    if student is None and search and student_results:

        normalized_search = search.lower().strip()

        exact_matches = []

        for item in student_results:

            candidate_values = [
                first_value(item, "admission_no"),
                first_value(item, "roll_no"),
                first_value(item, "name"),
                first_value(item, "full_name"),
                first_value(item, "student_name"),
            ]

            candidate_name = (
                f"{first_value(item, 'first_name', default='') or ''} "
                f"{first_value(item, 'last_name', default='') or ''}"
            ).strip()

            candidate_values.append(candidate_name)

            for candidate in candidate_values:

                if candidate is not None:

                    if str(candidate).strip().lower() == normalized_search:
                        exact_matches.append(item)
                        break


        if len(exact_matches) == 1:

            student = exact_matches[0]


    # ========================================================
    # DEFAULT EMPTY DATA
    # ========================================================

    institution = None
    branch = None

    enrollments = []
    current_enrollment = None
    enrollment_data = {
        "program": None,
        "academic_year": None,
        "class": None,
        "section": None,
    }

    attendance_rows = []
    attendance_total = 0

    attendance_summary = {
        "total": 0,
        "present": 0,
        "absent": 0,
        "late": 0,
        "excused": 0,
        "sick": 0,
        "leave": 0,
        "attendance_percentage": 0,
    }

    exam_mark_rows = []
    mark_total = 0

    student_results_exam = []

    result_summary = {
        "total_exams": 0,
        "passed": 0,
        "failed": 0,
        "incomplete": 0,
        "published": 0,
        "average_percentage": 0,
    }

    ranking_rows = []

    rank_summary = {
        "institution_position": None,
        "branch_position": None,
        "program_position": None,
        "class_position": None,
        "section_position": None,
    }


    # ========================================================
    # LOAD INSTITUTION / BRANCH
    # ========================================================

    if student:

        institution = getattr(
            student,
            "institution",
            None
        )

        branch = getattr(
            student,
            "branch",
            None
        )

        # ----------------------------------------------------
        # FALLBACK INSTITUTION
        # ----------------------------------------------------

        if institution is None:

            student_institution_id = getattr(
                student,
                "institution_id",
                None
            )

            if student_institution_id:

                institution = (
                    Institution.query
                    .filter(
                        Institution.id ==
                        student_institution_id
                    )
                    .first()
                )


        # ----------------------------------------------------
        # FALLBACK BRANCH
        # ----------------------------------------------------

        if branch is None:

            student_branch_id = getattr(
                student,
                "branch_id",
                None
            )

            if student_branch_id:

                branch = (
                    Branch.query
                    .filter(
                        Branch.id ==
                        student_branch_id
                    )
                    .first()
                )


        # ====================================================
        # ENROLLMENTS
        # ====================================================

        enrollment_query = (
            StudentEnrollment.query
            .filter(
                StudentEnrollment.student_id ==
                student.id
            )
        )


        # Institution safety
        if hasattr(
            StudentEnrollment,
            "institution_id"
        ):

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.institution_id ==
                getattr(
                    student,
                    "institution_id",
                    user_institution_id
                )
            )


        # Branch safety
        if (
            user_role in {
                "branch_admin",
                "teacher",
            }
            and hasattr(
                StudentEnrollment,
                "branch_id"
            )
            and user_branch_id is not None
        ):

            enrollment_query = enrollment_query.filter(
                StudentEnrollment.branch_id ==
                user_branch_id
            )


        # Academic year filter
        enrollment_query = apply_optional_filter(
            enrollment_query,
            StudentEnrollment,
            "academic_year_id",
            academic_year_id
        )


        enrollments = (
            enrollment_query
            .order_by(
                StudentEnrollment.id.desc()
            )
            .all()
        )


        # ====================================================
        # CURRENT ENROLLMENT
        # ====================================================

        if enrollments:

            active_enrollment = None

            for enrollment in enrollments:

                status = normalize_status(
                    getattr(
                        enrollment,
                        "status",
                        ""
                    )
                )

                if status in {
                    "active",
                    "current",
                    "enrolled",
                }:

                    active_enrollment = enrollment
                    break


            current_enrollment = (
                active_enrollment
                or enrollments[0]
            )


        # ====================================================
        # ENROLLMENT DATA
        # ====================================================

        if current_enrollment:

            enrollment_data = {
                "program": getattr(
                    current_enrollment,
                    "program",
                    None
                ),

                "academic_year": getattr(
                    current_enrollment,
                    "academic_year",
                    None
                ),

                "class": getattr(
                    current_enrollment,
                    "class_",
                    getattr(
                        current_enrollment,
                        "classroom",
                        getattr(
                            current_enrollment,
                            "class",
                            None
                        )
                    )
                ),

                "section": getattr(
                    current_enrollment,
                    "section",
                    None
                ),
            }


        # ====================================================
        # ATTENDANCE
        # ====================================================

        try:

            attendance_query = (
                AttendanceRecord.query
                .join(
                    AttendanceRecord.session
                )
                .filter(
                    AttendanceRecord.student_id ==
                    student.id
                )
            )


            # Session institution
            attendance_session_model = (
                getattr(
                    AttendanceRecord,
                    "session",
                    None
                )
            )


            # Academic year
            if academic_year_id:

                session_rel = getattr(
                    AttendanceRecord,
                    "session",
                    None
                )

                if session_rel is not None:

                    try:

                        attendance_query = (
                            attendance_query
                            .filter(
                                AttendanceSession.academic_year_id
                                ==
                                academic_year_id
                            )
                        )

                    except Exception:
                        pass


            # Term
            if term_id:

                try:

                    attendance_query = (
                        attendance_query
                        .filter(
                            AttendanceSession.term_id ==
                            term_id
                        )
                    )

                except Exception:
                    pass


            # Institution
            try:

                attendance_query = (
                    attendance_query
                    .filter(
                        AttendanceSession.institution_id ==
                        getattr(
                            student,
                            "institution_id",
                            user_institution_id
                        )
                    )
                )

            except Exception:
                pass


            # Branch
            if (
                user_role in {
                    "branch_admin",
                    "teacher",
                }
                and user_branch_id is not None
            ):

                try:

                    attendance_query = (
                        attendance_query
                        .filter(
                            AttendanceSession.branch_id ==
                            user_branch_id
                        )
                    )

                except Exception:
                    pass


            attendance_records = (
                attendance_query
                .order_by(
                    AttendanceRecord.id.desc()
                )
                .all()
            )


            # ------------------------------------------------
            # BUILD ATTENDANCE ROWS
            # ------------------------------------------------

            for record in attendance_records:

                session = getattr(
                    record,
                    "session",
                    None
                )

                status = first_value(
                    record,
                    "status",
                    "attendance_status",
                    default=""
                )


                date_value = first_value(
                    record,
                    "attendance_date",
                    "date",
                    default=None
                )

                if date_value is None and session:

                    date_value = first_value(
                        session,
                        "attendance_date",
                        "date",
                        "session_date",
                        default=None
                    )


                row = {
                    "record": record,
                    "session": session,
                    "date": date_value,
                    "status": status,
                    "minutes_late": first_value(
                        record,
                        "minutes_late",
                        "late_minutes",
                        default=None
                    ),
                    "check_in": first_value(
                        record,
                        "check_in",
                        "check_in_time",
                        default=None
                    ),
                    "check_out": first_value(
                        record,
                        "check_out",
                        "check_out_time",
                        default=None
                    ),
                    "notes": first_value(
                        record,
                        "notes",
                        "note",
                        "remarks",
                        default=None
                    ),
                }

                attendance_rows.append(row)


            # ------------------------------------------------
            # ATTENDANCE SUMMARY
            # ------------------------------------------------

            attendance_total = len(
                attendance_rows
            )

            for row in attendance_rows:

                status = normalize_status(
                    row["status"]
                )

                if status in {
                    "present",
                    "p",
                }:

                    attendance_summary["present"] += 1

                elif status in {
                    "absent",
                    "a",
                }:

                    attendance_summary["absent"] += 1

                elif status in {
                    "late",
                    "l",
                }:

                    attendance_summary["late"] += 1

                elif status in {
                    "excused",
                    "e",
                }:

                    attendance_summary["excused"] += 1

                elif status in {
                    "sick",
                }:

                    attendance_summary["sick"] += 1

                elif status in {
                    "leave",
                }:

                    attendance_summary["leave"] += 1


            attendance_summary["total"] = (
                attendance_total
            )


            # Present + Late are treated as attended
            attended_count = (
                attendance_summary["present"]
                +
                attendance_summary["late"]
            )


            if attendance_total > 0:

                attendance_summary[
                    "attendance_percentage"
                ] = round(
                    (
                        attended_count /
                        attendance_total
                    ) * 100,
                    2
                )

            else:

                attendance_summary[
                    "attendance_percentage"
                ] = 0


        except Exception:

            # Do not allow attendance relationship
            # problems to destroy the complete report.
            attendance_rows = []
            attendance_total = 0


        # ====================================================
        # MARKS
        # ====================================================

        try:

            mark_query = (
                Mark.query
                .filter(
                    Mark.student_id ==
                    student.id
                )
            )


            # Institution
            if hasattr(
                Mark,
                "institution_id"
            ):

                mark_query = mark_query.filter(
                    Mark.institution_id ==
                    getattr(
                        student,
                        "institution_id",
                        user_institution_id
                    )
                )


            # Branch
            if (
                user_role in {
                    "branch_admin",
                    "teacher",
                }
                and user_branch_id is not None
                and hasattr(
                    Mark,
                    "branch_id"
                )
            ):

                mark_query = mark_query.filter(
                    Mark.branch_id ==
                    user_branch_id
                )


            # Academic year
            mark_query = apply_optional_filter(
                mark_query,
                Mark,
                "academic_year_id",
                academic_year_id
            )


            # Term
            mark_query = apply_optional_filter(
                mark_query,
                Mark,
                "term_id",
                term_id
            )


            marks = (
                mark_query
                .order_by(
                    Mark.id.desc()
                )
                .all()
            )


            # =================================================
            # BUILD MARK ROWS
            # =================================================

            for mark in marks:

                exam_subject = getattr(
                    mark,
                    "exam_subject",
                    None
                )


                exam = getattr(
                    mark,
                    "exam",
                    None
                )


                subject = getattr(
                    mark,
                    "subject",
                    None
                )


                # ---------------------------------------------
                # FALLBACK EXAM SUBJECT
                # ---------------------------------------------

                if exam_subject is None:

                    exam_subject_id = getattr(
                        mark,
                        "exam_subject_id",
                        None
                    )

                    if exam_subject_id:

                        try:

                            exam_subject = (
                                ExamSubject.query
                                .filter(
                                    ExamSubject.id ==
                                    exam_subject_id
                                )
                                .first()
                            )

                        except Exception:
                            exam_subject = None


                # ---------------------------------------------
                # FALLBACK EXAM
                # ---------------------------------------------

                if exam is None and exam_subject:

                    exam = getattr(
                        exam_subject,
                        "exam",
                        None
                    )


                # ---------------------------------------------
                # FALLBACK SUBJECT
                # ---------------------------------------------

                if subject is None and exam_subject:

                    subject = getattr(
                        exam_subject,
                        "subject",
                        None
                    )


                marks_obtained = first_value(
                    mark,
                    "marks_obtained",
                    "obtained_marks",
                    "score",
                    "marks",
                    "mark",
                    default=None
                )


                is_absent = bool(
                    first_value(
                        mark,
                        "is_absent",
                        "absent",
                        default=False
                    )
                )


                is_exempted = bool(
                    first_value(
                        mark,
                        "is_exempted",
                        "exempted",
                        default=False
                    )
                )


                exam_mark_rows.append({

                    "mark": mark,

                    "exam_subject": exam_subject,

                    "exam": exam,

                    "subject": subject,

                    "marks_obtained": marks_obtained,

                    "is_absent": is_absent,

                    "is_exempted": is_exempted,

                    "status": first_value(
                        mark,
                        "status",
                        "mark_status",
                        default=None
                    ),

                    "remarks": first_value(
                        mark,
                        "remarks",
                        "remark",
                        "notes",
                        "note",
                        default=None
                    ),
                })


            mark_total = len(
                exam_mark_rows
            )


        except Exception:

            exam_mark_rows = []
            mark_total = 0


        # ====================================================
        # STUDENT RESULTS
        # ====================================================

        try:

            result_query = (
                StudentResult.query
                .filter(
                    StudentResult.student_id ==
                    student.id
                )
            )


            # Institution
            if hasattr(
                StudentResult,
                "institution_id"
            ):

                result_query = result_query.filter(
                    StudentResult.institution_id ==
                    getattr(
                        student,
                        "institution_id",
                        user_institution_id
                    )
                )


            # Branch
            if (
                user_role in {
                    "branch_admin",
                    "teacher",
                }
                and user_branch_id is not None
                and hasattr(
                    StudentResult,
                    "branch_id"
                )
            ):

                result_query = result_query.filter(
                    StudentResult.branch_id ==
                    user_branch_id
                )


            # Academic Year
            result_query = apply_optional_filter(
                result_query,
                StudentResult,
                "academic_year_id",
                academic_year_id
            )


            # Term
            result_query = apply_optional_filter(
                result_query,
                StudentResult,
                "term_id",
                term_id
            )


            student_results_exam = (
                result_query
                .order_by(
                    StudentResult.id.desc()
                )
                .all()
            )


            # =================================================
            # RESULT SUMMARY
            # =================================================

            result_summary["total_exams"] = len(
                student_results_exam
            )


            percentage_values = []


            for result in student_results_exam:

                result_status = normalize_status(
                    first_value(
                        result,
                        "result_status",
                        "status",
                        default=""
                    )
                )


                publication_status = normalize_status(
                    first_value(
                        result,
                        "status",
                        default=""
                    )
                )


                if result_status in {
                    "pass",
                    "passed",
                    "promoted",
                }:

                    result_summary["passed"] += 1


                elif result_status in {
                    "fail",
                    "failed",
                }:

                    result_summary["failed"] += 1


                elif result_status in {
                    "incomplete",
                    "pending",
                }:

                    result_summary["incomplete"] += 1


                if publication_status in {
                    "published",
                }:

                    result_summary["published"] += 1


                percentage = first_value(
                    result,
                    "percentage",
                    "average_percentage",
                    default=None
                )


                if percentage is not None:

                    try:
                        percentage_values.append(
                            float(percentage)
                        )
                    except (
                        TypeError,
                        ValueError
                    ):
                        pass


            if percentage_values:

                result_summary[
                    "average_percentage"
                ] = round(
                    sum(percentage_values)
                    /
                    len(percentage_values),
                    2
                )


        except Exception:

            student_results_exam = []


        # ====================================================
        # RANKING
        #
        # StudentResult architecture:
        #
        # institution_position
        # branch_position
        # program_position
        # class_position
        # section_position
        # ====================================================

        if student_results_exam:

            latest_result = student_results_exam[0]


            rank_summary = {

                "institution_position":
                    first_value(
                        latest_result,
                        "institution_position",
                        default=None
                    ),

                "branch_position":
                    first_value(
                        latest_result,
                        "branch_position",
                        default=None
                    ),

                "program_position":
                    first_value(
                        latest_result,
                        "program_position",
                        default=None
                    ),

                "class_position":
                    first_value(
                        latest_result,
                        "class_position",
                        default=None
                    ),

                "section_position":
                    first_value(
                        latest_result,
                        "section_position",
                        default=None
                    ),
            }


            # =================================================
            # BUILD RANKING TABLE DATA
            # =================================================

            for result in student_results_exam:

                ranking_rows.append({

                    "exam": getattr(
                        result,
                        "exam",
                        None
                    ),

                    "academic_year": getattr(
                        result,
                        "academic_year",
                        None
                    ),

                    "term": getattr(
                        result,
                        "term",
                        None
                    ),

                    "percentage": first_value(
                        result,
                        "percentage",
                        default=None
                    ),

                    "grade": first_value(
                        result,
                        "grade",
                        default=None
                    ),

                    "gpa": first_value(
                        result,
                        "gpa",
                        default=None
                    ),

                    "result_status": first_value(
                        result,
                        "result_status",
                        default=None
                    ),

                    "institution_position":
                        first_value(
                            result,
                            "institution_position",
                            default=None
                        ),

                    "branch_position":
                        first_value(
                            result,
                            "branch_position",
                            default=None
                        ),

                    "program_position":
                        first_value(
                            result,
                            "program_position",
                            default=None
                        ),

                    "class_position":
                        first_value(
                            result,
                            "class_position",
                            default=None
                        ),

                    "section_position":
                        first_value(
                            result,
                            "section_position",
                            default=None
                        ),

                    "status": first_value(
                        result,
                        "status",
                        default=None
                    ),
                })


        # ====================================================
        # ACADEMIC YEAR / TERM LISTS
        #
        # IMPORTANT:
        # These are NOT all students.
        # They are only filter options.
        # ====================================================

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = AcademicYear.query


    if user_role != "superadmin":

        if user_institution_id is not None:

            if hasattr(
                AcademicYear,
                "institution_id"
            ):

                academic_year_query = (
                    academic_year_query
                    .filter(
                        AcademicYear.institution_id ==
                        user_institution_id
                    )
                )


    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )


    # ========================================================
    # TERMS
    # ========================================================

    term_query = Term.query


    if user_role != "superadmin":

        if user_institution_id is not None:

            if hasattr(
                Term,
                "institution_id"
            ):

                term_query = (
                    term_query
                    .filter(
                        Term.institution_id ==
                        user_institution_id
                    )
                )


    if academic_year_id:

        if hasattr(
            Term,
            "academic_year_id"
        ):

            term_query = term_query.filter(
                Term.academic_year_id ==
                academic_year_id
            )


    terms = (
        term_query
        .order_by(
            Term.id.asc()
        )
        .all()
    )


    # ========================================================
    # STUDENT DATA
    # ========================================================

    student_data = None

    if student:

        student_name = first_value(
            student,
            "name",
            "full_name",
            "student_name",
            default=None
        )


        if not student_name:

            student_name = (
                f"{first_value(student, 'first_name', default='') or ''} "
                f"{first_value(student, 'last_name', default='') or ''}"
            ).strip()


        student_data = {

            "id":
                getattr(student, "id", None),

            "name":
                student_name or "Student",

            "admission_no":
                first_value(
                    student,
                    "admission_no",
                    "admission_number",
                    default=None
                ),

            "roll_no":
                first_value(
                    student,
                    "roll_no",
                    "roll_number",
                    default=None
                ),

            "gender":
                first_value(
                    student,
                    "gender",
                    default=None
                ),

            "dob":
                first_value(
                    student,
                    "dob",
                    "date_of_birth",
                    default=None
                ),

            "phone":
                first_value(
                    student,
                    "phone",
                    "phone_number",
                    default=None
                ),

            "email":
                first_value(
                    student,
                    "email",
                    default=None
                ),

            "address":
                first_value(
                    student,
                    "address",
                    default=None
                ),

            "photo":
                first_value(
                    student,
                    "photo",
                    "photo_url",
                    "profile_photo",
                    "image",
                    default=None
                ),
        }


    # ========================================================
    # RANK SUMMARY
    #
    # Additional readable ranking information for template.
    # ========================================================

    ranking_display = {

        "institution":
            rank_summary.get(
                "institution_position"
            ),

        "branch":
            rank_summary.get(
                "branch_position"
            ),

        "program":
            rank_summary.get(
                "program_position"
            ),

        "class":
            rank_summary.get(
                "class_position"
            ),

        "section":
            rank_summary.get(
                "section_position"
            ),
    }


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/students/student_report.html",

        # ----------------------------------------------------
        # STUDENT
        # ----------------------------------------------------

        student=student,

        student_data=student_data,

        student_results=student_results,

        # ----------------------------------------------------
        # INSTITUTION / BRANCH
        # ----------------------------------------------------

        institution=institution,

        branch=branch,

        # ----------------------------------------------------
        # ENROLLMENT
        # ----------------------------------------------------

        enrollments=enrollments,

        current_enrollment=current_enrollment,

        enrollment_data=enrollment_data,

        # ----------------------------------------------------
        # ATTENDANCE
        # ----------------------------------------------------

        attendance_rows=attendance_rows,

        attendance_total=attendance_total,

        attendance_summary=attendance_summary,

        # ----------------------------------------------------
        # MARKS
        # ----------------------------------------------------

        exam_mark_rows=exam_mark_rows,

        mark_total=mark_total,

        # ----------------------------------------------------
        # RESULTS
        # ----------------------------------------------------

        student_results_exam=student_results_exam,

        result_summary=result_summary,

        # ----------------------------------------------------
        # RANKING
        # ----------------------------------------------------

        ranking_rows=ranking_rows,

        rank_summary=rank_summary,

        ranking_display=ranking_display,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        academic_years=academic_years,

        terms=terms,


        search=search,

        student_id=student_id,

        academic_year_id=academic_year_id,

        term_id=term_id,
    )



# ============================================================
# STUDENT ABSENT REPORT
# ============================================================


@bp.route(
    "/attendance/reports/student-absent",
    methods=["GET"]
)
@login_required
def student_absent_report():

    # ========================================================
    # IMPORTS
    # ========================================================

    from datetime import date, datetime
    from zoneinfo import ZoneInfo

    from sqlalchemy import (
        func,
        case,
        or_,
        and_,
    )

    # ========================================================
    # SECURITY
    # ========================================================

    user = current_user

    if not user or not user.is_authenticated:
        abort(403)

    role = getattr(
        user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT DATE
    # AFRICA/MOGADISHU
    # ========================================================

    try:
        today = datetime.now(
            ZoneInfo("Africa/Mogadishu")
        ).date()
    except Exception:
        today = date.today()

    # ========================================================
    # SAFE INTEGER
    # ========================================================

    def _to_int(value, default=None):
        try:
            if value is None:
                return default

            value = str(value).strip()

            if not value:
                return default

            return int(value)

        except (TypeError, ValueError):
            return default

    # ========================================================
    # QUERY PARAMETERS
    # ========================================================

    search = (
        request.args.get("search", "")
        .strip()
    )

    academic_year_id = _to_int(
        request.args.get("academic_year_id")
    )

    branch_id = _to_int(
        request.args.get("branch_id")
    )

    class_id = _to_int(
        request.args.get("class_id")
    )

    section_id = _to_int(
        request.args.get("section_id")
    )

    subject_id = _to_int(
        request.args.get("subject_id")
    )

    teacher_id = _to_int(
        request.args.get("teacher_id")
    )

    # ========================================================
    # DATE FILTERS
    # ========================================================

    date_from_raw = (
        request.args.get("date_from", "")
        .strip()
    )

    date_to_raw = (
        request.args.get("date_to", "")
        .strip()
    )

    date_from = None
    date_to = None

    # --------------------------------------------------------
    # Parse date_from
    # --------------------------------------------------------

    if date_from_raw:
        try:
            date_from = date.fromisoformat(
                date_from_raw
            )
        except ValueError:
            date_from = None

    # --------------------------------------------------------
    # Parse date_to
    # --------------------------------------------------------

    if date_to_raw:
        try:
            date_to = date.fromisoformat(
                date_to_raw
            )
        except ValueError:
            date_to = None

    # ========================================================
    # DATE VALIDATION
    # ========================================================

    if date_from and date_to:
        if date_from > date_to:
            date_from, date_to = (
                date_to,
                date_from
            )

    # ========================================================
    # PAGINATION
    # ========================================================

    page = _to_int(
        request.args.get("page"),
        1
    )

    if not page or page < 1:
        page = 1

    per_page = _to_int(
        request.args.get("per_page"),
        10
    )

    if per_page not in {
        10,
        25,
        50,
        100,
    }:
        per_page = 10

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        user,
        "branch_id",
        None
    )

    # ========================================================
    # TEACHER SCOPE
    # ========================================================

    teacher_scope_id = None

    if role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:
            abort(403)

        teacher_scope_id = teacher.id

        # Teacher's own branch is authoritative.
        teacher_branch_id = getattr(
            teacher,
            "branch_id",
            None
        )

        if teacher_branch_id:
            user_branch_id = teacher_branch_id

        # Teacher's institution is authoritative.
        teacher_institution_id = getattr(
            teacher,
            "institution_id",
            None
        )

        if teacher_institution_id:
            user_institution_id = (
                teacher_institution_id
            )

    # ========================================================
    # FORCE BRANCH FOR RESTRICTED ROLES
    # ========================================================

    if role in {
        "branch_admin",
        "teacher",
    }:

        branch_id = user_branch_id

        if not branch_id:
            abort(403)

    # ========================================================
    # FORCE TEACHER FOR TEACHER ROLE
    # ========================================================

    if role == "teacher":

        teacher_id = teacher_scope_id

    # ========================================================
    # VALIDATE INSTITUTION FOR RESTRICTED USERS
    # ========================================================

    if role in {
        "school_admin",
        "branch_admin",
        "teacher",
    }:

        if not user_institution_id:
            abort(403)

    # ========================================================
    # VALIDATE SELECTED BRANCH
    # ========================================================

    selected_branch = None

    if branch_id:

        selected_branch = (
            db.session.query(Branch)
            .filter(
                Branch.id == branch_id
            )
            .first()
        )

        if not selected_branch:
            abort(404)

        # ----------------------------------------------------
        # school_admin
        # ----------------------------------------------------

        if role == "school_admin":

            if (
                selected_branch.institution_id
                != user_institution_id
            ):
                abort(403)

        # ----------------------------------------------------
        # branch_admin
        # ----------------------------------------------------

        elif role == "branch_admin":

            if (
                selected_branch.institution_id
                != user_institution_id
            ):
                abort(403)

            if (
                selected_branch.id
                != user_branch_id
            ):
                abort(403)

        # ----------------------------------------------------
        # teacher
        # ----------------------------------------------------

        elif role == "teacher":

            if (
                selected_branch.institution_id
                != user_institution_id
            ):
                abort(403)

            if (
                selected_branch.id
                != user_branch_id
            ):
                abort(403)

    # ========================================================
    # VALIDATE ACADEMIC YEAR
    # ========================================================

    selected_academic_year = None

    if academic_year_id:

        selected_academic_year = (
            db.session.query(AcademicYear)
            .filter(
                AcademicYear.id
                == academic_year_id
            )
            .first()
        )

        if not selected_academic_year:
            abort(404)

        if role != "superadmin":

            if (
                selected_academic_year.institution_id
                != user_institution_id
            ):
                abort(403)

    # ========================================================
    # VALIDATE CLASS
    # ========================================================

    selected_class = None

    if class_id:

        selected_class = (
            db.session.query(Class)
            .filter(
                Class.id == class_id
            )
            .first()
        )

        if not selected_class:
            abort(404)

        if role != "superadmin":

            if (
                selected_class.institution_id
                != user_institution_id
            ):
                abort(403)

        # ----------------------------------------------------
        # Branch validation where class is branch-specific
        # ----------------------------------------------------

        class_branch_id = getattr(
            selected_class,
            "branch_id",
            None
        )

        if branch_id and class_branch_id:

            if class_branch_id != branch_id:
                abort(403)

    # ========================================================
    # VALIDATE SECTION
    # ========================================================

    selected_section = None

    if section_id:

        selected_section = (
            db.session.query(Section)
            .filter(
                Section.id == section_id
            )
            .first()
        )

        if not selected_section:
            abort(404)

        if role != "superadmin":

            section_institution_id = getattr(
                selected_section,
                "institution_id",
                None
            )

            if (
                section_institution_id
                and section_institution_id
                != user_institution_id
            ):
                abort(403)

        # ----------------------------------------------------
        # Section -> class validation
        # ----------------------------------------------------

        section_class_id = getattr(
            selected_section,
            "class_id",
            None
        )

        if class_id and section_class_id:

            if section_class_id != class_id:
                abort(403)

        # ----------------------------------------------------
        # Section -> branch validation
        # ----------------------------------------------------

        section_branch_id = getattr(
            selected_section,
            "branch_id",
            None
        )

        if branch_id and section_branch_id:

            if section_branch_id != branch_id:
                abort(403)

    # ========================================================
    # VALIDATE SUBJECT
    # ========================================================

    selected_subject = None

    if subject_id:

        selected_subject = (
            db.session.query(Subject)
            .filter(
                Subject.id == subject_id
            )
            .first()
        )

        if not selected_subject:
            abort(404)

        if role != "superadmin":

            subject_institution_id = getattr(
                selected_subject,
                "institution_id",
                None
            )

            if (
                subject_institution_id
                and subject_institution_id
                != user_institution_id
            ):
                abort(403)

        # ----------------------------------------------------
        # Branch-specific subject
        # ----------------------------------------------------

        subject_branch_id = getattr(
            selected_subject,
            "branch_id",
            None
        )

        if branch_id and subject_branch_id:

            if subject_branch_id != branch_id:
                abort(403)

    # ========================================================
    # VALIDATE TEACHER FILTER
    # ========================================================

    selected_teacher = None

    if teacher_id:

        selected_teacher = (
            db.session.query(Teacher)
            .filter(
                Teacher.id == teacher_id
            )
            .first()
        )

        if not selected_teacher:
            abort(404)

        if role != "superadmin":

            if (
                selected_teacher.institution_id
                != user_institution_id
            ):
                abort(403)

        # ----------------------------------------------------
        # Branch-specific teacher
        # ----------------------------------------------------

        selected_teacher_branch_id = getattr(
            selected_teacher,
            "branch_id",
            None
        )

        if (
            branch_id
            and selected_teacher_branch_id
            and selected_teacher_branch_id
            != branch_id
        ):
            abort(403)

    # ========================================================
    # BASE ATTENDANCE FILTERS
    # ========================================================

    base_filters = []

    # --------------------------------------------------------
    # Institution
    # --------------------------------------------------------

    if role != "superadmin":

        base_filters.append(
            AttendanceSession.institution_id
            == user_institution_id
        )

    # --------------------------------------------------------
    # Branch
    # --------------------------------------------------------

    if branch_id:

        base_filters.append(
            AttendanceSession.branch_id
            == branch_id
        )

    # --------------------------------------------------------
    # Academic Year
    # --------------------------------------------------------

    if academic_year_id:

        base_filters.append(
            AttendanceSession.academic_year_id
            == academic_year_id
        )

    # --------------------------------------------------------
    # Class
    # --------------------------------------------------------

    if class_id:

        base_filters.append(
            AttendanceSession.class_id
            == class_id
        )

    # --------------------------------------------------------
    # Section
    # --------------------------------------------------------

    if section_id:

        base_filters.append(
            AttendanceSession.section_id
            == section_id
        )

    # --------------------------------------------------------
    # Subject
    # --------------------------------------------------------

    if subject_id:

        base_filters.append(
            AttendanceSession.subject_id
            == subject_id
        )

    # --------------------------------------------------------
    # Teacher
    # --------------------------------------------------------

    if teacher_id:

        base_filters.append(
            AttendanceSession.teacher_id
            == teacher_id
        )

    # --------------------------------------------------------
    # Date From
    # --------------------------------------------------------

    if date_from:

        base_filters.append(
            AttendanceSession.attendance_date
            >= date_from
        )

    # --------------------------------------------------------
    # Date To
    # --------------------------------------------------------

    if date_to:

        base_filters.append(
            AttendanceSession.attendance_date
            <= date_to
        )

    # ========================================================
    # SEARCH STUDENT
    # ========================================================

    if search:

        search_like = f"%{search}%"

        base_filters.append(
            or_(
                Student.full_name.ilike(
                    search_like
                ),
                Student.admission_no.ilike(
                    search_like
                ),
                Student.roll_no.ilike(
                    search_like
                )
            )
        )

    # ========================================================
    # STATUS EXPRESSIONS
    # ========================================================

    absent_case = case(
        (
            AttendanceRecord.status
            == "absent",
            1
        ),
        else_=0
    )

    present_case = case(
        (
            AttendanceRecord.status
            == "present",
            1
        ),
        else_=0
    )

    late_case = case(
        (
            AttendanceRecord.status
            == "late",
            1
        ),
        else_=0
    )

    excused_case = case(
        (
            AttendanceRecord.status
            == "excused",
            1
        ),
        else_=0
    )

    sick_case = case(
        (
            AttendanceRecord.status
            == "sick",
            1
        ),
        else_=0
    )

    leave_case = case(
        (
            AttendanceRecord.status
            == "leave",
            1
        ),
        else_=0
    )

    # ========================================================
    # MAIN STUDENT REPORT QUERY
    #
    # IMPORTANT:
    # We DO NOT filter AttendanceRecord.status == "absent"
    # here.
    #
    # Instead:
    #   HAVING absent_count > 0
    #
    # This allows all statuses to be counted correctly.
    # ========================================================

    report_query = (
        db.session.query(
            Student.id.label(
                "student_id"
            ),

            Student.full_name.label(
                "student_name"
            ),

            Student.admission_no.label(
                "admission_no"
            ),

            Student.roll_no.label(
                "roll_no"
            ),

            Student.photo.label(
                "student_photo"
            ),

            func.count(
                AttendanceRecord.id
            ).label(
                "total_attendance"
            ),

            func.coalesce(
                func.sum(
                    absent_case
                ),
                0
            ).label(
                "absent_count"
            ),

            func.coalesce(
                func.sum(
                    present_case
                ),
                0
            ).label(
                "present_count"
            ),

            func.coalesce(
                func.sum(
                    late_case
                ),
                0
            ).label(
                "late_count"
            ),

            func.coalesce(
                func.sum(
                    excused_case
                ),
                0
            ).label(
                "excused_count"
            ),

            func.coalesce(
                func.sum(
                    sick_case
                ),
                0
            ).label(
                "sick_count"
            ),

            func.coalesce(
                func.sum(
                    leave_case
                ),
                0
            ).label(
                "leave_count"
            ),
        )

        .join(
            AttendanceSession,
            AttendanceSession.id
            == AttendanceRecord.attendance_session_id
        )

        .join(
            Student,
            Student.id
            == AttendanceRecord.student_id
        )

        .filter(
            *base_filters
        )

        .group_by(
            Student.id,
            Student.full_name,
            Student.admission_no,
            Student.roll_no,
            Student.photo,
        )

        # ----------------------------------------------------
        # ONLY STUDENTS WITH ABSENCE
        # ----------------------------------------------------

        .having(
            func.sum(
                absent_case
            ) > 0
        )

        .order_by(
            Student.full_name.asc()
        )
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = report_query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    absent_reports = []

    # ========================================================
    # CURRENT PAGE STUDENT IDS
    # ========================================================

    student_ids = [
        row.student_id
        for row in pagination.items
        if row.student_id
    ]

    # ========================================================
    # ACTIVE ENROLLMENT DISPLAY DATA
    # ========================================================

    enrollment_map = {}

    if student_ids:

        enrollment_rows = (
            db.session.query(
                StudentEnrollment.student_id,

                Branch.name.label(
                    "branch_name"
                ),

                Class.name.label(
                    "class_name"
                ),

                Section.name.label(
                    "section_name"
                ),
            )

            .join(
                Branch,
                Branch.id
                == StudentEnrollment.branch_id
            )

            .join(
                Class,
                Class.id
                == StudentEnrollment.class_id
            )

            .outerjoin(
                Section,
                Section.id
                == StudentEnrollment.section_id
            )

            .filter(
                StudentEnrollment.student_id.in_(
                    student_ids
                )
            )

            .filter(
                StudentEnrollment.status
                == "active"
            )
        )

        # ----------------------------------------------------
        # Keep institution scope
        # ----------------------------------------------------

        if role != "superadmin":

            enrollment_rows = enrollment_rows.filter(
                StudentEnrollment.institution_id
                == user_institution_id
            )

        # ----------------------------------------------------
        # If branch is selected, display enrollment
        # from that branch.
        # ----------------------------------------------------

        if branch_id:

            enrollment_rows = enrollment_rows.filter(
                StudentEnrollment.branch_id
                == branch_id
            )

        # ----------------------------------------------------
        # If academic year selected
        # ----------------------------------------------------

        if academic_year_id:

            enrollment_rows = enrollment_rows.filter(
                StudentEnrollment.academic_year_id
                == academic_year_id
            )

        # ----------------------------------------------------
        # If class selected
        # ----------------------------------------------------

        if class_id:

            enrollment_rows = enrollment_rows.filter(
                StudentEnrollment.class_id
                == class_id
            )

        # ----------------------------------------------------
        # If section selected
        # ----------------------------------------------------

        if section_id:

            enrollment_rows = enrollment_rows.filter(
                StudentEnrollment.section_id
                == section_id
            )

        enrollment_rows = enrollment_rows.all()

        # ====================================================
        # BUILD STUDENT -> ENROLLMENTS MAP
        # ====================================================

        for row in enrollment_rows:

            sid = row.student_id

            if sid not in enrollment_map:

                enrollment_map[sid] = {
                    "branches": set(),
                    "classes": set(),
                    "sections": set(),
                }

            if row.branch_name:
                enrollment_map[sid][
                    "branches"
                ].add(
                    row.branch_name
                )

            if row.class_name:
                enrollment_map[sid][
                    "classes"
                ].add(
                    row.class_name
                )

            if row.section_name:
                enrollment_map[sid][
                    "sections"
                ].add(
                    row.section_name
                )

    # ========================================================
    # BUILD FINAL REPORT ROWS
    # ========================================================

    for row in pagination.items:

        total_attendance = int(
            row.total_attendance or 0
        )

        absent_count = int(
            row.absent_count or 0
        )

        present_count = int(
            row.present_count or 0
        )

        late_count = int(
            row.late_count or 0
        )

        excused_count = int(
            row.excused_count or 0
        )

        sick_count = int(
            row.sick_count or 0
        )

        leave_count = int(
            row.leave_count or 0
        )

        # ====================================================
        # ATTENDANCE RATE
        #
        # PRESENT + LATE are considered attended.
        # ====================================================

        if total_attendance > 0:

            attendance_rate = round(
                (
                    (
                        present_count
                        + late_count
                    )
                    / total_attendance
                ) * 100,
                1
            )

        else:

            attendance_rate = 0.0

        # ====================================================
        # ABSENCE RATE
        # ====================================================

        if total_attendance > 0:

            absence_rate = round(
                (
                    absent_count
                    / total_attendance
                ) * 100,
                1
            )

        else:

            absence_rate = 0.0

        # ====================================================
        # CLAMP PERCENTAGES
        # ====================================================

        attendance_rate = max(
            0.0,
            min(
                100.0,
                attendance_rate
            )
        )

        absence_rate = max(
            0.0,
            min(
                100.0,
                absence_rate
            )
        )

        # ====================================================
        # ENROLLMENT NAMES
        # ====================================================

        enrollment_data = enrollment_map.get(
            row.student_id,
            {
                "branches": set(),
                "classes": set(),
                "sections": set(),
            }
        )

        branch_names = sorted(
            enrollment_data["branches"]
        )

        class_names = sorted(
            enrollment_data["classes"]
        )

        section_names = sorted(
            enrollment_data["sections"]
        )

        branch_names_text = (
            ", ".join(branch_names)
            if branch_names
            else "—"
        )

        class_names_text = (
            ", ".join(class_names)
            if class_names
            else "—"
        )

        section_names_text = (
            ", ".join(section_names)
            if section_names
            else "—"
        )

        # ====================================================
        # APPEND REPORT OBJECT
        # ====================================================

        absent_reports.append({
            # ------------------------------------------------
            # Student
            # ------------------------------------------------

            "student_id": row.student_id,

            "student_name": (
                row.student_name
                or "Unknown Student"
            ),

            "admission_no": (
                row.admission_no
                or "—"
            ),

            "roll_no": (
                row.roll_no
                or "—"
            ),

            "student_photo": (
                row.student_photo
                if row.student_photo
                else None
            ),

            # ------------------------------------------------
            # Attendance totals
            # ------------------------------------------------

            "total_attendance": (
                total_attendance
            ),

            "absent_count": (
                absent_count
            ),

            "present_count": (
                present_count
            ),

            "late_count": (
                late_count
            ),

            "excused_count": (
                excused_count
            ),

            "sick_count": (
                sick_count
            ),

            "leave_count": (
                leave_count
            ),

            # ------------------------------------------------
            # Percentages
            # ------------------------------------------------

            "attendance_rate": (
                attendance_rate
            ),

            "absence_rate": (
                absence_rate
            ),

            # ------------------------------------------------
            # Enrollment display
            # ------------------------------------------------

            "branch_names": (
                branch_names_text
            ),

            "branch_name": (
                branch_names_text
            ),

            "class_names": (
                class_names_text
            ),

            "class_name": (
                class_names_text
            ),

            "section_names": (
                section_names_text
            ),

            "section_name": (
                section_names_text
            ),
        })

    # ========================================================
    # GLOBAL STATISTICS
    #
    # MUST USE THE SAME BASE FILTERS AND SAME ABSENT-STUDENT
    # LOGIC AS THE MAIN REPORT.
    # ========================================================

    stats_grouped = (
        db.session.query(

            Student.id.label(
                "student_id"
            ),

            func.count(
                AttendanceRecord.id
            ).label(
                "total_attendance"
            ),

            func.coalesce(
                func.sum(
                    absent_case
                ),
                0
            ).label(
                "absent_count"
            ),

            func.coalesce(
                func.sum(
                    present_case
                ),
                0
            ).label(
                "present_count"
            ),

            func.coalesce(
                func.sum(
                    late_case
                ),
                0
            ).label(
                "late_count"
            ),

            func.coalesce(
                func.sum(
                    excused_case
                ),
                0
            ).label(
                "excused_count"
            ),

            func.coalesce(
                func.sum(
                    sick_case
                ),
                0
            ).label(
                "sick_count"
            ),

            func.coalesce(
                func.sum(
                    leave_case
                ),
                0
            ).label(
                "leave_count"
            ),
        )

        .join(
            AttendanceSession,
            AttendanceSession.id
            == AttendanceRecord.attendance_session_id
        )

        .join(
            Student,
            Student.id
            == AttendanceRecord.student_id
        )

        .filter(
            *base_filters
        )

        .group_by(
            Student.id
        )

        .having(
            func.sum(
                absent_case
            ) > 0
        )

        .subquery()
    )

    # ========================================================
    # AGGREGATE GLOBAL STATISTICS
    # ========================================================

    stats_row = (
        db.session.query(

            func.coalesce(
                func.sum(
                    stats_grouped.c.total_attendance
                ),
                0
            ).label(
                "total_attendance"
            ),

            func.coalesce(
                func.sum(
                    stats_grouped.c.absent_count
                ),
                0
            ).label(
                "absent_count"
            ),

            func.coalesce(
                func.sum(
                    stats_grouped.c.present_count
                ),
                0
            ).label(
                "present_count"
            ),

            func.coalesce(
                func.sum(
                    stats_grouped.c.late_count
                ),
                0
            ).label(
                "late_count"
            ),

            func.coalesce(
                func.sum(
                    stats_grouped.c.excused_count
                ),
                0
            ).label(
                "excused_count"
            ),

            func.coalesce(
                func.sum(
                    stats_grouped.c.sick_count
                ),
                0
            ).label(
                "sick_count"
            ),

            func.coalesce(
                func.sum(
                    stats_grouped.c.leave_count
                ),
                0
            ).label(
                "leave_count"
            ),

            func.count(
                stats_grouped.c.student_id
            ).label(
                "total_students"
            ),
        )
        .first()
    )

    # ========================================================
    # GLOBAL STATS VALUES
    # ========================================================

    total_students = int(
        getattr(
            stats_row,
            "total_students",
            0
        ) or 0
    )

    total_attendance = int(
        getattr(
            stats_row,
            "total_attendance",
            0
        ) or 0
    )

    absent_count = int(
        getattr(
            stats_row,
            "absent_count",
            0
        ) or 0
    )

    present_count = int(
        getattr(
            stats_row,
            "present_count",
            0
        ) or 0
    )

    late_count = int(
        getattr(
            stats_row,
            "late_count",
            0
        ) or 0
    )

    excused_count = int(
        getattr(
            stats_row,
            "excused_count",
            0
        ) or 0
    )

    sick_count = int(
        getattr(
            stats_row,
            "sick_count",
            0
        ) or 0
    )

    leave_count = int(
        getattr(
            stats_row,
            "leave_count",
            0
        ) or 0
    )

    # ========================================================
    # GLOBAL ABSENCE RATE
    # ========================================================

    if total_attendance > 0:

        absent_rate = round(
            (
                absent_count
                / total_attendance
            ) * 100,
            1
        )

    else:

        absent_rate = 0.0

    # ========================================================
    # GLOBAL ATTENDANCE RATE
    # ========================================================

    if total_attendance > 0:

        attendance_rate = round(
            (
                (
                    present_count
                    + late_count
                )
                / total_attendance
            ) * 100,
            1
        )

    else:

        attendance_rate = 0.0

    # ========================================================
    # CLAMP GLOBAL RATES
    # ========================================================

    absent_rate = max(
        0.0,
        min(
            100.0,
            absent_rate
        )
    )

    attendance_rate = max(
        0.0,
        min(
            100.0,
            attendance_rate
        )
    )

    # ========================================================
    # ACADEMIC YEARS DROPDOWN
    # ========================================================

    academic_years_query = (
        db.session.query(AcademicYear)
    )

    if role != "superadmin":

        academic_years_query = (
            academic_years_query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
        )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # BRANCHES DROPDOWN
    # ========================================================

    branches_query = (
        db.session.query(Branch)
    )

    if role != "superadmin":

        branches_query = (
            branches_query
            .filter(
                Branch.institution_id
                == user_institution_id
            )
        )

    if role in {
        "branch_admin",
        "teacher",
    }:

        branches_query = (
            branches_query
            .filter(
                Branch.id
                == user_branch_id
            )
        )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES DROPDOWN
    # ========================================================

    classes_query = (
        db.session.query(Class)
    )

    if role != "superadmin":

        classes_query = (
            classes_query
            .filter(
                Class.institution_id
                == user_institution_id
            )
        )

    if branch_id:

        classes_query = (
            classes_query
            .filter(
                or_(
                    Class.branch_id
                    == branch_id,

                    Class.branch_id.is_(None)
                )
            )
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS DROPDOWN
    # ========================================================

    sections_query = (
        db.session.query(Section)
    )

    if role != "superadmin":

        sections_query = (
            sections_query
            .filter(
                Section.institution_id
                == user_institution_id
            )
        )

    if class_id:

        sections_query = (
            sections_query
            .filter(
                Section.class_id
                == class_id
            )
        )

    if branch_id:

        sections_query = (
            sections_query
            .filter(
                or_(
                    Section.branch_id
                    == branch_id,

                    Section.branch_id.is_(None)
                )
            )
        )

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECTS DROPDOWN
    # ========================================================

    subjects_query = (
        db.session.query(Subject)
    )

    if role != "superadmin":

        subjects_query = (
            subjects_query
            .filter(
                Subject.institution_id
                == user_institution_id
            )
        )

    if branch_id:

        subjects_query = (
            subjects_query
            .filter(
                or_(
                    Subject.branch_id
                    == branch_id,

                    Subject.branch_id.is_(None)
                )
            )
        )

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # TEACHERS DROPDOWN
    # ========================================================

    teachers_query = (
        db.session.query(Teacher)
    )

    if role != "superadmin":

        teachers_query = (
            teachers_query
            .filter(
                Teacher.institution_id
                == user_institution_id
            )
        )

    if branch_id:

        teachers_query = (
            teachers_query
            .filter(
                or_(
                    Teacher.branch_id
                    == branch_id,

                    Teacher.branch_id.is_(None)
                )
            )
        )

    # --------------------------------------------------------
    # Teacher should only see himself.
    # --------------------------------------------------------

    if role == "teacher":

        teachers_query = (
            teachers_query
            .filter(
                Teacher.id
                == teacher_scope_id
            )
        )

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # DATE RANGE LABEL
    # ========================================================

    if date_from and date_to:

        if date_from == date_to:

            date_range_label = (
                date_from.strftime("%d %b %Y")
            )

        else:

            date_range_label = (
                f"{date_from.strftime('%d %b %Y')}"
                f" - "
                f"{date_to.strftime('%d %b %Y')}"
            )

    elif date_from:

        date_range_label = (
            f"From "
            f"{date_from.strftime('%d %b %Y')}"
        )

    elif date_to:

        date_range_label = (
            f"Until "
            f"{date_to.strftime('%d %b %Y')}"
        )

    else:

        date_range_label = "All dates"

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/attendance/student_absent_report.html",

        # ----------------------------------------------------
        # REPORT DATA
        # ----------------------------------------------------

        absent_reports=absent_reports,
        user=current_user,

        # Alias in case template/JS uses another name
        absent_records=absent_reports,

        # ----------------------------------------------------
        # PAGINATION
        # ----------------------------------------------------

        pagination=pagination,

        page=page,

        per_page=per_page,

        # ----------------------------------------------------
        # GLOBAL STATS
        # ----------------------------------------------------

        total_students=total_students,

        total_attendance=total_attendance,

        absent_count=absent_count,

        present_count=present_count,

        late_count=late_count,

        excused_count=excused_count,

        sick_count=sick_count,

        leave_count=leave_count,

        absent_rate=absent_rate,

        attendance_rate=attendance_rate,

        # ----------------------------------------------------
        # DROPDOWNS
        # ----------------------------------------------------

        academic_years=academic_years,

        branches=branches,

        classes=classes,

        sections=sections,

        subjects=subjects,

        teachers=teachers,

        # ----------------------------------------------------
        # FILTER VALUES
        # ----------------------------------------------------

        search=search,

        academic_year_id=academic_year_id,

        branch_id=branch_id,

        class_id=class_id,

        section_id=section_id,

        subject_id=subject_id,

        teacher_id=teacher_id,

        date_from=(
            date_from.isoformat()
            if date_from
            else ""
        ),

        date_to=(
            date_to.isoformat()
            if date_to
            else ""
        ),

        # ----------------------------------------------------
        # DATE
        # ----------------------------------------------------

        today=today.isoformat(),

        date_range_label=date_range_label,

        # ----------------------------------------------------
        # REPORT STATUS
        # ----------------------------------------------------

        status="absent",

        # ----------------------------------------------------
        # ROLE
        # ----------------------------------------------------

        role=role,
    )






# ============================================================
# EXAM RESULTS
# ============================================================

@bp.route(
    "/exam-results",
    methods=["GET"]
)
@login_required
def exam_results():

    # ========================================================
    # SECURITY
    # ========================================================

    role = str(
        getattr(current_user, "role", "") or ""
    ).lower().strip()

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER INSTITUTION
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # SUPERADMIN
    # ========================================================
    #
    # Superadmin can work with all institutions.
    #
    # school_admin:
    #   institution only
    #
    # branch_admin:
    #   institution + branch only
    #
    # ========================================================

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    exam_id = request.args.get(
        "exam_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    term_id = request.args.get(
        "term_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    result_status = (
        request.args.get(
            "result_status",
            ""
        )
        .strip()
        .lower()
    )

    status = (
        request.args.get(
            "status",
            ""
        )
        .strip()
        .lower()
    )

    search = (
        request.args.get(
            "search",
            ""
        )
        .strip()
    )

    # ========================================================
    # NORMALIZE EMPTY VALUES
    # ========================================================

    if result_status not in {
        "",
        "pass",
        "fail",
        "incomplete",
    }:
        result_status = ""

    if status not in {
        "",
        "draft",
        "submitted",
        "approved",
        "published",
    }:
        status = ""

    # ========================================================
    # INSTITUTION SECURITY
    # ========================================================

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        institution_id = current_institution_id

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        institution_id = current_institution_id
        branch_id = current_branch_id

    elif role == "superadmin":

        # ----------------------------------------------------
        # Superadmin can select institution.
        # ----------------------------------------------------

        if institution_id:

            selected_institution = (
                Institution.query
                .filter(
                    Institution.id == institution_id
                )
                .first()
            )

            if not selected_institution:
                abort(404)

    # ========================================================
    # BRANCH SECURITY
    # ========================================================

    if institution_id and branch_id:

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id,
                Branch.institution_id == institution_id
            )
            .first()
        )

        if not branch:
            abort(404)

    # ========================================================
    # BASE RESULT QUERY
    # ========================================================

    query = (
        StudentResult.query
        .join(
            Student,
            Student.id == StudentResult.student_id
        )
        .filter(
            StudentResult.institution_id
            == institution_id
        )
    )

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if branch_id:

        query = query.filter(
            StudentResult.branch_id == branch_id
        )

    # ========================================================
    # EXAM
    # ========================================================

    if exam_id:

        query = query.filter(
            StudentResult.exam_id == exam_id
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:

        query = query.filter(
            StudentResult.academic_year_id
            == academic_year_id
        )

    # ========================================================
    # TERM
    # ========================================================

    if term_id:

        query = query.filter(
            StudentResult.term_id == term_id
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    if program_id:

        query = query.filter(
            StudentResult.program_id == program_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:

        query = query.filter(
            StudentResult.class_id == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        query = query.filter(
            StudentResult.section_id == section_id
        )

    # ========================================================
    # RESULT STATUS
    # ========================================================

    if result_status:

        query = query.filter(
            db.func.lower(
                StudentResult.result_status
            ) == result_status
        )

    # ========================================================
    # WORKFLOW STATUS
    # ========================================================

    if status:

        query = query.filter(
            db.func.lower(
                StudentResult.status
            ) == status
        )

    # ========================================================
    # STUDENT SEARCH
    # ========================================================

    if search:

        search_pattern = f"%{search}%"

        query = query.filter(
            db.or_(

                Student.full_name.ilike(
                    search_pattern
                ),

                Student.admission_no.ilike(
                    search_pattern
                )
            )
        )

    # ========================================================
    # SUMMARY
    # ========================================================

    total_results = query.count()

    total_pass = (
        query
        .filter(
            db.func.lower(
                StudentResult.result_status
            ) == "pass"
        )
        .count()
    )

    total_fail = (
        query
        .filter(
            db.func.lower(
                StudentResult.result_status
            ) == "fail"
        )
        .count()
    )

    total_incomplete = (
        query
        .filter(
            db.func.lower(
                StudentResult.result_status
            ) == "incomplete"
        )
        .count()
    )

    total_published = (
        query
        .filter(
            db.func.lower(
                StudentResult.status
            ) == "published"
        )
        .count()
    )

    total_approved = (
        query
        .filter(
            db.func.lower(
                StudentResult.status
            ) == "approved"
        )
        .count()
    )

    total_draft = (
        query
        .filter(
            db.func.lower(
                StudentResult.status
            ) == "draft"
        )
        .count()
    )

    # ========================================================
    # AVERAGE PERCENTAGE
    # ========================================================

    average_percentage = (
        db.session.query(
            db.func.avg(
                StudentResult.percentage
            )
        )
        .filter(
            StudentResult.institution_id
            == institution_id
        )
    )

    if branch_id:

        average_percentage = average_percentage.filter(
            StudentResult.branch_id == branch_id
        )

    if exam_id:

        average_percentage = average_percentage.filter(
            StudentResult.exam_id == exam_id
        )

    if academic_year_id:

        average_percentage = average_percentage.filter(
            StudentResult.academic_year_id
            == academic_year_id
        )

    if term_id:

        average_percentage = average_percentage.filter(
            StudentResult.term_id == term_id
        )

    if program_id:

        average_percentage = average_percentage.filter(
            StudentResult.program_id == program_id
        )

    if class_id:

        average_percentage = average_percentage.filter(
            StudentResult.class_id == class_id
        )

    if section_id:

        average_percentage = average_percentage.filter(
            StudentResult.section_id == section_id
        )

    if result_status:

        average_percentage = average_percentage.filter(
            db.func.lower(
                StudentResult.result_status
            ) == result_status
        )

    if status:

        average_percentage = average_percentage.filter(
            db.func.lower(
                StudentResult.status
            ) == status
        )

    average_percentage = (
        average_percentage
        .scalar()
    )

    average_percentage = to_decimal(
        average_percentage
    ).quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    if per_page not in {
        10,
        25,
        50,
        100,
    }:
        per_page = 25

    pagination = (
        query
        .options(
            joinedload(
                StudentResult.student
            ),

            joinedload(
                StudentResult.exam
            ),

            joinedload(
                StudentResult.institution
            ),

            joinedload(
                StudentResult.branch
            ),

            joinedload(
                StudentResult.program
            ),

            joinedload(
                StudentResult.academic_year
            ),

            joinedload(
                StudentResult.term
            ),

            joinedload(
                StudentResult.class_
            ),

            joinedload(
                StudentResult.section
            )
        )
        .order_by(

            StudentResult.percentage.desc(),

            StudentResult.gpa.desc(),

            StudentResult.student_id.asc(),

            StudentResult.id.asc()
        )
        .paginate(
            page=page,
            per_page=per_page,
            error_out=False
        )
    )

    results = pagination.items

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institutions = []

    if role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        institution = (
            Institution.query
            .filter(
                Institution.id
                == current_institution_id
            )
            .first()
        )

        if institution:
            institutions = [institution]

    # ========================================================
    # BRANCHES
    # ========================================================

    branches_query = Branch.query

    if institution_id:

        branches_query = branches_query.filter(
            Branch.institution_id
            == institution_id
        )

    if role == "branch_admin":

        branches_query = branches_query.filter(
            Branch.id == current_branch_id
        )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # EXAMS
    # ========================================================

    exams_query = Exam.query

    if institution_id:

        exams_query = exams_query.filter(
            Exam.institution_id
            == institution_id
        )

    if branch_id:

        exams_query = exams_query.filter(
            Exam.branch_id == branch_id
        )

    if academic_year_id:

        exams_query = exams_query.filter(
            Exam.academic_year_id
            == academic_year_id
        )

    if program_id:

        exams_query = exams_query.filter(
            Exam.program_id == program_id
        )

    exams = (
        exams_query
        .order_by(
            Exam.id.desc()
        )
        .all()
    )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_years_query = AcademicYear.query

    if institution_id:

        academic_years_query = (
            academic_years_query
            .filter(
                AcademicYear.institution_id
                == institution_id
            )
        )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # TERMS
    # ========================================================

    terms_query = Term.query

    if institution_id:

        terms_query = terms_query.filter(
            Term.institution_id
            == institution_id
        )

    if academic_year_id:

        terms_query = terms_query.filter(
            Term.academic_year_id
            == academic_year_id
        )

    terms = (
        terms_query
        .order_by(
            Term.id.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    programs_query = Program.query

    if institution_id:

        programs_query = programs_query.filter(
            Program.institution_id
            == institution_id
        )

    if branch_id:

        programs_query = programs_query.filter(
            db.or_(
                Program.branch_id == branch_id,
                Program.branch_id.is_(None)
            )
        )

    programs = (
        programs_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    # ========================================================

    classes_query = Class.query

    if institution_id:

        classes_query = classes_query.filter(
            Class.institution_id
            == institution_id
        )

    if branch_id:

        classes_query = classes_query.filter(
            Class.branch_id == branch_id
        )

    if program_id:

        classes_query = classes_query.filter(
            Class.program_id == program_id
        )

    if academic_year_id:

        classes_query = classes_query.filter(
            Class.academic_year_id
            == academic_year_id
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections_query = Section.query

    if institution_id:

        sections_query = sections_query.filter(
            Section.institution_id
            == institution_id
        )

    if branch_id:

        sections_query = sections_query.filter(
            Section.branch_id == branch_id
        )

    if class_id:

        sections_query = sections_query.filter(
            Section.class_id == class_id
        )

    if academic_year_id:

        sections_query = sections_query.filter(
            Section.academic_year_id
            == academic_year_id
        )

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/exam_results.html",

        # ----------------------------------------------------
        # RESULTS
        # ----------------------------------------------------

        results=results,

        pagination=pagination,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        exams=exams,

        academic_years=academic_years,

        terms=terms,

        programs=programs,

        classes=classes,

        sections=sections,

        # ----------------------------------------------------
        # CURRENT FILTERS
        # ----------------------------------------------------

        institution_id=institution_id,

        branch_id=branch_id,

        exam_id=exam_id,

        academic_year_id=academic_year_id,

        term_id=term_id,

        program_id=program_id,

        class_id=class_id,

        section_id=section_id,

        result_status=result_status,

        status=status,

        search=search,

        page=page,

        per_page=per_page,

        # ----------------------------------------------------
        # SUMMARY
        # ----------------------------------------------------

        total_results=total_results,

        total_pass=total_pass,

        total_fail=total_fail,

        total_incomplete=total_incomplete,

        total_published=total_published,

        total_approved=total_approved,

        total_draft=total_draft,

        average_percentage=average_percentage,

        # ----------------------------------------------------
        # CURRENT USER
        # ----------------------------------------------------

        user=current_user
    )


# ============================================================
# DELETE EXAM RESULT
# PostgreSQL / Neon
# ============================================================

@bp.route(
    "/exam-results/<int:result_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_result(result_id):

    # ========================================================
    # SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    # --------------------------------------------------------
    # Support Enum role
    # --------------------------------------------------------

    if hasattr(role, "value"):
        role = role.value

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # LOAD STUDENT RESULT
    # ========================================================

    result = (
        StudentResult.query
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    if not result:

        flash(
            "Exam result was not found.",
            "error"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # SCOPE CHECK
    # ========================================================

    if role == "superadmin":

        # ----------------------------------------------------
        # SUPERADMIN
        # Can manage all results.
        # ----------------------------------------------------

        pass

    elif role == "school_admin":

        # ----------------------------------------------------
        # SCHOOL ADMIN
        # Institution scope.
        # ----------------------------------------------------

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not user_institution_id:
            abort(403)

        if (
            result.institution_id
            != user_institution_id
        ):
            abort(403)

    elif role == "branch_admin":

        # ----------------------------------------------------
        # BRANCH ADMIN
        # Institution + branch scope.
        # ----------------------------------------------------

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        user_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not user_institution_id
            or not user_branch_id
        ):
            abort(403)

        if (
            result.institution_id
            != user_institution_id
            or result.branch_id
            != user_branch_id
        ):
            abort(403)

    # ========================================================
    # SAVE REQUIRED IDs
    # ========================================================

    exam_id = result.exam_id
    student_id = result.student_id

    # ========================================================
    # STUDENT NAME
    # ========================================================

    student_name = "Student"

    student = getattr(
        result,
        "student",
        None
    )

    if student:

        student_name = (
            getattr(
                student,
                "full_name",
                None
            )
            or getattr(
                student,
                "name",
                None
            )
            or "Student"
        )

    # ========================================================
    # EXAM NAME
    # ========================================================

    exam_name = "Exam"

    exam = getattr(
        result,
        "exam",
        None
    )

    if exam:

        exam_name = (
            getattr(
                exam,
                "name",
                None
            )
            or getattr(
                exam,
                "title",
                None
            )
            or getattr(
                exam,
                "code",
                None
            )
            or "Exam"
        )

    # ========================================================
    # DELETE
    # ========================================================

    try:

        # ====================================================
        # STEP 1
        # GET EXAM SUBJECT IDs
        #
        # IMPORTANT:
        #
        # We are ONLY reading ExamSubject.
        #
        # NOTHING is deleted from ExamSubject.
        # ====================================================

        exam_subject_rows = (
            db.session.query(
                ExamSubject.id
            )
            .filter(
                ExamSubject.exam_id == exam_id
            )
            .all()
        )

        exam_subject_ids = [
            row[0]
            for row in exam_subject_rows
        ]

        # ====================================================
        # STEP 2
        # DELETE MARKS
        #
        # ONLY:
        #
        #   student_id = this student
        #
        #   AND
        #
        #   exam_subject_id belongs to this exam
        #
        # ====================================================

        deleted_marks = 0

        if exam_subject_ids:

            deleted_marks = (
                Mark.query
                .filter(
                    Mark.student_id == student_id,
                    Mark.exam_subject_id.in_(
                        exam_subject_ids
                    )
                )
                .delete(
                    synchronize_session=False
                )
            )

        # ====================================================
        # STEP 3
        # DELETE STUDENT RESULT
        # ====================================================

        db.session.delete(result)

        # ====================================================
        # STEP 4
        # COMMIT
        # ====================================================

        db.session.commit()

        # ====================================================
        # SUCCESS MESSAGE
        # ====================================================

        flash(
            f"Exam result for {student_name} "
            f"({exam_name}) was deleted successfully. "
            f"{deleted_marks} subject mark(s) were also deleted.",
            "success"
        )

    except Exception as exc:

        # ====================================================
        # ROLLBACK
        # ====================================================

        db.session.rollback()

        current_app.logger.exception(
            "DELETE EXAM RESULT FAILED | "
            "result_id=%s | exam_id=%s | student_id=%s",
            result_id,
            exam_id,
            student_id
        )

        # ====================================================
        # ERROR MESSAGE
        # ====================================================

        flash(
            "Unable to delete the exam result "
            "and related subject marks. "
            "No changes were saved.",
            "error"
        )

    # ========================================================
    # RETURN
    # ========================================================

    return redirect(
        url_for("main.exam_results")
    )



# ============================================================
# DELETE EXAM MARK + STUDENT RESULT
 #============================================================
@bp.route(
    "/exam-results/marks/<int:mark_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_mark(mark_id):

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(current_user, "role", None)
    role = getattr(role, "value", role)

    role = (
        str(role).strip().lower()
        if role is not None
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    current_app.logger.info(
        "DELETE MARK REQUEST | mark_id=%s | role=%s",
        mark_id,
        role
    )

    # ========================================================
    # VALIDATE MARK ID
    # ========================================================

    if mark_id <= 0:
        flash(
            "Invalid Mark ID.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.exam_results")
        )

    # ========================================================
    # LOAD MARK
    # ========================================================

    mark = db.session.get(Mark, mark_id)

    if mark is None:

        current_app.logger.warning(
            "DELETE MARK FAILED | Mark not found | mark_id=%s",
            mark_id
        )

        flash(
            f"The mark was not found. Mark ID: {mark_id}",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.exam_results")
        )

    # ========================================================
    # SAVE ORIGINAL VALUES
    # ========================================================

    student_id = mark.student_id
    exam_subject_id = mark.exam_subject_id
    old_mark_value = mark.marks_obtained

    # ========================================================
    # LOAD EXAM SUBJECT
    # ========================================================

    exam_subject = db.session.get(
        ExamSubject,
        exam_subject_id
    )

    if exam_subject is None:

        flash(
            "The exam subject connected to this mark was not found.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.exam_results")
        )

    # ========================================================
    # LOAD EXAM
    # ========================================================

    exam_id = exam_subject.exam_id

    exam = db.session.get(
        Exam,
        exam_id
    )

    if exam is None:

        flash(
            "The examination connected to this mark was not found.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.exam_results")
        )

    # ========================================================
    # LOAD STUDENT
    # ========================================================

    student = db.session.get(
        Student,
        student_id
    )

    if student is None:

        flash(
            "The student connected to this mark was not found.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.exam_results")
        )

    # ========================================================
    # INSTITUTION / BRANCH
    # ========================================================

    institution_id = getattr(
        exam_subject,
        "institution_id",
        None
    )

    if institution_id is None:
        institution_id = getattr(
            exam,
            "institution_id",
            None
        )

    branch_id = getattr(
        exam_subject,
        "branch_id",
        None
    )

    if branch_id is None:
        branch_id = getattr(
            exam,
            "branch_id",
            None
        )

    # ========================================================
    # ROLE SCOPE
    # ========================================================

    if role == "school_admin":

        if (
            getattr(
                current_user,
                "institution_id",
                None
            )
            != institution_id
        ):
            abort(403)

    elif role == "branch_admin":

        if (
            getattr(
                current_user,
                "institution_id",
                None
            )
            != institution_id
        ):
            abort(403)

        if (
            getattr(
                current_user,
                "branch_id",
                None
            )
            != branch_id
        ):
            abort(403)

    elif role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if teacher is None:
            abort(403)

        if (
            getattr(
                teacher,
                "institution_id",
                None
            )
            != institution_id
        ):
            abort(403)

        if (
            getattr(
                teacher,
                "branch_id",
                None
            )
            != branch_id
        ):
            abort(403)

    # ========================================================
    # LOAD EXISTING STUDENT RESULT
    #
    # IMPORTANT:
    # NEVER DELETE IT.
    # ========================================================

    result_query = StudentResult.query.filter(
        StudentResult.exam_id == exam_id,
        StudentResult.student_id == student_id,
    )

    if institution_id is not None:

        result_query = result_query.filter(
            StudentResult.institution_id == institution_id
        )

    if branch_id is not None:

        result_query = result_query.filter(
            StudentResult.branch_id == branch_id
        )

    student_result = (
        result_query
        .order_by(StudentResult.id.desc())
        .first()
    )

    if student_result is None:

        current_app.logger.warning(
            "DELETE MARK | StudentResult does not exist | "
            "student_id=%s | exam_id=%s",
            student_id,
            exam_id
        )

        # We can still delete the mark.
        # There is simply no result row to recalculate.

    # ========================================================
    # DELETE + RECALCULATE
    # ========================================================

    try:

        current_app.logger.info(
            "DELETE MARK START | "
            "mark_id=%s | "
            "student_id=%s | "
            "exam_id=%s | "
            "exam_subject_id=%s | "
            "old_mark=%s",
            mark.id,
            student_id,
            exam_id,
            exam_subject_id,
            old_mark_value
        )

        # ====================================================
        # DELETE ONLY THIS MARK
        # ====================================================

        db.session.delete(mark)

        db.session.flush()

        current_app.logger.info(
            "MARK DELETED FROM SESSION | "
            "mark_id=%s",
            mark_id
        )

        # ====================================================
        # IMPORTANT
        #
        # DO NOT CALL calculate_student_result() HERE.
        #
        # The existing calculator is what is throwing the
        # exception in your current implementation.
        #
        # We recalculate the existing StudentResult directly.
        # ====================================================

        if student_result is not None:

            # =================================================
            # FIND EXAM SUBJECTS FOR THIS STUDENT
            #
            # Priority:
            #
            # SECTION
            #     ↓
            # CLASS
            #     ↓
            # GENERAL
            #
            # Branch-specific is preferred over shared.
            # =================================================

            student_class_id = getattr(
                student_result,
                "class_id",
                None
            )

            student_section_id = getattr(
                student_result,
                "section_id",
                None
            )

            exam_subjects = (
                ExamSubject.query
                .filter(
                    ExamSubject.exam_id == exam_id,
                    ExamSubject.status == "active",
                )
                .order_by(
                    ExamSubject.id.asc()
                )
                .all()
            )

            # =================================================
            # SELECT ONE EXAM SUBJECT PER SUBJECT
            # =================================================

            selected_subjects = {}

            for es in exam_subjects:

                # ---------------------------------------------
                # CLASS FILTER
                # ---------------------------------------------

                es_class_id = getattr(
                    es,
                    "class_id",
                    None
                )

                if (
                    es_class_id is not None
                    and student_class_id is not None
                    and es_class_id != student_class_id
                ):
                    continue

                # ---------------------------------------------
                # If ExamSubject is class-specific but result
                # has no class, do not use it.
                # ---------------------------------------------

                if (
                    es_class_id is not None
                    and student_class_id is None
                ):
                    continue

                # ---------------------------------------------
                # SECTION FILTER
                # ---------------------------------------------

                es_section_id = getattr(
                    es,
                    "section_id",
                    None
                )

                if (
                    es_section_id is not None
                    and student_section_id is not None
                    and es_section_id != student_section_id
                ):
                    continue

                if (
                    es_section_id is not None
                    and student_section_id is None
                ):
                    continue

                # ---------------------------------------------
                # SUBJECT ID
                # ---------------------------------------------

                subject_id = getattr(
                    es,
                    "subject_id",
                    None
                )

                if subject_id is None:
                    continue

                # ---------------------------------------------
                # PRIORITY
                #
                # section = 4
                # class   = 3
                # general = 1
                # ---------------------------------------------

                if es_section_id is not None:
                    priority = 4

                elif es_class_id is not None:
                    priority = 3

                else:
                    priority = 1

                # ---------------------------------------------
                # Keep highest priority subject.
                # ---------------------------------------------

                existing = selected_subjects.get(
                    subject_id
                )

                if existing is None:

                    selected_subjects[subject_id] = (
                        priority,
                        es
                    )

                else:

                    old_priority, old_es = existing

                    if priority > old_priority:

                        selected_subjects[subject_id] = (
                            priority,
                            es
                        )

                    elif (
                        priority == old_priority
                        and es.id < old_es.id
                    ):

                        selected_subjects[subject_id] = (
                            priority,
                            es
                        )

            # =================================================
            # SORT SELECTED SUBJECTS
            # =================================================

            selected_exam_subjects = [
                item[1]
                for item in selected_subjects.values()
            ]

            selected_exam_subjects.sort(
                key=lambda x: (
                    getattr(
                        x,
                        "display_order",
                        None
                    )
                    is None,
                    getattr(
                        x,
                        "display_order",
                        0
                    ) or 0,
                    x.id
                )
            )

            # =================================================
            # LOAD REMAINING MARKS
            # =================================================

            remaining_marks = (
                Mark.query
                .filter(
                    Mark.student_id == student_id,
                    Mark.exam_subject_id.in_(
                        [
                            es.id
                            for es in selected_exam_subjects
                        ]
                    )
                )
                .all()
            )

            mark_map = {
                m.exam_subject_id: m
                for m in remaining_marks
            }

            # =================================================
            # CALCULATE RESULT
            # =================================================

            total_marks = 0.0
            total_max_marks = 0.0

            subjects_total = 0
            subjects_completed = 0
            subjects_missing = 0
            subjects_failed = 0
            subjects_passed = 0

            incomplete = False
            failed = False

            for es in selected_exam_subjects:

                max_marks = float(
                    getattr(
                        es,
                        "max_marks",
                        100
                    )
                    or 100
                )

                pass_marks = float(
                    getattr(
                        es,
                        "pass_marks",
                        50
                    )
                    or 50
                )

                subjects_total += 1

                total_max_marks += max_marks

                mark_row = mark_map.get(es.id)

                # =============================================
                # MISSING MARK
                # =============================================

                if mark_row is None:

                    subjects_missing += 1
                    incomplete = True

                    continue

                # =============================================
                # ABSENT
                # =============================================

                if getattr(
                    mark_row,
                    "is_absent",
                    False
                ):

                    subjects_missing += 1
                    incomplete = True

                    continue

                # =============================================
                # EXEMPTED
                # =============================================

                if getattr(
                    mark_row,
                    "is_exempted",
                    False
                ):

                    subjects_completed += 1

                    continue

                # =============================================
                # MARK VALUE
                #
                # 0 IS VALID.
                # =============================================

                value = mark_row.marks_obtained

                if value is None:

                    subjects_missing += 1
                    incomplete = True

                    continue

                value = float(value)

                # =============================================
                # ADD MARK
                # =============================================

                total_marks += value
                subjects_completed += 1

                # =============================================
                # PASS / FAIL
                # =============================================

                if value < pass_marks:

                    subjects_failed += 1
                    failed = True

                else:

                    subjects_passed += 1

            # =================================================
            # PERCENTAGE
            # =================================================

            if total_max_marks > 0:

                percentage = (
                    total_marks
                    / total_max_marks
                ) * 100.0

            else:

                percentage = 0.0

            # =================================================
            # AVERAGE
            # =================================================

            if subjects_completed > 0:

                average = (
                    total_marks
                    / subjects_completed
                )

            else:

                average = 0.0

            # =================================================
            # RESULT STATUS
            #
            # MISSING SUBJECT => INCOMPLETE
            # ANY FAILED       => FAIL
            # OTHERWISE         => PASS
            # =================================================

            if incomplete:

                result_status = "INCOMPLETE"

            elif failed:

                result_status = "FAIL"

            else:

                result_status = "PASS"

            # =================================================
            # GRADE
            # =================================================

            if incomplete:

                grade = "N/A"

            elif percentage >= 90:

                grade = "A+"

            elif percentage >= 80:

                grade = "A"

            elif percentage >= 75:

                grade = "B+"

            elif percentage >= 70:

                grade = "B"

            elif percentage >= 65:

                grade = "C+"

            elif percentage >= 60:

                grade = "C"

            elif percentage >= 50:

                grade = "D"

            else:

                grade = "F"

            # =================================================
            # UPDATE EXISTING RESULT
            #
            # NEVER DELETE StudentResult.
            # =================================================

            student_result.total_marks = total_marks

            student_result.total_max_marks = (
                total_max_marks
            )

            student_result.percentage = percentage

            student_result.average = average

            student_result.subjects_total = (
                subjects_total
            )

            student_result.subjects_completed = (
                subjects_completed
            )

            student_result.subjects_missing = (
                subjects_missing
            )

            student_result.subjects_failed = (
                subjects_failed
            )

            student_result.subjects_passed = (
                subjects_passed
            )

            student_result.grade = grade

            student_result.result_status = (
                result_status
            )

            student_result.status = "draft"

            student_result.calculated_at = (
                datetime.utcnow()
            )

            current_app.logger.info(
                "STUDENT RESULT RECALCULATED | "
                "result_id=%s | "
                "student_id=%s | "
                "exam_id=%s | "
                "total=%s | "
                "max=%s | "
                "percentage=%s | "
                "missing=%s | "
                "failed=%s | "
                "status=%s",
                student_result.id,
                student_id,
                exam_id,
                total_marks,
                total_max_marks,
                percentage,
                subjects_missing,
                subjects_failed,
                result_status
            )

        # ====================================================
        # COMMIT EVERYTHING
        # ====================================================

        db.session.commit()

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "DELETE MARK FAILED | "
            "mark_id=%s | "
            "student_id=%s | "
            "exam_id=%s | "
            "exam_subject_id=%s",
            mark_id,
            student_id,
            exam_id,
            exam_subject_id
        )

        flash(
            "Unable to delete the mark and recalculate "
            "the student's result. Please check the server "
            "log for the exact error.",
            "danger"
        )

        return redirect(
            request.referrer
            or url_for("main.exam_results")
        )

    # ========================================================
    # SUBJECT NAME
    # ========================================================

    subject = getattr(
        exam_subject,
        "subject",
        None
    )

    subject_name = (
        getattr(
            subject,
            "name",
            None
        )
        or "Subject"
    )

    # ========================================================
    # STUDENT NAME
    # ========================================================

    student_name = (
        getattr(
            student,
            "full_name",
            None
        )
        or getattr(
            student,
            "name",
            None
        )
        or "Student"
    )

    # ========================================================
    # SUCCESS
    # ========================================================

    current_app.logger.info(
        "MARK DELETED SUCCESSFULLY | "
        "mark_id=%s | "
        "student_id=%s | "
        "exam_id=%s | "
        "exam_subject_id=%s | "
        "old_mark=%s | "
        "result_id=%s",
        mark_id,
        student_id,
        exam_id,
        exam_subject_id,
        old_mark_value,
        (
            student_result.id
            if student_result
            else None
        )
    )

    flash(
        f"{subject_name} mark for {student_name} "
        "was deleted successfully. "
        "The student result was recalculated.",
        "success"
    )

    return redirect(
        request.referrer
        or url_for("main.exam_results")
    )



# ============================================================
# EDIT EXAM RESULT
# ============================================================

@bp.route(
    "/exam-results/<int:result_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam_result(result_id):

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # LOAD RESULT
    # ========================================================

    result = (
        StudentResult.query
        .options(
            db.joinedload(
                StudentResult.student
            ),
            db.joinedload(
                StudentResult.exam
            ),
            db.joinedload(
                StudentResult.institution
            ),
            db.joinedload(
                StudentResult.branch
            ),
            db.joinedload(
                StudentResult.program
            ),
            db.joinedload(
                StudentResult.academic_year
            ),
            db.joinedload(
                StudentResult.term
            ),
            db.joinedload(
                StudentResult.section
            ),
        )
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    # ========================================================
    # RESULT NOT FOUND
    # ========================================================

    if not result:

        flash(
            "Exam result was not found.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    # ========================================================
    # BASIC IDS
    # ========================================================

    exam_id = getattr(
        result,
        "exam_id",
        None
    )

    student_id = getattr(
        result,
        "student_id",
        None
    )

    institution_id = getattr(
        result,
        "institution_id",
        None
    )

    branch_id = getattr(
        result,
        "branch_id",
        None
    )

    program_id = getattr(
        result,
        "program_id",
        None
    )

    # ========================================================
    # BASIC VALIDATION
    # ========================================================

    if not exam_id:

        flash(
            "This result is not linked to an examination.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    if not student_id:

        flash(
            "This result is not linked to a student.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    if not institution_id:

        flash(
            "This result has no institution assigned.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    if not branch_id:

        flash(
            "This result has no branch assigned.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    # ========================================================
    # SCOPE SECURITY
    # ========================================================

    if role == "superadmin":

        pass

    elif role == "school_admin":

        current_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not current_institution_id:
            abort(403)

        if (
            result.institution_id
            != current_institution_id
        ):
            abort(403)

    elif role == "branch_admin":

        current_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        current_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        if (
            result.institution_id
            != current_institution_id
        ):
            abort(403)

        if (
            result.branch_id
            != current_branch_id
        ):
            abort(403)

    # ========================================================
    # LOAD EXAM
    # ========================================================

    exam = (
        Exam.query
        .filter(
            Exam.id == exam_id
        )
        .first()
    )

    if not exam:

        flash(
            "The examination linked to this result was not found.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    # ========================================================
    # EXAM SECURITY
    # ========================================================

    if (
        getattr(exam, "institution_id", None)
        and
        exam.institution_id != institution_id
    ):
        abort(403)

    if (
        getattr(exam, "branch_id", None)
        and
        exam.branch_id != branch_id
    ):
        abort(403)

    # ========================================================
    # STUDENT CLASS / SECTION
    #
    # Priority:
    #
    # 1. StudentResult.class_id
    # 2. StudentResult.section_id
    # 3. StudentEnrollment
    # ========================================================

    student_class_id = getattr(
        result,
        "class_id",
        None
    )

    student_section_id = getattr(
        result,
        "section_id",
        None
    )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    academic_year_id = getattr(
        result,
        "academic_year_id",
        None
    )

    if not academic_year_id:

        academic_year_id = getattr(
            exam,
            "academic_year_id",
            None
        )

    # ========================================================
    # FALLBACK: STUDENT ENROLLMENT
    # ========================================================

    enrollment = None

    try:

        enrollment_query = (
            StudentEnrollment.query
            .filter(
                StudentEnrollment.student_id
                == student_id
            )
        )

        if hasattr(
            StudentEnrollment,
            "institution_id"
        ):

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.institution_id
                    == institution_id
                )
            )

        if hasattr(
            StudentEnrollment,
            "branch_id"
        ):

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.branch_id
                    == branch_id
                )
            )

        if (
            academic_year_id
            and hasattr(
                StudentEnrollment,
                "academic_year_id"
            )
        ):

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.academic_year_id
                    == academic_year_id
                )
            )

        if (
            program_id
            and hasattr(
                StudentEnrollment,
                "program_id"
            )
        ):

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.program_id
                    == program_id
                )
            )

        # ----------------------------------------------------
        # If class is already known, prefer that class.
        # ----------------------------------------------------

        if (
            student_class_id
            and hasattr(
                StudentEnrollment,
                "class_id"
            )
        ):

            enrollment_query = (
                enrollment_query.filter(
                    StudentEnrollment.class_id
                    == student_class_id
                )
            )

        # ----------------------------------------------------
        # Prefer newest enrollment.
        # ----------------------------------------------------

        enrollment = (
            enrollment_query
            .order_by(
                StudentEnrollment.id.desc()
            )
            .first()
        )

    except Exception:

        current_app.logger.exception(
            "Enrollment lookup failed | "
            "result_id=%s | student_id=%s",
            result_id,
            student_id,
        )

    # ========================================================
    # APPLY ENROLLMENT FALLBACK
    # ========================================================

    if enrollment:

        if not student_class_id:

            student_class_id = getattr(
                enrollment,
                "class_id",
                None
            )

        if not student_section_id:

            student_section_id = getattr(
                enrollment,
                "section_id",
                None
            )

        if not program_id:

            program_id = getattr(
                enrollment,
                "program_id",
                None
            )

    # ========================================================
    # FINAL CLASS SAFETY
    # ========================================================

    if not student_class_id:

        flash(
            "The student's class could not be determined "
            "for this examination result. "
            "Subjects were not loaded to prevent incorrect "
            "class assignments.",
            "error"
        )

        return redirect(
            url_for(
                "main.view_exam_result",
                result_id=result.id
            )
        )

    # ========================================================
    # FINAL SECTION
    #
    # IMPORTANT:
    # section can legitimately be NULL.
    #
    # NULL means:
    # use class-level assignment.
    # ========================================================

    # ========================================================
    # BUILD SCOPED EXAM SUBJECT QUERY
    #
    # THIS IS THE MAIN DUPLICATE FIX.
    #
    # We explicitly require:
    #
    # exam
    # institution
    # branch
    # program
    # class
    #
    # before subject deduplication.
    # ========================================================

    exam_subject_query = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id == exam_id
        )
    )

    # ========================================================
    # INSTITUTION
    # ========================================================

    if hasattr(
        ExamSubject,
        "institution_id"
    ):

        exam_subject_query = (
            exam_subject_query.filter(
                ExamSubject.institution_id
                == institution_id
            )
        )

    # ========================================================
    # BRANCH
    # ========================================================

    if hasattr(
        ExamSubject,
        "branch_id"
    ):

        exam_subject_query = (
            exam_subject_query.filter(
                ExamSubject.branch_id
                == branch_id
            )
        )

    # ========================================================
    # PROGRAM
    #
    # IMPORTANT:
    # If the ExamSubject has program_id, we ONLY accept
    # this student's program.
    # ========================================================

    if hasattr(
        ExamSubject,
        "program_id"
    ):

        if program_id:

            exam_subject_query = (
                exam_subject_query.filter(
                    ExamSubject.program_id
                    == program_id
                )
            )

        else:

            # No student program = do not accidentally
            # load every program's subjects.
            exam_subject_query = (
                exam_subject_query.filter(
                    ExamSubject.program_id.is_(None)
                )
            )

    # ========================================================
    # CLASS
    #
    # THIS MUST BE A REAL SQL FILTER.
    #
    # We do NOT fetch all classes and filter in template.
    # ========================================================

    if hasattr(
        ExamSubject,
        "class_id"
    ):

        exam_subject_query = (
            exam_subject_query.filter(
                ExamSubject.class_id
                == student_class_id
            )
        )

    else:

        current_app.logger.error(
            "ExamSubject.class_id does not exist. "
            "Cannot safely scope exam subjects by class. "
            "result_id=%s | exam_id=%s | class_id=%s",
            result_id,
            exam_id,
            student_class_id,
        )

        flash(
            "Exam subject class assignment could not be "
            "verified safely.",
            "error"
        )

        return redirect(
            url_for(
                "main.view_exam_result",
                result_id=result.id
            )
        )

    # ========================================================
    # LOAD CANDIDATES
    # ========================================================

    scoped_exam_subjects = (
        exam_subject_query
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # SECTION FILTER + SUBJECT DEDUPLICATION
    #
    # RULE:
    #
    # Student section = KD21 Section A
    #
    # Candidate:
    #   English / KD21 / NULL
    #   English / KD21 / A
    #
    # Result:
    #   English / KD21 / A
    #
    # If student has NO section:
    #   only class-level assignment is accepted.
    # ========================================================

    subject_assignment_map = {}

    for exam_subject in scoped_exam_subjects:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )

        if not subject_id:
            continue

        assignment_section_id = getattr(
            exam_subject,
            "section_id",
            None
        )

        # ====================================================
        # SECTION MATCH
        # ====================================================

        if student_section_id is not None:

            # -----------------------------------------------
            # Student has section.
            #
            # Accept:
            #   exact section
            #   OR class-level NULL section
            # -----------------------------------------------

            if (
                assignment_section_id is not None
                and
                assignment_section_id
                != student_section_id
            ):
                continue

        else:

            # -----------------------------------------------
            # Student has no section.
            #
            # DO NOT show section-specific subjects.
            # -----------------------------------------------

            if assignment_section_id is not None:
                continue

        # ====================================================
        # PRIORITY
        #
        # Exact section > class-level
        # ====================================================

        existing = subject_assignment_map.get(
            subject_id
        )

        if existing is None:

            subject_assignment_map[
                subject_id
            ] = exam_subject

            continue

        existing_section_id = getattr(
            existing,
            "section_id",
            None
        )

        # ====================================================
        # NEW RECORD IS SECTION-SPECIFIC
        # ====================================================

        new_is_section_specific = (
            assignment_section_id is not None
            and
            assignment_section_id
            == student_section_id
        )

        # ====================================================
        # OLD RECORD IS CLASS-LEVEL
        # ====================================================

        old_is_class_level = (
            existing_section_id is None
        )

        if (
            new_is_section_specific
            and
            old_is_class_level
        ):

            subject_assignment_map[
                subject_id
            ] = exam_subject

            continue

        # ====================================================
        # BOTH ARE SECTION-SPECIFIC
        #
        # Keep lowest ID deterministically.
        # ====================================================

        if (
            new_is_section_specific
            and
            existing_section_id
            == student_section_id
        ):

            if (
                exam_subject.id
                <
                existing.id
            ):

                subject_assignment_map[
                    subject_id
                ] = exam_subject

            continue

        # ====================================================
        # BOTH ARE CLASS-LEVEL
        #
        # Keep lowest ID deterministically.
        # ====================================================

        if (
            assignment_section_id is None
            and
            existing_section_id is None
        ):

            if (
                exam_subject.id
                <
                existing.id
            ):

                subject_assignment_map[
                    subject_id
                ] = exam_subject

    # ========================================================
    # FINAL SUBJECT LIST
    # ========================================================

    exam_subjects = list(
        subject_assignment_map.values()
    )

    # ========================================================
    # FINAL SORT
    # ========================================================

    exam_subjects.sort(
        key=lambda item: (
            getattr(
                item,
                "display_order",
                None
            ) is None,

            getattr(
                item,
                "display_order",
                0
            ) or 0,

            item.id,
        )
    )

    # ========================================================
    # HARD SAFETY CHECK
    #
    # No subject may appear twice.
    # ========================================================

    seen_subject_ids = set()

    unique_exam_subjects = []

    for exam_subject in exam_subjects:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )

        if not subject_id:
            continue

        if subject_id in seen_subject_ids:
            continue

        seen_subject_ids.add(
            subject_id
        )

        unique_exam_subjects.append(
            exam_subject
        )

    exam_subjects = unique_exam_subjects

    # ========================================================
    # NO SUBJECTS
    # ========================================================

    if not exam_subjects:

        flash(
            "No examination subjects were assigned to "
            "this student's class/program.",
            "error"
        )

        return redirect(
            url_for(
                "main.view_exam_result",
                result_id=result.id
            )
        )

    # ========================================================
    # DEBUG LOG
    #
    # This will help you verify that KD20 is NOT being loaded
    # for a KD21 student.
    # ========================================================

    current_app.logger.info(
        "EDIT EXAM RESULT SUBJECT SCOPE | "
        "result_id=%s | "
        "exam_id=%s | "
        "student_id=%s | "
        "institution_id=%s | "
        "branch_id=%s | "
        "program_id=%s | "
        "class_id=%s | "
        "section_id=%s | "
        "subjects=%s",
        result_id,
        exam_id,
        student_id,
        institution_id,
        branch_id,
        program_id,
        student_class_id,
        student_section_id,
        [
            {
                "exam_subject_id": item.id,
                "subject_id": getattr(
                    item,
                    "subject_id",
                    None
                ),
                "class_id": getattr(
                    item,
                    "class_id",
                    None
                ),
                "section_id": getattr(
                    item,
                    "section_id",
                    None
                ),
            }
            for item in exam_subjects
        ],
    )

    # ========================================================
    # SUBJECT IDS
    # ========================================================

    exam_subject_ids = [
        item.id
        for item in exam_subjects
    ]

    # ========================================================
    # LOAD MARKS
    # ========================================================

    existing_marks = []

    if exam_subject_ids:

        existing_marks = (
            Mark.query
            .filter(
                Mark.student_id
                == student_id,

                Mark.exam_subject_id.in_(
                    exam_subject_ids
                )
            )
            .all()
        )

    # ========================================================
    # MARK MAP
    # ========================================================

    mark_map = {
        mark.exam_subject_id: mark
        for mark in existing_marks
    }

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        try:

            # =================================================
            # SECURITY:
            #
            # submitted ExamSubject IDs are NOT trusted.
            #
            # We process ONLY exam_subjects from the scoped
            # server-side list.
            # =================================================

            for exam_subject in exam_subjects:

                exam_subject_id = (
                    exam_subject.id
                )

                mark = mark_map.get(
                    exam_subject_id
                )

                # =============================================
                # FIELD NAMES
                # =============================================

                mark_field = (
                    f"mark_{exam_subject_id}"
                )

                absent_field = (
                    f"absent_{exam_subject_id}"
                )

                exempted_field = (
                    f"exempted_{exam_subject_id}"
                )

                remark_field = (
                    f"remark_{exam_subject_id}"
                )

                # =============================================
                # RAW MARK
                # =============================================

                raw_marks = request.form.get(
                    mark_field,
                    ""
                )

                raw_marks = (
                    raw_marks.strip()
                    if raw_marks
                    else ""
                )

                # =============================================
                # ABSENT
                # =============================================

                is_absent = (
                    request.form.get(
                        absent_field
                    )
                    == "1"
                )

                # =============================================
                # EXEMPTED
                # =============================================

                is_exempted = (
                    request.form.get(
                        exempted_field
                    )
                    == "1"
                )

                # =============================================
                # REMARK
                # =============================================

                subject_remark = (
                    request.form.get(
                        remark_field,
                        ""
                    )
                )

                subject_remark = (
                    subject_remark.strip()
                    if subject_remark
                    else ""
                )

                # =============================================
                # SUBJECT
                # =============================================

                subject = getattr(
                    exam_subject,
                    "subject",
                    None
                )

                subject_name = (
                    getattr(
                        subject,
                        "name",
                        None
                    )
                    or
                    getattr(
                        subject,
                        "title",
                        None
                    )
                    or
                    "Subject"
                )

                # =============================================
                # ABSENT + EXEMPTED
                # =============================================

                if (
                    is_absent
                    and
                    is_exempted
                ):

                    raise ValueError(
                        f"{subject_name}: "
                        "A subject cannot be both "
                        "absent and exempted."
                    )

                # =============================================
                # EMPTY
                #
                # Do NOT create zero.
                # Preserve existing mark.
                # =============================================

                if (
                    not raw_marks
                    and
                    not is_absent
                    and
                    not is_exempted
                ):
                    continue

                # =============================================
                # ABSENT
                # =============================================

                if is_absent:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=(
                                exam_subject_id
                            ),
                            student_id=student_id,
                            marks_obtained=None,
                            is_absent=True,
                            is_exempted=False,
                            remarks=(
                                subject_remark
                                or None
                            ),
                            status="submitted",
                            entered_by=None,
                        )

                        db.session.add(
                            mark
                        )

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None

                        mark.is_absent = True

                        mark.is_exempted = False

                        mark.remarks = (
                            subject_remark
                            or None
                        )

                        mark.status = (
                            "submitted"
                        )

                    continue

                # =============================================
                # EXEMPTED
                # =============================================

                if is_exempted:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=(
                                exam_subject_id
                            ),
                            student_id=student_id,
                            marks_obtained=None,
                            is_absent=False,
                            is_exempted=True,
                            remarks=(
                                subject_remark
                                or None
                            ),
                            status="submitted",
                            entered_by=None,
                        )

                        db.session.add(
                            mark
                        )

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None

                        mark.is_absent = False

                        mark.is_exempted = True

                        mark.remarks = (
                            subject_remark
                            or None
                        )

                        mark.status = (
                            "submitted"
                        )

                    continue

                # =============================================
                # NORMAL MARK
                # =============================================

                try:

                    marks = Decimal(
                        raw_marks
                    )

                except (
                    InvalidOperation,
                    ValueError,
                    TypeError
                ):

                    raise ValueError(
                        f"Invalid marks entered for "
                        f"{subject_name}."
                    )

                # =============================================
                # FINITE
                # =============================================

                if not marks.is_finite():

                    raise ValueError(
                        f"Invalid marks entered for "
                        f"{subject_name}."
                    )

                # =============================================
                # NEGATIVE
                # =============================================

                if marks < Decimal("0"):

                    raise ValueError(
                        f"Marks cannot be negative for "
                        f"{subject_name}."
                    )

                # =============================================
                # MAX MARKS
                # =============================================

                max_marks = to_decimal(
                    exam_subject.max_marks,
                    Decimal("0")
                )

                if max_marks <= Decimal("0"):

                    raise ValueError(
                        f"Maximum marks are not configured "
                        f"correctly for {subject_name}."
                    )

                # =============================================
                # EXCEEDS MAX
                # =============================================

                if marks > max_marks:

                    raise ValueError(
                        f"Marks for {subject_name} "
                        f"cannot exceed {max_marks}."
                    )

                # =============================================
                # CREATE MARK
                # =============================================

                if mark is None:

                    mark = Mark(
                        exam_subject_id=(
                            exam_subject_id
                        ),
                        student_id=student_id,
                        marks_obtained=marks,
                        is_absent=False,
                        is_exempted=False,
                        remarks=(
                            subject_remark
                            or None
                        ),
                        status="submitted",
                        entered_by=None,
                    )

                    db.session.add(
                        mark
                    )

                    mark_map[
                        exam_subject_id
                    ] = mark

                # =============================================
                # UPDATE MARK
                # =============================================

                else:

                    mark.marks_obtained = marks

                    mark.is_absent = False

                    mark.is_exempted = False

                    mark.remarks = (
                        subject_remark
                        or None
                    )

                    mark.status = (
                        "submitted"
                    )

            # =================================================
            # OVERALL REMARKS
            # =================================================

            remarks = request.form.get(
                "remarks",
                ""
            )

            remarks = (
                remarks.strip()
                if remarks
                else ""
            )

            if len(remarks) > 5000:

                raise ValueError(
                    "Remarks cannot exceed "
                    "5000 characters."
                )

            # =================================================
            # WORKFLOW STATUS
            # =================================================

            submitted_status = request.form.get(
                "status",
                result.status or "draft"
            )

            submitted_status = (
                submitted_status.strip().lower()
                if submitted_status
                else "draft"
            )

            allowed_statuses = {
                "draft",
                "submitted",
                "approved",
                "published",
            }

            if (
                submitted_status
                not in allowed_statuses
            ):

                raise ValueError(
                    "Invalid result workflow status."
                )

            # =================================================
            # UPDATE RESULT
            # =================================================

            result.remarks = (
                remarks
                or None
            )

            result.status = (
                submitted_status
            )

            # =================================================
            # FLUSH MARKS
            # =================================================

            db.session.flush()

            # =================================================
            # RECALCULATE STUDENT RESULT
            # =================================================

            calculated_result = (
                calculate_student_result(
                    result.exam,
                    student_id,
                    institution_id,
                    branch_id,
                )
            )

            if calculated_result is None:

                raise RuntimeError(
                    "The student result calculation "
                    "did not return a result."
                )

            # =================================================
            # FLUSH
            # =================================================

            db.session.flush()

            # =================================================
            # RELOAD RESULT
            # =================================================

            refreshed_result = (
                StudentResult.query
                .filter(
                    StudentResult.id
                    == result_id
                )
                .first()
            )

            if not refreshed_result:

                raise RuntimeError(
                    "Student result could not be "
                    "reloaded after calculation."
                )

            # =================================================
            # RESTORE ADMIN VALUES
            # =================================================

            refreshed_result.remarks = (
                remarks
                or None
            )

            refreshed_result.status = (
                submitted_status
            )

            # =================================================
            # RECALCULATE RANKINGS
            # =================================================

            calculate_exam_rankings(
                exam_id,
                institution_id,
                branch_id,
            )

            # =================================================
            # FINAL FLUSH
            # =================================================

            db.session.flush()

            # =================================================
            # COMMIT
            # =================================================

            db.session.commit()

            # =================================================
            # SUCCESS
            # =================================================

            flash(
                "Exam result updated successfully. "
                "Subject marks, result values, "
                "and rankings have been regenerated.",
                "success"
            )

            return redirect(
                url_for(
                    "main.view_exam_result",
                    result_id=result_id
                )
            )

        # ====================================================
        # VALIDATION ERROR
        # ====================================================

        except ValueError as exc:

            db.session.rollback()

            flash(
                str(exc),
                "error"
            )

        # ====================================================
        # UNEXPECTED ERROR
        # ====================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "EDIT EXAM RESULT FAILED | "
                "result_id=%s | "
                "exam_id=%s | "
                "student_id=%s | "
                "institution_id=%s | "
                "branch_id=%s | "
                "program_id=%s | "
                "class_id=%s | "
                "section_id=%s",
                result_id,
                exam_id,
                student_id,
                institution_id,
                branch_id,
                program_id,
                student_class_id,
                student_section_id,
            )

            flash(
                "Unable to update the exam result. "
                "The update was rolled back. "
                "Please check the server console "
                "for the exact error.",
                "error"
            )

    # ========================================================
    # RELOAD RESULT AFTER GET / FAILED POST
    # ========================================================

    result = (
        StudentResult.query
        .options(
            db.joinedload(
                StudentResult.student
            ),
            db.joinedload(
                StudentResult.exam
            ),
            db.joinedload(
                StudentResult.institution
            ),
            db.joinedload(
                StudentResult.branch
            ),
            db.joinedload(
                StudentResult.program
            ),
            db.joinedload(
                StudentResult.academic_year
            ),
            db.joinedload(
                StudentResult.term
            ),
            db.joinedload(
                StudentResult.section
            ),
        )
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    # ========================================================
    # SAFETY
    # ========================================================

    if not result:

        flash(
            "Exam result was not found.",
            "error"
        )

        return redirect(
            url_for(
                "main.exam_results"
            )
        )

    # ========================================================
    # RELOAD IDs
    # ========================================================

    exam_id = result.exam_id
    student_id = result.student_id

    institution_id = result.institution_id
    branch_id = result.branch_id

    program_id = getattr(
        result,
        "program_id",
        None
    )

    student_class_id = getattr(
        result,
        "class_id",
        None
    )

    student_section_id = getattr(
        result,
        "section_id",
        None
    )

    academic_year_id = getattr(
        result,
        "academic_year_id",
        None
    )

    # ========================================================
    # FALLBACK ENROLLMENT
    # ========================================================

    if not student_class_id:

        try:

            enrollment_query = (
                StudentEnrollment.query
                .filter(
                    StudentEnrollment.student_id
                    == student_id
                )
            )

            if hasattr(
                StudentEnrollment,
                "institution_id"
            ):

                enrollment_query = (
                    enrollment_query.filter(
                        StudentEnrollment.institution_id
                        == institution_id
                    )
                )

            if hasattr(
                StudentEnrollment,
                "branch_id"
            ):

                enrollment_query = (
                    enrollment_query.filter(
                        StudentEnrollment.branch_id
                        == branch_id
                    )
                )

            if (
                academic_year_id
                and
                hasattr(
                    StudentEnrollment,
                    "academic_year_id"
                )
            ):

                enrollment_query = (
                    enrollment_query.filter(
                        StudentEnrollment.academic_year_id
                        == academic_year_id
                    )
                )

            if (
                program_id
                and
                hasattr(
                    StudentEnrollment,
                    "program_id"
                )
            ):

                enrollment_query = (
                    enrollment_query.filter(
                        StudentEnrollment.program_id
                        == program_id
                    )
                )

            enrollment = (
                enrollment_query
                .order_by(
                    StudentEnrollment.id.desc()
                )
                .first()
            )

            if enrollment:

                student_class_id = (
                    getattr(
                        enrollment,
                        "class_id",
                        None
                    )
                )

                student_section_id = (
                    getattr(
                        enrollment,
                        "section_id",
                        None
                    )
                )

                if not program_id:

                    program_id = getattr(
                        enrollment,
                        "program_id",
                        None
                    )

        except Exception:

            current_app.logger.exception(
                "Enrollment fallback failed while "
                "rendering edit_exam_result | "
                "result_id=%s",
                result_id,
            )

    # ========================================================
    # CLASS SAFETY
    # ========================================================

    if not student_class_id:

        flash(
            "The student's class could not be determined.",
            "error"
        )

        return redirect(
            url_for(
                "main.view_exam_result",
                result_id=result.id
            )
        )

    # ========================================================
    # BUILD FINAL EXAM SUBJECT QUERY AGAIN
    #
    # MUST BE IDENTICAL TO POST SCOPE.
    # ========================================================

    exam_subject_query = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id == exam_id
        )
    )

    # ========================================================
    # INSTITUTION
    # ========================================================

    if hasattr(
        ExamSubject,
        "institution_id"
    ):

        exam_subject_query = (
            exam_subject_query.filter(
                ExamSubject.institution_id
                == institution_id
            )
        )

    # ========================================================
    # BRANCH
    # ========================================================

    if hasattr(
        ExamSubject,
        "branch_id"
    ):

        exam_subject_query = (
            exam_subject_query.filter(
                ExamSubject.branch_id
                == branch_id
            )
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    if hasattr(
        ExamSubject,
        "program_id"
    ):

        if program_id:

            exam_subject_query = (
                exam_subject_query.filter(
                    ExamSubject.program_id
                    == program_id
                )
            )

        else:

            exam_subject_query = (
                exam_subject_query.filter(
                    ExamSubject.program_id.is_(None)
                )
            )

    # ========================================================
    # CLASS
    # ========================================================

    if hasattr(
        ExamSubject,
        "class_id"
    ):

        exam_subject_query = (
            exam_subject_query.filter(
                ExamSubject.class_id
                == student_class_id
            )
        )

    # ========================================================
    # LOAD
    # ========================================================

    scoped_exam_subjects = (
        exam_subject_query
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # SECTION + SUBJECT DEDUPLICATION
    # ========================================================

    subject_assignment_map = {}

    for exam_subject in scoped_exam_subjects:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )

        if not subject_id:
            continue

        assignment_section_id = getattr(
            exam_subject,
            "section_id",
            None
        )

        # ====================================================
        # STUDENT HAS SECTION
        # ====================================================

        if student_section_id is not None:

            if (
                assignment_section_id is not None
                and
                assignment_section_id
                != student_section_id
            ):
                continue

        # ====================================================
        # STUDENT HAS NO SECTION
        # ====================================================

        else:

            if assignment_section_id is not None:
                continue

        # ====================================================
        # FIRST SUBJECT
        # ====================================================

        existing = subject_assignment_map.get(
            subject_id
        )

        if existing is None:

            subject_assignment_map[
                subject_id
            ] = exam_subject

            continue

        existing_section_id = getattr(
            existing,
            "section_id",
            None
        )

        new_is_section_specific = (
            assignment_section_id is not None
            and
            assignment_section_id
            == student_section_id
        )

        old_is_class_level = (
            existing_section_id is None
        )

        # ====================================================
        # SECTION-SPECIFIC WINS
        # ====================================================

        if (
            new_is_section_specific
            and
            old_is_class_level
        ):

            subject_assignment_map[
                subject_id
            ] = exam_subject

            continue

        # ====================================================
        # SAME SECTION
        # KEEP LOWEST ID
        # ====================================================

        if (
            new_is_section_specific
            and
            existing_section_id
            == student_section_id
        ):

            if exam_subject.id < existing.id:

                subject_assignment_map[
                    subject_id
                ] = exam_subject

            continue

        # ====================================================
        # BOTH CLASS LEVEL
        # KEEP LOWEST ID
        # ====================================================

        if (
            assignment_section_id is None
            and
            existing_section_id is None
        ):

            if exam_subject.id < existing.id:

                subject_assignment_map[
                    subject_id
                ] = exam_subject

    # ========================================================
    # FINAL SUBJECT LIST
    # ========================================================

    exam_subjects = list(
        subject_assignment_map.values()
    )

    # ========================================================
    # SORT
    # ========================================================

    exam_subjects.sort(
        key=lambda item: (
            getattr(
                item,
                "display_order",
                None
            ) is None,

            getattr(
                item,
                "display_order",
                0
            ) or 0,

            item.id,
        )
    )

    # ========================================================
    # HARD FINAL DEDUPLICATION
    # ========================================================

    seen_subject_ids = set()

    unique_exam_subjects = []

    for exam_subject in exam_subjects:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )

        if not subject_id:
            continue

        if subject_id in seen_subject_ids:
            continue

        seen_subject_ids.add(
            subject_id
        )

        unique_exam_subjects.append(
            exam_subject
        )

    exam_subjects = unique_exam_subjects

    # ========================================================
    # NO SUBJECTS
    # ========================================================

    if not exam_subjects:

        flash(
            "No examination subjects were assigned to "
            "this student's class/program.",
            "error"
        )

        return redirect(
            url_for(
                "main.view_exam_result",
                result_id=result.id
            )
        )

    # ========================================================
    # SUBJECT IDS
    # ========================================================

    exam_subject_ids = [
        item.id
        for item in exam_subjects
    ]

    # ========================================================
    # LOAD MARKS
    # ========================================================

    existing_marks = []

    if exam_subject_ids:

        existing_marks = (
            Mark.query
            .filter(
                Mark.student_id
                == student_id,

                Mark.exam_subject_id.in_(
                    exam_subject_ids
                )
            )
            .all()
        )

    # ========================================================
    # MARK MAP
    # ========================================================

    mark_map = {
        mark.exam_subject_id: mark
        for mark in existing_marks
    }

    # ========================================================
    # SUBJECT ROWS
    # ========================================================

    subject_rows = []

    for exam_subject in exam_subjects:

        mark = mark_map.get(
            exam_subject.id
        )

        # ====================================================
        # SUBJECT
        # ====================================================

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        subject_name = (
            getattr(
                subject,
                "name",
                None
            )
            or
            getattr(
                subject,
                "title",
                None
            )
            or
            "Subject"
        )

        # ====================================================
        # TEACHER
        # ====================================================

        teacher = getattr(
            exam_subject,
            "teacher",
            None
        )

        teacher_name = (
            getattr(
                teacher,
                "full_name",
                None
            )
            or
            "—"
        )

        # ====================================================
        # MARKS
        # ====================================================

        marks_value = None

        if (
            mark
            and
            mark.marks_obtained is not None
        ):

            marks_value = (
                mark.marks_obtained
            )

        # ====================================================
        # ABSENT
        # ====================================================

        is_absent = (
            bool(mark.is_absent)
            if mark
            else False
        )

        # ====================================================
        # EXEMPTED
        # ====================================================

        is_exempted = (
            bool(mark.is_exempted)
            if mark
            else False
        )

        # ====================================================
        # MISSING
        # ====================================================

        is_missing = (
            mark is None
            or
            (
                mark.marks_obtained is None
                and
                not is_absent
                and
                not is_exempted
            )
        )

        # ====================================================
        # APPEND
        # ====================================================

        subject_rows.append({

            "exam_subject": exam_subject,

            "mark": mark,

            "subject_name": subject_name,

            "teacher_name": teacher_name,

            "marks": marks_value,

            "max_marks": (
                exam_subject.max_marks
            ),

            "pass_marks": (
                exam_subject.pass_marks
            ),

            "is_absent": is_absent,

            "is_exempted": is_exempted,

            "is_missing": is_missing,

        })

    # ========================================================
    # COUNTS
    # ========================================================

    total_subjects = len(
        subject_rows
    )

    missing_subjects = sum(
        1
        for row in subject_rows
        if row["is_missing"]
    )

    completed_subjects = sum(
        1
        for row in subject_rows
        if (
            row["marks"] is not None
            and
            not row["is_absent"]
            and
            not row["is_exempted"]
        )
    )

    absent_subjects = sum(
        1
        for row in subject_rows
        if row["is_absent"]
    )

    exempted_subjects = sum(
        1
        for row in subject_rows
        if row["is_exempted"]
    )

    # ========================================================
    # FINAL DEBUG
    # ========================================================

    current_app.logger.info(
        "FINAL EDIT SUBJECTS | "
        "result=%s | "
        "student=%s | "
        "class=%s | "
        "section=%s | "
        "subject_ids=%s | "
        "count=%s",
        result_id,
        student_id,
        student_class_id,
        student_section_id,
        [
            getattr(
                row["exam_subject"],
                "subject_id",
                None
            )
            for row in subject_rows
        ],
        len(subject_rows),
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/edit_exam_result.html",

        result=result,

        exam=exam,

        exam_subjects=exam_subjects,

        subject_rows=subject_rows,

        mark_map=mark_map,

        total_subjects=total_subjects,

        missing_subjects=missing_subjects,

        completed_subjects=completed_subjects,

        absent_subjects=absent_subjects,

        exempted_subjects=exempted_subjects,

        can_edit_subject_marks=True,

        can_edit_workflow_status=True,

        page_mode="edit",

        user=current_user,

        # ----------------------------------------------------
        # Useful for template/debug display
        # ----------------------------------------------------

        student_class_id=student_class_id,

        student_section_id=student_section_id,

        program_id=program_id,

    )



# ============================================================
# VIEW EXAM RESULT
# ============================================================

@bp.route(
    "/exam-results/<int:result_id>/view",
    methods=["GET"]
)
@login_required
def view_exam_result(result_id):

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # GET RESULT
    # ========================================================

    result = (
        StudentResult.query
        .filter(
            StudentResult.id == result_id
        )
        .first()
    )

    if not result:

        flash(
            "Exam result was not found.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # RESULT SCOPE
    # ========================================================

    result_institution_id = getattr(
        result,
        "institution_id",
        None
    )

    result_branch_id = getattr(
        result,
        "branch_id",
        None
    )

    # ========================================================
    # SUPERADMIN
    # ========================================================

    if role == "superadmin":

        pass

    # ========================================================
    # SCHOOL ADMIN
    # ========================================================

    elif role == "school_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not user_institution_id:
            abort(403)

        if (
            result_institution_id
            != user_institution_id
        ):
            abort(403)

    # ========================================================
    # BRANCH ADMIN
    # ========================================================

    elif role == "branch_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        user_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not user_institution_id
            or not user_branch_id
        ):
            abort(403)

        if (
            result_institution_id
            != user_institution_id
        ):
            abort(403)

        if (
            result_branch_id
            != user_branch_id
        ):
            abort(403)

    # ========================================================
    # TEACHER
    # ========================================================

    elif role == "teacher":

        teacher = getattr(
            g,
            "teacher",
            None
        )

        if not teacher:
            abort(403)

        teacher_institution_id = getattr(
            teacher,
            "institution_id",
            None
        )

        teacher_branch_id = getattr(
            teacher,
            "branch_id",
            None
        )

        if (
            teacher_institution_id
            != result_institution_id
        ):
            abort(403)

        if (
            teacher_branch_id
            != result_branch_id
        ):
            abort(403)

    # ========================================================
    # RELATED DATA
    # ========================================================

    student = getattr(
        result,
        "student",
        None
    )

    exam = getattr(
        result,
        "exam",
        None
    )

    enrollment = getattr(
        result,
        "student_enrollment",
        None
    )

    institution = getattr(
        result,
        "institution",
        None
    )

    branch = getattr(
        result,
        "branch",
        None
    )

    program = getattr(
        result,
        "program",
        None
    )

    academic_year = getattr(
        result,
        "academic_year",
        None
    )

    term = getattr(
        result,
        "term",
        None
    )

    selected_class = getattr(
        result,
        "class_",
        None
    )

    section = getattr(
        result,
        "section",
        None
    )

    # ========================================================
    # REQUIRED RELATION VALIDATION
    # ========================================================

    if not student:

        flash(
            "The student connected to this result was not found.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    if not exam:

        flash(
            "The examination connected to this result was not found.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # ENROLLMENT VALIDATION
    #
    # The result must have an enrollment because the student's
    # class/section/program determine which ExamSubjects belong
    # to this result.
    # ========================================================

    if not enrollment:

        flash(
            "The student enrollment connected to this result was not found.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # ENROLLMENT SCOPE
    # ========================================================

    enrollment_institution_id = getattr(
        enrollment,
        "institution_id",
        None
    )

    enrollment_branch_id = getattr(
        enrollment,
        "branch_id",
        None
    )

    enrollment_program_id = getattr(
        enrollment,
        "program_id",
        None
    )

    enrollment_academic_year_id = getattr(
        enrollment,
        "academic_year_id",
        None
    )

    enrollment_class_id = getattr(
        enrollment,
        "class_id",
        None
    )

    enrollment_section_id = getattr(
        enrollment,
        "section_id",
        None
    )

    # ========================================================
    # RESULT / ENROLLMENT CONSISTENCY
    # ========================================================

    if (
        result_institution_id is not None
        and enrollment_institution_id is not None
        and result_institution_id
        != enrollment_institution_id
    ):
        abort(403)

    if (
        result_branch_id is not None
        and enrollment_branch_id is not None
        and result_branch_id
        != enrollment_branch_id
    ):
        abort(403)

    # ========================================================
    # ACADEMIC YEAR VALIDATION
    # ========================================================

    exam_academic_year_id = getattr(
        exam,
        "academic_year_id",
        None
    )

    if (
        exam_academic_year_id is not None
        and enrollment_academic_year_id is not None
        and exam_academic_year_id
        != enrollment_academic_year_id
    ):

        flash(
            "The student's enrollment does not belong to the academic year of this examination.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # PROGRAM VALIDATION
    # ========================================================

    exam_program_id = getattr(
        exam,
        "program_id",
        None
    )

    if (
        exam_program_id is not None
        and enrollment_program_id is not None
        and exam_program_id
        != enrollment_program_id
    ):

        flash(
            "The student's enrollment does not belong to the program of this examination.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # CLASS IS REQUIRED FOR SUBJECT SCOPING
    # ========================================================

    if not enrollment_class_id:

        flash(
            "The student's class could not be determined for this result.",
            "danger"
        )

        return redirect(
            url_for("main.exam_results")
        )

    # ========================================================
    # GET EXAM SUBJECTS
    #
    # IMPORTANT:
    #
    # DO NOT simply use:
    #
    # ExamSubject.exam_id == exam.id
    #
    # because one exam can contain subjects for multiple
    # classes.
    #
    # Example:
    #
    # KD20:
    #   English
    #   Mathematics
    #   Somali
    #
    # KD21:
    #   English
    #   Mathematics
    #   Somali
    #
    # A KD21 student must receive ONLY the KD21 subjects.
    # ========================================================

    exam_subject_query = (
        ExamSubject.query
        .filter(
            ExamSubject.exam_id == exam.id
        )
    )

    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    if hasattr(
        ExamSubject,
        "institution_id"
    ):

        if enrollment_institution_id is not None:

            exam_subject_query = (
                exam_subject_query
                .filter(
                    ExamSubject.institution_id
                    == enrollment_institution_id
                )
            )

    # ========================================================
    # BRANCH FILTER
    #
    # We first retrieve the student's branch scope.
    # Shared ExamSubjects with branch_id=NULL are also allowed.
    # ========================================================

    exam_subjects_candidates = (
        exam_subject_query
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # FILTER CANDIDATES IN PYTHON
    #
    # This allows us to support:
    #
    # branch-specific
    # OR
    # shared branch
    #
    # and then select the most specific assignment.
    # ========================================================

    filtered_exam_subjects = []

    for exam_subject in exam_subjects_candidates:

        # ----------------------------------------------------
        # BRANCH
        # ----------------------------------------------------

        exam_subject_branch_id = getattr(
            exam_subject,
            "branch_id",
            None
        )

        if (
            exam_subject_branch_id is not None
            and enrollment_branch_id is not None
            and exam_subject_branch_id
            != enrollment_branch_id
        ):
            continue

        # ----------------------------------------------------
        # PROGRAM
        #
        # Program must match the student's enrollment.
        # ----------------------------------------------------

        exam_subject_program_id = getattr(
            exam_subject,
            "program_id",
            None
        )

        if (
            exam_subject_program_id is not None
            and enrollment_program_id is not None
            and exam_subject_program_id
            != enrollment_program_id
        ):
            continue

        # ----------------------------------------------------
        # CLASS
        #
        # THIS IS THE MOST IMPORTANT FIX.
        #
        # An ExamSubject belonging to KD20 must NEVER be
        # displayed for a KD21 student.
        # ----------------------------------------------------

        exam_subject_class_id = getattr(
            exam_subject,
            "class_id",
            None
        )

        if not exam_subject_class_id:

            # Fail closed.
            #
            # An ExamSubject without class assignment cannot
            # safely be shown in a class-scoped result.
            continue

        if (
            exam_subject_class_id
            != enrollment_class_id
        ):
            continue

        # ----------------------------------------------------
        # SECTION
        #
        # If student has a section:
        #
        #   section-specific assignment -> accepted
        #   class-level assignment      -> accepted
        #   other section               -> rejected
        #
        # If student has NO section:
        #
        #   only class-level assignment is accepted.
        # ----------------------------------------------------

        exam_subject_section_id = getattr(
            exam_subject,
            "section_id",
            None
        )

        if enrollment_section_id is not None:

            if (
                exam_subject_section_id is not None
                and exam_subject_section_id
                != enrollment_section_id
            ):
                continue

        else:

            if exam_subject_section_id is not None:
                continue

        filtered_exam_subjects.append(
            exam_subject
        )

    # ========================================================
    # SELECT ONE SUBJECT ONLY
    #
    # Priority:
    #
    # 1. Exact branch + exact section
    # 2. Exact branch + class-level
    # 3. Shared branch + exact section
    # 4. Shared branch + class-level
    #
    # This prevents duplicate subjects.
    # ========================================================

    selected_by_subject = {}

    for exam_subject in filtered_exam_subjects:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )

        if not subject_id:
            continue

        # ----------------------------------------------------
        # BRANCH PRIORITY
        # ----------------------------------------------------

        exam_subject_branch_id = getattr(
            exam_subject,
            "branch_id",
            None
        )

        branch_priority = (
            1
            if (
                enrollment_branch_id is not None
                and exam_subject_branch_id
                == enrollment_branch_id
            )
            else 0
        )

        # ----------------------------------------------------
        # SECTION PRIORITY
        # ----------------------------------------------------

        exam_subject_section_id = getattr(
            exam_subject,
            "section_id",
            None
        )

        section_priority = (
            1
            if (
                enrollment_section_id is not None
                and exam_subject_section_id
                == enrollment_section_id
            )
            else 0
        )

        priority = (
            section_priority,
            branch_priority,
        )

        current = selected_by_subject.get(
            subject_id
        )

        if current is None:

            selected_by_subject[
                subject_id
            ] = (
                priority,
                exam_subject
            )

        else:

            current_priority, current_exam_subject = current

            # ------------------------------------------------
            # MORE SPECIFIC ASSIGNMENT WINS
            # ------------------------------------------------

            if priority > current_priority:

                selected_by_subject[
                    subject_id
                ] = (
                    priority,
                    exam_subject
                )

            # ------------------------------------------------
            # IF SAME PRIORITY:
            # LOWEST ExamSubject ID WINS
            # ------------------------------------------------

            elif (
                priority
                == current_priority
                and exam_subject.id
                < current_exam_subject.id
            ):

                selected_by_subject[
                    subject_id
                ] = (
                    priority,
                    exam_subject
                )

    # ========================================================
    # FINAL EXAM SUBJECT LIST
    # ========================================================

    exam_subjects = [
        item[1]
        for item in selected_by_subject.values()
    ]

    # ========================================================
    # DISPLAY ORDER
    # ========================================================

    def exam_subject_sort_key(
        exam_subject
    ):

        display_order = getattr(
            exam_subject,
            "display_order",
            None
        )

        if display_order is None:

            return (
                1,
                0,
                exam_subject.id
            )

        return (
            0,
            display_order,
            exam_subject.id
        )

    exam_subjects.sort(
        key=exam_subject_sort_key
    )

    # ========================================================
    # GET STUDENT MARKS
    #
    # ONLY MARKS BELONGING TO THE SELECTED SUBJECTS.
    # ========================================================

    exam_subject_ids = [
        exam_subject.id
        for exam_subject in exam_subjects
    ]

    marks_by_exam_subject = {}

    if exam_subject_ids:

        marks = (
            Mark.query
            .filter(
                Mark.exam_subject_id.in_(
                    exam_subject_ids
                ),
                Mark.student_id == student.id
            )
            .order_by(
                Mark.id.asc()
            )
            .all()
        )

        # ----------------------------------------------------
        # Keep the first/oldest mark deterministically.
        # ----------------------------------------------------

        for mark in marks:

            if (
                mark.exam_subject_id
                not in marks_by_exam_subject
            ):

                marks_by_exam_subject[
                    mark.exam_subject_id
                ] = mark

    # ========================================================
    # PREPARE SUBJECT RESULTS
    # ========================================================

    subject_results = []

    for exam_subject in exam_subjects:

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        mark = marks_by_exam_subject.get(
            exam_subject.id
        )

        # ====================================================
        # MAX MARKS
        # ====================================================

        max_marks = to_decimal(
            getattr(
                exam_subject,
                "max_marks",
                None
            )
        )

        if max_marks <= 0:

            max_marks = to_decimal(
                getattr(
                    subject,
                    "max_marks",
                    100
                )
            )

        # ====================================================
        # MARKS OBTAINED
        # ====================================================

        marks_obtained = None

        if mark:

            marks_obtained = getattr(
                mark,
                "marks_obtained",
                None
            )

        # ====================================================
        # ABSENT
        # ====================================================

        is_absent = False

        if mark:

            is_absent = bool(
                getattr(
                    mark,
                    "is_absent",
                    False
                )
            )

        # ====================================================
        # EXEMPTED
        # ====================================================

        is_exempted = False

        if mark:

            is_exempted = bool(
                getattr(
                    mark,
                    "is_exempted",
                    False
                )
            )

        # ====================================================
        # SUBJECT PERCENTAGE
        # ====================================================

        subject_percentage = None

        subject_grade = "-"

        if (
            mark
            and not is_absent
            and not is_exempted
            and marks_obtained is not None
            and max_marks > 0
        ):

            obtained_decimal = to_decimal(
                marks_obtained
            )

            # -----------------------------------------------
            # Prevent invalid negative marks.
            # -----------------------------------------------

            if obtained_decimal < 0:

                obtained_decimal = Decimal(
                    "0"
                )

            # -----------------------------------------------
            # Prevent marks above maximum.
            # -----------------------------------------------

            if obtained_decimal > max_marks:

                obtained_decimal = max_marks

            # -----------------------------------------------
            # Calculate percentage.
            # -----------------------------------------------

            subject_percentage = (
                obtained_decimal
                / max_marks
            ) * Decimal("100")

            subject_percentage = (
                subject_percentage.quantize(
                    Decimal("0.01"),
                    rounding=ROUND_HALF_UP
                )
            )

            subject_grade = calculate_grade(
                subject_percentage
            )

        # ====================================================
        # PASS MARKS
        # ====================================================

        pass_marks = to_decimal(
            getattr(
                exam_subject,
                "pass_marks",
                None
            )
        )

        if pass_marks <= 0:

            pass_marks = to_decimal(
                getattr(
                    subject,
                    "pass_marks",
                    50
                )
            )

        # ====================================================
        # SUBJECT STATUS
        # ====================================================

        if not mark:

            subject_status = "Not Entered"

        elif is_absent:

            subject_status = "Absent"

        elif is_exempted:

            subject_status = "Exempted"

        elif marks_obtained is None:

            subject_status = "Incomplete"

        elif (
            to_decimal(
                marks_obtained
            )
            >= pass_marks
        ):

            subject_status = "Pass"

        else:

            subject_status = "Fail"

        # ====================================================
        # REMARKS
        # ====================================================

        subject_remarks = None

        if mark:

            subject_remarks = getattr(
                mark,
                "remarks",
                None
            )

        # ====================================================
        # APPEND
        # ====================================================

        subject_results.append({

            "exam_subject": exam_subject,

            "subject": subject,

            "mark": mark,

            "marks_obtained": marks_obtained,

            "max_marks": max_marks,

            "pass_marks": pass_marks,

            "percentage": subject_percentage,

            "grade": subject_grade,

            "is_absent": is_absent,

            "is_exempted": is_exempted,

            "status": subject_status,

            "remarks": subject_remarks,

        })

    # ========================================================
    # DISPLAY COUNTS
    #
    # These are based on the actual subjects shown on this
    # page, not all ExamSubjects in the examination.
    # ========================================================

    view_subjects_total = len(
        exam_subjects
    )

    view_subjects_completed = 0

    view_subjects_failed = 0

    for item in subject_results:

        if (
            item["status"]
            not in {
                "Not Entered",
                "Absent",
                "Exempted",
                "Incomplete",
            }
            and item["marks_obtained"]
            is not None
        ):

            view_subjects_completed += 1

        if item["status"] == "Fail":

            view_subjects_failed += 1

    # ========================================================
    # DEBUG LOG
    #
    # Useful for confirming KD20/KD21 filtering.
    # ========================================================

    try:

        current_app.logger.info(
            "VIEW EXAM RESULT | "
            "result=%s | student=%s | exam=%s | "
            "institution=%s | branch=%s | program=%s | "
            "class=%s | section=%s | "
            "subjects=%s",
            result.id,
            student.id,
            exam.id,
            enrollment_institution_id,
            enrollment_branch_id,
            enrollment_program_id,
            enrollment_class_id,
            enrollment_section_id,
            [
                getattr(
                    es,
                    "subject_id",
                    None
                )
                for es in exam_subjects
            ]
        )

    except Exception:
        pass

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/view_exam_result.html",

        # ====================================================
        # RESULT
        # ====================================================

        result=result,

        # ====================================================
        # STUDENT
        # ====================================================

        student=student,

        # ====================================================
        # EXAM
        # ====================================================

        exam=exam,

        exam_subjects=exam_subjects,

        subject_results=subject_results,

        # ====================================================
        # ACADEMIC STRUCTURE
        # ====================================================

        enrollment=enrollment,

        institution=institution,

        branch=branch,

        program=program,

        academic_year=academic_year,

        term=term,

        selected_class=selected_class,

        section=section,

        user=current_user,

        # ====================================================
        # RESULT VALUES
        # ====================================================

        total_marks=(
            getattr(
                result,
                "total_marks",
                0
            )
            or 0
        ),

        total_possible_marks=(
            getattr(
                result,
                "total_possible_marks",
                0
            )
            or 0
        ),

        percentage=(
            getattr(
                result,
                "percentage",
                0
            )
            or 0
        ),

        average=(
            getattr(
                result,
                "average",
                0
            )
            or 0
        ),

        grade=(
            getattr(
                result,
                "grade",
                "-"
            )
            or "-"
        ),

        gpa=(
            getattr(
                result,
                "gpa",
                0
            )
            or 0
        ),

        result_status=(
            getattr(
                result,
                "result_status",
                "incomplete"
            )
            or "incomplete"
        ),

        status=(
            getattr(
                result,
                "status",
                "draft"
            )
            or "draft"
        ),

        # ====================================================
        # SUBJECT COUNTS
        #
        # Use stored StudentResult values if available.
        # Also expose view-specific counts for templates that
        # want the subjects currently displayed.
        # ====================================================

        subjects_total=(
            getattr(
                result,
                "subjects_total",
                0
            )
            or 0
        ),

        subjects_completed=(
            getattr(
                result,
                "subjects_completed",
                0
            )
            or 0
        ),

        subjects_failed=(
            getattr(
                result,
                "subjects_failed",
                0
            )
            or 0
        ),

        view_subjects_total=(
            view_subjects_total
        ),

        view_subjects_completed=(
            view_subjects_completed
        ),

        view_subjects_failed=(
            view_subjects_failed
        ),

        # ====================================================
        # RANKINGS
        # ====================================================

        institution_position=(
            getattr(
                result,
                "institution_position",
                None
            )
        ),

        branch_position=(
            getattr(
                result,
                "branch_position",
                None
            )
        ),

        program_position=(
            getattr(
                result,
                "program_position",
                None
            )
        ),

        class_position=(
            getattr(
                result,
                "class_position",
                None
            )
        ),

        section_position=(
            getattr(
                result,
                "section_position",
                None
            )
        ),

        # ====================================================
        # REMARKS
        # ====================================================

        remarks=(
            getattr(
                result,
                "remarks",
                ""
            )
            or ""
        ),
    )




# ============================================================
# ADD / ENTER EXAM RESULT MARKS
# ============================================================

@bp.route(
    "/exam-results/add",
    methods=["GET", "POST"]
)
@login_required
def add_exam_result():

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # RESPONSE TYPE
    # ========================================================

    accept_header = (
        request.headers.get(
            "Accept",
            ""
        )
        or ""
    ).lower()

    is_json_request = (
        "application/json"
        in accept_header
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def to_int(value):

        if value is None:
            return None

        try:

            value = str(
                value
            ).strip()

            if not value:
                return None

            return int(value)

        except (
            ValueError,
            TypeError,
        ):

            return None

    def request_value(
        name,
        aliases=None,
        default=None,
    ):

        aliases = aliases or []

        names = [
            name,
            *aliases,
        ]

        # ----------------------------------------------------
        # POST
        # ----------------------------------------------------

        if request.method == "POST":

            for field_name in names:

                value = request.form.get(
                    field_name
                )

                if value is not None:

                    value = str(
                        value
                    ).strip()

                    if value:
                        return value

        # ----------------------------------------------------
        # GET
        # ----------------------------------------------------

        for field_name in names:

            value = request.args.get(
                field_name
            )

            if value is not None:

                value = str(
                    value
                ).strip()

                if value:
                    return value

        return default

    def normalize_status(value):

        value = getattr(
            value,
            "value",
            value
        )

        return (
            str(value).strip().lower()
            if value
            else ""
        )

    def json_error(message):

        return jsonify({
            "success": False,
            "message": str(message),
        }), 400

    # ========================================================
    # EXAM SUBJECT SCOPE HELPER
    # ========================================================
    #
    # THIS IS THE MAIN FIX.
    #
    # It receives all ExamSubjects belonging to the exam and
    # returns ONLY the subjects applicable to the student's
    # enrollment.
    #
    # Example:
    #
    # Exam:
    #     English -> class 1 / KD20
    #     English -> class 2 / KD21
    #
    # Student enrollment:
    #     class_id = 1
    #
    # Result:
    #     English -> class 1 only
    #
    # ========================================================

    def subjects_for_enrollment(
        all_subjects,
        enrollment
    ):

        if not enrollment:
            return []

        enrollment_class_id = getattr(
            enrollment,
            "class_id",
            None
        )

        enrollment_section_id = getattr(
            enrollment,
            "section_id",
            None
        )

        scoped_subjects = []

        for exam_subject in all_subjects:

            subject_class_id = getattr(
                exam_subject,
                "class_id",
                None
            )

            subject_section_id = getattr(
                exam_subject,
                "section_id",
                None
            )

            # ------------------------------------------------
            # CLASS SCOPE
            #
            # class_id NULL means the subject is not restricted
            # to a specific class.
            # ------------------------------------------------

            if (
                subject_class_id is not None
                and subject_class_id
                != enrollment_class_id
            ):
                continue

            # ------------------------------------------------
            # SECTION SCOPE
            #
            # section_id NULL means the subject is not restricted
            # to a specific section.
            # ------------------------------------------------

            if (
                subject_section_id is not None
                and subject_section_id
                != enrollment_section_id
            ):
                continue

            scoped_subjects.append(
                exam_subject
            )

        return scoped_subjects

    # ========================================================
    # REQUEST VALUES
    # ========================================================

    exam_id = to_int(
        request_value(
            "exam_id",
            aliases=[
                "selected_exam_id",
            ]
        )
    )

    student_id = to_int(
        request_value(
            "student_id",
            aliases=[
                "selected_student_id",
                "student",
                "student_select",
            ]
        )
    )

    scope_type = request_value(
        "scope_type",
        aliases=[
            "student_scope",
            "scope",
        ]
    )

    if scope_type:

        scope_type = (
            str(scope_type)
            .strip()
            .lower()
        )

    allowed_scopes = {
        "class",
        "section",
        "all_students",
        "all_program",
    }

    if scope_type not in allowed_scopes:
        scope_type = None

    class_id = to_int(
        request_value(
            "class_id",
            aliases=[
                "selected_class_id",
            ]
        )
    )

    section_id = to_int(
        request_value(
            "section_id",
            aliases=[
                "selected_section_id",
            ]
        )
    )

    program_id = to_int(
        request_value(
            "program_id",
            aliases=[
                "selected_program_id",
            ]
        )
    )

    # ========================================================
    # NAVIGATION
    # ========================================================

    navigation = request_value(
        "navigation",
        aliases=[
            "student_navigation",
        ]
    )

    navigation = (
        str(navigation).strip().lower()
        if navigation
        else None
    )

    # ========================================================
    # EXAMS
    # ========================================================

    exams_query = Exam.query

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        exams_query = (
            exams_query
            .filter(
                Exam.institution_id
                == current_institution_id
            )
        )

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        exams_query = (
            exams_query
            .filter(
                Exam.institution_id
                == current_institution_id,
                Exam.branch_id
                == current_branch_id,
            )
        )

    exams = (
        exams_query
        .order_by(
            Exam.id.desc()
        )
        .all()
    )

    # ========================================================
    # SELECTED EXAM
    # ========================================================

    exam = None

    if exam_id:

        exam_query = Exam.query

        if role == "school_admin":

            exam_query = (
                exam_query
                .filter(
                    Exam.institution_id
                    == current_institution_id
                )
            )

        elif role == "branch_admin":

            exam_query = (
                exam_query
                .filter(
                    Exam.institution_id
                    == current_institution_id,
                    Exam.branch_id
                    == current_branch_id,
                )
            )

        exam = (
            exam_query
            .filter(
                Exam.id == exam_id
            )
            .first()
        )

        if not exam:

            message = (
                "The selected examination was not found "
                "or is outside your access scope."
            )

            if is_json_request:

                return json_error(
                    message
                )

            flash(
                message,
                "error"
            )

            return redirect(
                url_for(
                    "main.add_exam_result"
                )
            )

    # ========================================================
    # EXAM STATUS
    # ========================================================

    if exam:

        exam_status = normalize_status(
            getattr(
                exam,
                "status",
                None
            )
        )

        if exam_status not in {
            "draft",
            "ongoing",
            "published",
        }:

            message = (
                "Marks can only be entered for draft, "
                "ongoing, or published examinations."
            )

            if is_json_request:

                return json_error(
                    message
                )

            flash(
                message,
                "error"
            )

            return redirect(
                url_for(
                    "main.add_exam_result"
                )
            )

    # ========================================================
    # ALL EXAM SUBJECTS
    # ========================================================
    #
    # IMPORTANT:
    # Do NOT call this `exam_subjects` for student processing.
    #
    # These are all subjects configured for the exam.
    #
    # Later we create `student_exam_subjects` based on the
    # student's enrollment.
    #
    # ========================================================

    all_exam_subjects = []

    if exam:

        all_exam_subjects = (
            ExamSubject.query
            .options(
                db.joinedload(
                    ExamSubject.subject
                ),
                db.joinedload(
                    ExamSubject.teacher
                ),
            )
            .filter(
                ExamSubject.exam_id
                == exam.id
            )
            .order_by(
                ExamSubject.id.asc()
            )
            .all()
        )

    # ========================================================
    # DEFAULT EXAM SUBJECTS
    # ========================================================
    #
    # Used only when no student is selected yet.
    #
    # Once a student is selected, this variable is replaced
    # with the student's scoped subjects.
    #
    # ========================================================

    exam_subjects = list(
        all_exam_subjects
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    programs = []

    if exam:

        programs = (
            Program.query
            .filter(
                Program.institution_id
                == exam.institution_id
            )
            .order_by(
                db.func.lower(
                    Program.name
                ).asc()
            )
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    classes = []

    if exam:

        classes_query = (
            Class.query
            .filter(
                Class.institution_id
                == exam.institution_id,

                Class.branch_id
                == exam.branch_id,

                Class.academic_year_id
                == exam.academic_year_id,
            )
        )

        if getattr(
            exam,
            "program_id",
            None
        ):

            classes_query = (
                classes_query
                .filter(
                    Class.program_id
                    == exam.program_id
                )
            )

        classes = (
            classes_query
            .order_by(
                db.func.lower(
                    Class.name
                ).asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections = []

    if exam:

        sections_query = (
            Section.query
            .filter(
                Section.institution_id
                == exam.institution_id,

                Section.branch_id
                == exam.branch_id,

                Section.academic_year_id
                == exam.academic_year_id,
            )
        )

        if class_id:

            sections_query = (
                sections_query
                .filter(
                    Section.class_id
                    == class_id
                )
            )

        sections = (
            sections_query
            .order_by(
                db.func.lower(
                    Section.name
                ).asc()
            )
            .all()
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        try:

            # =================================================
            # EXAM
            # =================================================

            if not exam:

                raise ValueError(
                    "Please select an examination."
                )

            # =================================================
            # SUBJECTS
            # =================================================

            if not all_exam_subjects:

                raise ValueError(
                    "This examination has no subjects assigned."
                )

            # =================================================
            # SCOPE
            # =================================================

            if not scope_type:

                raise ValueError(
                    "Please select a student scope."
                )

            if scope_type not in allowed_scopes:

                raise ValueError(
                    "Invalid student scope selected."
                )

            # =================================================
            # CLEAR UNUSED VALUES
            # =================================================

            if scope_type == "class":

                if not class_id:

                    raise ValueError(
                        "Please select a class."
                    )

                section_id = None
                program_id = None

            elif scope_type == "section":

                if not section_id:

                    raise ValueError(
                        "Please select a section."
                    )

                class_id = None
                program_id = None

            elif scope_type == "all_students":

                class_id = None
                section_id = None
                program_id = None

            elif scope_type == "all_program":

                if not program_id:

                    raise ValueError(
                        "Please select a program."
                    )

                class_id = None
                section_id = None

            # =================================================
            # VALIDATE CLASS
            # =================================================

            selected_class = None

            if scope_type == "class":

                selected_class = (
                    Class.query
                    .filter(
                        Class.id == class_id,

                        Class.institution_id
                        == exam.institution_id,

                        Class.branch_id
                        == exam.branch_id,

                        Class.academic_year_id
                        == exam.academic_year_id,
                    )
                    .first()
                )

                if not selected_class:

                    raise ValueError(
                        "Selected class does not belong to this examination."
                    )

                if (
                    exam.program_id
                    and selected_class.program_id
                    != exam.program_id
                ):

                    raise ValueError(
                        "Selected class does not belong to the examination program."
                    )

            # =================================================
            # VALIDATE SECTION
            # =================================================

            selected_section = None

            if scope_type == "section":

                selected_section = (
                    Section.query
                    .filter(
                        Section.id == section_id,

                        Section.institution_id
                        == exam.institution_id,

                        Section.branch_id
                        == exam.branch_id,

                        Section.academic_year_id
                        == exam.academic_year_id,
                    )
                    .first()
                )

                if not selected_section:

                    raise ValueError(
                        "Selected section does not belong to this examination."
                    )

                section_class = (
                    Class.query
                    .filter(
                        Class.id
                        == selected_section.class_id,

                        Class.institution_id
                        == exam.institution_id,

                        Class.branch_id
                        == exam.branch_id,

                        Class.academic_year_id
                        == exam.academic_year_id,
                    )
                    .first()
                )

                if not section_class:

                    raise ValueError(
                        "The selected section is not connected to a valid class."
                    )

                if (
                    exam.program_id
                    and section_class.program_id
                    != exam.program_id
                ):

                    raise ValueError(
                        "Selected section does not belong to the examination program."
                    )

            # =================================================
            # VALIDATE PROGRAM
            # =================================================

            selected_program = None

            if scope_type == "all_program":

                selected_program = (
                    Program.query
                    .filter(
                        Program.id == program_id,

                        Program.institution_id
                        == exam.institution_id,
                    )
                    .first()
                )

                if not selected_program:

                    raise ValueError(
                        "Selected program does not belong to this institution."
                    )

                if (
                    exam.program_id
                    and program_id
                    != exam.program_id
                ):

                    raise ValueError(
                        "Selected program does not match the examination program."
                    )

            # =================================================
            # STUDENT REQUIRED
            # =================================================

            if not student_id:

                raise ValueError(
                    "Please select a student."
                )

            # =================================================
            # STUDENT
            # =================================================

            student = (
                Student.query
                .filter(
                    Student.id == student_id,

                    Student.institution_id
                    == exam.institution_id,

                    Student.branch_id
                    == exam.branch_id,
                )
                .first()
            )

            if not student:

                raise ValueError(
                    "Selected student was not found in this examination branch."
                )

            # =================================================
            # ENROLLMENT
            # =================================================

            enrollment = (
                StudentEnrollment.query
                .filter(
                    StudentEnrollment.student_id
                    == student.id,

                    StudentEnrollment.academic_year_id
                    == exam.academic_year_id,

                    StudentEnrollment.branch_id
                    == exam.branch_id,

                    StudentEnrollment.institution_id
                    == exam.institution_id,
                )
                .order_by(
                    StudentEnrollment.id.desc()
                )
                .first()
            )

            if not enrollment:

                raise ValueError(
                    "The selected student has no enrollment for this exam academic year."
                )

            # =================================================
            # ENROLLMENT BRANCH
            # =================================================

            enrollment_branch_id = getattr(
                enrollment,
                "branch_id",
                None
            )

            if (
                enrollment_branch_id
                and enrollment_branch_id
                != exam.branch_id
            ):

                raise ValueError(
                    "The selected student does not belong to this exam branch."
                )

            # =================================================
            # ENROLLMENT INSTITUTION
            # =================================================

            enrollment_institution_id = getattr(
                enrollment,
                "institution_id",
                None
            )

            if (
                enrollment_institution_id
                and enrollment_institution_id
                != exam.institution_id
            ):

                raise ValueError(
                    "The selected student enrollment does not belong to this institution."
                )

            # =================================================
            # ENROLLMENT STATUS
            # =================================================

            enrollment_status = normalize_status(
                getattr(
                    enrollment,
                    "status",
                    None
                )
            )

            if (
                enrollment_status
                and enrollment_status
                not in {
                    "active",
                    "enrolled",
                }
            ):

                raise ValueError(
                    "The selected student is not actively enrolled for this academic year."
                )

            # =================================================
            # ENROLLMENT PROGRAM
            # =================================================

            enrollment_program_id = getattr(
                enrollment,
                "program_id",
                None
            )

            if (
                exam.program_id
                and enrollment_program_id
                != exam.program_id
            ):

                raise ValueError(
                    "The selected student does not belong to the program assigned to this examination."
                )

            # =================================================
            # ENROLLMENT CLASS
            # =================================================

            enrollment_class_id = getattr(
                enrollment,
                "class_id",
                None
            )

            # =================================================
            # ENROLLMENT SECTION
            # =================================================

            enrollment_section_id = getattr(
                enrollment,
                "section_id",
                None
            )

            # =================================================
            # SCOPE VALIDATION
            # =================================================

            if (
                scope_type == "class"
                and enrollment_class_id
                != class_id
            ):

                raise ValueError(
                    "The selected student does not belong to the selected class."
                )

            if (
                scope_type == "section"
                and enrollment_section_id
                != section_id
            ):

                raise ValueError(
                    "The selected student does not belong to the selected section."
                )

            if (
                scope_type == "all_program"
                and enrollment_program_id
                != program_id
            ):

                raise ValueError(
                    "The selected student does not belong to the selected program."
                )

            # =================================================
            # IMPORTANT SUBJECT SCOPE
            # =================================================
            #
            # THIS IS THE MAIN FIX FOR THE DUPLICATE ENGLISH.
            #
            # The student gets only the ExamSubjects matching
            # his/her enrolled class and section.
            #
            # =================================================

            exam_subjects = subjects_for_enrollment(
                all_exam_subjects,
                enrollment
            )

            if not exam_subjects:

                raise ValueError(
                    "No examination subjects are assigned to the selected student's class or section."
                )

            # =================================================
            # EXISTING MARKS
            # =================================================

            exam_subject_ids = [
                item.id
                for item in exam_subjects
            ]

            existing_marks = (
                Mark.query
                .filter(
                    Mark.student_id == student.id,

                    Mark.exam_subject_id.in_(
                        exam_subject_ids
                    ),
                )
                .all()
            )

            mark_map = {
                mark.exam_subject_id: mark
                for mark in existing_marks
            }

            # =================================================
            # PROCESS MARKS
            # =================================================

            changed_any = False

            for exam_subject in exam_subjects:

                exam_subject_id = (
                    exam_subject.id
                )

                subject = getattr(
                    exam_subject,
                    "subject",
                    None
                )

                subject_name = (
                    getattr(
                        subject,
                        "name",
                        None
                    )
                    or getattr(
                        subject,
                        "title",
                        None
                    )
                    or "Subject"
                )

                mark_field = (
                    f"mark_{exam_subject_id}"
                )

                absent_field = (
                    f"absent_{exam_subject_id}"
                )

                exempted_field = (
                    f"exempted_{exam_subject_id}"
                )

                remark_field = (
                    f"remark_{exam_subject_id}"
                )

                raw_marks = request.form.get(
                    mark_field,
                    ""
                )

                raw_marks = (
                    raw_marks.strip()
                    if raw_marks
                    else ""
                )

                is_absent = (
                    request.form.get(
                        absent_field
                    )
                    == "1"
                )

                is_exempted = (
                    request.form.get(
                        exempted_field
                    )
                    == "1"
                )

                subject_remark = request.form.get(
                    remark_field,
                    ""
                )

                subject_remark = (
                    subject_remark.strip()
                    if subject_remark
                    else ""
                )

                # =================================================
                # BOTH ABSENT + EXEMPTED
                # =================================================

                if (
                    is_absent
                    and is_exempted
                ):

                    raise ValueError(
                        f"{subject_name}: "
                        "A subject cannot be both absent and exempted."
                    )

                # =================================================
                # EMPTY
                # =================================================

                if (
                    not raw_marks
                    and not is_absent
                    and not is_exempted
                ):

                    continue

                mark = mark_map.get(
                    exam_subject_id
                )

                # =================================================
                # ABSENT
                # =================================================

                if is_absent:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=exam_subject_id,

                            student_id=student.id,

                            marks_obtained=None,

                            is_absent=True,

                            is_exempted=False,

                            remarks=(
                                subject_remark
                                or None
                            ),

                            status="submitted",

                            entered_by=None,
                        )

                        db.session.add(
                            mark
                        )

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None

                        mark.is_absent = True

                        mark.is_exempted = False

                        mark.remarks = (
                            subject_remark
                            or None
                        )

                        mark.status = (
                            "submitted"
                        )

                    changed_any = True

                    continue

                # =================================================
                # EXEMPTED
                # =================================================

                if is_exempted:

                    if mark is None:

                        mark = Mark(
                            exam_subject_id=exam_subject_id,

                            student_id=student.id,

                            marks_obtained=None,

                            is_absent=False,

                            is_exempted=True,

                            remarks=(
                                subject_remark
                                or None
                            ),

                            status="submitted",

                            entered_by=None,
                        )

                        db.session.add(
                            mark
                        )

                        mark_map[
                            exam_subject_id
                        ] = mark

                    else:

                        mark.marks_obtained = None

                        mark.is_absent = False

                        mark.is_exempted = True

                        mark.remarks = (
                            subject_remark
                            or None
                        )

                        mark.status = (
                            "submitted"
                        )

                    changed_any = True

                    continue

                # =================================================
                # NORMAL MARK
                # =================================================

                try:

                    marks = Decimal(
                        raw_marks
                    )

                except (
                    InvalidOperation,
                    ValueError,
                    TypeError,
                ):

                    raise ValueError(
                        f"Invalid marks entered for {subject_name}."
                    )

                if not marks.is_finite():

                    raise ValueError(
                        f"Invalid marks entered for {subject_name}."
                    )

                if marks < Decimal("0"):

                    raise ValueError(
                        f"Marks cannot be negative for {subject_name}."
                    )

                max_marks = to_decimal(
                    exam_subject.max_marks,
                    Decimal("0")
                )

                if max_marks <= Decimal("0"):

                    raise ValueError(
                        f"Maximum marks are not configured correctly for {subject_name}."
                    )

                if marks > max_marks:

                    raise ValueError(
                        f"Marks for {subject_name} cannot exceed {max_marks}."
                    )

                # =================================================
                # CREATE
                # =================================================

                if mark is None:

                    mark = Mark(
                        exam_subject_id=exam_subject_id,

                        student_id=student.id,

                        marks_obtained=marks,

                        is_absent=False,

                        is_exempted=False,

                        remarks=(
                            subject_remark
                            or None
                        ),

                        status="submitted",

                        entered_by=None,
                    )

                    db.session.add(
                        mark
                    )

                    mark_map[
                        exam_subject_id
                    ] = mark

                # =================================================
                # UPDATE
                # =================================================

                else:

                    mark.marks_obtained = marks

                    mark.is_absent = False

                    mark.is_exempted = False

                    mark.remarks = (
                        subject_remark
                        or None
                    )

                    mark.status = (
                        "submitted"
                    )

                changed_any = True

            # =================================================
            # NOTHING ENTERED
            # =================================================

            if not changed_any:

                raise ValueError(
                    "Please enter at least one subject mark, absent status, or exempted status."
                )

            # =================================================
            # SAVE MARKS
            # =================================================

            db.session.flush()

            # =================================================
            # PRESERVE RESULT STATUS
            # =================================================

            old_result = (
                StudentResult.query
                .filter(
                    StudentResult.exam_id
                    == exam.id,

                    StudentResult.student_id
                    == student.id,
                )
                .first()
            )

            old_result_status = None

            if old_result:

                old_result_status = getattr(
                    old_result,
                    "status",
                    None
                )

            # =================================================
            # CALCULATE RESULT
            # =================================================

            calculated_result = (
                calculate_student_result(
                    exam,
                    student.id,
                    exam.institution_id,
                    exam.branch_id,
                )
            )

            if calculated_result is None:

                raise RuntimeError(
                    "Student result calculation did not return a result."
                )

            db.session.flush()

            # =================================================
            # RESTORE RESULT STATUS
            # =================================================

            saved_result = (
                StudentResult.query
                .filter(
                    StudentResult.exam_id
                    == exam.id,

                    StudentResult.student_id
                    == student.id,
                )
                .first()
            )

            if saved_result:

                if old_result_status:

                    saved_result.status = (
                        old_result_status
                    )

                elif not getattr(
                    saved_result,
                    "status",
                    None
                ):

                    saved_result.status = (
                        "draft"
                    )

            # =================================================
            # RANKINGS
            # =================================================

            calculate_exam_rankings(
                exam.id,
                exam.institution_id,
                exam.branch_id,
            )

            db.session.flush()

            # =================================================
            # COMMIT
            # =================================================

            db.session.commit()

            # =================================================
            # BUILD NAVIGATION QUERY
            # =================================================

            navigation_query = (
                StudentEnrollment.query
                .join(
                    Student,
                    Student.id
                    == StudentEnrollment.student_id
                )
                .filter(
                    StudentEnrollment.academic_year_id
                    == exam.academic_year_id,

                    StudentEnrollment.branch_id
                    == exam.branch_id,

                    StudentEnrollment.institution_id
                    == exam.institution_id,

                    Student.branch_id
                    == exam.branch_id,

                    Student.institution_id
                    == exam.institution_id,
                )
            )

            # =================================================
            # EXAM PROGRAM
            # =================================================

            if exam.program_id:

                navigation_query = (
                    navigation_query
                    .filter(
                        StudentEnrollment.program_id
                        == exam.program_id
                    )
                )

            # =================================================
            # SCOPE
            # =================================================

            if scope_type == "class":

                navigation_query = (
                    navigation_query
                    .filter(
                        StudentEnrollment.class_id
                        == class_id
                    )
                )

            elif scope_type == "section":

                navigation_query = (
                    navigation_query
                    .filter(
                        StudentEnrollment.section_id
                        == section_id
                    )
                )

            elif scope_type == "all_program":

                navigation_query = (
                    navigation_query
                    .filter(
                        StudentEnrollment.program_id
                        == program_id
                    )
                )

            # =================================================
            # ACTIVE ENROLLMENTS
            # =================================================

            enrollment_status_column = getattr(
                StudentEnrollment,
                "status",
                None
            )

            if enrollment_status_column is not None:

                navigation_query = (
                    navigation_query
                    .filter(
                        db.func.lower(
                            enrollment_status_column
                        ).in_(
                            [
                                "active",
                                "enrolled",
                            ]
                        )
                    )
                )

            # =================================================
            # NAVIGATION ENROLLMENTS
            # =================================================

            navigation_enrollments = (
                navigation_query
                .order_by(
                    db.func.lower(
                        Student.full_name
                    ).asc(),

                    Student.id.asc()
                )
                .all()
            )

            navigation_student_ids = [
                enrollment_item.student_id
                for enrollment_item
                in navigation_enrollments
                if getattr(
                    enrollment_item,
                    "student_id",
                    None
                )
            ]

            # =================================================
            # LOAD ALL EXAM MARKS FOR NAVIGATION
            #
            # We load all exam marks here, but each student's
            # completeness is checked only against THEIR scoped
            # ExamSubjects.
            # =================================================

            navigation_exam_subject_ids = [
                item.id
                for item in all_exam_subjects
            ]

            navigation_marks = []

            if (
                navigation_student_ids
                and navigation_exam_subject_ids
            ):

                navigation_marks = (
                    Mark.query
                    .filter(
                        Mark.student_id.in_(
                            navigation_student_ids
                        ),

                        Mark.exam_subject_id.in_(
                            navigation_exam_subject_ids
                        ),
                    )
                    .all()
                )

            navigation_marks_by_student = {}

            for mark in navigation_marks:

                navigation_marks_by_student.setdefault(
                    mark.student_id,
                    {}
                )[
                    mark.exam_subject_id
                ] = mark

            navigation_students = []

            # =================================================
            # BUILD NAVIGATION STUDENTS
            # =================================================

            for nav_enrollment in navigation_enrollments:

                nav_student = getattr(
                    nav_enrollment,
                    "student",
                    None
                )

                if not nav_student:
                    continue

                # ---------------------------------------------
                # IMPORTANT:
                # Every student gets THEIR OWN subjects.
                # ---------------------------------------------

                nav_exam_subjects = (
                    subjects_for_enrollment(
                        all_exam_subjects,
                        nav_enrollment
                    )
                )

                nav_mark_map = (
                    navigation_marks_by_student.get(
                        nav_student.id,
                        {}
                    )
                )

                has_missing = False

                for exam_subject in nav_exam_subjects:

                    nav_mark = nav_mark_map.get(
                        exam_subject.id
                    )

                    if nav_mark is None:

                        has_missing = True

                        break

                    if (
                        nav_mark.marks_obtained
                        is None

                        and not nav_mark.is_absent

                        and not nav_mark.is_exempted
                    ):

                        has_missing = True

                        break

                # ------------------------------------------------
                # NO SUBJECTS
                # ------------------------------------------------

                if not nav_exam_subjects:

                    continue

                # ------------------------------------------------
                # COMPLETE STUDENTS ARE HIDDEN
                # ------------------------------------------------

                if not has_missing:

                    continue

                navigation_students.append(
                    nav_student
                )

            # =================================================
            # CURRENT INDEX
            # =================================================

            current_index = None

            for index, nav_student in enumerate(
                navigation_students
            ):

                if nav_student.id == student.id:

                    current_index = index

                    break

            previous_student = None

            next_student = None

            if current_index is not None:

                if current_index > 0:

                    previous_student = (
                        navigation_students[
                            current_index - 1
                        ]
                    )

                if (
                    current_index
                    < len(navigation_students) - 1
                ):

                    next_student = (
                        navigation_students[
                            current_index + 1
                        ]
                    )

            # =================================================
            # DYNAMIC URLS
            # =================================================

            next_url = None

            previous_url = None

            if next_student:

                next_url = url_for(
                    "main.add_exam_result",

                    exam_id=exam.id,

                    scope_type=scope_type,

                    class_id=class_id,

                    section_id=section_id,

                    program_id=program_id,

                    student_id=next_student.id,
                )

            if previous_student:

                previous_url = url_for(
                    "main.add_exam_result",

                    exam_id=exam.id,

                    scope_type=scope_type,

                    class_id=class_id,

                    section_id=section_id,

                    program_id=program_id,

                    student_id=previous_student.id,
                )

            # =================================================
            # EXPLICIT JSON REQUEST
            # =================================================

            if is_json_request:

                return jsonify({

                    "success": True,

                    "message": (
                        f"Marks for "
                        f"{getattr(student, 'full_name', 'student')} "
                        f"were saved successfully."
                    ),

                    "exam_id": exam.id,

                    "student_id": student.id,

                    "current_student": {

                        "id": student.id,

                        "name": getattr(
                            student,
                            "full_name",
                            "Student"
                        ),
                    },

                    "previous_student": (

                        {
                            "id": previous_student.id,

                            "name": getattr(
                                previous_student,
                                "full_name",
                                "Student"
                            ),

                            "url": previous_url,
                        }

                        if previous_student

                        else None
                    ),

                    "next_student": (

                        {
                            "id": next_student.id,

                            "name": getattr(
                                next_student,
                                "full_name",
                                "Student"
                            ),

                            "url": next_url,
                        }

                        if next_student

                        else None
                    ),

                    "previous_url":
                        previous_url,

                    "next_url":
                        next_url,

                    "has_previous": (
                        previous_student
                        is not None
                    ),

                    "has_next": (
                        next_student
                        is not None
                    ),

                    "total_students":
                        len(
                            navigation_students
                        ),

                    "current_index": (
                        current_index + 1
                        if current_index is not None
                        else None
                    ),

                    "navigation": (
                        navigation
                        or "save"
                    ),
                })

            # =================================================
            # NORMAL HTML SUBMISSION
            # =================================================

            flash(
                f"Marks for "
                f"{getattr(student, 'full_name', 'student')} "
                f"were saved successfully.",
                "success"
            )

            # =================================================
            # REDIRECT STUDENT
            # =================================================

            redirect_student_id = (
                student.id
            )

            if (
                navigation == "next"
                and next_student
            ):

                redirect_student_id = (
                    next_student.id
                )

            elif (
                navigation == "previous"
                and previous_student
            ):

                redirect_student_id = (
                    previous_student.id
                )

            return redirect(
                url_for(
                    "main.add_exam_result",

                    exam_id=exam.id,

                    scope_type=scope_type,

                    class_id=class_id,

                    section_id=section_id,

                    program_id=program_id,

                    student_id=redirect_student_id,
                )
            )

        # ====================================================
        # VALIDATION ERROR
        # ====================================================

        except ValueError as exc:

            db.session.rollback()

            if is_json_request:

                return jsonify({
                    "success": False,
                    "message": str(exc),
                }), 400

            flash(
                str(exc),
                "error"
            )

        # ====================================================
        # DATABASE / UNEXPECTED ERROR
        # ====================================================

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "ADD EXAM RESULT FAILED | "
                "exam_id=%s | "
                "student_id=%s | "
                "scope=%s | "
                "class=%s | "
                "section=%s | "
                "program=%s",

                exam_id,

                student_id,

                scope_type,

                class_id,

                section_id,

                program_id,
            )

            if is_json_request:

                return jsonify({
                    "success": False,

                    "message": (
                        "Unable to save the exam result. "
                        "The update was rolled back."
                    ),
                }), 500

            flash(
                "Unable to save the exam result. "
                "The update was rolled back. "
                "Please check the server console for the exact error.",

                "error"
            )

    # ========================================================
    # BUILD DYNAMIC STUDENT LIST
    # ========================================================

    students = []

    if (
        exam
        and scope_type in allowed_scopes
    ):

        enrollment_query = (
            StudentEnrollment.query
            .join(
                Student,
                Student.id
                == StudentEnrollment.student_id
            )
            .filter(
                StudentEnrollment.academic_year_id
                == exam.academic_year_id,

                StudentEnrollment.branch_id
                == exam.branch_id,

                StudentEnrollment.institution_id
                == exam.institution_id,

                Student.institution_id
                == exam.institution_id,

                Student.branch_id
                == exam.branch_id,
            )
        )

        # ====================================================
        # EXAM PROGRAM
        # ====================================================

        if exam.program_id:

            enrollment_query = (
                enrollment_query
                .filter(
                    StudentEnrollment.program_id
                    == exam.program_id
                )
            )

        # ====================================================
        # CLASS
        # ====================================================

        if scope_type == "class":

            if class_id:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        StudentEnrollment.class_id
                        == class_id
                    )
                )

            else:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        db.literal(False)
                    )
                )

        # ====================================================
        # SECTION
        # ====================================================

        elif scope_type == "section":

            if section_id:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        StudentEnrollment.section_id
                        == section_id
                    )
                )

            else:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        db.literal(False)
                    )
                )

        # ====================================================
        # ALL PROGRAM
        # ====================================================

        elif scope_type == "all_program":

            if program_id:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        StudentEnrollment.program_id
                        == program_id
                    )
                )

            else:

                enrollment_query = (
                    enrollment_query
                    .filter(
                        db.literal(False)
                    )
                )

        # ====================================================
        # ALL STUDENTS
        # ====================================================

        elif scope_type == "all_students":

            pass

        # ====================================================
        # ACTIVE ENROLLMENTS
        # ====================================================

        enrollment_status_column = getattr(
            StudentEnrollment,
            "status",
            None
        )

        if enrollment_status_column is not None:

            enrollment_query = (
                enrollment_query
                .filter(
                    db.func.lower(
                        enrollment_status_column
                    ).in_(
                        [
                            "active",
                            "enrolled",
                        ]
                    )
                )
            )

        # ====================================================
        # SORT
        # ====================================================

        enrollments = (
            enrollment_query
            .order_by(
                db.func.lower(
                    Student.full_name
                ).asc(),

                Student.id.asc()
            )
            .all()
        )

        # ====================================================
        # LOAD ALL MARKS ONCE
        # ====================================================

        all_exam_subject_ids = [
            item.id
            for item in all_exam_subjects
        ]

        student_ids = [
            enrollment_item.student_id
            for enrollment_item in enrollments
            if getattr(
                enrollment_item,
                "student_id",
                None
            )
        ]

        all_marks = []

        if (
            student_ids
            and all_exam_subject_ids
        ):

            all_marks = (
                Mark.query
                .filter(
                    Mark.student_id.in_(
                        student_ids
                    ),

                    Mark.exam_subject_id.in_(
                        all_exam_subject_ids
                    ),
                )
                .all()
            )

        # ====================================================
        # MARKS BY STUDENT
        # ====================================================

        marks_by_student = {}

        for mark in all_marks:

            marks_by_student.setdefault(
                mark.student_id,
                {}
            )[
                mark.exam_subject_id
            ] = mark

        # ====================================================
        # BUILD STUDENT LIST
        # ====================================================

        for enrollment_item in enrollments:

            student_obj = getattr(
                enrollment_item,
                "student",
                None
            )

            if not student_obj:
                continue

            # ------------------------------------------------
            # IMPORTANT:
            # Each student gets their own class/section
            # subjects.
            # ------------------------------------------------

            student_exam_subjects = (
                subjects_for_enrollment(
                    all_exam_subjects,
                    enrollment_item
                )
            )

            # ------------------------------------------------
            # No subjects assigned to this student's class.
            # ------------------------------------------------

            if not student_exam_subjects:

                continue

            student_mark_map = (
                marks_by_student.get(
                    student_obj.id,
                    {}
                )
            )

            missing_subject_ids = []

            for exam_subject in (
                student_exam_subjects
            ):

                mark = student_mark_map.get(
                    exam_subject.id
                )

                if mark is None:

                    missing_subject_ids.append(
                        exam_subject.id
                    )

                    continue

                if (
                    mark.marks_obtained
                    is None

                    and not mark.is_absent

                    and not mark.is_exempted
                ):

                    missing_subject_ids.append(
                        exam_subject.id
                    )

            # ------------------------------------------------
            # COMPLETE STUDENTS HIDDEN
            # ------------------------------------------------

            if not missing_subject_ids:

                continue

            students.append({

                "student":
                    student_obj,

                "enrollment":
                    enrollment_item,

                "marks":
                    student_mark_map,

                "missing_subject_ids":
                    missing_subject_ids,

                "missing_count":
                    len(
                        missing_subject_ids
                    ),
            })

    # ========================================================
    # SELECTED STUDENT
    # ========================================================

    selected_student = None

    selected_enrollment = None

    selected_subject_rows = []

    if (
        student_id
        and exam
    ):

        selected_student = (
            Student.query
            .filter(
                Student.id == student_id,

                Student.institution_id
                == exam.institution_id,

                Student.branch_id
                == exam.branch_id,
            )
            .first()
        )

        if selected_student:

            selected_enrollment = (
                StudentEnrollment.query
                .filter(
                    StudentEnrollment.student_id
                    == selected_student.id,

                    StudentEnrollment.academic_year_id
                    == exam.academic_year_id,

                    StudentEnrollment.branch_id
                    == exam.branch_id,

                    StudentEnrollment.institution_id
                    == exam.institution_id,
                )
                .order_by(
                    StudentEnrollment.id.desc()
                )
                .first()
            )

            if selected_enrollment:

                # =============================================
                # IMPORTANT:
                # Scope ExamSubjects to THIS student's class
                # and section.
                # =============================================

                exam_subjects = (
                    subjects_for_enrollment(
                        all_exam_subjects,
                        selected_enrollment
                    )
                )

                # =============================================
                # LOAD MARKS
                # =============================================

                selected_mark_map = {}

                exam_subject_ids = [
                    item.id
                    for item in exam_subjects
                ]

                if exam_subject_ids:

                    selected_marks = (
                        Mark.query
                        .filter(
                            Mark.student_id
                            == selected_student.id,

                            Mark.exam_subject_id.in_(
                                exam_subject_ids
                            ),
                        )
                        .all()
                    )

                    selected_mark_map = {
                        mark.exam_subject_id:
                            mark

                        for mark in selected_marks
                    }

                # =============================================
                # ONLY MISSING SUBJECTS
                # =============================================

                for exam_subject in exam_subjects:

                    mark = selected_mark_map.get(
                        exam_subject.id
                    )

                    is_missing = (

                        mark is None

                        or (

                            mark.marks_obtained
                            is None

                            and not mark.is_absent

                            and not mark.is_exempted
                        )
                    )

                    if not is_missing:

                        continue

                    subject = getattr(
                        exam_subject,
                        "subject",
                        None
                    )

                    subject_name = (
                        getattr(
                            subject,
                            "name",
                            None
                        )

                        or getattr(
                            subject,
                            "title",
                            None
                        )

                        or "Subject"
                    )

                    teacher = getattr(
                        exam_subject,
                        "teacher",
                        None
                    )

                    teacher_name = (
                        getattr(
                            teacher,
                            "full_name",
                            None
                        )

                        or "—"
                    )

                    selected_subject_rows.append({

                        "exam_subject":
                            exam_subject,

                        "mark":
                            mark,

                        "subject_name":
                            subject_name,

                        "teacher_name":
                            teacher_name,

                        "marks": (

                            mark.marks_obtained

                            if (
                                mark
                                and mark.marks_obtained
                                is not None
                            )

                            else None
                        ),

                        "max_marks":
                            exam_subject.max_marks,

                        "pass_marks":
                            exam_subject.pass_marks,

                        "is_absent": (

                            bool(
                                mark.is_absent
                            )

                            if mark

                            else False
                        ),

                        "is_exempted": (

                            bool(
                                mark.is_exempted
                            )

                            if mark

                            else False
                        ),

                        "is_missing":
                            True,
                    })

            else:

                # ------------------------------------------------
                # No enrollment = no student subjects
                # ------------------------------------------------

                exam_subjects = []

    # ========================================================
    # CURRENT / PREVIOUS / NEXT
    # ========================================================

    current_student_index = None

    previous_student = None

    next_student = None

    student_objects = [
        item["student"]
        for item in students
    ]

    if student_id:

        for index, item_student in enumerate(
            student_objects
        ):

            if item_student.id == student_id:

                current_student_index = index

                break

    if current_student_index is not None:

        if current_student_index > 0:

            previous_student = (
                student_objects[
                    current_student_index - 1
                ]
            )

        if (
            current_student_index
            < len(student_objects) - 1
        ):

            next_student = (
                student_objects[
                    current_student_index + 1
                ]
            )

    # ========================================================
    # COUNTS
    # ========================================================

    total_students = len(
        students
    )

    missing_subject_count = sum(
        item["missing_count"]
        for item in students
    )

    selected_missing_count = len(
        selected_subject_rows
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/results/add_exam_result.html",

        # ----------------------------------------------------
        # EXAMS
        # ----------------------------------------------------

        exams=exams,

        exam=exam,

        # ----------------------------------------------------
        # PROGRAM / CLASS / SECTION
        # ----------------------------------------------------

        programs=programs,

        classes=classes,

        sections=sections,

        scope_type=scope_type,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_program_id=program_id,

        selected_student_id=student_id,

        # ----------------------------------------------------
        # STUDENTS
        # ----------------------------------------------------

        students=students,

        total_students=total_students,

        missing_subject_count=
            missing_subject_count,

        # ----------------------------------------------------
        # SELECTED STUDENT
        # ----------------------------------------------------

        selected_student=
            selected_student,

        selected_enrollment=
            selected_enrollment,

        # ----------------------------------------------------
        # SUBJECTS
        #
        # exam_subjects is now:
        #     - selected student's subjects when a student
        #       is selected
        #     - all exam subjects only before a student is
        #       selected
        #
        # subject_rows contains only missing subjects.
        # ----------------------------------------------------

        exam_subjects=
            exam_subjects,

        subject_rows=
            selected_subject_rows,

        selected_subject_rows=
            selected_subject_rows,

        selected_missing_count=
            selected_missing_count,

        # ----------------------------------------------------
        # NAVIGATION
        # ----------------------------------------------------

        current_student_index=
            current_student_index,

        previous_student=
            previous_student,

        next_student=
            next_student,

        page_mode="add",

        can_edit_subject_marks=True,

        can_edit_workflow_status=False,

        user=current_user,

        # ----------------------------------------------------
        # PREVIOUS
        # ----------------------------------------------------

        has_previous=(
            previous_student
            is not None
        ),

        previous_url=(
            url_for(
                "main.add_exam_result",

                exam_id=exam.id,

                scope_type=scope_type,

                class_id=class_id,

                section_id=section_id,

                program_id=program_id,

                student_id=previous_student.id,
            )

            if (
                previous_student
                and exam
            )

            else None
        ),

        # ----------------------------------------------------
        # NEXT
        # ----------------------------------------------------

        has_next=(
            next_student
            is not None
        ),

        next_url=(
            url_for(
                "main.add_exam_result",

                exam_id=exam.id,

                scope_type=scope_type,

                class_id=class_id,

                section_id=section_id,

                program_id=program_id,

                student_id=next_student.id,
            )

            if (
                next_student
                and exam
            )

            else None
        ),
    )


# ============================================================
# EXPORT SAMPLE EXAM RESULT CSV
# ============================================================
# ============================================================

@bp.route(
    "/exam-results/export-sample",
    methods=["GET"]
)
@login_required
def export_sample_exam_result():

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def safe_value(value, default=""):

        if value is None:
            return default

        return str(value).strip()

    def safe_decimal(value, default=Decimal("0")):

        try:

            if value is None:
                return default

            return Decimal(
                str(value)
            )

        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):

            return default

    def clean_csv_value(value):

        if value is None:
            return ""

        return str(value).strip()

    # ========================================================
    # SUBJECT SCOPE HELPER
    # ========================================================
    #
    # SAME LOGIC AS add_exam_result()
    #
    # A student should only receive subjects applicable to
    # his/her enrolled class and section.
    #
    # ========================================================

    def subjects_for_enrollment(
        all_subjects,
        enrollment
    ):

        if not enrollment:
            return []

        enrollment_class_id = getattr(
            enrollment,
            "class_id",
            None
        )

        enrollment_section_id = getattr(
            enrollment,
            "section_id",
            None
        )

        scoped_subjects = []

        for exam_subject in all_subjects:

            subject_class_id = getattr(
                exam_subject,
                "class_id",
                None
            )

            subject_section_id = getattr(
                exam_subject,
                "section_id",
                None
            )

            # ------------------------------------------------
            # CLASS
            # ------------------------------------------------

            if (
                subject_class_id is not None
                and subject_class_id
                != enrollment_class_id
            ):
                continue

            # ------------------------------------------------
            # SECTION
            # ------------------------------------------------

            if (
                subject_section_id is not None
                and subject_section_id
                != enrollment_section_id
            ):
                continue

            scoped_subjects.append(
                exam_subject
            )

        return scoped_subjects

    # ========================================================
    # FIND EXAM
    # ========================================================
    #
    # Use optional ?exam_id=...
    #
    # If exam_id is not supplied, use the newest accessible
    # exam.
    #
    # Example:
    #
    # /exam-results/export-sample?exam_id=12
    #
    # ========================================================

    raw_exam_id = request.args.get(
        "exam_id"
    )

    exam_id = None

    if raw_exam_id:

        try:

            exam_id = int(
                str(raw_exam_id).strip()
            )

        except (
            ValueError,
            TypeError,
        ):

            flash(
                "Invalid examination ID.",
                "error"
            )

            return redirect(
                url_for(
                    "main.add_exam_result"
                )
            )

    # ========================================================
    # EXAM QUERY
    # ========================================================

    exam_query = Exam.query

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id
                == current_institution_id
            )
        )

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id
                == current_institution_id,

                Exam.branch_id
                == current_branch_id,
            )
        )

    # ========================================================
    # SELECT EXAM
    # ========================================================

    if exam_id:

        exam = (
            exam_query
            .filter(
                Exam.id == exam_id
            )
            .first()
        )

    else:

        exam = (
            exam_query
            .order_by(
                Exam.id.desc()
            )
            .first()
        )

    if not exam:

        flash(
            "No examination was found in your access scope.",
            "error"
        )

        return redirect(
            url_for(
                "main.add_exam_result"
            )
        )

    # ========================================================
    # EXAM SUBJECTS
    # ========================================================

    all_exam_subjects = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id
            == exam.id
        )
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    if not all_exam_subjects:

        flash(
            "The selected examination has no subjects assigned.",
            "error"
        )

        return redirect(
            url_for(
                "main.add_exam_result",
                exam_id=exam.id,
            )
        )

    # ========================================================
    # STUDENT ENROLLMENTS
    # ========================================================
    #
    # Only students belonging to this:
    #
    # institution
    # branch
    # academic year
    #
    # are exported.
    #
    # ========================================================

    enrollment_query = (
        StudentEnrollment.query
        .join(
            Student,
            Student.id
            == StudentEnrollment.student_id
        )
        .filter(
            StudentEnrollment.academic_year_id
            == exam.academic_year_id,

            StudentEnrollment.branch_id
            == exam.branch_id,

            StudentEnrollment.institution_id
            == exam.institution_id,

            Student.institution_id
            == exam.institution_id,

            Student.branch_id
            == exam.branch_id,
        )
    )

    # ========================================================
    # EXAM PROGRAM
    # ========================================================

    if exam.program_id:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.program_id
                == exam.program_id
            )
        )

    # ========================================================
    # ACTIVE ENROLLMENTS
    # ========================================================

    enrollment_status_column = getattr(
        StudentEnrollment,
        "status",
        None
    )

    if enrollment_status_column is not None:

        enrollment_query = (
            enrollment_query
            .filter(
                db.func.lower(
                    enrollment_status_column
                ).in_(
                    [
                        "active",
                        "enrolled",
                    ]
                )
            )
        )

    # ========================================================
    # ORDER
    # ========================================================

    enrollments = (
        enrollment_query
        .order_by(
            db.func.lower(
                Student.full_name
            ).asc(),

            Student.id.asc()
        )
        .all()
    )

    if not enrollments:

        flash(
            "No active students were found for this examination.",
            "error"
        )

        return redirect(
            url_for(
                "main.add_exam_result",
                exam_id=exam.id,
            )
        )

    # ========================================================
    # CSV
    # ========================================================

    output = io.StringIO(
        newline=""
    )

    writer = csv.writer(
        output
    )

    # ========================================================
    # CSV HEADER
    # ========================================================

    writer.writerow([
        "exam_id",
        "exam_code",
        "exam_title",
        "exam_type",
        "academic_year_id",
        "term_id",

        "student_id",
        "admission_no",
        "roll_no",
        "student_name",

        "program_id",
        "program_name",

        "class_id",
        "class_name",

        "section_id",
        "section_name",

        "exam_subject_id",
        "subject_id",
        "subject_code",
        "subject_name",

        "teacher_id",
        "teacher_name",

        "max_marks",
        "pass_marks",

        "marks",

        "absent",
        "exempted",

        "remark",
    ])

    # ========================================================
    # SAMPLE MARK COUNTER
    # ========================================================
    #
    # Used to produce deterministic but realistic sample marks.
    #
    # We do NOT use random values because a CSV export should
    # remain predictable during testing.
    #
    # ========================================================

    sample_counter = 0

    # ========================================================
    # STUDENTS
    # ========================================================

    exported_rows = 0

    for enrollment in enrollments:

        student = getattr(
            enrollment,
            "student",
            None
        )

        if not student:
            continue

        # ====================================================
        # STUDENT SUBJECTS
        # ====================================================

        student_exam_subjects = (
            subjects_for_enrollment(
                all_exam_subjects,
                enrollment
            )
        )

        if not student_exam_subjects:
            continue

        # ====================================================
        # PROGRAM
        # ====================================================

        program = getattr(
            enrollment,
            "program",
            None
        )

        program_name = (
            getattr(
                program,
                "name",
                None
            )
            or ""
        )

        # ====================================================
        # CLASS
        # ====================================================

        student_class = None

        enrollment_class_id = getattr(
            enrollment,
            "class_id",
            None
        )

        if enrollment_class_id:

            student_class = (
                Class.query
                .filter(
                    Class.id
                    == enrollment_class_id
                )
                .first()
            )

        class_name = (
            getattr(
                student_class,
                "name",
                None
            )
            or ""
        )

        # ====================================================
        # SECTION
        # ====================================================

        student_section = None

        enrollment_section_id = getattr(
            enrollment,
            "section_id",
            None
        )

        if enrollment_section_id:

            student_section = (
                Section.query
                .filter(
                    Section.id
                    == enrollment_section_id
                )
                .first()
            )

        section_name = (
            getattr(
                student_section,
                "name",
                None
            )
            or ""
        )

        # ====================================================
        # EACH SUBJECT
        # ====================================================

        for exam_subject in student_exam_subjects:

            sample_counter += 1

            subject = getattr(
                exam_subject,
                "subject",
                None
            )

            teacher = getattr(
                exam_subject,
                "teacher",
                None
            )

            # =================================================
            # SUBJECT DATA
            # =================================================

            subject_id = getattr(
                subject,
                "id",
                None
            )

            subject_name = (
                getattr(
                    subject,
                    "name",
                    None
                )
                or getattr(
                    subject,
                    "title",
                    None
                )
                or "Subject"
            )

            subject_code = (
                getattr(
                    subject,
                    "code",
                    None
                )
                or ""
            )

            # =================================================
            # TEACHER DATA
            # =================================================

            teacher_id = getattr(
                teacher,
                "id",
                None
            )

            teacher_name = (
                getattr(
                    teacher,
                    "full_name",
                    None
                )
                or ""
            )

            # =================================================
            # MARK CONFIG
            # =================================================

            max_marks = safe_decimal(
                getattr(
                    exam_subject,
                    "max_marks",
                    None
                ),
                Decimal("100")
            )

            pass_marks = safe_decimal(
                getattr(
                    exam_subject,
                    "pass_marks",
                    None
                ),
                Decimal("50")
            )

            if max_marks <= Decimal("0"):

                max_marks = Decimal(
                    "100"
                )

            # =================================================
            # SAMPLE MARK
            # =================================================
            #
            # Produce marks such as:
            #
            # 62
            # 68
            # 74
            # 81
            # 87
            # 93
            #
            # Always keep it <= max_marks.
            #
            # =================================================

            sample_percentages = [
                Decimal("62"),
                Decimal("68"),
                Decimal("74"),
                Decimal("81"),
                Decimal("87"),
                Decimal("93"),
            ]

            percentage = (
                sample_percentages[
                    (sample_counter - 1)
                    % len(
                        sample_percentages
                    )
                ]
            )

            marks = (
                max_marks
                * percentage
                / Decimal("100")
            )

            # -------------------------------------------------
            # Remove unnecessary decimal places.
            # -------------------------------------------------

            marks = marks.quantize(
                Decimal("0.01")
            )

            # =================================================
            # ABSENT / EXEMPTED
            # =================================================
            #
            # Sample CSV uses normal marks for all rows.
            #
            # This makes the exported file immediately useful
            # for testing normal mark imports.
            #
            # =================================================

            absent = "0"

            exempted = "0"

            remark = (
                "Sample exam result"
            )

            # =================================================
            # CSV ROW
            # =================================================

            writer.writerow([

                # ---------------------------------------------
                # EXAM
                # ---------------------------------------------

                exam.id,

                clean_csv_value(
                    getattr(
                        exam,
                        "code",
                        ""
                    )
                ),

                clean_csv_value(
                    getattr(
                        exam,
                        "title",
                        None
                    )
                    or getattr(
                        exam,
                        "name",
                        None
                    )
                    or ""
                ),

                clean_csv_value(
                    getattr(
                        exam,
                        "exam_type",
                        ""
                    )
                ),

                getattr(
                    exam,
                    "academic_year_id",
                    ""
                ),

                getattr(
                    exam,
                    "term_id",
                    ""
                ),

                # ---------------------------------------------
                # STUDENT
                # ---------------------------------------------

                student.id,

                clean_csv_value(
                    getattr(
                        student,
                        "admission_no",
                        ""
                    )
                ),

                clean_csv_value(
                    getattr(
                        student,
                        "roll_no",
                        ""
                    )
                ),

                clean_csv_value(
                    getattr(
                        student,
                        "full_name",
                        ""
                    )
                ),

                # ---------------------------------------------
                # PROGRAM
                # ---------------------------------------------

                getattr(
                    enrollment,
                    "program_id",
                    ""
                ),

                clean_csv_value(
                    program_name
                ),

                # ---------------------------------------------
                # CLASS
                # ---------------------------------------------

                enrollment_class_id
                or "",

                clean_csv_value(
                    class_name
                ),

                # ---------------------------------------------
                # SECTION
                # ---------------------------------------------

                enrollment_section_id
                or "",

                clean_csv_value(
                    section_name
                ),

                # ---------------------------------------------
                # EXAM SUBJECT
                # ---------------------------------------------

                exam_subject.id,

                subject_id
                or "",

                clean_csv_value(
                    subject_code
                ),

                clean_csv_value(
                    subject_name
                ),

                # ---------------------------------------------
                # TEACHER
                # ---------------------------------------------

                teacher_id
                or "",

                clean_csv_value(
                    teacher_name
                ),

                # ---------------------------------------------
                # MARK CONFIG
                # ---------------------------------------------

                max_marks,

                pass_marks,

                # ---------------------------------------------
                # SAMPLE MARK
                # ---------------------------------------------

                marks,

                # ---------------------------------------------
                # STATUS
                # ---------------------------------------------

                absent,

                exempted,

                # ---------------------------------------------
                # REMARK
                # ---------------------------------------------

                remark,
            ])

            exported_rows += 1

    # ========================================================
    # NO ROWS
    # ========================================================

    if exported_rows == 0:

        flash(
            "No student exam-result rows were available for export.",
            "error"
        )

        return redirect(
            url_for(
                "main.add_exam_result",
                exam_id=exam.id,
            )
        )

    # ========================================================
    # PREPARE RESPONSE
    # ========================================================

    csv_content = output.getvalue()

    output.close()

    # ========================================================
    # FILE NAME
    # ========================================================

    exam_code = clean_csv_value(
        getattr(
            exam,
            "code",
            None
        )
    )

    if not exam_code:

        exam_code = (
            f"exam_{exam.id}"
        )

    # --------------------------------------------------------
    # Remove characters that are unsafe for a filename.
    # --------------------------------------------------------

    safe_filename = re.sub(
        r"[^A-Za-z0-9._-]+",
        "_",
        exam_code
    )

    filename = (
        f"sample_exam_results_"
        f"{safe_filename}.csv"
    )

    # ========================================================
    # DOWNLOAD
    # ========================================================

    response = make_response(
        "\ufeff" + csv_content
    )

    response.headers[
        "Content-Type"
    ] = (
        "text/csv; charset=utf-8"
    )

    response.headers[
        "Content-Disposition"
    ] = (
        f'attachment; filename="{filename}"'
    )

    response.headers[
        "Cache-Control"
    ] = (
        "no-store, no-cache, must-revalidate, max-age=0"
    )

    response.headers[
        "Pragma"
    ] = "no-cache"

    return response



# ============================================================
# EXAM RESULT IMPORT
# ============================================================

@bp.route(
    "/exam-results/import",
    methods=["POST"]
)
@login_required
def import_exam_result():

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

    # ========================================================
    # RESPONSE TYPE
    # ========================================================

    accept_header = (
        request.headers.get(
            "Accept",
            ""
        )
        or ""
    ).lower()

    is_json_request = (
        request.is_json
        or "application/json" in accept_header
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def normalize_text(value):

        if value is None:
            return ""

        return str(value).strip()

    def normalize_key(value):

        value = normalize_text(value)

        value = (
            value
            .lower()
            .replace("-", "_")
            .replace("/", "_")
            .replace(" ", "_")
        )

        value = re.sub(
            r"[^a-z0-9_]+",
            "_",
            value
        )

        value = re.sub(
            r"_+",
            "_",
            value
        )

        return value.strip("_")

    def normalize_status(value):

        value = getattr(
            value,
            "value",
            value
        )

        return (
            str(value).strip().lower()
            if value is not None
            else ""
        )

    def to_int(value):

        if value is None:
            return None

        try:

            text = normalize_text(
                value
            )

            if not text:
                return None

            decimal_value = Decimal(
                text
            )

            if (
                not decimal_value.is_finite()
                or decimal_value
                != decimal_value.to_integral_value()
            ):
                return None

            return int(
                decimal_value
            )

        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):

            return None

    def to_decimal(value):

        if value is None:
            return None

        try:

            text = normalize_text(
                value
            )

            if not text:
                return None

            result = Decimal(
                text
            )

            if not result.is_finite():
                return None

            return result

        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):

            return None

    def truthy_excel_value(value):

        if isinstance(
            value,
            bool
        ):
            return value

        value = normalize_text(
            value
        ).lower()

        return value in {
            "1",
            "true",
            "yes",
            "y",
            "on",
            "x",
        }

    def get_row_value(
        row,
        *names
    ):

        if not row:
            return None

        for name in names:

            key = normalize_key(
                name
            )

            if key not in row:
                continue

            value = row.get(
                key
            )

            if value is not None:
                return value

        return None

    def get_row_mark(row):

        return get_row_value(
            row,
            "marks",
            "mark",
            "marks_obtained",
            "score",
            "score_obtained",
            "grade_mark",
        )

    def get_row_absent(row):

        value = get_row_value(
            row,
            "absent",
            "is_absent",
            "absence",
        )

        return truthy_excel_value(
            value
        )

    def get_row_exempted(row):

        value = get_row_value(
            row,
            "exempted",
            "exempt",
            "is_exempted",
        )

        return truthy_excel_value(
            value
        )

    def get_row_remarks(row):

        value = get_row_value(
            row,
            "remarks",
            "remark",
            "comment",
            "comments",
            "note",
        )

        value = normalize_text(
            value
        )

        return value or None

    def json_response(
        success,
        message,
        status_code=200,
        **extra
    ):

        payload = {
            "success": success,
            "message": message,
        }

        payload.update(
            extra
        )

        return jsonify(
            payload
        ), status_code

    # ========================================================
    # SUBJECT HELPERS
    # ========================================================

    def subject_name(
        exam_subject
    ):

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        return (
            normalize_text(
                getattr(
                    subject,
                    "name",
                    None
                )
            )
            or normalize_text(
                getattr(
                    subject,
                    "title",
                    None
                )
            )
            or "Subject"
        )

    def subject_code(
        exam_subject
    ):

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        return (
            normalize_text(
                getattr(
                    subject,
                    "code",
                    None
                )
            )
            or normalize_text(
                getattr(
                    subject,
                    "short_code",
                    None
                )
            )
        )

    # ========================================================
    # STUDENT SUBJECT SCOPE
    # ========================================================

    def subjects_for_enrollment(
        all_subjects,
        enrollment
    ):

        if not enrollment:
            return []

        enrollment_class_id = getattr(
            enrollment,
            "class_id",
            None
        )

        enrollment_section_id = getattr(
            enrollment,
            "section_id",
            None
        )

        result = []

        for exam_subject in all_subjects:

            subject_class_id = getattr(
                exam_subject,
                "class_id",
                None
            )

            subject_section_id = getattr(
                exam_subject,
                "section_id",
                None
            )

            # ------------------------------------------------
            # CLASS
            # ------------------------------------------------

            if (
                subject_class_id is not None
                and subject_class_id
                != enrollment_class_id
            ):
                continue

            # ------------------------------------------------
            # SECTION
            # ------------------------------------------------

            if (
                subject_section_id is not None
                and subject_section_id
                != enrollment_section_id
            ):
                continue

            result.append(
                exam_subject
            )

        return result

    # ========================================================
    # FILE READER
    #
    # IMPORTANT:
    # Supports both:
    #       CSV
    #       XLSX
    #
    # The sample exporter currently produces CSV.
    # ========================================================

    def read_import_file(
        file_storage
    ):

        if not file_storage:
            raise ValueError(
                "Please select an exam result file."
            )

        filename = (
            file_storage.filename
            or ""
        ).strip().lower()

        if not filename:
            raise ValueError(
                "The uploaded file has no filename."
            )

        # ====================================================
        # CSV
        # ====================================================

        if filename.endswith(
            ".csv"
        ):

            try:

                raw = (
                    file_storage
                    .read()
                )

                if not raw:
                    raise ValueError(
                        "The CSV file is empty."
                    )

                if isinstance(
                    raw,
                    bytes
                ):

                    text = raw.decode(
                        "utf-8-sig"
                    )

                else:

                    text = str(
                        raw
                    )

                reader = csv.reader(
                    io.StringIO(
                        text
                    )
                )

                all_rows = list(
                    reader
                )

            except UnicodeDecodeError:

                raise ValueError(
                    "CSV encoding is not supported. "
                    "Please save the file as UTF-8 CSV."
                )

        # ====================================================
        # XLSX
        # ====================================================

        elif filename.endswith(
            ".xlsx"
        ):

            try:

                workbook = load_workbook(
                    file_storage,
                    read_only=True,
                    data_only=True
                )

            except Exception as exc:

                raise ValueError(
                    "The XLSX file could not be opened."
                ) from exc

            try:

                worksheet = (
                    workbook.active
                )

                all_rows = list(
                    worksheet.iter_rows(
                        values_only=True
                    )
                )

            finally:

                workbook.close()

        else:

            raise ValueError(
                "Only CSV and XLSX files are supported."
            )

        if not all_rows:

            raise ValueError(
                "The uploaded file is empty."
            )

        # ====================================================
        # FIND HEADER
        # ====================================================

        header_index = None

        for index, row in enumerate(
            all_rows
        ):

            if not row:
                continue

            normalized_headers = {
                normalize_key(cell)
                for cell in row
                if cell is not None
            }

            student_headers = {
                "student_id",
                "admission_no",
                "admission_number",
                "roll_no",
                "roll_number",
            }

            subject_headers = {
                "exam_subject_id",
                "subject_id",
                "subject_code",
                "subject_name",
                "subject",
            }

            if (
                normalized_headers
                & student_headers
            ) and (
                normalized_headers
                & subject_headers
            ):

                header_index = index
                break

        if header_index is None:

            raise ValueError(
                "Excel/CSV header was not detected. "
                "The file must contain student and subject fields."
            )

        # ====================================================
        # NORMALIZE HEADERS
        # ====================================================

        header_row = all_rows[
            header_index
        ]

        headers = []

        for index, header in enumerate(
            header_row
        ):

            normalized = normalize_key(
                header
            )

            if not normalized:

                normalized = (
                    f"column_{index + 1}"
                )

            headers.append(
                normalized
            )

        # ====================================================
        # DUPLICATE HEADERS
        # ====================================================

        if len(headers) != len(
            set(headers)
        ):

            duplicates = []

            seen = set()

            for header in headers:

                if header in seen:
                    duplicates.append(
                        header
                    )

                seen.add(
                    header
                )

            raise ValueError(
                "Duplicate column headers detected: "
                + ", ".join(
                    sorted(
                        set(
                            duplicates
                        )
                    )
                )
            )

        # ====================================================
        # DATA
        # ====================================================

        data = []

        for excel_row_number, values in enumerate(
            all_rows[
                header_index + 1:
            ],
            start=header_index + 2
        ):

            if not values:
                continue

            row = {}

            has_data = False

            for index, header in enumerate(
                headers
            ):

                value = (
                    values[index]
                    if index < len(values)
                    else None
                )

                if (
                    value is not None
                    and normalize_text(
                        value
                    )
                ):

                    has_data = True

                row[
                    header
                ] = value

            if not has_data:
                continue

            row[
                "_excel_row"
            ] = excel_row_number

            data.append(
                row
            )

        if not data:

            raise ValueError(
                "The uploaded file contains no data rows."
            )

        return data

    # ========================================================
    # EXAM ID FROM REQUEST
    #
    # IMPORTANT:
    # The current import button does NOT send exam_id.
    #
    # Therefore:
    #       form exam_id
    #       OR query exam_id
    #       OR file exam_id
    #
    # ========================================================

    exam_id = to_int(
        request.form.get(
            "exam_id"
        )
    )

    if not exam_id:

        exam_id = to_int(
            request.args.get(
                "exam_id"
            )
        )

    # ========================================================
    # FILE
    # ========================================================

    uploaded_file = (
        request.files.get(
            "exam_result_file"
        )
        or request.files.get(
            "student_file"
        )
        or request.files.get(
            "file"
        )
        or request.files.get(
            "result_file"
        )
    )

    # ========================================================
    # READ FILE BEFORE REQUIRING EXAM
    #
    # This is the main fix for:
    #
    # "No examination was selected."
    #
    # Because sample file already contains exam_id.
    # ========================================================

    try:

        rows = read_import_file(
            uploaded_file
        )

    except ValueError as exc:

        if is_json_request:

            return json_response(
                False,
                str(exc),
                400
            )

        flash(
            str(exc),
            "error"
        )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result"
            )
        )

    except Exception:

        current_app.logger.exception(
            "EXAM RESULT IMPORT FILE READ FAILED"
        )

        if is_json_request:

            return json_response(
                False,
                "Unable to read the uploaded exam result file.",
                400
            )

        flash(
            "Unable to read the uploaded exam result file.",
            "error"
        )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result"
            )
        )

    # ========================================================
    # INFER EXAM ID FROM FILE
    #
    # Sample exporter contains:
    #
    #       exam_id
    #
    # ========================================================

    if not exam_id:

        file_exam_ids = set()

        for row in rows:

            value = get_row_value(
                row,
                "exam_id",
                "exam",
                "exam_pk",
            )

            parsed = to_int(
                value
            )

            if parsed:
                file_exam_ids.add(
                    parsed
                )

        if len(file_exam_ids) == 1:

            exam_id = next(
                iter(
                    file_exam_ids
                )
            )

        elif len(file_exam_ids) > 1:

            if is_json_request:

                return json_response(
                    False,
                    (
                        "The import file contains "
                        "multiple examination IDs."
                    ),
                    400
                )

            flash(
                (
                    "The import file contains multiple "
                    "examinations. Please use one exam file."
                ),
                "error"
            )

            return redirect(
                request.referrer
                or url_for(
                    "main.add_exam_result"
                )
            )

    # ========================================================
    # EXAM REQUIRED
    # ========================================================

    if not exam_id:

        message = (
            "No examination was selected. "
            "Please export the sample file for the examination "
            "and use that file for import."
        )

        if is_json_request:

            return json_response(
                False,
                message,
                400
            )

        flash(
            message,
            "error"
        )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result"
            )
        )

    # ========================================================
    # EXAM QUERY
    # ========================================================

    exam_query = Exam.query

    if role == "school_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id
                == current_institution_id
            )
        )

    elif role == "branch_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id
                == current_institution_id,

                Exam.branch_id
                == current_branch_id,
            )
        )

    exam = (
        exam_query
        .filter(
            Exam.id
            == exam_id
        )
        .first()
    )

    if not exam:

        message = (
            "The selected examination was not found "
            "or is outside your access scope."
        )

        if is_json_request:

            return json_response(
                False,
                message,
                403
            )

        flash(
            message,
            "error"
        )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result"
            )
        )

    # ========================================================
    # EXTRA SECURITY
    # ========================================================

    if role == "school_admin":

        if (
            exam.institution_id
            != current_institution_id
        ):
            abort(403)

    elif role == "branch_admin":

        if (
            exam.institution_id
            != current_institution_id
            or exam.branch_id
            != current_branch_id
        ):
            abort(403)

    # ========================================================
    # EXAM STATUS
    # ========================================================

    exam_status = normalize_status(
        getattr(
            exam,
            "status",
            None
        )
    )

    if exam_status not in {
        "draft",
        "ongoing",
        "published",
    }:

        message = (
            "Marks can only be imported for draft, "
            "ongoing, or published examinations."
        )

        if is_json_request:

            return json_response(
                False,
                message,
                400
            )

        flash(
            message,
            "error"
        )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result"
            )
        )

    # ========================================================
    # EXAM SUBJECTS
    # ========================================================

    exam_subjects = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id
            == exam.id
        )
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    if not exam_subjects:

        message = (
            "This examination has no subjects assigned."
        )

        if is_json_request:

            return json_response(
                False,
                message,
                400
            )

        flash(
            message,
            "error"
        )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result"
            )
        )

    # ========================================================
    # LOOKUP MAP
    # ========================================================

    exam_subject_by_id = {
        exam_subject.id: exam_subject
        for exam_subject in exam_subjects
    }

    # ========================================================
    # CACHES
    # ========================================================

    student_cache = {}

    enrollment_cache = {}

    existing_mark_cache = {}

    # ========================================================
    # RESULT COLLECTIONS
    # ========================================================

    imported_rows = []

    updated_rows = []

    duplicate_rows = []

    skipped_rows = []

    affected_student_ids = set()

    # ========================================================
    # FILE DUPLICATE PROTECTION
    #
    # One:
    #
    # student + exam_subject
    #
    # can only be imported once.
    # ========================================================

    imported_keys = set()

    # ========================================================
    # PROCESS ROWS
    # ========================================================

    try:

        for row in rows:

            excel_row_number = row.get(
                "_excel_row"
            )

            # =================================================
            # STUDENT IDENTIFIER
            # =================================================

            raw_student_id = get_row_value(
                row,
                "student_id",
                "student_pk",
            )

            raw_admission_no = get_row_value(
                row,
                "admission_no",
                "admission_number",
                "admission",
            )

            raw_roll_no = get_row_value(
                row,
                "roll_no",
                "roll_number",
                "roll",
            )

            student_id_value = to_int(
                raw_student_id
            )

            admission_no = normalize_text(
                raw_admission_no
            )

            roll_no = normalize_text(
                raw_roll_no
            )

            if not any([
                student_id_value,
                admission_no,
                roll_no,
            ]):

                skipped_rows.append({
                    "row": excel_row_number,
                    "reason": (
                        "Student identifier is missing. "
                        "Use student_id, admission_no, or roll_no."
                    ),
                })

                continue

            # =================================================
            # STUDENT CACHE
            # =================================================

            cache_key = (
                f"id:{student_id_value}"
                if student_id_value
                else
                f"admission:{admission_no.lower()}"
                if admission_no
                else
                f"roll:{roll_no.lower()}"
            )

            student = student_cache.get(
                cache_key
            )

            if student is None:

                student_query = (
                    Student.query
                    .filter(
                        Student.institution_id
                        == exam.institution_id,

                        Student.branch_id
                        == exam.branch_id,
                    )
                )

                # ---------------------------------------------
                # STUDENT ID
                # ---------------------------------------------

                if student_id_value:

                    student = (
                        student_query
                        .filter(
                            Student.id
                            == student_id_value
                        )
                        .first()
                    )

                # ---------------------------------------------
                # ADMISSION NO
                # ---------------------------------------------

                if (
                    student is None
                    and admission_no
                ):

                    student = (
                        student_query
                        .filter(
                            db.func.lower(
                                Student.admission_no
                            )
                            == admission_no.lower()
                        )
                        .first()
                    )

                # ---------------------------------------------
                # ROLL NO
                # ---------------------------------------------

                if (
                    student is None
                    and roll_no
                ):

                    student = (
                        student_query
                        .filter(
                            db.func.lower(
                                Student.roll_no
                            )
                            == roll_no.lower()
                        )
                        .first()
                    )

                if student:

                    student_cache[
                        cache_key
                    ] = student

            # =================================================
            # STUDENT NOT FOUND
            # =================================================

            if not student:

                skipped_rows.append({
                    "row": excel_row_number,
                    "student": (
                        admission_no
                        or roll_no
                        or student_id_value
                    ),
                    "reason": (
                        "Student was not found inside "
                        "this examination institution/branch."
                    ),
                })

                continue

            # =================================================
            # ENROLLMENT
            # =================================================

            enrollment = enrollment_cache.get(
                student.id
            )

            if enrollment is None:

                enrollment = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.student_id
                        == student.id,

                        StudentEnrollment.academic_year_id
                        == exam.academic_year_id,

                        StudentEnrollment.branch_id
                        == exam.branch_id,

                        StudentEnrollment.institution_id
                        == exam.institution_id,
                    )
                    .order_by(
                        StudentEnrollment.id.desc()
                    )
                    .first()
                )

                if enrollment:

                    enrollment_cache[
                        student.id
                    ] = enrollment

            if not enrollment:

                skipped_rows.append({
                    "row": excel_row_number,
                    "student": (
                        getattr(
                            student,
                            "full_name",
                            None
                        )
                        or student.id
                    ),
                    "reason": (
                        "Student has no enrollment "
                        "for this examination academic year."
                    ),
                })

                continue

            # =================================================
            # ENROLLMENT STATUS
            # =================================================

            enrollment_status = normalize_status(
                getattr(
                    enrollment,
                    "status",
                    None
                )
            )

            if (
                enrollment_status
                and enrollment_status
                not in {
                    "active",
                    "enrolled",
                }
            ):

                skipped_rows.append({
                    "row": excel_row_number,
                    "student": (
                        getattr(
                            student,
                            "full_name",
                            None
                        )
                        or student.id
                    ),
                    "reason": (
                        "Student enrollment is not active."
                    ),
                })

                continue

            # =================================================
            # PROGRAM SECURITY
            # =================================================

            if exam.program_id:

                if (
                    getattr(
                        enrollment,
                        "program_id",
                        None
                    )
                    != exam.program_id
                ):

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": (
                            getattr(
                                student,
                                "full_name",
                                None
                            )
                            or student.id
                        ),
                        "reason": (
                            "Student does not belong "
                            "to the examination program."
                        ),
                    })

                    continue

            # =================================================
            # STUDENT EXAM SUBJECTS
            # =================================================

            student_exam_subjects = (
                subjects_for_enrollment(
                    exam_subjects,
                    enrollment
                )
            )

            if not student_exam_subjects:

                skipped_rows.append({
                    "row": excel_row_number,
                    "student": (
                        getattr(
                            student,
                            "full_name",
                            None
                        )
                        or student.id
                    ),
                    "reason": (
                        "No ExamSubject is assigned "
                        "to the student's class/section."
                    ),
                })

                continue

            # =================================================
            # SUBJECT IDENTIFIERS
            # =================================================

            raw_exam_subject_id = get_row_value(
                row,
                "exam_subject_id",
                "exam_subject",
                "exam_subject_pk",
            )

            raw_subject_id = get_row_value(
                row,
                "subject_id"
            )

            raw_subject_code = get_row_value(
                row,
                "subject_code",
                "code",
                "subject_short_code",
            )

            raw_subject_name = get_row_value(
                row,
                "subject_name",
                "subject",
                "name",
            )

            exam_subject_id = to_int(
                raw_exam_subject_id
            )

            subject_id = to_int(
                raw_subject_id
            )

            subject_code_value = normalize_text(
                raw_subject_code
            )

            subject_name_value = normalize_text(
                raw_subject_name
            )

            matched_exam_subject = None

            # =================================================
            # EXAM SUBJECT ID
            # =================================================

            if exam_subject_id:

                candidate = (
                    exam_subject_by_id.get(
                        exam_subject_id
                    )
                )

                if candidate is None:

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "reason": (
                            "ExamSubject ID was not found "
                            "inside this examination."
                        ),
                    })

                    continue

                if candidate not in student_exam_subjects:

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "reason": (
                            "ExamSubject does not belong "
                            "to the student's class/section."
                        ),
                    })

                    continue

                matched_exam_subject = candidate

            # =================================================
            # SUBJECT ID
            # =================================================

            if (
                matched_exam_subject is None
                and subject_id
            ):

                candidates = []

                for candidate in student_exam_subjects:

                    subject = getattr(
                        candidate,
                        "subject",
                        None
                    )

                    candidate_subject_id = getattr(
                        subject,
                        "id",
                        None
                    )

                    if (
                        candidate_subject_id
                        == subject_id
                    ):

                        candidates.append(
                            candidate
                        )

                if len(candidates) == 1:

                    matched_exam_subject = (
                        candidates[0]
                    )

                elif len(candidates) > 1:

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "reason": (
                            "Multiple ExamSubjects match "
                            "this subject_id. Use exam_subject_id."
                        ),
                    })

                    continue

            # =================================================
            # SUBJECT CODE
            # =================================================

            if (
                matched_exam_subject is None
                and subject_code_value
            ):

                candidates = [
                    candidate
                    for candidate
                    in student_exam_subjects
                    if (
                        subject_code(candidate)
                        and
                        normalize_key(
                            subject_code(candidate)
                        )
                        ==
                        normalize_key(
                            subject_code_value
                        )
                    )
                ]

                if len(candidates) == 1:

                    matched_exam_subject = (
                        candidates[0]
                    )

                elif len(candidates) > 1:

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "reason": (
                            f"Multiple ExamSubjects match "
                            f"subject code '{subject_code_value}'. "
                            "Use exam_subject_id."
                        ),
                    })

                    continue

            # =================================================
            # SUBJECT NAME
            # =================================================

            if (
                matched_exam_subject is None
                and subject_name_value
            ):

                candidates = [
                    candidate
                    for candidate
                    in student_exam_subjects
                    if (
                        normalize_key(
                            subject_name(candidate)
                        )
                        ==
                        normalize_key(
                            subject_name_value
                        )
                    )
                ]

                if len(candidates) == 1:

                    matched_exam_subject = (
                        candidates[0]
                    )

                elif len(candidates) > 1:

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "reason": (
                            f"Multiple ExamSubjects match "
                            f"subject name '{subject_name_value}'. "
                            "Use exam_subject_id."
                        ),
                    })

                    continue

            # =================================================
            # SUBJECT NOT FOUND
            # =================================================

            if matched_exam_subject is None:

                skipped_rows.append({
                    "row": excel_row_number,
                    "student": student.id,
                    "subject": (
                        subject_code_value
                        or subject_name_value
                        or exam_subject_id
                        or subject_id
                        or "Unknown"
                    ),
                    "reason": (
                        "ExamSubject was not found for "
                        "the student's class/section."
                    ),
                })

                continue

            # =================================================
            # MARK VALUES
            # =================================================

            raw_marks = get_row_mark(
                row
            )

            raw_marks_text = normalize_text(
                raw_marks
            )

            is_absent = get_row_absent(
                row
            )

            is_exempted = get_row_exempted(
                row
            )

            remarks = get_row_remarks(
                row
            )

            # =================================================
            # ABSENT + EXEMPTED
            # =================================================

            if (
                is_absent
                and is_exempted
            ):

                skipped_rows.append({
                    "row": excel_row_number,
                    "student": student.id,
                    "subject": subject_name(
                        matched_exam_subject
                    ),
                    "reason": (
                        "A result cannot be both "
                        "absent and exempted."
                    ),
                })

                continue

            # =================================================
            # EMPTY
            # =================================================

            if (
                not raw_marks_text
                and not is_absent
                and not is_exempted
            ):

                skipped_rows.append({
                    "row": excel_row_number,
                    "student": student.id,
                    "subject": subject_name(
                        matched_exam_subject
                    ),
                    "reason": (
                        "No marks, absent status, "
                        "or exempted status was supplied."
                    ),
                })

                continue

            # =================================================
            # FILE DUPLICATE
            # =================================================

            import_key = (
                student.id,
                matched_exam_subject.id
            )

            if import_key in imported_keys:

                duplicate_rows.append({
                    "row": excel_row_number,
                    "student": (
                        getattr(
                            student,
                            "full_name",
                            None
                        )
                        or student.id
                    ),
                    "student_id": student.id,
                    "subject": subject_name(
                        matched_exam_subject
                    ),
                    "exam_subject_id": (
                        matched_exam_subject.id
                    ),
                    "reason": (
                        "The same student and subject "
                        "appeared more than once in the file."
                    ),
                })

                continue

            # =================================================
            # MARK LOOKUP
            # =================================================

            mark = existing_mark_cache.get(
                import_key
            )

            if mark is None:

                mark = (
                    Mark.query
                    .filter(
                        Mark.student_id
                        == student.id,

                        Mark.exam_subject_id
                        == matched_exam_subject.id,
                    )
                    .first()
                )

                existing_mark_cache[
                    import_key
                ] = mark

            # =================================================
            # EXISTING MARK
            # =================================================

            if mark:

                existing_has_marks = (
                    getattr(
                        mark,
                        "marks_obtained",
                        None
                    )
                    is not None
                )

                existing_absent = bool(
                    getattr(
                        mark,
                        "is_absent",
                        False
                    )
                )

                existing_exempted = bool(
                    getattr(
                        mark,
                        "is_exempted",
                        False
                    )
                )

                existing_complete = (
                    existing_has_marks
                    or existing_absent
                    or existing_exempted
                )

                # ---------------------------------------------
                # COMPLETE = DUPLICATE
                # ---------------------------------------------

                if existing_complete:

                    duplicate_rows.append({
                        "row": excel_row_number,
                        "student": (
                            getattr(
                                student,
                                "full_name",
                                None
                            )
                            or student.id
                        ),
                        "student_id": student.id,
                        "subject": subject_name(
                            matched_exam_subject
                        ),
                        "exam_subject_id": (
                            matched_exam_subject.id
                        ),
                        "reason": (
                            "A complete result already exists "
                            "for this student and subject."
                        ),
                    })

                    continue

            # =================================================
            # MARK VALIDATION
            # =================================================

            marks = None

            if (
                not is_absent
                and not is_exempted
            ):

                marks = to_decimal(
                    raw_marks
                )

                if marks is None:

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "subject": subject_name(
                            matched_exam_subject
                        ),
                        "reason": (
                            f"Invalid marks value "
                            f"'{raw_marks_text}'."
                        ),
                    })

                    continue

                if marks < Decimal("0"):

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "subject": subject_name(
                            matched_exam_subject
                        ),
                        "reason": (
                            "Marks cannot be negative."
                        ),
                    })

                    continue

                max_marks = to_decimal(
                    getattr(
                        matched_exam_subject,
                        "max_marks",
                        None
                    )
                )

                if (
                    max_marks is None
                    or max_marks <= Decimal("0")
                ):

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "subject": subject_name(
                            matched_exam_subject
                        ),
                        "reason": (
                            "ExamSubject maximum marks "
                            "are not configured correctly."
                        ),
                    })

                    continue

                if marks > max_marks:

                    skipped_rows.append({
                        "row": excel_row_number,
                        "student": student.id,
                        "subject": subject_name(
                            matched_exam_subject
                        ),
                        "marks": str(
                            marks
                        ),
                        "max_marks": str(
                            max_marks
                        ),
                        "reason": (
                            "Marks exceed the configured "
                            "maximum marks."
                        ),
                    })

                    continue

            # =================================================
            # INSERT / UPDATE
            # =================================================

            if mark is None:

                mark = Mark(
                    exam_subject_id=(
                        matched_exam_subject.id
                    ),

                    student_id=student.id,

                    marks_obtained=(
                        None
                        if (
                            is_absent
                            or is_exempted
                        )
                        else marks
                    ),

                    is_absent=is_absent,

                    is_exempted=is_exempted,

                    remarks=remarks,

                    status="submitted",

                    entered_by=getattr(
                        current_user,
                        "id",
                        None
                    ),
                )

                db.session.add(
                    mark
                )

                imported_rows.append({
                    "row": excel_row_number,
                    "student": (
                        getattr(
                            student,
                            "full_name",
                            None
                        )
                        or student.id
                    ),
                    "student_id": student.id,
                    "subject": subject_name(
                        matched_exam_subject
                    ),
                    "exam_subject_id": (
                        matched_exam_subject.id
                    ),
                    "marks": (
                        "ABSENT"
                        if is_absent
                        else
                        "EXEMPTED"
                        if is_exempted
                        else
                        str(marks)
                    ),
                    "action": "imported",
                })

            else:

                # ---------------------------------------------
                # EXISTING INCOMPLETE MARK
                # ---------------------------------------------

                mark.marks_obtained = (
                    None
                    if (
                        is_absent
                        or is_exempted
                    )
                    else marks
                )

                mark.is_absent = (
                    is_absent
                )

                mark.is_exempted = (
                    is_exempted
                )

                mark.remarks = remarks

                mark.status = (
                    "submitted"
                )

                if hasattr(
                    mark,
                    "entered_by"
                ):

                    mark.entered_by = getattr(
                        current_user,
                        "id",
                        None
                    )

                updated_rows.append({
                    "row": excel_row_number,
                    "student": (
                        getattr(
                            student,
                            "full_name",
                            None
                        )
                        or student.id
                    ),
                    "student_id": student.id,
                    "subject": subject_name(
                        matched_exam_subject
                    ),
                    "exam_subject_id": (
                        matched_exam_subject.id
                    ),
                    "marks": (
                        "ABSENT"
                        if is_absent
                        else
                        "EXEMPTED"
                        if is_exempted
                        else
                        str(marks)
                    ),
                    "action": "updated",
                })

            # =================================================
            # MARK IMPORT KEY
            # =================================================

            imported_keys.add(
                import_key
            )

            affected_student_ids.add(
                student.id
            )

        # ====================================================
        # NOTHING CHANGED
        # ====================================================

        if not affected_student_ids:

            db.session.rollback()

            summary = {
                "total_rows": len(
                    rows
                ),
                "imported": 0,
                "updated": 0,
                "duplicates": len(
                    duplicate_rows
                ),
                "skipped": len(
                    skipped_rows
                ),
                "students_calculated": 0,
            }

            message = (
                "No new exam results were imported. "
                "All rows were duplicate or skipped."
            )

            if is_json_request:

                return json_response(
                    True,
                    message,
                    200,
                    exam_id=exam.id,
                    summary=summary,
                    imported_rows=imported_rows,
                    updated_rows=updated_rows,
                    duplicate_rows=duplicate_rows,
                    skipped_rows=skipped_rows,
                )

            flash(
                message,
                "warning"
            )

            return redirect(
                request.referrer
                or url_for(
                    "main.add_exam_result",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # FLUSH
        # ====================================================

        db.session.flush()

        # ====================================================
        # CALCULATE STUDENT RESULTS
        # ====================================================

        calculated_students = []

        for student_id in sorted(
            affected_student_ids
        ):

            calculated_result = (
                calculate_student_result(
                    exam,
                    student_id,
                    exam.institution_id,
                    exam.branch_id,
                )
            )

            if calculated_result is None:

                raise RuntimeError(
                    "Student result calculation failed "
                    f"for student_id={student_id}."
                )

            calculated_students.append(
                student_id
            )

            db.session.flush()

        # ====================================================
        # CALCULATE RANKINGS
        # ====================================================

        calculate_exam_rankings(
            exam.id,
            exam.institution_id,
            exam.branch_id,
        )

        db.session.flush()

        # ====================================================
        # COMMIT
        # ====================================================

        db.session.commit()

        # ====================================================
        # SUMMARY
        # ====================================================

        summary = {
            "total_rows": len(
                rows
            ),

            "imported": len(
                imported_rows
            ),

            "updated": len(
                updated_rows
            ),

            "duplicates": len(
                duplicate_rows
            ),

            "skipped": len(
                skipped_rows
            ),

            "students_calculated": len(
                calculated_students
            ),
        }

        message = (
            f"Exam result import completed: "
            f"{summary['imported']} imported, "
            f"{summary['updated']} updated, "
            f"{summary['duplicates']} duplicates, "
            f"{summary['skipped']} skipped."
        )

        # ====================================================
        # JSON
        # ====================================================

        if is_json_request:

            return json_response(
                True,
                message,
                200,

                exam_id=exam.id,

                summary=summary,

                imported_rows=(
                    imported_rows
                ),

                updated_rows=(
                    updated_rows
                ),

                duplicate_rows=(
                    duplicate_rows
                ),

                skipped_rows=(
                    skipped_rows
                ),
            )

        # ====================================================
        # HTML
        #
        # NO SEPARATE IMPORT PAGE.
        #
        # Return to the page where the import button exists.
        # ====================================================

        flash(
            message,
            "success"
        )

        # ----------------------------------------------------
        # Separate flash messages for each category
        # ----------------------------------------------------

        if imported_rows:

            flash(
                f"{len(imported_rows)} result(s) imported.",
                "success"
            )

        if updated_rows:

            flash(
                f"{len(updated_rows)} incomplete result(s) updated.",
                "info"
            )

        if duplicate_rows:

            flash(
                f"{len(duplicate_rows)} duplicate result(s) skipped.",
                "warning"
            )

        if skipped_rows:

            flash(
                f"{len(skipped_rows)} invalid/unmatched row(s) skipped.",
                "warning"
            )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result",
                exam_id=exam.id
            )
        )

    # ========================================================
    # TRANSACTION / UNEXPECTED ERROR
    # ========================================================

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "EXAM RESULT IMPORT FAILED | exam_id=%s",
            exam.id
        )

        if is_json_request:

            return json_response(
                False,
                (
                    "Unable to import exam results. "
                    "The complete import was rolled back."
                ),
                500
            )

        flash(
            (
                "Unable to import exam results. "
                "The complete import was rolled back. "
                "Please check the server log."
            ),
            "error"
        )

        return redirect(
            request.referrer
            or url_for(
                "main.add_exam_result",
                exam_id=exam.id
            )
        )



# ============================================================
# PRINT STUDENT EXAM RESULT
# ============================================================
# ============================================================

@bp.route(
    "/exam-results/<int:result_id>/print",
    methods=["GET"]
)
@login_required
def print_student_exam_result(result_id):

    # ========================================================
    # IMPORTS / DECIMAL
    # ========================================================

    from decimal import Decimal, InvalidOperation

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD RESULT
    # ========================================================

    result_query = (
        StudentResult.query
        .options(
            db.joinedload(
                StudentResult.student
            ),
            db.joinedload(
                StudentResult.exam
            ),
        )
        .filter(
            StudentResult.id == result_id
        )
    )

    # ========================================================
    # SCHOOL ADMIN SCOPE
    # ========================================================

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        result_query = (
            result_query
            .join(
                Exam,
                Exam.id
                == StudentResult.exam_id
            )
            .filter(
                Exam.institution_id
                == current_institution_id
            )
        )

    # ========================================================
    # BRANCH ADMIN SCOPE
    # ========================================================

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        result_query = (
            result_query
            .join(
                Exam,
                Exam.id
                == StudentResult.exam_id
            )
            .filter(
                Exam.institution_id
                == current_institution_id,

                Exam.branch_id
                == current_branch_id,
            )
        )

    # ========================================================
    # GET RESULT
    # ========================================================

    result = (
        result_query
        .first()
    )

    if not result:
        abort(404)

    # ========================================================
    # EXAM
    # ========================================================

    exam = getattr(
        result,
        "exam",
        None
    )

    if not exam:
        abort(404)

    # ========================================================
    # STUDENT
    # ========================================================

    student = getattr(
        result,
        "student",
        None
    )

    if not student:
        abort(404)

    # ========================================================
    # EXTRA SECURITY
    # ========================================================

    exam_institution_id = getattr(
        exam,
        "institution_id",
        None
    )

    exam_branch_id = getattr(
        exam,
        "branch_id",
        None
    )

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if role == "school_admin":

        if (
            exam_institution_id
            != current_institution_id
        ):
            abort(403)

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif role == "branch_admin":

        if (
            exam_institution_id
            != current_institution_id
        ):
            abort(403)

        if (
            exam_branch_id
            != current_branch_id
        ):
            abort(403)

    # ========================================================
    # STUDENT SECURITY
    # ========================================================

    student_institution_id = getattr(
        student,
        "institution_id",
        None
    )

    student_branch_id = getattr(
        student,
        "branch_id",
        None
    )

    if (
        student_institution_id
        != exam_institution_id
    ):
        abort(403)

    if (
        student_branch_id
        != exam_branch_id
    ):
        abort(403)

    # ========================================================
    # SITE SETTINGS
    # ========================================================

    site_settings = (
        SiteSettings.query
        .filter(
            SiteSettings.institution_id
            == exam_institution_id
        )
        .first()
    )

    # ========================================================
    # STUDENT ENROLLMENT
    # ========================================================

    enrollment = (
        StudentEnrollment.query
        .filter(
            StudentEnrollment.student_id
            == student.id,

            StudentEnrollment.academic_year_id
            == exam.academic_year_id,

            StudentEnrollment.institution_id
            == exam_institution_id,

            StudentEnrollment.branch_id
            == exam_branch_id,
        )
        .order_by(
            StudentEnrollment.id.desc()
        )
        .first()
    )

    # ========================================================
    # CLASS
    # ========================================================

    student_class = None

    if enrollment:

        class_id = getattr(
            enrollment,
            "class_id",
            None
        )

        if class_id:

            student_class = (
                Class.query
                .filter(
                    Class.id == class_id
                )
                .first()
            )

    # ========================================================
    # SECTION
    # ========================================================

    student_section = None

    if enrollment:

        section_id = getattr(
            enrollment,
            "section_id",
            None
        )

        if section_id:

            student_section = (
                Section.query
                .filter(
                    Section.id == section_id
                )
                .first()
            )

    # ========================================================
    # PROGRAM
    # ========================================================

    program = None

    if enrollment:

        enrollment_program_id = getattr(
            enrollment,
            "program_id",
            None
        )

        if enrollment_program_id:

            program = (
                Program.query
                .filter(
                    Program.id
                    == enrollment_program_id
                )
                .first()
            )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    academic_year = getattr(
        exam,
        "academic_year",
        None
    )

    if academic_year is None and enrollment:

        academic_year = getattr(
            enrollment,
            "academic_year",
            None
        )

    # ========================================================
    # TERM
    # ========================================================

    term = getattr(
        exam,
        "term",
        None
    )

    # ========================================================
    # EXAM SUBJECTS
    # ========================================================

    all_exam_subjects = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id
            == exam.id
        )
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )

    # ========================================================
    # SUBJECT SCOPE
    # ========================================================

    exam_subjects = []

    if enrollment:

        enrollment_class_id = getattr(
            enrollment,
            "class_id",
            None
        )

        enrollment_section_id = getattr(
            enrollment,
            "section_id",
            None
        )

        for exam_subject in all_exam_subjects:

            subject_class_id = getattr(
                exam_subject,
                "class_id",
                None
            )

            subject_section_id = getattr(
                exam_subject,
                "section_id",
                None
            )

            # ------------------------------------------------
            # CLASS FILTER
            # ------------------------------------------------

            if (
                subject_class_id is not None
                and subject_class_id
                != enrollment_class_id
            ):
                continue

            # ------------------------------------------------
            # SECTION FILTER
            # ------------------------------------------------

            if (
                subject_section_id is not None
                and subject_section_id
                != enrollment_section_id
            ):
                continue

            exam_subjects.append(
                exam_subject
            )

    # ========================================================
    # EXAM SUBJECT IDS
    # ========================================================

    exam_subject_ids = [
        exam_subject.id
        for exam_subject in exam_subjects
    ]

    # ========================================================
    # MARKS
    # ========================================================

    marks = []

    if exam_subject_ids:

        marks = (
            Mark.query
            .filter(
                Mark.student_id
                == student.id,

                Mark.exam_subject_id.in_(
                    exam_subject_ids
                ),
            )
            .all()
        )

    # ========================================================
    # MARK MAP
    # ========================================================

    mark_map = {
        mark.exam_subject_id: mark
        for mark in marks
    }

    # ========================================================
    # RESULT SUBJECT ROWS
    # ========================================================

    subject_rows = []

    calculated_total = Decimal("0")

    calculated_maximum = Decimal("0")

    # ========================================================
    # PROCESS SUBJECTS
    # ========================================================

    for exam_subject in exam_subjects:

        subject = getattr(
            exam_subject,
            "subject",
            None
        )

        teacher = getattr(
            exam_subject,
            "teacher",
            None
        )

        # ----------------------------------------------------
        # SUBJECT NAME
        # ----------------------------------------------------

        subject_name = (
            getattr(
                subject,
                "name",
                None
            )
            or getattr(
                subject,
                "title",
                None
            )
            or "Subject"
        )

        # ----------------------------------------------------
        # SUBJECT CODE
        # ----------------------------------------------------

        subject_code = (
            getattr(
                subject,
                "code",
                None
            )
            or getattr(
                exam_subject,
                "subject_code",
                None
            )
            or "—"
        )

        # ----------------------------------------------------
        # TEACHER
        # ----------------------------------------------------

        teacher_name = (
            getattr(
                teacher,
                "full_name",
                None
            )
            or "—"
        )

        # ----------------------------------------------------
        # MARK
        # ----------------------------------------------------

        mark = mark_map.get(
            exam_subject.id
        )

        # ----------------------------------------------------
        # MAX MARKS
        # ----------------------------------------------------

        max_marks_raw = getattr(
            exam_subject,
            "max_marks",
            None
        )

        try:

            max_marks = Decimal(
                str(
                    max_marks_raw
                    if max_marks_raw is not None
                    else 0
                )
            )

        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):

            max_marks = Decimal("0")

        # ----------------------------------------------------
        # PASS MARKS
        # ----------------------------------------------------

        pass_marks_raw = getattr(
            exam_subject,
            "pass_marks",
            None
        )

        try:

            pass_marks = Decimal(
                str(
                    pass_marks_raw
                    if pass_marks_raw is not None
                    else 0
                )
            )

        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):

            pass_marks = Decimal("0")

        # ----------------------------------------------------
        # OBTAINED MARKS
        # ----------------------------------------------------

        marks_obtained = None

        if mark:

            raw_mark = getattr(
                mark,
                "marks_obtained",
                None
            )

            if raw_mark is not None:

                try:

                    marks_obtained = Decimal(
                        str(raw_mark)
                    )

                except (
                    InvalidOperation,
                    ValueError,
                    TypeError,
                ):

                    marks_obtained = None

        # ----------------------------------------------------
        # ABSENT
        # ----------------------------------------------------

        is_absent = (
            bool(
                getattr(
                    mark,
                    "is_absent",
                    False
                )
            )
            if mark
            else False
        )

        # ----------------------------------------------------
        # EXEMPTED
        # ----------------------------------------------------

        is_exempted = (
            bool(
                getattr(
                    mark,
                    "is_exempted",
                    False
                )
            )
            if mark
            else False
        )

        # ----------------------------------------------------
        # REMARK
        # ----------------------------------------------------

        remark = (
            getattr(
                mark,
                "remarks",
                None
            )
            if mark
            else None
        )

        # ----------------------------------------------------
        # SUBJECT STATUS
        # ----------------------------------------------------

        if is_absent:

            subject_status = "ABSENT"

        elif is_exempted:

            subject_status = "EXEMPTED"

        elif marks_obtained is None:

            subject_status = "MISSING"

        elif marks_obtained >= pass_marks:

            subject_status = "PASS"

        else:

            subject_status = "FAIL"

        # ----------------------------------------------------
        # TOTALS
        #
        # Missing / absent / exempted are NOT zero.
        # ----------------------------------------------------

        if (
            marks_obtained is not None
            and not is_absent
            and not is_exempted
        ):

            calculated_total += (
                marks_obtained
            )

            if max_marks > Decimal("0"):

                calculated_maximum += (
                    max_marks
                )

        # ----------------------------------------------------
        # ROW
        # ----------------------------------------------------

        subject_rows.append({

            "exam_subject":
                exam_subject,

            "subject":
                subject,

            "teacher":
                teacher,

            "subject_name":
                subject_name,

            "subject_code":
                subject_code,

            "teacher_name":
                teacher_name,

            "mark":
                mark,

            "marks":
                marks_obtained,

            "max_marks":
                max_marks,

            "pass_marks":
                pass_marks,

            "is_absent":
                is_absent,

            "is_exempted":
                is_exempted,

            "status":
                subject_status,

            "remark":
                remark,
        })

    # ========================================================
    # CALCULATED PERCENTAGE
    # ========================================================

    calculated_percentage = Decimal("0")

    if calculated_maximum > Decimal("0"):

        calculated_percentage = (
            calculated_total
            / calculated_maximum
        ) * Decimal("100")

    # ========================================================
    # RESULT TOTAL
    # ========================================================

    result_total = getattr(
        result,
        "total_marks",
        None
    )

    if result_total is None:

        result_total = calculated_total

    # ========================================================
    # RESULT MAXIMUM
    # ========================================================

    result_maximum = getattr(
        result,
        "total_max_marks",
        None
    )

    if result_maximum is None:

        result_maximum = calculated_maximum

    # ========================================================
    # RESULT PERCENTAGE
    # ========================================================

    result_percentage = getattr(
        result,
        "percentage",
        None
    )

    if result_percentage is None:

        result_percentage = (
            calculated_percentage
        )

    # ========================================================
    # RESULT STATUS
    #
    # IMPORTANT:
    # This remains the real StudentResult status.
    # It is NOT used as ranking.
    # ========================================================

    result_status = getattr(
        result,
        "status",
        None
    )

    if not result_status:

        result_status = "draft"

    # ========================================================
    # RESULT GRADE
    # ========================================================

    result_grade = getattr(
        result,
        "grade",
        None
    )

    # ========================================================
    # SAFE DECIMAL
    # ========================================================

    def decimal_value(value):

        if value is None:
            return None

        try:

            return Decimal(
                str(value)
            )

        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):

            return None

    result_total = decimal_value(
        result_total
    )

    result_maximum = decimal_value(
        result_maximum
    )

    result_percentage = decimal_value(
        result_percentage
    )

    # ========================================================
    # REAL DATABASE POSITIONS
    #
    # These values are already generated by
    # calculate_exam_rankings().
    #
    # DO NOT calculate them here.
    # ========================================================

    branch_position = getattr(
        result,
        "branch_position",
        None
    )

    class_position = getattr(
        result,
        "class_position",
        None
    )

    # ========================================================
    # OPTIONAL OTHER POSITIONS
    #
    # Kept available for future use, but not displayed
    # on this print page.
    # ========================================================

    institution_position = getattr(
        result,
        "institution_position",
        None
    )

    program_position = getattr(
        result,
        "program_position",
        None
    )

    section_position = getattr(
        result,
        "section_position",
        None
    )

    # ========================================================
    # DISPLAY VALUES
    # ========================================================

    student_name = (
        getattr(
            student,
            "full_name",
            None
        )
        or "Student"
    )

    admission_no = (
        getattr(
            student,
            "admission_no",
            None
        )
        or "—"
    )

    roll_no = (
        getattr(
            student,
            "roll_no",
            None
        )
        or "—"
    )

    exam_code = (
        getattr(
            exam,
            "code",
            None
        )
        or "—"
    )

    exam_title = (
        getattr(
            exam,
            "title",
            None
        )
        or getattr(
            exam,
            "name",
            None
        )
        or "Examination"
    )

    exam_type = (
        getattr(
            exam,
            "exam_type",
            None
        )
        or "—"
    )

    # ========================================================
    # RANK DISPLAY
    #
    # NO Ranking model query.
    # Positions come directly from StudentResult.
    # ========================================================

    return render_template(
        "backend/pages/results/print_student_exam_result.html",

        # ----------------------------------------------------
        # CORE
        # ----------------------------------------------------

        result=result,

        student=student,

        exam=exam,

        site_settings=site_settings,

        enrollment=enrollment,

        # ----------------------------------------------------
        # ACADEMIC
        # ----------------------------------------------------

        program=program,

        student_class=student_class,

        student_section=student_section,

        academic_year=academic_year,

        term=term,

        # ----------------------------------------------------
        # SUBJECT RESULTS
        # ----------------------------------------------------

        exam_subjects=exam_subjects,

        subject_rows=subject_rows,

        marks=marks,

        mark_map=mark_map,

        # ----------------------------------------------------
        # RESULT VALUES
        # ----------------------------------------------------

        total_marks=result_total,

        maximum_marks=result_maximum,

        percentage=result_percentage,

        grade=result_grade,

        result_status=result_status,

        # ----------------------------------------------------
        # REAL DATABASE POSITIONS
        # ----------------------------------------------------

        branch_position=branch_position,

        class_position=class_position,

        # ----------------------------------------------------
        # OPTIONAL POSITIONS
        # ----------------------------------------------------

        institution_position=(
            institution_position
        ),

        program_position=(
            program_position
        ),

        section_position=(
            section_position
        ),

        # ----------------------------------------------------
        # DISPLAY
        # ----------------------------------------------------

        student_name=student_name,

        admission_no=admission_no,

        roll_no=roll_no,

        exam_code=exam_code,

        exam_title=exam_title,

        exam_type=exam_type,

        # ----------------------------------------------------
        # PAGE MODE
        # ----------------------------------------------------

        page_mode="print",

        is_print_page=True,
    )


# ============================================================
# PRINT ALL EXAM RESULT OPTIONS
# ============================================================

@bp.route(
    "/exam-results/print-all/options",
    methods=["GET"]
)
@login_required
def print_all_exam_result_options():

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)


    # ========================================================
    # CURRENT SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )


    # ========================================================
    # PROGRAM ID
    # ========================================================

    try:

        program_id = int(
            request.args.get(
                "program_id"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        return jsonify({
            "success": False,
            "message": "Invalid program."
        }), 400


    # ========================================================
    # PROGRAM QUERY
    # ========================================================

    program_query = (
        Program.query
        .filter(
            Program.id == program_id
        )
    )


    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        program_query = (
            program_query
            .filter(
                Program.institution_id ==
                current_institution_id
            )
        )


    elif role == "branch_admin":

        if (
            not current_institution_id or
            not current_branch_id
        ):
            abort(403)

        program_query = (
            program_query
            .filter(
                Program.institution_id ==
                current_institution_id,
                db.or_(
                    Program.branch_id ==
                    current_branch_id,

                    Program.branch_id.is_(None),
                ),
            )
        )


    program = program_query.first()

    if not program:

        return jsonify({
            "success": False,
            "message": "Program not found."
        }), 404


    # ========================================================
    # CLASSES
    #
    # IMPORTANT:
    # ONLY CLASSES BELONGING TO THIS PROGRAM
    #
    # If Class model does not have program_id, the fallback
    # uses active enrollments for that program.
    # ========================================================

    classes = []


    # --------------------------------------------------------
    # Try direct Class.program_id if available
    # --------------------------------------------------------

    if hasattr(Class, "program_id"):

        class_query = (
            Class.query
            .filter(
                Class.institution_id ==
                program.institution_id,
                Class.program_id ==
                program.id,
            )
        )

        if role in {
            "school_admin",
            "branch_admin",
        }:

            class_query = (
                class_query
                .filter(
                    Class.branch_id ==
                    current_branch_id
                )
            )

        classes = (
            class_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )


    # --------------------------------------------------------
    # Fallback:
    # classes found through active enrollments
    # --------------------------------------------------------

    else:

        enrollment_query = (
            StudentEnrollment.query
            .filter(
                StudentEnrollment.institution_id ==
                program.institution_id,

                StudentEnrollment.program_id ==
                program.id,
            )
        )

        if role in {
            "school_admin",
            "branch_admin",
        }:

            enrollment_query = (
                enrollment_query
                .filter(
                    StudentEnrollment.branch_id ==
                    current_branch_id
                )
            )


        class_ids = [
            row[0]
            for row in (
                enrollment_query
                .with_entities(
                    StudentEnrollment.class_id
                )
                .filter(
                    StudentEnrollment.class_id.isnot(None)
                )
                .distinct()
                .all()
            )
        ]


        if class_ids:

            classes = (
                Class.query
                .filter(
                    Class.id.in_(class_ids)
                )
                .order_by(
                    Class.name.asc()
                )
                .all()
            )


    # ========================================================
    # EXAMS
    # ========================================================

    exam_query = (
        Exam.query
        .filter(
            Exam.institution_id ==
            program.institution_id,

            Exam.program_id ==
            program.id,
        )
    )


    if role == "school_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id ==
                current_institution_id
            )
        )


    elif role == "branch_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id ==
                current_institution_id,

                Exam.branch_id ==
                current_branch_id,
            )
        )


    exams = (
        exam_query
        .order_by(
            Exam.id.desc()
        )
        .all()
    )


    # ========================================================
    # RESPONSE
    # ========================================================

    return jsonify({
        "success": True,

        "program": {
            "id": program.id,
            "name": (
                getattr(program, "name", None)
                or "Program"
            ),
            "code": (
                getattr(program, "code", None)
                or ""
            ),
        },

        "classes": [
            {
                "id": item.id,
                "name": (
                    getattr(item, "name", None)
                    or getattr(item, "title", None)
                    or f"Class {item.id}"
                ),
                "code": (
                    getattr(item, "code", None)
                    or ""
                ),
            }
            for item in classes
        ],

        "exams": [
            {
                "id": item.id,

                "code": (
                    getattr(item, "code", None)
                    or ""
                ),

                "title": (
                    getattr(item, "title", None)
                    or getattr(item, "name", None)
                    or ""
                ),

                "name": (
                    getattr(item, "name", None)
                    or ""
                ),

                "exam_type": (
                    getattr(item, "exam_type", None)
                    or ""
                ),
            }
            for item in exams
        ],
    })


# ============================================================
# PRINT ALL EXAM RESULT
# ============================================================

@bp.route(
    "/exam-results/print-all",
    methods=["GET"]
)
@login_required
def print_all_exam_result():

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)


    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )


    # ========================================================
    # HELPERS
    # ========================================================

    def to_int(value):

        try:
            return int(value)

        except (
            TypeError,
            ValueError,
        ):
            return None


    def decimal_value(value):

        if value is None:
            return None

        try:

            return Decimal(
                str(value)
            )

        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):

            return None


    def clean_text(value):

        if value is None:
            return ""

        return str(value).strip()


    def normalize_upper(value):

        value = clean_text(value)

        return value.upper() if value else ""


    # ========================================================
    # PARAMETERS
    # ========================================================

    program_id = to_int(
        request.args.get(
            "program_id"
        )
    )

    class_id = to_int(
        request.args.get(
            "class_id"
        )
    )

    exam_id = to_int(
        request.args.get(
            "exam_id"
        )
    )


    if not program_id:

        abort(
            400,
            "Program is required."
        )


    if not class_id:

        abort(
            400,
            "Class is required."
        )


    if not exam_id:

        abort(
            400,
            "Examination is required."
        )


    # ========================================================
    # PROGRAM
    # ========================================================

    program_query = (
        Program.query
        .filter(
            Program.id == program_id
        )
    )


    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        program_query = (
            program_query
            .filter(
                Program.institution_id ==
                current_institution_id
            )
        )


    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif role == "branch_admin":

        if (
            not current_institution_id or
            not current_branch_id
        ):
            abort(403)

        program_query = (
            program_query
            .filter(
                Program.institution_id ==
                current_institution_id,

                db.or_(
                    Program.branch_id ==
                    current_branch_id,

                    Program.branch_id.is_(None),
                ),
            )
        )


    program = program_query.first()


    if not program:

        abort(
            404,
            "Program not found."
        )


    # ========================================================
    # EXAM
    # ========================================================

    exam_query = (
        Exam.query
        .options(
            db.joinedload(
                Exam.branch
            ),
        )
        .filter(
            Exam.id == exam_id,

            Exam.institution_id ==
            program.institution_id,

            Exam.program_id ==
            program.id,
        )
    )


    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if role == "school_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id ==
                current_institution_id
            )
        )


    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif role == "branch_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id ==
                current_institution_id,

                Exam.branch_id ==
                current_branch_id,
            )
        )


    exam = exam_query.first()


    if not exam:

        abort(
            404,
            "Examination not found."
        )


    # ========================================================
    # CLASS
    # ========================================================

    class_query = (
        Class.query
        .filter(
            Class.id == class_id,

            Class.institution_id ==
            exam.institution_id,

            Class.branch_id ==
            exam.branch_id,
        )
    )


    # --------------------------------------------------------
    # If Class has program_id
    # --------------------------------------------------------

    if hasattr(
        Class,
        "program_id"
    ):

        class_query = (
            class_query
            .filter(
                Class.program_id ==
                program.id
            )
        )


    selected_class = (
        class_query.first()
    )


    # ========================================================
    # FALLBACK CLASS VALIDATION
    # THROUGH ENROLLMENT
    # ========================================================

    if not selected_class:

        enrollment_class_exists = (
            StudentEnrollment.query
            .filter(
                StudentEnrollment.institution_id ==
                exam.institution_id,

                StudentEnrollment.branch_id ==
                exam.branch_id,

                StudentEnrollment.program_id ==
                program.id,

                StudentEnrollment.class_id ==
                class_id,

                StudentEnrollment.academic_year_id ==
                exam.academic_year_id,
            )
            .first()
        )


        if not enrollment_class_exists:

            abort(
                404,
                "Selected class does not belong to this program."
            )


        selected_class = (
            Class.query
            .filter(
                Class.id == class_id
            )
            .first()
        )


        if not selected_class:

            abort(
                404,
                "Class not found."
            )


    # ========================================================
    # SITE SETTINGS
    # ========================================================

    site_settings = (
        SiteSettings.query
        .filter(
            SiteSettings.institution_id ==
            exam.institution_id
        )
        .first()
    )


    # ========================================================
    # BRANCH
    # ========================================================

    branch = getattr(
        exam,
        "branch",
        None
    )


    if not branch:

        branch = (
            Branch.query
            .filter(
                Branch.id ==
                exam.branch_id
            )
            .first()
        )


    # ========================================================
    # EXAM SUBJECTS
    # ========================================================

    all_exam_subjects = (
        ExamSubject.query
        .options(
            db.joinedload(
                ExamSubject.subject
            ),
            db.joinedload(
                ExamSubject.teacher
            ),
        )
        .filter(
            ExamSubject.exam_id ==
            exam.id
        )
        .order_by(
            ExamSubject.id.asc()
        )
        .all()
    )


    # ========================================================
    # SELECT SUBJECTS FOR CLASS
    #
    # RULE:
    #
    # class_id NULL
    #     = global exam subject
    #
    # class_id == selected class
    #     = class-specific subject
    #
    # Section-specific records are handled by selecting
    # the subject only once for the class report.
    # ========================================================

    class_subjects = []


    for exam_subject in all_exam_subjects:

        subject_class_id = getattr(
            exam_subject,
            "class_id",
            None
        )


        if (
            subject_class_id is not None and
            subject_class_id != selected_class.id
        ):

            continue


        class_subjects.append(
            exam_subject
        )


    # ========================================================
    # DEDUPLICATE SUBJECTS
    #
    # CLASS-SPECIFIC RECORD HAS PRIORITY
    # ========================================================

    subject_map = {}


    for exam_subject in class_subjects:

        subject = getattr(
            exam_subject,
            "subject",
            None
        )


        subject_id = getattr(
            exam_subject,
            "subject_id",
            None
        )


        if (
            subject_id is None and
            subject is not None
        ):

            subject_id = getattr(
                subject,
                "id",
                None
            )


        if subject_id is None:

            continue


        existing = subject_map.get(
            subject_id
        )


        if existing is None:

            subject_map[
                subject_id
            ] = exam_subject

            continue


        existing_class_id = getattr(
            existing,
            "class_id",
            None
        )


        new_class_id = getattr(
            exam_subject,
            "class_id",
            None
        )


        # Class-specific wins
        if (
            existing_class_id is None and
            new_class_id ==
            selected_class.id
        ):

            subject_map[
                subject_id
            ] = exam_subject


    exam_subjects = list(
        subject_map.values()
    )


    # ========================================================
    # ORDER SUBJECTS
    # ========================================================

    exam_subjects.sort(
        key=lambda item: (
            getattr(
                item,
                "display_order",
                None
            )
            if getattr(
                item,
                "display_order",
                None
            ) is not None
            else 999999,

            getattr(
                item,
                "id",
                0
            )
        )
    )


    # ========================================================
    # STUDENTS
    #
    # ONLY:
    #   institution
    #   branch
    #   program
    #   class
    #   academic year
    #
    # ACTIVE / ENROLLED
    # ========================================================

    enrollment_query = (
        StudentEnrollment.query
        .options(
            db.joinedload(
                StudentEnrollment.student
            )
        )
        .filter(
            StudentEnrollment.institution_id ==
            exam.institution_id,

            StudentEnrollment.branch_id ==
            exam.branch_id,

            StudentEnrollment.program_id ==
            program.id,

            StudentEnrollment.class_id ==
            selected_class.id,

            StudentEnrollment.academic_year_id ==
            exam.academic_year_id,

            StudentEnrollment.status.in_([
                "active",
                "enrolled",
            ]),
        )
        .order_by(
            StudentEnrollment.id.asc()
        )
    )


    enrollments = (
        enrollment_query
        .all()
    )


    # ========================================================
    # UNIQUE STUDENTS
    # ========================================================

    student_map = {}


    for enrollment in enrollments:

        student = getattr(
            enrollment,
            "student",
            None
        )


        if not student:
            continue


        student_map[
            student.id
        ] = {
            "student": student,
            "enrollment": enrollment,
        }


    students = list(
        student_map.values()
    )


    # ========================================================
    # STUDENT IDS
    # ========================================================

    student_ids = [
        item["student"].id
        for item in students
    ]


    exam_subject_ids = [
        item.id
        for item in exam_subjects
    ]


    # ========================================================
    # MARKS
    # ========================================================

    marks = []


    if (
        student_ids and
        exam_subject_ids
    ):

        marks = (
            Mark.query
            .filter(
                Mark.student_id.in_(
                    student_ids
                ),

                Mark.exam_subject_id.in_(
                    exam_subject_ids
                ),
            )
            .all()
        )


    # ========================================================
    # MARK MAP
    # ========================================================

    mark_map = {}


    for mark in marks:

        mark_map[
            (
                mark.student_id,
                mark.exam_subject_id
            )
        ] = mark


    # ========================================================
    # STUDENT RESULT MAP
    # ========================================================

    result_map = {}


    if student_ids:

        result_rows = (
            StudentResult.query
            .filter(
                StudentResult.exam_id ==
                exam.id,

                StudentResult.student_id.in_(
                    student_ids
                )
            )
            .all()
        )


        for result in result_rows:

            result_map[
                result.student_id
            ] = result


    # ========================================================
    # EXISTING RANKING MAP
    # ========================================================

    ranking_map = {}


    ranking_model = globals().get(
        "Ranking"
    )


    if (
        ranking_model and
        student_ids
    ):

        try:

            ranking_rows = (
                ranking_model.query
                .filter(
                    ranking_model.exam_id ==
                    exam.id,

                    ranking_model.student_id.in_(
                        student_ids
                    )
                )
                .all()
            )


            for ranking in ranking_rows:

                ranking_map[
                    ranking.student_id
                ] = ranking


        except Exception:

            ranking_map = {}


    # ========================================================
    # BUILD RAW STUDENT RESULT DATA FIRST
    #
    # This is important.
    #
    # We calculate EVERY student before calculating rank.
    # Therefore rank is based on the complete selected class.
    # ========================================================

    raw_rows = []


    for item in students:

        student = item["student"]

        enrollment = item["enrollment"]

        result = result_map.get(
            student.id
        )


        # ====================================================
        # CALCULATED VALUES
        # ====================================================

        calculated_total = Decimal(
            "0"
        )

        calculated_maximum = Decimal(
            "0"
        )

        has_missing = False

        has_absent = False

        subject_marks = {}


        # ====================================================
        # SUBJECT MARKS
        # ====================================================

        for exam_subject in exam_subjects:

            mark = mark_map.get(
                (
                    student.id,
                    exam_subject.id
                )
            )


            marks_obtained = None

            is_absent = False

            is_exempted = False


            if mark:

                is_absent = bool(
                    getattr(
                        mark,
                        "is_absent",
                        False
                    )
                )


                is_exempted = bool(
                    getattr(
                        mark,
                        "is_exempted",
                        False
                    )
                )


                if is_absent:

                    has_absent = True


                raw_marks = getattr(
                    mark,
                    "marks_obtained",
                    None
                )


                marks_obtained = decimal_value(
                    raw_marks
                )


            # ------------------------------------------------
            # SAVE SUBJECT DATA
            # ------------------------------------------------

            subject_marks[
                exam_subject.id
            ] = {
                "mark": mark,
                "marks": marks_obtained,
                "absent": is_absent,
                "exempted": is_exempted,
            }


            # ------------------------------------------------
            # CALCULATE TOTAL
            # ------------------------------------------------

            if (
                marks_obtained is not None
                and not is_absent
                and not is_exempted
            ):

                calculated_total += (
                    marks_obtained
                )


                max_marks = decimal_value(
                    getattr(
                        exam_subject,
                        "max_marks",
                        None
                    )
                )


                if (
                    max_marks is not None
                    and max_marks >
                    Decimal("0")
                ):

                    calculated_maximum += (
                        max_marks
                    )


            elif (
                not is_absent
                and not is_exempted
            ):

                has_missing = True


        # ====================================================
        # STUDENT RESULT DATABASE VALUES
        # ====================================================

        total_marks = None

        maximum_marks = None

        percentage = None

        grade = None


        if result:

            total_marks = decimal_value(
                getattr(
                    result,
                    "total_marks",
                    None
                )
            )


            maximum_marks = decimal_value(
                getattr(
                    result,
                    "total_max_marks",
                    None
                )
            )


            percentage = decimal_value(
                getattr(
                    result,
                    "percentage",
                    None
                )
            )


            grade = clean_text(
                getattr(
                    result,
                    "grade",
                    None
                )
            )


        # ====================================================
        # FALLBACK TOTAL
        #
        # If StudentResult has no total, use actual marks.
        # ====================================================

        if total_marks is None:

            total_marks = (
                calculated_total
            )


        # ====================================================
        # FALLBACK MAXIMUM
        # ====================================================

        if maximum_marks is None:

            maximum_marks = (
                calculated_maximum
            )


        # ====================================================
        # FALLBACK AVERAGE / PERCENTAGE
        # ====================================================

        if percentage is None:

            if (
                maximum_marks is not None
                and maximum_marks >
                Decimal("0")
            ):

                percentage = (
                    total_marks /
                    maximum_marks
                ) * Decimal("100")

            else:

                percentage = Decimal(
                    "0"
                )


        # ====================================================
        # ROUND
        # ====================================================

        total_marks = total_marks.quantize(
            Decimal("0.01")
        )

        maximum_marks = maximum_marks.quantize(
            Decimal("0.01")
        )

        percentage = percentage.quantize(
            Decimal("0.01")
        )


        # ====================================================
        # GRADE
        #
        # FIRST:
        #   StudentResult.grade
        #
        # SECOND:
        #   GradeScale if available
        #
        # THIRD:
        #   standard fallback
        # ====================================================

        if not grade:

            grade_scale_model = globals().get(
                "GradeScale"
            )


            if grade_scale_model:

                try:

                    grade_scale_rows = (
                        grade_scale_model.query
                        .all()
                    )


                    for scale in grade_scale_rows:

                        min_mark = decimal_value(
                            getattr(
                                scale,
                                "min_percentage",
                                None
                            )
                            or getattr(
                                scale,
                                "min_percent",
                                None
                            )
                            or getattr(
                                scale,
                                "minimum",
                                None
                            )
                        )


                        max_mark = decimal_value(
                            getattr(
                                scale,
                                "max_percentage",
                                None
                            )
                            or getattr(
                                scale,
                                "max_percent",
                                None
                            )
                            or getattr(
                                scale,
                                "maximum",
                                None
                            )
                        )


                        scale_grade = clean_text(
                            getattr(
                                scale,
                                "grade",
                                None
                            )
                        )


                        if (
                            min_mark is not None
                            and max_mark is not None
                            and scale_grade
                            and min_mark <= percentage
                            and percentage <= max_mark
                        ):

                            grade = scale_grade

                            break


                except Exception:

                    pass


        # ====================================================
        # FINAL GRADE FALLBACK
        #
        # Your existing SOOYAAL grade scale.
        # ====================================================

        if not grade:

            if percentage >= Decimal("90"):

                grade = "A+"


            elif percentage >= Decimal("80"):

                grade = "A"


            elif percentage >= Decimal("75"):

                grade = "B+"


            elif percentage >= Decimal("70"):

                grade = "B"


            elif percentage >= Decimal("65"):

                grade = "C+"


            elif percentage >= Decimal("60"):

                grade = "C"


            elif percentage >= Decimal("50"):

                grade = "D"


            else:

                grade = "F"


        # ====================================================
        # ACADEMIC RESULT
        #
        # NEVER use StudentResult.status here.
        #
        # status:
        #   DRAFT / PUBLISHED / ...
        #
        # result:
        #   PASS / FAIL / INCOMPLETE
        # ====================================================

        academic_result = ""


        if result:

            # Try actual result field only.
            academic_result = clean_text(
                getattr(
                    result,
                    "result",
                    None
                )
            )


        academic_result = normalize_upper(
            academic_result
        )


        # ----------------------------------------------------
        # Reject administrative statuses
        # ----------------------------------------------------

        invalid_academic_results = {
            "",
            "DRAFT",
            "PUBLISHED",
            "ONGOING",
            "COMPLETED",
            "SCHEDULED",
            "CANCELLED",
        }


        if academic_result in invalid_academic_results:

            academic_result = ""


        # ====================================================
        # CALCULATE ACADEMIC RESULT
        # ====================================================

        if not academic_result:

            if has_missing:

                academic_result = "INCOMPLETE"


            elif percentage >= Decimal("50"):

                academic_result = "PASS"


            else:

                academic_result = "FAIL"


        # ====================================================
        # DECISION
        #
        # Use real DB decision if meaningful.
        # Ignore PENDING when actual academic result exists.
        # ====================================================

        decision = ""


        if result:

            decision = clean_text(
                getattr(
                    result,
                    "decision",
                    None
                )
            )


        decision = normalize_upper(
            decision
        )


        # ====================================================
        # Remove generic/non-final decision values
        # ====================================================

        if decision in {
            "",
            "PENDING",
            "DRAFT",
        }:

            decision = ""


        # ====================================================
        # FINAL DECISION
        # ====================================================

        if not decision:

            if academic_result == "PASS":

                decision = "PROMOTE"


            elif academic_result == "FAIL":

                decision = "REPEAT"


            elif academic_result == "INCOMPLETE":

                decision = "PENDING"


            else:

                decision = "PENDING"


        # ====================================================
        # EXISTING RANKING
        # ====================================================

        ranking = ranking_map.get(
            student.id
        )


        existing_rank = None


        if ranking:

            existing_rank = (
                getattr(
                    ranking,
                    "rank",
                    None
                )
                or getattr(
                    ranking,
                    "position",
                    None
                )
            )


        # ====================================================
        # STUDENT RESULT RANK
        # ====================================================

        if existing_rank is None and result:

            existing_rank = (
                getattr(
                    result,
                    "rank",
                    None
                )
                or getattr(
                    result,
                    "position",
                    None
                )
            )


        # ====================================================
        # SAVE RAW ROW
        # ====================================================

        raw_rows.append({

            "student":
                student,

            "enrollment":
                enrollment,

            "result":
                result,

            "ranking":
                ranking,

            "subject_marks":
                subject_marks,

            "total":
                total_marks,

            "maximum":
                maximum_marks,

            "average":
                percentage,

            "grade":
                grade,

            "decision":
                decision,

            "result_value":
                academic_result,

            "existing_rank":
                existing_rank,

        })


    # ========================================================
    # RANKING
    #
    # Rank is calculated ONLY among the selected class
    # students.
    #
    # Highest percentage = Rank 1
    #
    # Same percentage = same rank
    #
    # Example:
    #
    # 90 -> 1
    # 90 -> 1
    # 80 -> 3
    #
    # Students with INCOMPLETE result are not ranked.
    # ========================================================

    ranked_rows = []


    for row in raw_rows:

        if (
            row["result_value"] ==
            "PASS"
            or
            row["result_value"] ==
            "FAIL"
        ):

            ranked_rows.append(
                row
            )


    # ========================================================
    # SORT BY:
    #
    #   percentage DESC
    #   total DESC
    #   student name ASC
    # ========================================================

    ranked_rows.sort(
        key=lambda row: (
            -float(
                row["average"]
                or Decimal("0")
            ),

            -float(
                row["total"]
                or Decimal("0")
            ),

            (
                clean_text(
                    getattr(
                        row["student"],
                        "full_name",
                        ""
                    )
                ).lower()
            ),
        )
    )


    # ========================================================
    # ASSIGN RANK
    # ========================================================

    rank_by_student = {}

    previous_percentage = None

    previous_total = None

    current_rank = 0


    for index, row in enumerate(
        ranked_rows,
        start=1
    ):

        current_percentage = (
            row["average"]
            or Decimal("0")
        )

        current_total = (
            row["total"]
            or Decimal("0")
        )


        if (
            previous_percentage is not None
            and
            current_percentage ==
            previous_percentage
            and
            current_total ==
            previous_total
        ):

            rank = current_rank

        else:

            rank = index

            current_rank = rank


        rank_by_student[
            row["student"].id
        ] = rank


        previous_percentage = (
            current_percentage
        )

        previous_total = (
            current_total
        )


    # ========================================================
    # FINAL REPORT ROWS
    # ========================================================

    report_rows = []


    for row in raw_rows:

        student = row[
            "student"
        ]


        # ----------------------------------------------------
        # Rank priority:
        #
        # 1. Existing Ranking
        # 2. StudentResult rank
        # 3. Calculated class rank
        # ----------------------------------------------------

        rank = row[
            "existing_rank"
        ]


        if rank is None:

            rank = rank_by_student.get(
                student.id
            )


        # ----------------------------------------------------
        # Branch / Class positions
        # ----------------------------------------------------

        result = row[
            "result"
        ]


        branch_position = None

        class_position = None


        if result:

            branch_position = getattr(
                result,
                "branch_position",
                None
            )


            class_position = getattr(
                result,
                "class_position",
                None
            )


        # ----------------------------------------------------
        # Final row
        # ----------------------------------------------------

        report_rows.append({

            "student":
                student,

            "enrollment":
                row["enrollment"],

            "result":
                result,

            "ranking":
                row["ranking"],

            "subject_marks":
                row["subject_marks"],

            "total":
                row["total"],

            "maximum":
                row["maximum"],

            "average":
                row["average"],

            "rank":
                rank,

            "branch_position":
                branch_position,

            "class_position":
                class_position,

            "grade":
                row["grade"],

            "decision":
                row["decision"],

            "result_value":
                row["result_value"],

        })


    # ========================================================
    # FINAL STUDENT ORDER
    #
    # Rank first.
    # Students without rank go last.
    # ========================================================

    def student_sort_key(row):

        rank = row.get(
            "rank"
        )


        if rank is None:

            rank_value = 999999

        else:

            try:

                rank_value = int(
                    rank
                )

            except (
                TypeError,
                ValueError,
            ):

                rank_value = 999999


        student = row[
            "student"
        ]


        name = (
            getattr(
                student,
                "full_name",
                None
            )
            or ""
        )


        return (
            rank_value,
            str(name).lower(),
        )


    report_rows.sort(
        key=student_sort_key
    )


    # ========================================================
    # SUBJECT HEADERS
    # ========================================================

    subject_columns = []


    for exam_subject in exam_subjects:

        subject = getattr(
            exam_subject,
            "subject",
            None
        )


        subject_name = (
            getattr(
                subject,
                "name",
                None
            )
            or getattr(
                subject,
                "title",
                None
            )
            or "Subject"
        )


        subject_code = (
            getattr(
                subject,
                "code",
                None
            )
            or ""
        )


        subject_columns.append({

            "id":
                exam_subject.id,

            "name":
                subject_name,

            "code":
                subject_code,

        })


    # ========================================================
    # RANKED STUDENT COUNT
    # ========================================================

    total_ranked_students = len(
        ranked_rows
    )


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/results/print_all_exam_result.html",

        site_settings=
            site_settings,

        branch=
            branch,

        program=
            program,

        selected_class=
            selected_class,

        exam=
            exam,

        exam_subjects=
            exam_subjects,

        subject_columns=
            subject_columns,

        report_rows=
            report_rows,

        total_ranked_students=
            total_ranked_students,

        page_mode=
            "print",

        is_print_page=
            True,

    )


# ============================================================
# EXPORT EXAM RESULTS OPTIONS
# ============================================================

@bp.route(
    "/exam-results/export/options",
    methods=["GET"]
)
@login_required
def export_exam_result_options():

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)


    # ========================================================
    # CURRENT SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )


    # ========================================================
    # PROGRAM ID
    # ========================================================

    try:

        program_id = int(
            request.args.get(
                "program_id"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        return jsonify({
            "success": False,
            "message": "Invalid program."
        }), 400


    # ========================================================
    # PROGRAM QUERY
    # ========================================================

    program_query = (
        Program.query
        .filter(
            Program.id == program_id
        )
    )


    # ========================================================
    # SCHOOL ADMIN
    # ========================================================

    if role == "school_admin":

        if not current_institution_id:
            abort(403)

        program_query = (
            program_query
            .filter(
                Program.institution_id ==
                current_institution_id
            )
        )


    # ========================================================
    # BRANCH ADMIN
    # ========================================================

    elif role == "branch_admin":

        if (
            not current_institution_id
            or not current_branch_id
        ):
            abort(403)

        program_query = (
            program_query
            .filter(
                Program.institution_id ==
                current_institution_id,

                db.or_(
                    Program.branch_id ==
                    current_branch_id,

                    Program.branch_id.is_(None),
                ),
            )
        )


    # ========================================================
    # GET PROGRAM
    # ========================================================

    program = program_query.first()

    if not program:

        return jsonify({
            "success": False,
            "message": "Program not found."
        }), 404


    # ========================================================
    # CLASSES
    #
    # IMPORTANT:
    # Only classes belonging to selected program.
    #
    # If Class.program_id exists:
    #     use it directly.
    #
    # Otherwise:
    #     find classes through enrollments.
    # ========================================================

    classes = []


    # --------------------------------------------------------
    # DIRECT PROGRAM RELATIONSHIP
    # --------------------------------------------------------

    if hasattr(Class, "program_id"):

        class_query = (
            Class.query
            .filter(
                Class.institution_id ==
                program.institution_id,

                Class.program_id ==
                program.id,
            )
        )


        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        if role == "branch_admin":

            class_query = (
                class_query
                .filter(
                    Class.branch_id ==
                    current_branch_id
                )
            )


        # ----------------------------------------------------
        # SCHOOL ADMIN
        #
        # School admin can see all branches inside
        # their institution.
        # ----------------------------------------------------

        elif role == "school_admin":

            class_query = (
                class_query
                .filter(
                    Class.institution_id ==
                    current_institution_id
                )
            )


        classes = (
            class_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )


    # --------------------------------------------------------
    # FALLBACK THROUGH ENROLLMENTS
    # --------------------------------------------------------

    else:

        enrollment_query = (
            StudentEnrollment.query
            .filter(
                StudentEnrollment.institution_id ==
                program.institution_id,

                StudentEnrollment.program_id ==
                program.id,
            )
        )


        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        if role == "branch_admin":

            enrollment_query = (
                enrollment_query
                .filter(
                    StudentEnrollment.branch_id ==
                    current_branch_id
                )
            )


        # ----------------------------------------------------
        # SCHOOL ADMIN
        # ----------------------------------------------------

        elif role == "school_admin":

            enrollment_query = (
                enrollment_query
                .filter(
                    StudentEnrollment.institution_id ==
                    current_institution_id
                )
            )


        class_ids = [
            row[0]
            for row in (
                enrollment_query
                .with_entities(
                    StudentEnrollment.class_id
                )
                .filter(
                    StudentEnrollment.class_id.isnot(None)
                )
                .distinct()
                .all()
            )
        ]


        if class_ids:

            classes = (
                Class.query
                .filter(
                    Class.id.in_(class_ids)
                )
                .order_by(
                    Class.name.asc()
                )
                .all()
            )


    # ========================================================
    # EXAMS
    # ========================================================

    exam_query = (
        Exam.query
        .filter(
            Exam.institution_id ==
            program.institution_id,

            Exam.program_id ==
            program.id,
        )
    )


    # ========================================================
    # SCHOOL ADMIN
    # ========================================================

    if role == "school_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id ==
                current_institution_id
            )
        )


    # ========================================================
    # BRANCH ADMIN
    # ========================================================

    elif role == "branch_admin":

        exam_query = (
            exam_query
            .filter(
                Exam.institution_id ==
                current_institution_id,

                Exam.branch_id ==
                current_branch_id,
            )
        )


    # ========================================================
    # GET EXAMS
    # ========================================================

    exams = (
        exam_query
        .order_by(
            Exam.id.desc()
        )
        .all()
    )


    # ========================================================
    # RESPONSE
    # ========================================================

    return jsonify({

        "success": True,

        # ----------------------------------------------------
        # PROGRAM
        # ----------------------------------------------------

        "program": {

            "id": program.id,

            "name": (
                getattr(
                    program,
                    "name",
                    None
                )
                or "Program"
            ),

            "code": (
                getattr(
                    program,
                    "code",
                    None
                )
                or ""
            ),
        },


        # ----------------------------------------------------
        # CLASSES
        # ----------------------------------------------------

        "classes": [

            {
                "id": item.id,

                "name": (
                    getattr(
                        item,
                        "name",
                        None
                    )
                    or getattr(
                        item,
                        "title",
                        None
                    )
                    or f"Class {item.id}"
                ),

                "code": (
                    getattr(
                        item,
                        "code",
                        None
                    )
                    or ""
                ),
            }

            for item in classes
        ],


        # ----------------------------------------------------
        # EXAMS
        # ----------------------------------------------------

        "exams": [

            {
                "id": item.id,

                "code": (
                    getattr(
                        item,
                        "code",
                        None
                    )
                    or ""
                ),

                "title": (
                    getattr(
                        item,
                        "title",
                        None
                    )
                    or getattr(
                        item,
                        "name",
                        None
                    )
                    or ""
                ),

                "name": (
                    getattr(
                        item,
                        "name",
                        None
                    )
                    or ""
                ),

                "exam_type": (
                    getattr(
                        item,
                        "exam_type",
                        None
                    )
                    or ""
                ),
            }

            for item in exams
        ],
    })


# ============================================================
# EXPORT FULL EXAM RESULT REPORT
# ============================================================

@bp.route(
    "/exam-results/export",
    methods=["GET"]
)
@login_required
def export_exam_result():

    # ========================================================
    # IMPORTS
    # ========================================================

    import csv
    import io
    import re

    from decimal import (
        Decimal,
        InvalidOperation,
        ROUND_HALF_UP,
    )

    from flask import (
        Response,
        abort,
        flash,
        redirect,
        request,
        url_for,
    )

    # ========================================================
    # SECURITY / ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    role = getattr(
        role,
        "value",
        role
    )

    role = (
        str(role).strip().lower()
        if role
        else None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # HELPERS
    # ========================================================

    def normalize_text(value):
        if value is None:
            return ""

        return str(value).strip()

    # --------------------------------------------------------
    # Decimal conversion
    # --------------------------------------------------------

    def to_decimal(value, default=None):

        if value is None:
            return default

        if isinstance(value, Decimal):
            return value

        try:
            return Decimal(
                str(value)
            )
        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):
            return default

    # --------------------------------------------------------
    # Decimal display
    # --------------------------------------------------------

    def decimal_text(
        value,
        places=2,
    ):

        value = to_decimal(
            value
        )

        if value is None:
            return ""

        quantizer = Decimal(
            "1"
            if places == 0
            else "0." + ("0" * (places - 1)) + "1"
        )

        value = value.quantize(
            quantizer,
            rounding=ROUND_HALF_UP,
        )

        return format(
            value,
            "f",
        )

    # --------------------------------------------------------
    # Grade
    #
    # 95+  A+
    # 90+  A
    # 85+  A-
    # 80+  B+
    # 75+  B
    # 70+  B-
    # 65+  C+
    # 60+  C
    # 50+  C-
    # 40+  D
    # 20+  E
    # <20  F
    # --------------------------------------------------------

    def calculate_grade(
        percentage
    ):

        percentage = to_decimal(
            percentage,
            Decimal("0"),
        )

        if percentage >= Decimal("95"):
            return "A+"

        if percentage >= Decimal("90"):
            return "A"

        if percentage >= Decimal("85"):
            return "A-"

        if percentage >= Decimal("80"):
            return "B+"

        if percentage >= Decimal("75"):
            return "B"

        if percentage >= Decimal("70"):
            return "B-"

        if percentage >= Decimal("65"):
            return "C+"

        if percentage >= Decimal("60"):
            return "C"

        if percentage >= Decimal("50"):
            return "C-"

        if percentage >= Decimal("40"):
            return "D"

        if percentage >= Decimal("20"):
            return "E"

        return "F"

    # --------------------------------------------------------
    # GPA points
    # --------------------------------------------------------

    GRADE_POINTS = {
        "A+": Decimal("4.00"),
        "A":  Decimal("4.00"),
        "A-": Decimal("3.70"),

        "B+": Decimal("3.30"),
        "B":  Decimal("3.00"),
        "B-": Decimal("2.70"),

        "C+": Decimal("2.30"),
        "C":  Decimal("2.00"),
        "C-": Decimal("1.70"),

        "D": Decimal("1.00"),
        "E": Decimal("0.50"),
        "F": Decimal("0.00"),
    }

    # --------------------------------------------------------
    # Result status
    #
    # StudentResult.result_status
    #
    # PASS
    # FAIL
    # INCOMPLETE
    # --------------------------------------------------------

    def get_result_status(
        result,
        percentage=None,
        has_missing=False,
    ):

        stored_status = normalize_text(
            getattr(
                result,
                "result_status",
                None,
            )
        ).upper()

        if stored_status in {
            "PASS",
            "FAIL",
            "INCOMPLETE",
        }:
            return stored_status

        if has_missing:
            return "INCOMPLETE"

        percentage = to_decimal(
            percentage
        )

        if percentage is None:
            return "INCOMPLETE"

        return (
            "PASS"
            if percentage >= Decimal("50")
            else "FAIL"
        )

    # --------------------------------------------------------
    # Decision
    #
    # StudentResult has NO decision column.
    #
    # Therefore derive it from result_status.
    # --------------------------------------------------------

    def academic_decision(
        result_status
    ):

        result_status = normalize_text(
            result_status
        ).upper()

        return {
            "PASS": "PROMOTE",
            "FAIL": "REPEAT",
            "INCOMPLETE": "PENDING",
        }.get(
            result_status,
            "PENDING",
        )

    # --------------------------------------------------------
    # Workflow status
    #
    # StudentResult.status is NOT PASS/FAIL.
    #
    # It is:
    # draft
    # submitted
    # approved
    # published
    # --------------------------------------------------------

    def workflow_status(result):

        return normalize_text(
            getattr(
                result,
                "status",
                None,
            )
        ).upper()

    # --------------------------------------------------------
    # Subject status
    # --------------------------------------------------------

    def subject_status(
        mark,
        exam_subject,
    ):

        if mark is None:
            return "MISSING"

        if getattr(
            mark,
            "is_exempted",
            False,
        ):
            return "EXEMPTED"

        if getattr(
            mark,
            "is_absent",
            False,
        ):
            return "ABSENT"

        marks = getattr(
            mark,
            "marks_obtained",
            None,
        )

        if marks is None:
            return "MISSING"

        return "RECORDED"

    # --------------------------------------------------------
    # Subject percentage
    # --------------------------------------------------------

    def subject_percentage(
        mark,
        exam_subject,
    ):

        if mark is None:
            return None

        if getattr(
            mark,
            "is_exempted",
            False,
        ):
            return None

        if getattr(
            mark,
            "is_absent",
            False,
        ):
            return Decimal("0")

        marks = to_decimal(
            getattr(
                mark,
                "marks_obtained",
                None,
            )
        )

        max_marks = to_decimal(
            getattr(
                exam_subject,
                "max_marks",
                None,
            )
        )

        if (
            marks is None
            or max_marks is None
            or max_marks <= 0
        ):
            return None

        return (
            marks / max_marks
        ) * Decimal("100")

    # --------------------------------------------------------
    # Subject grade
    # --------------------------------------------------------

    def subject_grade(
        mark,
        exam_subject,
    ):

        percentage = subject_percentage(
            mark,
            exam_subject,
        )

        if percentage is None:
            return ""

        return calculate_grade(
            percentage
        )

    # --------------------------------------------------------
    # GPA
    #
    # Prefer stored StudentResult.gpa.
    #
    # If missing, calculate from subject grades.
    #
    # If credit_hours exists on ExamSubject or Subject,
    # use weighted GPA.
    # --------------------------------------------------------

    def calculate_gpa_from_subjects(
        subject_rows
    ):

        weighted_possible = True

        total_quality_points = Decimal(
            "0"
        )

        total_credit_hours = Decimal(
            "0"
        )

        simple_points = []

        for item in subject_rows:

            mark = item.get(
                "mark"
            )

            exam_subject = item.get(
                "exam_subject"
            )

            subject = item.get(
                "subject"
            )

            if mark is None:
                continue

            if getattr(
                mark,
                "is_absent",
                False,
            ):
                grade = "F"

            elif getattr(
                mark,
                "is_exempted",
                False,
            ):
                continue

            else:
                grade = item.get(
                    "grade"
                )

            if not grade:
                continue

            grade_point = GRADE_POINTS.get(
                grade
            )

            if grade_point is None:
                continue

            simple_points.append(
                grade_point
            )

            # ------------------------------------------------
            # Try ExamSubject.credit_hours
            # ------------------------------------------------

            credit_hours = getattr(
                exam_subject,
                "credit_hours",
                None,
            )

            # ------------------------------------------------
            # Then Subject.credit_hours
            # ------------------------------------------------

            if credit_hours is None:
                credit_hours = getattr(
                    subject,
                    "credit_hours",
                    None,
                )

            credit_hours = to_decimal(
                credit_hours
            )

            if (
                credit_hours is None
                or credit_hours <= 0
            ):
                weighted_possible = False
                continue

            total_quality_points += (
                grade_point
                * credit_hours
            )

            total_credit_hours += (
                credit_hours
            )

        # ----------------------------------------------------
        # Weighted GPA
        # ----------------------------------------------------

        if (
            weighted_possible
            and total_credit_hours > 0
        ):

            return (
                total_quality_points
                / total_credit_hours
            ).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

        # ----------------------------------------------------
        # Fallback
        #
        # If credit hours are not available in the current
        # schema/data, use simple subject GPA average.
        # ----------------------------------------------------

        if simple_points:

            return (
                sum(simple_points)
                / Decimal(
                    len(simple_points)
                )
            ).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

        return None

    # --------------------------------------------------------
    # Get stored position according to report scope
    #
    # Ranking is stored in StudentResult.
    # --------------------------------------------------------

    def get_stored_position(
        result,
        section_selected=False,
        class_selected=False,
        program_selected=False,
        exam=None,
    ):

        if result is None:
            return None

        # ----------------------------------------------------
        # Section report
        # ----------------------------------------------------

        if section_selected:

            return getattr(
                result,
                "section_position",
                None,
            )

        # ----------------------------------------------------
        # Class report
        # ----------------------------------------------------

        if class_selected:

            return getattr(
                result,
                "class_position",
                None,
            )

        # ----------------------------------------------------
        # Program report
        # ----------------------------------------------------

        if program_selected:

            return getattr(
                result,
                "program_position",
                None,
            )

        # ----------------------------------------------------
        # Exam branch report
        # ----------------------------------------------------

        if exam is not None:

            branch_id = getattr(
                exam,
                "branch_id",
                None,
            )

            if branch_id:

                return getattr(
                    result,
                    "branch_position",
                    None,
                )

        # ----------------------------------------------------
        # Institution report
        # ----------------------------------------------------

        return getattr(
            result,
            "institution_position",
            None,
        )

    # --------------------------------------------------------
    # Competition ranking
    #
    # 1, 1, 3, 4...
    # --------------------------------------------------------

    def calculate_fallback_positions(
        rows
    ):

        sortable = []

        for row_index, row in enumerate(
            rows
        ):

            result = row.get(
                "result"
            )

            status = row.get(
                "result_status"
            )

            percentage = to_decimal(
                row.get(
                    "percentage"
                )
            )

            total_marks = to_decimal(
                row.get(
                    "total_marks"
                ),
                Decimal("0"),
            )

            if result is None:
                continue

            if status not in {
                "PASS",
                "FAIL",
            }:
                continue

            if percentage is None:
                continue

            sortable.append(
                (
                    row_index,
                    percentage,
                    total_marks,
                    normalize_text(
                        row.get(
                            "student_name"
                        )
                    ).lower(),
                    row.get(
                        "student_id"
                    ),
                )
            )

        sortable.sort(
            key=lambda item: (
                -item[1],
                -item[2],
                item[3],
                item[4] or 0,
            )
        )

        positions = {}

        previous_percentage = None
        previous_total = None
        current_position = 0

        for index, item in enumerate(
            sortable,
            start=1,
        ):

            row_index = item[0]
            percentage = item[1]
            total_marks = item[2]

            if (
                previous_percentage is None
                or percentage != previous_percentage
                or total_marks != previous_total
            ):
                current_position = index

            positions[
                row_index
            ] = current_position

            previous_percentage = percentage
            previous_total = total_marks

        return positions

    # --------------------------------------------------------
    # Filename sanitizer
    # --------------------------------------------------------

    def safe_filename(value):

        value = normalize_text(
            value
        )

        if not value:
            return "exam-results"

        value = re.sub(
            r"[^A-Za-z0-9._-]+",
            "-",
            value,
        )

        value = value.strip(
            "-_."
        )

        return (
            value
            or "exam-results"
        )

    # ========================================================
    # REQUEST PARAMETERS
    # ========================================================

    exam_id = request.args.get(
        "exam_id",
        type=int,
    )

    program_id = request.args.get(
        "program_id",
        type=int,
    )

    class_id = request.args.get(
        "class_id",
        type=int,
    )

    section_id = request.args.get(
        "section_id",
        type=int,
    )

    # ========================================================
    # EXAM REQUIRED
    # ========================================================

    if not exam_id:

        flash(
            "Please select an exam before exporting results.",
            "warning",
        )

        return redirect(
            url_for(
                "main.add_exam_result"
            )
        )

    # ========================================================
    # GET EXAM
    # ========================================================

    exam = (
        Exam.query
        .filter(
            Exam.id == exam_id
        )
        .first()
    )

    if not exam:
        abort(404)

    # ========================================================
    # EXAM SECURITY / SCOPE
    # ========================================================

    exam_institution_id = getattr(
        exam,
        "institution_id",
        None,
    )

    exam_branch_id = getattr(
        exam,
        "branch_id",
        None,
    )

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None,
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None,
    )

    # --------------------------------------------------------
    # Superadmin
    # --------------------------------------------------------

    if role == "superadmin":

        pass

    # --------------------------------------------------------
    # School admin
    # --------------------------------------------------------

    elif role == "school_admin":

        if (
            not current_institution_id
            or exam_institution_id
            != current_institution_id
        ):
            abort(403)

    # --------------------------------------------------------
    # Branch admin
    # --------------------------------------------------------

    elif role == "branch_admin":

        if (
            not current_institution_id
            or exam_institution_id
            != current_institution_id
        ):
            abort(403)

        if (
            not current_branch_id
            or exam_branch_id
            != current_branch_id
        ):
            abort(403)

    # ========================================================
    # VALIDATE PROGRAM
    # ========================================================

    exam_program_id = getattr(
        exam,
        "program_id",
        None,
    )

    if program_id:

        if (
            exam_program_id
            and program_id
            != exam_program_id
        ):
            abort(400)

        program = (
            Program.query
            .filter(
                Program.id == program_id
            )
            .first()
        )

        if not program:
            abort(404)

        if (
            getattr(
                program,
                "institution_id",
                None,
            )
            != exam_institution_id
        ):
            abort(403)

    else:

        program_id = exam_program_id

    # ========================================================
    # VALIDATE CLASS
    # ========================================================

    selected_class = None

    if class_id:

        selected_class = (
            Class.query
            .filter(
                Class.id == class_id
            )
            .first()
        )

        if not selected_class:
            abort(404)

        selected_class_branch_id = getattr(
            selected_class,
            "branch_id",
            None,
        )

        if (
            exam_branch_id
            and selected_class_branch_id
            != exam_branch_id
        ):
            abort(403)

        selected_class_program_id = getattr(
            selected_class,
            "program_id",
            None,
        )

        if (
            program_id
            and selected_class_program_id
            != program_id
        ):
            abort(400)

    # ========================================================
    # VALIDATE SECTION
    # ========================================================

    selected_section = None

    if section_id:

        selected_section = (
            Section.query
            .filter(
                Section.id == section_id
            )
            .first()
        )

        if not selected_section:
            abort(404)

        selected_section_branch_id = getattr(
            selected_section,
            "branch_id",
            None,
        )

        if (
            exam_branch_id
            and selected_section_branch_id
            != exam_branch_id
        ):
            abort(403)

        section_class_id = getattr(
            selected_section,
            "class_id",
            None,
        )

        if (
            class_id
            and section_class_id
            != class_id
        ):
            abort(400)

        if (
            not class_id
            and section_class_id
        ):
            class_id = section_class_id

            selected_class = (
                Class.query
                .filter(
                    Class.id == class_id
                )
                .first()
            )

    # ========================================================
    # GET EXAM SUBJECTS
    #
    # IMPORTANT:
    # Section-specific subject overrides class-specific,
    # and class-specific overrides global.
    # ========================================================

    exam_subject_query = (
        ExamSubject.query
        .filter(
            ExamSubject.exam_id == exam.id
        )
    )

    all_exam_subjects = (
        exam_subject_query
        .order_by(
            ExamSubject.display_order.asc(),
            ExamSubject.id.asc(),
        )
        .all()
    )

    if not all_exam_subjects:

        flash(
            "No subjects are assigned to this exam.",
            "warning",
        )

        return redirect(
            url_for(
                "main.add_exam_result",
                exam_id=exam.id,
            )
        )

    # ========================================================
    # SUBJECT SELECTION
    #
    # Priority:
    #
    # 1. section
    # 2. class
    # 3. global
    #
    # One subject only once.
    # ========================================================

    selected_exam_subjects = []

    subjects_by_subject_id = {}

    for exam_subject in all_exam_subjects:

        subject_id = getattr(
            exam_subject,
            "subject_id",
            None,
        )

        if not subject_id:
            continue

        es_class_id = getattr(
            exam_subject,
            "class_id",
            None,
        )

        es_section_id = getattr(
            exam_subject,
            "section_id",
            None,
        )

        # ----------------------------------------------------
        # If section selected
        # ----------------------------------------------------

        if section_id:

            if es_section_id == section_id:

                priority = 1

            elif (
                es_section_id is None
                and es_class_id == class_id
            ):

                priority = 2

            elif (
                es_section_id is None
                and es_class_id is None
            ):

                priority = 3

            else:
                continue

        # ----------------------------------------------------
        # If class selected
        # ----------------------------------------------------

        elif class_id:

            if es_section_id is not None:
                continue

            if es_class_id == class_id:

                priority = 1

            elif es_class_id is None:

                priority = 2

            else:
                continue

        # ----------------------------------------------------
        # Program / general exam
        # ----------------------------------------------------

        else:

            if (
                es_section_id is not None
                or es_class_id is not None
            ):
                continue

            priority = 1

        existing = subjects_by_subject_id.get(
            subject_id
        )

        if (
            existing is None
            or priority < existing[0]
            or (
                priority == existing[0]
                and exam_subject.id
                < existing[1].id
            )
        ):

            subjects_by_subject_id[
                subject_id
            ] = (
                priority,
                exam_subject,
            )

    # --------------------------------------------------------
    # Final subject list
    # --------------------------------------------------------

    selected_exam_subjects = [
        item[1]
        for item in subjects_by_subject_id.values()
    ]

    selected_exam_subjects.sort(
        key=lambda item: (
            getattr(
                item,
                "display_order",
                0,
            )
            or 0,
            getattr(
                item,
                "id",
                0,
            )
            or 0,
        )
    )

    if not selected_exam_subjects:

        flash(
            "No exam subjects match the selected class or section.",
            "warning",
        )

        return redirect(
            url_for(
                "main.add_exam_result",
                exam_id=exam.id,
            )
        )

    # ========================================================
    # SUBJECT IDS
    # ========================================================

    selected_subject_ids = {
        getattr(
            item,
            "subject_id",
            None,
        )
        for item in selected_exam_subjects
    }

    selected_subject_ids.discard(
        None
    )

    # ========================================================
    # ENROLLMENTS
    #
    # Student scope:
    #
    # institution
    # branch
    # academic year
    # program
    # class
    # section
    # ========================================================

    enrollment_query = (
        StudentEnrollment.query
        .join(
            Student,
            Student.id
            == StudentEnrollment.student_id,
        )
        .filter(
            StudentEnrollment.institution_id
            == exam.institution_id,

            StudentEnrollment.branch_id
            == exam.branch_id,

            StudentEnrollment.academic_year_id
            == exam.academic_year_id,
        )
    )

    if program_id:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.program_id
                == program_id
            )
        )

    if class_id:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.class_id
                == class_id
            )
        )

    if section_id:

        enrollment_query = (
            enrollment_query
            .filter(
                StudentEnrollment.section_id
                == section_id
            )
        )

    # --------------------------------------------------------
    # Active enrollment only
    # --------------------------------------------------------

    enrollment_status_column = getattr(
        StudentEnrollment,
        "status",
        None,
    )

    if enrollment_status_column is not None:

        enrollment_query = (
            enrollment_query
            .filter(
                db.func.lower(
                    enrollment_status_column
                ).in_(
                    [
                        "active",
                        "enrolled",
                        "current",
                    ]
                )
            )
        )

    enrollments = (
        enrollment_query
        .order_by(
            Student.full_name.asc(),
            Student.id.asc(),
        )
        .all()
    )

    if not enrollments:

        flash(
            "No enrolled students were found for this exam scope.",
            "warning",
        )

        return redirect(
            url_for(
                "main.add_exam_result",
                exam_id=exam.id,
            )
        )

    # ========================================================
    # STUDENT IDS
    # ========================================================

    student_ids = [
        enrollment.student_id
        for enrollment in enrollments
        if getattr(
            enrollment,
            "student_id",
            None,
        )
    ]

    # ========================================================
    # MARKS
    #
    # Load all selected ExamSubject marks in one query.
    # ========================================================

    exam_subject_ids = [
        item.id
        for item in selected_exam_subjects
    ]

    marks = (
        Mark.query
        .filter(
            Mark.exam_subject_id.in_(
                exam_subject_ids
            ),
            Mark.student_id.in_(
                student_ids
            ),
        )
        .all()
    )

    marks_map = {}

    for mark in marks:

        key = (
            mark.student_id,
            mark.exam_subject_id,
        )

        marks_map[
            key
        ] = mark

    # ========================================================
    # STUDENT RESULTS
    #
    # IMPORTANT:
    # StudentResult is the source of:
    #
    # total_marks
    # total_possible_marks
    # percentage
    # average
    # grade
    # gpa
    # result_status
    # positions
    # workflow status
    # ========================================================

    student_results = (
        StudentResult.query
        .filter(
            StudentResult.exam_id
            == exam.id,

            StudentResult.student_id.in_(
                student_ids
            ),
        )
        .all()
    )

    results_map = {
        result.student_id: result
        for result in student_results
    }

    # ========================================================
    # SUBJECT MASTER
    # ========================================================

    subject_master = []

    for exam_subject in selected_exam_subjects:

        subject = getattr(
            exam_subject,
            "subject",
            None,
        )

        subject_name = ""

        if subject:

            subject_name = (
                getattr(
                    subject,
                    "name",
                    None,
                )
                or getattr(
                    subject,
                    "subject_name",
                    None,
                )
                or getattr(
                    subject,
                    "code",
                    None,
                )
                or f"Subject {exam_subject.subject_id}"
            )

        else:

            subject_name = (
                f"Subject {exam_subject.subject_id}"
            )

        subject_master.append(
            {
                "exam_subject": exam_subject,
                "subject": subject,
                "subject_id": exam_subject.subject_id,
                "name": normalize_text(
                    subject_name
                ),
            }
        )

    # ========================================================
    # BUILD REPORT ROWS
    # ========================================================

    report_rows = []

    for enrollment in enrollments:

        student = getattr(
            enrollment,
            "student",
            None,
        )

        if not student:
            continue

        student_id = getattr(
            student,
            "id",
            None,
        )

        result = results_map.get(
            student_id
        )

        # ----------------------------------------------------
        # Student information
        # ----------------------------------------------------

        student_name = (
            getattr(
                student,
                "full_name",
                None,
            )
            or getattr(
                student,
                "name",
                None,
            )
            or ""
        )

        admission_no = (
            getattr(
                student,
                "admission_no",
                None,
            )
            or ""
        )

        roll_no = (
            getattr(
                student,
                "roll_no",
                None,
            )
            or ""
        )

        # ----------------------------------------------------
        # Calculate subject details
        # ----------------------------------------------------

        subject_rows = []

        calculated_total_marks = Decimal(
            "0"
        )

        calculated_total_possible = Decimal(
            "0"
        )

        calculated_subject_percentages = []

        completed_subjects = 0
        failed_subjects = 0

        has_missing = False

        for subject_item in subject_master:

            exam_subject = subject_item[
                "exam_subject"
            ]

            subject = subject_item[
                "subject"
            ]

            mark = marks_map.get(
                (
                    student_id,
                    exam_subject.id,
                )
            )

            status = subject_status(
                mark,
                exam_subject,
            )

            percentage = subject_percentage(
                mark,
                exam_subject,
            )

            grade = subject_grade(
                mark,
                exam_subject,
            )

            # ------------------------------------------------
            # Teacher
            # ------------------------------------------------

            teacher = getattr(
                exam_subject,
                "teacher",
                None,
            )

            teacher_name = ""

            if teacher:

                teacher_name = (
                    getattr(
                        teacher,
                        "full_name",
                        None,
                    )
                    or getattr(
                        teacher,
                        "name",
                        None,
                    )
                    or getattr(
                        teacher,
                        "username",
                        None,
                    )
                    or ""
                )

            # ------------------------------------------------
            # Mark
            # ------------------------------------------------

            marks_obtained = None

            if mark:

                marks_obtained = getattr(
                    mark,
                    "marks_obtained",
                    None,
                )

            # ------------------------------------------------
            # Subject calculations
            # ------------------------------------------------

            if status == "RECORDED":

                marks_decimal = to_decimal(
                    marks_obtained
                )

                max_marks = to_decimal(
                    getattr(
                        exam_subject,
                        "max_marks",
                        None,
                    )
                )

                if marks_decimal is not None:

                    calculated_total_marks += (
                        marks_decimal
                    )

                if (
                    max_marks is not None
                    and max_marks > 0
                ):

                    calculated_total_possible += (
                        max_marks
                    )

                completed_subjects += 1

                if (
                    percentage is not None
                    and percentage < Decimal("50")
                ):
                    failed_subjects += 1

                if percentage is not None:

                    calculated_subject_percentages.append(
                        percentage
                    )

            elif status == "ABSENT":

                # Absent counts as zero against the
                # subject maximum.

                max_marks = to_decimal(
                    getattr(
                        exam_subject,
                        "max_marks",
                        None,
                    )
                )

                if (
                    max_marks is not None
                    and max_marks > 0
                ):

                    calculated_total_possible += (
                        max_marks
                    )

                completed_subjects += 1

                failed_subjects += 1

                calculated_subject_percentages.append(
                    Decimal("0")
                )

            elif status == "EXEMPTED":

                # Exempted subject is excluded from
                # denominator and completed count.

                pass

            elif status == "MISSING":

                has_missing = True

            subject_rows.append(
                {
                    "exam_subject": exam_subject,
                    "subject": subject,
                    "mark": mark,
                    "status": status,
                    "percentage": percentage,
                    "grade": grade,
                    "teacher_name": teacher_name,
                    "marks_obtained": marks_obtained,
                }
            )

        # ====================================================
        # OVERALL RESULT VALUES
        # ====================================================

        # ----------------------------------------------------
        # Prefer StudentResult stored values.
        # ----------------------------------------------------

        total_marks = None

        total_possible_marks = None

        percentage = None

        average = None

        if result:

            total_marks = to_decimal(
                getattr(
                    result,
                    "total_marks",
                    None,
                )
            )

            total_possible_marks = to_decimal(
                getattr(
                    result,
                    "total_possible_marks",
                    None,
                )
            )

            percentage = to_decimal(
                getattr(
                    result,
                    "percentage",
                    None,
                )
            )

            average = to_decimal(
                getattr(
                    result,
                    "average",
                    None,
                )
            )

        # ----------------------------------------------------
        # Fallback totals
        # ----------------------------------------------------

        if total_marks is None:

            total_marks = (
                calculated_total_marks
            )

        if total_possible_marks is None:

            total_possible_marks = (
                calculated_total_possible
            )

        # ----------------------------------------------------
        # Fallback percentage
        #
        # Do NOT convert missing marks to zero.
        # If there is missing data, result is incomplete.
        # ----------------------------------------------------

        if percentage is None:

            if (
                not has_missing
                and total_possible_marks
                and total_possible_marks > 0
            ):

                percentage = (
                    total_marks
                    / total_possible_marks
                ) * Decimal("100")

            else:

                percentage = None

        # ----------------------------------------------------
        # Fallback average
        #
        # Average is average of subject percentages.
        # ----------------------------------------------------

        if average is None:

            if calculated_subject_percentages:

                average = (
                    sum(
                        calculated_subject_percentages
                    )
                    / Decimal(
                        len(
                            calculated_subject_percentages
                        )
                    )
                )

            else:

                average = None

        # ====================================================
        # RESULT STATUS
        # ====================================================

        result_status = get_result_status(
            result,
            percentage,
            has_missing,
        )

        # ====================================================
        # GRADE
        # ====================================================

        stored_grade = ""

        if result:

            stored_grade = normalize_text(
                getattr(
                    result,
                    "grade",
                    None,
                )
            ).upper()

        valid_grades = set(
            GRADE_POINTS.keys()
        )

        if (
            stored_grade
            and stored_grade in valid_grades
        ):

            overall_grade = stored_grade

        elif (
            percentage is not None
            and result_status != "INCOMPLETE"
        ):

            overall_grade = calculate_grade(
                percentage
            )

        else:

            overall_grade = ""

        # ====================================================
        # GPA
        # ====================================================

        stored_gpa = None

        if result:

            stored_gpa = to_decimal(
                getattr(
                    result,
                    "gpa",
                    None,
                )
            )

        if stored_gpa is not None:

            gpa = stored_gpa

        else:

            gpa = calculate_gpa_from_subjects(
                subject_rows
            )

        # ====================================================
        # DECISION
        # ====================================================

        decision = academic_decision(
            result_status
        )

        # ====================================================
        # WORKFLOW STATUS
        # ====================================================

        workflow = workflow_status(
            result
        )

        # ====================================================
        # SUBJECT COUNTS
        # ====================================================

        stored_subject_total = None

        stored_subject_completed = None

        stored_subject_failed = None

        if result:

            stored_subject_total = getattr(
                result,
                "subjects_total",
                None,
            )

            stored_subject_completed = getattr(
                result,
                "subjects_completed",
                None,
            )

            stored_subject_failed = getattr(
                result,
                "subjects_failed",
                None,
            )

        subjects_total = (
            stored_subject_total
            if stored_subject_total is not None
            else len(
                selected_exam_subjects
            )
        )

        subjects_completed = (
            stored_subject_completed
            if stored_subject_completed is not None
            else completed_subjects
        )

        subjects_failed = (
            stored_subject_failed
            if stored_subject_failed is not None
            else failed_subjects
        )

        # ====================================================
        # POSITION FROM STUDENT RESULT
        #
        # NO Ranking table.
        # ====================================================

        stored_position = get_stored_position(
            result=result,
            section_selected=bool(
                section_id
            ),
            class_selected=bool(
                class_id
            ),
            program_selected=bool(
                program_id
            ),
            exam=exam,
        )

        report_rows.append(
            {
                "student": student,
                "student_id": student_id,
                "student_name": normalize_text(
                    student_name
                ),
                "admission_no": normalize_text(
                    admission_no
                ),
                "roll_no": normalize_text(
                    roll_no
                ),
                "enrollment": enrollment,
                "result": result,
                "subject_rows": subject_rows,
                "total_marks": total_marks,
                "total_possible_marks": total_possible_marks,
                "percentage": percentage,
                "average": average,
                "overall_grade": overall_grade,
                "gpa": gpa,
                "result_status": result_status,
                "decision": decision,
                "workflow": workflow,
                "subjects_total": subjects_total,
                "subjects_completed": subjects_completed,
                "subjects_failed": subjects_failed,
                "stored_position": stored_position,
            }
        )

    # ========================================================
    # FALLBACK RANK
    #
    # If StudentResult position is NULL, calculate it.
    #
    # Still NO Ranking model/table.
    # ========================================================

    fallback_positions = (
        calculate_fallback_positions(
            report_rows
        )
    )

    for index, row in enumerate(
        report_rows
    ):

        if row.get(
            "stored_position"
        ) is not None:

            row["position"] = row[
                "stored_position"
            ]

        else:

            row["position"] = (
                fallback_positions.get(
                    index
                )
            )

    # ========================================================
    # SITE SETTINGS
    # ========================================================

    site_settings = None

    try:

        site_settings = (
            SiteSettings.query
            .first()
        )

    except Exception:

        site_settings = None

    # ========================================================
    # INSTITUTION
    # ========================================================

    institution = getattr(
        exam,
        "institution",
        None,
    )

    institution_name = ""

    if institution:

        institution_name = (
            getattr(
                institution,
                "institution_name",
                None,
            )
            or getattr(
                institution,
                "name",
                None,
            )
            or ""
        )

    if not institution_name:

        institution_name = (
            getattr(
                site_settings,
                "institution_name",
                None,
            )
            or "SOOYAAL EDUCATIONAL INSTITUTE"
        )

    # ========================================================
    # BRANCH
    # ========================================================

    branch = getattr(
        exam,
        "branch",
        None,
    )

    branch_name = ""

    if branch:

        branch_name = (
            getattr(
                branch,
                "name",
                None,
            )
            or getattr(
                branch,
                "branch_name",
                None,
            )
            or ""
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    program = getattr(
        exam,
        "program",
        None,
    )

    program_name = ""

    if program:

        program_name = (
            getattr(
                program,
                "name",
                None,
            )
            or getattr(
                program,
                "short_name",
                None,
            )
            or getattr(
                program,
                "code",
                None,
            )
            or ""
        )

    # ========================================================
    # CLASS
    # ========================================================

    class_name = ""

    if selected_class:

        class_name = (
            getattr(
                selected_class,
                "name",
                None,
            )
            or getattr(
                selected_class,
                "class_name",
                None,
            )
            or getattr(
                selected_class,
                "code",
                None,
            )
            or ""
        )

    # ========================================================
    # SECTION
    # ========================================================

    section_name = ""

    if selected_section:

        section_name = (
            getattr(
                selected_section,
                "name",
                None,
            )
            or getattr(
                selected_section,
                "section_name",
                None,
            )
            or getattr(
                selected_section,
                "code",
                None,
            )
            or ""
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    academic_year = getattr(
        exam,
        "academic_year",
        None,
    )

    academic_year_name = ""

    if academic_year:

        academic_year_name = (
            getattr(
                academic_year,
                "name",
                None,
            )
            or getattr(
                academic_year,
                "year",
                None,
            )
            or getattr(
                academic_year,
                "code",
                None,
            )
            or ""
        )

    # ========================================================
    # TERM
    # ========================================================

    term = getattr(
        exam,
        "term",
        None,
    )

    term_name = ""

    if term:

        term_name = (
            getattr(
                term,
                "name",
                None,
            )
            or getattr(
                term,
                "code",
                None,
            )
            or ""
        )

    # ========================================================
    # EXAM DETAILS
    # ========================================================

    exam_code = normalize_text(
        getattr(
            exam,
            "code",
            None,
        )
    )

    exam_title = (
        normalize_text(
            getattr(
                exam,
                "title",
                None,
            )
        )
        or normalize_text(
            getattr(
                exam,
                "name",
                None,
            )
        )
        or "Exam Results"
    )

    exam_type = normalize_text(
        getattr(
            exam,
            "exam_type",
            None,
        )
    )

    exam_status = normalize_text(
        getattr(
            exam,
            "status",
            None,
        )
    )

    # ========================================================
    # CSV OUTPUT
    # ========================================================

    output = io.StringIO(
        newline=""
    )

    writer = csv.writer(
        output
    )

    # ========================================================
    # HEADER
    # ========================================================

    headers = [
        "Institution",
        "Branch",
        "Program",
        "Class",
        "Section",

        "Academic Year",
        "Term",

        "Exam Code",
        "Exam",
        "Exam Type",
        "Exam Status",

        "Admission No",
        "Roll No",
        "Student Name",

        "Subjects Total",
        "Subjects Completed",
        "Subjects Failed",

        "Total Marks",
        "Total Possible Marks",
        "Percentage",
        "Average",

        "Overall Grade",
        "GPA",

        "Result Status",
        "Decision",

        "Position",
        "Workflow Status",
    ]

    # ========================================================
    # DYNAMIC SUBJECT COLUMNS
    #
    # Each subject gets:
    #
    # Max
    # Pass
    # Mark
    # Grade
    # Status
    # Workflow
    # Teacher
    # Remark
    # ========================================================

    for subject_item in subject_master:

        subject_name = subject_item[
            "name"
        ]

        headers.extend(
            [
                f"{subject_name} - Max",
                f"{subject_name} - Pass",
                f"{subject_name} - Mark",
                f"{subject_name} - Grade",
                f"{subject_name} - Status",
                f"{subject_name} - Workflow",
                f"{subject_name} - Teacher",
                f"{subject_name} - Remark",
            ]
        )

    writer.writerow(
        headers
    )

    # ========================================================
    # DATA ROWS
    # ========================================================

    for row in report_rows:

        result = row.get(
            "result"
        )

        csv_row = [
            institution_name,
            branch_name,
            program_name,
            class_name,
            section_name,

            academic_year_name,
            term_name,

            exam_code,
            exam_title,
            exam_type,
            exam_status,

            row.get(
                "admission_no",
                "",
            ),

            row.get(
                "roll_no",
                "",
            ),

            row.get(
                "student_name",
                "",
            ),

            row.get(
                "subjects_total",
                "",
            ),

            row.get(
                "subjects_completed",
                "",
            ),

            row.get(
                "subjects_failed",
                "",
            ),

            decimal_text(
                row.get(
                    "total_marks"
                )
            ),

            decimal_text(
                row.get(
                    "total_possible_marks"
                )
            ),

            decimal_text(
                row.get(
                    "percentage"
                )
            ),

            decimal_text(
                row.get(
                    "average"
                )
            ),

            row.get(
                "overall_grade",
                "",
            ),

            decimal_text(
                row.get(
                    "gpa"
                )
            ),

            row.get(
                "result_status",
                "",
            ),

            row.get(
                "decision",
                "",
            ),

            row.get(
                "position",
                "",
            ),

            row.get(
                "workflow",
                "",
            ),
        ]

        # ----------------------------------------------------
        # Map subject rows by exam_subject_id
        # ----------------------------------------------------

        student_subject_map = {}

        for subject_row in row.get(
            "subject_rows",
            [],
        ):

            exam_subject = subject_row.get(
                "exam_subject"
            )

            if not exam_subject:
                continue

            student_subject_map[
                exam_subject.id
            ] = subject_row

        # ----------------------------------------------------
        # Subject columns
        # ----------------------------------------------------

        for subject_item in subject_master:

            exam_subject = subject_item[
                "exam_subject"
            ]

            subject_row = (
                student_subject_map.get(
                    exam_subject.id
                )
            )

            max_marks = getattr(
                exam_subject,
                "max_marks",
                None,
            )

            pass_marks = getattr(
                exam_subject,
                "pass_marks",
                None,
            )

            if subject_row is None:

                csv_row.extend(
                    [
                        decimal_text(
                            max_marks
                        ),

                        decimal_text(
                            pass_marks
                        ),

                        "",
                        "",
                        "MISSING",
                        "",
                        "",
                        "",
                    ]
                )

                continue

            mark = subject_row.get(
                "mark"
            )

            status = subject_row.get(
                "status",
                "",
            )

            grade = subject_row.get(
                "grade",
                "",
            )

            teacher_name = subject_row.get(
                "teacher_name",
                "",
            )

            # ------------------------------------------------
            # Mark workflow
            # ------------------------------------------------

            mark_workflow = ""

            if mark:

                mark_workflow = normalize_text(
                    getattr(
                        mark,
                        "status",
                        None,
                    )
                ).upper()

            # ------------------------------------------------
            # Remark
            # ------------------------------------------------

            remark = ""

            if mark:

                remark = normalize_text(
                    getattr(
                        mark,
                        "remarks",
                        None,
                    )
                )

            # ------------------------------------------------
            # Display mark
            # ------------------------------------------------

            if status == "ABSENT":

                display_mark = "ABSENT"

            elif status == "EXEMPTED":

                display_mark = "EXEMPTED"

            elif status == "MISSING":

                display_mark = ""

            else:

                display_mark = decimal_text(
                    subject_row.get(
                        "marks_obtained"
                    )
                )

            csv_row.extend(
                [
                    decimal_text(
                        max_marks
                    ),

                    decimal_text(
                        pass_marks
                    ),

                    display_mark,

                    grade,

                    status,

                    mark_workflow,

                    teacher_name,

                    remark,
                ]
            )

        writer.writerow(
            csv_row
        )

    # ========================================================
    # SUMMARY ROW
    # ========================================================

    writer.writerow([])

    writer.writerow(
        [
            "SUMMARY"
        ]
    )

    total_students = len(
        report_rows
    )

    passed_students = sum(
        1
        for row in report_rows
        if row.get(
            "result_status"
        ) == "PASS"
    )

    failed_students = sum(
        1
        for row in report_rows
        if row.get(
            "result_status"
        ) == "FAIL"
    )

    incomplete_students = sum(
        1
        for row in report_rows
        if row.get(
            "result_status"
        ) == "INCOMPLETE"
    )

    writer.writerow(
        [
            "Total Students",
            total_students,
        ]
    )

    writer.writerow(
        [
            "PASS",
            passed_students,
        ]
    )

    writer.writerow(
        [
            "FAIL",
            failed_students,
        ]
    )

    writer.writerow(
        [
            "INCOMPLETE",
            incomplete_students,
        ]
    )

    # ========================================================
    # RESULT DISTRIBUTION
    # ========================================================

    grade_counts = {
        "A+": 0,
        "A": 0,
        "A-": 0,
        "B+": 0,
        "B": 0,
        "B-": 0,
        "C+": 0,
        "C": 0,
        "C-": 0,
        "D": 0,
        "E": 0,
        "F": 0,
    }

    for row in report_rows:

        grade = normalize_text(
            row.get(
                "overall_grade"
            )
        ).upper()

        if grade in grade_counts:

            grade_counts[
                grade
            ] += 1

    writer.writerow([])

    writer.writerow(
        [
            "GRADE DISTRIBUTION"
        ]
    )

    for grade in [
        "A+",
        "A",
        "A-",
        "B+",
        "B",
        "B-",
        "C+",
        "C",
        "C-",
        "D",
        "E",
        "F",
    ]:

        writer.writerow(
            [
                grade,
                grade_counts[
                    grade
                ],
            ]
        )

    # ========================================================
    # PASS RATE
    # ========================================================

    pass_rate = None

    if total_students > 0:

        pass_rate = (
            Decimal(
                passed_students
            )
            / Decimal(
                total_students
            )
        ) * Decimal("100")

    writer.writerow([])

    writer.writerow(
        [
            "Pass Rate",
            (
                decimal_text(
                    pass_rate
                )
                + "%"
                if pass_rate is not None
                else ""
            ),
        ]
    )

    # ========================================================
    # UTF-8 BOM
    #
    # Makes Somali/Arabic/Excel display correctly.
    # ========================================================

    csv_content = (
        "\ufeff"
        + output.getvalue()
    )

    # ========================================================
    # FILENAME
    # ========================================================

    filename_parts = [
        "exam-results",
    ]

    if exam_code:

        filename_parts.append(
            safe_filename(
                exam_code
            )
        )

    elif exam_title:

        filename_parts.append(
            safe_filename(
                exam_title
            )
        )

    if program_name:

        filename_parts.append(
            safe_filename(
                program_name
            )
        )

    if class_name:

        filename_parts.append(
            safe_filename(
                class_name
            )
        )

    if section_name:

        filename_parts.append(
            safe_filename(
                section_name
            )
        )

    filename = (
        "_".join(
            filename_parts
        )
        + ".csv"
    )

    # ========================================================
    # RESPONSE
    # ========================================================

    response = Response(
        csv_content,
        mimetype="text/csv; charset=utf-8",
    )

    response.headers[
        "Content-Disposition"
    ] = (
        f'attachment; filename="{filename}"'
    )

    response.headers[
        "Cache-Control"
    ] = "no-store"

    return response




















#-------------------------------------------
#---- Route: Ending |  Logout Sections -----
#-------------------------------------------
@bp.route("/logout")
def logout():

    if current_user.is_authenticated:

        user = User.query.get(current_user.id)

        if user:
            user.auth_status = "logout"
            user.session_token = None
            user.last_seen = datetime.utcnow()

            try:
                db.session.commit()
            except Exception:
                db.session.rollback()
                current_app.logger.exception("Logout update error")

        logout_user()

        flash(
            "You have been logged out successfully.",
            "success"
        )

    else:

        flash(
            "You are already logged out.",
            "info"
        )

    return redirect(
        url_for("main.login")
    )


# ---------------------------------------
# ---- Route: Teacher Logout ------------
# ---------------------------------------

@bp.route("/teacher/logout")
def teacher_logout():

    # Get current teacher from session
    teacher_id = session.get("teacher_id")

    if teacher_id:

        teacher = Teacher.query.get(teacher_id)

        if teacher:
            teacher.last_active = datetime.utcnow()

            try:
                db.session.commit()

            except Exception:
                db.session.rollback()

                current_app.logger.exception(
                    "Teacher logout update error"
                )

        # IMPORTANT:
        # Remove ONLY teacher session data.
        # Do NOT use session.clear()
        # because Admin/User Flask-Login session
        # must remain untouched.

        session.pop("teacher_id", None)
        session.pop("teacher_role", None)
        session.pop("teacher_institution_id", None)
        session.pop("teacher_branch_id", None)

        flash(
            "You have been logged out successfully.",
            "success"
        )

    else:

        flash(
            "You are already logged out.",
            "info"
        )

    return redirect(
        url_for("main.teacher_login")
    )

    



